window.Q=window.Q||{};Q["m37_S5"]=[{"i":"S5-1-1-학개론-01","r":"S5","g":1,"c":1,"n":1,"s":"학개론","q":"다중주택의 요건이 아닌 것은? (단, 건축법령상 단서 조항은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["1개 동의 주택으로 쓰이는 바닥면적(부설 주차장 면적은 제외한다)의 합계가 660제곱미터 이하이고 주택으로 쓰는 층수(지하층은 제외한다)가 3개 층 이하일 것","독립된 주거의 형태를 갖추지 않은 것(각 실별로 욕실은 설치할 수 있으나, 취사시설은 설치하지 않은 것을 말한다)","학교 또는 공장 등의 학생 또는 종업원 등을 위하여 쓰는 것으로서 1개 동의 공동취사시설 이용 세대 수가 전체의 50퍼센트 이상인 것","적정한 주거환경을 조성하기 위하여 건축조례로 정하는 실별 최소 면적, 창문의 설치 및 크기 등의 기준에 적합할 것","학생 또는 직장인 등 여러 사람이 장기간 거주할 수 있는 구조로 되어 있는 것"],"a":[3],"L":"학1-2","o":"기출","x":{"한줄":"공동취사시설 이용 세대 수가 전체의 50퍼센트 이상인 것은 다중주택이 아니라 공동주택 중 일반기숙사의 요건이다.","근거":[{"법령":"건축법 시행령","조문":"제3조의5 [별표 1] 제1호나목","원문":"나. 다중주택: 다음의 요건을 모두 갖춘 주택을 말한다. 1) 학생 또는 직장인 등 여러 사람이 장기간 거주할 수 있는 구조로 되어 있는 것 2) 독립된 주거의 형태를 갖추지 않은 것(각 실별로 욕실은 설치할 수 있으나, 취사시설은 설치하지 않은 것을 말한다) 3) 1개 동의 주택으로 쓰이는 바닥면적(부설 주차장 면적은 제외한다. 이하 같다)의 합계가 660제곱미터 이하이고 주택으로 쓰는 층수(지하층은 제외한다)가 3개 층 이하일 것. 4) 적정한 주거환경을 조성하기 위하여 건축조례로 정하는 실별 최소 면적, 창문의 설치 및 크기 등의 기준에 적합할 것"},{"법령":"건축법 시행령","조문":"제3조의5 [별표 1] 제2호라목1)","원문":"1) 일반기숙사: 학교 또는 공장 등의 학생 또는 종업원 등을 위하여 사용하는 것으로서 해당 기숙사의 공동취사시설 이용 세대 수가 전체 세대 수(건축물의 일부를 기숙사로 사용하는 경우에는 기숙사로 사용하는 세대 수로 한다. 이하 같다)의 50퍼센트 이상인 것"}],"선지":[{"번호":1,"판정":"옳음","설명":"다중주택의 규모 요건이다. 1개 동 바닥면적 합계 660제곱미터 이하, 주택 층수 3개 층 이하(지하층 제외)다(건축법 시행령 별표 1 제1호나목3))."},{"번호":2,"판정":"옳음","설명":"독립된 주거의 형태를 갖추지 않아야 한다. 실별 욕실은 설치할 수 있고 취사시설은 설치할 수 없다(같은 목 2))."},{"번호":3,"판정":"틀림","설명":"공동취사시설 이용 세대 수 50퍼센트 이상은 일반기숙사의 요건이다(별표 1 제2호라목1)). 다중주택은 취사시설을 두지 않는다."},{"번호":4,"판정":"옳음","설명":"건축조례로 정하는 실별 최소 면적, 창문의 설치 및 크기 등의 기준에 적합해야 한다(같은 목 4))."},{"번호":5,"판정":"옳음","설명":"학생·직장인 등 여러 사람이 장기간 거주할 수 있는 구조여야 한다(같은 목 1))."}],"개념":[{"종류":"표","제목":"단독주택·공동주택의 종류별 요건","머리":["구분","종류","층수","바닥면적(1개 동)","그 밖의 요건"],"행":[["단독주택","다중주택","3개 층 이하","660제곱미터 이하","독립된 주거 형태 불가, 취사시설 불가"],["단독주택","다가구주택","3개 층 이하","660제곱미터 이하","19세대 이하"],["공동주택","아파트","5개 층 이상","제한 없음","-"],["공동주택","연립주택","4개 층 이하","660제곱미터 초과","-"],["공동주택","다세대주택","4개 층 이하","660제곱미터 이하","-"],["공동주택","기숙사(일반기숙사)","-","-","학교·공장 등의 학생·종업원용, 공동취사시설 이용 세대 수가 전체의 50퍼센트 이상"]]}],"함정":"공동취사시설 50퍼센트 이상 문구는 기숙사 정의에 있는 문장이다. 다중주택 선지에 끼워 넣으면 읽다가 지나치기 쉽다. 다중주택과 다가구주택은 층수·바닥면적 숫자(3개 층, 660제곱미터)가 같아 서로 바꿔 쓴 문장도 자주 나온다. 다가구는 19세대 이하, 다중주택은 독립 주거 형태 불가가 갈림 요소다."}},{"i":"S5-1-1-학개론-02","r":"S5","g":1,"c":1,"n":2,"s":"학개론","q":"부동산을 다양한 기준에 따라 분류하여 설명한 것으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["공간정보의 구축 및 관리 등에 관한 법령상 물이 고이거나 상시적으로 물을 저장하고 있는 댐·저수지·호수·연못 등의 토지의 지목은 구거이다.","택지지역, 농지지역, 임지지역 상호 간에 다른 지역으로 전환되고 있는 지역의 토지를 후보지라고 한다.","건축법령상 주택으로 쓰는 층수가 4개 층 이상인 주택은 아파트이다.","주택법령상 준주택은 도시지역에 건설하는 300세대 미만의 국민주택규모에 해당하는 주택을 말한다.","국토의 계획 및 이용에 관한 법령상 문화재·전통사찰 등 역사적·문화적으로 보존가치가 큰 시설 및 지역을 보호하기 위하여 필요한 지구는 중요시설물보호지구로 지정한다."],"a":[2],"L":"학1-2","o":"변형","x":{"한줄":"대분류인 택지·농지·임지지역 상호 간에 전환 중인 토지가 후보지이고, 같은 대분류 안에서 소분류끼리 전환 중인 토지는 이행지다.","근거":[{"이론":"후보지와 이행지","내용":"후보지는 택지지역·농지지역·임지지역 상호 간에 다른 지역으로 전환되고 있는 지역의 토지다. 이행지는 같은 대분류 안에서 소분류 간(택지 안의 주거지역에서 상업지역으로 등) 이행 중인 토지다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제19호","원문":"19. 유지(溜池) 물이 고이거나 상시적으로 물을 저장하고 있는 댐ㆍ저수지ㆍ소류지(沼溜地)ㆍ호수ㆍ연못 등의 토지와 연ㆍ왕골 등이 자생하는 배수가 잘 되지 아니하는 토지"},{"법령":"주택법","조문":"제2조제4호","원문":"4. \"준주택\"이란 주택 외의 건축물과 그 부속토지로서 주거시설로 이용가능한 시설 등을 말하며, 그 범위와 종류는 대통령령으로 정한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제31조제2항제5호","원문":"5. 보호지구 가. 역사문화환경보호지구 : 국가유산ㆍ전통사찰 등 역사ㆍ문화적으로 보존가치가 큰 시설 및 지역의 보호와 보존을 위하여 필요한 지구 나. 중요시설물보호지구 : 중요시설물(제1항에 따른 시설물을 말한다. 이하 같다)의 보호와 기능의 유지 및 증진 등을 위하여 필요한 지구"}],"선지":[{"번호":1,"판정":"틀림","설명":"댐·저수지·호수·연못 등의 토지는 유지(溜池)다. 구거는 용수·배수를 위한 인공 수로·둑 및 그 부속시설물의 부지 등이다(공간정보법 시행령 제58조제18호·제19호)."},{"번호":2,"판정":"옳음","설명":"대분류 간 전환 중인 토지가 후보지다. 대분류 안에서 소분류끼리 전환 중이면 이행지다."},{"번호":3,"판정":"틀림","설명":"아파트는 주택으로 쓰는 층수가 5개 층 이상인 주택이다(건축법 시행령 별표 1 제2호가목). 4개 층 이하는 연립주택·다세대주택이다."},{"번호":4,"판정":"틀림","설명":"300세대 미만의 국민주택규모 주택은 도시형 생활주택이다(주택법 제2조제20호). 준주택은 주택 외의 건축물과 그 부속토지로서 주거시설로 이용 가능한 시설이다(같은 조 제4호)."},{"번호":5,"판정":"틀림","설명":"문화재·전통사찰 등 보존가치가 큰 시설 및 지역의 보호는 역사문화환경보호지구다(국토계획법 시행령 제31조제2항제5호가목). 중요시설물보호지구는 항만·공항·공용시설·교정시설·군사시설 등의 보호와 기능 유지를 위한 지구다."}],"개념":[{"종류":"비교","제목":"후보지와 이행지","왼쪽":{"이름":"후보지","항목":["대분류 간 전환 중인 토지","택지지역↔농지지역↔임지지역 상호 전환","예: 농지지역에서 택지지역으로 바뀌는 토지"]},"오른쪽":{"이름":"이행지","항목":["같은 대분류 안에서 소분류 간 이행 중인 토지","예: 택지지역 안에서 주거지역에서 상업지역으로, 공업지역에서 상업지역으로","택지·농지·임지 대분류는 그대로"]}},{"종류":"표","제목":"주택법령상 주택·준주택·도시형 생활주택","머리":["구분","정의 또는 범위","근거"],"행":[["주택","세대 구성원이 장기간 독립된 주거생활을 할 수 있는 구조의 건축물 전부 또는 일부 및 부속토지","주택법 제2조제1호"],["준주택","주택 외의 건축물과 그 부속토지로서 주거시설로 이용 가능한 시설(기숙사·다중생활시설·노인복지주택·오피스텔)","주택법 제2조제4호"],["도시형 생활주택","300세대 미만의 국민주택규모 주택으로서 대통령령으로 정하는 주택","주택법 제2조제20호"],["도시형 생활주택의 유형","아파트형 주택, 단지형 연립주택, 단지형 다세대주택(도시지역에 건설)","주택법 시행령 제10조제1항"],["국민주택규모","주거전용면적 1호(세대)당 85제곱미터 이하(수도권 외 도시지역 아닌 읍·면은 100제곱미터 이하)","주택법 제2조제6호"]]}],"함정":"준주택과 도시형 생활주택의 정의를 맞바꾼 문장이 가장 많이 걸린다. 구거와 유지(溜池)도 서로 바꿔 쓴다. 이행지와 후보지는 대분류 간이면 후보지, 소분류 간이면 이행지로 가른다.","개정":"2017.12.29 개정으로 국토계획법 시행령 제31조제2항의 보존지구·시설보호지구(제2호·제3호)가 삭제되고 보호지구(역사문화환경보호지구·중요시설물보호지구·생태계보호지구)로 통합되었다. 공용시설은 중요시설물보호지구의 보호 대상 시설물에 포함된다(제31조제1항·제2항제5호)."}},{"i":"S5-1-1-학개론-03","r":"S5","g":1,"c":1,"n":3,"s":"학개론","q":"부동산의 특성에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지는 물리적 위치가 고정되어 있어 부동산시장이 국지화 된다.","토지는 생산요소와 자본의 성격을 가지고 있지만, 소비재의 성격은 가지고 있지 않다.","토지는 개별성으로 인해 용도적 관점에서도 공급을 늘릴 수 없다.","토지의 부증성으로 인해 토지공급은 특정 용도의 토지에 대해서도 장ㆍ단기적으로 완전비탄력적이다.","토지는 영속성으로 인해 물리적ㆍ경제적인 측면에서 감가상각을 하게 한다."],"a":[1],"L":"학1-3","o":"기출","x":{"한줄":"부동성 때문에 시장이 지역별로 나뉘어 국지화되고, 지역마다 수요·공급과 가격이 따로 형성된다.","근거":[{"이론":"토지의 자연적 특성","내용":"부동성(위치 고정)은 시장의 국지화·지역성, 외부효과, 지역분석의 근거다. 영속성은 소모되지 않아 감가상각을 배제하고, 부증성은 물리적 공급 증가를 막는다. 개별성은 일물일가 법칙의 배제, 비교 곤란과 관련된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"부동성으로 부동산시장은 지역별로 수요·공급이 따로 형성되는 국지적 시장이 된다."},{"번호":2,"판정":"틀림","설명":"토지는 생산요소와 자본의 성격에 더해 소비재(주거 등 소비 목적)의 성격도 가진다."},{"번호":3,"판정":"틀림","설명":"물리적 공급은 늘릴 수 없어도 용도적 관점(용도 전환·용도변경)에서는 공급을 늘릴 수 있다. 용도적 공급 변화는 개별성이 아니라 용도의 다양성과 관련된다."},{"번호":4,"판정":"틀림","설명":"부증성은 물리적 공급이 고정된다는 뜻이다. 특정 용도의 토지는 용도 전환으로 공급이 변하므로 장·단기 모두 완전비탄력적이라고 할 수 없다."},{"번호":5,"판정":"틀림","설명":"영속성(비소모성)이 있어 토지는 물리적·경제적으로 감가상각을 하지 않는다. 감가상각 대상은 건물이다."}],"개념":[{"종류":"표","제목":"토지의 자연적 특성과 파생 현상","머리":["특성","내용","파생 현상"],"행":[["부동성","위치가 고정","지역성·국지적 시장, 외부효과, 지역분석, 임장활동, 부동산활동의 장소적 한계"],["영속성(비소모성)","사용·시간으로 소모되지 않음","감가상각 배제, 가치보존·소유 선호, 장기 투자"],["부증성(비생산성)","물리적 양을 늘릴 수 없음","물리적 공급의 완전비탄력, 지대·지가 발생, 최유효이용, 집약적 이용"],["개별성(비동질성)","같은 토지가 없음","일물일가 법칙 배제, 상품 비교 곤란, 개별분석, 거래 정보의 비공개성"]]},{"종류":"비교","제목":"토지 공급: 물리적 공급과 경제적 공급","왼쪽":{"이름":"물리적(자연적) 공급","항목":["토지 면적 자체","부증성 때문에 장·단기 완전비탄력","간척 등이 있어도 일반적으로 고정으로 봄"]},"오른쪽":{"이름":"경제적(용도적) 공급","항목":["특정 용도의 토지 공급","용도 전환·용도변경으로 증감","가격이 오르면 늘어나므로 비탄력적이어도 완전비탄력은 아님"]}}],"함정":"부증성을 곧바로 모든 공급의 완전비탄력으로 확장한 선지에 속는다. 완전비탄력은 물리적 공급에만 해당한다. 영속성과 감가상각을 이어 붙인 문장도 자주 나온다. 토지는 감가상각하지 않고 건물은 한다."}},{"i":"S5-1-1-학개론-04","r":"S5","g":1,"c":1,"n":4,"s":"학개론","q":"A지역 단독주택 시장의 균형가격과 균형거래량의 변화에 관한 설명으로 옳은 것은? (단, 수요곡선은 우하향하고 공급곡선은 우상향하며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["수요가 불변이고 공급이 감소하는 경우, 균형가격은 하락하고 균형거래량은 감소한다.","공급이 불변이고 수요가 증가하는 경우, 균형가격은 상승하고 균형거래량은 감소한다.","수요와 공급이 동시에 증가하고 공급의 증가폭이 수요의 증가폭보다 더 큰 경우, 균형가격은 상승하고 균형거래량은 증가한다.","수요와 공급이 동시에 감소하고 수요의 감소폭이 공급의 감소폭보다 더 큰 경우, 균형가격은 하락하고 균형거래량은 감소한다.","수요는 증가하고 공급이 감소하는데 수요의 증가폭이 공급의 감소폭보다 더 큰 경우, 균형가격은 상승하고 균형거래량은 감소한다."],"a":[4],"L":"학2-1","o":"기출","x":{"한줄":"수요와 공급이 함께 줄면 균형거래량은 확실히 감소하고, 가격은 수요 감소폭이 더 클 때 하락한다.","근거":[{"이론":"수요·공급 변화와 균형","내용":"수요 증가는 가격과 거래량을 올리고, 공급 증가는 가격을 내리고 거래량을 올린다. 둘이 같은 방향으로 함께 움직이면 거래량 방향이 확정되고 가격은 변화폭으로 정해진다. 반대 방향으로 움직이면 가격 방향이 확정되고 거래량은 변화폭으로 정해진다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수요 불변·공급 감소이면 공급곡선이 왼쪽으로 이동해 균형가격은 상승하고 균형거래량은 감소한다."},{"번호":2,"판정":"틀림","설명":"공급 불변·수요 증가이면 균형가격은 상승하고 균형거래량도 증가한다."},{"번호":3,"판정":"틀림","설명":"수요·공급이 동시에 증가할 때 공급 증가폭이 더 크면 균형가격은 하락하고 균형거래량은 증가한다."},{"번호":4,"판정":"옳음","설명":"동시 감소이므로 거래량은 감소한다. 수요 감소폭이 더 크면 가격은 하락한다."},{"번호":5,"판정":"틀림","설명":"수요 증가·공급 감소이면 가격은 상승한다. 수요 증가폭이 더 크면 거래량은 증가하고, 공급 감소폭이 더 크면 거래량은 감소한다."}],"개념":[{"종류":"표","제목":"수요·공급 변화에 따른 균형 변화","머리":["수요","공급","균형가격","균형거래량"],"행":[["증가","불변","상승","증가"],["감소","불변","하락","감소"],["불변","증가","하락","증가"],["불변","감소","상승","감소"],["증가","증가","증가폭 비교(수요폭이 크면 상승, 공급폭이 크면 하락)","증가"],["감소","감소","감소폭 비교(수요폭이 크면 하락, 공급폭이 크면 상승)","감소"],["증가","감소","상승","증가폭 비교(수요폭이 크면 증가, 공급폭이 크면 감소)"],["감소","증가","하락","변화폭 비교(수요폭이 크면 감소, 공급폭이 크면 증가)"]]}],"함정":"수요·공급이 같은 방향으로 움직이면 거래량이, 반대 방향이면 가격이 확정된다. 확정되지 않는 변수만 변화폭으로 가른다. 3번은 동시 증가에서 가격이 상승한다고 확정해 놓았고, 5번은 반대 방향 이동에서 거래량을 감소로 확정해 놓았다."}},{"i":"S5-1-1-학개론-05","r":"S5","g":1,"c":1,"n":5,"s":"학개론","q":"부동산의 수요 및 공급에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["수요곡선이 변하지 않을 때, 세금부과에 의한 경제적 순손실은 공급이 탄력적일수록 커진다.","공급이 완전비탄력적일 때 수요가 증가하면 균형가격은 상승하지만 균형거래량은 변하지 않는다.","건축자재 가격이 상승하면 주택의 공급곡선은 왼쪽(위쪽)으로 이동한다.","수요가 감소하고 공급이 증가하는 경우, 수요와 공급의 변화폭에 관계없이 균형거래량은 감소한다.","대체재의 가격이 상승하면 해당 부동산의 수요곡선은 오른쪽으로 이동한다."],"a":[4],"L":"학2-1","o":"변형","x":{"한줄":"수요 감소와 공급 증가가 겹치면 가격은 하락이 확정되지만 거래량은 변화폭에 따라 증가·감소·불변이 모두 가능하다.","근거":[{"이론":"수요·공급의 변화와 조세","내용":"수요곡선이 변하지 않을 때 조세의 경제적 순손실은 공급이 탄력적일수록, 수요가 탄력적일수록 크다. 공급곡선은 생산요소 가격 상승 시 왼쪽으로 이동한다. 대체재 가격 상승은 수요를 증가시킨다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공급이 탄력적일수록 세금으로 줄어드는 거래량이 커져 순손실이 커진다. 공급이 완전비탄력적이면 순손실은 0이다."},{"번호":2,"판정":"옳음","설명":"공급곡선이 수직이면 수요 증가는 가격만 올린다."},{"번호":3,"판정":"옳음","설명":"건축자재 가격 상승은 생산비 증가이므로 공급이 감소한다(공급곡선 좌측 이동)."},{"번호":4,"판정":"틀림","설명":"수요 감소와 공급 증가가 동시에 일어나면 가격은 하락한다. 거래량은 수요 감소폭이 크면 감소, 공급 증가폭이 크면 증가한다."},{"번호":5,"판정":"옳음","설명":"대체재 가격이 오르면 해당 부동산의 수요가 늘어 수요곡선이 오른쪽으로 이동한다."}],"개념":[{"종류":"표","제목":"공급곡선 탄력성별 수요 증가의 효과","머리":["공급의 탄력성","균형가격","균형거래량"],"행":[["완전비탄력적","상승","불변"],["비탄력적","크게 상승","적게 증가"],["탄력적","적게 상승","크게 증가"],["완전탄력적","불변","증가"]]},{"종류":"비교","제목":"수요와 공급의 변화 요인","왼쪽":{"이름":"수요 변화 요인","항목":["소득 증가: 정상재 수요 증가","인구·가구 수 증가","대체재 가격 상승: 수요 증가","보완재 가격 상승: 수요 감소","금리 하락·대출 완화","가격 상승 기대"]},"오른쪽":{"이름":"공급 변화 요인","항목":["건축자재·임금 등 생산요소 가격 상승: 공급 감소","건축기술 발달: 공급 증가","건축규제 강화: 공급 감소","공급자 수 증가","세금 부과·보조금 폐지: 공급 감소","가격 상승 기대 시 공급 유보 가능"]}}],"함정":"수요·공급이 반대 방향으로 움직이는 문장에서 거래량까지 확정으로 쓴 선지에 걸린다. 같은 방향이면 거래량, 반대 방향이면 가격만 확정된다. 순손실은 탄력적인 쪽이 클수록 커진다는 것도 방향을 반대로 외우기 쉽다."}},{"i":"S5-1-1-학개론-06","r":"S5","g":1,"c":1,"n":6,"s":"학개론","q":"부동산매매시장의 수요와 공급에 관한 설명으로 옳은 것은? (단, 수요곡선은 우하향, 공급곡선은 우상향하며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["수요곡선은 한계비용곡선이다.","수요곡선상의 수요량은 주어진 가격에서 수요자들이 구입하고자 하는 부동산의 최소수량이다.","수요량의 변화는 수요 자체의 변화를 말하며, 수요곡선 자체를 이동시킨다.","공급곡선은 한계편익곡선이다.","공급함수는 부동산의 공급량에 영향을 미치는 요인들과 공급량의 관계를 나타내는 함수이다."],"a":[5],"L":"학2-1","o":"기출","x":{"한줄":"공급함수는 공급량과 그 결정 요인 사이의 관계를 나타낸 함수다.","근거":[{"이론":"수요·공급의 기본 개념","내용":"수요곡선은 한계편익곡선, 공급곡선은 한계비용곡선이다. 수요량은 주어진 가격에서 구입하고자 하는 최대수량이다. 가격 변화로 인한 수요량 변화는 곡선상 이동이고, 가격 이외 요인 변화로 인한 수요 변화는 곡선 자체의 이동이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수요곡선은 소비자의 한계편익을 나타내는 한계편익곡선이다. 한계비용곡선은 공급곡선이다."},{"번호":2,"판정":"틀림","설명":"수요량은 주어진 가격에서 수요자가 구입하려는 최대수량이다."},{"번호":3,"판정":"틀림","설명":"수요량의 변화는 가격 변화에 따른 수요곡선상 이동이다. 수요곡선 자체의 이동은 수요의 변화다."},{"번호":4,"판정":"틀림","설명":"공급곡선은 공급자의 한계비용을 나타내는 한계비용곡선이다."},{"번호":5,"판정":"옳음","설명":"공급함수는 Qs=f(가격, 생산요소 가격, 기술 등)처럼 공급량과 공급량에 영향을 주는 요인의 관계를 나타낸다."}],"개념":[{"종류":"비교","제목":"수요량의 변화와 수요의 변화","왼쪽":{"이름":"수요량의 변화","항목":["원인: 해당 부동산 가격 변화","수요곡선상의 점 이동","가격 상승 시 수요량 감소"]},"오른쪽":{"이름":"수요의 변화","항목":["원인: 가격 이외 요인(소득·인구·선호·대체재 가격·금리·기대 등)","수요곡선 자체의 좌우 이동","공급도 같은 방식: 공급량 변화는 곡선상 이동, 공급 변화는 곡선 이동"]}},{"종류":"표","제목":"수요곡선과 공급곡선의 경제적 의미","머리":["구분","나타내는 것","기울기","수량의 의미"],"행":[["수요곡선","한계편익","우하향","주어진 가격에서 구입하려는 최대수량"],["공급곡선","한계비용","우상향","주어진 가격에서 공급하려는 최대수량"],["수요함수","수요량과 결정 요인(가격·소득·대체재 가격 등)의 관계","-","-"],["공급함수","공급량과 결정 요인(가격·생산요소 가격·기술 등)의 관계","-","-"]]}],"함정":"한계편익과 한계비용의 짝을 바꾸거나 최대·최소를 바꾼 선지가 반복해서 나온다. 수요량과 수요도 이름이 비슷해 섞어 쓴다. 곡선 자체가 움직이는 것은 수요(공급)의 변화다."}},{"i":"S5-1-1-학개론-07","r":"S5","g":1,"c":1,"n":7,"s":"학개론","q":"부동산에 관한 수요와 공급의 탄력성에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["수요의 가격탄력성이 1보다 큰 경우, 임대료가 하락하면 임대료 총수입은 증가한다.","임대주택 수요의 가격탄력성이 비탄력적인 경우, 임대료가 상승하면 임대료 총수입은 감소한다.","소득탄력성이 0보다 작은 재화는 열등재이다.","두 재화의 교차탄력성이 음(-)이면 두 재화는 보완재 관계이다.","주택을 건축하여 공급하는 기간이 길수록 단기에는 공급의 가격탄력성이 작아진다."],"a":[2],"L":"학2-2","o":"변형","x":{"한줄":"수요가 비탄력적이면 임대료가 오를 때 수요량이 덜 줄어 총수입이 증가한다.","근거":[{"이론":"탄력성과 총수입","내용":"총수입=가격×수량. 탄력적(e>1)이면 가격 인하 시 총수입 증가, 비탄력적(e<1)이면 가격 인상 시 총수입 증가, 단위탄력적(e=1)이면 가격이 변해도 총수입은 불변이다. 소득탄력성이 0보다 작으면 열등재, 교차탄력성이 음(-)이면 보완재, 양(+)이면 대체재다."}],"선지":[{"번호":1,"판정":"옳음","설명":"탄력적(e>1)이면 가격 하락률보다 수요량 증가율이 커서 총수입이 증가한다."},{"번호":2,"판정":"틀림","설명":"비탄력적(e<1)이면 임대료 상승률보다 수요량 감소율이 작아서 총수입이 증가한다."},{"번호":3,"판정":"옳음","설명":"소득이 증가할 때 수요량이 감소하는 재화(소득탄력성<0)가 열등재다."},{"번호":4,"판정":"옳음","설명":"교차탄력성=A재 수요량 변화율÷B재 가격 변화율. 음이면 B재 가격이 오를 때 A재 수요가 줄므로 보완재다."},{"번호":5,"판정":"옳음","설명":"건축 기간이 긴 주택은 단기에 공급을 늘리기 어려워 공급의 가격탄력성이 작다. 기간이 길수록 공급 조정이 어렵기 때문이다."}],"개념":[{"종류":"표","제목":"탄력성의 종류와 판정","머리":["종류","공식","판정"],"행":[["수요의 가격탄력성","수요량 변화율÷가격 변화율(절댓값)","1보다 크면 탄력적, 1이면 단위탄력적, 1보다 작으면 비탄력적"],["수요의 소득탄력성","수요량 변화율÷소득 변화율","양(+)이면 정상재(1 초과 사치재), 음(-)이면 열등재"],["수요의 교차탄력성","A재 수요량 변화율÷B재 가격 변화율","양(+)이면 대체재, 음(-)이면 보완재, 0이면 독립재"],["공급의 가격탄력성","공급량 변화율÷가격 변화율","기간이 길수록, 생산요소 대체가 쉬울수록 커짐"]]},{"종류":"계산","제목":"가격탄력성과 총수입","단계":[{"설명":"가격탄력성 공식","식":"탄력성=수요량 변화율÷가격 변화율","값":"-"},{"설명":"임대료 10% 하락, 수요량 20% 증가 대입","식":"20%÷10%","값":"탄력성 2(탄력적)"},{"설명":"총수입 변화: 새 가격 0.9, 새 수량 1.2","식":"0.9×1.2","값":"1.08 → 총수입 8% 증가"}]}],"함정":"비탄력적일 때는 가격을 올려야 총수입이 늘어나고, 탄력적일 때는 가격을 내려야 늘어난다. 이 방향을 반대로 쓰기 쉽다. 단위탄력적에서는 가격이 변해도 총수입이 변하지 않는다."}},{"i":"S5-1-1-학개론-08","r":"S5","g":1,"c":1,"n":8,"s":"학개론","q":"어느 지역의 수요와 공급함수가 A부동산상품 시장에서는 Qd=200-2P, 2Qs=-20+6P, B부동산상품 시장에서는 Qd=300-4P, 3Qs=-30+6P 이며, A부동산상품의 가격이 5% 상승하였을 때 B부동산상품의 수요가 3% 증가하였다. 거미집이론(Cob-web theory)에 의한 A와 B 각각의 모형 형태와 A부동산상품과 B부동산상품의 관계는? (단, x축은 수량, y축은 가격, 각각의 시장에 대한 P는 가격, Qd는 수요량, Qs는 공급량이며, 다른 조건은 동일함) (순서대로 A, B, A와 B의 관계)","b":null,"bs":"없음","img":[],"ch":["수렴형, 발산형, 대체재","발산형, 수렴형, 보완재","순환형, 수렴형, 대체재","발산형, 수렴형, 대체재","수렴형, 순환형, 보완재"],"a":[4],"L":"학2-3","o":"변형","x":{"한줄":"A시장은 공급곡선이 수요곡선보다 완만해 발산형, B시장은 공급곡선이 더 가팔라 수렴형이고, 교차탄력성이 양(+)이어서 대체재다.","근거":[{"이론":"거미집모형의 판정","내용":"x축을 수량, y축을 가격으로 놓았을 때 수요곡선 기울기의 절댓값이 공급곡선 기울기의 절댓값보다 작으면 수렴, 같으면 순환(진동), 크면 발산이다. 탄력성으로는 공급의 가격탄력성이 수요의 가격탄력성보다 작으면 수렴, 같으면 순환, 크면 발산이다."},{"이론":"교차탄력성","내용":"A재 가격 변화율에 대한 B재 수요량 변화율의 비. 양(+)이면 대체재, 음(-)이면 보완재다."}],"선지":[{"번호":1,"판정":"-","설명":"A시장은 수렴이 아니라 발산이다. 수요 기울기 1/2이 공급 기울기 1/3보다 크다."},{"번호":2,"판정":"-","설명":"A와 B의 형태는 맞지만 관계가 보완재가 아니다. 교차탄력성이 +0.6이므로 대체재다."},{"번호":3,"판정":"-","설명":"A시장은 순환형이 아니다. 두 기울기가 같지 않다(수요 1/2, 공급 1/3)."},{"번호":4,"판정":"-","설명":"A 발산형, B 수렴형, 두 상품은 대체재로 모두 맞다."},{"번호":5,"판정":"-","설명":"A는 수렴형이 아니고 B는 순환형이 아니며 관계도 대체재다."}],"개념":[{"종류":"계산","제목":"거미집 판정과 교차탄력성","단계":[{"설명":"A 수요함수를 P에 대해 정리, 기울기 절댓값","식":"Qd=200-2P → P=100-0.5Q","값":"1/2"},{"설명":"A 공급함수를 P에 대해 정리, 기울기","식":"2Qs=-20+6P → Qs=-10+3P → P=(Qs+10)/3","값":"1/3"},{"설명":"A 판정: 수요 기울기 1/2 > 공급 기울기 1/3","식":"수요 기울기 > 공급 기울기","값":"발산형"},{"설명":"B 수요함수 기울기","식":"Qd=300-4P → P=75-0.25Q","값":"1/4"},{"설명":"B 공급함수 기울기","식":"3Qs=-30+6P → Qs=-10+2P → P=5+0.5Qs","값":"1/2"},{"설명":"B 판정: 수요 기울기 1/4 < 공급 기울기 1/2","식":"수요 기울기 < 공급 기울기","값":"수렴형"},{"설명":"교차탄력성: B 수요량 변화율÷A 가격 변화율","식":"3%÷5%","값":"+0.6 → 대체재"}]},{"종류":"표","제목":"거미집모형의 세 유형","머리":["유형","기울기 비교(절댓값)","탄력성 비교","가격·수량의 움직임"],"행":[["수렴형","수요 기울기 < 공급 기울기","수요탄력성 > 공급탄력성","균형점으로 접근"],["순환형(진동형)","수요 기울기 = 공급 기울기","수요탄력성 = 공급탄력성","일정한 폭으로 진동"],["발산형","수요 기울기 > 공급 기울기","수요탄력성 < 공급탄력성","균형에서 점점 이탈"],["전제","공급은 한 기간 전의 가격에 반응","수요는 현재 가격에 반응","주택·농산물처럼 생산 기간이 긴 재화"]]}],"함정":"함수의 P 앞 계수는 가격에 대한 수량 반응이다. 기울기(y축 가격)는 이 계수의 역수이므로 계수 크기와 기울기 크기의 순서가 뒤집힌다. 계수를 그대로 비교하면 수렴과 발산이 뒤바뀐다. 가격을 수량에 대해 정리한 뒤 기울기를 비교한다."}},{"i":"S5-1-1-학개론-09","r":"S5","g":1,"c":1,"n":9,"s":"학개론","q":"부동산시장에 관한 설명으로 틀린 것은? (단, 다른 조건은 모두 동일함)","b":null,"bs":"없음","img":[],"ch":["부동산시장은 거래의 비공개성과 정보의 비대칭성 때문에 불완전경쟁시장이 되기 쉽다.","준강성 효율적 시장에서는 공표된 정보는 물론 아직 공표되지 않은 내부정보를 이용해서도 초과이윤을 얻을 수 없다.","약성 효율적 시장에서는 과거의 가격 추세를 분석해서는 초과이윤을 얻을 수 없다.","할당효율적 시장에서는 정보를 이용하여 얻은 초과이윤이 정보를 얻는 비용을 초과하지 못한다.","부동산시장은 지역성이 강해 지역별로 수요와 공급 및 가격이 다르게 형성될 수 있다."],"a":[2],"L":"학3-1","o":"변형","x":{"한줄":"준강성 효율적 시장은 공표된 정보만 가격에 반영돼 있어서 공표되지 않은 내부정보를 이용하면 초과이윤을 얻을 수 있다.","근거":[{"이론":"효율적 시장가설","내용":"약성은 과거 정보, 준강성은 과거와 현재의 공표된 정보, 강성은 공표된 정보와 공표되지 않은 정보까지 모두 가격에 반영돼 있다고 본다. 반영되지 않은 정보를 이용하면 초과이윤이 가능하다. 할당효율적 시장은 정보를 이용한 초과이윤이 정보비용을 넘지 못해 자원이 효율적으로 배분되는 시장이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"거래 정보가 비공개이고 정보가 비대칭이어서 부동산시장은 불완전경쟁시장이 되기 쉽다."},{"번호":2,"판정":"틀림","설명":"준강성 효율적 시장에서도 공표되지 않은 내부정보를 이용하면 초과이윤을 얻을 수 있다. 내부정보까지 반영된 시장은 강성이다."},{"번호":3,"판정":"옳음","설명":"약성 효율적 시장은 과거 정보가 이미 가격에 반영돼 있어 기술적 분석(과거 추세 분석)으로 초과이윤을 얻을 수 없다."},{"번호":4,"판정":"옳음","설명":"정보비용을 뺀 초과이윤이 없으면 정보에 투자할 유인이 없으므로 할당효율적이다. 불완전경쟁시장에서도 성립할 수 있다."},{"번호":5,"판정":"옳음","설명":"부동성 때문에 시장이 지역별로 나뉘고 가격·거래 조건이 지역마다 다르게 형성된다."}],"개념":[{"종류":"표","제목":"효율적 시장의 세 형태","머리":["형태","가격에 반영된 정보","초과이윤 가능 여부"],"행":[["약성","과거 정보(가격·거래량 추세)","과거 추세 분석(기술적 분석)으로 불가능, 공표된 정보 분석(기본적 분석)과 내부정보 이용은 가능"],["준강성","과거 정보와 현재 공표된 정보","기술적·기본적 분석으로 불가능, 내부정보 이용은 가능"],["강성","공표된 정보와 공표되지 않은 정보 전부","어떤 정보를 이용해도 불가능"],["부동산시장의 현실","정보 비대칭·거래 비공개로 약성 효율적 시장도 어렵다","초과이윤 가능성이 큼"]]},{"종류":"표","제목":"시장의 효율성 구분","머리":["구분","내용"],"행":[["정보효율적 시장","정보가 가격에 얼마나 반영되었는가(약성·준강성·강성)"],["할당효율적 시장","정보를 이용한 초과이윤이 정보비용을 넘지 못하는 시장"],["불완전경쟁시장","진입장벽·정보 비대칭이 있어도 할당효율적일 수 있음"],["시장 분화","부분시장별로 수급 불균형이 생길 수 있음"]]}],"함정":"준강성과 강성의 경계는 공표되지 않은 내부정보다. 내부정보를 이용한 초과이윤은 약성·준강성에서는 가능하고 강성에서만 불가능하다. 반영 정보를 한 단계씩 밀어서 쓴 선지에 걸린다."}},{"i":"S5-1-1-학개론-10","r":"S5","g":1,"c":1,"n":10,"s":"학개론","q":"주택여과과정과 주거분리에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["저급주택이 수선되거나 재개발되어 상위계층이 사용하게 되는 것을 하향여과라 한다.","주거분리는 고소득층과 저소득층이 같은 지역에서 어울려 사는 현상이다.","저소득층 주거지역과 인접한 고소득층 주거지역의 주택은 할증된 가격으로 거래된다.","상위계층이 사용하던 기존주택을 하위계층이 사용하게 되는 것을 하향여과라 하며, 하위계층의 주거수준을 높이는 효과가 있다.","공가(公家)의 발생은 주거지 이동과는 관계가 없다."],"a":[4],"L":"학3-2","o":"변형","x":{"한줄":"고소득층이 쓰던 주택을 저소득층이 쓰게 되는 것이 하향여과이고, 이 과정에서 저소득층의 주거수준이 오를 수 있다.","근거":[{"이론":"주택여과과정과 주거분리","내용":"하향여과는 상위계층 주택이 하위계층으로 넘어가는 현상, 상향여과는 저급주택이 수선·재개발되어 상위계층이 쓰는 현상이다. 주거분리는 소득·인종 등에 따라 주거지가 나뉘는 현상으로, 저소득층 주거지와 인접한 고소득층 주거지의 주택은 할인되고 고소득층 주거지와 인접한 저소득층 주거지의 주택은 할증된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"저급주택이 수선·재개발되어 상위계층이 사용하는 것은 상향여과다."},{"번호":2,"판정":"틀림","설명":"주거분리는 소득 등에 따라 계층별로 주거지역이 나뉘는 현상이다. 같은 지역에서 어울려 사는 것은 혼합(통합)이다."},{"번호":3,"판정":"틀림","설명":"저소득층 주거지와 인접한 고소득층 주거지의 주택은 할인되어 거래된다. 할증되는 쪽은 고소득층 주거지에 인접한 저소득층 주거지의 주택이다."},{"번호":4,"판정":"옳음","설명":"하향여과는 상위계층 주택이 하위계층에 넘어가는 현상으로 하위계층의 주거수준 상승 효과가 있다."},{"번호":5,"판정":"틀림","설명":"여과과정에서 주택이 이동하면 이전 거주 주택이 비어 공가가 생기고 연쇄적인 주거지 이동이 일어난다. 공가의 발생은 주거지 이동과 관계가 있다."}],"개념":[{"종류":"비교","제목":"상향여과와 하향여과","왼쪽":{"이름":"상향여과","항목":["저급주택이 수선·재개발","상위계층이 사용하게 됨","예: 저소득층 주거지의 고급화(젠트리피케이션)"]},"오른쪽":{"이름":"하향여과","항목":["상위계층이 사용하던 기존주택","하위계층이 사용하게 됨","저소득층의 주거수준 상승 효과","공가·주거지 이동의 연쇄가 일어남"]}},{"종류":"표","제목":"주거분리와 외부효과","머리":["구분","내용","가격 영향"],"행":[["주거분리","소득·인종·민족 등에 따라 주거지역이 나뉘는 현상","-"],["고소득층 주거지와 인접한 저소득층 주거지의 주택","고소득층 주택의 긍정적 외부효과를 누림","할증"],["저소득층 주거지와 인접한 고소득층 주거지의 주택","저소득층 주거지의 부정적 외부효과를 받음","할인"],["경계지역","두 계층 사이 접경 지역","가격 차이가 나타남"]]}],"함정":"상향여과와 하향여과의 방향을 맞바꾼 문장이 가장 흔하다. 상향은 저급주택이 올라가 상위계층이 쓰는 경우, 하향은 상위계층 주택이 내려오는 경우로 기억한다. 주거분리의 할증·할인도 반대로 쓰기 쉽다."}},{"i":"S5-1-1-학개론-11","r":"S5","g":1,"c":1,"n":11,"s":"학개론","q":"지대이론에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["리카도의 차액지대설에 따르면 한계지에서도 지대가 발생한다.","마르크스의 절대지대설은 토지의 비옥도 차이에서 지대가 발생한다고 본다.","튀넨의 위치지대설은 토지의 비옥도 차이가 지대를 결정한다고 본다.","마샬의 준지대는 토지에서 발생하는 영구적인 소득을 말한다.","알론소의 입찰지대는 토지이용자가 초과이윤 없이 지불할 수 있는 최대 지대이며, 입찰지대곡선은 각 지점에서 가장 높은 입찰지대를 이은 선이다."],"a":[5],"L":"학3-3","o":"신작","x":{"한줄":"알론소의 입찰지대는 초과이윤이 0이 되는 수준에서 이용자가 낼 수 있는 최대 금액이고, 입찰지대곡선은 각 위치의 최고 입찰지대를 연결한 선이다.","근거":[{"이론":"지대이론","내용":"리카도는 비옥도 차이에 따른 차액지대로 한계지는 무지대로 본다. 마르크스는 토지 소유의 독점으로 최열등지에도 절대지대가 생긴다고 본다. 튀넨은 비옥도가 같아도 수송비 차이로 위치지대가 생긴다고 본다. 마샬의 준지대는 기계·설비 등 단기 고정 생산요소의 소득으로 장기에는 소멸한다. 알론소는 튀넨의 이론을 단일 도심 도시에 적용해 입찰지대 개념을 정립했다."}],"선지":[{"번호":1,"판정":"틀림","설명":"리카도의 한계지(조방적 한계)는 무지대다. 한계지보다 비옥한 토지에만 차액지대가 생긴다."},{"번호":2,"판정":"틀림","설명":"절대지대는 토지 소유의 독점적 지위에서 생기며 최열등지에도 발생한다. 비옥도 차이에서 생기는 지대는 리카도의 차액지대다."},{"번호":3,"판정":"틀림","설명":"튀넨의 위치지대는 비옥도가 같아도 시장까지의 수송비 차이로 생긴다."},{"번호":4,"판정":"틀림","설명":"준지대는 기계·설비 등 단기 고정 생산요소에 대한 일시적 소득이며 장기에는 사라진다."},{"번호":5,"판정":"옳음","설명":"입찰지대는 이용자가 낼 수 있는 최대 금액이다. 입찰지대곡선은 도심에서 외곽까지 지점별 최고 입찰지대를 이은 선이다."}],"개념":[{"종류":"표","제목":"지대이론 학자별 비교","머리":["학자","이론","지대 발생 원인","한 줄 포인트"],"행":[["리카도","차액지대","비옥한 토지의 희소성과 수확체감","한계지는 무지대"],["마르크스","절대지대","토지 소유의 독점","최열등지에도 지대 발생"],["튀넨","위치지대(고립국)","수송비 차이","도심에 가까우면 집약, 멀면 조방"],["알론소","입찰지대","지점별 지불 가능한 최대 금액","단일 도심 도시, 초과이윤 0"],["마샬","준지대","단기 고정 생산요소의 소득","일시적, 장기엔 소멸"]]},{"종류":"표","제목":"도시공간구조이론 세 가지","머리":["이론","학자","구조","특징"],"행":[["동심원이론","버제스","중심업무지구→점이지대→저소득층 주거지대→중산층 지대→통근자 지대","시카고 실증, 침입·경쟁·천이"],["선형이론","호이트","교통축을 따라 부채꼴로 확장","고급주택지구는 교통노선·호반·해안 따라 입지"],["다핵심이론","해리스·울만","여러 개 핵이 분리됐다가 점차 통합","현대 대도시 설명에 적합"],["지대와 지가","-","지가=지대÷환원이율","지대가 높으면 지가도 높다"]]}],"함정":"학자와 이론을 맞바꾼 선지가 대부분이다. 최열등지의 지대는 리카도는 없다, 마르크스는 있다로 가른다. 튀넨은 비옥도가 같다는 전제에서 수송비만 다르다."}},{"i":"S5-1-1-학개론-12","r":"S5","g":1,"c":1,"n":12,"s":"학개론","q":"공업입지이론에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["베버의 최소비용이론은 시장 확대 가능성이 가장 큰 지점을 최적 입지로 본다.","베버의 최소비용이론에서 국지원료 중량을 제품 중량으로 나눈 원료지수가 1보다 크면 원료지향형 입지가 유리하다.","원료지수가 1보다 작은 산업은 중량감소산업이므로 원료산지에 입지하는 것이 유리하다.","등비용선은 노동비 절감액과 추가 운송비가 같아지는 점을 연결한 선이다.","아이사드·그린허트·스미스의 통합이론은 총비용이 가장 적은 지점을 최적 입지로 본다."],"a":[2],"L":"학3-4","o":"신작","x":{"한줄":"원료지수가 1보다 크면 국지원료가 제품보다 무거운 중량감소산업이어서 원료산지 쪽에 입지하는 것이 운송비가 적게 든다.","근거":[{"이론":"베버의 최소비용이론","내용":"원료지수(MI)=국지원료 중량÷제품 중량. MI>1이면 중량감소산업으로 원료지향형, MI<1이면 중량증가산업(보편원료를 많이 사용)으로 시장지향형이다. 입지중량=원료지수+1. 등비용선은 최소운송비 지점에서 이동할 때 추가되는 운송비가 같은 점을 연결한 선이고, 임계등비용선은 노동비 절감액과 추가 운송비가 같은 점을 연결한 선이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"시장 확대 가능성(최대수요)을 기준으로 보는 이론은 뢰쉬의 최대수요이론이다. 베버는 비용(운송비·노동비·집적이익)이 최소인 지점을 본다."},{"번호":2,"판정":"옳음","설명":"MI>1이면 중량감소산업이고 원료지향형이 유리하다."},{"번호":3,"판정":"틀림","설명":"MI<1이면 중량증가산업이고 시장지향형이 유리하다. 원료산지 입지가 유리한 쪽은 MI>1이다."},{"번호":4,"판정":"틀림","설명":"노동비 절감액과 추가 운송비가 같은 점을 연결한 선은 임계등비용선이다. 등비용선은 추가 운송비가 같은 점을 연결한 선이다."},{"번호":5,"판정":"틀림","설명":"통합이론은 총수익에서 총비용을 뺀 이윤이 가장 큰 지점을 최적 입지로 본다."}],"개념":[{"종류":"표","제목":"공업입지 이론 비교","머리":["학자","관점","최적 입지 기준"],"행":[["베버","공급(비용) 측면","운송비·노동비·집적이익을 따져 총비용이 최소인 지점"],["뢰쉬","수요 측면","시장 확대 가능성이 가장 큰 지점"],["아이사드·그린허트·스미스(통합이론)","수익과 비용 모두","총수익-총비용이 최대인 지점"],["입지삼각형","베버","원료지 2곳과 시장을 꼭짓점으로 한 삼각형 안의 운송비 최소점"]]},{"종류":"표","제목":"원료지수와 입지 유형","머리":["원료지수(MI)","산업 성격","유리한 입지"],"행":[["MI>1","중량감소산업(국지원료가 제품보다 무거움)","원료지향형"],["MI=1","중간","원료지·시장 어디든 운송비 같음"],["MI<1","중량증가산업, 보편원료를 많이 사용","시장지향형"],["입지중량","MI+1","운송비 크기 가늠"]]}],"함정":"원료지수 1을 기준으로 원료지향과 시장지향을 뒤바꾸기 쉽다. 베버를 수요 측면 이론으로, 뢰쉬를 비용 측면 이론으로 바꿔 쓰는 선지도 자주 나온다. 등비용선과 임계등비용선도 짝을 맞바꾼다."}},{"i":"S5-1-1-학개론-13","r":"S5","g":1,"c":1,"n":13,"s":"학개론","q":"허프(D. Huff)모형을 활용하여 점포 A의 월 매출액을 구하면 얼마인가? (단, 공간마찰계수는 2이고, 다른 조건은 동일함)\n○ 소비자 거주 지역에 1,000명이 거주하며 1인당 월 평균 40만원을 이 상품에 소비한다.\n○ 소비자는 점포 A, B, C 중 한 곳에서만 구매한다.\n○ 점포 A: 매장면적 600m², 거주 지역으로부터 거리 2km\n○ 점포 B: 매장면적 900m², 거주 지역으로부터 거리 3km\n○ 점포 C: 매장면적 250m², 거주 지역으로부터 거리 1km","b":null,"bs":"없음","img":[],"ch":["0.8억원","1.0억원","1.2억원","1.4억원","2.0억원"],"a":[3],"L":"학3-4","o":"신작","x":{"한줄":"A의 유인력 150은 전체 유인력 500의 30퍼센트이므로 전체 시장 4억원에 곱하면 월 매출액은 1.2억원이다.","근거":[{"이론":"허프의 확률모형","내용":"유인력=매장면적÷거리^k(k는 공간마찰계수). 소비자가 점포를 선택할 확률=해당 점포 유인력÷모든 점포 유인력의 합. 점포 매출=상권 내 총수요(인구×1인당 소비액)×선택 확률."}],"선지":[{"번호":1,"판정":"-","설명":"0.8억원은 점포 B의 매출액이다(확률 20퍼센트)."},{"번호":2,"판정":"-","설명":"1.0억원이 될 확률 25퍼센트는 어느 점포에도 해당하지 않는다."},{"번호":3,"판정":"-","설명":"A 확률 30퍼센트에 시장 규모 4억원을 곱하면 1.2억원이다."},{"번호":4,"판정":"-","설명":"공간마찰계수를 2가 아니라 1로 적용했을 때 나오는 값(약 1.41억원)에 가깝다."},{"번호":5,"판정":"-","설명":"2.0억원은 점포 C의 매출액이다(확률 50퍼센트)."}],"개념":[{"종류":"계산","제목":"허프모형 매출액 계산","단계":[{"설명":"점포별 유인력=매장면적÷거리²","식":"A: 600÷2², B: 900÷3², C: 250÷1²","값":"A 150, B 100, C 250"},{"설명":"유인력 합계","식":"150+100+250","값":"500"},{"설명":"점포 A 선택 확률","식":"150÷500","값":"30%"},{"설명":"시장 전체 월 소비","식":"1,000명×40만원","값":"4억원"},{"설명":"점포 A 월 매출액","식":"4억원×30%","값":"1.2억원"}]},{"종류":"표","제목":"상업입지 이론 학자별 비교","머리":["학자","이론","핵심 내용"],"행":[["레일리","소매인력법칙","유인력은 도시 인구에 비례하고 거리의 제곱에 반비례"],["컨버스","분기점 모형","경계 거리=두 도시 사이 거리÷(1+√(상대 도시 인구÷기준 도시 인구)), 경계는 작은 도시 쪽으로 붙음"],["허프","확률모형","선택 확률은 매장면적에 비례, 거리의 k제곱에 반비례"],["크리스탈러","중심지이론","최소요구치 범위가 재화의 도달범위보다 작을 때 중심지 성립, 배후지는 정육각형"],["넬슨","소매입지 8원칙","최대 매출을 얻을 점포 입지 원칙"]]}],"함정":"거리에 k제곱을 하지 않고 1제곱으로 계산하면 비슷한 값이 나와 1.4억원에 걸린다. 확률을 구한 뒤 시장 전체 규모(인구×1인당 소비액)를 곱하는 것도 빠뜨리기 쉽다."}},{"i":"S5-1-1-학개론-14","r":"S5","g":1,"c":1,"n":14,"s":"학개론","q":"외부효과와 공공재에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["긍정적 외부효과가 있는 재화는 시장에서 사회적 최적 수준보다 과다하게 생산된다.","공공재는 비경합성과 비배제성 때문에 무임승차 문제가 생기고 시장에 맡기면 과소공급되는 경향이 있다.","부정적 외부효과가 있는 재화는 시장에서 사회적 최적 수준보다 과소하게 생산된다.","코즈(R. Coase)의 정리는 거래비용이 크더라도 재산권이 확립되면 시장에서 외부효과가 해결된다고 본다.","공공재는 한 사람이 소비하면 다른 사람이 소비할 수 있는 양이 줄어드는 경합성이 있다."],"a":[2],"L":"학4-1","o":"변형","x":{"한줄":"공공재는 소비에서 배제할 수 없고 서로 경합하지 않아서 비용을 내지 않고 이용하려는 무임승차가 생기고 시장에서는 과소공급된다.","근거":[{"이론":"외부효과와 공공재","내용":"긍정적 외부효과는 사회적 편익이 사적 편익보다 커서 과소생산, 부정적 외부효과는 사회적 비용이 사적 비용보다 커서 과다생산된다. 공공재는 비경합성·비배제성이 있고 무임승차로 과소공급된다. 코즈의 정리는 거래비용이 없거나 작고 재산권이 확립됐을 때 당사자 협상으로 외부효과가 해결된다는 이론이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"긍정적 외부효과가 있으면 사회적 편익이 사적 편익보다 커서 과소하게 생산된다."},{"번호":2,"판정":"옳음","설명":"비경합성·비배제성 때문에 무임승차가 생기고 시장 기구에 맡기면 과소공급된다."},{"번호":3,"판정":"틀림","설명":"부정적 외부효과가 있으면 사회적 비용이 사적 비용보다 커서 과다하게 생산된다."},{"번호":4,"판정":"틀림","설명":"코즈의 정리는 거래비용이 없거나 작을 때 성립한다. 거래비용이 크면 협상으로 해결하기 어렵다."},{"번호":5,"판정":"틀림","설명":"공공재는 한 사람의 소비가 다른 사람의 소비를 줄이지 않는 비경합성이 있다."}],"개념":[{"종류":"비교","제목":"긍정적 외부효과와 부정적 외부효과","왼쪽":{"이름":"긍정적(+) 외부효과","항목":["사회적 편익 > 사적 편익","시장 생산량은 과소","대응: 보조금, 세제 혜택, 규제 완화","예: 공원·철도역 개통이 주변 지가 상승"]},"오른쪽":{"이름":"부정적(-) 외부효과","항목":["사회적 비용 > 사적 비용","시장 생산량은 과다","대응: 부담금·세금, 규제, 용도지역제","예: 공장·혐오시설이 주변 지가 하락"]}},{"종류":"표","제목":"시장실패 원인과 정부 개입 수단","머리":["시장실패 원인","내용","정부 개입 예"],"행":[["외부효과","제3자에게 대가 없는 이익·손해","부담금, 보조금, 용도지역제"],["공공재","비경합성·비배제성, 무임승차","정부가 직접 공급"],["불완전경쟁(독점)","공급자 우위로 과소생산·고가","독점 규제, 가격 규제"],["정보의 비대칭","거래 당사자 간 정보 격차","부동산 가격공시, 거래 신고·정보 공개"]]}],"함정":"긍정적 외부효과는 과소생산, 부정적 외부효과는 과다생산이다. 이 방향을 반대로 쓴 선지에 걸린다. 코즈의 정리는 거래비용이 낮다는 전제를 빼면 틀린다."}},{"i":"S5-1-1-학개론-15","r":"S5","g":1,"c":1,"n":15,"s":"학개론","q":"부동산정책 중 금융규제에 해당하는 것은?","b":null,"bs":"없음","img":[],"ch":["택지개발지구 지정","토지거래허가제 시행","개발부담금의 부담률 인상","분양가상한제의 적용 지역 확대","총부채원리금상환비율(DSR) 강화"],"a":[5],"L":"학4-1","o":"기출","x":{"한줄":"총부채원리금상환비율(DSR) 강화는 대출 한도를 줄여 수요를 억제하는 금융규제다.","근거":[{"이론":"부동산정책 수단의 분류","내용":"금융규제는 담보인정비율(LTV)·총부채상환비율(DTI)·총부채원리금상환비율(DSR) 등으로 대출 한도와 요건을 조정하는 정책이다. 토지거래 허가·분양가 제한은 거래·가격에 대한 직접규제, 개발부담금은 개발이익 환수, 택지개발지구 지정은 토지 공급과 이용에 관한 정책이다."}],"선지":[{"번호":1,"판정":"-","설명":"택지개발지구 지정은 주택용 택지를 계획적으로 개발·공급하는 공급정책이다."},{"번호":2,"판정":"-","설명":"토지거래허가제는 허가구역 안에서 토지거래계약을 허가받게 하는 거래규제다(부동산 거래신고 등에 관한 법률 제10조)."},{"번호":3,"판정":"-","설명":"개발부담금은 개발이익 중 법에 따라 부과·징수하는 금액으로 개발이익 환수 수단이다(개발이익 환수에 관한 법률 제2조제4호)."},{"번호":4,"판정":"-","설명":"분양가상한제는 일정 지역의 공동주택 분양가격을 제한하는 가격규제다(주택법 제57조제1항)."},{"번호":5,"판정":"-","설명":"DSR 강화는 연간 원리금 상환액의 소득 대비 비율 한도를 낮추는 대출 규제로 금융규제에 해당한다."}],"개념":[{"종류":"표","제목":"부동산정책 수단 분류","머리":["분류","수단 예","내용"],"행":[["금융규제","LTV·DTI·DSR 조정, 대출 총량 관리","대출 한도와 상환 능력을 기준으로 수요 조절"],["거래규제","토지거래허가제, 부동산 거래신고","거래 자체를 허가·신고 대상으로 관리"],["가격규제","분양가상한제, 임대료 규제","가격 상한을 정해 시장가격에 개입"],["개발이익 환수","개발부담금, 재건축부담금","개발로 생긴 이익의 일부를 환수"],["공급정책","택지개발지구 지정, 공공주택 공급","토지·주택 공급량 확대"],["이용규제","용도지역·지구제, 개발제한구역","토지이용을 제한해 개발 조절"]]}],"함정":"토지거래허가제와 분양가상한제도 부동산시장을 누르는 정책이라 금융규제로 오해하기 쉽다. 금융규제는 대출과 관련된 정책(LTV·DTI·DSR)만 가리킨다."}},{"i":"S5-1-1-학개론-16","r":"S5","g":1,"c":1,"n":16,"s":"학개론","q":"부동산정책과 관련된 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["분양가상한제와 택지소유상한제는 현재 시행되고 있다.","토지비축제도(토지은행)와 부동산가격공시제도는 정부가 간접적으로 부동산시장에 개입하는 수단이다.","법령상 개발부담금제가 재건축부담금제보다 먼저 도입되었다.","주택시장의 지표로서 PIR(Price to Income Ratio)은 개인의 주택지불능력을 나타내며, 그 값이 클수록 주택구매가 더 쉽다는 의미다.","부동산실명제의 근거 법률은 ｢부동산등기법｣이다."],"a":[3],"L":"학4-1","o":"기출","x":{"한줄":"개발부담금은 개발이익 환수에 관한 법률에 따라 먼저 도입됐고, 재건축부담금은 재건축초과이익 환수에 관한 법률에 따라 나중에 도입됐다.","근거":[{"법령":"개발이익 환수에 관한 법률","조문":"제2조제4호","원문":"4. \"개발부담금\"이란 개발이익 중 이 법에 따라 특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수 또는 구청장(구청장은 자치구의 구청장을 말하며, 이하 \"시장ㆍ군수ㆍ구청장\"이라 한다)이 부과ㆍ징수하는 금액을 말한다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제1조","원문":"이 법은 부동산에 관한 소유권과 그 밖의 물권을 실체적 권리관계와 일치하도록 실권리자 명의(名義)로 등기하게 함으로써 부동산등기제도를 악용한 투기ㆍ탈세ㆍ탈법행위 등 반사회적 행위를 방지하고 부동산 거래의 정상화와 부동산 가격의 안정을 도모하여 국민경제의 건전한 발전에 이바지함을 목적으로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"분양가상한제는 주택법 제57조에 따라 시행 중이나 택지소유상한제는 폐지되어 시행되지 않는다."},{"번호":2,"판정":"틀림","설명":"토지비축제도는 정부가 직접 토지를 매입·비축하는 직접개입 수단이다. 부동산가격공시제도는 정보 제공으로 시장 판단을 돕는 간접개입이다."},{"번호":3,"판정":"옳음","설명":"개발이익 환수에 관한 법률의 개발부담금이 먼저 시행됐고, 재건축부담금은 재건축초과이익 환수에 관한 법률로 뒤에 도입됐다."},{"번호":4,"판정":"틀림","설명":"PIR은 주택가격÷가구소득으로, 값이 클수록 소득에 비해 주택가격이 높아 구매가 어렵다."},{"번호":5,"판정":"틀림","설명":"부동산실명제의 근거 법률은 부동산 실권리자명의 등기에 관한 법률이다(제1조)."}],"개념":[{"종류":"표","제목":"정부의 시장개입 방식","머리":["구분","수단","내용"],"행":[["직접개입","토지은행(토지비축), 공영개발, 공공임대주택 공급","정부가 직접 매입·공급하는 방식"],["직접규제","토지거래허가제, 분양가상한제, 용도지역·지구제","행위나 가격을 법으로 제한"],["간접개입","금융지원, 세제 혜택·중과, 보조금, 부동산가격공시","유인이나 정보를 통해 민간 결정에 영향"],["환수·부담금","개발부담금, 재건축부담금","개발이익을 환수해 공익에 사용"]]},{"종류":"표","제목":"주택지불능력 지표","머리":["지표","산식","값이 클수록"],"행":[["PIR(소득 대비 주택가격 비율)","주택가격÷가구소득","구매 부담 증가, 주택구매 어려움"],["RIR(소득 대비 임대료 비율)","임대료÷가구소득","임차 부담 증가"],["의의","가구의 지불능력 측정","정책 대상 판단"]]}],"함정":"토지비축을 간접개입으로 분류한 문장에 속기 쉽다. 정부가 직접 사고 파는 방식이 직접개입이다. PIR은 값이 클수록 구매가 어려워진다는 점도 반대로 쓰기 쉽다. 폐지된 제도(택지소유상한제)는 현재 시행되지 않는다."}},{"i":"S5-1-1-학개론-17","r":"S5","g":1,"c":1,"n":17,"s":"학개론","q":"주택정책에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["주거급여처럼 임차인에게 임대료의 일부를 지원하는 정책은 소비자보조방식에 속한다.","임대료를 균형임대료보다 낮게 규제하면 초과수요가 발생하고 장기에는 임대주택 공급이 감소할 수 있다.","분양가상한제는 분양가격을 시장가격보다 낮게 묶어 당첨자에게 시세차익이 생길 수 있다.","임대료 상한을 균형임대료보다 높은 수준으로 정하면 초과수요가 발생한다.","공공임대주택 건설에 대한 보조금 지원은 공급자보조방식에 속한다."],"a":[4],"L":"학4-2","o":"변형","x":{"한줄":"임대료 상한이 균형임대료보다 높으면 시장 임대료가 상한에 걸리지 않으므로 규제 효과가 없고 초과수요도 생기지 않는다.","근거":[{"이론":"임대료 규제와 보조","내용":"임대료 상한이 균형임대료보다 낮을 때 초과수요가 생기고 장기에는 공급 감소·품질 저하가 나타난다. 균형임대료보다 높은 상한은 구속력이 없다. 임대료 보조는 소비자(수요자) 보조방식, 건설비 지원은 공급자 보조방식이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"주거급여는 임차료를 지원해 수요자의 지불능력을 높이는 소비자보조방식이다."},{"번호":2,"판정":"옳음","설명":"상한이 균형보다 낮으면 수요량이 공급량을 넘어 초과수요가 생기고 장기에는 임대주택 공급과 질이 줄 수 있다."},{"번호":3,"판정":"옳음","설명":"분양가를 시세보다 낮게 제한하면 당첨자가 시세차익을 얻을 수 있다."},{"번호":4,"판정":"틀림","설명":"균형임대료보다 높은 상한은 구속력이 없어 시장 임대료가 그대로 유지된다. 초과수요는 상한이 균형보다 낮을 때 생긴다."},{"번호":5,"판정":"옳음","설명":"건설비 지원처럼 공급자에게 주는 보조는 공급자보조방식이다."}],"개념":[{"종류":"표","제목":"임대료 상한 규제의 효과","머리":["상한 수준","시장 효과","장기 영향"],"행":[["균형임대료보다 낮음","초과수요 발생","공급 감소, 품질 저하, 암시장 가능"],["균형임대료와 같음","변화 없음","변화 없음"],["균형임대료보다 높음","구속력 없음","변화 없음"],["임대료 보조(수요자)","수요 증가, 임대료 상승 가능","공급이 비탄력적이면 임대료 상승 폭이 큼"]]},{"종류":"비교","제목":"소비자보조와 공급자보조","왼쪽":{"이름":"소비자(수요자) 보조","항목":["임차인에게 임대료 일부 지원","주거급여, 주택바우처","주거지 선택이 자유로움"]},"오른쪽":{"이름":"공급자 보조","항목":["공급자에게 건설비·금융 지원","공공임대주택 건설 지원","입주자의 주거지 선택 폭이 좁음"]}}],"함정":"임대료 규제는 상한이 균형보다 낮을 때만 효과가 있다. 상한이 균형보다 높은 경우를 초과수요로 연결한 문장에 속는다. 공공임대주택은 입주자가 주거지를 자유롭게 고르기 어렵다는 점이 단점이다."}},{"i":"S5-1-1-학개론-18","r":"S5","g":1,"c":1,"n":18,"s":"학개론","q":"공공주택 특별법령상 공공임대주택의 용어 정의로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["국민임대주택은 국가나 지방자치단체의 재정이나 주택도시기금의 자금을 지원받아 저소득 서민의 주거안정을 위하여 30년 이상 장기간 임대를 목적으로 공급하는 공공임대주택을 말한다.","행복주택은 국가나 지방자치단체의 재정이나 주택도시기금의 자금을 지원받아 대학생, 사회초년생, 신혼부부 등 젊은 층의 주거안정을 목적으로 공급하는 공공임대주택을 말한다.","통합공공임대주택은 국가나 지방자치단체의 재정이나 주택도시기금의 자금을 지원받아 최저소득 계층, 저소득 서민, 젊은 층 및 장애인ㆍ국가유공자 등 사회 취약계층 등의 주거안정을 목적으로 공급하는 공공임대주택을 말한다.","영구임대주택은 국가나 지방자치단체의 재정을 지원받아 최저소득 계층의 주거안정을 위하여 50년 이상 또는 영구적인 임대를 목적으로 공급하는 공공임대주택을 말한다.","기존주택등매입임대주택은 국가나 지방자치단체의 재정이나 주택도시기금의 자금을 지원받아 기존주택을 임차하여 「국민기초생활 보장법」에 따른 수급자 등 저소득층과 청년 및 신혼부부 등에게 전대(轉貸)하는 공공임대주택을 말한다."],"a":[5],"L":"학4-2","o":"변형","x":{"한줄":"기존주택을 임차해 전대하는 것은 기존주택전세임대주택이고, 기존주택등매입임대주택은 기존주택 등을 매입해 공급하는 유형이다.","근거":[{"법령":"공공주택 특별법 시행령","조문":"제2조제1항제6호·제7호","원문":"6. 기존주택등매입임대주택: 국가나 지방자치단체의 재정이나 주택도시기금의 자금을 지원받아 제37조제1항 각 호의 어느 하나에 해당하는 주택 또는 건축물(이하 \"기존주택등\"이라 한다)을 매입하여 「국민기초생활 보장법」에 따른 수급자 등 저소득층과 청년 및 신혼부부 등에게 공급하는 공공임대주택 7. 기존주택전세임대주택: 국가나 지방자치단체의 재정이나 주택도시기금의 자금을 지원받아 기존주택을 임차하여 「국민기초생활 보장법」에 따른 수급자 등 저소득층과 청년 및 신혼부부 등에게 전대(轉貸)하는 공공임대주택"},{"법령":"공공주택 특별법 시행령","조문":"제2조제1항제1호~제3호의2","원문":"1. 영구임대주택: 국가나 지방자치단체의 재정을 지원받아 최저소득 계층의 주거안정을 위하여 50년 이상 또는 영구적인 임대를 목적으로 공급하는 공공임대주택 2. 국민임대주택: 국가나 지방자치단체의 재정이나 「주택도시기금법」에 따른 주택도시기금(이하 \"주택도시기금\"이라 한다)의 자금을 지원받아 저소득 서민의 주거안정을 위하여 30년 이상 장기간 임대를 목적으로 공급하는 공공임대주택 3. 행복주택: 국가나 지방자치단체의 재정이나 주택도시기금의 자금을 지원받아 대학생, 사회초년생, 신혼부부 등 젊은 층의 주거안정을 목적으로 공급하는 공공임대주택 3의2. 통합공공임대주택: 국가나 지방자치단체의 재정이나 주택도시기금의 자금을 지원받아 최저소득 계층, 저소득 서민, 젊은 층 및 장애인ㆍ국가유공자 등 사회 취약계층 등의 주거안정을 목적으로 공급하는 공공임대주택"}],"선지":[{"번호":1,"판정":"옳음","설명":"국민임대주택은 저소득 서민을 위해 30년 이상 장기간 임대하는 유형이다(공공주택 특별법 시행령 제2조제1항제2호)."},{"번호":2,"판정":"옳음","설명":"행복주택은 대학생·사회초년생·신혼부부 등 젊은 층 대상이다(같은 항 제3호)."},{"번호":3,"판정":"옳음","설명":"통합공공임대주택은 최저소득 계층, 저소득 서민, 젊은 층, 장애인·국가유공자 등 취약계층을 아우른다(같은 항 제3의2호)."},{"번호":4,"판정":"옳음","설명":"영구임대주택은 최저소득 계층 대상, 50년 이상 또는 영구 임대다(같은 항 제1호)."},{"번호":5,"판정":"틀림","설명":"기존주택을 임차해 전대하는 유형은 기존주택전세임대주택이다(제7호). 기존주택등매입임대주택은 기존주택등을 매입해 공급하는 유형이다(제6호)."}],"개념":[{"종류":"표","제목":"공공임대주택의 유형(공공주택 특별법 시행령 제2조제1항)","머리":["유형","재원","대상·방식"],"행":[["영구임대주택","국가·지방자치단체 재정","최저소득 계층, 50년 이상 또는 영구 임대"],["국민임대주택","재정 또는 주택도시기금","저소득 서민, 30년 이상 장기 임대"],["행복주택","재정 또는 주택도시기금","대학생·사회초년생·신혼부부 등 젊은 층"],["통합공공임대주택","재정 또는 주택도시기금","최저소득 계층·저소득 서민·젊은 층·취약계층"],["장기전세주택","재정 또는 주택도시기금","전세계약 방식으로 공급"],["분양전환공공임대주택","-","일정 기간 임대 후 분양전환 목적"],["기존주택등매입임대주택","재정 또는 주택도시기금","기존주택등을 매입해 저소득층·청년·신혼부부 등에게 공급"],["기존주택전세임대주택","재정 또는 주택도시기금","기존주택을 임차해 저소득층·청년·신혼부부 등에게 전대"]]}],"함정":"매입임대와 전세임대의 동사(매입, 임차해 전대)를 맞바꾼 문장에 속는다. 영구임대만 재원에 주택도시기금이 빠지고 국가·지방자치단체의 재정만 쓴다."}},{"i":"S5-1-1-학개론-19","r":"S5","g":1,"c":1,"n":19,"s":"학개론","q":"우리나라의 부동산 조세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["종합부동산세는 국세로서 보유단계에 부과하는 조세이다.","양도소득세는 국세로서 처분(양도)단계에 부과하는 조세이다.","취득세는 지방세로서 취득단계에 부과하는 조세이다.","상속세는 국세로서 취득단계에 부과하는 조세이다.","등록면허세는 국세로서 취득단계에 부과하는 조세이다."],"a":[5],"L":"학4-3","o":"변형","x":{"한줄":"등록면허세는 국세가 아니라 지방세(도세·구세)이고, 취득단계에서 등기·등록 시 부과된다.","근거":[{"법령":"지방세기본법","조문":"제8조제2항·제3항","원문":"② 도세는 다음 각 호와 같다. 1. 보통세 가. 취득세 나. 등록면허세 다. 레저세 라. 지방소비세 2. 목적세 가. 지역자원시설세 나. 지방교육세 ③ 구세는 다음 각 호와 같다. 1. 등록면허세 2. 재산세"},{"법령":"국세기본법","조문":"제2조제1호","원문":"1. \"국세\"(國稅)란 국가가 부과하는 조세 중 다음 각 목의 것을 말한다. 가. 소득세 나. 법인세 다. 상속세와 증여세 라. 종합부동산세 마. 부가가치세 바. 개별소비세 사. 교통ㆍ에너지ㆍ환경세 아. 주세(酒稅) 자. 인지세(印紙稅) 차. 증권거래세 카. 교육세 타. 농어촌특별세"}],"선지":[{"번호":1,"판정":"옳음","설명":"종합부동산세는 국세이고(국세기본법 제2조제1호라목) 부동산 보유에 과세한다."},{"번호":2,"판정":"옳음","설명":"양도소득세는 소득세의 한 종류로 국세이며 부동산을 양도한 때 과세한다."},{"번호":3,"판정":"옳음","설명":"취득세는 지방세(지방세기본법 제8조)이고 취득 시 과세한다."},{"번호":4,"판정":"옳음","설명":"상속세는 국세(국세기본법 제2조제1호다목)이고 상속에 의한 무상 취득 시 과세한다."},{"번호":5,"판정":"틀림","설명":"등록면허세는 지방세다(지방세기본법 제8조제2항·제3항)."}],"개념":[{"종류":"표","제목":"부동산 관련 조세의 단계별 분류","머리":["단계","국세","지방세"],"행":[["취득","상속세·증여세, 인지세, 농어촌특별세","취득세, 등록면허세, 지방교육세"],["보유","종합부동산세","재산세, 지역자원시설세, 지방교육세"],["처분(양도)","양도소득세(소득세)","지방소득세(양도소득분)"],["법적 근거","국세기본법 제2조제1호","지방세기본법 제8조"]]},{"종류":"비교","제목":"거래세와 보유세의 효과","왼쪽":{"이름":"거래세(취득·양도 단계)","항목":["취득세 감면은 거래 활성화에 기여","양도소득세 중과는 매각을 미루는 동결효과(lock-in effect)","거래 비용이 늘어 거래량 감소"]},"오른쪽":{"이름":"보유세(보유 단계)","항목":["보유 비용이 늘어 매각 유인이 생길 수 있음","토지 공급이 비탄력적이면 토지분 보유세는 임차인에게 전가되기 어려움","재산세·종합부동산세"]}}],"함정":"등록면허세는 이름 때문에 국세로 오해하기 쉽다. 지방세기본법 제8조에 도세·구세로 열거돼 있다. 재산세는 보유단계, 취득세는 취득단계라는 단계 구분도 바꿔 쓴다."}},{"i":"S5-1-1-학개론-20","r":"S5","g":1,"c":1,"n":20,"s":"학개론","q":"부동산투자에 관한 설명으로 틀린 것은? (단, 주어진 조건에 한함)","b":null,"bs":"없음","img":[],"ch":["시중금리 상승은 부동산투자자의 요구수익률을 하락시키는 요인이다.","기대수익률은 투자로 인해 기대되는 예상수입과 예상지출로부터 계산되는 수익률이다.","정(+)의 레버리지효과는 자기자본수익률이 총자본수익률(종합수익률)보다 높을 때 발생한다.","요구수익률은 투자에 대한 위험이 주어졌을 때, 투자자가 대상부동산에 자금을 투자하기 위해 충족되어야 할 최소한의 수익률이다.","부동산투자자는 담보대출과 전세를 통해 레버리지를 활용할 수 있다."],"a":[1],"L":"학5-1","o":"기출","x":{"한줄":"시중금리가 오르면 무위험률이 올라 요구수익률도 상승한다.","근거":[{"이론":"요구수익률의 구성","내용":"요구수익률=무위험률+위험할증률+예상인플레이션율. 시중금리(무위험률) 상승, 위험 증가, 인플레이션 예상 상승은 모두 요구수익률을 높인다. 기대수익률이 요구수익률보다 크면 투자가 채택된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"시중금리 상승은 무위험률을 높여 요구수익률을 상승시킨다."},{"번호":2,"판정":"옳음","설명":"기대수익률은 예상수입과 예상지출로 계산하는 사전(事前) 수익률이다."},{"번호":3,"판정":"옳음","설명":"자기자본수익률이 총자본수익률보다 높으면 정(+)의 레버리지효과다."},{"번호":4,"판정":"옳음","설명":"요구수익률은 위험을 고려해 투자자가 최소한 얻어야 하는 수익률이다."},{"번호":5,"판정":"옳음","설명":"담보대출과 전세보증금은 타인자본이므로 레버리지로 활용할 수 있다."}],"개념":[{"종류":"표","제목":"투자 수익률의 종류","머리":["수익률","의미","시점"],"행":[["기대수익률","예상수입과 예상지출로 계산한 예상 수익률","사전"],["요구수익률","위험을 고려해 투자자가 최소한 요구하는 수익률(무위험률+위험할증률+예상인플레이션율)","사전"],["실현수익률","투자 후 실제로 달성한 수익률","사후"],["투자 결정","기대수익률 > 요구수익률이면 채택","-"]]},{"종류":"계산","제목":"레버리지효과 판정","단계":[{"설명":"총투자액 10억원, 대출 4억원(금리 4퍼센트), 총자본수익률 6퍼센트일 때 순영업소득","식":"10억원×6%","값":"0.6억원"},{"설명":"대출이자","식":"4억원×4%","값":"0.16억원"},{"설명":"자기자본 투자액과 세전현금수지","식":"(10-4)억원, 0.6-0.16","값":"6억원, 0.44억원"},{"설명":"자기자본수익률","식":"0.44÷6","값":"약 7.33%"},{"설명":"판정: 자기자본수익률 7.33% > 총자본수익률 6%","식":"대출금리 4% < 총자본수익률 6%","값":"정(+)의 레버리지"}]}],"함정":"시중금리와 요구수익률은 같은 방향으로 움직인다. 금리가 오르면 요구수익률도 오른다. 정(+)·부(-)의 레버리지는 대출금리와 총자본수익률의 크기 비교로 정해진다."}},{"i":"S5-1-1-학개론-21","r":"S5","g":1,"c":1,"n":21,"s":"학개론","q":"부동산투자의 지렛대효과(leverage effect)에 관한 설명으로 틀린 것은? (단, 세후기준이며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["총자본수익률이 저당수익률보다 높은 상태에서 부채비율을 높이면 자기자본수익률은 상승한다.","총자본수익률과 저당수익률이 같으면 부채비율을 바꾸어도 자기자본수익률은 변하지 않는다.","총자본수익률이 저당수익률보다 낮은 부(-)의 지렛대효과 상태에서는 부채비율을 낮추면 자기자본수익률이 하락한다.","부채비율이 높을수록 총자본수익률 변동에 따른 자기자본수익률의 변동폭이 커져 투자위험이 증가한다.","대출이자는 세금을 계산할 때 비용으로 공제되므로 부채의 이용은 세후 자기자본수익률을 높이는 요인이 된다."],"a":[3],"L":"학5-1","o":"변형","x":{"한줄":"부(-)의 지렛대효과에서는 부채가 늘수록 자기자본수익률이 떨어지므로, 부채비율을 낮추면 자기자본수익률은 오른다.","근거":[{"이론":"지렛대효과(레버리지)","내용":"자기자본수익률 = 총자본수익률 + (총자본수익률 − 저당수익률) × 부채비율(부채÷자기자본). 괄호 안이 양(+)이면 부채비율에 비례해 오르고, 0이면 불변, 음(−)이면 부채비율에 비례해 내린다."},{"이론":"세후 지렛대효과","내용":"대출이자는 비용으로 공제되어 과세소득을 줄이므로 세후기준에서 부채 이용은 절세효과를 낳는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"괄호 안 (총자본수익률 − 저당수익률)이 양(+)이므로 부채비율이 커질수록 자기자본수익률이 오른다."},{"번호":2,"판정":"옳음","설명":"괄호 안이 0이면 식의 둘째 항이 사라져 자기자본수익률은 총자본수익률과 같고 부채비율과 무관하다."},{"번호":3,"판정":"틀림","설명":"괄호 안이 음(−)이면 부채비율을 높일수록 자기자본수익률이 떨어지고, 반대로 부채비율을 낮추면 올라간다. 부채가 0이면 자기자본수익률은 총자본수익률과 같다."},{"번호":4,"판정":"옳음","설명":"부채비율이 클수록 총자본수익률이 1%p 움직일 때 자기자본수익률이 더 크게 움직인다. 정(+)의 지렛대에서 이익이 커지는 만큼 손실 위험도 커진다."},{"번호":5,"판정":"옳음","설명":"이자비용 공제로 세금이 줄어드는 만큼 세후 자기자본수익률이 높아진다. 도관체 활용과 함께 자기자본수익률 상승 전략으로 꼽힌다."}],"개념":[{"종류":"비교","제목":"지렛대효과 세 가지","머리":["구분","정(+)","중립","부(−)"],"행":[["조건","총자본수익률 > 저당수익률","총자본수익률 = 저당수익률","총자본수익률 < 저당수익률"],["부채비율을 높이면 자기자본수익률","오른다","그대로","떨어진다"],["부채비율을 낮추면 자기자본수익률","떨어진다","그대로","오른다"],["부채비율 0일 때 자기자본수익률","총자본수익률","총자본수익률","총자본수익률"]]},{"종류":"계산","제목":"자기자본수익률 계산 (자산 10억원, 부채 5억원, 자기자본 5억원)","단계":[{"설명":"공식","식":"자기자본수익률 = 총자본수익률 + (총자본수익률 − 저당수익률) × 부채비율","값":"부채비율 = 5억 ÷ 5억 = 100%"},{"설명":"정(+): 총자본수익률 8%, 저당수익률 5%","식":"8% + (8% − 5%) × 1.0","값":"11%"},{"설명":"중립: 총자본수익률 5%, 저당수익률 5%","식":"5% + (5% − 5%) × 1.0","값":"5%"},{"설명":"부(−): 총자본수익률 4%, 저당수익률 5%","식":"4% + (4% − 5%) × 1.0","값":"3%"},{"설명":"부(−)에서 부채비율을 0으로 낮추면","식":"4% + (4% − 5%) × 0","값":"4%"}]}],"함정":"①을 ‘부채는 늘리면 무조건 유리’로 외우면 ③의 방향을 거꾸로 읽는다. 부(−)에서는 부채를 줄여야 자기자본수익률이 오른다. ⑤는 세후기준이라는 단서 때문에 맞는 선지이므로 이자 공제를 부정하지 않는다."}},{"i":"S5-1-1-학개론-22","r":"S5","g":1,"c":1,"n":22,"s":"학개론","q":"부동산투자에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["투자자는 부동산의 자산가치와 운영수익의 극대화를 위해 효과적인 자산관리 운영전략을 수립할 필요가 있다.","금리상승은 투자자의 요구수익률을 상승시키는 요인이다.","동일 투자자산이라도 개별투자자가 위험을 기피할수록 요구수익률이 높아진다.","민감도분석을 통해 미래의 투자환경 변화에 따른 투자가치의 영향을 검토할 수 있다.","순현재가치는 투자자의 내부수익률로 할인한 현금유입의 현가에서 현금유출의 현가를 뺀 값이다."],"a":[5],"L":"학5-1","o":"기출","x":{"한줄":"순현재가치는 내부수익률이 아니라 투자자의 요구수익률로 할인한 현금유입의 현가에서 현금유출의 현가를 뺀 값이다.","근거":[{"이론":"순현재가치(NPV)와 내부수익률(IRR)","내용":"NPV = 현금유입의 현가(요구수익률로 할인) − 현금유출의 현가. IRR은 NPV를 0으로 만드는 할인율, 곧 유입의 현가와 유출의 현가를 같게 하는 수익률이다."},{"이론":"요구수익률","내용":"요구수익률 = 무위험률 + 위험할증률 + 예상 인플레이션율. 시장금리가 오르거나 투자자가 위험을 더 싫어하면 오른다."}],"선지":[{"번호":1,"판정":"옳음","설명":"자산가치 극대화와 운영수익 극대화는 자산관리의 목적이다. 투자 후 관리 단계에서 운영전략을 세운다."},{"번호":2,"판정":"옳음","설명":"금리가 오르면 무위험률이 올라 요구수익률의 기본 수준이 높아진다."},{"번호":3,"판정":"옳음","설명":"위험기피도가 클수록 위험할증률이 커져 같은 자산에도 더 높은 수익률을 요구한다."},{"번호":4,"판정":"옳음","설명":"민감도분석은 수익, 비용, 공실률 같은 투입변수가 변할 때 순현재가치·내부수익률 등 결과가 얼마나 달라지는지 본다."},{"번호":5,"판정":"틀림","설명":"NPV를 구하는 할인율은 요구수익률이다. 내부수익률은 NPV를 0으로 만드는 값으로 NPV 계산의 입력값이 아니다."}],"개념":[{"종류":"표","제목":"수익률 세 가지","머리":["구분","뜻","시점·쓰임"],"행":[["기대수익률","투자로 얻을 것으로 예상하는 수익률","투자 전, 요구수익률과 비교해 투자 여부를 정한다"],["요구수익률","투자자가 최소한 얻어야 한다고 보는 수익률 (무위험률 + 위험할증률 + 예상 인플레이션율)","투자 전, NPV의 할인율·투자 기준선"],["실현수익률","투자를 끝내고 실제로 얻은 수익률","투자 후, 사후 성과"],["투자 결정","기대수익률 > 요구수익률이면 채택, 기대수익률 < 요구수익률이면 기각","위험이 클수록 요구수익률이 높아진다"]]},{"종류":"표","제목":"요구수익률을 움직이는 요인","머리":["요인","변화","요구수익률"],"행":[["시장금리(무위험률)","상승","상승"],["투자자의 위험기피도","커짐","상승"],["투자자산의 위험","커짐","상승"],["예상 인플레이션율","상승","상승"],["위험 선호(위험 감수 성향)","커짐","하락"]]}],"함정":"⑤는 ‘내부수익률’이라는 낱말이 투자분석 문맥에서 자연스러워 맞는 문장처럼 읽힌다. 할인율은 요구수익률이고 내부수익률은 계산으로 구하는 결과값이다."}},{"i":"S5-1-1-학개론-23","r":"S5","g":1,"c":1,"n":23,"s":"학개론","q":"부채감당률(debt coverage ratio)에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["부채감당률은 순영업소득을 부채서비스액으로 나눈 비율이며, 1보다 작으면 순영업소득으로 부채서비스액을 감당하지 못한다.","부채서비스액은 대출의 원금상환액과 이자지급액을 합한 금액이다.","부채감당률이 1.5, 대부비율이 60%, 연간 저당상수가 0.1이라면 (종합)자본환원율은 9%이다.","순영업소득이 일정할 때 대출금리 상승으로 부채서비스액이 증가하면 부채감당률은 높아진다.","부채감당률이 1이면 순영업소득과 부채서비스액이 같아 세전현금수지는 0이 된다."],"a":[4],"L":"학5-3","o":"변형","x":{"한줄":"부채감당률 = 순영업소득 ÷ 부채서비스액이므로 분자가 일정할 때 분모인 부채서비스액이 늘면 부채감당률은 낮아진다.","근거":[{"이론":"부채감당률(DCR)","내용":"DCR = 순영업소득(NOI) ÷ 부채서비스액. 부채서비스액 = 원금상환액 + 이자지급액 = 대출액 × 저당상수."},{"이론":"종합자본환원율","내용":"종합환원율 = 부채감당률 × 대부비율(LTV) × 저당상수 (= NOI ÷ 부동산가치)."}],"선지":[{"번호":1,"판정":"옳음","설명":"DCR 정의 그대로다. 1 미만이면 NOI가 원리금에 못 미치고, 대출기관은 DCR이 클수록 안전하다고 본다."},{"번호":2,"판정":"옳음","설명":"부채서비스액에는 이자와 원금이 모두 들어간다. 이자만 또는 원금만을 뜻하지 않는다."},{"번호":3,"판정":"옳음","설명":"1.5 × 0.6 × 0.1 = 0.09, 곧 9%다."},{"번호":4,"판정":"틀림","설명":"NOI가 일정하고 부채서비스액이 증가하면 DCR은 낮아진다. 금리가 올라 원리금이 늘면 대출기관이 보는 안전도는 떨어진다."},{"번호":5,"판정":"옳음","설명":"세전현금수지 = 순영업소득 − 부채서비스액이다. DCR이 1이면 두 값이 같아 0이다."}],"개념":[{"종류":"계산","제목":"부채감당률과 종합환원율 (부동산가치 10억원, 대부비율 60%, 저당상수 0.1, 부채감당률 1.5)","단계":[{"설명":"대출액","식":"10억원 × 60%","값":"6억원"},{"설명":"부채서비스액","식":"6억원 × 0.1","값":"6,000만원"},{"설명":"순영업소득","식":"6,000만원 × 1.5","값":"9,000만원"},{"설명":"종합환원율","식":"9,000만원 ÷ 10억원","값":"9%"},{"설명":"공식 확인","식":"1.5 × 0.6 × 0.1","값":"0.09 = 9%"}]},{"종류":"표","제목":"대출·부채 관련 비율","머리":["비율","산식","클수록"],"행":[["대부비율(LTV)","대출액 ÷ 부동산가치","대출기관 위험 증가"],["부채감당률(DCR)","순영업소득 ÷ 부채서비스액","대출기관 안전도 증가"],["부채비율","타인자본(부채) ÷ 자기자본","재무 위험 증가"],["채무불이행률","(영업경비 + 부채서비스액) ÷ 유효총소득","손익분기 가까워져 위험 증가"],["총부채상환비율(DTI)","연간 원리금 상환액 ÷ 연소득","차입자 상환부담 증가"]]}],"함정":"‘금리가 오르면 부채서비스액이 늘어 DCR이 올라간다’는 식으로 부채서비스액을 분자로 착각하면 ④를 맞는 문장으로 읽는다. 분자는 순영업소득, 분모가 부채서비스액이다."}},{"i":"S5-1-1-학개론-24","r":"S5","g":1,"c":1,"n":24,"s":"학개론","q":"자본환원율에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["자본환원율은 시장추출법, 조성법, 투자결합법 등을 통해 구할 수 있다.","자본환원율은 자본의 기회비용을 반영하며, 금리의 상승은 자본환원율을 높이는 요인이 된다.","순영업소득(NOI)이 일정할 때 투자수요의 증가로 인한 자산가격 상승은 자본환원율을 높이는 요인이 된다.","투자위험의 감소는 자본환원율을 낮추는 요인이 된다.","부동산시장이 균형을 이루더라도 자산의 유형, 위치 등 특성에 따라 자본환원율이 서로 다른 부동산들이 존재할 수 있다."],"a":[3],"L":"학5-3","o":"기출","x":{"한줄":"자본환원율 = 순영업소득 ÷ 자산가격이므로, 순영업소득이 일정한데 자산가격이 오르면 자본환원율은 낮아진다.","근거":[{"이론":"자본환원율","내용":"자본환원율(R) = 순영업소득(NOI) ÷ 부동산가격(V). 부동산가격 = NOI ÷ R. 자본의 기회비용과 투자위험을 반영한다."},{"이론":"자본환원율 산정방법","내용":"시장추출법(유사 거래사례에서 추출), 조성법(무위험률 + 위험할증률 ± 비유동성·관리 난이도·금융 상 이점), 투자결합법(물리적 결합·금융적 결합), 부채감당법, 엘우드법."}],"선지":[{"번호":1,"판정":"옳음","설명":"자본환원율을 구하는 대표 방법이다. 시장추출법은 시장자료에서 직접 뽑는다."},{"번호":2,"판정":"옳음","설명":"금리가 오르면 자본의 기회비용이 커져 자본환원율이 높아진다."},{"번호":3,"판정":"틀림","설명":"NOI가 일정할 때 가격이 오르면 R = NOI ÷ V가 작아진다. 투자수요 증가·가격 상승은 자본환원율을 낮추는 요인이다."},{"번호":4,"판정":"옳음","설명":"위험할증률이 줄어 자본환원율이 낮아진다."},{"번호":5,"판정":"옳음","설명":"시장이 균형이어도 유형·위치별 위험과 성장 전망이 달라 자본환원율은 부동산마다 다를 수 있다."}],"개념":[{"종류":"표","제목":"자본환원율을 움직이는 요인 (NOI 일정 가정)","머리":["요인","변화","자본환원율","부동산가격"],"행":[["시장금리·기회비용","상승","상승","하락"],["투자위험(위험할증률)","감소","하락","상승"],["투자수요","증가 (가격 상승)","하락","상승"],["순영업소득 성장 기대","커짐","하락","상승"],["부동산 유동성","높음","하락","상승"]]},{"종류":"표","제목":"자본환원율 산정방법","머리":["방법","내용"],"행":[["시장추출법","시장에서 거래된 유사 부동산의 NOI와 가격으로 R을 추출"],["조성법","무위험률 + 위험할증률(+ 비유동성·관리 난이도·금융 상 이점 가감)"],["투자결합법(물리적)","토지환원율과 건물환원율을 가격 구성비로 가중평균"],["투자결합법(금융적)","저당환원율과 지분환원율을 대출·자기자본 구성비로 가중평균"],["부채감당법","R = 부채감당률 × 대부비율 × 저당상수"]]}],"함정":"‘수요가 늘면 좋은 것이니 환원율도 오른다’는 식의 직관이 ③을 맞는 문장으로 읽게 만든다. 환원율은 수익률이므로 가격이 오르면 내려간다."}},{"i":"S5-1-1-학개론-25","r":"S5","g":1,"c":1,"n":25,"s":"학개론","q":"부동산투자분석기법에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["동일한 현금흐름의 투자안이라도 요구수익률이 높아지면 순현재가치는 작아진다.","순현재가치법은 현금흐름을 내부수익률로 재투자한다고 가정하고, 내부수익률법은 요구수익률로 재투자한다고 가정한다.","순현재가치법에는 가치가산원리가 적용되지만 내부수익률법에는 적용되지 않는다.","상호 배타적인 투자안을 비교할 때 순현재가치법과 내부수익률법의 결론이 달라질 수 있다.","단순회수기간법은 회수기간 이후의 현금흐름과 화폐의 시간가치를 고려하지 않는다."],"a":[2],"L":"학5-3","o":"변형","x":{"한줄":"재투자율 가정은 반대다. 순현재가치법은 요구수익률로, 내부수익률법은 내부수익률로 재투자한다고 가정한다.","근거":[{"이론":"순현재가치법과 내부수익률법의 비교","내용":"NPV법: 재투자율 = 요구수익률, 가치가산원리 적용, 투자안 선택은 NPV > 0. IRR법: 재투자율 = 내부수익률, 가치가산원리 미적용, IRR > 요구수익률이면 채택. 서로 배타적인 투자안에서는 결론이 다를 수 있고 이때는 NPV법을 따른다."},{"이론":"회수기간법","내용":"투자액을 회수하는 데 걸리는 기간이 짧은 안을 택한다. 단순회수기간법은 회수 이후 현금흐름과 시간가치를 무시한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"NPV의 할인율이 요구수익률이므로 요구수익률이 오르면 현가가 줄어 NPV가 작아진다."},{"번호":2,"판정":"틀림","설명":"NPV법은 요구수익률, IRR법은 내부수익률로 재투자한다고 가정한다. 요구수익률이 시장에서 실제 얻을 수 있는 수익률에 가까워 NPV법의 가정이 더 현실적이다."},{"번호":3,"판정":"옳음","설명":"NPV는 개별 투자안 NPV를 더하면 합산 NPV와 같다. IRR은 더해도 합산 IRR이 되지 않는다."},{"번호":4,"판정":"옳음","설명":"투자규모나 현금흐름 시기가 다른 배타적 투자안에서는 IRR이 큰 안의 NPV가 작을 수 있다. 이때는 NPV법으로 선택한다."},{"번호":5,"판정":"옳음","설명":"단순회수기간법은 시간가치를 반영하지 않는다. 할인회수기간법은 현가로 바꾸어 계산하나 회수 이후 현금흐름은 여전히 무시한다."}],"개념":[{"종류":"계산","제목":"NPV·IRR·수익성지수 (투자액 1,000만원, 1년 말 550만원, 2년 말 605만원, 요구수익률 10%)","단계":[{"설명":"1년 말 현금유입의 현가","식":"550 ÷ 1.1","값":"500만원"},{"설명":"2년 말 현금유입의 현가","식":"605 ÷ 1.1²","값":"500만원"},{"설명":"현금유입의 현가 합계","식":"500 + 500","값":"1,000만원"},{"설명":"순현재가치","식":"1,000 − 1,000","값":"0"},{"설명":"수익성지수","식":"1,000 ÷ 1,000","값":"1.0"},{"설명":"내부수익률","식":"NPV = 0이 되는 할인율","값":"10%"}]},{"종류":"비교","제목":"순현재가치법 vs 내부수익률법","왼쪽":{"이름":"순현재가치법(NPV)","항목":["할인율은 요구수익률","재투자율은 요구수익률","가치가산원리 적용","NPV > 0이면 채택","배타적 투자안 선택에서 우선"]},"오른쪽":{"이름":"내부수익률법(IRR)","항목":["NPV를 0으로 만드는 할인율","재투자율은 내부수익률","가치가산원리 미적용","IRR > 요구수익률이면 채택","현금흐름 부호가 여러 번 바뀌면 IRR이 복수로 나올 수 있다"]}}],"함정":"두 방법의 재투자 가정을 앞뒤로 바꾸어 놓은 문장이다. ‘내부수익률법이 더 합리적’이라는 기억에 끌리면 ②를 맞는 문장으로 읽는다. 재투자율은 NPV법이 요구수익률, IRR법이 내부수익률이다."}},{"i":"S5-1-1-학개론-26","r":"S5","g":1,"c":1,"n":26,"s":"학개론","q":"A는 주택을 구입하기 위해 은행에서 3억원을 연 4% 고정금리로 대출받았다. 상환기간은 10년이고 매년 말 원금균등분할상환 방식으로 갚는다. 5회차(5년 차 말)에 상환할 원리금은? (단, 주어진 조건에 한하며, 중도상환은 없음)","b":null,"bs":"없음","img":[],"ch":["3,720만원","3,840만원","3,960만원","4,080만원","4,200만원"],"a":[1],"L":"학6-1","o":"신작","x":{"한줄":"원금은 매년 3,000만원씩 갚고, 5회차 이자는 4회차까지 갚고 남은 1억 8,000만원에 4%를 곱한 720만원이므로 원리금은 3,720만원이다.","근거":[{"이론":"원금균등분할상환","내용":"매기 상환원금 = 대출원금 ÷ 상환기간. 매기 이자 = 기초 대출잔액 × 이자율. 이자가 매기 줄어 원리금도 일정액씩 줄어든다."}],"선지":[{"번호":1,"판정":"-","설명":"3,000만원 + (3억원 − 3,000만원×4) × 4% = 3,000만원 + 720만원 = 3,720만원. 정답이다."},{"번호":2,"판정":"-","설명":"4회차 원리금이다. 이자 840만원(기초잔액 2억 1,000만원)을 쓴 값이다."},{"번호":3,"판정":"-","설명":"3회차 원리금이다. 이자 960만원(기초잔액 2억 4,000만원)을 쓴 값이다."},{"번호":4,"판정":"-","설명":"2회차 원리금이다. 이자 1,080만원(기초잔액 2억 7,000만원)을 쓴 값이다."},{"번호":5,"판정":"-","설명":"1회차 원리금이다. 이자 1,200만원(기초잔액 3억원)을 쓴 값이다."}],"개념":[{"종류":"계산","제목":"원금균등분할상환 5회차 원리금 (대출 3억원, 연 4%, 10년)","단계":[{"설명":"매기 상환원금","식":"3억원 ÷ 10년","값":"3,000만원"},{"설명":"5회차 기초 잔액 (4회차까지 상환한 원금 1억 2,000만원 차감)","식":"3억원 − 3,000만원 × 4","값":"1억 8,000만원"},{"설명":"5회차 이자","식":"1억 8,000만원 × 4%","값":"720만원"},{"설명":"5회차 원리금","식":"3,000만원 + 720만원","값":"3,720만원"},{"설명":"검산: 매회 이자는 3,000만원 × 4% = 120만원씩 감소","식":"4,200 → 4,080 → 3,960 → 3,840 → 3,720","값":"5회차 3,720만원"}]},{"종류":"비교","제목":"대출 상환방식","머리":["구분","원금균등","원리금균등","체증식","만기일시"],"행":[["매기 원리금","점점 줄어듦","매기 같음","점점 늘어남","이자만 내다 만기에 원금 전부"],["매기 원금","매기 같음","점점 늘어남","초기엔 잔액이 늘 수도 있음(부의 상환)","만기에 한꺼번에"],["1회차 원리금","가장 큼","중간","가장 작음","이자만"],["총이자","가장 적음","원금균등보다 많음","원리금균등보다 많음","원금이 끝까지 그대로라 가장 많음"],["특징","원금 회수 빨라 은행의 원금회수 위험이 가장 낮다","초기 소득이 낮은 차주에 유리(원금균등 대비)","미래 소득이 늘 젊은 층에 적합, 대출 시점 DTI 가장 작음","은행의 이자수입이 크다"]]}],"함정":"1~4회차 값이 선지에 하나씩 들어 있다. 회차를 한 칸 틀리게 세면 바로 옆 선지가 나온다. 5회차 이자는 4회차까지 갚은 뒤의 잔액에 곱한다."}},{"i":"S5-1-1-학개론-27","r":"S5","g":1,"c":1,"n":27,"s":"학개론","q":"A가 시가 5억원인 주택을 담보로 대출을 받으려 한다. 다음 조건에서 A가 받을 수 있는 최대 대출금액은? (단, 주어진 조건에 한함)\n· 담보인정비율(LTV): 60%\n· A의 연소득: 6,000만원\n· 총부채상환비율(DTI): 40%\n· 대출은 연 1회 원리금균등상환이며, 저당상수는 0.1\n· A의 다른 부채는 없음","b":null,"bs":"없음","img":[],"ch":["2억원","2억 4,000만원","3억원","3억 6,000만원","6억원"],"a":[2],"L":"학6-1","o":"신작","x":{"한줄":"LTV로는 3억원, DTI로는 2억 4,000만원까지 가능하고 두 기준을 모두 충족해야 하므로 최대 대출금액은 2억 4,000만원이다.","근거":[{"이론":"LTV·DTI","내용":"LTV = 대출액 ÷ 담보가치, DTI = 연간 원리금 상환액 ÷ 연소득. 두 규제를 모두 충족하는 한도 중 작은 금액이 최대 대출액이다. 연 원리금 = 대출액 × 저당상수."}],"선지":[{"번호":1,"판정":"-","설명":"5억원에 DTI 40%를 곱한 값이다. LTV 자리에 DTI를 넣은 오류다."},{"번호":2,"판정":"-","설명":"연소득 6,000만원 × 40% = 2,400만원(연 원리금 한도) ÷ 0.1 = 2억 4,000만원. LTV 한도 3억원보다 작아 이 값이 최대액이다. 정답이다."},{"번호":3,"판정":"-","설명":"LTV 한도(5억원 × 60%)만 적용한 값이다. DTI 한도를 넘는다."},{"번호":4,"판정":"-","설명":"연소득에 LTV 60%를 곱한 3,600만원을 저당상수 0.1로 나눈 값이다. DTI 자리에 LTV를 넣은 오류다."},{"번호":5,"판정":"-","설명":"연소득 전액을 원리금으로 쓴다고 보고(6,000만원 ÷ 0.1) 구한 값이다. DTI 40%를 적용하지 않았다."}],"개념":[{"종류":"계산","제목":"LTV·DTI 동시 적용 최대 대출액","단계":[{"설명":"LTV 기준 한도","식":"5억원 × 60%","값":"3억원"},{"설명":"DTI 기준 연 원리금 한도","식":"6,000만원 × 40%","값":"2,400만원"},{"설명":"DTI 기준 대출 한도 (연 원리금 = 대출액 × 저당상수)","식":"2,400만원 ÷ 0.1","값":"2억 4,000만원"},{"설명":"최대 대출금액 (둘 중 작은 값)","식":"min(3억원, 2억 4,000만원)","값":"2억 4,000만원"}]},{"종류":"비교","제목":"LTV · DTI · DSR","왼쪽":{"이름":"LTV (담보 기준)","항목":["대출액 ÷ 담보가치","높이면 대출 가능액 증가, 차주 자기자본 비율 감소","경기 과열기에 낮추고 침체기에 높인다"]},"오른쪽":{"이름":"DTI · DSR (소득 기준)","항목":["DTI: 해당 주택담보대출 원리금 ÷ 연소득","DSR: 모든 대출의 원리금 ÷ 연소득","차주의 상환능력을 본다","DSR이 DTI보다 대출 범위가 넓다"]}}],"함정":"LTV와 DTI 중 하나만 계산하고 끝내는 것이 가장 흔한 실수다. 두 선지(3억원, 6억원)가 한쪽 기준만 쓴 값이다. 비율 값 40%와 60%를 서로 바꿔 대입한 값도 선지에 들어 있다."}},{"i":"S5-1-1-학개론-28","r":"S5","g":1,"c":1,"n":28,"s":"학개론","q":"주택금융에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["정부는 주택소비금융의 확대와 금리인하, 대출규제의 완화로 주택가격의 급격한 상승에 대처한다.","주택소비금융은 주택구입능력을 제고시켜 자가주택 소유를 촉진시킬 수 있다.","주택자금대출의 확대는 주택거래를 활성화 시킬 수 있다.","주택금융은 주택과 같은 거주용 부동산을 매입 또는 임대하는데 필요한 자금조달을 위한 금융상품을 포괄한다.","주택도시기금은 국민주택의 건설이나 국민주택규모 이하의 주택 구입에 출자 또는 융자할 수 있다."],"a":[1],"L":"학6-2","o":"기출","x":{"한줄":"주택가격이 급등할 때는 대출을 죄고 금리를 올리는 방향으로 대응한다. 소비금융 확대, 금리인하, 대출규제 완화는 수요를 더 키운다.","근거":[{"법령":"주택도시기금법","조문":"제9조제1항제1호","원문":"기금의 주택계정은 다음 각 호의 용도에 사용한다. 1. 다음 각 목에 대한 출자 또는 융자 가. 국민주택의 건설 나. 국민주택규모 이하의 주택의 구입ㆍ임차 또는 개량"},{"이론":"주택금융의 경기조절 기능","내용":"과열기에는 금리 인상, LTV·DTI 하향, 대출규제 강화로 수요를 억제하고, 침체기에는 반대로 금리 인하, LTV·DTI 상향, 상환기간 연장으로 수요를 늘린다."}],"선지":[{"번호":1,"판정":"틀림","설명":"가격 급등기에는 소비금융 축소, 금리 인상, 대출규제 강화로 수요를 억제한다. 지문의 세 수단은 침체기 처방이다."},{"번호":2,"판정":"옳음","설명":"주택구입 자금을 빌려 줄수록 구입능력이 커져 자가소유가 늘 수 있다."},{"번호":3,"판정":"옳음","설명":"대출이 늘면 매수 여력이 커져 거래가 활발해진다."},{"번호":4,"판정":"옳음","설명":"주택금융은 거주용 부동산의 구입·임차에 필요한 자금조달 금융상품을 포괄하는 개념이다."},{"번호":5,"판정":"옳음","설명":"주택도시기금 주택계정은 국민주택의 건설, 국민주택규모 이하 주택의 구입·임차·개량에 출자 또는 융자한다(주택도시기금법 제9조제1항제1호가목·나목)."}],"개념":[{"종류":"표","제목":"경기 국면별 주택금융 정책수단","머리":["수단","과열기(가격 급등)","침체기"],"행":[["금리","인상","인하"],["LTV·DTI","하향","상향"],["대출규제","강화","완화"],["상환기간","단축","연장"],["주택거래·가격에 미치는 효과","수요 억제","수요 확대"]]},{"종류":"표","제목":"주택도시기금 주택계정의 출자·융자 대상 (주택도시기금법 제9조제1항제1호)","머리":["목","대상"],"행":[["가","국민주택의 건설"],["나","국민주택규모 이하 주택의 구입·임차·개량"],["다","준주택의 건설"],["라","준주택의 구입·임차·개량"],["마","국민주택규모 이하 주택의 리모델링"],["바","국민주택 건설을 위한 대지조성사업"]]}],"함정":"‘주택금융 확대 = 좋은 것’이라는 인상으로 ①을 고르지 못한다. 가격 급등과 대출 확대는 같이 움직이므로 대응 방향은 반대다."}},{"i":"S5-1-1-학개론-29","r":"S5","g":1,"c":1,"n":29,"s":"학개론","q":"부동산투자회사법상 부동산투자회사(REITs)에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["자기관리 부동산투자회사는 자산운용 전문인력을 포함한 임직원을 상근으로 두고 자산의 투자·운용을 직접 수행한다.","위탁관리 부동산투자회사는 본점 외의 지점을 설치할 수 없으며, 직원을 고용하거나 상근 임원을 둘 수 없다.","위탁관리 부동산투자회사는 자산의 투자·운용업무뿐 아니라 주식발행업무와 일반적인 사무도 자산관리회사에 위탁하여야 한다.","부동산투자회사는 최저자본금준비기간이 끝난 후 매 분기 말 현재 총자산의 100분의 80 이상을 부동산, 부동산 관련 증권 및 현금으로 구성하여야 하며, 이 경우 총자산의 100분의 70 이상은 부동산이어야 한다.","자기관리 부동산투자회사와 자산관리회사는 임직원이 따라야 할 내부통제기준을 제정하여 시행하여야 한다."],"a":[3],"L":"학6-3","o":"변형","x":{"한줄":"위탁관리 부동산투자회사가 자산관리회사에 맡기는 것은 자산의 투자·운용업무이고, 주식발행업무와 일반 사무는 일반사무등 위탁기관에 맡긴다.","근거":[{"법령":"부동산투자회사법","조문":"제22조의2제1항","원문":"위탁관리 부동산투자회사는 자산의 투자ㆍ운용업무는 자산관리회사에 위탁하여야 하고, 주식발행업무 및 일반적인 사무는 대통령령으로 정하는 요건을 갖춘 기관(이하 \"일반사무등 위탁기관\"이라 한다)에 위탁하여야 한다."},{"법령":"부동산투자회사법","조문":"제11조의2","원문":"위탁관리 부동산투자회사는 본점 외의 지점을 설치할 수 없으며, 직원을 고용하거나 상근 임원을 둘 수 없다."},{"법령":"부동산투자회사법","조문":"제25조제1항","원문":"부동산투자회사는 최저자본금준비기간이 끝난 후에는 매 분기 말 현재 총자산의 100분의 80 이상을 부동산, 부동산 관련 증권 및 현금으로 구성하여야 한다. 이 경우 총자산의 100분의 70 이상은 부동산(건축 중인 건축물을 포함한다)이어야 한다."},{"법령":"부동산투자회사법","조문":"제47조제1항","원문":"자기관리 부동산투자회사 및 자산관리회사는 법령을 준수하고 자산운용을 건전하게 하며 주주를 보호하기 위하여 임직원이 따라야 할 기본적인 절차와 기준(이하 \"내부통제기준\"이라 한다)을 제정하여 시행하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"자기관리 부동산투자회사의 정의다(제2조제1호가목). 자산운용 전문인력도 상근으로 둔다(제22조제1항)."},{"번호":2,"판정":"옳음","설명":"위탁관리 부동산투자회사는 서류상 회사에 가까워 지점·직원·상근 임원이 없다(제11조의2)."},{"번호":3,"판정":"틀림","설명":"자산관리회사에는 투자·운용업무만 위탁하고, 주식발행업무와 일반 사무는 일반사무등 위탁기관에 위탁한다(제22조의2제1항)."},{"번호":4,"판정":"옳음","설명":"분기 말 기준 80% 이상(부동산·부동산 관련 증권·현금), 그중 70% 이상 부동산이다(제25조제1항)."},{"번호":5,"판정":"옳음","설명":"내부통제기준 제정·시행 의무자는 자기관리 부동산투자회사와 자산관리회사다(제47조제1항). 위탁관리 부동산투자회사에는 직원이 없어 이 의무가 없다."}],"개념":[{"종류":"표","제목":"부동산투자회사 세 종류","머리":["구분","자기관리","위탁관리","기업구조조정"],"행":[["자산 투자·운용","직접 수행","자산관리회사에 위탁","자산관리회사에 위탁"],["임직원","전문인력 포함 상근","직원 고용·상근 임원 불가","직원 고용·상근 임원 불가 (제11조의2 준용)"],["설립 자본금","5억원 이상","3억원 이상","3억원 이상"],["최저자본금 (인가·등록 후 6개월)","70억원","50억원","50억원"],["내부통제기준·준법감시인","제정·상근 준법감시인","해당 없음 (자산관리회사가 제정)","해당 없음 (자산관리회사가 제정)"],["배당","이익배당한도의 50% 이상 (이익준비금 적립 가능)","90% 이상, 초과배당 가능","90% 이상, 초과배당 가능"],["투자 대상","제21조제1항의 부동산·부동산개발사업·증권 등","제21조제1항의 부동산·부동산개발사업·증권 등","구조조정 관련 부동산이 총자산의 70% 이상 (제49조의2제1항)"]]},{"종류":"표","제목":"위탁관리 부동산투자회사 규제 모음","머리":["항목","내용","조문"],"행":[["지점·인력","본점 외 지점 설치 불가, 직원 고용·상근 임원 불가","제11조의2"],["업무 위탁","투자·운용은 자산관리회사, 주식발행·일반사무는 일반사무등 위탁기관","제22조의2제1항"],["자산관리회사와의 거래","해당 회사와 자산관리회사 및 특별관계자는 부동산·증권 거래 금지 (예외 있음)","제22조의2제3항"],["자산관리회사의 주식 취득","발행주식 총수의 100분의 30 이내에서 대통령령으로 정하는 비율 초과 취득·최대주주 불가","제22조의4제1항"],["초과배당","해당 연도 감가상각비 범위에서 가능","제28조제3항"]]}],"함정":"‘위탁관리 = 모든 일을 맡긴다’고 단순화하면 ③을 맞는 문장으로 읽는다. 자산관리회사에 맡기는 것은 투자·운용업무뿐이다. 내부통제기준 의무가 위탁관리 부동산투자회사 본체에는 없다는 점도 ⑤에서 같이 묻는다."}},{"i":"S5-1-1-학개론-30","r":"S5","g":1,"c":1,"n":30,"s":"학개론","q":"부동산투자회사법상 부동산투자회사(REITs)에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["영업인가를 받거나 등록을 한 날부터 6개월이 지난 자기관리 부동산투자회사의 자본금은 70억원 이상이어야 한다.","위탁관리 부동산투자회사와 기업구조조정 부동산투자회사는 영업인가를 받거나 등록을 한 날부터 6개월이 지나면 자본금이 50억원 이상이어야 한다.","부동산 관련 분야의 석사학위 이상 소지자로서 부동산의 투자·운용과 관련된 업무에 3년 이상 종사한 사람은 자기관리 부동산투자회사의 자산운용 전문인력이 될 수 있다.","부동산투자회사는 영업인가를 받거나 등록을 하고 최저자본금 이상을 갖추기 전에도 현물출자를 받는 방식으로 신주를 발행할 수 있다.","부동산투자회사의 자금차입 및 사채발행은 자기자본의 2배를 초과할 수 없으나, 주주총회의 특별결의를 거치면 자기자본의 10배를 넘지 않는 범위에서 할 수 있다."],"a":[4],"L":"학6-3","o":"변형","x":{"한줄":"현물출자를 받는 신주발행은 영업인가·등록을 하고 최저자본금 이상을 갖춘 뒤에만 할 수 있다.","근거":[{"법령":"부동산투자회사법","조문":"제19조제1항","원문":"부동산투자회사는 영업인가를 받거나 등록을 하고 제10조에 따른 최저자본금 이상을 갖추기 전에는 현물출자를 받는 방식으로 신주를 발행할 수 없다."},{"법령":"부동산투자회사법","조문":"제10조","원문":"영업인가를 받거나 등록을 한 날부터 6개월(부동산투자회사 및 이해관계자 등이 다른 법령에서 정한 방법 및 절차 등을 이행하기 위하여 소요되는 기간으로서 국토교통부장관이 인정하는 기간은 제외한다. 이하 \"최저자본금준비기간\"이라 한다)이 지난 부동산투자회사의 자본금은 다음 각 호에서 정한 금액 이상이 되어야 한다. 1. 자기관리 부동산투자회사: 70억원 2. 위탁관리 부동산투자회사 및 기업구조조정 부동산투자회사: 50억원"},{"법령":"부동산투자회사법","조문":"제22조제1항제2호","원문":"부동산 관련 분야의 석사학위 이상의 소지자로서 부동산의 투자ㆍ운용과 관련된 업무에 3년 이상 종사한 사람"},{"법령":"부동산투자회사법","조문":"제29조제2항","원문":"제1항에 따른 자금차입 및 사채발행은 자기자본의 2배를 초과할 수 없다. 다만, 「상법」 제434조의 결의 방법에 따른 주주총회의 특별결의를 한 경우에는 그 합계가 자기자본의 10배를 넘지 아니하는 범위에서 자금차입 및 사채발행을 할 수 있다."},{"법령":"부동산투자회사법","조문":"제5조제2항","원문":"부동산투자회사는 「상법」 제290조제2호에도 불구하고 현물출자에 의한 설립을 할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"최저자본금은 자기관리 70억원이다(제10조제1호)."},{"번호":2,"판정":"옳음","설명":"위탁관리·기업구조조정은 50억원이다(제10조제2호)."},{"번호":3,"판정":"옳음","설명":"석사학위 이상 + 투자·운용 업무 3년 이상은 전문인력 요건의 하나다(제22조제1항제2호). 감정평가사·공인중개사는 해당 분야 5년 이상이 요건이다(같은 항 제1호)."},{"번호":4,"판정":"틀림","설명":"최저자본금을 갖추기 전에는 현물출자를 받는 신주발행을 할 수 없다(제19조제1항). 설립 자체도 현물출자로는 할 수 없다(제5조제2항)."},{"번호":5,"판정":"옳음","설명":"원칙 2배, 주주총회 특별결의 시 10배까지다(제29조제2항)."}],"개념":[{"종류":"흐름","제목":"자기관리 부동산투자회사의 설립 이후 절차","단계":[{"이름":"발기설립","설명":"발기설립만 가능하고 현물출자에 의한 설립은 불가 (제5조)"},{"이름":"설립보고","설명":"설립등기일부터 10일 이내 설립보고서 제출, 제출일부터 3개월 후 현황 보고서 제출 (제8조의2제1항·제2항)"},{"이름":"영업인가 신청","설명":"설립등기일부터 6개월 이내에 국토교통부장관에게 신청 (제8조의2제4항)"},{"이름":"영업인가","설명":"인가 전에는 주주가 아닌 자에게 배정하는 신주발행 불가 (제9조제4항)"},{"이름":"최저자본금준비기간","설명":"인가일부터 6개월. 최저자본금을 갖추기 전에는 현물출자를 받는 신주발행 불가 (제19조제1항)"},{"이름":"최저자본금 70억원 충족 이후","설명":"매 분기 말 총자산의 80% 이상을 부동산·부동산 관련 증권·현금으로, 그중 70% 이상은 부동산으로 구성 (제25조제1항)"}]},{"종류":"표","제목":"자본금과 차입 한도","머리":["항목","자기관리","위탁관리·기업구조조정","조문"],"행":[["설립 자본금","5억원 이상","3억원 이상","제6조"],["최저자본금 (인가·등록 후 6개월)","70억원 이상","50억원 이상","제10조"],["차입·사채발행 한도","자기자본의 2배 (주주총회 특별결의 시 10배)","자기자본의 2배 (주주총회 특별결의 시 10배)","제29조제2항"],["자산운용 전문인력","상근 (감정평가사·공인중개사 5년 이상 등)","해당 없음","제22조제1항"]]}],"함정":"현물출자는 부동산투자회사에서 허용되는 방법이라는 기억만으로 ④를 맞다고 본다. 허용 시점이 최저자본금 확보 이후라는 조건이 붙는다."}},{"i":"S5-1-1-학개론-31","r":"S5","g":1,"c":1,"n":31,"s":"학개론","q":"민간투자사업 방식에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["BTO(build-transfer-operate)방식은 준공과 동시에 시설의 소유권이 국가 또는 지방자치단체에 귀속되고, 사업시행자는 일정 기간 시설을 운영하며 이용자의 사용료로 투자비를 회수한다.","BTL(build-transfer-lease)방식은 준공 후에도 시설의 소유권이 사업시행자에게 남고, 이용자가 내는 사용료로 투자비를 회수한다.","BOT(build-operate-transfer)방식은 준공과 동시에 시설의 소유권이 국가 또는 지방자치단체에 귀속된다.","BOO(build-own-operate)방식은 일정 기간 운영한 뒤 시설의 소유권을 국가 또는 지방자치단체에 이전한다.","BLT(build-lease-transfer)방식은 준공과 동시에 소유권이 국가 또는 지방자치단체에 귀속되고, 사업시행자는 운영권만 갖는다."],"a":[1],"L":"학7-1","o":"신작","x":{"한줄":"BTO는 준공(Build)과 동시에 소유권이 국가 등에 넘어가고(Transfer), 사업시행자가 운영(Operate)하며 이용자의 사용료로 투자비를 회수한다.","근거":[{"이론":"민간투자사업 방식 판별","내용":"글자 순서가 사건 순서다. B 바로 뒤에 T가 오면 준공 즉시 소유권이 국가 등에 귀속(BTO·BTL). O(운영)나 L(임대) 뒤에 T가 오면 기간이 끝난 뒤 이전(BOT·BLT). T가 없으면 민간이 계속 소유(BOO)."}],"선지":[{"번호":1,"판정":"옳음","설명":"BTO의 정의다. 도로·항만·공항처럼 이용자에게 사용료를 받을 수 있는 시설에 쓴다."},{"번호":2,"판정":"틀림","설명":"BTL도 준공과 동시에 소유권이 국가 등에 귀속된다. 사업시행자는 운영하고 국가 등이 시설을 임차해 임대료를 지급하며, 이 임대료로 투자비를 회수한다. 학교·기숙사·도서관처럼 사용료를 걷기 어려운 시설에 쓴다."},{"번호":3,"판정":"틀림","설명":"BOT는 준공 후 일정 기간 사업시행자가 소유·운영한 뒤 기간이 끝나면 소유권을 국가 등에 이전한다."},{"번호":4,"판정":"틀림","설명":"BOO는 소유권을 이전하지 않고 사업시행자가 계속 소유·운영한다."},{"번호":5,"판정":"틀림","설명":"BLT는 사업시행자가 준공 후 일정 기간 시설을 소유하면서 국가 등에 임대해 투자비를 회수하고, 기간이 끝나면 소유권을 이전한다. 준공 즉시 귀속되는 방식은 BTO·BTL이다."}],"개념":[{"종류":"표","제목":"민간투자사업 다섯 가지","머리":["구분","준공 때 소유권","기간 동안","기간이 끝나면"],"행":[["BTO","국가 등","민간이 운영, 이용자 사용료로 회수","(이미 국가 소유)"],["BTL","국가 등","민간이 운영, 국가 등이 임차해 임대료 지급","(이미 국가 소유)"],["BOT","민간","민간이 소유·운영","국가 등에 이전"],["BOO","민간","민간이 소유·운영","이전 없음"],["BLT","민간","민간이 소유하며 국가 등에 임대","국가 등에 이전"]]},{"종류":"비교","제목":"BTO vs BTL","왼쪽":{"이름":"BTO","항목":["준공 즉시 소유권 국가 등에 귀속","민간이 운영권 보유","이용자 사용료로 투자비 회수","도로·공항·항만 등 수요 위험을 민간이 진다"]},"오른쪽":{"이름":"BTL","항목":["준공 즉시 소유권 국가 등에 귀속","민간이 운영권 보유","국가 등이 임차해 지급하는 임대료로 회수","학교·기숙사·도서관 등 사용료를 걷기 어려운 시설"]}}],"함정":"BTO와 BTL은 둘 다 ‘준공 즉시 국가 귀속’이다. 차이는 투자비 회수 수단(사용료/임대료)이다. ②처럼 BTL의 소유권을 민간에 남기거나 사용료로 회수한다고 적으면 틀린다."}},{"i":"S5-1-1-학개론-32","r":"S5","g":1,"c":1,"n":32,"s":"학개론","q":"부동산개발과 분석에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["워포드(D. Wofford)의 개발 7단계에서 부지모색·확보 단계는 예비적 타당성 분석 단계보다 앞선다.","시장성 분석은 법률적·기술적·경제적 측면에서 개발사업의 실행 가능성을 따지는 분석이며, 그중 경제적 타당성이 중심이다.","시장분석은 인구, 고용, 소득 등을 통해 도시 전체의 기본 수요를 분석하는 단계다.","환지방식은 사업구역의 토지를 전부 매수하여 시행하므로 보상비 부담이 크고, 수용방식은 개발 전 권리를 개발 후 토지로 재분배한다.","사업위탁(수탁)방식은 토지 소유권과 사업 명의가 소유자에게 남고 개발업자는 수수료를 받는 반면, 토지신탁방식은 소유권이 형식상 신탁회사로 이전되고 신탁회사가 사업 명의자가 되어 부족한 자금도 조달한다."],"a":[5],"L":"학7-1","o":"신작","x":{"한줄":"사업위탁방식은 소유권이 소유자에게 그대로 있고 개발업자가 수수료를 받는다. 토지신탁방식은 소유권이 형식상 신탁회사로 넘어가 신탁회사가 사업을 맡는다.","근거":[{"이론":"개발방식: 사업위탁과 토지신탁","내용":"사업위탁은 소유권·사업 명의가 소유자에게 있고 개발업자는 수수료를 받는다. 토지신탁은 소유권이 형식상 신탁회사로 이전되고 신탁회사가 사업 주체로서 부족자금을 조달하며 사업 뒤 수익을 소유자에게 돌려준다."},{"이론":"워포드의 개발 7단계","내용":"아이디어 → 예비적 타당성 분석 → 부지모색·확보 → 타당성 분석 → 금융 → 건설 → 마케팅."},{"이론":"부동산 분석 5단계","내용":"지역경제 분석 → 시장 분석 → 시장성 분석 → 타당성 분석 → 투자 분석."}],"선지":[{"번호":1,"판정":"틀림","설명":"예비적 타당성 분석이 먼저고 그 결과를 보고 부지를 찾아 확보한다. 순서는 아이디어 → 예비적 타당성 분석 → 부지모색·확보 → 타당성 분석이다."},{"번호":2,"판정":"틀림","설명":"법률·기술·경제 세 측면에서 실행 가능성을 따지는 것은 타당성 분석이다. 시장성 분석은 완성될 부동산이 매매·임대될 가능성, 곧 미래 흡수율을 본다."},{"번호":3,"판정":"틀림","설명":"도시 전체의 기본 수요(인구·고용·소득)는 지역경제 분석 단계다. 시장분석은 특정 유형 부동산의 수요·공급을 시장지역 설정부터 분석한다."},{"번호":4,"판정":"틀림","설명":"설명이 뒤바뀌었다. 구역의 토지를 전부 사들이는 쪽은 수용(매수)방식이고, 개발 전 권리를 개발 후 토지로 다시 나누어 주는 쪽은 환지방식이다."},{"번호":5,"판정":"옳음","설명":"사업위탁과 토지신탁의 차이를 정확히 구분했다. 소유권이 넘어가는 쪽은 토지신탁뿐이다."}],"개념":[{"종류":"흐름","제목":"워포드의 개발 7단계","단계":[{"이름":"아이디어","설명":"개발 구상"},{"이름":"예비적 타당성 분석","설명":"수입·비용을 개략적으로 따져 본다"},{"이름":"부지모색·확보","설명":"땅을 찾아 확보"},{"이름":"타당성 분석","설명":"실행 가능성을 세부적으로 분석"},{"이름":"금융","설명":"자금 조달"},{"이름":"건설","설명":"공사"},{"이름":"마케팅","설명":"분양·임대"}]},{"종류":"비교","제목":"사업위탁방식 vs 토지신탁방식","왼쪽":{"이름":"사업위탁(수탁)방식","항목":["소유권은 소유자에게 그대로","사업 명의는 소유자","개발업자는 수수료를 받는다"]},"오른쪽":{"이름":"토지신탁방식","항목":["소유권이 형식상 신탁회사로 이전","사업 명의는 신탁회사, 부족자금도 신탁회사가 조달","사업 뒤 수익을 소유자에게 돌려준다"]}}],"함정":"①~③은 단계 이름을 서로 바꿔 끼운 선지다. 지역경제 분석(도시 전체) · 시장분석(특정 유형) · 시장성 분석(흡수율) · 타당성 분석(법률·기술·경제 3측면)을 단계 순서와 함께 묶어 두어야 한다. ④는 수용과 환지의 설명을 맞바꿨다."}},{"i":"S5-1-1-학개론-33","r":"S5","g":1,"c":1,"n":33,"s":"학개론","q":"한국표준산업분류상 부동산업에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["부동산업은 부동산 임대 및 공급업과 부동산 관련 서비스업으로 나뉜다.","부동산 개발 및 공급업은 부동산 관련 서비스업에 속한다.","주거용 부동산 관리업과 비주거용 부동산 관리업은 부동산 관련 서비스업에 속한다.","부동산 중개 및 대리업과 부동산 투자 자문업은 부동산 관련 서비스업에 속한다.","부동산 감정평가업은 부동산 관련 서비스업에 속한다."],"a":[2],"L":"학7-2","o":"변형","x":{"한줄":"부동산 개발 및 공급업은 부동산 임대업과 함께 ‘부동산 임대 및 공급업’에 속하고, 부동산 관련 서비스업에는 관리업, 중개·대리업, 투자 자문업, 감정평가업이 속한다.","근거":[{"이론":"한국표준산업분류의 부동산업","내용":"부동산업 = 부동산 임대 및 공급업(부동산 임대업, 부동산 개발 및 공급업) + 부동산 관련 서비스업(부동산 관리업[주거용·비주거용], 부동산 중개·자문 및 감정평가업[중개 및 대리업, 투자 자문업, 감정평가업])."}],"선지":[{"번호":1,"판정":"옳음","설명":"부동산업의 두 갈래다."},{"번호":2,"판정":"틀림","설명":"부동산 개발 및 공급업은 부동산 임대 및 공급업에 속한다."},{"번호":3,"판정":"옳음","설명":"관리업은 서비스업 쪽이며 주거용과 비주거용으로 나뉜다."},{"번호":4,"판정":"옳음","설명":"중개 및 대리업, 투자 자문업 모두 부동산 중개·자문 및 감정평가업에 들어간다."},{"번호":5,"판정":"옳음","설명":"감정평가업도 부동산 중개·자문 및 감정평가업에 들어간다."}],"개념":[{"종류":"표","제목":"한국표준산업분류상 부동산업 구조","머리":["구분","세분류","해당 업종"],"행":[["부동산 임대 및 공급업","부동산 임대업","건물·토지 등 임대"],["부동산 임대 및 공급업","부동산 개발 및 공급업","주거용·비주거용 건물 개발·공급 등"],["부동산 관련 서비스업","부동산 관리업","주거용 부동산 관리업, 비주거용 부동산 관리업"],["부동산 관련 서비스업","부동산 중개, 자문 및 감정평가업","부동산 중개 및 대리업, 부동산 투자 자문업, 부동산 감정평가업"]]},{"종류":"비교","제목":"부동산관리 방식: 자기관리 vs 위탁관리","왼쪽":{"이름":"자기관리","항목":["소유자가 직접 관리","기밀유지·신속한 의사결정에 유리","업무 수행이 일관되나 전문성이 낮을 수 있다","관리 인력 유지 비용이 든다"]},"오른쪽":{"이름":"위탁관리","항목":["전문 관리업체에 위탁","전문성·규모의 경제를 활용","기밀유지가 어렵고 책임 소재가 흐려질 수 있다","위탁 수수료가 든다 (자기관리와 위탁을 섞으면 혼합관리)"]}}],"함정":"‘개발 및 공급’이라는 이름에서 서비스업으로 읽기 쉽다. 개발업은 임대업과 같은 갈래이고, 서비스업은 관리·중개·자문·감정평가다."}},{"i":"S5-1-1-학개론-34","r":"S5","g":1,"c":1,"n":34,"s":"학개론","q":"부동산마케팅 전략에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["바이럴 마케팅(viral marketing)전략은 SNS, 블로그 등 다양한 매체를 통해 해당 브랜드나 제품에 대해 입소문을 내게 하여 마케팅효과를 극대화시키는 것이다.","분양성공을 위해 아파트 브랜드를 고급스러운 이미지로 고객의 인식에 각인시키도록 하는 노력은 STP전략 중 시장세분화(Segmentation) 전략에 해당한다.","아파트 분양 모델하우스 방문고객 대상으로 추첨을 통해 자동차를 경품으로 제공하는 것은 4P Mix 전략 중 유통경로(Place)전략에 해당한다.","아파트의 차별화를 위해 커뮤니티 시설에 헬스장, 골프연습장을 설치하는 방안은 4P Mix 전략 중 가격(Price)전략에 해당한다.","고객점유 마케팅전략에서 AIDA의 원리는 주의(Attention) - 관심(Interest) - 결정(Decision) - 행동(Action)의 과정을 말한다."],"a":[1],"L":"학7-2","o":"기출","x":{"한줄":"바이럴 마케팅은 SNS·블로그 같은 매체를 통해 소비자가 입소문을 퍼뜨리게 하는 전략이다.","근거":[{"이론":"마케팅 전략","내용":"STP = 시장세분화(Segmentation) → 표적시장 선정(Targeting) → 포지셔닝(Positioning). 4P Mix = 제품(Product)·가격(Price)·유통경로(Place)·판매촉진(Promotion). AIDA = 주의(Attention) → 관심(Interest) → 욕망(Desire) → 행동(Action)."}],"선지":[{"번호":1,"판정":"옳음","설명":"바이럴 마케팅의 정의다. 이용자가 스스로 퍼뜨리는 점이 특징이다."},{"번호":2,"판정":"틀림","설명":"브랜드를 고급스러운 이미지로 인식시키는 것은 포지셔닝(Positioning)이다. 시장세분화는 구매자를 기준에 따라 나누는 일이다."},{"번호":3,"판정":"틀림","설명":"경품 추첨은 판매촉진(Promotion) 전략이다. 유통경로(Place)는 분양대행사, 모델하우스 위치 같은 판매 경로에 관한 전략이다."},{"번호":4,"판정":"틀림","설명":"커뮤니티 시설의 차별화는 제품(Product) 전략이다. 가격(Price) 전략은 분양가 책정, 할인, 중도금 조건 등이다."},{"번호":5,"판정":"틀림","설명":"AIDA의 셋째 단계는 결정(Decision)이 아니라 욕망(Desire)이다."}],"개념":[{"종류":"표","제목":"마케팅 전략 구분 (STP와 4P Mix)","머리":["전략","내용","부동산 사례"],"행":[["시장세분화(Segmentation)","구매자를 소득·연령·가구 형태 등으로 나눔","신혼부부 / 은퇴 세대 구분"],["표적시장 선정(Targeting)","세분시장 중 공략할 대상을 고름","30대 맞벌이를 분양 대상으로 선정"],["포지셔닝(Positioning)","표적 고객 인식 속에 경쟁 상품과 구별되는 이미지를 심음","고급 브랜드 이미지 구축"],["제품(Product)","상품의 품질·설계·시설","커뮤니티 시설, 평면 특화"],["가격(Price)","가격 책정·할인·지불 조건","분양가, 중도금 무이자"],["유통경로(Place)","판매·유통 경로","분양대행사, 모델하우스 위치"],["판매촉진(Promotion)","광고·경품·인적판매","경품 추첨, 광고"]]},{"종류":"흐름","제목":"AIDA 원리 (소비자 구매 과정)","단계":[{"이름":"주의(Attention)","설명":"광고 등으로 상품을 알게 된다"},{"이름":"관심(Interest)","설명":"상품에 흥미를 갖는다"},{"이름":"욕망(Desire)","설명":"사고 싶은 마음이 생긴다"},{"이름":"행동(Action)","설명":"구매·계약을 한다"}]}],"함정":"AIDA의 D를 결정(Decision)으로 적은 ⑤가 가장 그럴듯하다. D는 욕망(Desire)이다. 경품은 가격이 아닌 판매촉진이고, 고급 이미지 각인은 세분화가 아닌 포지셔닝이다."}},{"i":"S5-1-1-학개론-35","r":"S5","g":1,"c":1,"n":35,"s":"학개론","q":"감정평가 과정상 지역분석과 개별분석에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지역분석은 대상부동산이 속한 지역의 표준적 이용과 가격수준을 판정하는 분석이다.","지역분석은 개별분석보다 먼저 이루어지며, 지역분석으로 파악한 표준적 이용의 틀 안에서 개별분석을 한다.","유사지역이란 대상부동산이 속하지 아니하는 지역으로서 인근지역과 유사한 특성을 갖는 지역을 말한다.","동일수급권이란 대상부동산과 대체·경쟁 관계가 성립하고 가치 형성에 서로 영향을 미치는 부동산이 존재하는 권역으로, 인근지역은 포함하지만 유사지역은 포함하지 않는다.","개별분석은 대상부동산의 개별요인을 분석하여 최유효이용과 구체적 가격을 판정하는 미시적·국지적 분석이다."],"a":[4],"L":"학8-1","o":"변형","x":{"한줄":"동일수급권은 인근지역과 유사지역을 모두 포함하는 권역이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제15호","원문":"\"동일수급권(同一需給圈)\"이란 대상부동산과 대체ㆍ경쟁 관계가 성립하고 가치 형성에 서로 영향을 미치는 관계에 있는 다른 부동산이 존재하는 권역(圈域)을 말하며, 인근지역과 유사지역을 포함한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제13호·제14호","원문":"\"인근지역\"이란 감정평가의 대상이 된 부동산(이하 \"대상부동산\"이라 한다)이 속한 지역으로서 부동산의 이용이 동질적이고 가치형성요인 중 지역요인을 공유하는 지역을 말한다. \"유사지역\"이란 대상부동산이 속하지 아니하는 지역으로서 인근지역과 유사한 특성을 갖는 지역을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지역분석은 대상지역 전체를 거시적·광역적으로 보아 표준적 이용과 가격수준을 파악한다."},{"번호":2,"판정":"옳음","설명":"지역분석이 선행분석, 개별분석이 후행분석이다."},{"번호":3,"판정":"옳음","설명":"규칙 제2조제14호의 정의 그대로다."},{"번호":4,"판정":"틀림","설명":"동일수급권은 인근지역과 유사지역을 포함한다(규칙 제2조제15호)."},{"번호":5,"판정":"옳음","설명":"개별분석은 대상부동산의 개별요인을 분석해 최유효이용을 판정하고 구체적 가격을 구하는 후행분석이다."}],"개념":[{"종류":"비교","제목":"지역분석 vs 개별분석","왼쪽":{"이름":"지역분석","항목":["분석 대상은 대상부동산이 속한 지역","거시적·광역적 분석","지역요인(일반요인 포함)을 분석","표준적 이용과 가격수준을 판정","선행분석"]},"오른쪽":{"이름":"개별분석","항목":["분석 대상은 대상부동산 그 자체","미시적·국지적 분석","개별요인을 분석","최유효이용과 구체적 가격을 판정","후행분석"]}},{"종류":"표","제목":"인근지역 · 유사지역 · 동일수급권 (감정평가에 관한 규칙 제2조)","머리":["용어","뜻","대상부동산"],"행":[["인근지역","대상부동산이 속한 지역으로, 이용이 동질적이고 지역요인을 공유","속함"],["유사지역","대상부동산이 속하지 않는 지역으로, 인근지역과 유사한 특성","속하지 않음"],["동일수급권","대상부동산과 대체·경쟁 관계인 부동산이 존재하는 권역. 인근지역과 유사지역을 포함","인근지역 + 유사지역"],["가치형성요인","일반요인, 지역요인, 개별요인 등 (제2조제4호)","-"]]}],"함정":"‘동일수급권 = 인근지역 + 유사지역’이라는 정의에서 유사지역을 빼면 틀린다. 지역분석(거시)과 개별분석(미시)의 성격을 뒤바꾼 선지가 원문 계열의 대표 오답이다."}},{"i":"S5-1-1-학개론-36","r":"S5","g":1,"c":1,"n":36,"s":"학개론","q":"원가법으로 평가한 다음 건물의 적산가액은? (단, 주어진 조건에 한하며, 감가수정은 정액법으로 하고 내용연수 만료 시 잔존가치율은 10%)\n· 기준시점 현재 재조달원가: 6억원\n· 경제적 내용연수: 40년\n· 기준시점까지 경과연수: 10년","b":null,"bs":"없음","img":[],"ch":["4억 500만원","4억 5,000만원","4억 6,500만원","5억 4,000만원","5억 8,500만원"],"a":[3],"L":"학8-2","o":"신작","x":{"한줄":"감가누계액 1억 3,500만원을 재조달원가 6억원에서 빼면 적산가액은 4억 6,500만원이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제5호","원문":"\"원가법\"이란 대상물건의 재조달원가에 감가수정(減價修正)을 하여 대상물건의 가액을 산정하는 감정평가방법을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제15조제1항","원문":"감정평가법인등은 건물을 감정평가할 때에 원가법을 적용해야 한다."},{"이론":"정액법 감가수정","내용":"매년 감가액 = (재조달원가 − 잔존가치) ÷ 경제적 내용연수. 감가누계액 = 매년 감가액 × 경과연수. 적산가액 = 재조달원가 − 감가누계액."}],"선지":[{"번호":1,"판정":"-","설명":"감가 대상 금액 5억 4,000만원(재조달원가에서 잔존가치를 뺀 값)에서 다시 25%를 공제한 값(5.4억 × 0.75)이다. 잔존가치를 두 번 뺐다."},{"번호":2,"판정":"-","설명":"잔존가치를 무시하고 6억원 × (1 − 10/40)로 계산한 값이다."},{"번호":3,"판정":"-","설명":"6억원 − 6억원 × 90% × 10/40 = 6억원 − 1억 3,500만원 = 4억 6,500만원. 정답이다."},{"번호":4,"판정":"-","설명":"재조달원가에서 잔존가치(6,000만원)만 빼고 경과연수에 따른 감가를 하지 않은 값이다."},{"번호":5,"판정":"-","설명":"감가율을 잔존가치율 10% × 경과비율 10/40 = 2.5%로 잘못 잡아 6억원 × 97.5%를 구한 값이다."}],"개념":[{"종류":"계산","제목":"원가법 · 정액법 감가수정","단계":[{"설명":"감가 대상 금액 (재조달원가 − 잔존가치)","식":"6억원 − 6억원 × 10%","값":"5억 4,000만원"},{"설명":"매년 감가액","식":"5억 4,000만원 ÷ 40년","값":"1,350만원"},{"설명":"감가누계액","식":"1,350만원 × 10년","값":"1억 3,500만원"},{"설명":"적산가액","식":"6억원 − 1억 3,500만원","값":"4억 6,500만원"},{"설명":"검산","식":"6억원 × (1 − 0.9 × 10/40)","값":"4억 6,500만원"}]},{"종류":"표","제목":"감가수정 방법 세 가지","머리":["구분","정액법","정률법","상환기금법"],"행":[["매년 감가","감가액이 일정","감가율이 일정하여 감가액은 해마다 줄어듦","감채기금계수로 적립(이자 포함)"],["첫해 감가액","중간","가장 큼","가장 작음"],["적산가액","중간","가장 작음","가장 큼"],["어울리는 대상","건물 일반","기계·설비","-"]]}],"함정":"잔존가치를 빼는 위치가 핵심이다. 감가 대상 금액만 잔존가치를 뺀 값이고, 적산가액은 재조달원가에서 감가누계액을 뺀다. 잔존가치를 이중으로 빼거나 아예 빼지 않으면 인접한 선지가 나온다."}},{"i":"S5-1-1-학개론-37","r":"S5","g":1,"c":1,"n":37,"s":"학개론","q":"거래사례비교법으로 평가한 대상토지의 비준가액은? (단, 주어진 조건에 한하며, 사례토지와 대상토지의 면적은 같음)\n· 거래사례: 인근지역에서 6억원에 거래된 토지로, 정상적인 거래가격보다 20% 낮게 거래된 것으로 확인됨\n· 거래시점부터 기준시점까지 지가는 8% 상승\n· 개별요인은 대상토지가 사례토지보다 5% 우세\n· 지역요인은 동일","b":null,"bs":"없음","img":[],"ch":["5억 6,700만원","6억 8,040만원","7억 6,950만원","7억 8,750만원","8억 5,050만원"],"a":[5],"L":"학8-2","o":"신작","x":{"한줄":"사례가격 6억원에 사정보정 100/80, 시점수정 1.08, 개별요인 105/100을 곱한 8억 5,050만원이 비준가액이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제7호","원문":"\"거래사례비교법\"이란 대상물건과 가치형성요인이 같거나 비슷한 물건의 거래사례와 비교하여 대상물건의 현황에 맞게 사정보정(事情補正), 시점수정, 가치형성요인 비교 등의 과정을 거쳐 대상물건의 가액을 산정하는 감정평가방법을 말한다."},{"이론":"비준가액 계산","내용":"비준가액 = 사례가격 × 사정보정치 × 시점수정치 × 지역요인 비교치 × 개별요인 비교치 × 면적 비교치. 모든 비교치는 대상 ÷ 사례이며 사정보정치 = 정상가격 ÷ 사례 실제가격."}],"선지":[{"번호":1,"판정":"-","설명":"사정보정을 100/120로 계산한 값이다. 저가 거래(정상보다 20% 낮음)를 고가 거래로 읽었다."},{"번호":2,"판정":"-","설명":"사정보정을 하지 않고 6억원 × 1.08 × 1.05로 계산한 값이다."},{"번호":3,"판정":"-","설명":"개별요인 우세 5%를 0.95로 계산한 값이다. 대상이 우세하면 비교치는 1.05다."},{"번호":4,"판정":"-","설명":"시점수정을 하지 않고 6억원 × 100/80 × 1.05로 계산한 값이다."},{"번호":5,"판정":"-","설명":"6억원 × 100/80 × 1.08 × 1.05 = 8억 5,050만원. 정답이다."}],"개념":[{"종류":"계산","제목":"거래사례비교법 비준가액","단계":[{"설명":"사정보정치 (정상가격 100 ÷ 사례가격 80)","식":"100/80","값":"1.25"},{"설명":"사정보정 후 가격","식":"6억원 × 1.25","값":"7억 5,000만원"},{"설명":"시점수정치","식":"1 + 0.08","값":"1.08"},{"설명":"시점수정 후 가격","식":"7억 5,000만원 × 1.08","값":"8억 1,000만원"},{"설명":"개별요인 비교치 (대상 105 ÷ 사례 100)","식":"105/100","값":"1.05"},{"설명":"비준가액 (지역요인 1, 면적비 1)","식":"8억 1,000만원 × 1.05","값":"8억 5,050만원"}]},{"종류":"표","제목":"가액을 구하는 식 비교","머리":["구분","원가법","거래사례비교법","공시지가기준법","수익환원법"],"행":[["출발점","재조달원가","거래사례 가격","비교표준지 공시지가","순영업소득(순수익)"],["거치는 단계","− 감가수정","× 사정보정 × 시점수정 × 지역요인 × 개별요인 × 면적","× 시점수정 × 지역요인 × 개별요인 × 그 밖의 요인 보정","÷ 환원이율"],["결과","적산가액","비준가액","토지 가액","수익가액"]]}],"함정":"사정보정은 사례가 정상보다 싸게 거래되었으면 1보다 크게, 비싸게 거래되었으면 1보다 작게 곱한다. 저가 거래를 100/120으로 읽으면 ①이 나온다. 사정보정은 거래사례비교법에만 있고 공시지가기준법에는 없다."}},{"i":"S5-1-1-학개론-38","r":"S5","g":1,"c":1,"n":38,"s":"학개론","q":"감정평가에 관한 규칙에 규정된 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["기준시점이란 대상물건의 감정평가액을 결정하는 기준이 되는 날짜를 말한다.","하나의 대상물건이라도 가치를 달리하는 부분은 이를 구분하여 감정평가할 수 있다.","거래사례비교법은 감정평가방식 중 비교방식에 해당되나, 공시지가기준법은 비교방식에 해당되지 않는다.","감정평가법인등은 대상물건별로 정한 감정평가방법(이하 “주된 방법”이라 함)을 적용하여 감정평가하되, 주된 방법을 적용하는 것이 곤란하거나 부적절한 경우에는 다른 감정평가방법을 적용할 수 있다.","감정평가법인등은 감정평가서를 감정평가 의뢰인과 이해관계자가 이해할 수 있도록 명확하고 일관성 있게 작성해야 한다."],"a":[3],"L":"학8-3","o":"기출","x":{"한줄":"공시지가기준법은 거래사례비교법, 임대사례비교법과 함께 비교방식에 속한다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제11조제2호","원문":"비교방식: 거래사례비교법, 임대사례비교법 등 시장성의 원리에 기초한 감정평가방식 및 공시지가기준법"},{"법령":"감정평가에 관한 규칙","조문":"제2조제2호","원문":"\"기준시점\"이란 대상물건의 감정평가액을 결정하는 기준이 되는 날짜를 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제7조제3항","원문":"하나의 대상물건이라도 가치를 달리하는 부분은 이를 구분하여 감정평가할 수 있다."},{"법령":"감정평가에 관한 규칙","조문":"제12조제1항","원문":"감정평가법인등은 제14조부터 제26조까지의 규정에서 대상물건별로 정한 감정평가방법(이하 \"주된 방법\"이라 한다)을 적용하여 감정평가해야 한다. 다만, 주된 방법을 적용하는 것이 곤란하거나 부적절한 경우에는 다른 감정평가방법을 적용할 수 있다."},{"법령":"감정평가에 관한 규칙","조문":"제13조제1항","원문":"감정평가법인등은 법 제6조에 따른 감정평가서(「전자문서 및 전자거래기본법」에 따른 전자문서로 된 감정평가서를 포함한다. 이하 같다)를 의뢰인과 이해관계자가 이해할 수 있도록 명확하고 일관성 있게 작성해야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"기준시점의 정의다(제2조제2호)."},{"번호":2,"판정":"옳음","설명":"구분 평가의 근거는 제7조제3항이다."},{"번호":3,"판정":"틀림","설명":"공시지가기준법도 비교방식이다(제11조제2호). 토지는 공시지가기준법이 주된 방법이다(제14조제1항)."},{"번호":4,"판정":"옳음","설명":"주된 방법이 곤란하거나 부적절하면 다른 방법을 적용할 수 있다(제12조제1항 단서)."},{"번호":5,"판정":"옳음","설명":"감정평가서 작성 원칙이다(제13조제1항)."}],"개념":[{"종류":"표","제목":"3방식 6방법 (규칙 제11조)","머리":["방식 (원리)","가액을 구하면","임대료를 구하면"],"행":[["원가방식 (비용성)","원가법 → 적산가액","적산법 → 적산임료"],["비교방식 (시장성)","거래사례비교법 → 비준가액, 공시지가기준법(토지)","임대사례비교법 → 비준임료"],["수익방식 (수익성)","수익환원법 → 수익가액","수익분석법 → 수익임료"]]},{"종류":"표","제목":"감정평가 기본원칙","머리":["원칙","내용","조문"],"행":[["시장가치기준 원칙","감정평가액은 시장가치를 기준으로 결정. 법령 규정·의뢰인 요청·사회통념상 필요 시 시장가치 외 가치도 가능","제5조"],["현황기준 원칙","기준시점의 이용상황(불법적·일시적 이용 제외)과 공법상 제한을 받는 상태 기준. 감정평가조건을 붙일 수 있는 경우 있음","제6조"],["개별물건기준 원칙","대상물건마다 개별로 평가. 일체 거래·용도상 불가분이면 일괄 가능, 가치를 달리하는 부분은 구분 가능, 일부분 평가도 가능","제7조"]]}],"함정":"‘공시지가비교법’이라는 이름이 비교방식이 아니라는 느낌을 준다. 공시지가기준법은 비교방식에 들어간다."}},{"i":"S5-1-1-학개론-39","r":"S5","g":1,"c":1,"n":39,"s":"학개론","q":"감정평가에 관한 규칙에 규정된 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["기준시점은 대상물건의 가격조사를 완료한 날짜로 한다. 다만, 기준시점을 미리 정하였을 때에는 그 날짜로 하여야 한다.","감정평가법인등은 법령에 다른 규정이 있는 경우에는 기준시점의 가치형성요인 등을 실제와 다르게 가정하거나 특수한 경우로 한정하는 조건을 붙여 감정평가할 수 있다.","둘 이상의 대상물건이 일체로 거래되거나 대상물건 상호간에 용도상 불가분의 관계가 있는 경우에는 일괄하여 감정평가할 수 있다.","하나의 대상물건이라도 가치를 달리하는 부분은 이를 구분하여 감정평가할 수 있다.","일체로 이용되고 있는 대상물건의 일부분에 대하여 감정평가하여야 할 특수한 목적이나 합리적인 이유가 있는 경우에는 그 부분에 대하여 감정평가할 수 있다."],"a":[1],"L":"학8-3","o":"기출","x":{"한줄":"기준시점을 미리 정했더라도 그 날짜에 가격조사가 가능한 경우에만 기준시점으로 할 수 있다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제9조제2항","원문":"기준시점은 대상물건의 가격조사를 완료한 날짜로 한다. 다만, 기준시점을 미리 정하였을 때에는 그 날짜에 가격조사가 가능한 경우에만 기준시점으로 할 수 있다."},{"법령":"감정평가에 관한 규칙","조문":"제6조제2항","원문":"감정평가법인등은 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 기준시점의 가치형성요인 등을 실제와 다르게 가정하거나 특수한 경우로 한정하는 조건(이하 \"감정평가조건\"이라 한다)을 붙여 감정평가할 수 있다. 1. 법령에 다른 규정이 있는 경우"},{"법령":"감정평가에 관한 규칙","조문":"제7조제2항~제4항","원문":"둘 이상의 대상물건이 일체로 거래되거나 대상물건 상호 간에 용도상 불가분의 관계가 있는 경우에는 일괄하여 감정평가할 수 있다. 하나의 대상물건이라도 가치를 달리하는 부분은 이를 구분하여 감정평가할 수 있다. 일체로 이용되고 있는 대상물건의 일부분에 대하여 감정평가하여야 할 특수한 목적이나 합리적인 이유가 있는 경우에는 그 부분에 대하여 감정평가할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"미리 정한 기준시점은 ‘그 날짜에 가격조사가 가능한 경우에만’ 기준시점이 된다(제9조제2항 단서). ‘그 날짜로 하여야 한다’는 규정이 아니다."},{"번호":2,"판정":"옳음","설명":"감정평가조건을 붙일 수 있는 경우 중 하나가 법령에 다른 규정이 있는 경우다(제6조제2항제1호)."},{"번호":3,"판정":"옳음","설명":"일괄평가의 요건이다(제7조제2항)."},{"번호":4,"판정":"옳음","설명":"구분평가다(제7조제3항)."},{"번호":5,"판정":"옳음","설명":"일부분 평가다(제7조제4항)."}],"개념":[{"종류":"흐름","제목":"감정평가 절차 (규칙 제8조)","단계":[{"이름":"기본적 사항의 확정","설명":"의뢰인·대상물건·목적·기준시점·감정평가조건·기준가치·자문등·수수료 확정 (제9조제1항)"},{"이름":"처리계획 수립","설명":"평가 계획"},{"이름":"대상물건 확인","설명":"현장 확인"},{"이름":"자료수집 및 정리","설명":"사례·자료 수집"},{"이름":"자료검토 및 가치형성요인의 분석","설명":"일반요인·지역요인·개별요인 분석"},{"이름":"감정평가방법의 선정 및 적용","설명":"주된 방법과 다른 방식의 시산가액 비교"},{"이름":"감정평가액의 결정 및 표시","설명":"감정평가서 작성"}]},{"종류":"표","제목":"기준시점과 일괄·구분·일부 평가 (규칙 제7조·제9조)","머리":["항목","내용","조문"],"행":[["기준시점 원칙","가격조사를 완료한 날짜","제9조제2항"],["기준시점을 미리 정한 경우","그 날짜에 가격조사가 가능한 경우에만 기준시점으로 할 수 있다","제9조제2항 단서"],["일괄평가","일체 거래이거나 용도상 불가분 관계인 둘 이상의 물건","제7조제2항"],["구분평가","하나의 물건이라도 가치를 달리하는 부분","제7조제3항"],["일부분 평가","일체 이용 물건의 일부를 평가할 특수한 목적·합리적 이유","제7조제4항"]]}],"함정":"‘미리 정한 날짜로 한다’는 단정형과 ‘가격조사가 가능한 경우에만’이라는 조건형의 차이를 묻는다. 나머지 네 선지는 조문 문장 그대로다."}},{"i":"S5-1-1-학개론-40","r":"S5","g":1,"c":1,"n":40,"s":"학개론","q":"부동산 가격공시에 관한 법령에 규정된 내용으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["개별공시지가에 이의가 있는 자는 그 결정·공시일부터 30일 이내에 서면으로 시장·군수 또는 구청장에게 이의를 신청할 수 있다.","시장·군수 또는 구청장은 개별주택가격을 산정할 때 그 타당성에 대하여 감정평가법인등의 검증을 받아야 한다.","국토교통부장관은 일단의 공동주택 중에서 표준공동주택을 선정하여 매년 공시기준일 현재의 적정가격을 조사·산정한다.","국토교통부장관이 표준지공시지가를 조사·평가할 때에는 해당 토지 소유자의 의견을 들을 필요가 없다.","국토교통부장관은 비주거용 표준부동산가격을 매년 반드시 조사·산정하여 공시하여야 한다."],"a":[1],"L":"학8-4","o":"변형","x":{"한줄":"개별공시지가에 이의가 있으면 결정·공시일부터 30일 이내에 서면으로 시장·군수·구청장에게 이의를 신청한다.","근거":[{"법령":"부동산 가격공시에 관한 법률","조문":"제11조제1항","원문":"개별공시지가에 이의가 있는 자는 그 결정ㆍ공시일부터 30일 이내에 서면으로 시장ㆍ군수 또는 구청장에게 이의를 신청할 수 있다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제17조제6항","원문":"시장ㆍ군수 또는 구청장은 개별주택가격을 결정ㆍ공시하기 위하여 개별주택의 가격을 산정할 때에는 표준주택가격과의 균형 등 그 타당성에 대하여 대통령령으로 정하는 바에 따라 부동산원의 검증을 받고 토지소유자, 그 밖의 이해관계인의 의견을 들어야 한다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제18조제1항","원문":"국토교통부장관은 공동주택에 대하여 매년 공시기준일 현재의 적정가격(이하 \"공동주택가격\"이라 한다)을 조사ㆍ산정하여 제24조에 따른 중앙부동산가격공시위원회의 심의를 거쳐 공시하고, 이를 관계 행정기관 등에 제공하여야 한다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제3조제2항","원문":"국토교통부장관은 표준지공시지가를 공시하기 위하여 표준지의 가격을 조사ㆍ평가할 때에는 대통령령으로 정하는 바에 따라 해당 토지 소유자의 의견을 들어야 한다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제20조제1항","원문":"국토교통부장관은 용도지역, 이용상황, 건물구조 등이 일반적으로 유사하다고 인정되는 일단의 비주거용 일반부동산 중에서 선정한 비주거용 표준부동산에 대하여 매년 공시기준일 현재의 적정가격(이하 \"비주거용 표준부동산가격\"이라 한다)을 조사ㆍ산정하고, 제24조에 따른 중앙부동산가격공시위원회의 심의를 거쳐 이를 공시할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"이의신청 기간은 30일이고 신청처는 시장·군수·구청장이다(제11조제1항)."},{"번호":2,"판정":"틀림","설명":"개별주택가격의 검증 기관은 한국부동산원이다(제17조제6항). 감정평가법인등의 검증을 받는 것은 개별공시지가다(제10조제5항)."},{"번호":3,"판정":"틀림","설명":"공동주택은 표준공동주택을 따로 선정하지 않고 공동주택 전체에 대해 가격을 조사·산정한다(제18조제1항). ‘일단의 단독주택 중에서 선정한 표준주택’은 표준주택가격 방식이다(제16조제1항)."},{"번호":4,"판정":"틀림","설명":"표준지의 가격을 조사·평가할 때 토지 소유자의 의견을 들어야 한다(제3조제2항)."},{"번호":5,"판정":"틀림","설명":"비주거용 표준부동산가격은 조사·산정하여 공시‘할 수 있다’(제20조제1항). 반드시 공시해야 하는 것이 아니다."}],"개념":[{"종류":"표","제목":"부동산 가격공시 비교","머리":["구분","공시 주체","산정 시 의뢰·검증","이의신청"],"행":[["표준지공시지가","국토교통부장관","둘 이상의 감정평가법인등에 조사·평가 의뢰 (지가 변동이 작은 등 대통령령 기준이면 하나)","공시일부터 30일 이내, 국토교통부장관"],["개별공시지가","시장·군수·구청장","감정평가법인등의 검증 (필요 없다고 인정되면 생략 가능)","결정·공시일부터 30일 이내, 시장·군수·구청장"],["표준주택가격","국토교통부장관","한국부동산원에 의뢰","공시일부터 30일 이내, 국토교통부장관 (제7조 준용)"],["개별주택가격","시장·군수·구청장","한국부동산원의 검증 (생략 가능)","30일 이내, 시장·군수·구청장 (제11조 준용)"],["공동주택가격","국토교통부장관","한국부동산원에 의뢰","공시일부터 30일 이내, 국토교통부장관 (제7조 준용)"]]},{"종류":"표","제목":"결정·공시 기한과 기준일 이후 사유 처리 (시행령)","머리":["구분","공시기준일","결정·공시 기한","기준일 이후 분할·합병 등이 발생한 경우"],"행":[["개별공시지가","1월 1일","매년 5월 31일까지","1.1~6.30 사유는 그 해 7월 1일 기준, 7.1~12.31 사유는 다음 해 1월 1일 기준"],["개별주택가격","1월 1일","매년 4월 30일까지","1.1~5.31 사유는 그 해 6월 1일 기준, 6.1~12.31 사유는 다음 해 1월 1일 기준"],["공동주택가격","1월 1일","매년 4월 30일까지","1.1~5.31 사유는 그 해 6월 1일 기준, 6.1~12.31 사유는 다음 해 1월 1일 기준"]]}],"함정":"표준지·표준주택·공동주택 가격은 국토교통부장관, 개별공시지가·개별주택가격은 시장·군수·구청장이 공시한다. 검증 기관도 개별공시지가는 감정평가법인등, 개별주택가격은 한국부동산원으로 갈린다. 검증을 받는 쪽을 서로 바꾼 선지가 자주 나온다."}},{"i":"S5-1-1-민법-01","r":"S5","g":1,"c":1,"n":41,"s":"민법","q":"반사회질서의 법률행위에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["법률행위가 사회질서에 반하는지는 법률행위 성립 후 변화된 가치관념을 기준으로 판단한다.","반사회질서의 법률행위는 무효이지만, 그 무효를 선의의 제3자에게는 대항하지 못한다.","반사회질서의 법률행위에 따라 급부를 이행한 자는 불법의 원인이 자신에게도 있다면 그 급부의 반환을 청구하지 못한다.","형사사건에서 변호사가 의뢰인과 체결한 성공보수약정은 그 액수가 적정하면 반사회질서의 법률행위가 아니다.","부동산 이중매매에서 제2매수인이 매도인과 제1매수인 사이의 매매 사실을 알고 매수하였다면, 배임행위에 적극 가담하지 않았더라도 제2매매는 무효이다."],"a":[3],"L":"민1-1","o":"변형","x":{"한줄":"반사회질서의 법률행위에 따라 이행한 급부는 불법의 원인이 급부자에게도 있으면 반환을 청구하지 못한다.","근거":[{"법령":"민법","조문":"제103조","원문":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"법령":"민법","조문":"제746조","원문":"불법의 원인으로 인하여 재산을 급여하거나 노무를 제공한 때에는 그 이익의 반환을 청구하지 못한다. 그러나 그 불법원인이 수익자에게만 있는 때에는 그러하지 아니하다."},{"판례":"대법원 판례(판단 시점)","요지":"반사회질서 여부는 법률행위가 이루어진 때를 기준으로 판단한다. 이후 사회 가치관이 변해도 달라지지 않는다."},{"판례":"대법원 판례(이중매매)","요지":"제2매수인이 매도인의 배임행위에 적극 가담한 경우에 제2매매가 무효이다. 이미 매매된 사실을 알고 매수한 것만으로는 무효가 아니다."},{"판례":"대법원 전원합의체 판례(성공보수)","요지":"형사사건의 성공보수약정은 선량한 풍속 기타 사회질서에 반하여 무효이다. 민사사건의 성공보수약정은 적정한 범위에서 유효하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"반사회질서 여부는 법률행위가 이루어진 때를 기준으로 판단한다. 성립 후 가치관이 변해도 유효·무효가 달라지지 않는다."},{"번호":2,"판정":"틀림","설명":"제103조의 무효는 절대적 무효이다. 제108조제2항 같은 선의 제3자 보호 규정이 없어 선의의 제3자에게도 무효를 주장할 수 있다."},{"번호":3,"판정":"옳음","설명":"불법원인급여는 반환을 청구하지 못한다(제746조 본문). 불법의 원인이 수익자에게만 있으면 반환을 청구할 수 있다(같은 조 단서)."},{"번호":4,"판정":"틀림","설명":"형사사건의 성공보수약정은 액수가 적정해도 무효이다(대법원 전원합의체). 적정한 범위에서 유효한 것은 민사사건의 성공보수약정이다."},{"번호":5,"판정":"틀림","설명":"제2매수인이 이미 매매된 사실을 안 것만으로는 무효가 아니다. 매도인의 배임행위에 적극 가담해야 제103조에 해당한다."}],"개념":[{"종류":"표","제목":"반사회질서 해당 여부 사례","머리":["구분","사례","결과"],"행":[["무효","보험금을 부정취득할 목적으로 체결한 다수의 보험계약","제103조 무효, 보험자가 선의여도 같다"],["무효","매도인의 배임행위에 적극 가담한 제2매수인과의 이중매매","제2매매 무효, 제1매수인은 매도인을 대위하여 말소를 구할 수 있다"],["무효","형사사건의 성공보수약정","액수가 적정해도 무효(전원합의체)"],["무효","허위 증언의 대가를 주기로 한 약정","무효, 진실한 증언의 일당·여비 상당액 약정은 유효"],["유효","이미 매매된 사실을 알고 매수한 이중매매(적극 가담 없음)","유효, 자유경쟁의 범위"],["유효","반사회적 행위로 조성된 비자금을 소극적으로 은닉하는 임치","유효"]]},{"종류":"표","제목":"제103조와 제104조 비교","머리":["구분","제103조 반사회질서","제104조 불공정"],"행":[["요건","내용이 선량한 풍속 기타 사회질서에 반함","궁박·경솔·무경험 + 현저한 불균형 + 상대방의 악용 의사"],["판단 시점","법률행위 성립 시","법률행위 성립 시"],["효과","절대적 무효, 추인해도 유효가 되지 않음","절대적 무효, 추인해도 유효가 되지 않음"],["선의 제3자 보호","규정 없음","규정 없음"],["불법원인급여(제746조)","적용됨","적용되지 않음(판례)"]]}],"함정":"이중매매는 매수인이 매매 사실을 아는 것만으로 무효가 되지 않고, 매도인의 배임행위에 적극 가담해야 무효이다. 성공보수약정은 형사사건이 무효, 민사사건이 적정 범위에서 유효이다. 선의 제3자 보호 규정은 허위표시(제108조제2항)에만 있고 제103조에는 없다."}},{"i":"S5-1-1-민법-02","r":"S5","g":1,"c":1,"n":42,"s":"민법","q":"상대방 있는 단독행위에 해당하지 않는 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["공유지분의 포기","무권대리행위의 추인","상계의 의사표시","취득시효 이익의 포기","재단법인의 설립행위"],"a":[5],"L":"민1-1","o":"기출","x":{"한줄":"재단법인의 설립행위는 상대방 없는 단독행위이고, 나머지는 모두 상대방에게 하는 단독행위이다.","근거":[{"법령":"민법","조문":"제43조","원문":"재단법인의 설립자는 일정한 재산을 출연하고 제40조제1호 내지 제5호의 사항을 기재한 정관을 작성하여 기명날인하여야 한다."},{"법령":"민법","조문":"제493조제1항","원문":"①상계는 상대방에 대한 의사표시로 한다. 이 의사표시에는 조건 또는 기한을 붙이지 못한다."},{"법령":"민법","조문":"제132조","원문":"추인 또는 거절의 의사표시는 상대방에 대하여 하지 아니하면 그 상대방에 대항하지 못한다. 그러나 상대방이 그 사실을 안 때에는 그러하지 아니하다."},{"이론":"법률행위의 분류","내용":"단독행위는 상대방 있는 것(동의·철회·추인·취소·해제·해지·상계·채무면제)과 상대방 없는 것(유언·재단법인 설립·소유권 포기)으로 나뉜다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공유지분의 포기는 다른 공유자에게 하는 상대방 있는 단독행위이다. 포기한 지분은 다른 공유자에게 귀속한다(제267조)."},{"번호":2,"판정":"옳음","설명":"추인은 상대방 또는 무권대리인에 대한 의사표시로 한다(제132조). 상대방 있는 단독행위이다."},{"번호":3,"판정":"옳음","설명":"상계는 상대방에 대한 의사표시로 한다(제493조제1항). 상대방 있는 단독행위이다."},{"번호":4,"판정":"옳음","설명":"시효이익의 포기는 시효로 불이익을 받는 상대방에 대한 의사표시로 하는 단독행위이다."},{"번호":5,"판정":"틀림","설명":"재단법인의 설립행위는 설립자가 재산을 출연하고 정관을 작성하는 행위로, 상대방이 없다(제43조)."}],"개념":[{"종류":"표","제목":"법률행위의 분류","머리":["구분","의미","예"],"행":[["상대방 없는 단독행위","의사표시 하나로 성립하고 상대방이 없음","유언, 재단법인 설립, 소유권 포기"],["상대방 있는 단독행위","의사표시 하나로 성립하고 상대방에게 하는 것","동의, 철회, 추인, 취소, 해제, 해지, 상계, 채무면제, 공유지분 포기"],["계약","서로 대립하는 두 개의 의사표시가 합치","매매, 임대차, 합의해제"],["합동행위","방향이 같은 여러 의사표시가 합치","사단법인 설립행위"]]}],"함정":"상대방 없는 단독행위는 유언, 재단법인 설립, 소유권 포기로 한정된다. 추인·상계·취소·해제·채무면제는 모두 상대방에게 하는 행위이다. 사단법인 설립은 합동행위이다."}},{"i":"S5-1-1-민법-03","r":"S5","g":1,"c":1,"n":43,"s":"민법","q":"의사표시의 효력발생에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["표의자가 청약의 의사표시를 발송한 후 사망하면 그 청약은 효력을 잃는다.","의사표시가 도달하였다고 하려면 상대방이 그 내용을 실제로 읽어 알아야 한다.","상대방이 정당한 사유 없이 우편물의 수취를 거절한 경우에도, 그 내용을 알 수 있는 객관적 상태에 놓인 때에 의사표시가 도달한 것으로 본다.","의사표시가 상대방에게 도달한 후라도 상대방이 아직 그 내용을 알지 못했다면 표의자는 이를 철회할 수 있다.","표의자가 과실로 상대방의 소재를 알지 못하는 경우에도 공시송달의 방법으로 의사표시를 할 수 있다."],"a":[3],"L":"민1-2","o":"변형","x":{"한줄":"상대방이 수령을 거절해도 그 내용을 알 수 있는 객관적 상태에 놓이면 의사표시가 도달한 것으로 본다.","근거":[{"법령":"민법","조문":"제111조","원문":"① 상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생긴다. ② 의사표시자가 그 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제113조","원문":"표의자가 과실없이 상대방을 알지 못하거나 상대방의 소재를 알지 못하는 경우에는 의사표시는 민사소송법 공시송달의 규정에 의하여 송달할 수 있다."},{"판례":"대법원 판례(도달의 의미)","요지":"도달은 의사표시가 상대방의 지배 영역 안에 들어가 사회통념상 상대방이 알 수 있는 객관적 상태에 놓인 것을 뜻한다. 상대방이 실제로 내용을 알 필요는 없다."},{"판례":"대법원 판례(수령 거절)","요지":"상대방이 정당한 사유 없이 우편물의 수취를 거절한 경우, 그 우편물은 수취 가능한 상태에 놓인 때에 도달한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"표의자가 발송 후 사망해도 의사표시의 효력에는 영향이 없다(제111조제2항)."},{"번호":2,"판정":"틀림","설명":"도달은 상대방이 알 수 있는 객관적 상태에 놓이면 충분하다. 내용을 실제로 읽어 알 필요가 없다."},{"번호":3,"판정":"옳음","설명":"수령 거절에 정당한 사유가 없으면 거절한 우편물도 수취 가능한 상태에 놓인 때에 도달한 것으로 본다."},{"번호":4,"판정":"틀림","설명":"도달한 의사표시는 상대방이 내용을 알기 전이라도 철회할 수 없다. 철회가 가능하려면 철회의 통지가 먼저 또는 동시에 도달해야 한다."},{"번호":5,"판정":"틀림","설명":"공시송달은 표의자가 과실 없이 상대방이나 그 소재를 알지 못하는 경우에 쓴다(제113조)."}],"개념":[{"종류":"표","제목":"의사표시 효력발생 시기 정리","머리":["구분","내용","근거"],"행":[["원칙","상대방 있는 의사표시는 상대방에게 도달한 때 효력 발생(도달주의)","제111조제1항"],["발송 후 사정 변경","발송 후 표의자의 사망·제한능력에도 효력에 영향 없음","제111조제2항"],["상대방이 제한능력자","의사표시로 대항하지 못함, 법정대리인이 도달 사실을 안 후에는 가능","제112조"],["공시송달","표의자가 과실 없이 상대방이나 소재를 모를 때 민사소송법의 공시송달 규정에 따름","제113조"],["발신주의 예외","격지자 간 계약은 승낙 통지를 발송한 때 성립, 제한능력자 상대방의 확답 촉구는 확답 발송 기준","제531조, 제15조"]]}],"함정":"도달은 상대방이 알 수 있는 상태에 놓이는 것으로 족하고 요지는 필요 없다. 도달한 의사표시는 상대방이 내용을 알기 전에도 철회할 수 없다. 발송 후 표의자가 사망해도 효력은 그대로이다(제111조제2항)."}},{"i":"S5-1-1-민법-04","r":"S5","g":1,"c":1,"n":44,"s":"민법","q":"통정허위표시(민법 제108조)에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["통정허위표시는 표의자가 의식적으로 진의와 다른 표시를 한다는 것을 상대방이 알았다면 성립한다.","가장행위가 무효이면 당연히 은닉행위도 무효이다.","대리인이 본인 몰래 대리권의 범위 안에서 상대방과 통정허위표시를 한 경우, 본인은 선의의 제3자로서 그 유효를 주장할 수 있다.","민법 제108조제2항에 따라 보호받는 선의의 제3자에 대해서는 그 누구도 통정허위표시의 무효로써 대항할 수 없다.","가장소비대차에 따른 대여금채권의 선의의 양수인은 민법 제108조제2항에 따라 보호받는 제3자가 아니다."],"a":[4],"L":"민1-2","o":"기출","x":{"한줄":"제108조제2항에 따라 보호받는 선의의 제3자에게는 누구도 허위표시의 무효로 대항하지 못한다.","근거":[{"법령":"민법","조문":"제108조","원문":"①상대방과 통정한 허위의 의사표시는 무효로 한다. ②전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"법령":"민법","조문":"제107조제1항","원문":"①의사표시는 표의자가 진의아님을 알고 한 것이라도 그 효력이 있다. 그러나 상대방이 표의자의 진의아님을 알았거나 이를 알 수 있었을 경우에는 무효로 한다."},{"판례":"대법원 판례(제3자의 범위)","요지":"허위표시의 당사자와 포괄승계인 이외의 자로서 허위표시에 기초하여 새로운 이해관계를 맺은 자가 제3자이다. 가장소비대차의 대여금채권을 양수한 자, 가장 매수인으로부터 저당권을 취득한 자가 이에 해당한다. 대리인이 허위표시를 한 경우 본인은 제3자가 아니다."}],"선지":[{"번호":1,"판정":"틀림","설명":"통정은 상대방과 합의하여 허위의 표시를 하는 것이다. 상대방이 진의 아님을 알기만 한 경우는 비진의표시(제107조제1항 단서)의 문제이다."},{"번호":2,"판정":"틀림","설명":"가장행위가 무효여도 은닉행위는 그 자체의 요건을 갖추어야 유효하다. 은닉행위가 당연히 무효가 되는 것은 아니다."},{"번호":3,"판정":"틀림","설명":"대리행위의 효과는 본인에게 귀속되므로 본인은 허위표시의 당사자와 같은 지위이다. 제3자에 해당하지 않는다."},{"번호":4,"판정":"옳음","설명":"제108조제2항의 선의 제3자에게는 표의자, 상대방, 그 승계인 누구도 무효로 대항하지 못한다."},{"번호":5,"판정":"틀림","설명":"가장소비대차의 대여금채권을 양수한 선의의 양수인은 허위표시에 기초하여 새로 이해관계를 맺은 제3자로서 보호받는다."}],"개념":[{"종류":"표","제목":"제108조제2항의 제3자 해당 여부","머리":["구분","사례","제3자 해당"],"행":[["해당","가장소비대차 대여금채권의 양수인","해당"],["해당","허위표시로 이전등기를 받은 자로부터 저당권을 취득한 자","해당"],["해당","가장채권을 압류한 채권자","해당"],["해당하지 않음","대리인이 한 허위표시에서의 본인","해당하지 않음"],["해당하지 않음","당사자의 상속인 등 포괄승계인","해당하지 않음"],["해당하지 않음","채권 가장양도에서의 채무자","해당하지 않음"],["해당하지 않음","허위표시 목적물에 대한 일반 채권자","해당하지 않음"]]},{"종류":"표","제목":"진의 아닌 표시와 통정허위표시 비교","머리":["구분","비진의표시(제107조)","통정허위표시(제108조)"],"행":[["상대방과의 통정","없음","있음"],["무효 요건","상대방이 진의 아님을 알았거나 알 수 있었을 때","상대방과 통정한 허위의 표시이면 무효"],["선의 제3자 보호","있음(제107조제2항)","있음(제108조제2항)"],["제3자의 선의 증명","무효를 주장하는 자가 제3자의 악의를 증명","무효를 주장하는 자가 제3자의 악의를 증명"]]}],"함정":"상대방이 진의 아님을 알기만 한 경우는 비진의표시이고 통정허위표시가 아니다. 대리인이 한 허위표시에서 본인은 제3자가 아니다. 가장채권의 양수인은 보호되는 제3자이다."}},{"i":"S5-1-1-민법-05","r":"S5","g":1,"c":1,"n":45,"s":"민법","q":"대리권 없는 乙이 甲을 대리하여 丙에게 甲 소유의 토지를 매도하였다. 이에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["丙은 계약 당시 乙에게 대리권이 없음을 알았더라도, 甲의 추인이 있기 전에는 계약을 철회할 수 있다.","甲이 乙에게 추인의 의사표시를 한 경우, 丙이 그 사실을 알았더라도 甲은 丙에게 추인의 효과를 주장할 수 없다.","甲이 乙의 행위가 무권대리임을 알지 못한 채 추인하였더라도 추인은 유효하다.","甲이 사망하여 乙이 甲을 단독상속한 경우, 乙은 본인의 지위에서 추인을 거절하는 것이 신의칙상 허용되지 않는다.","丙이 乙에게 대리권이 없음을 알지 못하였고 알지 못한 데 과실이 없다면, 乙이 미성년자여도 丙은 乙에게 계약의 이행이나 손해배상을 청구할 수 있다."],"a":[4],"L":"민1-3","o":"변형","x":{"한줄":"무권대리인이 본인을 단독상속하면 본인의 지위에서 추인을 거절하는 것은 신의칙상 허용되지 않는다.","근거":[{"법령":"민법","조문":"제134조","원문":"대리권없는 자가 한 계약은 본인의 추인이 있을 때까지 상대방은 본인이나 그 대리인에 대하여 이를 철회할 수 있다. 그러나 계약당시에 상대방이 대리권 없음을 안 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제132조","원문":"추인 또는 거절의 의사표시는 상대방에 대하여 하지 아니하면 그 상대방에 대항하지 못한다. 그러나 상대방이 그 사실을 안 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제135조","원문":"① 다른 자의 대리인으로서 계약을 맺은 자가 그 대리권을 증명하지 못하고 또 본인의 추인을 받지 못한 경우에는 그는 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다. ② 대리인으로서 계약을 맺은 자에게 대리권이 없다는 사실을 상대방이 알았거나 알 수 있었을 때 또는 대리인으로서 계약을 맺은 사람이 제한능력자일 때에는 제1항을 적용하지 아니한다."},{"판례":"대법원 판례(추인)","요지":"추인은 무권대리행위임을 알고 해야 효력이 있다."},{"판례":"대법원 판례(단독상속)","요지":"무권대리인이 본인을 단독상속하면 본인 지위에서 추인을 거절하는 것은 신의칙상 허용되지 않는다. 반대로 본인이 무권대리인을 상속한 경우에는 추인을 거절해도 신의칙에 반하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"철회권은 계약 당시 대리권 없음을 모른 선의의 상대방에게만 있다. 알았던 상대방은 철회하지 못한다(제134조 단서)."},{"번호":2,"판정":"틀림","설명":"본인이 무권대리인에게 추인해도 상대방에게는 대항하지 못하지만, 상대방이 그 사실을 안 때에는 대항할 수 있다(제132조 단서)."},{"번호":3,"판정":"틀림","설명":"추인은 무권대리행위가 있음을 알고 해야 효력이 생긴다는 것이 판례이다."},{"번호":4,"판정":"옳음","설명":"무권대리인이 본인을 단독상속하면 추인거절권을 행사하는 것은 신의칙에 반한다. 본인의 지위와 무권대리인의 지위가 한 사람에게 합쳐졌기 때문이다."},{"번호":5,"판정":"틀림","설명":"무권대리인이 제한능력자이면 제135조제1항의 책임이 없다(같은 조 제2항). 상대방이 선의·무과실이어도 같다."}],"개념":[{"종류":"표","제목":"무권대리에서 상대방 보호 수단","머리":["수단","요건","효과"],"행":[["최고권(제131조)","선의·악의 불문","상당한 기간 안에 본인이 확답을 발하지 않으면 추인거절로 간주"],["철회권(제134조)","계약 당시 선의, 본인의 추인 전까지","계약을 철회하면 계약이 확정적으로 무효"],["무권대리인 책임(제135조)","상대방 선의·무과실, 무권대리인이 행위능력자이고 본인의 추인이 없음","상대방의 선택에 따라 계약 이행 또는 손해배상"],["표현대리 주장(제125조·제126조·제129조)","각 조문의 요건 충족","본인에게 유권대리와 같은 책임"],["본인의 추인(제133조)","무권대리임을 알고 상대방 또는 무권대리인에게 의사표시","다른 의사표시가 없으면 계약 시로 소급해 유효"]]}],"함정":"무권대리인이 제한능력자이면 제135조의 책임이 없다. 철회권은 선의의 상대방에게만 있고, 본인이 무권대리인에게 한 추인은 상대방이 안 때에는 상대방에게도 대항할 수 있다."}},{"i":"S5-1-1-민법-06","r":"S5","g":1,"c":1,"n":46,"s":"민법","q":"민법상 대리에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임의대리인이 수인(數人)인 경우, 대리인은 원칙적으로 공동으로 대리해야 한다.","대리행위의 하자로 인한 취소권은 원칙적으로 대리인에게 귀속된다.","대리인을 통한 부동산거래에서 상대방 앞으로 소유권이전등기가 마쳐진 경우, 대리권 유무에 대한 증명책임은 대리행위의 유효를 주장하는 상대방에게 있다.","복대리인은 대리인이 자신의 이름으로 선임한 대리인의 대리인이다.","법정대리인은 특별한 사정이 없는 한 그 책임으로 복대리인을 선임할 수 있다."],"a":[5],"L":"민1-3","o":"기출","x":{"한줄":"법정대리인은 자기 책임으로 복대리인을 선임할 수 있다(제122조).","근거":[{"법령":"민법","조문":"제122조","원문":"법정대리인은 그 책임으로 복대리인을 선임할 수 있다. 그러나 부득이한 사유로 인한 때에는 전조제1항에 정한 책임만이 있다."},{"법령":"민법","조문":"제119조","원문":"대리인이 수인인 때에는 각자가 본인을 대리한다. 그러나 법률 또는 수권행위에 다른 정한 바가 있는 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제123조","원문":"①복대리인은 그 권한내에서 본인을 대리한다."},{"판례":"대법원 판례(증명책임)","요지":"등기가 마쳐져 있으면 그 원인과 절차가 적법한 것으로 추정되므로, 대리권이 없었다고 다투는 쪽이 증명책임을 진다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대리인이 수인이면 각자가 본인을 대리한다(제119조). 공동대리는 법률이나 수권행위에 정한 경우에 한한다."},{"번호":2,"판정":"틀림","설명":"대리행위의 하자로 인한 취소권은 법률행위의 당사자인 본인에게 귀속한다. 대리인이 취소하려면 별도의 수권이 있어야 한다."},{"번호":3,"판정":"틀림","설명":"등기가 마쳐진 경우 적법하게 이루어진 것으로 추정되어, 대리권 없음을 주장하는 쪽에 증명책임이 있다."},{"번호":4,"판정":"틀림","설명":"복대리인은 대리인이 본인의 이름으로 선임한, 본인의 대리인이다(제123조제1항)."},{"번호":5,"판정":"옳음","설명":"법정대리인은 자유롭게 복대리인을 선임할 수 있고 그 대신 선임·감독의 전 책임을 진다(제122조). 부득이한 사유로 선임한 때에는 선임·감독 책임만 진다."}],"개념":[{"종류":"표","제목":"복임권과 복대리인 선임의 책임","머리":["구분","임의대리인","법정대리인"],"행":[["복임권","본인의 승낙이 있거나 부득이한 사유가 있을 때만(제120조)","자유롭게 가능(제122조)"],["선임·감독 책임","본인에 대해 선임·감독 책임(제121조제1항)","원칙적으로 전 책임, 부득이한 사유로 선임했으면 선임·감독 책임만(제122조)"],["본인이 지명한 복대리인","부적임·불성실을 알고 통지나 해임을 게을리한 때만 책임(제121조제2항)","해당 없음"],["복대리인의 지위","본인의 대리인, 본인·제3자에 대해 대리인과 동일한 권리의무(제123조)","같음"]]},{"종류":"표","제목":"대리인 관련 기준","머리":["쟁점","기준","근거"],"행":[["의사표시의 하자·악의·과실 판단","대리인을 기준으로 결정","제116조제1항"],["본인이 특정 행위를 지시한 경우","본인이 안 사정은 대리인의 부지를 주장하지 못함","제116조제2항"],["대리인의 행위능력","필요 없음","제117조"],["수인의 대리인","각자 대리가 원칙","제119조"]]}],"함정":"등기가 있으면 대리권 없음을 주장하는 쪽이 증명한다. 복대리인은 본인의 대리인이다. 수인의 대리인은 각자 대리하는 것이 원칙이다."}},{"i":"S5-1-1-민법-07","r":"S5","g":1,"c":1,"n":47,"s":"민법","q":"표현대리에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["본인이 타인에게 대리권을 수여하지 않았지만 수여하였다고 상대방에게 통보한 경우, 그 타인이 통보받은 상대방 외의 자와 본인을 대리하여 행위를 한 때는 민법 제125조의 표현대리가 적용된다.","표현대리가 성립하는 경우, 과실상계의 법리를 유추적용하여 본인의 책임을 경감할 수 있다.","민법 제129조의 표현대리를 기본대리권으로 하는 민법 제126조의 표현대리는 성립될 수 없다.","대리행위가 강행법규에 위반하여 무효인 경우에는 표현대리의 법리가 적용되지 않는다.","유권대리의 주장 속에는 표현대리의 주장이 포함되어 있다."],"a":[4],"L":"민1-3","o":"기출","x":{"한줄":"대리행위 자체가 강행법규 위반으로 무효이면 표현대리의 법리가 적용되지 않는다.","근거":[{"법령":"민법","조문":"제125조","원문":"제삼자에 대하여 타인에게 대리권을 수여함을 표시한 자는 그 대리권의 범위내에서 행한 그 타인과 그 제삼자간의 법률행위에 대하여 책임이 있다. 그러나 제삼자가 대리권없음을 알았거나 알 수 있었을 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제126조","원문":"대리인이 그 권한외의 법률행위를 한 경우에 제삼자가 그 권한이 있다고 믿을 만한 정당한 이유가 있는 때에는 본인은 그 행위에 대하여 책임이 있다."},{"법령":"민법","조문":"제129조","원문":"대리권의 소멸은 선의의 제삼자에게 대항하지 못한다. 그러나 제삼자가 과실로 인하여 그 사실을 알지 못한 때에는 그러하지 아니하다."},{"판례":"대법원 판례(표현대리의 적용 범위)","요지":"표현대리는 대리권의 흠결을 보충하는 제도라서 대리행위 자체가 강행법규 위반으로 무효이면 적용되지 않는다. 표현대리가 성립하면 본인은 전부 책임을 지고 과실상계를 하지 못한다."},{"판례":"대법원 전원합의체 판례(유권대리와 표현대리)","요지":"유권대리의 주장에는 표현대리의 주장이 포함되지 않는다. 별개의 요건사실이므로 당사자가 따로 주장해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"제125조는 대리권 수여를 통보받은 상대방에 대해서만 성립한다. 통보받지 않은 제3자에 대해서는 적용되지 않는다."},{"번호":2,"판정":"틀림","설명":"표현대리가 성립하면 본인은 전부 책임을 진다. 과실상계를 유추적용하여 책임을 줄일 수 없다."},{"번호":3,"판정":"틀림","설명":"제129조의 표현대리를 기본대리권으로 하여 제126조의 표현대리가 성립할 수 있다(판례)."},{"번호":4,"판정":"옳음","설명":"대리행위가 강행법규를 위반해 무효이면 표현대리를 적용할 여지가 없다. 표현대리는 유효한 대리행위의 대리권 흠결만 보충한다."},{"번호":5,"판정":"틀림","설명":"유권대리의 주장에는 표현대리의 주장이 포함되지 않는다. 법원이 당사자의 주장 없이 표현대리를 인정할 수 없다."}],"개념":[{"종류":"표","제목":"표현대리 3유형 비교","머리":["구분","제125조(수권표시)","제126조(권한초과)","제129조(소멸 후)"],"행":[["전제","대리권을 수여하지 않았으나 수여했다고 상대방에게 표시","기본대리권이 있는 대리인이 권한 밖의 행위","대리권이 있었다가 소멸"],["상대방 요건","표시를 받은 상대방, 대리권 없음을 알지 못하고 알 수도 없었을 것","권한이 있다고 믿을 만한 정당한 이유","선의이고 과실이 없을 것"],["본인의 책임","표시한 대리권의 범위 안에서 책임","행위 전체에 대해 책임","소멸 전 대리권의 범위 안에서 책임"],["판례 포인트","통보받지 않은 제3자에게는 적용되지 않음","기본대리권이 없으면 성립하지 않음","소멸 후 권한 밖 행위를 하면 제126조와 중첩해 성립 가능"]]}],"함정":"유권대리의 주장에는 표현대리의 주장이 포함되지 않는다. 제129조의 표현대리를 기본대리권으로 제126조의 표현대리가 성립할 수 있다. 표현대리가 성립하면 본인은 전부 책임을 지고 과실상계는 없다."}},{"i":"S5-1-1-민법-08","r":"S5","g":1,"c":1,"n":48,"s":"민법","q":"무효와 취소에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["취소권은 추인할 수 있는 날부터 10년 내, 법률행위를 한 날부터 3년 내에 행사하여야 한다.","당사자가 무효임을 알고 무효인 법률행위를 추인하면 그 법률행위 시로 소급하여 유효가 된다.","토지거래허가구역 내 토지의 매매계약이 허가를 받기 전의 유동적 무효 상태에서 허가를 받으면 계약 시로 소급하여 유효가 된다.","취소된 법률행위는 취소한 때부터 장래를 향하여 무효가 된다.","제한능력을 이유로 취소할 수 있는 법률행위는 제한능력자가 능력자가 되기 전에는 그 법정대리인도 추인할 수 없다."],"a":[3],"L":"민1-4","o":"변형","x":{"한줄":"허가구역 내 토지거래계약은 허가를 받으면 유동적 무효 상태에서 계약 시로 소급하여 유효가 된다.","근거":[{"법령":"민법","조문":"제146조","원문":"취소권은 추인할 수 있는 날로부터 3년내에 법률행위를 한 날로부터 10년내에 행사하여야 한다."},{"법령":"민법","조문":"제139조","원문":"무효인 법률행위는 추인하여도 그 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다."},{"법령":"민법","조문":"제141조","원문":"취소된 법률행위는 처음부터 무효인 것으로 본다. 다만, 제한능력자는 그 행위로 인하여 받은 이익이 현존하는 한도에서 상환(償還)할 책임이 있다."},{"법령":"민법","조문":"제144조","원문":"① 추인은 취소의 원인이 소멸된 후에 하여야만 효력이 있다. ② 제1항은 법정대리인 또는 후견인이 추인하는 경우에는 적용하지 아니한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제11조제6항","원문":"제1항에 따른 허가를 받지 아니하고 체결한 토지거래계약은 그 효력이 발생하지 아니한다."},{"판례":"대법원 전원합의체 판례(유동적 무효)","요지":"허가를 받기 전의 계약은 유동적 무효이다. 허가를 받으면 소급하여 유효가 되고, 불허가되거나 허가를 배제·잠탈하는 합의를 한 경우는 확정적으로 무효가 된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"취소권은 추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년 안에 행사한다(제146조). 기간이 뒤바뀌었다."},{"번호":2,"판정":"틀림","설명":"무효를 알고 추인한 때에는 새로운 법률행위로 본다(제139조 단서). 소급하여 유효가 되지 않는다."},{"번호":3,"판정":"옳음","설명":"허가를 받으면 유동적 무효였던 계약이 소급하여 유효가 된다. 허가를 받기 전에는 이행 청구를 할 수 없고 허가신청 협력을 청구할 수 있을 뿐이다."},{"번호":4,"판정":"틀림","설명":"취소된 법률행위는 처음부터 무효인 것으로 본다(제141조 본문)."},{"번호":5,"판정":"틀림","설명":"법정대리인 또는 후견인이 추인하는 경우에는 취소의 원인이 소멸하기 전에도 추인할 수 있다(제144조제2항)."}],"개념":[{"종류":"비교","제목":"무효와 취소 비교","왼쪽":{"이름":"무효","항목":["처음부터 당연히 효력이 없음","누구든지, 누구에게든 주장할 수 있음","주장 기간의 제한이 없음","추인해도 유효가 되지 않고, 무효임을 알고 추인하면 새로운 법률행위로 봄(제139조)"]},"오른쪽":{"이름":"취소","항목":["취소권자가 취소하기 전까지는 유효","취소권자는 제한능력자, 착오·사기·강박으로 표시한 자, 그 대리인·승계인(제140조)","추인할 수 있는 날부터 3년, 행위한 날부터 10년(제146조)","취소 전에 추인할 수 있고 취소하면 처음부터 무효(제141조)"]}},{"종류":"표","제목":"토지거래허가구역 안 계약의 효력","머리":["상황","효력","비고"],"행":[["허가를 받기 전","유동적 무효","이행 청구 불가, 허가신청 협력의무 청구 가능"],["허가를 받음","소급하여 유효","계약 시부터 유효"],["불허가 처분을 받음","확정적 무효","그 계약은 더 이상 유효가 될 수 없음"],["허가를 배제·잠탈하는 계약","확정적 무효","처음부터 허가를 받을 의사가 없는 계약"],["허가구역 지정 해제 또는 허가 불필요","확정적 유효","별도 허가 없이 계약이 유효로 확정"]]}],"함정":"취소권은 추인할 수 있는 날부터 3년, 행위한 날부터 10년이다. 무효행위를 알고 추인하면 새로운 법률행위가 되고 소급하지 않는다. 법정대리인은 취소원인이 소멸하기 전에도 추인할 수 있다(제144조제2항)."}},{"i":"S5-1-1-민법-09","r":"S5","g":1,"c":1,"n":49,"s":"민법","q":"甲의 기망으로 乙은 甲 소유의 토지를 매수하는 계약을 체결하였다. 乙이 이 계약을 취소할 수 있는 경우에 법정추인에 해당하는 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙이 사기 사실을 알게 된 후 이의를 보류하지 않고 甲에게 대금의 일부를 지급한 경우","甲이 乙에게 잔대금의 지급을 청구한 경우","乙이 사기 사실을 알기 전에 甲에게 대금 전부를 지급한 경우","乙이 사기 사실을 알게 된 후 취소권이 있음을 甲에게 밝히면서 이의를 보류하고 대금의 일부를 지급한 경우","乙이 사기 사실을 알게 된 후 계약을 취소한다는 의사표시를 하고 이미 지급한 계약금의 반환을 청구한 경우"],"a":[1],"L":"민1-4","o":"변형","x":{"한줄":"취소권자가 추인할 수 있는 상태에서 이의를 보류하지 않고 이행하면 법정추인이 된다(제145조제1호).","근거":[{"법령":"민법","조문":"제145조","원문":"취소할 수 있는 법률행위에 관하여 전조의 규정에 의하여 추인할 수 있는 후에 다음 각호의 사유가 있으면 추인한 것으로 본다. 그러나 이의를 보류한 때에는 그러하지 아니하다. 1. 전부나 일부의 이행 2. 이행의 청구 3. 경개 4. 담보의 제공 5. 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도 6. 강제집행"},{"법령":"민법","조문":"제144조","원문":"① 추인은 취소의 원인이 소멸된 후에 하여야만 효력이 있다."},{"판례":"대법원 판례(법정추인의 주체)","요지":"법정추인 사유는 취소권자가 한 행위여야 한다. 상대방이 취소권자에게 이행을 청구한 경우는 해당하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"취소원인이 소멸한 후 이의 없이 한 일부 이행은 법정추인 사유이다(제145조제1호)."},{"번호":2,"판정":"틀림","설명":"이행의 청구가 법정추인이 되려면 취소권자가 청구해야 한다. 상대방 甲이 청구한 것은 해당하지 않는다."},{"번호":3,"판정":"틀림","설명":"법정추인은 추인할 수 있는 후, 즉 취소의 원인이 소멸한 후에 한 행위여야 한다(제145조 본문, 제144조제1항). 사기를 알기 전의 이행은 해당하지 않는다."},{"번호":4,"판정":"틀림","설명":"이의를 보류하고 한 행위는 법정추인이 되지 않는다(제145조 단서)."},{"번호":5,"판정":"틀림","설명":"취소의 의사표시와 그에 따른 반환 청구는 취소권의 행사이다. 법정추인 사유가 아니다."}],"개념":[{"종류":"표","제목":"법정추인 사유(제145조)","머리":["호","사유","주의"],"행":[["1","전부나 일부의 이행","취소권자가 이행하거나 상대방의 이행을 수령하는 경우 포함(판례)"],["2","이행의 청구","취소권자가 청구하는 경우만, 상대방의 청구는 해당 없음"],["3","경개","취소권자가 상대방과 경개계약을 한 경우"],["4","담보의 제공","취소권자가 담보를 제공하거나 상대방이 제공한 담보를 받는 경우"],["5","취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도","취소권자가 양도한 경우"],["6","강제집행","취소권자가 강제집행을 하는 경우"]]},{"종류":"표","제목":"추인의 요건","머리":["구분","제한능력자 본인","법정대리인·후견인"],"행":[["추인 시기","능력자가 된 후(제144조제1항)","취소원인 소멸 전에도 가능(제144조제2항)"],["법정추인","추인할 수 있는 후의 행위만 해당","같음"],["이의의 보류","보류하면 법정추인 안 됨","같음"],["취소권 소멸","추인할 수 있는 날부터 3년, 행위한 날부터 10년","같음"]]}],"함정":"선지 3은 취소원인이 소멸하기 전의 이행으로, 추인할 수 있는 후의 행위가 아니다. 선지 2는 상대방이 한 행위이고, 선지 4는 이의를 보류했다."}},{"i":"S5-1-1-민법-10","r":"S5","g":1,"c":1,"n":50,"s":"민법","q":"법률행위의 부관에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["조건이 선량한 풍속 기타 사회질서에 위반한 경우, 그 조건만 무효이고 법률행위는 유효하다.","법률행위에 조건이 붙어 있는지 여부는 조건의 존재를 주장하는 자에게 증명책임이 있다.","기한은 특별한 사정이 없는 한 채무자의 이익을 위한 것으로 추정한다.","조건부 법률행위에서 기성조건이 해제조건이면 그 법률행위는 무효이다.","종기(終期) 있는 법률행위는 기한이 도래한 때로부터 그 효력을 잃는다."],"a":[1],"L":"민1-5","o":"기출","x":{"한줄":"조건이 사회질서에 위반하면 조건만이 아니라 법률행위 전부가 무효이다(제151조제1항).","근거":[{"법령":"민법","조문":"제151조","원문":"①조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 법률행위는 무효로 한다. ②조건이 법률행위의 당시 이미 성취한 것인 경우에는 그 조건이 정지조건이면 조건없는 법률행위로 하고 해제조건이면 그 법률행위는 무효로 한다. ③조건이 법률행위의 당시에 이미 성취할 수 없는 것인 경우에는 그 조건이 해제조건이면 조건없는 법률행위로 하고 정지조건이면 그 법률행위는 무효로 한다."},{"법령":"민법","조문":"제153조","원문":"①기한은 채무자의 이익을 위한 것으로 추정한다."},{"법령":"민법","조문":"제152조","원문":"②종기있는 법률행위는 기한이 도래한 때로부터 그 효력을 잃는다."},{"판례":"대법원 판례(조건의 증명책임)","요지":"법률행위에 조건이 붙어 있다는 사실은 이를 주장하는 자가 증명해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"불법조건이 붙은 법률행위는 조건만이 아니라 법률행위 전부가 무효이다(제151조제1항)."},{"번호":2,"판정":"옳음","설명":"조건이 붙어 있다는 사실은 이를 주장하는 자가 증명해야 한다."},{"번호":3,"판정":"옳음","설명":"기한은 채무자의 이익을 위한 것으로 추정한다(제153조제1항)."},{"번호":4,"판정":"옳음","설명":"이미 성취한 조건이 해제조건이면 법률행위는 무효이다(제151조제2항)."},{"번호":5,"판정":"옳음","설명":"종기 있는 법률행위는 기한이 도래한 때로부터 효력을 잃는다(제152조제2항)."}],"개념":[{"종류":"표","제목":"조건과 기한 비교","머리":["구분","조건","기한"],"행":[["내용","장래의 불확실한 사실","장래의 확실한 사실"],["효력 발생·소멸","정지조건은 성취한 때 발생, 해제조건은 성취한 때 소멸(제147조)","시기는 도래한 때 발생, 종기는 도래한 때 소멸(제152조)"],["소급효","당사자가 특약으로 소급하게 할 수 있음(제147조제3항)","소급효를 인정하지 않음"],["이익","조건의 성부 미정 중에도 조건부 권리는 처분·상속·보존·담보 가능(제149조)","기한은 채무자의 이익으로 추정(제153조제1항), 이익은 포기 가능하나 상대방 이익을 해하지 못함"],["불법의 경우","불법조건이면 법률행위 전부 무효(제151조제1항)","해당 없음"]]},{"종류":"표","제목":"기성조건·불능조건의 효과(제151조)","머리":["조건의 종류","정지조건","해제조건"],"행":[["이미 성취한 조건(기성)","조건 없는 법률행위","무효"],["성취할 수 없는 조건(불능)","무효","조건 없는 법률행위"],["불법조건","법률행위 전부 무효","법률행위 전부 무효"],["조건 성취를 신의칙에 반해 방해(제150조제1항)","상대방은 조건이 성취된 것으로 주장 가능","같음"]]}],"함정":"선지 1이 틀린 이유는 조건만 떼어 무효로 보는 점이다. 불법조건은 법률행위 전부를 무효로 만든다. 선지 4의 기성 해제조건은 무효이고, 선지 3의 기한 이익은 채무자에게 추정된다."}},{"i":"S5-1-1-민법-11","r":"S5","g":1,"c":1,"n":51,"s":"민법","q":"甲소유 토지에 乙이 무단으로 건물을 신축한 뒤 丙에게 임대하여 丙이 현재 그 건물을 점유하고 있다. 다음 설명 중 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲은 丙을 상대로 건물에서의 퇴거를 청구할 수 없다.","甲은 乙을 상대로 건물의 철거 및 토지의 인도를 청구할 수 있다.","甲은 乙을 상대로 토지의 무단 사용을 이유로 부당이득 반환청구권을 행사할 수 있다.","만약 乙이 임대하지 않고 스스로 점유하고 있다면, 甲은 乙을 상대로 건물에서의 퇴거를 청구할 수 없다.","만약 丙이 무단으로 건물을 점유하고 있다면, 乙은 丙을 상대로 건물의 인도를 청구할 수 있다."],"a":[1],"L":"민2-1","o":"기출","x":{"한줄":"토지 소유자는 건물 임차인에게 건물에서의 퇴거를 청구할 수 있다.","근거":[{"법령":"민법","조문":"제213조","원문":"소유자는 그 소유에 속한 물건을 점유한 자에 대하여 반환을 청구할 수 있다. 그러나 점유자가 그 물건을 점유할 권리가 있는 때에는 반환을 거부할 수 있다."},{"법령":"민법","조문":"제214조","원문":"소유자는 소유권을 방해하는 자에 대하여 방해의 제거를 청구할 수 있고 소유권을 방해할 염려있는 행위를 하는 자에 대하여 그 예방이나 손해배상의 담보를 청구할 수 있다."},{"법령":"민법","조문":"제741조","원문":"법률상 원인없이 타인의 재산 또는 노무로 인하여 이익을 얻고 이로 인하여 타인에게 손해를 가한 자는 그 이익을 반환하여야 한다."},{"판례":"대법원 판례(건물 점유자에 대한 퇴거 청구)","요지":"건물을 점유하는 임차인은 그 건물의 점유로 토지 소유자의 소유권 행사를 방해하므로, 토지 소유자는 임차인에게 건물에서의 퇴거를 청구할 수 있다. 건물 소유자가 직접 점유하는 경우에는 철거와 토지 인도를 구하면 되고 퇴거를 따로 청구할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"甲은 건물 임차인 丙에게 퇴거를 청구할 수 있다. 丙의 점유가 甲의 소유권 행사를 방해하기 때문이다(제214조)."},{"번호":2,"판정":"옳음","설명":"甲은 건물 소유자 乙에게 건물 철거와 토지 인도를 청구할 수 있다(제213조, 제214조)."},{"번호":3,"판정":"옳음","설명":"권원 없이 토지를 사용한 乙은 차임 상당의 이익을 부당이득으로 반환해야 한다(제741조)."},{"번호":4,"판정":"옳음","설명":"건물 소유자 乙이 직접 점유하는 경우 철거와 토지 인도를 구하면 되므로 퇴거를 따로 청구할 수 없다."},{"번호":5,"판정":"옳음","설명":"소유자 乙은 권원 없이 건물을 점유한 丙에게 소유물반환청구권으로 인도를 청구할 수 있다(제213조)."}],"개념":[{"종류":"표","제목":"물권적 청구권 정리","머리":["청구권","근거","내용","상대방·요건"],"행":[["소유물반환청구권","제213조","점유를 빼앗긴 소유자가 물건의 반환을 청구","점유자, 점유할 권리가 있으면 거부 가능"],["소유물방해제거청구권","제214조 전단","방해 상태를 없애 달라고 청구","방해자, 상대방의 귀책사유 불필요"],["소유물방해예방청구권","제214조 후단","방해할 염려가 있을 때 예방·담보를 청구","방해할 염려가 있는 행위자"],["점유권에 기한 청구권","제204조~제206조","점유 회수(1년), 보유(방해 종료 후 1년), 보전","점유자, 제척기간 있음"]]},{"종류":"표","제목":"무단 건물에 대한 소유자의 청구 상대방","머리":["상대방","청구","비고"],"행":[["건물 소유자","건물 철거 + 토지 인도","직접 점유하는 소유자에게 퇴거 청구는 따로 하지 않음"],["건물 임차인 등 점유자","건물에서의 퇴거","철거 집행을 위해 점유자 퇴거 필요"],["건물 소유자","차임 상당 부당이득 반환","토지 무단 사용 기간 동안의 이익(제741조)"],["건물을 무단 점유하는 자","건물 소유자(乙)의 건물 인도 청구","제213조, 소유물반환청구"]]}],"함정":"선지 1은 건물 임차인에 대한 퇴거 청구가 가능하다는 점과 반대여서 틀린 문장이다. 선지 4처럼 건물 소유자가 직접 점유하면 퇴거는 청구하지 않고 철거와 토지 인도를 구한다."}},{"i":"S5-1-1-민법-12","r":"S5","g":1,"c":1,"n":52,"s":"민법","q":"물권변동에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["건물을 신축한 사람은 소유권보존등기를 마쳐야 그 건물의 소유권을 취득한다.","소유권이전등기가 마쳐져 있으면 특별한 사정이 없는 한 그 등기의 원인과 절차는 적법한 것으로 추정된다.","매수인이 매도인을 상대로 소유권이전등기를 명하는 이행판결을 받아 확정되면, 등기 없이도 소유권을 취득한다.","같은 건물에 보존등기가 이중으로 마쳐진 경우, 나중에 마쳐진 보존등기가 유효하다.","상속으로 부동산 소유권을 취득한 상속인은 상속등기 없이도 그 부동산을 제3자에게 처분할 수 있다."],"a":[2],"L":"민2-2","o":"변형","x":{"한줄":"소유권이전등기가 마쳐져 있으면 그 등기의 원인과 절차가 적법한 것으로 추정된다.","근거":[{"법령":"민법","조문":"제186조","원문":"부동산에 관한 법률행위로 인한 물권의 득실변경은 등기하여야 그 효력이 생긴다."},{"법령":"민법","조문":"제187조","원문":"상속, 공용징수, 판결, 경매 기타 법률의 규정에 의한 부동산에 관한 물권의 취득은 등기를 요하지 아니한다. 그러나 등기를 하지 아니하면 이를 처분하지 못한다."},{"판례":"대법원 판례(등기의 추정력)","요지":"등기가 마쳐져 있으면 그 등기의 원인과 절차가 적법한 것으로 추정된다. 이를 다투는 쪽이 추정을 깨뜨릴 증명을 해야 한다."},{"판례":"대법원 판례(이중 보존등기)","요지":"같은 부동산에 보존등기가 이중으로 마쳐진 경우 먼저 마쳐진 보존등기가 유효하고 뒤에 마쳐진 보존등기는 무효이다. 선행 보존등기가 원인무효인 경우는 예외이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"건물은 신축으로 완성된 때 원시취득한다. 보존등기는 처분하려는 때 필요하다(제187조 단서)."},{"번호":2,"판정":"옳음","설명":"소유권이전등기가 마쳐져 있으면 등기원인과 절차가 모두 적법한 것으로 추정된다. 이를 다투는 쪽이 번복할 증명을 해야 한다."},{"번호":3,"판정":"틀림","설명":"제187조의 판결은 형성판결만 뜻한다. 이행판결이 확정되어도 이전등기를 마쳐야 소유권을 취득한다."},{"번호":4,"판정":"틀림","설명":"이중 보존등기는 먼저 마쳐진 등기가 유효하고 뒤에 마쳐진 등기가 무효이다."},{"번호":5,"판정":"틀림","설명":"상속은 등기 없이 취득하지만, 등기를 하지 않으면 처분하지 못한다(제187조 단서)."}],"개념":[{"종류":"표","제목":"제187조: 등기 없이 부동산 물권을 취득하는 경우","머리":["사유","내용","주의"],"행":[["상속","피상속인 사망 시 상속인이 소유권 취득","처분하려면 상속등기 필요"],["공용징수","재결수용 등","재결에서 정한 수용 개시일에 취득, 보상금 지급 또는 공탁이 전제"],["판결","형성판결(공유물분할판결 등)","이행판결·확인판결은 해당하지 않음"],["경매","민사집행법상 경매, 국세징수법상 공매","매각대금 완납 시 취득"],["기타 법률 규정","건물 신축, 법정지상권·법정갱신된 전세권 등","처분하려면 등기 필요"]]},{"종류":"표","제목":"물권변동의 구분","머리":["구분","부동산","동산"],"행":[["법률행위에 의한 변동","등기해야 효력(제186조)","인도해야 효력(제188조제1항)"],["간이인도","해당 없음","양수인이 이미 점유하면 의사표시만으로(제188조제2항)"],["점유개정","해당 없음","양도인이 점유를 계속하는 계약(제189조)"],["목적물반환청구권의 양도","해당 없음","제3자가 점유 중이면 반환청구권을 양도(제190조)"],["법률 규정에 의한 변동","등기 없이 취득, 처분은 등기 후(제187조)","즉시 취득"]]}],"함정":"제187조의 판결은 형성판결이고 이행판결은 포함되지 않는다. 상속인은 등기 없이 소유권을 취득하지만 등기해야 처분할 수 있다. 건물은 신축으로 원시취득하므로 보존등기가 취득 요건이 아니다."}},{"i":"S5-1-1-민법-13","r":"S5","g":1,"c":1,"n":53,"s":"민법","q":"등기 없이도 물권변동의 효력이 생기는 사유가 아닌 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["상속","재결수용","이행판결","건물의 신축","국세징수법상 공매"],"a":[3],"L":"민2-2","o":"기출","x":{"한줄":"제187조의 판결은 형성판결만 뜻하므로 이행판결로는 등기 없이 물권변동이 일어나지 않는다.","근거":[{"법령":"민법","조문":"제187조","원문":"상속, 공용징수, 판결, 경매 기타 법률의 규정에 의한 부동산에 관한 물권의 취득은 등기를 요하지 아니한다. 그러나 등기를 하지 아니하면 이를 처분하지 못한다."},{"이론":"건물의 신축","내용":"건물을 신축한 사람은 건물이 완성된 때 보존등기 없이 소유권을 원시취득한다."},{"판례":"대법원 판례(판결과 물권변동)","요지":"제187조의 판결은 형성판결을 말하고, 이행판결이나 확인판결은 포함하지 않는다. 공유물분할판결이 확정되면 등기 없이 물권이 변동한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상속은 제187조에 따라 등기 없이 소유권을 취득한다."},{"번호":2,"판정":"옳음","설명":"재결수용은 공용징수로서 제187조에 해당한다."},{"번호":3,"판정":"틀림","설명":"이행판결이 확정되어도 승소자는 판결에 따라 등기를 마쳐야 소유권을 취득한다."},{"번호":4,"판정":"옳음","설명":"건물은 신축으로 완성된 때 등기 없이 원시취득한다."},{"번호":5,"판정":"옳음","설명":"공매는 경매와 같이 매각대금을 완납한 때 등기 없이 소유권을 취득한다."}],"개념":[{"종류":"표","제목":"판결의 종류와 물권변동","머리":["판결 종류","물권변동 시기","예"],"행":[["형성판결","판결 확정 시 등기 없이 변동","공유물분할판결"],["이행판결","판결에 따라 등기를 마쳐야 변동","소유권이전등기절차 이행을 명한 판결"],["확인판결","변동을 일으키지 않음","소유권확인판결"],["이행판결 확정 후","승소자가 단독으로 등기를 신청","부동산등기법상 판결에 의한 등기"]]},{"종류":"표","제목":"등기가 필요한 경우와 불필요한 경우","머리":["구분","사례","등기"],"행":[["불필요","상속, 재결수용, 경매·공매, 건물 신축, 형성판결","제187조 본문"],["필요","매매·증여·교환 등 법률행위로 인한 변동","제186조"],["필요","점유취득시효 완성에 따른 소유권 취득","제245조제1항, 등기해야 취득"],["필요","등기 없이 취득한 부동산의 처분","제187조 단서"]]}],"함정":"제187조의 판결은 형성판결뿐이고 이행판결·확인판결은 해당하지 않는다. 점유취득시효가 완성되어도 등기를 마쳐야 소유권을 취득하므로 제187조의 사유와 구별한다."}},{"i":"S5-1-1-민법-14","r":"S5","g":1,"c":1,"n":54,"s":"민법","q":"점유에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["제3자가 직접점유자의 점유를 방해한 경우, 특별한 사정이 없는 한 간접점유자에게는 점유권에 기한 방해배제청구권이 인정되지 않는다.","취득시효의 요건인 점유에는 간접점유가 포함되지 않는다.","소유권의 시효취득을 주장하는 점유자는 특별한 사정이 없는 한 자신의 점유가 자주점유에 해당함을 증명하여야 한다.","선의의 점유자가 본권에 관한 소에 패소한 경우, 그 자는 패소가 확정된 때부터 악의의 점유자로 본다.","양도인이 등기부상의 명의인과 동일인이며 그 명의를 의심할 만한 특별한 사정이 없는 경우, 그 부동산을 양수하여 인도받은 자는 과실(過失) 없는 점유자에 해당한다."],"a":[5],"L":"민2-3","o":"기출","x":{"한줄":"등기부상 명의인에게서 양수하여 인도받고 명의를 의심할 사정이 없으면 과실 없는 점유자이다.","근거":[{"법령":"민법","조문":"제207조","원문":"①전3조의 청구권은 제194조의 규정에 의한 간접점유자도 이를 행사할 수 있다."},{"법령":"민법","조문":"제197조","원문":"①점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정한다. ②선의의 점유자라도 본권에 관한 소에 패소한 때에는 그 소가 제기된 때로부터 악의의 점유자로 본다."},{"판례":"대법원 판례(과실 없는 점유)","요지":"양도인이 등기부상 명의인과 동일인이고 그 명의를 의심할 만한 특별한 사정이 없으면, 양수하여 인도받은 자는 과실 없이 점유를 개시한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"간접점유자도 점유보호청구권을 행사할 수 있다(제207조제1항)."},{"번호":2,"판정":"틀림","설명":"취득시효의 점유에는 간접점유도 포함된다."},{"번호":3,"판정":"틀림","설명":"점유자는 소유의 의사로 점유한 것으로 추정되므로(제197조제1항) 타주점유라고 주장하는 쪽이 증명한다."},{"번호":4,"판정":"틀림","설명":"선의 점유자는 본권에 관한 소가 제기된 때부터 악의 점유자로 본다(제197조제2항). 패소 확정 시가 아니다."},{"번호":5,"판정":"옳음","설명":"등기부를 믿고 양수하여 인도받은 자는 과실 없는 점유자이다."}],"개념":[{"종류":"표","제목":"점유의 추정(제197조~제200조)","머리":["규정","추정 내용","의미"],"행":[["제197조제1항","소유의 의사, 선의, 평온, 공연한 점유","자주점유 아님을 주장하는 쪽이 증명"],["제197조제2항","본권 소에서 패소하면 소 제기 때부터 악의","확정 시가 아님"],["제198조","전후 양 시점에 점유하면 계속한 것으로 추정","중간 점유의 중단은 반증"],["제199조","점유의 승계 시 자기 점유만 또는 전점유와 합산 주장 가능","합산 시 하자도 승계"],["제200조","점유물에 행사하는 권리는 적법하게 보유한 것으로 추정","권리의 적법 추정"]]},{"종류":"표","제목":"점유보호청구권","머리":["청구권","행사 기간","내용"],"행":[["점유물반환(제204조)","침탈을 당한 날부터 1년","물건의 반환과 손해배상, 악의의 특별승계인에게만 행사"],["점유물방해제거(제205조)","방해가 종료한 날부터 1년","방해의 제거와 손해배상"],["점유물방해예방(제206조)","방해 염려가 있는 동안","방해의 예방 또는 손해배상의 담보"],["간접점유자(제207조)","위와 같음","제204조~제206조를 행사 가능"]]}],"함정":"본권 소송의 패소는 확정 시가 아니라 소가 제기된 때부터 악의로 본다. 자주점유는 추정되므로 타주점유를 주장하는 쪽이 증명한다. 간접점유는 점유보호청구권과 취득시효 모두에서 인정된다."}},{"i":"S5-1-1-민법-15","r":"S5","g":1,"c":1,"n":55,"s":"민법","q":"점유자와 회복자의 관계에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["점유물이 점유자의 책임 있는 사유로 멸실된 경우, 선의의 타주점유자는 이익이 현존하는 한도에서 배상해야 한다.","악의의 점유자는 특별한 사정이 없는 한 통상의 필요비를 청구할 수 있다.","점유자의 필요비상환청구에 대해 법원은 회복자의 청구에 의해 상당한 상환기간을 허여할 수 있다.","이행지체로 인해 매매계약이 해제된 경우, 선의의 점유자인 매수인에게 과실취득권이 인정된다.","은비(隱秘)에 의한 점유자는 점유물의 과실을 취득한다."],"a":[2],"L":"민2-3","o":"기출","x":{"한줄":"악의의 점유자는 과실을 취득하지 못하므로 통상의 필요비도 청구할 수 있다.","근거":[{"법령":"민법","조문":"제201조","원문":"①선의의 점유자는 점유물의 과실을 취득한다. ②악의의 점유자는 수취한 과실을 반환하여야 하며 소비하였거나 과실로 인하여 훼손 또는 수취하지 못한 경우에는 그 과실의 대가를 보상하여야 한다. ③전항의 규정은 폭력 또는 은비에 의한 점유자에 준용한다."},{"법령":"민법","조문":"제202조","원문":"점유물이 점유자의 책임있는 사유로 인하여 멸실 또는 훼손한 때에는 악의의 점유자는 그 손해의 전부를 배상하여야 하며 선의의 점유자는 이익이 현존하는 한도에서 배상하여야 한다. 소유의 의사가 없는 점유자는 선의인 경우에도 손해의 전부를 배상하여야 한다."},{"법령":"민법","조문":"제203조","원문":"①점유자가 점유물을 반환할 때에는 회복자에 대하여 점유물을 보존하기 위하여 지출한 금액 기타 필요비의 상환을 청구할 수 있다. 그러나 점유자가 과실을 취득한 경우에는 통상의 필요비는 청구하지 못한다. ②점유자가 점유물을 개량하기 위하여 지출한 금액 기타 유익비에 관하여는 그 가액의 증가가 현존한 경우에 한하여 회복자의 선택에 좇아 그 지출금액이나 증가액의 상환을 청구할 수 있다. ③전항의 경우에 법원은 회복자의 청구에 의하여 상당한 상환기간을 허여할 수 있다."},{"판례":"대법원 판례(계약해제와 과실)","요지":"매매계약이 해제되면 매수인은 원상회복 의무를 진다. 선의의 매수인이라도 해제 후 반환할 때 점유 중 얻은 과실을 반환해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"소유 의사 없는 점유자는 선의라도 손해 전부를 배상한다(제202조 후문). 이익이 현존하는 한도에서 배상하는 것은 선의의 자주점유자이다."},{"번호":2,"판정":"옳음","설명":"악의의 점유자는 수취한 과실을 반환해야 하므로 과실을 취득하지 못한다. 그래서 통상의 필요비도 청구할 수 있다(제203조제1항)."},{"번호":3,"판정":"틀림","설명":"법원이 허여하는 상환기간은 유익비에 관한 것이다(제203조제3항). 필요비에는 적용되지 않는다."},{"번호":4,"판정":"틀림","설명":"계약이 해제되면 선의의 매수인도 과실을 반환해야 한다. 과실취득권으로 보호받지 못한다."},{"번호":5,"판정":"틀림","설명":"폭력 또는 은비에 의한 점유자는 악의의 점유자와 같이 과실을 반환해야 한다(제201조제3항)."}],"개념":[{"종류":"표","제목":"점유자별 회복자에 대한 관계","머리":["점유자","과실(제201조)","멸실·훼손 책임(제202조)","필요비(제203조제1항)"],"행":[["선의의 자주점유자","취득","이익이 현존하는 한도","통상 필요비는 청구 불가, 특별 필요비는 가능"],["악의의 점유자","반환 및 소비·훼손분 보상","손해 전부","통상·특별 필요비 모두 청구 가능"],["폭력·은비 점유자","악의 점유자와 같음","손해 전부(악의 취급)","악의 점유자와 같음"],["소유 의사 없는 점유자","선의 여부에 따름","선의라도 손해 전부","선의 여부에 따름"]]},{"종류":"표","제목":"필요비와 유익비 비교","머리":["구분","필요비","유익비"],"행":[["의미","점유물을 보존하기 위해 지출한 금액","점유물을 개량하기 위해 지출한 금액"],["상환 범위","지출한 금액 전부(과실 취득 시 통상 필요비 제외)","가치 증가가 현존하는 경우 회복자 선택에 따라 지출액 또는 증가액"],["상환기간 허여","없음","회복자의 청구에 의해 법원이 허여 가능(제203조제3항)"],["과실을 취득한 점유자","통상의 필요비는 청구 불가","영향 없음"],["악의의 점유자","청구 가능","가치 증가가 현존하면 청구 가능"]]}],"함정":"상환기간 허여는 유익비에만 해당한다. 소유 의사 없는 점유자는 선의라도 손해 전부를 배상한다. 은비 점유자는 악의 점유자와 같이 과실을 반환한다."}},{"i":"S5-1-1-민법-16","r":"S5","g":1,"c":1,"n":56,"s":"민법","q":"甲은 자신의 X토지 중 일부를 특정(Y부분)하여 乙에게 매도하면서 토지를 분할하는 등의 절차를 피하기 위하여 편의상 乙에게 Y부분의 면적 비율에 상응하는 공유지분등기를 마쳤다. 이에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙은 甲에 대하여 Y부분에 관한 공유물분할을 청구할 수 있다.","乙이 Y부분을 제3자에게 처분하려면 甲의 동의를 받아야 한다.","乙이 甲 소유로 정해진 나머지 부분을 점유하는 것은 권원의 성질상 자주점유이다.","乙은 Y부분을 불법점유하는 丙에 대하여 공유물의 보존행위로 그 배제를 구할 수 있다.","乙이 甲 소유로 정해진 부분 위에 건물을 신축하면 그 건물을 위한 관습법상 법정지상권이 성립한다."],"a":[4],"L":"민2-4","o":"변형","x":{"한줄":"구분소유적 공유자는 자기 구분 부분에 대한 방해배제를 단독으로 구할 수 있다.","근거":[{"법령":"민법","조문":"제262조","원문":"①물건이 지분에 의하여 수인의 소유로 된 때에는 공유로 한다."},{"법령":"민법","조문":"제263조","원문":"공유자는 그 지분을 처분할 수 있고 공유물 전부를 지분의 비율로 사용, 수익할 수 있다."},{"법령":"민법","조문":"제265조","원문":"공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다. 그러나 보존행위는 각자가 할 수 있다."},{"판례":"대법원 판례(구분소유적 공유)","요지":"특정 부분을 구분하여 소유하면서 면적 비율로 공유지분등기를 한 경우, 내부적으로는 각자 특정 부분을 단독 소유하고 대외적으로는 공유이다. 상호 명의신탁 관계이므로 공유물분할을 청구할 수 없고, 자기 구분 부분은 다른 공유자 동의 없이 처분할 수 있으며, 자기 구분 부분의 방해배제를 단독으로 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"구분소유적 공유는 이미 특정 부분을 각자 소유하는 관계라서 공유물분할을 청구할 수 없다."},{"번호":2,"판정":"틀림","설명":"乙은 자기 구분 부분인 Y부분을 甲의 동의 없이 처분할 수 있다."},{"번호":3,"판정":"틀림","설명":"나머지 부분에 대한 乙의 점유는 상호 명의신탁 관계에 따른 점유이므로 타주점유이다."},{"번호":4,"판정":"옳음","설명":"Y부분을 불법으로 점유하는 丙에게 乙은 방해의 배제를 단독으로 청구할 수 있다(제265조 단서 보존행위)."},{"번호":5,"판정":"틀림","설명":"관습법상 법정지상권은 처분 당시 토지와 건물이 동일인 소유였을 때 성립한다. 甲 소유 부분의 건물은 乙 소유이므로 동일인 소유가 아니다."}],"개념":[{"종류":"비교","제목":"일반 공유와 구분소유적 공유","왼쪽":{"이름":"일반 공유","항목":["지분은 공유물 전체에 미침(제263조)","공유물분할을 청구할 수 있음(제268조)","지분은 자유롭게 처분 가능, 공유물 전부를 지분 비율로 사용","처분·변경은 전원 동의, 관리는 지분 과반수, 보존은 각자(제264조, 제265조)"]},"오른쪽":{"이름":"구분소유적 공유","항목":["특정 부분을 각자 단독 소유하고 등기만 공유(상호 명의신탁)","공유물분할을 청구할 수 없음","자기 구분 부분은 다른 공유자 동의 없이 처분 가능","타인 구분 부분 점유는 타주점유, 자기 구분 부분의 방해배제는 단독으로 청구"]}},{"종류":"표","제목":"공유물에 관한 의사결정","머리":["행위","결정 방법","근거"],"행":[["지분의 처분","각 공유자가 자유롭게","제263조"],["공유물의 처분·변경","다른 공유자 전원의 동의","제264조"],["공유물의 관리","지분의 과반수","제265조 본문"],["공유물의 보존","각자 단독으로","제265조 단서"]]}],"함정":"구분소유적 공유는 분할청구가 안 되고 자기 구분 부분의 처분이 자유롭다. 상대방 구분 부분의 점유는 타주점유이다. 관습법상 법정지상권은 처분 당시 토지와 건물이 동일인 소유일 때 성립한다."}},{"i":"S5-1-1-민법-17","r":"S5","g":1,"c":1,"n":57,"s":"민법","q":"공동소유에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["부동산 공유자 중 1인이 지분을 포기하면, 등기 없이도 포기의 의사표시만으로 그 지분이 다른 공유자에게 귀속된다.","합유자 중 1인이 사망하면 특별한 사정이 없는 한 그의 상속인이 합유지분을 승계하지 않는다.","공유물의 분할에 관하여 협의가 성립되지 않은 경우, 현물로 분할할 수 없거나 분할로 현저히 가액이 감손될 염려가 있으면 법원은 경매를 명할 수 있다.","비법인사단의 총유물에 관한 보존행위도 사원총회의 결의를 거쳐야 하며, 사원이 단독으로 할 수 없다.","공유자 1인의 지분 위에 설정된 저당권은 공유물이 분할된 뒤에도 다른 약정이 없으면 저당권설정자 앞으로 분할된 부분에 집중되지 않는다."],"a":[1],"L":"민2-4","o":"변형","x":{"한줄":"공유지분의 포기는 법률행위이므로 등기를 마쳐야 다른 공유자에게 귀속된다.","근거":[{"법령":"민법","조문":"제267조","원문":"공유자가 그 지분을 포기하거나 상속인없이 사망한 때에는 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다."},{"법령":"민법","조문":"제269조","원문":"①분할의 방법에 관하여 협의가 성립되지 아니한 때에는 공유자는 법원에 그 분할을 청구할 수 있다. ②현물로 분할할 수 없거나 분할로 인하여 현저히 그 가액이 감손될 염려가 있는 때에는 법원은 물건의 경매를 명할 수 있다."},{"법령":"민법","조문":"제273조","원문":"①합유자는 전원의 동의없이 합유물에 대한 지분을 처분하지 못한다. ②합유자는 합유물의 분할을 청구하지 못한다."},{"법령":"민법","조문":"제276조","원문":"①총유물의 관리 및 처분은 사원총회의 결의에 의한다. ②각 사원은 정관 기타의 규약에 좇아 총유물을 사용, 수익할 수 있다."},{"판례":"대법원 판례(공유지분 포기)","요지":"부동산 공유지분을 포기하면 그 지분은 다른 공유자에게 귀속되지만, 포기는 법률행위이므로 등기를 마친 때 물권변동의 효력이 생긴다."},{"판례":"대법원 판례(합유자의 사망)","요지":"합유자 중 1인이 사망하면 그의 상속인이 합유지분을 승계하지 않고, 잔존 합유자의 합유로 귀속된다."},{"판례":"대법원 판례(총유물의 보존행위)","요지":"총유물의 보존행위도 사원총회의 결의를 거쳐야 하며, 비법인사단의 대표자나 사원이 총회 결의 없이 단독으로 할 수 없다."},{"판례":"대법원 판례(공유지분 위 저당권)","요지":"공유자 지분 위의 저당권은 공유물이 분할된 뒤에도 소멸하지 않고, 저당권설정자 앞으로 분할된 부분에 집중되지 않는다. 다른 공유자 앞으로 분할된 부분에도 그 지분 비율대로 존속한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지분 포기에 의한 귀속은 법률행위로 인한 물권변동이므로 등기를 해야 효력이 생긴다."},{"번호":2,"판정":"옳음","설명":"합유자가 사망하면 상속인은 합유지분을 승계하지 못하고 잔존 합유자에게 귀속된다."},{"번호":3,"판정":"옳음","설명":"현물분할이 불가능하거나 가액이 현저히 감손될 염려가 있으면 법원은 경매를 명할 수 있다(제269조제2항)."},{"번호":4,"판정":"옳음","설명":"총유물의 관리·처분은 사원총회의 결의로 하고(제276조제1항), 보존행위도 총회 결의가 필요하다는 것이 판례이다."},{"번호":5,"판정":"옳음","설명":"공유자 지분 위의 저당권은 분할 후에도 소멸하지 않고 저당권설정자 앞으로 분할된 부분에 집중되지 않는다."}],"개념":[{"종류":"표","제목":"공유·합유·총유 비교","머리":["구분","공유","합유","총유"],"행":[["성립","수인이 지분으로 소유","조합체로서 소유","비법인사단의 사원이 집합체로서 소유"],["지분","지분 있음, 자유 처분(제263조)","지분 있으나 전원 동의 없이 처분 불가(제273조제1항)","지분 없음"],["분할청구","가능(제268조)","불가(제273조제2항)","분할 개념 없음(사원 지위의 득상에 따라 권리 득상, 제277조)"],["보존행위","각자(제265조 단서)","각자(제272조 단서)","사원총회 결의(판례)"],["관리·처분","관리는 지분 과반수, 처분·변경은 전원 동의","처분·변경은 전원 동의","관리·처분은 사원총회 결의(제276조제1항)"]]},{"종류":"흐름","제목":"공유물 분할 절차","단계":[{"이름":"분할금지 약정 확인","설명":"5년 내 기간으로 분할하지 않기로 약정 가능, 갱신하면 갱신한 날부터 5년을 넘지 못함(제268조)"},{"이름":"협의분할","설명":"공유자 전원의 협의로 분할 방법 결정"},{"이름":"재판분할 청구","설명":"협의가 성립하지 않으면 법원에 분할 청구(제269조제1항)"},{"이름":"현물분할 또는 경매","설명":"현물분할이 원칙, 불가능하거나 현저한 감손 염려가 있으면 경매 명령(제269조제2항)"},{"이름":"분할의 효과","설명":"분할 후 서로 지분 비율로 매도인과 같은 담보책임(제270조)"}]}],"함정":"선지 1이 틀린 이유는 공유지분 포기도 등기를 해야 물권변동의 효력이 생기기 때문이다. 합유자 사망과 총유물 보존행위, 저당권 불집중은 모두 옳은 문장이다."}},{"i":"S5-1-1-민법-18","r":"S5","g":1,"c":1,"n":58,"s":"민법","q":"지역권에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지역권은 요역지와 분리하여 따로 양도하거나 다른 권리의 목적으로 하지 못한다.","1필의 토지의 일부에는 지역권을 설정할 수 없다.","요역지의 공유자 중 1인이 지역권을 취득한 경우, 요역지의 다른 공유자도 지역권을 취득한다.","지역권에 기한 승역지 반환청구권은 인정되지 않는다.","계속되고 표현된 지역권은 시효취득의 대상이 될 수 있다."],"a":[2],"L":"민2-5","o":"기출","x":{"한줄":"승역지는 1필 토지의 일부에도 지역권을 설정할 수 있다.","근거":[{"법령":"민법","조문":"제292조","원문":"②지역권은 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다."},{"법령":"민법","조문":"제293조","원문":"②토지의 분할이나 토지의 일부양도의 경우에는 지역권은 요역지의 각 부분을 위하여 또는 그 승역지의 각부분에 존속한다. 그러나 지역권이 토지의 일부분에만 관한 것인 때에는 다른 부분에 대하여는 그러하지 아니하다."},{"법령":"민법","조문":"제295조","원문":"①공유자의 1인이 지역권을 취득한 때에는 다른 공유자도 이를 취득한다."},{"법령":"민법","조문":"제294조","원문":"지역권은 계속되고 표현된 것에 한하여 제245조의 규정을 준용한다."},{"판례":"대법원 판례(승역지 반환청구)","요지":"지역권은 점유를 수반하지 않는 권리라서 지역권자에게 승역지 반환청구권이 인정되지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지역권은 요역지 소유권에 부종한다. 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다(제292조제2항)."},{"번호":2,"판정":"틀림","설명":"승역지는 토지의 일부에도 지역권을 설정할 수 있다(제293조제2항 단서가 일부에만 관한 지역권을 예정한다). 요역지는 1필 전부여야 한다."},{"번호":3,"판정":"옳음","설명":"공유자 1인이 지역권을 취득하면 다른 공유자도 취득한다(제295조제1항)."},{"번호":4,"판정":"옳음","설명":"점유를 수반하지 않는 권리라서 승역지 반환청구는 인정되지 않는다. 방해제거·예방청구는 가능하다(제301조)."},{"번호":5,"판정":"옳음","설명":"지역권은 계속되고 표현된 것에 한하여 시효취득할 수 있다(제294조)."}],"개념":[{"종류":"표","제목":"지역권의 핵심 속성","머리":["속성","내용","근거"],"행":[["부종성","요역지 소유권에 부종하여 이전, 분리 양도 불가","제292조"],["불가분성","공유자 1인의 취득·소멸시효 중단은 다른 공유자에게 효력, 지분만 소멸하게 하지 못함","제293조제1항, 제295조, 제296조"],["시효취득","계속되고 표현된 지역권만 가능","제294조"],["점유 수반 여부","수반하지 않음, 반환청구권 없음, 방해제거·예방청구 가능","제301조, 제214조"],["요역지와 승역지","요역지는 1필 전부, 승역지는 일부도 가능","제293조제2항 단서"]]},{"종류":"표","제목":"지상권·지역권·전세권 비교","머리":["구분","지상권","지역권","전세권"],"행":[["목적","건물 기타 공작물·수목 소유를 위한 토지 사용","요역지 편익을 위한 승역지 이용","타인 부동산의 점유·사용·수익 + 전세금 우선변제"],["점유 수반","수반함","수반하지 않음","수반함"],["존속기간","최단 30년·15년·5년(제280조)","제한 없음","최장 10년, 건물은 최단 1년"],["대가","지료는 약정 사항","대가는 약정 사항","전세금 지급이 요소"],["양도","가능(제282조)","요역지와 분리 양도 불가","가능(제306조)"]]}],"함정":"선지 2가 틀린 이유는 승역지는 일부에도 설정할 수 있기 때문이다. 일부 설정이 안 되는 것은 요역지이다. 선지 4의 승역지 반환청구는 지역권이 점유를 수반하지 않아 인정되지 않는다."}},{"i":"S5-1-1-민법-19","r":"S5","g":1,"c":1,"n":59,"s":"민법","q":"지역권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["요역지는 1필의 토지 일부라도 무방하다.","요역지의 소유권이 이전되어도 특별한 사정이 없는 한 지역권은 이전되지 않는다.","지역권의 존속기간을 영구무한으로 약정할 수는 없다.","지역권자는 승역지를 권원 없이 점유한 자에게 그 반환을 청구할 수 있다.","요역지공유자의 1인은 지분에 관하여 그 토지를 위한 지역권을 소멸하게 하지 못한다."],"a":[5],"L":"민2-5","o":"기출","x":{"한줄":"요역지 공유자 1인은 자기 지분에 관하여 그 토지를 위한 지역권을 소멸하게 하지 못한다(제293조제1항).","근거":[{"법령":"민법","조문":"제293조","원문":"①토지공유자의 1인은 지분에 관하여 그 토지를 위한 지역권 또는 그 토지가 부담한 지역권을 소멸하게 하지 못한다."},{"법령":"민법","조문":"제292조","원문":"①지역권은 요역지소유권에 부종하여 이전하며 또는 요역지에 대한 소유권이외의 권리의 목적이 된다. 그러나 다른 약정이 있는 때에는 그 약정에 의한다."},{"법령":"민법","조문":"제301조","원문":"제214조의 규정은 지역권에 준용한다."},{"판례":"대법원 판례(지역권의 존속기간)","요지":"지역권의 존속기간은 영구무한으로 약정할 수 있다."},{"판례":"대법원 판례(승역지 반환청구)","요지":"지역권자에게는 승역지 반환청구권이 인정되지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"요역지는 1필의 토지 전부여야 한다. 일부를 요역지로 할 수 없다."},{"번호":2,"판정":"틀림","설명":"지역권은 요역지 소유권에 부종하여 함께 이전한다(제292조제1항)."},{"번호":3,"판정":"틀림","설명":"지역권의 존속기간은 영구무한으로도 약정할 수 있다."},{"번호":4,"판정":"틀림","설명":"지역권은 점유를 수반하지 않으므로 승역지 반환청구권이 없다. 방해제거·예방청구만 한다(제301조)."},{"번호":5,"판정":"옳음","설명":"공유자 1인은 자기 지분만으로 그 토지를 위한 지역권을 소멸하게 하지 못한다(제293조제1항)."}],"개념":[{"종류":"표","제목":"지역권 불가분성 정리","머리":["상황","효과","근거"],"행":[["공유자 1인의 지역권 취득","다른 공유자도 취득","제295조제1항"],["점유 취득시효 중단","지역권을 행사하는 모든 공유자에 대한 사유가 아니면 효력 없음","제295조제2항"],["요역지 공유자 1인의 시효 중단·정지","다른 공유자를 위해서도 효력 있음","제296조"],["공유자 1인의 지역권 소멸","자기 지분에 관해 소멸하게 하지 못함","제293조제1항"],["토지 분할·일부 양도","지역권은 요역지·승역지 각 부분에 존속","제293조제2항"]]},{"종류":"표","제목":"지역권의 기본 구조","머리":["구분","내용"],"행":[["요역지","편익을 받는 토지, 1필 전부"],["승역지","편익을 제공하는 토지, 일부도 가능"],["존속기간","영구무한 약정 가능"],["지역권자의 청구","방해제거·방해예방, 반환청구는 불가"]]}],"함정":"요역지는 1필 전부여야 하고, 지역권은 요역지 소유권과 함께 이전한다. 존속기간은 영구도 가능하다. 지역권자에게는 승역지 반환청구권이 없고 방해제거·예방청구만 인정된다."}},{"i":"S5-1-1-민법-20","r":"S5","g":1,"c":1,"n":60,"s":"민법","q":"甲은 자신의 X건물에 관하여 乙과 전세금 1억원으로 하는 전세권설정계약을 체결하고 乙 명의로 전세권설정등기를 마쳐주었다. 이에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["전세권의 존속기간을 약정하지 않은 경우, 乙이 소멸을 통고하면 통고한 날부터 3개월이 지나 전세권이 소멸한다.","乙의 전세권이 법정갱신된 경우, 乙은 갱신에 관한 변경등기를 해야 제3자에게 갱신된 전세권을 주장할 수 있다.","甲이 전세금의 반환을 지체하면 乙은 민사집행법에 따라 X건물의 경매를 청구할 수 있다.","설정행위로 금지하지 않았더라도 乙은 甲의 동의 없이는 전세권을 타인에게 양도할 수 없다.","乙이 X건물을 전전세한 경우, 乙은 전전세하지 않았으면 면할 수 있었던 불가항력으로 인한 손해에 대하여 책임이 없다."],"a":[3],"L":"민2-6","o":"변형","x":{"한줄":"전세권설정자가 전세금의 반환을 지체하면 전세권자는 목적물의 경매를 청구할 수 있다(제318조).","근거":[{"법령":"민법","조문":"제318조","원문":"전세권설정자가 전세금의 반환을 지체한 때에는 전세권자는 민사집행법의 정한 바에 의하여 전세권의 목적물의 경매를 청구할 수 있다."},{"법령":"민법","조문":"제313조","원문":"전세권의 존속기간을 약정하지 아니한 때에는 각 당사자는 언제든지 상대방에 대하여 전세권의 소멸을 통고할 수 있고 상대방이 이 통고를 받은 날로부터 6월이 경과하면 전세권은 소멸한다."},{"법령":"민법","조문":"제312조","원문":"④건물의 전세권설정자가 전세권의 존속기간 만료전 6월부터 1월까지 사이에 전세권자에 대하여 갱신거절의 통지 또는 조건을 변경하지 아니하면 갱신하지 아니한다는 뜻의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전전세권과 동일한 조건으로 다시 전세권을 설정한 것으로 본다. 이 경우 전세권의 존속기간은 그 정함이 없는 것으로 본다."},{"법령":"민법","조문":"제306조","원문":"전세권자는 전세권을 타인에게 양도 또는 담보로 제공할 수 있고 그 존속기간내에서 그 목적물을 타인에게 전전세 또는 임대할 수 있다. 그러나 설정행위로 이를 금지한 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제308조","원문":"전세권의 목적물을 전전세 또는 임대한 경우에는 전세권자는 전전세 또는 임대하지 아니하였으면 면할 수 있는 불가항력으로 인한 손해에 대하여 그 책임을 부담한다."},{"판례":"대법원 판례(법정갱신)","요지":"전세권의 법정갱신은 법률의 규정에 의한 물권변동이므로 갱신에 관한 등기 없이도 제3자에게 갱신된 전세권을 주장할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"존속기간을 약정하지 않은 전세권은 소멸통고를 받은 날부터 6월이 지나 소멸한다(제313조). 3개월이 아니다."},{"번호":2,"판정":"틀림","설명":"법정갱신은 법률 규정에 의한 변동이라서 등기 없이도 갱신된 전세권을 제3자에게 주장할 수 있다."},{"번호":3,"판정":"옳음","설명":"전세금의 반환이 지체되면 전세권자는 민사집행법에 따라 목적물의 경매를 청구할 수 있다(제318조)."},{"번호":4,"판정":"틀림","설명":"전세권자는 설정행위로 금지하지 않는 한 설정자의 동의 없이 전세권을 양도할 수 있다(제306조)."},{"번호":5,"판정":"틀림","설명":"전세권자가 목적물을 전전세 또는 임대한 경우, 전전세하지 않았으면 면할 수 있는 불가항력의 손해까지 책임진다(제308조)."}],"개념":[{"종류":"표","제목":"전세권의 존속기간과 소멸","머리":["구분","내용","근거"],"행":[["최장 존속기간","10년, 넘으면 10년으로 단축","제312조제1항"],["건물 전세권의 최단 기간","1년 미만이면 1년으로","제312조제2항"],["갱신","갱신한 날부터 10년을 넘지 못함","제312조제3항"],["법정갱신(건물)","만료 6월~1월 전에 갱신거절·조건변경 통지가 없으면 같은 조건으로 다시 설정한 것으로 보고, 존속기간은 정함이 없는 것으로 봄","제312조제4항"],["존속기간 약정이 없는 경우","언제든 소멸통고, 상대방이 통고를 받은 날부터 6월 경과 시 소멸","제313조"],["불가항력 멸실","멸실된 부분의 전세권 소멸, 목적 달성 불가 시 전부 소멸 통고와 전세금 반환 청구","제314조"]]},{"종류":"흐름","제목":"전세권 소멸 후 정산","단계":[{"이름":"전세권 소멸","설명":"존속기간 만료, 소멸통고, 소멸청구 등"},{"이름":"원상회복과 부속물","설명":"전세권자는 목적물을 원상에 회복하고 부속물을 수거, 설정자가 매수를 청구하면 정당한 이유 없이 거절 못함(제316조제1항)"},{"이름":"동시이행","설명":"전세권자의 인도·말소등기 서류 교부와 설정자의 전세금 반환이 동시이행(제317조)"},{"이름":"반환 지체","설명":"설정자가 전세금 반환을 지체하면 전세권자가 민사집행법에 따라 경매 청구(제318조)"}]}],"함정":"소멸통고 후 소멸까지의 기간은 6월이다(제313조). 법정갱신은 등기 없이 제3자에게 주장할 수 있다. 전세권 양도는 설정행위로 금지하지 않으면 동의가 필요 없다(제306조). 전전세 때의 불가항력 손해책임은 제308조에 따른다."}},{"i":"S5-1-1-민법-21","r":"S5","g":1,"c":1,"n":61,"s":"민법","q":"민법상 유치권에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["유치물의 침탈로 인한 유치권자의 유치권소멸에 따른 손해배상청구권은 침탈당한 날로부터 1년 내에 행사할 것을 요하지 않는다.","유치권자로부터 유치물의 유치방법으로 그 보관을 위탁 받은 자는 특별한 사정이 없는 한 유치물 소유자의 소유물반환청구를 거부할 수 있다.","토지전세권이 소멸하기 전에는 전세권자의 지상물매수청구권을 피담보채권으로 하는 유치권은 성립할 수 없다.","복수의 유치물은 그 각부분으로써 피담보채권의 전부를 담보한다.","유치권자가 동일채권을 담보하기 위한 복수의 유치물 중 일부를 채무자의 승낙없이 타인에게 대여한 경우, 특별한 사정이 없는 한 채무자는 유치물 전부에 대한 유치권의 소멸을 청구할 수 있다."],"a":[5],"L":"민2-7","o":"기출","x":{"한줄":"채무자의 승낙 없이 유치물 일부를 대여해도 소멸을 청구할 수 있는 범위는 대여한 그 유치물에 한정되고, 유치물 전부에 대한 소멸 청구는 인정되지 않는다.","근거":[{"법령":"민법","조문":"제324조제2·3항","원문":"제324조(유치권자의 선관의무) ②유치권자는 채무자의 승낙없이 유치물의 사용, 대여 또는 담보제공을 하지 못한다. 그러나 유치물의 보존에 필요한 사용은 그러하지 아니하다. ③유치권자가 전2항의 규정에 위반한 때에는 채무자는 유치권의 소멸을 청구할 수 있다."},{"법령":"민법","조문":"제321조","원문":"제321조(유치권의 불가분성) 유치권자는 채권전부의 변제를 받을 때까지 유치물전부에 대하여 그 권리를 행사할 수 있다."},{"판례":"대법원 판례(복수 유치물 중 일부의 대여)","요지":"유치권자가 복수의 유치물 중 일부를 채무자 승낙 없이 대여한 경우 소멸청구의 대상은 대여한 유치물이고, 나머지 유치물의 유치권은 그대로 남는다."},{"법령":"민법","조문":"제204조제1·3항","원문":"제204조(점유의 회수) ①점유자가 점유의 침탈을 당한 때에는 그 물건의 반환 및 손해의 배상을 청구할 수 있다. ③제1항의 청구권은 침탈을 당한 날로부터 1년내에 행사하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"유치권 소멸에 따른 손해배상청구권은 점유회수청구(제204조 제1항)와 별개의 채권이다. 침탈일부터 1년 안에 행사하라는 제한(제204조 제3항)은 점유회수의 소에 붙는 기간이다."},{"번호":2,"판정":"옳음","설명":"유치권은 점유가 있어야 유지되는데, 유치권자가 보관을 맡긴 경우 그 수탁자의 점유로 유치권자의 점유가 이어진다. 소유자의 반환청구를 거부할 수 있다."},{"번호":3,"판정":"옳음","설명":"지상물매수청구권은 전세권이 소멸한 뒤 행사해야 비로소 생기는 청구권이다. 소멸 전에는 변제기에 있는 채권이 없어 유치권이 성립하지 않는다(제320조 제1항)."},{"번호":4,"판정":"옳음","설명":"유치권은 불가분이어서 유치물 각 부분이 채권 전부를 담보한다(제321조)."},{"번호":5,"판정":"틀림","설명":"소멸청구는 제324조 제2항을 위반한 대여 대상 유치물에 한정된다. 나머지 유치물은 불가분성(제321조)에 따라 여전히 채권 전부를 담보하므로 전부에 대한 소멸 청구는 틀리다(제324조 제3항)."}],"개념":[{"종류":"표","제목":"유치권의 성립요건과 소멸","머리":["구분","내용","근거"],"행":[["목적물","타인의 물건 또는 유가증권(동산·부동산)","제320조 제1항"],["견련성","그 물건에 관하여 생긴 채권","제320조 제1항"],["변제기","채권이 변제기에 있을 것","제320조 제1항"],["점유","적법한 점유(불법행위로 시작한 점유는 제외)","제320조 제2항"],["배제특약","당사자 사이 유치권 포기 특약은 유효","판례"],["소멸","점유 상실, 채무자의 소멸청구(선관의무·무단 사용·대여·담보제공 위반), 상당한 담보 제공","제324조 제3항, 제327조, 제328조"]]},{"종류":"비교","제목":"유치권과 저당권","왼쪽":{"이름":"유치권","항목":["법정담보물권, 요건 충족 시 당연 성립","등기 불요, 점유 필요·상실 시 소멸","우선변제권 없음(경매권만 있음)","물상대위 없음","경매로 소멸하지 않고 인도 거절 가능"]},"오른쪽":{"이름":"저당권","항목":["약정담보물권, 설정계약+등기","점유를 넘기지 않음","우선변제권 있음","물상대위 있음(제370조, 제342조)","경매로 소멸"]}}],"함정":"선지 1을 틀렸다고 보기 쉽다. 1년 제한은 점유회수청구에만 걸리고 유치권 소멸에 따른 손해배상청구에는 걸리지 않는다. 선지 5는 불가분성(제321조)을 소멸청구에도 그대로 적용해 전부 소멸로 오해하기 쉽다."}},{"i":"S5-1-1-민법-22","r":"S5","g":1,"c":1,"n":62,"s":"민법","q":"저당권의 물상대위에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["저당부동산이 수용되어 설정자가 보상금을 지급받은 후에도 저당권자는 그 금전을 압류하여 물상대위권을 행사할 수 있다.","전세권을 목적으로 저당권을 설정한 경우, 존속기간 만료로 전세권이 소멸하면 저당권자는 전세금반환채권에 대하여 물상대위권을 행사할 수 없다.","저당부동산에 대한 압류가 있은 후 저당권설정자가 수취한 과실에는 저당권의 효력이 미치지 않는다.","저당부동산이 공용수용된 경우, 저당권자는 설정자가 받을 수용보상금이 지급되기 전에 압류하여 물상대위권을 행사할 수 있다.","저당부동산이 공용수용되더라도 저당권은 소멸하지 않고 사업시행자가 취득한 토지 위에 그대로 존속한다."],"a":[4],"L":"민2-8","o":"변형","x":{"한줄":"공용징수로 설정자가 받을 보상금은 지급·인도 전에 압류하면 저당권자가 물상대위권을 행사할 수 있다.","근거":[{"법령":"민법","조문":"제342조","원문":"제342조(물상대위) 질권은 질물의 멸실, 훼손 또는 공용징수로 인하여 질권설정자가 받을 금전 기타 물건에 대하여도 이를 행사할 수 있다. 이 경우에는 그 지급 또는 인도전에 압류하여야 한다."},{"법령":"민법","조문":"제370조","원문":"제370조(준용규정) 제214조, 제321조, 제333조, 제340조, 제341조 및 제342조의 규정은 저당권에 준용한다."},{"법령":"민법","조문":"제359조","원문":"제359조(과실에 대한 효력) 저당권의 효력은 저당부동산에 대한 압류가 있은 후에 저당권설정자가 그 부동산으로부터 수취한 과실 또는 수취할 수 있는 과실에 미친다. 그러나 저당권자가 그 부동산에 대한 소유권, 지상권 또는 전세권을 취득한 제삼자에 대하여는 압류한 사실을 통지한 후가 아니면 이로써 대항하지 못한다."},{"판례":"대법원 판례(전세권저당권과 물상대위)","요지":"전세권을 목적으로 한 저당권자는 전세권이 존속기간 만료로 소멸하면 전세금반환채권에 대하여 압류하는 방식으로 물상대위권을 행사할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"물상대위는 금전 그 밖의 물건이 지급 또는 인도되기 전에 압류해야 한다(제342조 후단, 제370조). 설정자가 보상금을 받은 뒤에는 압류해도 물상대위가 되지 않는다."},{"번호":2,"판정":"틀림","설명":"전세권이 소멸하면 저당권자는 전세금반환채권을 압류하여 물상대위권을 행사할 수 있다."},{"번호":3,"판정":"틀림","설명":"저당권의 효력은 압류 후 설정자가 수취한 과실 또는 수취할 수 있는 과실에 미친다(제359조 본문). 압류 전 수취한 과실에는 미치지 않는다."},{"번호":4,"판정":"옳음","설명":"공용징수로 설정자가 받을 금전에 대한 물상대위이고 지급 전 압류 요건을 충족한다(제342조, 제370조)."},{"번호":5,"판정":"틀림","설명":"공용수용에 의한 소유권 취득은 원시취득이어서 토지에 있던 저당권은 소멸한다. 저당권자는 보상금에 대한 물상대위로 보호받는다."}],"개념":[{"종류":"표","제목":"저당권의 효력이 미치는 범위","머리":["구분","효력 범위","근거"],"행":[["목적물","부합물·종물(설정행위에서 달리 정하면 제외)","제358조"],["과실","압류 후 설정자가 수취한 과실·수취할 수 있는 과실","제359조"],["피담보채권","원본·이자·위약금·손해배상·실행비용, 지연배상은 이행기 경과 후 1년분","제360조"],["물상대위","멸실·훼손·공용징수로 설정자가 받을 금전 등(지급·인도 전 압류)","제370조, 제342조"],["건물 축조","토지 저당 후 지은 건물은 일괄경매 가능, 건물 대가에서는 우선변제 불가","제365조"]]},{"종류":"흐름","제목":"물상대위권 행사 절차","단계":[{"이름":"대위물 발생","설명":"목적물의 멸실·훼손·공용징수로 설정자가 금전 등을 받게 됨"},{"이름":"지급·인도 전 압류","설명":"저당권자가 직접 압류해야 특정성이 유지됨"},{"이름":"채권 추심·전부","설명":"압류한 금전채권에 대해 추심명령 또는 전부명령을 받음"},{"이름":"우선변제","설명":"다른 채권자보다 먼저 피담보채권 충당"}]}],"함정":"선지 5처럼 수용 뒤에도 저당권이 남는다고 보기 쉽다. 수용은 원시취득이어서 저당권이 소멸하고 그 대신 보상금에 물상대위한다. 선지 1은 지급 후 압류가 되는지에서 갈리며 제342조 후단이 압류 시점을 지급·인도 전으로 못 박고 있다."}},{"i":"S5-1-1-민법-23","r":"S5","g":1,"c":1,"n":63,"s":"민법","q":"甲은 2020. 1. 1. 乙에게 1억원을 대여하면서 변제기 2020. 12. 31., 이율 연 5 %, 이자는 매달 말일 지급하기로 약정하였고, 그 담보로 당일 乙소유 토지에 저당권을 취득하였다. 乙이 차용일 이후부터 한 번도 이자를 지급하지 않았고, 甲은 2023. 7. 1. 저당권실행을 위한 경매를 신청하였다. 2023. 12. 31. 배당절차에서 배당재원 3억원으로 배당을 실시하게 되었는데, 甲은 총 1억 2,000만원의 채권신고서를 제출하였다. 甲의 배당금액은? (甲보다 우선하는 채권자는 없으나 2억원의 후순위저당권자가 있고, 공휴일 및 소멸시효와 이자에 대한 지연손해금 등은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["1억 500만원","1억 1,000만원","1억 1,500만원","1억 1,750만원","1억 2,000만원"],"a":[2],"L":"민2-8","o":"기출","x":{"한줄":"정상이자 1년분 500만원과 변제기 이후 지연배상 1년분 500만원만 담보되어 원금 1억원을 더한 1억 1,000만원을 배당받는다.","근거":[{"법령":"민법","조문":"제360조","원문":"제360조(피담보채권의 범위) 저당권은 원본, 이자, 위약금, 채무불이행으로 인한 손해배상 및 저당권의 실행비용을 담보한다. 그러나 지연배상에 대하여는 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"원금 1억원에 이자 500만원(1년분)만 더한 금액이다. 변제기 이후 지연배상 1년분 500만원이 빠졌다."},{"번호":2,"판정":"-","설명":"원금 1억원 + 약정기간 이자 500만원 + 지연배상 1년분 500만원 = 1억 1,000만원(제360조 단서)."},{"번호":3,"판정":"-","설명":"원금에 이자 3년분(1,500만원)을 더한 값이다. 지연배상은 3년이 아니라 1년분만 담보된다."},{"번호":4,"판정":"-","설명":"원금에 이자 3.5년분(1,750만원)을 더한 값이다. 경매신청일(2023.7.1)까지 이자를 모두 센 결과이며 제360조 단서에 어긋난다."},{"번호":5,"판정":"-","설명":"원금에 이자 4년분(2,000만원)을 더한 값으로 채권신고액과 같다. 신고액이 커도 담보 범위는 제360조로 정해진다."}],"개념":[{"종류":"계산","제목":"저당권 피담보채권 범위 계산","단계":[{"설명":"원본","식":"대여금","값":"1억원"},{"설명":"약정기간(2020.1.1~12.31) 이자는 전부 담보","식":"1억원 × 5% × 1년","값":"500만원"},{"설명":"변제기(2020.12.31) 후 지연배상은 1년분만 저당권으로 담보","식":"1억원 × 5% × 1년","값":"500만원"},{"설명":"배당액","식":"1억원 + 500만원 + 500만원","값":"1억 1,000만원"}]},{"종류":"표","제목":"저당권 피담보채권의 범위(제360조)","머리":["항목","담보 여부","비고"],"행":[["원본","담보","-"],["약정 이자","담보","변제기까지의 이자 전부"],["위약금","담보","-"],["채무불이행 손해배상","담보","-"],["저당권 실행비용","담보","-"],["지연배상","원본 이행기일 경과 후 1년분만","그 이상은 저당권 행사 불가"]]}],"함정":"경매신청일(2023.7.1)이나 배당일(2023.12.31)까지의 이자를 모두 더하기 쉽다. 지연배상은 이행기 경과 후 1년분에 한하므로 3년이 넘게 지났어도 1년분만 가산한다. 후순위저당권자가 있어 초과분은 후순위자 몫이 된다."}},{"i":"S5-1-1-민법-24","r":"S5","g":1,"c":1,"n":64,"s":"민법","q":"저당권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["저당권설정자의 책임 있는 사유로 저당물의 가액이 현저히 감소된 때에는 저당권자는 설정자에게 원상회복 또는 상당한 담보의 제공을 청구할 수 있다.","토지에 저당권을 설정한 후 설정자가 그 토지에 건물을 신축한 경우, 저당권자는 토지와 건물을 일괄하여 경매를 청구할 수 있고 건물의 경매대가에서도 우선변제를 받는다.","저당권이 담보하는 지연배상은 원본의 이행기일이 지난 후의 기간 전부에 대하여 저당권을 행사할 수 있다.","저당부동산에 지상권을 취득한 제3자는 저당권자에게 담보된 채권을 변제하고 저당권의 소멸을 청구할 수 없다.","저당권으로 담보한 채권이 시효로 소멸하더라도 저당권은 독립하여 존속한다."],"a":[1],"L":"민2-8","o":"변형","x":{"한줄":"설정자의 책임 있는 사유로 저당물 가액이 현저히 감소하면 저당권자는 원상회복이나 상당한 담보 제공을 청구할 수 있다(제362조).","근거":[{"법령":"민법","조문":"제362조","원문":"제362조(저당물의 보충) 저당권설정자의 책임있는 사유로 인하여 저당물의 가액이 현저히 감소된 때에는 저당권자는 저당권설정자에 대하여 그 원상회복 또는 상당한 담보제공을 청구할 수 있다."},{"법령":"민법","조문":"제365조","원문":"제365조(저당지상의 건물에 대한 경매청구권) 토지를 목적으로 저당권을 설정한 후 그 설정자가 그 토지에 건물을 축조한 때에는 저당권자는 토지와 함께 그 건물에 대하여도 경매를 청구할 수 있다. 그러나 그 건물의 경매대가에 대하여는 우선변제를 받을 권리가 없다."},{"법령":"민법","조문":"제360조","원문":"제360조(피담보채권의 범위) 저당권은 원본, 이자, 위약금, 채무불이행으로 인한 손해배상 및 저당권의 실행비용을 담보한다. 그러나 지연배상에 대하여는 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다."},{"법령":"민법","조문":"제364조","원문":"제364조(제삼취득자의 변제) 저당부동산에 대하여 소유권, 지상권 또는 전세권을 취득한 제삼자는 저당권자에게 그 부동산으로 담보된 채권을 변제하고 저당권의 소멸을 청구할 수 있다."},{"법령":"민법","조문":"제369조","원문":"제369조(부종성) 저당권으로 담보한 채권이 시효의 완성 기타 사유로 인하여 소멸한 때에는 저당권도 소멸한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제362조가 정한 저당물의 보충이다. 설정자의 책임 있는 사유로 가액이 현저히 감소해야 한다."},{"번호":2,"판정":"틀림","설명":"일괄경매는 가능하나 건물의 경매대가에서는 우선변제를 받을 권리가 없다(제365조 단서)."},{"번호":3,"판정":"틀림","설명":"지연배상은 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다(제360조 단서)."},{"번호":4,"판정":"틀림","설명":"소유권·지상권·전세권을 취득한 제3자는 변제하고 저당권의 소멸을 청구할 수 있다(제364조)."},{"번호":5,"판정":"틀림","설명":"저당권은 피담보채권이 시효 완성 등으로 소멸하면 함께 소멸한다(제369조 부종성)."}],"개념":[{"종류":"표","제목":"저당권 관련 제3자의 지위","머리":["구분","권리","근거"],"행":[["제3취득자(소유권·지상권·전세권)","변제 후 저당권 소멸 청구","제364조"],["저당물의 소유권 취득자","경매인이 될 수 있음","제363조 제2항"],["제3취득자의 필요비·유익비","경매대가에서 우선상환","제367조"],["저당권설정자","가액 감소 시 원상회복·담보제공 의무","제362조"],["저당권자","건물 일괄경매 청구(건물 대가 우선변제는 불가)","제365조"]]},{"종류":"비교","제목":"저당권과 피담보채권의 관계","왼쪽":{"이름":"부종성·수반성","항목":["피담보채권이 소멸하면 저당권도 소멸(제369조)","채권과 분리하여 양도·담보제공 불가(제361조)"]},"오른쪽":{"이름":"독립 처분 금지","항목":["저당권만 따로 양도하지 못함","채권 양도 시 저당권은 함께 이전"]}}],"함정":"선지 2의 일괄경매 후 건물 대가 우선변제 부분이 가장 많이 틀린다. 일괄경매권은 있으나 우선변제권은 토지 대가에만 있다. 선지 4는 지상권 취득자도 제364조의 제3취득자임을 놓치기 쉽다."}},{"i":"S5-1-1-민법-25","r":"S5","g":1,"c":1,"n":65,"s":"민법","q":"계약의 유형에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["도급계약은 일이 완성되어야 성립하는 요물계약이다.","사용대차는 쌍무·유상계약이다.","매매계약은 쌍무·유상·낙성·불요식계약이다.","부동산교환계약은 계약서를 작성해야 성립하는 요식계약이다.","증여계약은 서면으로 하지 않으면 성립하지 않는다."],"a":[3],"L":"민3-1","o":"변형","x":{"한줄":"매매는 당사자의 합의만으로 성립하고 양쪽이 서로 채무를 지며 대가가 있는 계약이어서 쌍무·유상·낙성·불요식계약이다.","근거":[{"법령":"민법","조문":"제563조","원문":"제563조(매매의 의의) 매매는 당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 그 대금을 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제664조","원문":"제664조(도급의 의의) 도급은 당사자 일방이 어느 일을 완성할 것을 약정하고 상대방이 그 일의 결과에 대하여 보수를 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제609조","원문":"제609조(사용대차의 의의) 사용대차는 당사자 일방이 상대방에게 무상으로 사용, 수익하게 하기 위하여 목적물을 인도할 것을 약정하고 상대방은 이를 사용, 수익한 후 그 물건을 반환할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제596조","원문":"제596조(교환의 의의) 교환은 당사자 쌍방이 금전 이외의 재산권을 상호이전할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제554조","원문":"제554조(증여의 의의) 증여는 당사자 일방이 무상으로 재산을 상대방에 수여하는 의사를 표시하고 상대방이 이를 승낙함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제555조","원문":"제555조(서면에 의하지 아니한 증여와 해제) 증여의 의사가 서면으로 표시되지 아니한 경우에는 각 당사자는 이를 해제할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"도급은 일의 완성을 약정하고 보수 지급을 약정함으로써 효력이 생기는 낙성계약이다(제664조)."},{"번호":2,"판정":"틀림","설명":"사용대차는 무상으로 사용·수익하게 하는 무상·편무계약이다(제609조)."},{"번호":3,"판정":"옳음","설명":"매매는 재산권 이전 약정과 대금 지급 약정으로 성립한다(제563조). 방식 제한이 없다."},{"번호":4,"판정":"틀림","설명":"교환은 금전 이외의 재산권을 상호 이전할 것을 약정함으로써 성립하며(제596조) 서면은 성립요건이 아니다. 유상·쌍무·낙성·불요식계약이다."},{"번호":5,"판정":"틀림","설명":"증여는 무상 수여의 의사 표시와 승낙으로 성립한다(제554조). 서면이 없으면 각 당사자가 해제할 수 있을 뿐이다(제555조)."}],"개념":[{"종류":"표","제목":"전형계약의 분류","머리":["계약","쌍무/편무","유상/무상","낙성/요물"],"행":[["증여","편무","무상","낙성"],["매매·교환","쌍무","유상","낙성"],["사용대차","편무","무상","낙성"],["임대차","쌍무","유상","낙성"],["도급","쌍무","유상","낙성"],["이자부 소비대차","쌍무","유상","낙성"]]},{"종류":"비교","제목":"계약 분류의 기준","왼쪽":{"이름":"쌍무·편무","항목":["쌍무: 양쪽이 서로 대가적 채무를 부담","편무: 한쪽만 채무를 부담","동시이행항변권·위험부담은 쌍무계약에만 적용"]},"오른쪽":{"이름":"유상·무상","항목":["유상: 서로 대가적 출연","무상: 한쪽만 출연","매매 규정은 다른 유상계약에 준용(제567조)"]}}],"함정":"증여는 서면 없이도 성립하고 해제만 가능하다. 도급을 일의 완성 시 성립하는 요물계약으로 오해하기 쉽다. 사용대차는 대가가 없어 편무·무상이다."}},{"i":"S5-1-1-민법-26","r":"S5","g":1,"c":1,"n":66,"s":"민법","q":"제3자를 위한 계약에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["제3자의 권리가 생긴 후에는 계약 당사자가 이를 변경하거나 소멸시키지 못한다.","요약자와 수익자 사이의 대가관계가 무효인 경우, 낙약자는 이를 이유로 수익자에 대한 급부를 거절할 수 있다.","낙약자의 채무불이행이 있으면 요약자는 수익자의 동의 없이 계약을 해제할 수 있다.","낙약자는 상당한 기간을 정하여 수익자에게 계약의 이익을 받을지 확답하도록 최고할 수 있다.","수익자는 계약의 당사자가 아니므로 계약을 해제할 수 없다."],"a":[2],"L":"민3-1","o":"변형","x":{"한줄":"요약자와 수익자 사이의 대가관계는 낙약자와 요약자 사이의 계약과 별개여서, 대가관계가 무효여도 낙약자는 급부를 거절하지 못한다.","근거":[{"법령":"민법","조문":"제539조","원문":"제539조(제삼자를 위한 계약) ①계약에 의하여 당사자 일방이 제삼자에게 이행할 것을 약정한 때에는 그 제삼자는 채무자에게 직접 그 이행을 청구할 수 있다. ②전항의 경우에 제삼자의 권리는 그 제삼자가 채무자에 대하여 계약의 이익을 받을 의사를 표시한 때에 생긴다."},{"법령":"민법","조문":"제540조","원문":"제540조(채무자의 제삼자에 대한 최고권) 전조의 경우에 채무자는 상당한 기간을 정하여 계약의 이익의 향수여부의 확답을 제삼자에게 최고할 수 있다. 채무자가 그 기간내에 확답을 받지 못한 때에는 제삼자가 계약의 이익을 받을 것을 거절한 것으로 본다."},{"법령":"민법","조문":"제541조","원문":"제541조(제삼자의 권리의 확정) 제539조의 규정에 의하여 제삼자의 권리가 생긴 후에는 당사자는 이를 변경 또는 소멸시키지 못한다."},{"법령":"민법","조문":"제542조","원문":"제542조(채무자의 항변권) 채무자는 제539조의 계약에 기한 항변으로 그 계약의 이익을 받을 제삼자에게 대항할 수 있다."},{"판례":"대법원 판례(제3자를 위한 계약의 대가관계)","요지":"요약자와 제3자 사이의 대가관계의 부존재·무효·취소는 낙약자와 요약자 사이의 계약 효력에 영향을 미치지 않고, 낙약자는 그것을 이유로 제3자에게 급부를 거절하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수익의 의사표시로 제3자의 권리가 확정된 뒤에는 당사자가 변경·소멸시키지 못한다(제541조)."},{"번호":2,"판정":"틀림","설명":"낙약자가 수익자에게 대항할 수 있는 항변은 낙약자와 요약자 사이의 계약(기본관계)에 기한 것이다(제542조). 대가관계의 흠은 낙약자의 항변사유가 아니다."},{"번호":3,"판정":"옳음","설명":"해제권은 계약 당사자인 요약자에게 있고 수익자의 동의는 필요 없다."},{"번호":4,"판정":"옳음","설명":"낙약자의 최고권이다. 기간 내에 확답을 받지 못하면 수익자가 이익을 거절한 것으로 본다(제540조)."},{"번호":5,"판정":"옳음","설명":"수익자는 계약 당사자가 아니어서 해제권·취소권이 없다. 낙약자에게 급부를 직접 청구할 권리만 가진다(제539조 제1항)."}],"개념":[{"종류":"비교","제목":"기본관계와 대가관계","왼쪽":{"이름":"기본관계(보상관계)","항목":["요약자와 낙약자 사이의 계약","낙약자는 이 계약에 기한 항변으로 수익자에게 대항 가능(제542조)","계약의 하자는 급부 거절 사유"]},"오른쪽":{"이름":"대가관계","항목":["요약자와 수익자 사이의 관계(증여·변제 등)","흠이 있어도 기본관계에 영향 없음","낙약자는 이를 이유로 급부 거절 불가"]}},{"종류":"표","제목":"제3자를 위한 계약의 당사자별 권리","머리":["당사자","권리·의무","근거"],"행":[["수익자","수익의 의사표시 시 낙약자에게 직접 이행청구권 취득","제539조 제2항"],["낙약자","최고권, 기본관계상 항변권","제540조, 제542조"],["요약자","해제권(수익자 동의 불요), 낙약자에 대한 이행청구권","판례"],["수익자 확정 후","당사자는 권리를 변경·소멸시키지 못함","제541조"]]}],"함정":"낙약자가 대항할 수 있는 항변을 대가관계의 흠으로까지 넓혀 읽기 쉽다. 제542조는 낙약자와 요약자 사이 계약에 기한 항변만 허용한다."}},{"i":"S5-1-1-민법-27","r":"S5","g":1,"c":1,"n":67,"s":"민법","q":"계약해제에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["계약의 당사자 일방이 수인인 경우, 해제는 그 전원으로부터 또는 전원에 대하여 하여야 한다.","계약이 해제되어 반환할 금전에는 그 받은 날부터 이자를 가하여야 한다.","계약이 해제되면 소급효에 따라 해제 전에 이미 소유권이전등기를 마친 제3자의 권리도 소멸한다.","계약의 해제는 손해배상의 청구에 영향을 미치지 않는다.","해제권 행사 기간을 정하지 않은 경우, 상대방은 상당한 기간을 정하여 해제권 행사 여부의 확답을 최고할 수 있다."],"a":[3],"L":"민3-1","o":"변형","x":{"한줄":"계약이 해제되어도 해제 전에 권리를 취득한 제3자의 권리는 해치지 못한다.","근거":[{"법령":"민법","조문":"제548조","원문":"제548조(해제의 효과, 원상회복의무) ①당사자 일방이 계약을 해제한 때에는 각 당사자는 그 상대방에 대하여 원상회복의 의무가 있다. 그러나 제삼자의 권리를 해하지 못한다. ②전항의 경우에 반환할 금전에는 그 받은 날로부터 이자를 가하여야 한다."},{"법령":"민법","조문":"제547조제1항","원문":"제547조(해지, 해제권의 불가분성) ①당사자의 일방 또는 쌍방이 수인인 경우에는 계약의 해지나 해제는 그 전원으로부터 또는 전원에 대하여 하여야 한다."},{"법령":"민법","조문":"제551조","원문":"제551조(해지, 해제와 손해배상) 계약의 해지 또는 해제는 손해배상의 청구에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제552조","원문":"제552조(해제권행사여부의 최고권) ①해제권의 행사의 기간을 정하지 아니한 때에는 상대방은 상당한 기간을 정하여 해제권행사여부의 확답을 해제권자에게 최고할 수 있다. ②전항의 기간내에 해제의 통지를 받지 못한 때에는 해제권은 소멸한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"해지·해제권의 불가분성이다(제547조 제1항)."},{"번호":2,"판정":"옳음","설명":"원상회복 시 반환할 금전에는 받은 날부터 이자를 가한다(제548조 제2항)."},{"번호":3,"판정":"틀림","설명":"해제의 효과로 각 당사자는 원상회복 의무를 지지만 제3자의 권리를 해치지 못한다(제548조 제1항 단서). 해제 전에 등기·인도 등 완전한 권리를 취득한 제3자는 보호된다."},{"번호":4,"판정":"옳음","설명":"해제와 손해배상은 병존한다(제551조)."},{"번호":5,"판정":"옳음","설명":"해제권 행사 여부에 대한 최고권이다. 기간 내에 해제 통지가 없으면 해제권이 소멸한다(제552조)."}],"개념":[{"종류":"표","제목":"계약해제의 요건과 효과","머리":["구분","내용","근거"],"행":[["이행지체","상당한 기간을 정한 최고 후 해제(미리 이행 거절 시 최고 불요)","제544조"],["정기행위","최고 없이 즉시 해제","제545조"],["이행불능","채무자의 책임 있는 사유일 때 최고 없이 해제","제546조"],["수인의 당사자","전원이 하거나 전원에 대하여 해제","제547조"],["효과","원상회복(제3자 권리 보호), 금전은 이자 가산","제548조"],["동시이행","원상회복의무는 동시이행","제549조"],["손해배상","해제와 별도로 청구 가능","제551조"]]},{"종류":"비교","제목":"해제와 합의해제","왼쪽":{"이름":"법정·약정해제","항목":["일방의 의사표시로 소급 소멸","원상회복 시 금전은 받은 날부터 이자","손해배상 청구 가능(제551조)"]},"오른쪽":{"이름":"합의해제","항목":["당사자 합의로 계약을 소멸","이자 가산은 약정이 있을 때만","특약이 없으면 채무불이행 손해배상 청구 못함"]}}],"함정":"해제의 소급효가 제3자에게도 미친다고 단정하기 쉽다. 제548조 제1항 단서가 제3자 보호를 규정한다. 합의해제는 이자 가산과 손해배상에서 법정해제와 다르다."}},{"i":"S5-1-1-민법-28","r":"S5","g":1,"c":1,"n":68,"s":"민법","q":"甲은 자신의 건물을 乙에게 팔기로 하고 계약금과 중도금을 수령하였으나, 인도와 이전등기 전에 태풍으로 그 건물이 전부 멸실되었다. 甲과 乙 모두에게 귀책사유가 없다면 다음 설명 중 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙은 甲에게 이행불능을 이유로 손해배상을 청구할 수 있다.","甲은 乙에게 잔대금의 지급을 청구할 수 있다.","乙이 이미 지급한 계약금과 중도금을 반환받으려면 반드시 매매계약을 해제하여야 한다.","乙은 이미 지급한 계약금과 중도금을 甲에게 부당이득으로 반환청구할 수 있다.","乙이 수령을 지체하던 중 건물이 멸실된 경우에도 乙은 이미 지급한 중도금을 반환청구할 수 있다."],"a":[4],"L":"민3-1","o":"변형","x":{"한줄":"쌍방 귀책 없이 매도인의 채무가 불능이 되면 매도인은 대금을 청구하지 못하고, 매수인은 이미 지급한 금액을 부당이득으로 돌려받는다.","근거":[{"법령":"민법","조문":"제537조","원문":"제537조(채무자위험부담주의) 쌍무계약의 당사자 일방의 채무가 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구하지 못한다."},{"법령":"민법","조문":"제538조제1항","원문":"제538조(채권자귀책사유로 인한 이행불능) ①쌍무계약의 당사자 일방의 채무가 채권자의 책임있는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구할 수 있다. 채권자의 수령지체 중에 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에도 같다."},{"법령":"민법","조문":"제546조","원문":"제546조(이행불능과 해제) 채무자의 책임있는 사유로 이행이 불능하게 된 때에는 채권자는 계약을 해제할 수 있다."},{"판례":"대법원 판례(쌍방 귀책 없는 이행불능과 기지급 대금)","요지":"채무자위험부담의 경우 채무자는 반대급부를 청구하지 못하며, 이미 이행받은 반대급부는 법률상 원인 없는 급부여서 부당이득으로 반환해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"甲에게 귀책사유가 없으므로 채무불이행 손해배상책임이 성립하지 않는다."},{"번호":2,"판정":"틀림","설명":"쌍방 무책의 이행불능이면 채무자는 상대방의 이행을 청구하지 못한다(제537조). 잔금 청구는 불가하다."},{"번호":3,"판정":"틀림","설명":"제537조에 따라 대금채무가 소멸하므로 해제할 필요가 없고, 이미 낸 금액은 부당이득으로 반환청구한다. 제546조의 해제는 채무자에게 귀책사유가 있을 때의 제도이다."},{"번호":4,"판정":"옳음","설명":"대금채무가 소멸하는데 이미 지급한 금액은 법률상 원인이 없어 부당이득이 된다."},{"번호":5,"판정":"틀림","설명":"채권자의 수령지체 중 쌍방 무책으로 불능이 되면 채무자는 상대방의 이행을 청구할 수 있다(제538조 제1항 후단). 乙은 중도금 반환을 청구하지 못한다."}],"개념":[{"종류":"표","제목":"이행불능의 유형과 효과","머리":["유형","대금(반대급부)","해제·배상","근거"],"행":[["쌍방 귀책 없음","소멸, 이미 낸 대금은 부당이득 반환","해제·배상 불가","제537조"],["채무자 귀책","소멸하지 않음, 채권자는 해제 가능","해제와 손해배상","제546조, 제551조"],["채권자 귀책","채무자는 대금 청구 가능(면한 이익은 상환)","-","제538조 제1항 전단, 제2항"],["채권자 수령지체 중 쌍방 무책","채무자는 대금 청구 가능","-","제538조 제1항 후단"]]},{"종류":"비교","제목":"대상청구권","왼쪽":{"이름":"요건","항목":["이행불능과 같은 원인으로 채무자가 이익(대상)을 취득","채권자가 반대급부를 이행하였거나 이행할 의사가 있음"]},"오른쪽":{"이름":"효과","항목":["채권자는 채무자가 받은 보상금·보험금 등의 양도를 청구","대상청구권을 행사하면 채권자의 반대급부 의무는 존속"]}}],"함정":"선지 3에서 제546조의 해제와 제537조의 대금채무 소멸을 섞기 쉽다. 쌍방 무책이면 해제 없이 곧바로 부당이득 반환이 된다. 선지 5는 수령지체 중이면 위험이 채권자에게 넘어간다는 점이 핵심이다."}},{"i":"S5-1-1-민법-29","r":"S5","g":1,"c":1,"n":69,"s":"민법","q":"청약과 승낙에 의한 계약의 성립에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["계약의 청약은 이를 철회하지 못한다.","격지자 간의 계약은 승낙의 통지가 청약자에게 도달한 때에 성립한다.","연착된 승낙은 청약자가 이를 새로운 청약으로 볼 수 있다.","승낙자가 청약에 조건을 붙이거나 변경을 가하여 승낙한 때에는 그 청약의 거절과 동시에 새로 청약한 것으로 본다.","당사자 간에 동일한 내용의 청약이 상호 교차된 경우에는 양 청약이 상대방에게 도달한 때에 계약이 성립한다."],"a":[2],"L":"민3-1","o":"변형","x":{"한줄":"격지자 간의 계약은 승낙의 통지를 발송한 때에 성립한다(발신주의).","근거":[{"법령":"민법","조문":"제531조","원문":"제531조(격지자간의 계약성립시기) 격지자간의 계약은 승낙의 통지를 발송한 때에 성립한다."},{"법령":"민법","조문":"제527조","원문":"제527조(계약의 청약의 구속력) 계약의 청약은 이를 철회하지 못한다."},{"법령":"민법","조문":"제530조","원문":"제530조(연착된 승낙의 효력) 전2조의 경우에 연착된 승낙은 청약자가 이를 새 청약으로 볼 수 있다."},{"법령":"민법","조문":"제534조","원문":"제534조(변경을 가한 승낙) 승낙자가 청약에 대하여 조건을 붙이거나 변경을 가하여 승낙한 때에는 그 청약의 거절과 동시에 새로 청약한 것으로 본다."},{"법령":"민법","조문":"제533조","원문":"제533조(교차청약) 당사자간에 동일한 내용의 청약이 상호교차된 경우에는 양청약이 상대방에게 도달한 때에 계약이 성립한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"청약의 구속력이다(제527조)."},{"번호":2,"판정":"틀림","설명":"승낙의 통지가 도달한 때가 아니라 발송한 때에 성립한다(제531조)."},{"번호":3,"판정":"옳음","설명":"연착된 승낙은 청약자가 새 청약으로 볼 수 있다(제530조)."},{"번호":4,"판정":"옳음","설명":"변경을 가한 승낙은 청약의 거절이면서 새 청약이다(제534조)."},{"번호":5,"판정":"옳음","설명":"교차청약은 양 청약이 상대방에게 도달한 때 성립한다(제533조)."}],"개념":[{"종류":"표","제목":"계약의 성립시기","머리":["유형","성립시기","근거"],"행":[["승낙기간 정한 청약","기간 내 승낙 통지가 도달해야 함(늦으면 청약 실효)","제528조 제1항"],["승낙기간 없는 청약","상당한 기간 내 승낙 통지 도달","제529조"],["격지자 간 계약","승낙 통지를 발송한 때","제531조"],["승낙 통지 불필요한 경우","승낙으로 인정되는 사실이 있는 때(의사실현)","제532조"],["교차청약","양 청약이 상대방에게 도달한 때","제533조"]]},{"종류":"흐름","제목":"청약에서 계약 성립까지","단계":[{"이름":"청약","설명":"상대방에게 도달하면 효력이 생기고 철회할 수 없다(제527조)"},{"이름":"승낙","설명":"기간 안에 도달해야 하며, 격지자 간 계약의 성립시기는 발송 시(제531조)"},{"이름":"연착·변경","설명":"연착한 승낙은 새 청약으로 볼 수 있고, 변경을 가한 승낙은 새 청약(제530조, 제534조)"},{"이름":"계약 성립","설명":"청약과 승낙의 주관적·객관적 합치"}]}],"함정":"청약은 도달해야 효력이 생기지만 격지자 간 계약은 승낙 발송 시에 성립한다. 도달주의와 발신주의가 갈리는 지점을 묻는 문항이다."}},{"i":"S5-1-1-민법-30","r":"S5","g":1,"c":1,"n":70,"s":"민법","q":"甲은 그 소유의 X토지에 대하여 乙과 매매계약을 체결하였다. 다음 설명 중 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["매매계약에 관한 비용은 특약이 없으면 甲과 乙이 균분하여 부담한다.","乙이 甲에게 중도금을 지급한 후에는 甲은 계약금의 배액을 상환하고 계약을 해제할 수 없다.","X토지를 인도받은 乙은 대금지급에 기한이 없다면 인도받은 날부터 대금의 이자를 지급하여야 한다.","乙이 대금을 완제하지 않았다면, X토지를 인도받지 못한 채 이전등기만 마쳤더라도 X토지에서 생긴 과실은 甲에게 속한다.","乙이 대금을 모두 지급하였다면, X토지를 인도받지 못했더라도 대금 완제 이후 X토지에서 생긴 과실은 甲에게 속한다."],"a":[5],"L":"민3-2","o":"변형","x":{"한줄":"매수인이 대금을 모두 지급하면 인도받기 전이라도 그 이후 생긴 과실은 매수인에게 귀속한다.","근거":[{"법령":"민법","조문":"제587조","원문":"제587조(과실의 귀속, 대금의 이자) 매매계약있은 후에도 인도하지 아니한 목적물로부터 생긴 과실은 매도인에게 속한다. 매수인은 목적물의 인도를 받은 날로부터 대금의 이자를 지급하여야 한다. 그러나 대금의 지급에 대하여 기한이 있는 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제566조","원문":"제566조(매매계약의 비용의 부담) 매매계약에 관한 비용은 당사자 쌍방이 균분하여 부담한다."},{"법령":"민법","조문":"제565조제1항","원문":"제565조(해약금) ①매매의 당사자 일방이 계약당시에 금전 기타 물건을 계약금, 보증금등의 명목으로 상대방에게 교부한 때에는 당사자간에 다른 약정이 없는 한 당사자의 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 매매계약을 해제할 수 있다."},{"판례":"대법원 판례(대금 완제와 과실의 귀속)","요지":"매매 목적물이 인도되지 않았더라도 매수인이 대금을 완제한 때에는 그 이후의 과실은 매수인에게 귀속한다. 대금 완제 전에는 인도 전이면 과실이 매도인에게 속한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"매매계약의 비용은 당사자 쌍방이 균분하여 부담한다(제566조)."},{"번호":2,"판정":"옳음","설명":"계약금에 의한 해제는 당사자 일방이 이행에 착수할 때까지만 가능하고, 중도금 지급은 이행의 착수에 해당한다(제565조 제1항)."},{"번호":3,"판정":"옳음","설명":"인도받은 날부터 이자를 지급하는 것이 원칙이고 대금지급에 기한이 있으면 예외이다(제587조)."},{"번호":4,"판정":"옳음","설명":"제587조에 따라 인도 전 목적물의 과실은 매도인에게 속하고, 이전등기를 먼저 받았어도 대금을 완제하지 않았다면 같다."},{"번호":5,"판정":"틀림","설명":"대금을 완제하면 인도 전이라도 그 이후의 과실은 매수인에게 귀속한다는 것이 판례이다."}],"개념":[{"종류":"표","제목":"매매의 효력(제566조~제587조)","머리":["쟁점","내용","근거"],"행":[["계약 비용","당사자 쌍방이 균분 부담","제566조"],["해약금","이행에 착수할 때까지 교부자는 포기, 수령자는 배액 상환","제565조 제1항"],["동시이행","매도인의 권리이전과 매수인의 대금지급은 동시 이행","제568조 제2항"],["과실","인도하지 않은 목적물의 과실은 매도인에게 속함","제587조 제1문"],["대금 이자","인도받은 날부터 이자 지급(대금 기한 있으면 제외)","제587조 제2문"],["대금 완제 후","인도 전이라도 과실은 매수인에게 귀속","판례"]]},{"종류":"계산","제목":"해약금 해제 시 금액","단계":[{"설명":"매수인이 해제할 때","식":"교부한 계약금 포기","값":"계약금 상실"},{"설명":"매도인이 해제할 때","식":"받은 계약금 + 같은 금액","값":"계약금의 2배 상환"},{"설명":"예: 계약금 1,000만원","식":"1,000만원 × 2","값":"2,000만원 상환(수령한 1,000만원 포함)"}]}],"함정":"인도 전 과실은 매도인에게 속한다는 제587조를 대금 완제 후에도 그대로 적용하기 쉽다. 판례는 대금 완제를 기준으로 과실 귀속을 바꾼다."}},{"i":"S5-1-1-민법-31","r":"S5","g":1,"c":1,"n":71,"s":"민법","q":"민법상 환매에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["환매권은 양도할 수 없는 일신전속권이다.","매매계약이 무효이면 환매특약도 무효이다.","환매기간을 정한 경우에는 그 기간을 다시 연장하지 못한다.","환매특약등기는 매수인의 권리취득의 등기에 부기하는 방식으로 한다.","환매특약은 매매계약과 동시에 해야 한다."],"a":[1],"L":"민3-2","o":"기출","x":{"한줄":"환매권은 재산권이어서 양도할 수 있고 매도인의 채권자도 대위하여 행사할 수 있다.","근거":[{"법령":"민법","조문":"제590조","원문":"제590조(환매의 의의) ①매도인이 매매계약과 동시에 환매할 권리를 보류한 때에는 그 영수한 대금 및 매수인이 부담한 매매비용을 반환하고 그 목적물을 환매할 수 있다. ②전항의 환매대금에 관하여 특별한 약정이 있으면 그 약정에 의한다. ③전2항의 경우에 목적물의 과실과 대금의 이자는 특별한 약정이 없으면 이를 상계한 것으로 본다."},{"법령":"민법","조문":"제591조","원문":"제591조(환매기간) ①환매기간은 부동산은 5년, 동산은 3년을 넘지 못한다. 약정기간이 이를 넘는 때에는 부동산은 5년, 동산은 3년으로 단축한다. ②환매기간을 정한 때에는 다시 이를 연장하지 못한다. ③환매기간을 정하지 아니한 때에는 그 기간은 부동산은 5년, 동산은 3년으로 한다."},{"법령":"민법","조문":"제593조","원문":"제593조(환매권의 대위행사와 매수인의 권리) 매도인의 채권자가 매도인을 대위하여 환매하고자 하는 때에는 매수인은 법원이 선정한 감정인의 평가액에서 매도인이 반환할 금액을 공제한 잔액으로 매도인의 채무를 변제하고 잉여액이 있으면 이를 매도인에게 지급하여 환매권을 소멸시킬 수 있다."},{"법령":"부동산등기법","조문":"제52조","원문":"제52조(부기로 하는 등기) 등기관이 다음 각 호의 등기를 할 때에는 부기로 하여야 한다. 다만, 제5호의 등기는 등기상 이해관계 있는 제3자의 승낙이 없는 경우에는 그러하지 아니하다. 1. 등기명의인표시의 변경이나 경정의 등기 2. 소유권 외의 권리의 이전등기 3. 소유권 외의 권리를 목적으로 하는 권리에 관한 등기 4. 소유권 외의 권리에 대한 처분제한 등기 5. 권리의 변경이나 경정의 등기 6. 제53조의 환매특약등기 7. 제54조의 권리소멸약정등기 8. 제67조제1항 후단의 공유물 분할금지의 약정등기 9. 그 밖에 대법원규칙으로 정하는 등기"},{"법령":"부동산등기법","조문":"제53조","원문":"제53조(환매특약의 등기) 등기관이 환매특약의 등기를 할 때에는 다음 각 호의 사항을 기록하여야 한다. 다만, 제3호는 등기원인에 그 사항이 정하여져 있는 경우에만 기록한다. 1. 매수인이 지급한 대금 2. 매매비용 3. 환매기간"}],"선지":[{"번호":1,"판정":"틀림","설명":"환매권은 일신전속권이 아니다. 매도인의 채권자가 대위하여 환매할 수 있고(제593조), 환매권도 양도할 수 있다."},{"번호":2,"판정":"옳음","설명":"환매특약은 매매계약에 부수하는 약정이어서 매매가 무효이면 함께 무효가 된다."},{"번호":3,"판정":"옳음","설명":"환매기간을 정한 때에는 다시 연장하지 못한다(제591조 제2항)."},{"번호":4,"판정":"옳음","설명":"환매특약의 등기는 부기로 한다(부동산등기법 제52조 제6호, 제53조)."},{"번호":5,"판정":"옳음","설명":"환매특약은 매매계약과 동시에 하여야 한다(제590조 제1항)."}],"개념":[{"종류":"표","제목":"환매의 요건과 효과","머리":["구분","내용","근거"],"행":[["시기","매매계약과 동시에 환매권 보류","제590조 제1항"],["환매대금","영수한 대금 + 매수인이 부담한 매매비용(특약 우선)","제590조 제1·2항"],["과실과 이자","특약이 없으면 상계한 것으로 봄","제590조 제3항"],["환매기간","부동산 5년, 동산 3년 이내 / 정하지 않으면 5년, 3년 / 연장 불가","제591조"],["제3자 대항","매매등기와 동시에 환매권 보류 등기","제592조"],["대금 제공","기간 내 대금과 매매비용을 제공하지 않으면 환매권 상실","제594조 제1항"],["비용 상환","매수인·전득자가 지출한 비용은 제203조에 따라 상환","제594조 제2항"]]},{"종류":"흐름","제목":"환매 절차","단계":[{"이름":"환매특약","설명":"매매계약과 동시에 합의하고 매매등기와 동시에 환매특약 등기(부기)"},{"이름":"환매권 행사","설명":"환매기간(최장 부동산 5년) 안에 대금과 매매비용을 매수인에게 제공"},{"이름":"소유권 회복","설명":"환매 의사표시와 대금 제공으로 목적물 소유권이 매도인에게 복귀"},{"이름":"비용 상환","설명":"매수인·전득자가 지출한 필요비·유익비는 제203조에 따라 상환"}]}],"함정":"환매권을 일신전속권으로 보는 것이 함정이다. 환매권은 양도·대위행사가 가능하다. 환매기간 5년은 부동산의 최장 기간이고 연장은 안 된다."}},{"i":"S5-1-1-민법-32","r":"S5","g":1,"c":1,"n":72,"s":"민법","q":"환매에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["부동산 매매에서 환매기간을 정하지 않은 때에는 그 기간은 5년으로 한다.","환매특약은 매매계약 체결 후 이전등기를 마치기 전이라면 별도의 합의로 할 수 있다.","특별한 약정이 없으면 환매대금은 매도인이 받은 대금만으로 정해지고, 매수인이 부담한 매매비용은 포함되지 않는다.","환매권은 매수인의 승낙이 있어야 행사의 효력이 생긴다.","특별한 약정이 없으면 매수인이 환매 전에 수취한 과실은 환매 시 매도인에게 반환하여야 한다."],"a":[1],"L":"민3-2","o":"변형","x":{"한줄":"환매기간을 정하지 않은 때에는 부동산은 5년, 동산은 3년으로 한다.","근거":[{"법령":"민법","조문":"제591조","원문":"제591조(환매기간) ①환매기간은 부동산은 5년, 동산은 3년을 넘지 못한다. 약정기간이 이를 넘는 때에는 부동산은 5년, 동산은 3년으로 단축한다. ②환매기간을 정한 때에는 다시 이를 연장하지 못한다. ③환매기간을 정하지 아니한 때에는 그 기간은 부동산은 5년, 동산은 3년으로 한다."},{"법령":"민법","조문":"제590조","원문":"제590조(환매의 의의) ①매도인이 매매계약과 동시에 환매할 권리를 보류한 때에는 그 영수한 대금 및 매수인이 부담한 매매비용을 반환하고 그 목적물을 환매할 수 있다. ②전항의 환매대금에 관하여 특별한 약정이 있으면 그 약정에 의한다. ③전2항의 경우에 목적물의 과실과 대금의 이자는 특별한 약정이 없으면 이를 상계한 것으로 본다."},{"법령":"민법","조문":"제594조제1항","원문":"제594조(환매의 실행) ①매도인은 기간내에 대금과 매매비용을 매수인에게 제공하지 아니하면 환매할 권리를 잃는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제591조 제3항이다."},{"번호":2,"판정":"틀림","설명":"환매특약은 매매계약과 동시에 해야 한다(제590조 제1항). 이후 합의는 환매특약이 아니라 새로운 매매의 예약이다."},{"번호":3,"판정":"틀림","설명":"환매대금은 영수한 대금과 매수인이 부담한 매매비용이다(제590조 제1항). 특별한 약정이 있으면 그에 따른다(제590조 제2항)."},{"번호":4,"판정":"틀림","설명":"환매권은 매도인의 일방적 의사표시로 행사하는 형성권이다. 기간 내에 대금과 매매비용을 제공하면 매수인의 승낙 없이 효력이 생긴다(제594조 제1항)."},{"번호":5,"판정":"틀림","설명":"특별한 약정이 없으면 목적물의 과실과 대금의 이자는 상계한 것으로 본다(제590조 제3항). 과실을 따로 반환하지 않는다."}],"개념":[{"종류":"표","제목":"환매기간","머리":["구분","부동산","동산"],"행":[["법정 최장 기간","5년","3년"],["약정이 최장 기간을 넘는 경우","5년으로 단축","3년으로 단축"],["기간을 정하지 않은 경우","5년","3년"],["기간 연장","불가","불가"]]},{"종류":"비교","제목":"환매와 재매매의 예약","왼쪽":{"이름":"환매","항목":["매매계약과 동시에 보류","일방적 의사표시(형성권)","환매대금: 받은 대금+매매비용","부동산은 환매등기로 제3자 대항(제592조)"]},"오른쪽":{"이름":"재매매의 예약","항목":["별도의 계약으로 예약","예약완결권 행사","매도인이 받은 대금 기준이 아님","당사자 약정에 따름"]}}],"함정":"환매기간 5년은 약정으로 정한 경우의 상한이기도 하고 약정이 없을 때의 기본 기간이기도 하다. 환매대금에 매수인이 부담한 매매비용이 포함된다는 점, 과실과 이자는 상계한 것으로 보는 점도 자주 묻는다."}},{"i":"S5-1-1-민법-33","r":"S5","g":1,"c":1,"n":73,"s":"민법","q":"임대인과 임차인 사이의 약정으로 유효한 것은? (단, 일시사용을 위한 임대차가 아님을 전제로 함)","b":null,"bs":"없음","img":[],"ch":["건물 임대차에서 차임 연체액이 1기의 차임액에 달하면 임대인이 계약을 해지할 수 있다는 약정","임차물의 일부가 임차인의 과실 없이 멸실되어 잔존부분만으로 임차의 목적을 달성할 수 없는 경우에도 임차인이 계약을 해지하지 못한다는 약정","임차인이 임대차 종료 시 유익비상환청구권을 포기한다는 약정","건물 소유를 목적으로 한 토지임대차에서 임차인의 지상물매수청구권을 배제하는 약정","건물 임차인이 적법하게 전대한 경우 전차인의 부속물매수청구권을 배제하는 약정"],"a":[3],"L":"민3-3","o":"변형","x":{"한줄":"유익비상환청구권은 제652조의 편면적 강행규정 대상이 아니어서 임차인이 사전에 포기하는 약정이 유효하다.","근거":[{"법령":"민법","조문":"제652조","원문":"제652조(강행규정) 제627조, 제628조, 제631조, 제635조, 제638조, 제640조, 제641조, 제643조 내지 제647조의 규정에 위반하는 약정으로 임차인이나 전차인에게 불리한 것은 그 효력이 없다."},{"법령":"민법","조문":"제626조제2항","원문":"제626조(임차인의 상환청구권) ②임차인이 유익비를 지출한 경우에는 임대인은 임대차종료시에 그 가액의 증가가 현존한 때에 한하여 임차인의 지출한 금액이나 그 증가액을 상환하여야 한다. 이 경우에 법원은 임대인의 청구에 의하여 상당한 상환기간을 허여할 수 있다."},{"법령":"민법","조문":"제640조","원문":"제640조(차임연체와 해지) 건물 기타 공작물의 임대차에는 임차인의 차임연체액이 2기의 차임액에 달하는 때에는 임대인은 계약을 해지할 수 있다."},{"법령":"민법","조문":"제627조","원문":"제627조(일부멸실 등과 감액청구, 해지권) ①임차물의 일부가 임차인의 과실없이 멸실 기타 사유로 인하여 사용, 수익할 수 없는 때에는 임차인은 그 부분의 비율에 의한 차임의 감액을 청구할 수 있다. ②전항의 경우에 그 잔존부분으로 임차의 목적을 달성할 수 없는 때에는 임차인은 계약을 해지할 수 있다."},{"법령":"민법","조문":"제643조","원문":"제643조(임차인의 갱신청구권, 매수청구권) 건물 기타 공작물의 소유 또는 식목, 채염, 목축을 목적으로 한 토지임대차의 기간이 만료한 경우에 건물, 수목 기타 지상시설이 현존한 때에는 제283조의 규정을 준용한다."},{"법령":"민법","조문":"제647조","원문":"제647조(전차인의 부속물매수청구권) ①건물 기타 공작물의 임차인이 적법하게 전대한 경우에 전차인이 그 사용의 편익을 위하여 임대인의 동의를 얻어 이에 부속한 물건이 있는 때에는 전대차의 종료시에 임대인에 대하여 그 부속물의 매수를 청구할 수 있다. ②임대인으로부터 매수하였거나 그 동의를 얻어 임차인으로부터 매수한 부속물에 대하여도 전항과 같다."}],"선지":[{"번호":1,"판정":"틀림","설명":"건물 임대차의 차임연체 해지는 2기의 차임액에 달해야 한다(제640조). 이보다 임차인에게 불리한 약정은 무효이다(제652조)."},{"번호":2,"판정":"틀림","설명":"잔존부분으로 임차 목적을 달성할 수 없으면 임차인은 해지할 수 있다(제627조 제2항). 이를 배제하는 약정은 임차인에게 불리해 무효이다(제652조)."},{"번호":3,"판정":"옳음","설명":"제626조는 제652조의 열거에 없는 임의규정이다. 임차인의 유익비상환청구권 포기 약정은 유효하다는 것이 판례이다."},{"번호":4,"판정":"틀림","설명":"지상물매수청구권(제643조)은 제652조의 강행규정이다. 배제 약정은 무효이다."},{"번호":5,"판정":"틀림","설명":"전차인의 부속물매수청구권(제647조)은 제652조의 강행규정이다. 배제 약정은 무효이다."}],"개념":[{"종류":"표","제목":"임대차 편면적 강행규정(제652조)","머리":["조문","내용","불리한 약정"],"행":[["제627조","일부멸실 시 차임감액청구, 목적 달성 불가 시 해지","무효"],["제628조","차임증감청구","무효"],["제631조","전차인의 권리 확정","무효"],["제635조","기간 약정 없는 임대차의 해지통고","무효"],["제638조","해지통고의 전차인 통지","무효"],["제640조·제641조","차임연체 해지(건물 2기)","무효"],["제643조~제647조","지상물·부속물 매수청구권, 전차인의 임대청구·매수청구","무효"]]},{"종류":"비교","제목":"임의규정과 강행규정","왼쪽":{"이름":"강행규정(임차인에게 불리하면 무효)","항목":["지상물매수청구권","부속물매수청구권","차임증감청구","차임연체 해지 기준"]},"오른쪽":{"이름":"임의규정(약정 유효)","항목":["비용상환청구권(제626조)","임차권 양도·전대 제한(제629조)","임차인의 차임 지급 시기 등","임차인에게 유리한 약정"]}}],"함정":"제652조에 열거되지 않은 조문은 임차인에게 불리해도 약정이 유효할 수 있다. 비용상환청구권(제626조)과 임차권 양도·전대 제한(제629조)이 대표적이다. 해지 사유를 다루는 조문 중에도 열거 여부가 갈린다."}},{"i":"S5-1-1-민법-34","r":"S5","g":1,"c":1,"n":74,"s":"민법","q":"임차인의 비용상환청구권과 부속물매수청구권에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임차인이 유익비를 지출한 경우, 임대인은 임대차 종료 시에 그 가액의 증가가 현존한 때에 한하여 지출한 금액이나 증가액을 상환하여야 한다.","임차인이 임차물의 보존에 관한 필요비를 지출한 때에는 임대차 종료를 기다리지 않고 임대인에게 그 상환을 청구할 수 있다.","건물 임차인이 임대인의 동의를 얻어 부속시킨 물건은 임대차 종료 시 임대인에게 그 매수를 청구할 수 있다.","임차인이 지출한 비용의 상환청구는 임대인이 목적물을 반환받은 날부터 6월 내에 하여야 한다.","건물 임차인이 임대인의 동의 없이 부속시킨 물건에 대해서도 임대차 종료 시 부속물매수청구권을 행사할 수 있다."],"a":[5],"L":"민3-3","o":"변형","x":{"한줄":"부속물매수청구권은 임대인의 동의를 얻어 부속시켰거나 임대인으로부터 매수한 물건에 인정되고, 동의 없이 부속시킨 물건에는 인정되지 않는다.","근거":[{"법령":"민법","조문":"제626조","원문":"제626조(임차인의 상환청구권) ①임차인이 임차물의 보존에 관한 필요비를 지출한 때에는 임대인에 대하여 그 상환을 청구할 수 있다. ②임차인이 유익비를 지출한 경우에는 임대인은 임대차종료시에 그 가액의 증가가 현존한 때에 한하여 임차인의 지출한 금액이나 그 증가액을 상환하여야 한다. 이 경우에 법원은 임대인의 청구에 의하여 상당한 상환기간을 허여할 수 있다."},{"법령":"민법","조문":"제646조","원문":"제646조(임차인의 부속물매수청구권) ①건물 기타 공작물의 임차인이 그 사용의 편익을 위하여 임대인의 동의를 얻어 이에 부속한 물건이 있는 때에는 임대차의 종료시에 임대인에 대하여 그 부속물의 매수를 청구할 수 있다. ②임대인으로부터 매수한 부속물에 대하여도 전항과 같다."},{"법령":"민법","조문":"제654조","원문":"제654조(준용규정) 제610조제1항, 제615조 내지 제617조의 규정은 임대차에 이를 준용한다."},{"법령":"민법","조문":"제617조","원문":"제617조(손해배상, 비용상환청구의 기간) 계약 또는 목적물의 성질에 위반한 사용, 수익으로 인하여 생긴 손해배상의 청구와 차주가 지출한 비용의 상환청구는 대주가 물건의 반환을 받은 날로부터 6월내에 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제626조 제2항이다. 법원은 임대인의 청구로 상당한 상환기간을 줄 수 있다."},{"번호":2,"판정":"옳음","설명":"필요비는 지출한 때 곧바로 상환을 청구할 수 있다(제626조 제1항)."},{"번호":3,"판정":"옳음","설명":"제646조 제1항이다. 임대인으로부터 매수한 부속물도 같다(제646조 제2항)."},{"번호":4,"판정":"옳음","설명":"제654조가 준용하는 제617조이다. 기간은 목적물 반환일부터 6월이다."},{"번호":5,"판정":"틀림","설명":"부속물매수청구권은 임대인의 동의를 얻어 부속한 물건 또는 임대인에게서 매수한 물건이 대상이다(제646조). 동의 없이 부속한 물건은 대상이 아니다."}],"개념":[{"종류":"표","제목":"임차인의 비용상환·매수청구권","머리":["구분","요건","효과·제한","근거"],"행":[["필요비","보존에 관한 비용","지출 즉시 상환 청구","제626조 제1항"],["유익비","개량을 위한 비용","임대차 종료 시 가액 증가가 현존하면 임대인 선택으로 지출액·증가액 상환(상환기간 허여 가능)","제626조 제2항"],["부속물매수청구권","임대인 동의 부속 또는 임대인에게서 매수","임대차 종료 시 매수 청구","제646조"],["행사기간","비용 상환청구","목적물 반환받은 날부터 6월","제654조, 제617조"],["건물 소유 토지임대차","지상물이 현존","갱신청구, 거절 시 매수청구","제643조"]]},{"종류":"비교","제목":"비용상환청구권과 부속물매수청구권","왼쪽":{"이름":"비용상환청구권","항목":["임차물 보존·개량 비용","임대인 동의 불필요","포기 특약 유효(임의규정)"]},"오른쪽":{"이름":"부속물매수청구권","항목":["임대인 동의 부속 또는 매수한 물건","독립성이 있는 물건(구성부분 제외)","불리한 약정 무효(제652조)"]}}],"함정":"유익비는 임대차 종료 시에만 청구할 수 있고 가액 증가가 현존해야 한다. 필요비와 혼동하지 않는다. 부속물은 동의 요건과 독립성이 있어야 대상이 되고, 차임 연체 등으로 해지된 경우 인정되지 않는다는 판례도 함께 묻는다."}},{"i":"S5-1-1-민법-35","r":"S5","g":1,"c":1,"n":75,"s":"민법","q":"乙은 甲소유의 X주택에 대하여 보증금 3억원으로 하는 임대차계약을 甲과 체결한 다음 즉시 대항요건을 갖추고 확정일자를 받아 현재 거주하고 있다. 다음 설명 중 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["묵시적 갱신으로 임대차가 갱신된 경우, 甲은 언제든지 乙에게 계약해지를 통지할 수 있다.","乙이 계약갱신요구권을 행사하여 갱신된 임대차에서도 乙은 언제든지 계약해지를 통지할 수 있고, 甲이 통지를 받은 날부터 3개월이 지나면 효력이 생긴다.","乙이 계약갱신요구권을 행사하여 갱신되는 경우, 보증금은 약정 보증금의 10분의 1까지 증액할 수 있다.","乙은 임대차기간이 끝나기 전이라도 보증금을 반환받지 못할 것에 대비하여 임차권등기명령을 신청할 수 있다.","임대차 기간 중 甲이 丙에게 X주택을 매도하고 이전등기를 마친 경우, 甲의 보증금반환채무는 丙에게 이전되지 않는다."],"a":[2],"L":"민4-1","o":"변형","x":{"한줄":"계약갱신요구권 행사로 갱신된 임대차의 해지에는 묵시적 갱신의 해지 규정이 준용되어, 임차인이 언제든 통지하고 3개월 뒤 효력이 생긴다.","근거":[{"법령":"주택임대차보호법","조문":"제6조의3제4항","원문":"제6조의3(계약갱신 요구 등) ④ 제1항에 따라 갱신되는 임대차의 해지에 관하여는 제6조의2를 준용한다."},{"법령":"주택임대차보호법","조문":"제6조의2","원문":"제6조의2(묵시적 갱신의 경우 계약의 해지) ① 제6조제1항에 따라 계약이 갱신된 경우 같은 조 제2항에도 불구하고 임차인은 언제든지 임대인에게 계약해지(契約解止)를 통지할 수 있다. ② 제1항에 따른 해지는 임대인이 그 통지를 받은 날부터 3개월이 지나면 그 효력이 발생한다."},{"법령":"주택임대차보호법","조문":"제7조","원문":"제7조(차임 등의 증감청구권) ① 당사자는 약정한 차임이나 보증금이 임차주택에 관한 조세, 공과금, 그 밖의 부담의 증감이나 경제사정의 변동으로 인하여 적절하지 아니하게 된 때에는 장래에 대하여 그 증감을 청구할 수 있다. 이 경우 증액청구는 임대차계약 또는 약정한 차임이나 보증금의 증액이 있은 후 1년 이내에는 하지 못한다. ② 제1항에 따른 증액청구는 약정한 차임이나 보증금의 20분의 1의 금액을 초과하지 못한다. 다만, 특별시ㆍ광역시ㆍ특별자치시ㆍ도 및 특별자치도는 관할 구역 내의 지역별 임대차 시장 여건 등을 고려하여 본문의 범위에서 증액청구의 상한을 조례로 달리 정할 수 있다."},{"법령":"주택임대차보호법","조문":"제3조의3제1항","원문":"제3조의3(임차권등기명령) ① 임대차가 끝난 후 보증금이 반환되지 아니한 경우 임차인은 임차주택의 소재지를 관할하는 지방법원ㆍ지방법원지원 또는 시ㆍ군 법원에 임차권등기명령을 신청할 수 있다."},{"법령":"주택임대차보호법","조문":"제3조제4항","원문":"제3조(대항력 등) ④ 임차주택의 양수인(讓受人)(그 밖에 임대할 권리를 승계한 자를 포함한다)은 임대인(賃貸人)의 지위를 승계한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"묵시적 갱신 후의 해지 통지권은 임차인에게만 있다(제6조의2 제1항). 임대인에게는 이런 권리가 없다."},{"번호":2,"판정":"옳음","설명":"제6조의3 제4항이 제6조의2를 준용한다. 임차인의 통지 후 임대인이 받은 날부터 3개월이 지나면 해지 효력이 생긴다(제6조의2 제2항)."},{"번호":3,"판정":"틀림","설명":"증액청구는 약정한 차임·보증금의 20분의 1을 넘지 못한다(제7조 제2항). 갱신되는 임대차도 제7조의 범위에서 증감한다(제6조의3 제3항)."},{"번호":4,"판정":"틀림","설명":"임차권등기명령은 임대차가 끝난 후 보증금이 반환되지 않은 경우에 신청한다(제3조의3 제1항)."},{"번호":5,"판정":"틀림","설명":"임차주택의 양수인은 임대인의 지위를 승계한 것으로 본다(제3조 제4항). 보증금반환채무도 양수인이 부담한다."}],"개념":[{"종류":"표","제목":"주택임대차 갱신 비교","머리":["구분","묵시적 갱신(제6조)","갱신요구권(제6조의3)"],"행":[["요건","임대인이 6개월~2개월 전, 임차인이 2개월 전까지 통지하지 않음","임차인이 6개월~2개월 전에 갱신 요구, 임대인은 정당한 사유 없이 거절 불가"],["횟수","제한 없음","1회"],["존속기간","2년","2년"],["임차인 해지","언제든지 통지, 3개월 후 효력","같음(제6조의2 준용)"],["임대인 해지","불가","불가"],["차임·보증금 증액","제7조(20분의 1 한도) 범위","제7조 범위"],["적용 제외","2기 차임 연체 등 의무 현저 위반","제1항 각 호 사유"]]},{"종류":"흐름","제목":"임차권등기명령 절차","단계":[{"이름":"임대차 종료","설명":"기간 만료·해지 등으로 임대차가 끝났으나 보증금이 반환되지 않음"},{"이름":"신청","설명":"임차인이 주택 소재지 관할 지방법원·지원·시군법원에 임차권등기명령 신청(제3조의3 제1항)"},{"이름":"결정과 등기","설명":"법원 결정 후 임차권등기 기입. 신청 비용은 임대인에게 청구 가능"},{"이름":"효과","설명":"대항력·우선변제권 취득, 이미 취득한 경우 유지. 이후 대항요건을 상실해도 유지"}]}],"함정":"묵시적 갱신에서 해지통지권은 임차인에게만 있다. 임차권등기명령은 임대차 종료 후에야 신청할 수 있고, 양수인이 임대인 지위를 승계해 보증금반환채무도 이전된다.","개정":"2020.7.31 개정으로 증액청구 한도(제7조 제2항)가 20분의 1로 정해졌고, 2020.6.9 개정으로 갱신거절 통지 기간이 6개월~2개월 전으로 바뀌었다(제6조 제1항)."}},{"i":"S5-1-1-민법-36","r":"S5","g":1,"c":1,"n":76,"s":"민법","q":"선순위 담보권 등이 없는 주택에 대해 대항요건과 확정일자를 갖춘 임대차에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["보증금이 모두 변제되지 않은 대항력 있는 임차권은 임차주택이 경매되어 매각되더라도 소멸하지 않는다.","임차인의 우선변제권은 임차주택과 함께 그 대지의 환가대금에도 미친다.","임차권등기명령에 따른 임차권등기가 끝난 주택을 그 이후에 임차한 임차인은 소액보증금 최우선변제를 받을 수 없다.","임차인이 주택을 인도받고 전입신고를 한 날에 곧바로 대항력이 생긴다.","임차권등기명령의 집행으로 임차권등기를 마친 임차인은 이후 주민등록을 이전하더라도 이미 취득한 대항력과 우선변제권을 잃지 않는다."],"a":[4],"L":"민4-1","o":"변형","x":{"한줄":"대항력은 주택의 인도와 주민등록(전입신고)을 마친 때가 아니라 그 다음 날부터 생긴다.","근거":[{"법령":"주택임대차보호법","조문":"제3조제1항","원문":"제3조(대항력 등) ① 임대차는 그 등기(登記)가 없는 경우에도 임차인(賃借人)이 주택의 인도(引渡)와 주민등록을 마친 때에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다. 이 경우 전입신고를 한 때에 주민등록이 된 것으로 본다."},{"법령":"주택임대차보호법","조문":"제3조의5","원문":"제3조의5(경매에 의한 임차권의 소멸) 임차권은 임차주택에 대하여 「민사집행법」에 따른 경매가 행하여진 경우에는 그 임차주택의 경락(競落)에 따라 소멸한다. 다만, 보증금이 모두 변제되지 아니한, 대항력이 있는 임차권은 그러하지 아니하다."},{"법령":"주택임대차보호법","조문":"제3조의2제2항","원문":"제3조의2(보증금의 회수) ② 제3조제1항ㆍ제2항 또는 제3항의 대항요건(對抗要件)과 임대차계약증서(제3조제2항 및 제3항의 경우에는 법인과 임대인 사이의 임대차계약증서를 말한다)상의 확정일자(確定日字)를 갖춘 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매(公賣)를 할 때에 임차주택(대지를 포함한다)의 환가대금(換價代金)에서 후순위권리자(後順位權利者)나 그 밖의 채권자보다 우선하여 보증금을 변제(辨濟)받을 권리가 있다."},{"법령":"주택임대차보호법","조문":"제3조의3제5·6항","원문":"제3조의3(임차권등기명령) ⑤ 임차인은 임차권등기명령의 집행에 따른 임차권등기를 마치면 제3조제1항ㆍ제2항 또는 제3항에 따른 대항력과 제3조의2제2항에 따른 우선변제권을 취득한다. 다만, 임차인이 임차권등기 이전에 이미 대항력이나 우선변제권을 취득한 경우에는 그 대항력이나 우선변제권은 그대로 유지되며, 임차권등기 이후에는 제3조제1항ㆍ제2항 또는 제3항의 대항요건을 상실하더라도 이미 취득한 대항력이나 우선변제권을 상실하지 아니한다. ⑥ 임차권등기명령의 집행에 따른 임차권등기가 끝난 주택(임대차의 목적이 주택의 일부분인 경우에는 해당 부분으로 한정한다)을 그 이후에 임차한 임차인은 제8조에 따른 우선변제를 받을 권리가 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"경매에 의한 임차권 소멸의 예외이다. 보증금이 모두 변제되지 않은 대항력 있는 임차권은 소멸하지 않는다(제3조의5 단서)."},{"번호":2,"판정":"옳음","설명":"임차주택(대지를 포함한다)의 환가대금에서 우선변제를 받는다(제3조의2 제2항)."},{"번호":3,"판정":"옳음","설명":"임차권등기가 끝난 주택을 이후에 임차한 임차인은 제8조의 최우선변제를 받을 권리가 없다(제3조의3 제6항)."},{"번호":4,"판정":"틀림","설명":"인도와 주민등록을 마친 때의 다음 날부터 제3자에 대하여 효력이 생긴다(제3조 제1항). 당일에는 대항력이 없다."},{"번호":5,"판정":"옳음","설명":"임차권등기를 마치면 이미 취득한 대항력·우선변제권은 대항요건을 상실해도 유지된다(제3조의3 제5항)."}],"개념":[{"종류":"표","제목":"주택임대차 대항력·우선변제권","머리":["구분","요건","효과·시기","근거"],"행":[["대항력","주택 인도 + 주민등록(전입신고)","그 다음 날부터 제3자에게 효력","제3조 제1항"],["우선변제권","대항요건 + 확정일자","경매·공매 시 후순위·일반채권자보다 우선(대지 포함)","제3조의2 제2항"],["최우선변제","경매신청 등기 전 대항요건","보증금 중 일정액을 담보물권자보다 우선","제8조"],["임차권등기","임대차 종료 후 보증금 미반환","대항력·우선변제권 취득·유지","제3조의3"],["경매 시","대항력 있고 보증금 전액 미변제","임차권 소멸하지 않음","제3조의5 단서"],["양수인","임차주택 양수인","임대인 지위 승계","제3조 제4항"]]},{"종류":"흐름","제목":"우선변제를 받는 순서","단계":[{"이름":"대항요건","설명":"주택의 인도와 주민등록(전입신고)"},{"이름":"확정일자","설명":"임대차계약증서에 확정일자를 받음"},{"이름":"경매·공매","설명":"임차주택(대지 포함) 환가대금에서 후순위권리자·일반채권자보다 우선 변제"},{"이름":"인도","설명":"양수인(낙찰자)에게 임차주택을 인도해야 보증금을 받음(제3조의2 제3항)"}]}],"함정":"전입신고한 날 곧바로 대항력이 생기는 것으로 오해하기 쉽다. 효력은 다음 날부터이다. 임차권등기 이후에도 대항요건 상실에 관한 제3조의3 제5항 후단과 경매 시 임차권 존속에 관한 제3조의5 단서를 구분해야 한다."}},{"i":"S5-1-1-민법-37","r":"S5","g":1,"c":1,"n":77,"s":"민법","q":"상가건물임대차보호법이 적용되는 X건물에 관하여 임대인 甲과 임차인 乙이 보증금 3억원, 월차임 60만원으로 정하여 체결한 임대차가 기간만료로 종료되었다. 그런데 甲이 乙에게 보증금을 반환하지 않아서 乙이 현재 X건물을 점유ㆍ사용하고 있다. 다음 설명 중 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲은 乙에게 불법행위로 인한 손해배상을 청구할 수 있다.","乙은 甲에 대해 채무불이행으로 인한 손해배상의무를 진다.","甲은 乙에게 차임에 상당하는 부당이득반환을 청구할 수 있다.","甲은 乙에게 종전 임대차계약에서 정한 차임의 지급을 청구할 수 있다.","乙은 보증금을 반환받을 때까지 X건물에 대해 유치권을 행사할 수 있다."],"a":[4],"L":"민4-2","o":"기출","x":{"한줄":"임대차가 끝나도 보증금을 돌려받을 때까지는 임대차 관계가 존속하는 것으로 보므로 임대인은 종전 계약에서 정한 차임을 청구할 수 있다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제9조","원문":"제9조(임대차기간 등) ① 기간을 정하지 아니하거나 기간을 1년 미만으로 정한 임대차는 그 기간을 1년으로 본다. 다만, 임차인은 1년 미만으로 정한 기간이 유효함을 주장할 수 있다. ② 임대차가 종료한 경우에도 임차인이 보증금을 돌려받을 때까지는 임대차 관계는 존속하는 것으로 본다."},{"법령":"상가건물 임대차보호법","조문":"제2조제1항","원문":"제2조(적용범위) ① 이 법은 상가건물(제3조제1항에 따른 사업자등록의 대상이 되는 건물을 말한다)의 임대차(임대차 목적물의 주된 부분을 영업용으로 사용하는 경우를 포함한다)에 대하여 적용한다. 다만, 제14조의2에 따른 상가건물임대차위원회의 심의를 거쳐 대통령령으로 정하는 보증금액을 초과하는 임대차에 대하여는 그러하지 아니하다."},{"판례":"대법원 판례(임대차 종료 후 동시이행 항변권에 의한 점유)","요지":"보증금을 반환받지 못한 임차인이 동시이행의 항변권에 기해 목적물을 계속 점유하는 것은 불법점유가 아니어서 불법행위나 채무불이행 책임이 생기지 않는다."},{"판례":"대법원 판례(보증금반환채권과 유치권)","요지":"임차보증금반환채권은 임차목적물 자체에서 생긴 채권이 아니어서 견련성이 없으므로 이를 담보하는 유치권은 성립하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"보증금을 받을 때까지 동시이행 항변권에 따라 점유하는 것은 불법점유가 아니어서 불법행위가 성립하지 않는다."},{"번호":2,"판정":"틀림","설명":"같은 이유로 동시이행 항변권에 기한 점유에는 이행지체 책임이 없다. 채무불이행 손해배상의무가 생기지 않는다."},{"번호":3,"판정":"틀림","설명":"임대차 관계가 존속하는 것으로 보는 이상(제9조 제2항) 부당이득이 아니라 임대차 관계에 따른 차임이 문제된다."},{"번호":4,"판정":"옳음","설명":"제9조 제2항에 따라 임대차 관계가 존속하는 것으로 보므로 종전 계약에서 정한 차임을 청구할 수 있다."},{"번호":5,"판정":"틀림","설명":"보증금반환채권은 목적물에 관하여 생긴 채권이 아니어서 견련성이 없고, 유치권은 성립하지 않는다(제320조 제1항)."}],"개념":[{"종류":"표","제목":"상가건물임대차보호법 주요 기간·요건","머리":["구분","내용","근거"],"행":[["적용범위","보증금이 시행령 환산보증금 한도 이하(서울 9억원 등). 월차임은 100을 곱해 환산","법 제2조, 시행령 제2조"],["대항력","건물 인도 + 사업자등록 신청 → 다음 날부터","법 제3조 제1항"],["우선변제","대항요건 + 관할 세무서장의 확정일자","법 제5조 제2항"],["최단 존속기간","1년 미만은 1년으로 간주(임차인은 유효 주장 가능)","법 제9조 제1항"],["갱신요구권","6개월~1개월 전, 전체 10년 이내","법 제10조 제1항·제2항"],["묵시적 갱신","존속기간 1년, 임차인은 언제든 해지(3개월 후 효력)","법 제10조 제4항·제5항"],["차임연체 해지","3기의 차임액","법 제10조의8"],["권리금 회수기회","임대차 종료 6개월 전~종료 시, 손해배상 시효 3년","법 제10조의4"]]},{"종류":"계산","제목":"환산보증금 계산","단계":[{"설명":"환산보증금 = 보증금 + 월차임 × 100","식":"3억원 + 60만원 × 100","값":"3억 6천만원"},{"설명":"한도(서울특별시)와 비교","식":"3억 6천만원 ≤ 9억원","값":"법 적용 가능"}]}],"함정":"임대차 종료 후 임차인의 점유를 불법점유로 보아 불법행위·채무불이행·부당이득을 고르기 쉽다. 제9조 제2항 때문에 임대차 관계가 존속하는 것으로 보아 종전 차임을 청구하는 구조이다. 유치권은 견련성이 없어 성립하지 않는다."}},{"i":"S5-1-1-민법-38","r":"S5","g":1,"c":1,"n":78,"s":"민법","q":"가등기담보 등에 관한 법률에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["채권자는 담보권 실행 통지를 할 때 청산금이 없다고 인정되는 경우에도 그 뜻을 통지하여야 한다.","청산기간은 통지가 채무자등에게 도달한 날부터 1개월이다.","채권자는 자신이 통지한 청산금의 액수가 객관적 평가액과 다르면 통지한 액수에 관하여 다툴 수 있다.","담보가등기를 마친 부동산이 강제경매로 매각되어도 담보가등기권리는 소멸하지 않는다.","채무자등은 청산금을 변제받을 때까지 채무액을 지급하고 말소를 청구할 수 있으나, 변제기가 지난 때부터 5년이 지나면 청구할 수 없다."],"a":[1],"L":"민4-3","o":"변형","x":{"한줄":"청산금이 없다고 인정되는 경우에도 채권자는 그 뜻을 채무자등에게 통지하여야 한다.","근거":[{"법령":"가등기담보 등에 관한 법률","조문":"제3조제1항","원문":"제3조(담보권 실행의 통지와 청산기간) ① 채권자가 담보계약에 따른 담보권을 실행하여 그 담보목적부동산의 소유권을 취득하기 위하여는 그 채권(債權)의 변제기(辨濟期) 후에 제4조의 청산금(淸算金)의 평가액을 채무자등에게 통지하고, 그 통지가 채무자등에게 도달한 날부터 2개월(이하 \"청산기간\"이라 한다)이 지나야 한다. 이 경우 청산금이 없다고 인정되는 경우에는 그 뜻을 통지하여야 한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제9조","원문":"제9조(통지의 구속력) 채권자는 제3조제1항에 따라 그가 통지한 청산금의 금액에 관하여 다툴 수 없다."},{"법령":"가등기담보 등에 관한 법률","조문":"제15조","원문":"제15조(담보가등기권리의 소멸) 담보가등기를 마친 부동산에 대하여 강제경매등이 행하여진 경우에는 담보가등기권리는 그 부동산의 매각에 의하여 소멸한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제11조","원문":"제11조(채무자등의 말소청구권) 채무자등은 청산금채권을 변제받을 때까지 그 채무액(반환할 때까지의 이자와 손해금을 포함한다)을 채권자에게 지급하고 그 채권담보의 목적으로 마친 소유권이전등기의 말소를 청구할 수 있다. 다만, 그 채무의 변제기가 지난 때부터 10년이 지나거나 선의의 제삼자가 소유권을 취득한 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제3조 제1항 후문이다. 청산금이 없어도 통지는 생략할 수 없다."},{"번호":2,"판정":"틀림","설명":"청산기간은 통지가 도달한 날부터 2개월이다(제3조 제1항)."},{"번호":3,"판정":"틀림","설명":"채권자는 통지한 청산금의 금액에 관하여 다툴 수 없다(제9조)."},{"번호":4,"판정":"틀림","설명":"담보가등기를 마친 부동산에 강제경매 등이 행하여지면 담보가등기권리는 매각으로 소멸한다(제15조)."},{"번호":5,"판정":"틀림","설명":"말소청구는 변제기가 지난 때부터 10년이 지나거나 선의의 제3자가 소유권을 취득한 경우에는 할 수 없다(제11조 단서)."}],"개념":[{"종류":"흐름","제목":"가등기담보 실행 절차","단계":[{"이름":"변제기 도래","설명":"채권의 변제기가 지난 뒤에 실행"},{"이름":"청산금 통지","설명":"청산금 평가액(없으면 없다는 뜻)을 채무자등에게 통지. 통지에는 부동산 평가액과 채권액을 밝힘"},{"이름":"청산기간","설명":"통지 도달일부터 2개월 경과"},{"이름":"청산금 지급·본등기","설명":"가등기: 청산기간 후 본등기 청구. 소유권이전등기를 한 경우: 청산기간이 지나고 청산금을 지급한 때 소유권 취득(동시이행)"}]},{"종류":"표","제목":"가등기담보법 핵심 수치","머리":["항목","내용","근거"],"행":[["청산기간","통지 도달일부터 2개월","제3조 제1항"],["청산금","통지 당시 부동산 가액 − 채권액(선순위 담보 채권액 포함)","제4조 제1항"],["통지 금액","채권자는 다툴 수 없음","제9조"],["말소청구 배제","변제기 후 10년 경과 또는 선의의 제3자 소유권 취득","제11조"],["강제경매 시","담보가등기는 매각으로 소멸, 우선변제권 있음(저당권으로 봄)","제13조, 제15조"],["법정지상권","토지·건물이 동일 소유자였다가 본등기 등이 된 경우 건물 소유를 위한 지상권 간주","제10조"]]}],"함정":"청산금이 없으면 통지가 필요 없다고 오해하기 쉽다. 청산금이 없다는 뜻도 통지해야 한다. 청산기간 2개월과 말소청구 10년의 수치 구분, 통지한 청산금을 채권자가 다툴 수 없다는 점이 자주 묻는다."}},{"i":"S5-1-1-민법-39","r":"S5","g":1,"c":1,"n":79,"s":"민법","q":"집합건물의 소유 및 관리에 관한 법령상 관리인 및 관리위원회 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["구분소유자가 아닌 자는 관리인이 될 수 없다.","구분소유자가 10인 이상일 때에는 관리단을 대표하고 관리단의 사무를 집행할 관리인을 선임하여야 한다.","관리위원회를 둔 경우에도 규약에서 달리 정한 바가 없으면, 관리인은 공용부분의 보존행위를 함에 있어 관리위원회의 결의를 요하지 않는다.","규약에서 달리 정한 바가 없으면, 관리인은 관리위원회의 위원이 될 수 있다.","규약에서 달리 정한 바가 없으면, 관리위원회 위원은 부득이한 사유가 없더라도 서면이나 대리인을 통하여 의결권을 행사할 수 있다."],"a":[2],"L":"민4-4","o":"기출","x":{"한줄":"구분소유자가 10인 이상이면 관리단을 대표하고 사무를 집행할 관리인을 반드시 선임하여야 한다.","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제24조제1·2항","원문":"제24조(관리인의 선임 등) ① 구분소유자가 10인 이상일 때에는 관리단을 대표하고 관리단의 사무를 집행할 관리인을 선임하여야 한다. ② 관리인은 구분소유자일 필요가 없으며, 그 임기는 2년의 범위에서 규약으로 정한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제26조의3제3항","원문":"제26조의3(관리위원회의 설치 및 기능) ③ 제1항에 따라 관리위원회를 둔 경우 관리인은 제25조제1항 각 호의 행위를 하려면 관리위원회의 결의를 거쳐야 한다. 다만, 규약으로 달리 정한 사항은 그러하지 아니하다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제26조의4제2항","원문":"제26조의4(관리위원회의 구성 및 운영) ② 관리인은 규약에 달리 정한 바가 없으면 관리위원회의 위원이 될 수 없다."},{"법령":"집합건물의 소유 및 관리에 관한 법률 시행령","조문":"제10조제2항","원문":"제10조(관리위원회의 의결방법) ② 관리위원회 위원은 질병, 해외체류 등 부득이한 사유가 있는 경우 외에는 서면이나 대리인을 통하여 의결권을 행사할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"관리인은 구분소유자일 필요가 없다(제24조 제2항)."},{"번호":2,"판정":"옳음","설명":"제24조 제1항이다."},{"번호":3,"판정":"틀림","설명":"관리위원회를 둔 경우 관리인은 제25조 제1항 각 호의 행위(공용부분의 보존행위 포함)를 하려면 관리위원회의 결의를 거쳐야 한다. 규약으로 달리 정한 사항만 예외이다(제26조의3 제3항)."},{"번호":4,"판정":"틀림","설명":"관리인은 규약에 달리 정한 바가 없으면 관리위원회의 위원이 될 수 없다(제26조의4 제2항)."},{"번호":5,"판정":"틀림","설명":"관리위원회 위원은 질병, 해외체류 등 부득이한 사유가 있는 경우 외에는 서면이나 대리인을 통하여 의결권을 행사할 수 없다(시행령 제10조 제2항)."}],"개념":[{"종류":"표","제목":"관리인·관리위원회","머리":["구분","내용","근거"],"행":[["관리인 선임","구분소유자 10인 이상이면 선임 의무","법 제24조 제1항"],["관리인 자격·임기","구분소유자일 필요 없음, 임기 2년 범위에서 규약","법 제24조 제2항"],["선임·해임","관리단집회 결의(규약으로 관리위원회 결의 가능)","법 제24조 제3항"],["관리인 권한","공용부분 보존행위, 결의 집행, 비용 청구·수령 등","법 제25조 제1항"],["관리위원회 설치","규약으로 설치 가능, 관리인 감독","법 제26조의3 제1·2항"],["관리인과 위원","규약이 없으면 관리인은 위원 불가","법 제26조의4 제2항"],["위원 의결권","부득이한 사유 외 서면·대리 행사 불가","시행령 제10조 제2항"]]},{"종류":"표","제목":"관리단집회 의결정족수","머리":["사항","정족수","근거"],"행":[["통상 결의","구분소유자 과반수 및 의결권 과반수","법 제38조 제1항"],["공용부분 변경","구분소유자 2/3 이상 및 의결권 2/3 이상(개량 목적이 지나치게 많은 비용이 들지 않으면 통상 결의)","법 제15조 제1항"],["재건축 결의","구분소유자 4/5 이상 및 의결권 4/5 이상","법 제47조 제2항"],["서면·전자적 방법 합의","구분소유자 3/4 이상 및 의결권 3/4 이상(재건축 등은 4/5 이상)","법 제41조 제1항·제2항"],["임시 집회 소집","구분소유자 5분의 1 이상이 청구(규약으로 감경 가능)","법 제33조 제2항"]]}],"함정":"관리인은 구분소유자여야 한다고 보기 쉽다. 구분소유자일 필요가 없다. 관리위원회를 둔 경우 보존행위도 관리위원회 결의를 거쳐야 하고(규약 예외), 관리인은 위원이 될 수 없다는 점이 함께 나온다."}},{"i":"S5-1-1-민법-40","r":"S5","g":1,"c":1,"n":80,"s":"민법","q":"甲은 2022. 7. 1. 자신의 X토지에 관하여 乙과 유효한 명의신탁약정을 체결하고, 乙 명의로 소유권이전등기를 마쳤다. 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 乙이 부부인 경우, 甲이 사망하더라도 그 명의신탁약정은 甲의 상속인 丙과 乙 사이에 유효하게 존속한다.","甲이 丙에게 X토지를 매도한 경우, 그 매매계약은 민법 제569조의 타인 권리의 매매라고 할 수 없다.","丙이 X토지를 무단점유하여 사용·수익할 경우, 甲은 丙에게 직접 그 소유권을 주장할 수 없다.","甲은 乙에게 명의신탁의 해지를 원인으로 소유권에 기한 이전등기를 청구할 수 있다.","丙이 X토지에 대해 점유취득시효를 완성한 후 소유권이전등기를 마치기 전에 甲이 명의신탁의 해지를 원인으로 소유권이전등기를 마친 경우, 丙은 특별한 사정이 없는 한 甲에게 취득시효를 주장할 수 있다."],"a":[5],"L":"민4-5","o":"기출","x":{"한줄":"시효완성 후 등기 전에 명의신탁 해지로 소유권을 이전받은 甲은 시효완성 후의 새 소유자여서, 丙은 특별한 사정이 없으면 甲에게 취득시효를 주장하지 못한다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제8조","원문":"제8조(종중, 배우자 및 종교단체에 대한 특례) 다음 각 호의 어느 하나에 해당하는 경우로서 조세 포탈, 강제집행의 면탈(免脫) 또는 법령상 제한의 회피를 목적으로 하지 아니하는 경우에는 제4조부터 제7조까지 및 제12조제1항부터 제3항까지를 적용하지 아니한다. 1. 종중(宗中)이 보유한 부동산에 관한 물권을 종중(종중과 그 대표자를 같이 표시하여 등기한 경우를 포함한다) 외의 자의 명의로 등기한 경우 2. 배우자 명의로 부동산에 관한 물권을 등기한 경우 3. 종교단체의 명의로 그 산하 조직이 보유한 부동산에 관한 물권을 등기한 경우"},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조","원문":"제4조(명의신탁약정의 효력) ① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"대법원 판례(취득시효 완성 후 소유자 변경)","요지":"점유취득시효가 완성된 뒤 등기를 하기 전에 소유권을 취득한 제3자에게는 특별한 사정이 없으면 시효취득을 주장하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"배우자 사이의 명의신탁은 조세포탈 등의 목적이 없으면 제4조의 무효 규정이 적용되지 않아 약정이 유효하다(제8조 제2호). 신탁자가 사망해도 약정은 상속인과 수탁자 사이에 존속한다."},{"번호":2,"판정":"옳음","설명":"유효한 명의신탁에서 신탁자는 대내적으로 소유자여서 신탁자가 부동산을 매도하는 계약은 타인 권리의 매매가 아니라는 것이 판례이다."},{"번호":3,"판정":"옳음","설명":"대외적으로는 수탁자 乙이 소유자이므로 신탁자 甲은 제3자 丙에게 직접 소유권을 주장하지 못한다."},{"번호":4,"판정":"옳음","설명":"유효한 명의신탁이므로 신탁자는 해지를 원인으로 수탁자에게 소유권이전등기를 청구할 수 있다."},{"번호":5,"판정":"틀림","설명":"시효 완성 당시 소유자는 대외적 소유자 乙이다. 완성 후 등기 전에 소유권을 이전받은 甲에게 丙은 시효취득을 주장하지 못한다."}],"개념":[{"종류":"표","제목":"명의신탁 유형별 효력","머리":["유형","약정","물권변동","부동산 소유자"],"행":[["2자간 등기명의신탁","무효","무효","신탁자"],["3자간 등기명의신탁(중간생략)","무효","수탁자 명의 등기 무효","매도인"],["계약명의신탁(매도인 선의)","무효","유효(제4조 제2항 단서)","수탁자"],["계약명의신탁(매도인 악의)","무효","무효","매도인"],["종중·배우자·종교단체 특례(조세포탈 등 목적 없음)","유효","유효","수탁자(대외), 신탁자(대내)"]]},{"종류":"비교","제목":"무효인 명의신탁과 특례의 명의신탁","왼쪽":{"이름":"무효인 명의신탁","항목":["약정 무효(제4조 제1항)","등기 물권변동 무효(제4조 제2항)","무효는 제3자에게 대항 못함(제4조 제3항)","신탁자에 대한 과징금·벌칙"]},"오른쪽":{"이름":"특례(제8조)","항목":["종중·배우자·종교단체","조세 포탈·강제집행 면탈·법령상 제한 회피 목적이 없어야 함","제4조~제7조 미적용","약정·등기 모두 유효, 대외적 소유자는 수탁자"]}}],"함정":"문제의 전제인 유효한 명의신탁은 제8조 특례를 뜻한다. 무효인 명의신탁의 법리(신탁자 소유, 부당이득 반환)를 적용하면 안 된다. 선지 5는 취득시효 완성 시점과 소유권 이전 시점의 선후를 따져야 한다."}},{"i":"S5-2-1-중개사법-01","r":"S5","g":2,"c":2,"n":1,"s":"중개사법","q":"공인중개사법령상 중개행위 등에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["중개행위에 해당하는지 여부는 개업공인중개사의 행위를 객관적으로 보아 판단할 것이 아니라 개업공인중개사의 주관적 의사를 기준으로 판단해야 한다.","임대차계약을 알선한 개업공인중개사가 계약 체결 후에도 목적물의 인도 등 거래당사자의 계약상 의무의 실현에 관여함으로써 계약상 의무가 원만하게 이행되도록 주선할 것이 예정되어 있는 경우, 그러한 개업공인중개사의 행위는 사회통념상 중개행위의 범주에 포함된다.","소속공인중개사는 자신의 중개사무소 개설등록을 신청할 수 있다.","개업공인중개사는 거래계약서를 작성하는 경우 거래계약서에 서명하거나 날인하면 된다.","개업공인중개사가 국토교통부장관이 정한 거래계약서 표준서식을 사용하지 않는 경우 과태료부과처분을 받게 된다."],"a":[2],"L":"중1-1","o":"기출","x":{"한줄":"중개행위인지는 행위를 객관적으로 보아 사회통념상 거래 알선을 위한 행위인지로 가리므로, 계약 뒤 인도 등 이행을 주선하기로 예정된 관여도 중개행위에 들어간다.","근거":[{"법령":"공인중개사법","조문":"제2조제1호","원문":"\"중개\"라 함은 제3조에 따른 중개대상물에 대하여 거래당사자간의 매매ㆍ교환ㆍ임대차 그 밖의 권리의 득실변경에 관한 행위를 알선하는 것을 말한다."},{"법령":"공인중개사법","조문":"제9조제2항","원문":"공인중개사(소속공인중개사는 제외한다) 또는 법인이 아닌 자는 제1항에 따라 중개사무소의 개설등록을 신청할 수 없다."},{"법령":"공인중개사법","조문":"제25조제4항","원문":"제3항에 따른 확인ㆍ설명서에는 개업공인중개사(법인인 경우에는 대표자를 말하며, 법인에 분사무소가 설치되어 있는 경우에는 분사무소의 책임자를 말한다)가 서명 및 날인하되, 해당 중개행위를 한 소속공인중개사가 있는 경우에는 소속공인중개사가 함께 서명 및 날인하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제22조제3항","원문":"국토교통부장관은 개업공인중개사가 작성하는 거래계약서의 표준이 되는 서식을 정하여 그 사용을 권장할 수 있다."},{"판례":"중개행위 판단 기준(판례)","요지":"중개행위인지는 중개사의 주관적 의사가 아니라 행위를 객관적으로 보아 사회통념상 거래당사자의 의뢰취지에 부응하는 알선·중개를 위한 행위인지로 판단한다. 계약 체결 뒤 인도·잔금 같은 이행의 주선까지 예정된 경우 그 관여도 중개행위다."}],"선지":[{"번호":1,"판정":"틀림","설명":"주관적 의사가 아니라 행위를 객관적으로 보아 판단한다(판례)."},{"번호":2,"판정":"옳음","설명":"이행의 주선이 예정된 관여도 사회통념상 중개행위의 범주에 든다(판례)."},{"번호":3,"판정":"틀림","설명":"소속공인중개사는 개설등록을 신청할 수 없다(법 제9조제2항)."},{"번호":4,"판정":"틀림","설명":"거래계약서에는 서명 및 날인을 모두 해야 한다(법 제26조제2항, 제25조제4항)."},{"번호":5,"판정":"틀림","설명":"표준서식은 사용을 권장할 뿐이어서 쓰지 않아도 과태료 처분 사유가 아니다(영 제22조제3항)."}],"개념":[{"종류":"표","제목":"용어별 자격·등록·서명 의무","머리":["구분","자격","개설등록","인장 등록","서명 및 날인"],"행":[["공인중개사","자격 취득자","등록 여부와 무관하게 공인중개사","-","-"],["개업공인중개사","공인중개사 또는 법인","등록을 마친 자","의무","확인·설명서·계약서에 서명 및 날인(법인은 대표자, 분사무소는 책임자)"],["소속공인중개사","공인중개사(법인의 사원·임원 포함)","신청 불가","의무","그 중개를 했으면 함께 서명 및 날인"],["중개보조원","공인중개사 아님","신청 불가","의무 없음","의무 없음"]]},{"종류":"표","제목":"중개대상물 범위(법 제3조, 영 제2조)","머리":["구분","중개대상물 여부","비고"],"행":[["토지","○","지목 무관"],["건축물·그 밖의 토지 정착물","○","미등기·무허가 건물, 분양계약이 체결된 동·호수 특정 아파트 분양권 포함"],["입목, 공장재단·광업재단","○","영 제2조"],["입주권·대토권 같은 지위, 권리금·영업시설","×","특정한 물건이 아닌 지위·무형 가치"],["동산(베어 낸 수목), 채굴 전 광물, 금전채권, 점유","×","중개대상물이 아님"]]}],"함정":"선지 4는 서명과 날인 중 하나만 하면 된다고 쓴 것이다. 확인·설명서와 거래계약서는 서명 「및」 날인이다. 선지 5는 표준서식 사용이 권장일 뿐이라는 점을 빼면 그럴듯해 보인다."}},{"i":"S5-2-1-중개사법-02","r":"S5","g":2,"c":2,"n":2,"s":"중개사법","q":"공인중개사법령상 공인중개사의 자격 및 자격증 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["시·도지사는 공인중개사자격시험 합격자의 결정 공고일부터 2개월 이내에 시험합격자에 관한 사항을 공인중개사자격증교부대장에 기재한 후 자격증을 교부해야 한다.","공인중개사자격증의 재교부를 신청하는 자는 재교부신청서를 국토교통부장관에게 제출해야 한다.","시험에서 부정한 행위를 한 응시자는 그 시험이 무효로 되고, 그 처분이 있은 날부터 5년간 시험응시자격이 정지된다.","공인중개사가 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 한 경우, 시·도지사는 6개월의 범위 안에서 그 자격을 정지할 수 있다.","공인중개사의 자격이 취소된 자는 자격취소처분을 받은 날부터 10일 이내에 공인중개사자격증을 교부한 시·도지사에게 반납해야 한다."],"a":[3],"L":"중1-2","o":"변형","x":{"한줄":"시험에서 부정한 행위를 한 응시자는 시험이 무효가 되고, 처분일부터 5년간 응시자격이 정지된다.","근거":[{"법령":"공인중개사법","조문":"제4조의3","원문":"시험시행기관장은 시험에서 부정한 행위를 한 응시자에 대하여는 그 시험을 무효로 하고, 그 처분이 있은 날부터 5년간 시험응시자격을 정지한다."},{"법령":"공인중개사법 시행규칙","조문":"제3조제1항","원문":"시ㆍ도지사는 …시험합격자의 결정 공고일부터 1개월 이내에 시험합격자에 관한 사항을 별지 제2호서식의 공인중개사자격증교부대장에 기재한 후, 시험 합격자에게 별지 제3호서식의 공인중개사자격증을 교부하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제3조제2항","원문":"법 제5조제3항의 규정에 따라 공인중개사자격증의 재교부를 신청하는 자는 별지 제4호서식의 재교부신청서를 자격증을 교부한 시ㆍ도지사에게 제출하여야 한다."},{"법령":"공인중개사법","조문":"제35조제1항제2호","원문":"시ㆍ도지사는 공인중개사가 …제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우에는 그 자격을 취소하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제21조","원문":"공인중개사자격증을 반납하고자 하는 자는 자격취소처분을 받은 날부터 7일 이내에 그 공인중개사자격증을 교부한 시ㆍ도지사에게 공인중개사자격증을 반납하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"합격자 결정 공고일부터 1개월 이내에 교부대장에 기재하고 교부한다(규칙 제3조제1항)."},{"번호":2,"판정":"틀림","설명":"재교부 신청서는 자격증을 교부한 시·도지사에게 낸다(규칙 제3조제2항)."},{"번호":3,"판정":"옳음","설명":"부정행위자는 시험 무효와 함께 처분일부터 5년간 응시자격이 정지된다(법 제4조의3)."},{"번호":4,"판정":"틀림","설명":"성명을 사용하게 한 공인중개사의 자격은 정지가 아니라 취소해야 한다(법 제35조제1항제2호)."},{"번호":5,"판정":"틀림","설명":"자격증 반납기한은 자격취소처분을 받은 날부터 7일이다(규칙 제21조)."}],"개념":[{"종류":"표","제목":"자격 관련 기관·기간","머리":["항목","내용"],"행":[["시험 시행","시·도지사. 국토교통부장관은 수준 균형 등을 위해 직접 출제·시행 가능(법 제4조)"],["부정행위자","시험 무효 + 처분일부터 5년 응시자격 정지(법 제4조의3)"],["자격증 교부","시·도지사, 합격자 결정 공고일부터 1개월 이내(규칙 제3조제1항)"],["자격증 재교부","교부한 시·도지사에게 신청(규칙 제3조제2항)"],["자격취소 시 반납","취소처분을 받은 날부터 7일 이내, 교부한 시·도지사에게(규칙 제21조)"],["자격취소 후 결격","취소 후 3년이 지나지 않으면 개설등록 불가(법 제10조제1항제6호)"]]},{"종류":"비교","제목":"자격취소와 자격정지","왼쪽":{"이름":"자격취소(법 제35조)","항목":["처분권자: 시·도지사, 반드시 취소","사유: 부정 취득, 성명 사용·자격증 양도·대여, 정지기간 중 중개업무, 이 법·직무 관련 형법 위반 금고 이상(집행유예 포함)","청문 실시","결과: 자격증 반납 7일, 3년 결격"]},"오른쪽":{"이름":"자격정지(법 제36조)","항목":["처분권자: 시·도지사, 6개월 범위에서 정지할 수 있음","대상: 소속공인중개사로서 업무수행 기간 중","사유: 이중소속, 인장등록 위반, 확인·설명 위반, 서명·날인 누락, 거래계약서 거짓 기재·이중 작성, 금지행위","정지기간 중 중개업무를 하면 자격취소 사유"]}}],"함정":"선지 4는 자격정지로 바꿔 놓았다. 성명 사용·자격증 양도·대여는 필요적 자격취소다. 선지 1은 1개월을 2개월로, 선지 5는 7일을 10일로 바꾼 숫자 함정이다."}},{"i":"S5-2-1-중개사법-03","r":"S5","g":2,"c":2,"n":3,"s":"중개사법","q":"공인중개사법령상 법인이 중개사무소 개설등록을 하려는 경우의 기준으로 틀린 것은? (다른 법률의 규정은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["「상법」상 회사로서 자본금이 5천만원 이상일 것","분사무소를 설치하려는 경우 분사무소의 책임자가 분사무소 설치신고일 전 1년 이내에 시·도지사가 실시하는 실무교육을 받았을 것","대표자와 임원·사원 중 공인중개사가 아닌 자는 실무교육을 받지 않아도 될 것","건축물대장에 기재된 건물에 사용대차의 방법으로 사용권을 확보하여 중개사무소를 확보할 것","법 제14조에 규정된 업무만을 영위할 목적으로 설립된 법인일 것"],"a":[3],"L":"중1-3","o":"변형","x":{"한줄":"법인은 공인중개사 여부와 관계없이 대표자, 임원 또는 사원 전원이 실무교육을 받아야 한다.","근거":[{"법령":"공인중개사법 시행령","조문":"제13조제1항제2호","원문":"법인이 중개사무소를 개설하려는 경우 가. 「상법」상 회사 또는 「협동조합 기본법」 제2조제1호에 따른 협동조합(같은 조 제3호에 따른 사회적협동조합은 제외한다)으로서 자본금이 5천만원 이상일 것 나. 법 제14조에 규정된 업무만을 영위할 목적으로 설립된 법인일 것 다. 대표자는 공인중개사이어야 하며, 대표자를 제외한 임원 또는 사원…의 3분의 1 이상은 공인중개사일 것 라. 대표자, 임원 또는 사원 전원 및 분사무소의 책임자…가 법 제34조제1항에 따른 실무교육을 받았을 것 마. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것"},{"법령":"공인중개사법","조문":"제34조제1항","원문":"중개사무소의 개설등록을 신청하려는 자(법인의 경우에는 사원ㆍ임원을 말하며, 제13조제3항에 따라 분사무소의 설치신고를 하려는 경우에는 분사무소의 책임자를 말한다)는 등록신청일(분사무소 설치신고의 경우에는 신고일을 말한다)전 1년 이내에 시ㆍ도지사가 실시하는 실무교육(실무수습을 포함한다)을 받아야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상법상 회사 또는 협동조합(사회적협동조합 제외)은 자본금 5천만원 이상이어야 한다(영 제13조제1항제2호가목)."},{"번호":2,"판정":"옳음","설명":"분사무소 책임자는 신고일 전 1년 이내 시·도지사의 실무교육을 받아야 한다(법 제34조제1항, 영 제13조제1항제2호라목)."},{"번호":3,"판정":"틀림","설명":"공인중개사가 아닌 대표자·임원·사원도 포함해 전원이 실무교육을 받아야 한다(영 제13조제1항제2호라목)."},{"번호":4,"판정":"옳음","설명":"소유가 아니어도 전세·임대차·사용대차로 사용권을 확보하면 된다(영 제13조제1항제2호마목)."},{"번호":5,"판정":"옳음","설명":"설립 목적은 법 제14조의 업무로 한정된다(영 제13조제1항제2호나목)."}],"개념":[{"종류":"표","제목":"법인 개설등록 기준(영 제13조제1항제2호)","머리":["구분","기준"],"행":[["법인 형태·자본금","상법상 회사 또는 협동조합(사회적협동조합 제외), 자본금 5천만원 이상"],["설립 목적","법 제14조 업무만 영위할 목적"],["공인중개사 비율","대표자는 공인중개사, 대표자 제외 임원·사원(합명·합자회사는 무한책임사원)의 3분의 1 이상 공인중개사"],["실무교육","대표자, 임원 또는 사원 전원 + 분사무소 책임자(분사무소를 설치하는 경우), 신청일(신고일) 전 1년 이내"],["사무소 확보","건축물대장에 기재된 건물, 소유·전세·임대차·사용대차 등으로 사용권 확보"]]},{"종류":"흐름","제목":"개설등록 절차","단계":[{"이름":"실무교육 수료","설명":"신청일 전 1년 이내 시·도지사가 실시하는 실무교육(법인은 대표자·임원·사원 전원)"},{"이름":"등록신청","설명":"중개사무소(법인은 주된 사무소)를 두려는 지역의 시장·군수·구청장에게 신청서, 교육 수료확인증 사본(전자 확인 시 생략), 사진, 사무소 확보 서류 제출(규칙 제4조제1항)"},{"이름":"자격 확인","설명":"등록관청이 자격증을 발급한 시·도지사에게 공인중개사 자격 확인 요청, 법인 등기사항증명서·건축물대장 확인"},{"이름":"등록 통지","설명":"종별(법인·공인중개사)에 따라 등록하고 신청일부터 7일 이내 서면 통지(규칙 제4조제2항)"},{"이름":"보증 확인과 등록증 교부","설명":"보증 설정 여부 확인 후 지체 없이 등록증 교부(규칙 제5조제1항)"},{"이름":"협회 통보","설명":"등록증 교부 등을 매월 모아 다음 달 10일까지 한국공인중개사협회에 통보(영 제14조, 규칙 제6조)"}]}],"함정":"선지 3은 공인중개사 비율 규정(3분의 1)과 실무교육 대상(전원)을 섞은 것이다. 3분의 1은 자격 요건이고 실무교육은 자격과 관계없이 전원이 받는다."}},{"i":"S5-2-1-중개사법-04","r":"S5","g":2,"c":2,"n":4,"s":"중개사법","q":"공인중개사법령상 중개사무소 개설등록의 결격사유에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["피특정후견인은 중개사무소의 개설등록을 할 수 없다.","금고 이상의 형의 선고유예를 받고 그 유예기간 중에 있는 자는 중개사무소의 개설등록을 할 수 없다.","이 법을 위반하여 200만원의 벌금형을 선고받고 1년이 지난 자는 중개사무소의 개설등록을 할 수 없다.","사원 중 파산선고를 받고 복권되지 않은 자가 있는 법인은 중개사무소의 개설등록을 할 수 없다.","개업공인중개사인 법인의 임원에게 결격사유가 생긴 경우, 그 사유가 발생한 날부터 3개월 이내에 해소하면 등록취소를 면한다."],"a":[4],"L":"중1-3","o":"변형","x":{"한줄":"사원 또는 임원 중 결격사유(제1호부터 제11호) 해당자가 있는 법인은 그 자체가 결격이다.","근거":[{"법령":"공인중개사법","조문":"제10조제1항","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 1. 미성년자 2. 피성년후견인 또는 피한정후견인 3. 파산선고를 받고 복권되지 아니한 자 … 5. 금고 이상의 형의 집행유예를 받고 그 유예기간이 만료된 날부터 2년이 지나지 아니한 자 … 11. 이 법을 위반하여 300만원 이상의 벌금형의 선고를 받고 3년이 지나지 아니한 자 12. 사원 또는 임원 중 제1호부터 제11호까지의 어느 하나에 해당하는 자가 있는 법인"},{"법령":"공인중개사법","조문":"제38조제1항제3호","원문":"제10조제1항제2호부터 제6호까지 또는 같은 항 제11호ㆍ제12호에 따른 결격사유에 해당하게 된 경우. 다만, 같은 항 제12호에 따른 결격사유에 해당하는 경우로서 그 사유가 발생한 날부터 2개월 이내에 그 사유를 해소한 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"피특정후견인은 결격사유가 아니다. 피성년후견인과 피한정후견인이 결격이다(법 제10조제1항제2호)."},{"번호":2,"판정":"틀림","설명":"선고유예는 결격사유가 아니다. 결격인 것은 금고 이상의 실형(집행 후 3년)과 집행유예(만료 후 2년)다(법 제10조제1항제4호·제5호)."},{"번호":3,"판정":"틀림","설명":"이 법 위반 벌금형은 300만원 이상일 때만 선고 후 3년간 결격이다. 200만원은 결격이 아니다(법 제10조제1항제11호)."},{"번호":4,"판정":"옳음","설명":"파산선고를 받고 복권되지 않은 자(제3호)가 사원이면 그 법인은 제12호로 결격이다."},{"번호":5,"판정":"틀림","설명":"해소 기한은 사유 발생일부터 2개월이다(법 제38조제1항제3호 단서)."}],"개념":[{"종류":"표","제목":"형벌·처분별 결격 기간","머리":["사유","결격 기간"],"행":[["금고 이상의 실형","집행 종료·면제일부터 3년"],["금고 이상의 집행유예","유예기간 만료일부터 2년"],["선고유예","결격 아님"],["이 법 위반 벌금 300만원 이상","선고 후 3년(300만원 미만, 다른 법 위반 벌금은 결격 아님)"],["공인중개사 자격취소","취소 후 3년"],["자격정지","정지기간 중"],["개설등록 취소(일정 사유)","취소 후 3년(사망·해산, 결격사유 발생, 등록기준 미달 등은 3년 제외)"],["파산선고","복권 전"]]},{"종류":"표","제목":"결격사유의 적용 범위","머리":["대상","적용"],"행":[["개설등록 신청인","제10조제1항 각 호"],["소속공인중개사·중개보조원","제1호부터 제11호(법 제10조제2항)"],["법인","사원 또는 임원 중 제1호부터 제11호 해당자가 있으면 결격(제12호)"],["등록 후 결격사유 발생","등록취소(법 제38조제1항제3호). 법인 임원 결격은 2개월 안에 해소하면 제외"]]}],"함정":"선고유예와 집행유예를 바꿔 읽기 쉽다(선지 2). 벌금은 금액(300만원)과 위반한 법률(이 법)이 모두 맞아야 결격이다(선지 3). 선지 5는 2개월을 3개월로 바꿨다."}},{"i":"S5-2-1-중개사법-05","r":"S5","g":2,"c":2,"n":5,"s":"중개사법","q":"공인중개사법령상 중개사무소의 설치에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["법인이 아닌 개업공인중개사는 그 등록관청의 관할구역안에 1개의 중개사무소만 둘 수 있다.","다른 법률의 규정에 따라 중개업을 할 수 있는 법인의 분사무소에는 공인중개사를 책임자로 두지 않아도 된다.","개업공인중개사가 중개사무소를 공동으로 사용하려면 중개사무소의 개설등록 또는 이전신고를 할 때 그 중개사무소를 사용할 권리가 있는 다른 개업공인중개사의 승낙서를 첨부해야 한다.","법인인 개업공인중개사가 분사무소를 두려는 경우 소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법으로 사용권을 확보해야 한다.","법인인 개업공인중개사가 그 등록관청의 관할구역 외의 지역에 둘 수 있는 분사무소는 시ㆍ도별로 1개소를 초과할 수 없다."],"a":[5],"L":"중1-4","o":"기출","x":{"한줄":"분사무소는 주된 사무소가 있는 시·군·구를 뺀 시·군·구별로 1개소까지 둘 수 있고, 시·도별이 아니다.","근거":[{"법령":"공인중개사법 시행령","조문":"제15조제1항","원문":"법 제13조제3항에 따른 분사무소는 주된 사무소의 소재지가 속한 시…ㆍ군ㆍ구를 제외한 시ㆍ군ㆍ구별로 설치하되, 시ㆍ군ㆍ구별로 1개소를 초과할 수 없다."},{"법령":"공인중개사법 시행령","조문":"제15조제2항","원문":"제1항의 규정에 따른 분사무소에는 공인중개사를 책임자로 두어야 한다. 다만, 다른 법률의 규정에 따라 중개업을 할 수 있는 법인의 분사무소인 경우에는 그러하지 아니하다."},{"법령":"공인중개사법 시행령","조문":"제16조제1항","원문":"법 제13조제6항 본문에 따라 중개사무소를 공동으로 사용하려는 개업공인중개사는 법 제9조에 따른 중개사무소의 개설등록 또는 법 제20조에 따른 중개사무소의 이전신고를 하는 때에 그 중개사무소를 사용할 권리가 있는 다른 개업공인중개사의 승낙서를 첨부하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제15조제3항제5호","원문":"건축물대장에 기재된 건물에 분사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)하였음을 증명하는 서류."}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사는 관할구역 안에 1개의 사무소만 둔다(법 제13조제1항)."},{"번호":2,"판정":"옳음","설명":"다른 법률로 중개업을 하는 법인의 분사무소는 공인중개사 책임자를 두지 않아도 된다(영 제15조제2항 단서)."},{"번호":3,"판정":"옳음","설명":"공동사용은 개설등록 또는 이전신고 때 승낙서를 붙인다(영 제16조제1항)."},{"번호":4,"판정":"옳음","설명":"분사무소 설치신고에도 사용권 확보 서류를 낸다(영 제15조제3항제5호)."},{"번호":5,"판정":"틀림","설명":"분사무소는 시·군·구별로 1개소를 초과할 수 없다(영 제15조제1항)."}],"개념":[{"종류":"표","제목":"사무소 설치 정리","머리":["항목","내용","위반 시"],"행":[["1등록 1사무소","등록관청 관할구역 안에 1개(법 제13조제1항)","등록취소 가능, 1년 이하 징역·1천만원 이하 벌금"],["임시 중개시설물","천막 등 이동이 쉬운 임시 시설물 설치 금지(법 제13조제2항)","등록취소 가능, 1년 이하 징역·1천만원 이하 벌금"],["분사무소","법인만. 주된 사무소 소재 시·군·구를 뺀 시·군·구별 1개소, 책임자는 공인중개사(영 제15조)","-"],["공동사용","다른 개업공인중개사 승낙서 첨부. 업무정지 중인 자는 승낙서 교부·이전신고로 새로 시작 불가(영 제16조)","-"],["이전신고","이전한 날부터 10일 이내(법 제20조제1항)","100만원 이하 과태료"]]},{"종류":"흐름","제목":"분사무소 설치","단계":[{"이름":"책임자 실무교육","설명":"설치신고일 전 1년 이내 시·도지사의 실무교육"},{"이름":"신고","설명":"주된 사무소 소재지 관할 등록관청에 설치신고서, 교육 수료확인증 사본, 보증 설정 증명서류, 사무소 확보 서류 제출"},{"이름":"확인","설명":"등록관청이 자격증 발급 시·도지사에게 책임자 자격 확인 요청, 법인 등기사항증명서 확인"},{"이름":"신고확인서 교부","설명":"적합하면 신고확인서 교부(법 제13조제4항)"},{"이름":"통보","설명":"분사무소 설치예정지역 시장·군수·구청장에게 지체 없이 통보, 협회에도 매월 다음 달 10일까지 통보"}]}],"함정":"선지 5는 '시·군·구별'을 '시·도별'로 바꿔 구역을 넓혔다. 선지 4의 사용권 확보는 본 사무소뿐 아니라 분사무소에도 적용된다."}},{"i":"S5-2-1-중개사법-06","r":"S5","g":2,"c":2,"n":6,"s":"중개사법","q":"공인중개사법령상 개업공인중개사 甲의 중개대상물 확인·설명에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲은 중개가 완성되어 거래계약서를 작성하는 때에는 확인·설명사항을 서면으로 작성하여 거래당사자에게 교부해야 한다.","甲이 근저당권이 설정된 중개대상물을 중개하면서 채권최고액을 확인하여 설명하였다면, 실제 피담보채무액까지 조사·확인하여 설명할 의무는 없다.","甲은 매도의뢰인이 중개대상물의 상태에 관한 자료요구에 불응한 경우 그 사실을 매수의뢰인에게 설명하되, 확인·설명서에는 기재하지 않아도 된다.","甲의 소속공인중개사 乙이 성실·정확하게 확인·설명을 하지 않은 경우 乙은 자격정지처분을 받을 수 있다.","甲은 주택 임대차계약을 중개하는 경우 관리비 금액과 그 산출내역을 확인·설명해야 한다."],"a":[3],"L":"중1-4","o":"변형","x":{"한줄":"자료요구에 불응한 사실은 임차·매수의뢰인에게 설명하고, 확인·설명서에도 기재해야 한다.","근거":[{"법령":"공인중개사법 시행령","조문":"제21조제2항","원문":"개업공인중개사는 매도의뢰인ㆍ임대의뢰인 등이 법 제25조제2항의 규정에 따른 중개대상물의 상태에 관한 자료요구에 불응한 경우에는 그 사실을 매수의뢰인ㆍ임차의뢰인 등에게 설명하고, 제3항의 규정에 따른 중개대상물확인ㆍ설명서에 기재하여야 한다."},{"법령":"공인중개사법","조문":"제25조제3항","원문":"개업공인중개사는 중개가 완성되어 거래계약서를 작성하는 때에는 제1항에 따른 확인ㆍ설명사항을 대통령령으로 정하는 바에 따라 서면으로 작성하여 거래당사자에게 교부하고 대통령령으로 정하는 기간 동안 그 원본, 사본 또는 전자문서를 보존하여야 한다."},{"법령":"공인중개사법","조문":"제36조제1항제3호","원문":"제25조제1항의 규정을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 경우(6개월의 범위 안에서 자격정지)"},{"법령":"공인중개사법 시행령","조문":"제21조제1항제3호의2","원문":"관리비 금액과 그 산출내역(주택 임대차 중개의 경우에만 적용한다)"},{"판례":"근저당권 설명의무(판례)","요지":"개업공인중개사는 근저당권이 설정된 부동산을 중개할 때 채권최고액을 확인해 설명하면 되고, 실제 피담보채무액까지 조사·확인할 의무는 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"확인·설명서는 중개가 완성되어 거래계약서를 쓰는 때 작성·교부한다(법 제25조제3항)."},{"번호":2,"판정":"옳음","설명":"채권최고액을 확인해 설명하면 충분하다는 것이 판례다."},{"번호":3,"판정":"틀림","설명":"불응한 사실을 확인·설명서에 기재해야 한다(영 제21조제2항)."},{"번호":4,"판정":"옳음","설명":"소속공인중개사의 확인·설명 위반은 자격정지 사유다(법 제36조제1항제3호)."},{"번호":5,"판정":"옳음","설명":"관리비 금액과 산출내역은 주택 임대차 중개 때 설명할 사항이다(영 제21조제1항제3호의2)."}],"개념":[{"종류":"표","제목":"확인·설명 사항(영 제21조제1항)","머리":["구분","내용","적용"],"행":[["물건 기본사항","종류·소재지·지번·지목·면적·용도·구조·건축연도","공통"],["권리관계","소유권·전세권·저당권·지상권·임차권","공통"],["금액","거래예정금액, 중개보수·실비와 산출내역","공통"],["관리비","관리비 금액과 산출내역","주택 임대차만"],["공법상 제한","토지이용계획, 공법상 거래규제·이용제한","공통"],["상태·환경·입지","수도·전기·가스 등 시설물, 벽면·바닥면·도배, 일조·소음·진동, 도로·대중교통·시장·학교","공통"],["조세","권리 취득에 따라 부담할 조세의 종류·세율","공통"],["주택 임대차 보호","임대인 정보 제시의무·최우선변제 사항, 전입세대확인서 열람·교부, 민간임대주택 임대보증금 보증","주택 임대차만(민간임대 보증은 민간임대주택일 때)"]]},{"종류":"흐름","제목":"확인·설명 절차","단계":[{"이름":"자료 요구","설명":"확인·설명에 필요하면 매도·임대의뢰인에게 중개대상물 상태에 관한 자료 요구(법 제25조제2항)"},{"이름":"불응 시 처리","설명":"그 사실을 매수·임차의뢰인에게 설명하고 확인·설명서에 기재(영 제21조제2항)"},{"이름":"확인·설명","설명":"중개가 완성되기 전에 권리를 취득하려는 의뢰인에게 근거자료(등기사항증명서, 건축물대장 등)를 제시하며 설명"},{"이름":"확인·설명서 작성·교부","설명":"중개가 완성되어 거래계약서를 작성하는 때 거래당사자에게 교부, 개업공인중개사와 해당 중개를 한 소속공인중개사가 서명 및 날인"},{"이름":"보존","설명":"원본·사본·전자문서로 3년(공인전자문서센터 보관 시 생략)"}]}],"함정":"선지 3은 설명만 하면 되고 서식 기재는 안 해도 된다고 줄여 놓았다. 영 제21조제2항은 설명과 기재를 모두 요구한다. 선지 5의 관리비는 임대차에만 해당하고 매매에는 적용되지 않는다.","개정":"확인·설명의 근거자료에 부동산종합증명서와 신탁원부가 들어간 것은 법 제25조제1항 <개정 2025.8.14>이다."}},{"i":"S5-2-1-중개사법-07","r":"S5","g":2,"c":2,"n":7,"s":"중개사법","q":"공인중개사법령상 중개대상물의 표시ㆍ광고 및 모니터링에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사는 의뢰받은 중개대상물에 대하여 표시ㆍ광고를 하려면 개업공인중개사, 소속공인중개사 및 중개보조원에 관한 사항을 명시해야 한다.","개업공인중개사는 중개대상물이 존재하지 않아서 실제로 거래를 할 수 없는 중개대상물에 대한 광고와 같은 부당한 표시ㆍ광고를 해서는 안 된다.","개업공인중개사는 중개대상물의 가격 등 내용을 과장되게 하는 부당한 표시ㆍ광고를 해서는 안 된다.","국토교통부장관은 인터넷을 이용한 중개대상물에 대한 표시ㆍ광고의 규정준수 여부에 관하여 기본 모니터링과 수시 모니터링을 할 수 있다.","국토교통부장관은 인터넷 표시ㆍ광고 모니터링 업무 수행에 필요한 전문인력과 전담조직을 갖췄다고 국토교통부장관이 인정하는 단체에게 인터넷 표시ㆍ광고 모니터링 업무를 위탁할 수 있다."],"a":[1],"L":"중1-4","o":"기출","x":{"한줄":"표시·광고에는 중개사무소와 개업공인중개사에 관한 사항을 밝히고, 중개보조원에 관한 사항은 적으면 안 된다.","근거":[{"법령":"공인중개사법","조문":"제18조의2제1항","원문":"개업공인중개사가 의뢰받은 중개대상물에 대하여 표시ㆍ광고…를 하려면 중개사무소, 개업공인중개사에 관한 사항으로서 대통령령으로 정하는 사항을 명시하여야 하며, 중개보조원에 관한 사항은 명시해서는 아니 된다."},{"법령":"공인중개사법 시행령","조문":"제17조의2제1항","원문":"1. 중개사무소의 명칭, 소재지, 연락처 및 등록번호 2. 개업공인중개사의 성명(법인인 경우에는 대표자의 성명)"},{"법령":"공인중개사법","조문":"제18조의2제4항","원문":"개업공인중개사는 중개대상물에 대하여 다음 각 호의 어느 하나에 해당하는 부당한 표시ㆍ광고를 하여서는 아니 된다. 1. 중개대상물이 존재하지 않아서 실제로 거래를 할 수 없는 중개대상물에 대한 표시ㆍ광고 2. 중개대상물의 가격 등 내용을 사실과 다르게 거짓으로 표시ㆍ광고하거나 사실을 과장되게 하는 표시ㆍ광고"},{"법령":"공인중개사법 시행규칙","조문":"제10조의3제1항","원문":"1. 기본 모니터링 업무: …분기별로 실시하는 모니터링 2. 수시 모니터링 업무: 법 제18조의2를 위반한 사실이 의심되는 경우 등 국토교통부장관이 필요하다고 판단하여 실시하는 모니터링"},{"법령":"공인중개사법 시행령","조문":"제17조의3제1항제4호","원문":"그 밖에 인터넷 표시ㆍ광고 모니터링 업무 수행에 필요한 전문인력과 전담조직을 갖췄다고 국토교통부장관이 인정하는 기관 또는 단체"}],"선지":[{"번호":1,"판정":"틀림","설명":"중개보조원에 관한 사항은 명시해서는 안 된다(법 제18조의2제1항)."},{"번호":2,"판정":"옳음","설명":"존재하지 않는 매물 광고는 부당한 표시·광고다(법 제18조의2제4항제1호)."},{"번호":3,"판정":"옳음","설명":"가격 등을 거짓·과장하는 광고는 금지된다(법 제18조의2제4항제2호)."},{"번호":4,"판정":"옳음","설명":"모니터링은 분기별 기본 모니터링과 수시 모니터링으로 나뉜다(규칙 제10조의3제1항)."},{"번호":5,"판정":"옳음","설명":"전문인력과 전담조직을 갖췄다고 장관이 인정하는 단체에 위탁할 수 있다(영 제17조의3제1항제4호)."}],"개념":[{"종류":"표","제목":"표시·광고 규제","머리":["구분","내용","위반 시"],"행":[["명시사항","중개사무소 명칭·소재지·연락처·등록번호, 개업공인중개사 성명(법인은 대표자). 중개보조원 사항은 명시 금지","100만원 이하 과태료"],["인터넷 광고 추가 명시","소재지·면적·가격·종류·거래 형태 등(영 제17조의2제2항), 구체적 방법은 장관 고시","100만원 이하 과태료"],["부당한 광고","없는 매물, 거짓·과장, 중개 대상이 될 수 없거나 중개 의사 없는 매물, 중요 사실 은폐·축소","500만원 이하 과태료"],["개업공인중개사 아닌 자의 광고","표시·광고 금지","1년 이하 징역·1천만원 이하 벌금, 포상금 신고 대상"]]},{"종류":"표","제목":"인터넷 표시·광고 모니터링","머리":["구분","내용"],"행":[["주체","국토교통부장관(법 제18조의3제1항)"],["위탁 가능 기관","공공기관, 정부출연연구기관, 관련 업무 비영리법인, 장관이 인정하는 단체(영 제17조의3)"],["기본 모니터링","분기별. 다음 해 기본계획서는 12월 31일까지, 결과보고서는 분기 마지막 날부터 30일 이내"],["수시 모니터링","위반 의심 시. 결과보고서는 완료일부터 15일 이내"],["결과 조치","장관이 시·도지사·등록관청에 통보하고 조사·조치 요구, 요구받은 기관은 완료일부터 10일 이내 결과 통보"]]}],"함정":"선지 1은 명시사항에 중개보조원을 넣었다. 소속공인중개사는 명시사항이 아니고 중개보조원은 명시 금지다. 선지 5의 위탁 대상에는 공공기관 등 외에 장관이 인정하는 단체도 들어간다."}},{"i":"S5-2-1-중개사법-08","r":"S5","g":2,"c":2,"n":8,"s":"중개사법","q":"개업공인중개사 甲의 중개보조원 乙이 중개업무를 하면서 중개대상물의 거래상 중요사항에 관하여 거짓된 언행으로 중개의뢰인 丙의 판단을 그르치게 하여 재산상 손해를 입혔다. 공인중개사법령에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["乙의 업무상 행위는 甲의 행위로 본다.","乙은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.","등록관청은 甲의 중개사무소 개설등록을 취소할 수 있다.","시·도지사는 乙에 대하여 6개월의 범위 안에서 자격정지처분을 할 수 있다.","丙은 甲에게 손해배상을 청구할 수 있다."],"a":[4],"L":"중1-4","o":"변형","x":{"한줄":"자격정지는 소속공인중개사에게 하는 처분이고, 공인중개사가 아닌 중개보조원에게는 이 처분이 없다.","근거":[{"법령":"공인중개사법","조문":"제15조제2항","원문":"소속공인중개사 또는 중개보조원의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다."},{"법령":"공인중개사법","조문":"제33조제1항제4호","원문":"해당 중개대상물의 거래상의 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위"},{"법령":"공인중개사법","조문":"제49조제1항제10호","원문":"제33조제1항제1호부터 제4호까지의 규정을 위반한 자(1년 이하의 징역 또는 1천만원 이하의 벌금)"},{"법령":"공인중개사법","조문":"제36조제1항","원문":"시ㆍ도지사는 공인중개사가 소속공인중개사로서 업무를 수행하는 기간 중에 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 그 자격을 정지할 수 있다."},{"법령":"공인중개사법","조문":"제38조제2항제9호","원문":"제33조제1항 각 호에 규정된 금지행위를 한 경우(중개사무소의 개설등록을 취소할 수 있다)"}],"선지":[{"번호":1,"판정":"옳음","설명":"고용인의 업무상 행위는 개업공인중개사의 행위로 본다(법 제15조제2항)."},{"번호":2,"판정":"옳음","설명":"거짓된 언행은 제33조제1항제4호 위반으로 제49조제1항의 벌칙 대상이다. 개업공인중개사등에 중개보조원도 포함된다."},{"번호":3,"판정":"옳음","설명":"금지행위를 한 개업공인중개사는 등록을 취소할 수 있다(법 제38조제2항제9호)."},{"번호":4,"판정":"틀림","설명":"자격정지 대상은 소속공인중개사로서 업무를 수행하는 공인중개사뿐이다(법 제36조제1항). 중개보조원에게 직접 내리는 행정처분 규정은 없다."},{"번호":5,"판정":"옳음","설명":"乙의 행위는 甲의 행위로 보아 甲이 중개행위로 인한 재산상 손해를 배상한다(법 제30조제1항, 제15조제2항)."}],"개념":[{"종류":"표","제목":"고용인 위반행위의 책임","머리":["구분","개업공인중개사","소속공인중개사","중개보조원"],"행":[["업무상 행위","본인 행위","개업공인중개사의 행위로 봄","개업공인중개사의 행위로 봄"],["형사처벌","양벌규정으로 해당 조의 벌금형(상당한 주의·감독 시 면책, 법 제50조)","행위자로서 처벌","행위자로서 처벌"],["행정처분","금지행위 시 등록취소 가능·업무정지","자격정지(6개월 범위)","직접 처분 규정 없음"],["민사","손해배상책임, 보증에서 지급","본인도 불법행위 책임 가능","본인도 불법행위 책임 가능"]]},{"종류":"흐름","제목":"금지행위(거짓 언행) 사건의 책임 흐름","단계":[{"이름":"행위","설명":"중개보조원이 거래상 중요사항에 관해 거짓된 언행"},{"이름":"간주","설명":"그 행위는 고용한 개업공인중개사의 행위로 본다(법 제15조제2항)"},{"이름":"형사","설명":"행위자는 1년 이하 징역·1천만원 이하 벌금(법 제49조제1항제10호), 개업공인중개사는 상당한 주의·감독을 하지 않았으면 같은 벌금형(법 제50조)"},{"이름":"행정","설명":"개업공인중개사는 등록취소 가능(법 제38조제2항제9호) 또는 업무정지(법 제39조제1항제11호)"},{"이름":"민사","설명":"의뢰인은 개업공인중개사에게 손해배상 청구, 보증보험·공제·공탁에서 지급받을 수 있음(법 제30조)"}]}],"함정":"선지 4는 소속공인중개사였다면 맞는 말이다. 사례의 乙이 중개보조원이어서 틀렸다. 선지 2·3은 乙이 중개보조원이어도 그대로 성립한다."}},{"i":"S5-2-1-중개사법-09","r":"S5","g":2,"c":2,"n":9,"s":"중개사법","q":"공인중개사법령상 중개사무소 및 분사무소의 이전신고에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["법인인 개업공인중개사가 분사무소를 이전하여 신고하는 경우 이전신고서에 중개사무소등록증을 첨부해야 한다.","개업공인중개사가 등록관청의 관할 지역 외의 지역으로 중개사무소를 이전한 경우 이전한 날부터 10일 이내에 종전의 등록관청에 신고해야 한다.","분사무소의 이전신고는 이전한 날부터 10일 이내에 주된 사무소의 소재지를 관할하는 등록관청에 하며, 신고를 받은 등록관청은 그 분사무소의 이전 전 및 이전 후의 소재지를 관할하는 시장·군수·구청장에게 지체 없이 통보해야 한다.","관할 지역 외로 이전한 경우 이전신고 전에 발생한 사유로 인한 행정처분은 종전의 등록관청이 한다.","개업공인중개사가 중개사무소 이전신고를 하지 않은 경우 업무정지처분을 받는다."],"a":[3],"L":"중1-4","o":"변형","x":{"한줄":"분사무소 이전은 주된 사무소 등록관청에 10일 안에 신고하고, 등록관청이 이전 전·후 지역 관청에 통보한다.","근거":[{"법령":"공인중개사법","조문":"제20조제1항","원문":"개업공인중개사는 중개사무소를 이전한 때에는 이전한 날부터 10일 이내에 국토교통부령으로 정하는 바에 따라 등록관청에 이전사실을 신고하여야 한다. 다만, 중개사무소를 등록관청의 관할 지역 외의 지역으로 이전한 경우에는 이전 후의 중개사무소를 관할하는 시장ㆍ군수 또는 구청장…에게 신고하여야 한다."},{"법령":"공인중개사법","조문":"제20조제3항","원문":"제1항 단서에 따른 신고 전에 발생한 사유로 인한 개업공인중개사에 대한 행정처분은 이전후 등록관청이 이를 행한다."},{"법령":"공인중개사법 시행규칙","조문":"제11조제1항","원문":"중개사무소의 이전신고를 하려는 자는 별지 제12호서식의 중개사무소이전신고서에 다음 각 호의 서류를 첨부하여 등록관청(분사무소의 경우에는 주된 사무소의 소재지를 관할하는 등록관청을 말한다)에 제출해야 한다. 1. 중개사무소등록증(분사무소의 경우에는 분사무소설치신고확인서를 말한다) 2. 건축물대장에 기재된 건물에 중개사무소를 확보…하였음을 증명하는 서류"},{"법령":"공인중개사법 시행규칙","조문":"제11조제3항","원문":"등록관청은 분사무소의 이전신고를 받은 때에는 지체 없이 그 분사무소의 이전 전 및 이전 후의 소재지를 관할하는 시장ㆍ군수 또는 구청장에게 이를 통보하여야 한다."},{"법령":"공인중개사법","조문":"제51조제3항제3호","원문":"제20조제1항을 위반하여 중개사무소의 이전신고를 하지 아니한 자(100만원 이하의 과태료)"}],"선지":[{"번호":1,"판정":"틀림","설명":"분사무소는 등록증이 아니라 분사무소설치신고확인서를 붙인다(규칙 제11조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"관할 밖으로 이전하면 이전 후 등록관청에 신고한다(법 제20조제1항 단서)."},{"번호":3,"판정":"옳음","설명":"분사무소 이전신고는 주된 사무소 등록관청에 하고, 등록관청이 이전 전·후 소재지 관할 관청에 통보한다(규칙 제11조제1항·제3항)."},{"번호":4,"판정":"틀림","설명":"이전신고 전에 생긴 사유의 행정처분은 이전 후 등록관청이 한다(법 제20조제3항)."},{"번호":5,"판정":"틀림","설명":"이전신고를 하지 않으면 100만원 이하 과태료다(법 제51조제3항제3호)."}],"개념":[{"종류":"표","제목":"이전신고 경우별 비교","머리":["구분","신고할 곳","붙일 서류","등록증 처리"],"행":[["관할 안 이전","종전 등록관청","등록증 + 사무소 확보 서류","재교부 또는 변경사항 적어 교부"],["관할 밖 이전","이전 후 등록관청","등록증 + 사무소 확보 서류","재교부"],["분사무소 이전","주된 사무소 등록관청","분사무소설치신고확인서 + 사무소 확보 서류","신고확인서 재교부, 이전 전·후 시·군·구에 통보"]]},{"종류":"흐름","제목":"관할 밖 이전 절차","단계":[{"이름":"이전","설명":"중개사무소 이전"},{"이름":"신고","설명":"이전한 날부터 10일 이내 이전 후 등록관청에 신고서, 등록증, 사무소 확보 서류 제출"},{"이름":"서류 송부 요청","설명":"이전 후 등록관청이 종전 등록관청에 관련 서류 송부 요청(법 제20조제2항)"},{"이름":"서류 송부","설명":"종전 관청이 지체 없이 등록대장, 개설등록 신청서류, 최근 1년간 행정처분 서류 송부(규칙 제11조제4항)"},{"이름":"등록증 재교부","설명":"내용이 적합하면 재교부(규칙 제11조제2항)"},{"이름":"행정처분","설명":"이전신고 전에 생긴 사유의 처분도 이전 후 등록관청이 담당"}]}],"함정":"분사무소는 서류도 신고 관청도 본점과 다르다(등록증이 아닌 신고확인서, 분사무소 소재지가 아닌 주된 사무소 등록관청). 선지 4는 이전신고 뒤 처분 관청이 바뀐다는 점을 거꾸로 쓴 것이다."}},{"i":"S5-2-1-중개사법-10","r":"S5","g":2,"c":2,"n":10,"s":"중개사법","q":"공인중개사법령상 중개보조원에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사가 고용할 수 있는 중개보조원의 수는 개업공인중개사와 소속공인중개사를 합한 수의 5배를 초과할 수 없다.","개업공인중개사가 중개보조원을 고용한 경우에는 업무를 개시한 후 10일 이내에 등록관청에 신고하면 된다.","중개보조원은 현장안내 등 중개업무를 보조하는 경우 중개의뢰인에게 본인이 중개보조원이라는 사실을 미리 알려야 한다.","중개보조원은 고용 신고일 전 1년 이내에 시·도지사 또는 등록관청이 실시하는 직무교육을 받아야 한다.","중개보조원의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다."],"a":[2],"L":"중1-5","o":"변형","x":{"한줄":"중개보조원의 고용은 직무교육을 받게 한 뒤 업무를 개시하기 전까지 신고하며, 업무 개시 뒤 사후 신고는 허용되지 않는다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제8조제1항","원문":"개업공인중개사는 소속공인중개사 또는 중개보조원을 고용한 경우에는 법 제34조제2항 또는 제3항에 따른 교육을 받도록 한 후 법 제15조제1항에 따라 업무개시 전까지 등록관청에 신고(전자문서에 의한 신고를 포함한다)하여야 한다."},{"법령":"공인중개사법","조문":"제15조제3항","원문":"개업공인중개사가 고용할 수 있는 중개보조원의 수는 개업공인중개사와 소속공인중개사를 합한 수의 5배를 초과하여서는 아니 된다."},{"법령":"공인중개사법","조문":"제18조의4","원문":"중개보조원은 현장안내 등 중개업무를 보조하는 경우 중개의뢰인에게 본인이 중개보조원이라는 사실을 미리 알려야 한다."},{"법령":"공인중개사법","조문":"제34조제3항","원문":"중개보조원은 제15조제1항에 따른 고용 신고일 전 1년 이내에 시ㆍ도지사 또는 등록관청이 실시하는 직무교육을 받아야 한다. 다만, 고용관계 종료 신고 후 1년 이내에 고용 신고를 다시 하려는 자는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"중개보조원은 개업공인중개사와 소속공인중개사 합계의 5배를 넘을 수 없다(법 제15조제3항)."},{"번호":2,"판정":"틀림","설명":"고용 신고는 업무개시 전까지 해야 한다(규칙 제8조제1항). 10일은 고용관계 종료 신고 기한이다(규칙 제8조제4항)."},{"번호":3,"판정":"옳음","설명":"신분 고지의무가 있다(법 제18조의4)."},{"번호":4,"판정":"옳음","설명":"고용 신고일 전 1년 이내 직무교육을 받는다(법 제34조제3항, 영 제28조제2항)."},{"번호":5,"판정":"옳음","설명":"고용인의 업무상 행위는 개업공인중개사의 행위로 본다(법 제15조제2항)."}],"개념":[{"종류":"표","제목":"고용 관련 기간·숫자","머리":["항목","내용"],"행":[["고용 신고","교육을 받게 한 뒤 업무개시 전까지 등록관청에 신고(규칙 제8조제1항)"],["고용관계 종료 신고","종료된 날부터 10일 이내(규칙 제8조제4항)"],["소속공인중개사 교육","고용 신고일 전 1년 이내 시·도지사 실무교육 45시간(영 제28조제1항)"],["중개보조원 교육","고용 신고일 전 1년 이내 시·도지사 또는 등록관청 직무교육 3시간 이상 4시간 이하(영 제28조제2항)"],["교육 면제","고용관계 종료 신고 후 1년 이내 다시 고용 신고"],["연수교육","실무교육 후 2년마다 12시간 이상 16시간 이하, 시·도지사(영 제28조제3항)"],["중개보조원 수","개업공인중개사 + 소속공인중개사 합계의 5배 이하. 초과 시 등록취소(법 제38조제1항제5호의2), 1년 이하 징역·1천만원 이하 벌금"],["신분 미고지","본인과 소속 개업공인중개사에게 500만원 이하 과태료(주의·감독 다한 개업공인중개사는 제외)"]]},{"종류":"비교","제목":"소속공인중개사와 중개보조원","왼쪽":{"이름":"소속공인중개사","항목":["공인중개사 자격 필요","실무교육(시·도지사)","인장 등록 의무","그 중개를 했으면 확인·설명서·계약서에 서명 및 날인","확인·설명 의무 있음, 위반 시 자격정지"]},"오른쪽":{"이름":"중개보조원","항목":["자격 없음","직무교육(시·도지사 또는 등록관청)","인장 등록 의무 없음","서명 및 날인 의무 없음","확인·설명 의무 없음, 현장안내 등 단순 보조만"]}}],"함정":"고용 신고와 고용관계 종료 신고의 시기를 바꿔 쓰기 쉽다. 신고 시기는 업무개시 전이고, 10일은 종료 신고 기한이다.","개정":"중개보조원 수 제한은 법 제15조제3항(신설 2023.4.18)이다. 위반하면 법 제38조제1항제5호의2에 따라 등록을 취소해야 한다."}},{"i":"S5-2-1-중개사법-11","r":"S5","g":2,"c":2,"n":11,"s":"중개사법","q":"공인중개사법령상 중개의뢰인 甲과 개업공인중개사 乙의 중개계약에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["甲의 요청에 따라 乙이 일반중개계약서를 작성한 경우 그 계약서를 3년간 보존해야 한다.","일반중개계약은 표준이 되는 서식이 정해져 있다.","전속중개계약은 법령이 정하는 계약서에 의하여야 하며, 乙이 서명 및 날인하되 소속공인중개사가 있는 경우 소속공인중개사가 함께 서명 및 날인해야 한다.","전속중개계약의 유효기간은 甲과 乙이 별도로 정하더라도 3개월을 초과할 수 없다.","전속중개계약을 체결한 甲이 그 유효기간 내에 스스로 발견한 상대방과 거래한 경우 중개보수에 해당하는 금액을 乙에게 위약금으로 지급해야 한다."],"a":[2],"L":"중1-6","o":"기출","x":{"한줄":"일반중개계약에도 국토교통부장관이 정한 표준서식이 있고, 다만 사용은 권장일 뿐이다.","근거":[{"법령":"공인중개사법 시행령","조문":"제19조","원문":"국토교통부장관은 법 제22조의 규정에 따른 일반중개계약의 표준이 되는 서식을 정하여 그 사용을 권장할 수 있다."},{"법령":"공인중개사법 시행령","조문":"제20조제1항","원문":"법 제23조제1항의 규정에 따른 전속중개계약의 유효기간은 3월로 한다. 다만, 당사자간에 다른 약정이 있는 경우에는 그 약정에 따른다."},{"법령":"공인중개사법 시행규칙","조문":"제14조","원문":"①법 제23조제2항의 규정에 따른 전속중개계약서는 별지 제15호서식에 따른다. ②법 제23조제2항에서 \"국토교통부령이 정하는 기간\"이라 함은 3년을 말한다."},{"법령":"공인중개사법 시행규칙","조문":"별지 제15호서식(전속중개계약서)","원문":"전속중개계약의 유효기간 내에 갑이 스스로 발견한 상대방과 거래한 경우(제3호)에는 중개보수의 50퍼센트에 해당하는 금액의 범위에서 을이 중개행위를 할 때 소요된 비용(사회통념에 비추어 상당하다고 인정되는 비용을 말한다)을 지급한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"3년 보존의무는 전속중개계약서에만 있다. 일반중개계약서는 보존의무가 없다(법 제23조제2항, 규칙 제14조제2항)."},{"번호":2,"판정":"옳음","설명":"표준서식이 있고 사용은 권장이다(영 제19조)."},{"번호":3,"판정":"틀림","설명":"전속중개계약서 서식 끝은 의뢰인과 개업공인중개사가 각자 서명 또는 날인한다. 소속공인중개사의 함께 서명 및 날인은 요구되지 않는다(별지 제15호서식)."},{"번호":4,"판정":"틀림","설명":"3개월은 정하지 않았을 때의 기간이고, 당사자 약정이 있으면 그에 따른다(영 제20조제1항)."},{"번호":5,"판정":"틀림","설명":"스스로 발견한 상대방과 거래하면 위약금이 아니라 중개보수의 50% 범위에서 중개사가 쓴 비용을 낸다(별지 제15호서식)."}],"개념":[{"종류":"표","제목":"일반중개계약과 전속중개계약","머리":["구분","일반중개계약","전속중개계약"],"행":[["계약서","의뢰인이 요청하면 작성, 표준서식 사용 권장(영 제19조)","국토교통부령 서식(별지 제15호) 필수(법 제23조제2항)"],["보존","의무 없음","3년"],["처리상황 통지","의무 없음","2주일에 1회 이상 문서"],["정보공개","의무 없음","체결 후 7일 이내 정보망·일간신문, 비공개 요청 시 공개 금지"],["유효기간","정한 바 없음","원칙 3개월, 약정이 있으면 그에 따름"],["제재","없음","서식 미사용·미보존은 업무정지, 공개 위반은 등록취소 가능"]]},{"종류":"표","제목":"전속중개계약 중 거래한 경우 의뢰인 부담","머리":["상황","의뢰인 부담"],"행":[["다른 개업공인중개사에게 의뢰해 거래","중개보수에 해당하는 금액을 위약금으로 지급"],["소개받은 상대방과 중개사를 배제하고 직접 거래","중개보수에 해당하는 금액을 위약금으로 지급"],["스스로 발견한 상대방과 거래","중개보수의 50% 범위에서 소요된 비용(사회통념상 상당한 비용)"]]}],"함정":"일반과 전속의 의무를 맞바꾼 선지가 나온다. 선지 1은 전속의 3년 보존을 일반에 붙였다. 선지 5는 스스로 발견한 상대방을 소개받은 상대방과 같은 취급으로 쓴 것이다."}},{"i":"S5-2-1-중개사법-12","r":"S5","g":2,"c":2,"n":12,"s":"중개사법","q":"중개의뢰인 甲과 개업공인중개사 乙은 공인중개사법령에 따른 전속중개계약을 체결하고 전속중개계약서를 작성하였다. 이에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["甲과 乙이 전속중개계약의 유효기간을 4개월로 약정한 것은 유효하다.","乙은 전속중개계약서를 3년 동안 보존해야 한다.","甲은 乙이 공인중개사법령상의 중개대상물 확인ㆍ설명의무를 이행하는데 협조해야 한다.","전속중개계약에 정하지 않은 사항에 대하여는 甲과 乙이 합의하여 별도로 정할 수 있다.","전속중개계약의 유효기간 내에 甲이 스스로 발견한 상대방과 거래한 경우, 甲은 乙에게 지급해야 할 중개보수 전액을 위약금으로 지급해야 한다."],"a":[5],"L":"중1-6","o":"기출","x":{"한줄":"스스로 발견한 상대방과 거래한 경우 의뢰인은 중개보수 전액이 아니라 중개보수의 50% 범위에서 중개사가 쓴 비용을 낸다.","근거":[{"법령":"공인중개사법 시행령","조문":"제20조제1항","원문":"법 제23조제1항의 규정에 따른 전속중개계약의 유효기간은 3월로 한다. 다만, 당사자간에 다른 약정이 있는 경우에는 그 약정에 따른다."},{"법령":"공인중개사법 시행규칙","조문":"제14조제2항","원문":"법 제23조제2항에서 \"국토교통부령이 정하는 기간\"이라 함은 3년을 말한다."},{"법령":"공인중개사법 시행규칙","조문":"별지 제15호서식(전속중개계약서)","원문":"② 갑은 을이 법 제25조에 따른 중개대상물 확인ㆍ설명의무를 이행하는데 협조하여야 한다. / 제3호의 경우에는 중개보수의 50퍼센트에 해당하는 금액의 범위에서 을이 중개행위를 할 때 소요된 비용…을 지급한다. / 이 계약에 정하지 않은 사항에 대하여는 갑과 을이 합의하여 별도로 정할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"약정이 있으면 3개월보다 길어도 된다(영 제20조제1항)."},{"번호":2,"판정":"옳음","설명":"전속중개계약서는 3년 보존한다(규칙 제14조제2항)."},{"번호":3,"판정":"옳음","설명":"의뢰인의 협조의무가 전속중개계약서(별지 제15호서식)에 있다."},{"번호":4,"판정":"옳음","설명":"계약서의 그 밖의 사항 조항에 합의로 별도 정할 수 있다고 되어 있다(별지 제15호서식)."},{"번호":5,"판정":"틀림","설명":"스스로 발견한 상대방과의 거래는 중개보수의 50% 범위의 비용만 낸다(별지 제15호서식)."}],"개념":[{"종류":"흐름","제목":"전속중개계약 이후 개업공인중개사의 의무","단계":[{"이름":"계약 체결","설명":"별지 제15호서식 사용, 계약서 3년 보존"},{"이름":"정보공개","설명":"체결 후 7일 이내 부동산거래정보망 또는 일간신문에 공개. 의뢰인이 비공개를 요청하면 공개하지 않음(법 제23조제3항)"},{"이름":"공개 통지","설명":"공개했으면 지체 없이 의뢰인에게 내용을 문서로 통지"},{"이름":"처리상황 통지","설명":"계약 체결 후 2주일에 1회 이상 문서로 통지"},{"이름":"거래 완성","설명":"정보망에 공개한 물건은 거래가 완성되면 지체 없이 거래정보사업자에게 통보(법 제24조제7항)"}]},{"종류":"표","제목":"공개할 정보(영 제20조제2항)","머리":["공개 항목","비고"],"행":[["종류·소재지·지목·면적·용도·구조·건축연도","물건 특정 사항"],["벽면·도배 상태","-"],["수도·전기·가스·소방·열공급·승강기 설비, 오수·폐수·쓰레기 처리시설 상태","-"],["도로·대중교통 연계성, 시장·학교 근접성, 지형, 일조·소음·진동","입지·환경조건"],["소유권·전세권·저당권·지상권·임차권 등 권리관계","권리자의 주소·성명 등 인적 사항은 공개 금지"],["공법상 이용제한·거래규제","-"],["거래예정금액·공시지가","임대차는 공시지가 공개하지 않을 수 있음"]]}],"함정":"선지 1과 2는 길이와 숫자만 보고 틀렸다고 오해하기 쉽다. 4개월 약정은 유효하고 보존은 3년이다. 5번만 위약금 범위가 다르다."}},{"i":"S5-2-1-중개사법-13","r":"S5","g":2,"c":2,"n":13,"s":"중개사법","q":"공인중개사법령상 금지행위에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["소속공인중개사는 소속 개업공인중개사의 승낙을 받으면 중개의뢰인과 직접 거래를 할 수 있다.","개업공인중개사가 거래당사자 중 어느 한쪽만을 대리하는 행위도 금지된다.","개인인 개업공인중개사가 중개대상물이 아닌 건축자재의 매매를 업으로 하는 것은 법 제33조에 따른 금지행위에 해당하지 않는다.","개업공인중개사가 중개의뢰인과 직접 거래를 하여 체결한 계약은 무효이다.","개업공인중개사가 사례 명목으로 법정 중개보수를 초과하여 금품을 받았더라도 이를 중개의뢰인에게 돌려주면 금지행위가 성립하지 않는다."],"a":[3],"L":"중1-7","o":"변형","x":{"한줄":"법 제33조제1항제1호의 금지행위는 중개대상물(토지·건축물 등)의 매매를 업으로 하는 것이어서, 건축자재 매매업은 해당하지 않는다.","근거":[{"법령":"공인중개사법","조문":"제33조제1항","원문":"개업공인중개사등은 다음 각 호의 행위를 하여서는 아니된다. 1. 제3조에 따른 중개대상물의 매매를 업으로 하는 행위 … 3. 사례ㆍ증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수 또는 실비를 초과하여 금품을 받는 행위 … 6. 중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위"},{"법령":"공인중개사법","조문":"제10조제3항","원문":"등록관청은 개업공인중개사ㆍ소속공인중개사ㆍ중개보조원 및 개업공인중개사인 법인의 사원ㆍ임원(이하 \"개업공인중개사등\"이라 한다)이 제1항제1호부터 제11호까지의 어느 하나에 해당하는지 여부를 확인하기 위하여 관계 기관에 조회할 수 있다."},{"판례":"직접거래 금지의 성격(판례)","요지":"직접거래를 금지한 규정은 공인중개사의 공정한 업무수행을 위한 단속규정이어서, 이를 어기고 체결한 계약이 사법상 무효가 되지는 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"금지행위는 소속공인중개사에게도 적용되고, 승낙으로 풀리지 않는다(법 제33조제1항, 제2조제5호)."},{"번호":2,"판정":"틀림","설명":"금지되는 것은 쌍방대리이고, 한쪽만 대리하는 일방대리는 금지되지 않는다(법 제33조제1항제6호)."},{"번호":3,"판정":"옳음","설명":"제1호의 대상은 제3조의 중개대상물이다. 건축자재는 중개대상물이 아니다."},{"번호":4,"판정":"틀림","설명":"단속규정이어서 계약 자체는 유효하다(판례)."},{"번호":5,"판정":"틀림","설명":"초과 수수가 이루어진 때 금지행위가 성립하고, 나중에 돌려줘도 성립은 달라지지 않는다(법 제33조제1항제3호)."}],"개념":[{"종류":"표","제목":"개업공인중개사등의 금지행위(법 제33조제1항)","머리":["호","행위","벌칙"],"행":[["1","중개대상물의 매매를 업으로 하는 행위","1년 이하 징역·1천만원 이하 벌금"],["2","무등록 중개업자임을 알면서 그를 통해 중개를 의뢰받거나 자기 명의를 이용하게 하는 행위","1년 이하 징역·1천만원 이하 벌금"],["3","사례·증여 등 어떤 명목으로든 보수·실비를 초과해 받는 행위","1년 이하 징역·1천만원 이하 벌금"],["4","중요사항에 관한 거짓된 언행으로 의뢰인의 판단을 그르치게 하는 행위","1년 이하 징역·1천만원 이하 벌금"],["5","양도·알선이 금지된 증서 등의 매매·교환을 중개하거나 그 매매를 업으로 하는 행위","3년 이하 징역·3천만원 이하 벌금"],["6","중개의뢰인과 직접 거래, 거래당사자 쌍방 대리","3년 이하 징역·3천만원 이하 벌금"],["7","미등기 또는 전매제한 부동산의 매매를 중개하는 등 투기를 조장하는 행위","3년 이하 징역·3천만원 이하 벌금"],["8","거짓으로 거래가 완료된 것처럼 꾸미는 등 시세에 부당한 영향을 주는 행위","3년 이하 징역·3천만원 이하 벌금, 포상금 대상"],["9","단체를 구성해 특정 물건의 중개를 제한하거나 비구성원과의 공동중개를 제한하는 행위","3년 이하 징역·3천만원 이하 벌금, 포상금 대상"]]},{"종류":"비교","제목":"법 제33조 제1항과 제2항","왼쪽":{"이름":"제1항","항목":["주체: 개업공인중개사등(개업공인중개사·소속공인중개사·중개보조원·법인의 사원·임원)","행위: 매매업, 직접거래, 쌍방대리 등 9가지","1호~4호 1년·1천만원, 5호~9호 3년·3천만원","개업공인중개사는 등록취소 가능·업무정지, 소속공인중개사는 자격정지"]},"오른쪽":{"이름":"제2항","항목":["주체: 누구든지","행위: 시세에 부당한 영향을 줄 목적으로 개업공인중개사등의 업무를 방해하는 5가지(안내문·온라인 커뮤니티 등)","3년 이하 징역·3천만원 이하 벌금","포상금 대상"]}}],"함정":"선지 2는 쌍방대리와 일방대리를 구별해야 한다. 선지 4는 금지규정이라는 이유로 계약까지 무효라고 확장한 것이다. 선지 3은 개인 개업공인중개사를 전제로 한다. 법인은 법 제14조의 겸업제한 때문에 건축자재 매매업을 함께 할 수 없다."}},{"i":"S5-2-1-중개사법-14","r":"S5","g":2,"c":2,"n":14,"s":"중개사법","q":"공인중개사법령상 주거용 건축물의 중개대상물 확인·설명서[Ⅰ]에서 개업공인중개사의 세부 확인사항(Ⅱ)에 기재하는 항목은?","b":null,"bs":"없음","img":[],"ch":["입지조건 중 도로와의 관계","비선호시설(1km 이내)","관리에 관한 사항 중 경비실","환경조건 중 일조량","건축물대장상 위반건축물 여부"],"a":[4],"L":"중1-8","o":"변형","x":{"한줄":"주거용 확인·설명서에서 일조량·소음·진동 같은 환경조건은 세부 확인사항(Ⅱ)이고, 나머지 선지는 기본 확인사항(Ⅰ)이다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제16조제1호","원문":"중개대상물 확인ㆍ설명서[Ⅰ](주거용건축물) : 별지 제20호서식"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식","원문":"Ⅰ. 개업공인중개사 기본 확인사항 ① 대상물건의 표시 ② 권리관계 ③ 토지이용계획, 공법상 이용제한 및 거래규제에 관한 사항 ④ 임대차 확인사항 ⑤ 입지조건 ⑥ 관리에 관한 사항 ⑦ 비선호시설(1km이내) ⑧ 거래예정금액 등 ⑨ 취득 시 부담할 조세의 종류 및 세율 / Ⅱ. 개업공인중개사 세부 확인사항 ⑩ 실제 권리관계 또는 공시되지 않은 물건의 권리 사항 ⑪ 내부ㆍ외부 시설물의 상태(건축물) ⑫ 벽면ㆍ바닥면 및 도배 상태 ⑬ 환경조건 ⑭ 현장안내"}],"선지":[{"번호":1,"판정":"-","설명":"입지조건은 기본 확인사항(Ⅰ)의 항목이다. 도로와의 관계, 대중교통, 주차장, 교육시설을 적는다."},{"번호":2,"판정":"-","설명":"비선호시설은 기본 확인사항(Ⅰ)에 있다."},{"번호":3,"판정":"-","설명":"관리에 관한 사항(경비실, 관리주체, 관리비)은 기본 확인사항(Ⅰ)이다."},{"번호":4,"판정":"-","설명":"환경조건(일조량, 소음, 진동)은 세부 확인사항(Ⅱ)이다."},{"번호":5,"판정":"-","설명":"대상물건의 표시에 속하는 위반건축물 여부는 기본 확인사항(Ⅰ)이다."}],"개념":[{"종류":"표","제목":"주거용 확인·설명서 기본/세부 확인사항","머리":["구분","항목"],"행":[["기본 확인사항(Ⅰ) - 공부 등으로 직접 확인","대상물건의 표시(내진설계·위반건축물 여부 포함), 권리관계(등기부, 신탁등기, 공동담보, 계약갱신요구권), 토지이용계획·공법상 제한, 임대차 확인사항, 입지조건, 관리, 비선호시설, 거래예정금액 등, 취득 시 조세"],["세부 확인사항(Ⅱ) - 매도·임대의뢰인 자료 요구·고지","실제 권리관계 또는 공시되지 않은 물건의 권리, 시설물 상태, 벽면·바닥면·도배, 환경조건, 현장안내(중개보조원 신분고지 여부)"],["중개보수 등(Ⅲ)","중개보수, 실비, 산출내역"]]},{"종류":"표","제목":"확인·설명서 4종의 입지조건·관리 칸","머리":["칸","Ⅰ 주거용","Ⅱ 비주거용","Ⅲ 토지"],"행":[["입지조건","도로·대중교통·주차장·교육시설","도로·대중교통·주차장","도로·대중교통"],["관리에 관한 사항","경비실·관리주체·관리비","경비실·관리주체","없음"],["비선호시설(1km 이내)","있음","없음","있음"],["임대차 확인사항","있음","없음","없음"]]}],"함정":"입지조건은 기본 확인사항이고, 일조·소음·진동은 환경조건으로 세부 확인사항이다. 같은 '환경'이라는 말이 붙은 입지조건(도로·대중교통)과 헷갈린다.","개정":"별지 제20호서식은 2026.8.11 개정되었다. 현행 서식에서는 계약갱신요구권 행사 여부가 권리관계 칸에 있고, 권리관계에 신탁등기 여부·공동담보 여부 칸이, 관리비에 공동관리비 칸이 있다."}},{"i":"S5-2-1-중개사법-15","r":"S5","g":2,"c":2,"n":15,"s":"중개사법","q":"공인중개사법령상 확인·설명서와 거래계약서에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사는 중개대상물 확인·설명서를 원본, 사본 또는 전자문서의 형태로 5년간 보존해야 한다.","거래계약서에는 중개대상물 확인·설명서 교부일자를 기재해야 한다.","개업공인중개사는 거래계약서를 원본, 사본 또는 전자문서의 형태로 3년간 보존해야 한다.","개업공인중개사가 국토교통부장관이 정한 표준 거래계약서 서식을 사용하지 않으면 업무정지처분을 받는다.","중개대상물 확인·설명서에는 개업공인중개사만 서명 및 날인하면 되고, 해당 중개행위를 한 소속공인중개사는 서명 및 날인하지 않아도 된다."],"a":[2],"L":"중1-8","o":"변형","x":{"한줄":"거래계약서의 필수 기재사항에는 중개대상물 확인·설명서 교부일자가 들어간다.","근거":[{"법령":"공인중개사법 시행령","조문":"제22조제1항제8호","원문":"중개대상물확인ㆍ설명서 교부일자"},{"법령":"공인중개사법 시행령","조문":"제21조제4항","원문":"법 제25조제3항 본문에서 \"대통령령이 정하는 기간\"이란 3년을 말한다."},{"법령":"공인중개사법 시행령","조문":"제22조제2항·제3항","원문":"법 제26조제1항에서 \"대통령령이 정하는 기간\"이라 함은 5년을 말한다. / 국토교통부장관은 개업공인중개사가 작성하는 거래계약서의 표준이 되는 서식을 정하여 그 사용을 권장할 수 있다."},{"법령":"공인중개사법","조문":"제25조제4항","원문":"확인ㆍ설명서에는 개업공인중개사…가 서명 및 날인하되, 해당 중개행위를 한 소속공인중개사가 있는 경우에는 소속공인중개사가 함께 서명 및 날인하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"확인·설명서는 3년 보존한다(영 제21조제4항)."},{"번호":2,"판정":"옳음","설명":"교부일자는 거래계약서 필수 기재사항이다(영 제22조제1항제8호)."},{"번호":3,"판정":"틀림","설명":"거래계약서는 5년 보존한다(영 제22조제2항)."},{"번호":4,"판정":"틀림","설명":"표준서식은 권장일 뿐이어서 쓰지 않아도 처분 사유가 아니다(영 제22조제3항)."},{"번호":5,"판정":"틀림","설명":"해당 중개행위를 한 소속공인중개사가 함께 서명 및 날인해야 한다(법 제25조제4항)."}],"개념":[{"종류":"표","제목":"서식·보존기간","머리":["문서","서식","보존"],"행":[["일반중개계약서","표준서식 있음, 사용 권장","의무 없음"],["전속중개계약서","법정 서식(별지 제15호) 필수","3년"],["확인·설명서","법정 서식 4종 필수","3년"],["거래계약서","권장 근거만 있고 법정 서식 없음","5년"]]},{"종류":"표","제목":"거래계약서 필수 기재사항(영 제22조제1항)","머리":["호","사항"],"행":[["1","거래당사자의 인적 사항"],["2","물건의 표시"],["3","계약일"],["4","거래금액·계약금액 및 그 지급일자 등 지급에 관한 사항"],["5","물건의 인도일시"],["6","권리이전의 내용"],["7","계약의 조건이나 기한이 있는 경우 그 조건 또는 기한"],["8","중개대상물확인·설명서 교부일자"],["9","그 밖의 약정내용"]]}],"함정":"3년과 5년이 서로 맞바뀐 선지가 두 개(1, 3)다. 확인·설명서가 3년, 거래계약서가 5년이다. 선지 5는 서명 「및」 날인과 소속공인중개사의 동참을 모두 건드린다."}},{"i":"S5-2-1-중개사법-16","r":"S5","g":2,"c":2,"n":16,"s":"중개사법","q":"공인중개사법령상 개업공인중개사의 손해배상책임 보장에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["법인인 개업공인중개사가 분사무소를 두는 경우에는 4억원 이상의 보증을 설정하고, 분사무소마다 1억원 이상을 추가로 설정해야 한다.","개업공인중개사가 공탁한 공탁금은 폐업 또는 사망한 날부터 3년 이내에는 회수할 수 없다.","개업공인중개사가 보증보험금으로 손해배상을 한 때에는 15일 이내에 보증보험에 다시 가입해야 한다.","개업공인중개사는 중개가 완성된 때 거래당사자에게 보장금액, 보증기관과 그 소재지, 보장기간을 설명하고 관계 증서의 사본을 교부해야 한다.","이미 설정한 보증을 다른 보증으로 변경하려는 개업공인중개사는 기존 보증의 효력이 있는 기간 중에 다른 보증을 설정해야 한다."],"a":[1],"L":"중1-9","o":"변형","x":{"한줄":"법인은 4억원 이상이고 분사무소를 두면 분사무소마다 2억원 이상을 더한다.","근거":[{"법령":"공인중개사법 시행령","조문":"제24조제1항","원문":"1. 법인인 개업공인중개사 : 4억원 이상. 다만, 분사무소를 두는 경우에는 분사무소마다 2억원 이상을 추가로 설정해야 한다. 2. 법인이 아닌 개업공인중개사 : 2억원 이상"},{"법령":"공인중개사법","조문":"제30조제4항","원문":"제3항에 따라 공탁한 공탁금은 개업공인중개사가 폐업 또는 사망한 날부터 3년 이내에는 이를 회수할 수 없다."},{"법령":"공인중개사법 시행령","조문":"제26조제2항","원문":"개업공인중개사는 보증보험금ㆍ공제금 또는 공탁금으로 손해배상을 한 때에는 15일 이내에 보증보험 또는 공제에 다시 가입하거나 공탁금 중 부족하게 된 금액을 보전하여야 한다."},{"법령":"공인중개사법","조문":"제30조제5항","원문":"개업공인중개사는 중개가 완성된 때에는 거래당사자에게 손해배상책임의 보장에 관한 다음 각 호의 사항을 설명하고 관계 증서의 사본을 교부하거나 관계 증서에 관한 전자문서를 제공하여야 한다. 1. 보장금액 2. 보증보험회사, 공제사업을 행하는 자, 공탁기관 및 그 소재지 3. 보장기간"},{"법령":"공인중개사법 시행령","조문":"제25조제1항","원문":"보증을 설정한 개업공인중개사는 그 보증을 다른 보증으로 변경하고자 하는 경우에는 이미 설정한 보증의 효력이 있는 기간 중에 다른 보증을 설정하고 그 증명서류를 갖추어 등록관청에 신고하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"분사무소마다 추가하는 금액은 2억원 이상이다(영 제24조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"공탁금 회수 제한은 폐업·사망일부터 3년이다(법 제30조제4항)."},{"번호":3,"판정":"옳음","설명":"배상 뒤 15일 이내에 재가입하거나 보전한다(영 제26조제2항)."},{"번호":4,"판정":"옳음","설명":"보장 사항 설명과 증서 교부는 중개가 완성된 때 한다(법 제30조제5항)."},{"번호":5,"판정":"옳음","설명":"변경은 기존 보증 효력 기간 중에 새 보증을 설정한다(영 제25조제1항)."}],"개념":[{"종류":"표","제목":"손해배상책임 보장의 수치","머리":["항목","내용"],"행":[["설정 시기","중개사무소 개설등록 후 업무를 개시하기 전, 증명서류를 갖춰 등록관청에 신고(영 제24조제2항)"],["보장금액","법인 4억원 이상(분사무소마다 2억원 추가), 법인 아닌 개업공인중개사 2억원 이상"],["다른 법률로 중개업을 하는 자","2천만원 이상(영 제24조제3항)"],["보증 변경","기존 보증 효력 기간 중에 새 보증 설정"],["보증기간 만료","만료일까지 다시 설정(영 제25조제2항)"],["배상 후 재가입·보전","15일 이내"],["공탁금 회수","폐업·사망일부터 3년 후"],["보장 설명·증서 교부","중개 완성 때, 어기면 100만원 이하 과태료"],["보증 없이 업무 개시","등록취소 가능(법 제38조제2항제8호)"]]},{"종류":"흐름","제목":"보증 설정부터 배상까지","단계":[{"이름":"보증 설정","설명":"업무 개시 전에 보증보험·공제 가입 또는 공탁 후 등록관청에 신고(보증기관이 직접 통보하면 생략)"},{"이름":"중개 완성 시 설명","설명":"보장금액, 보증기관·소재지, 보장기간을 설명하고 증서 사본 교부"},{"이름":"청구","설명":"의뢰인이 손해배상합의서·화해조서·확정판결 사본 등을 첨부해 보증기관에 지급 청구(영 제26조제1항)"},{"이름":"지급","설명":"보증기관이 보증보험금·공제금·공탁금으로 지급"},{"이름":"재가입·보전","설명":"배상한 때부터 15일 이내에 보증보험·공제에 다시 가입하거나 공탁금 부족액을 보전"}]}],"함정":"숫자 하나만 바꾼 선지가 정답이다. 분사무소 추가분은 2억원이고, 재가입은 15일, 공탁금 회수 제한은 3년이다.","개정":"영 제24조제1항은 2021.12.31 개정을 거쳤다. 현행 보장금액은 법인 4억원 이상(분사무소마다 2억원 추가), 법인 아닌 개업공인중개사 2억원 이상이다. 분사무소 추가분을 1억원으로 본 옛 기출 해설은 현행과 다르다."}},{"i":"S5-2-1-중개사법-17","r":"S5","g":2,"c":2,"n":17,"s":"중개사법","q":"공인중개사법령상 계약금등의 반환채무이행 보장 및 손해배상책임에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사는 거래의 안전을 위해 필요하다고 인정하면 계약금·중도금·잔금을 예치하도록 거래당사자에게 권고할 수 있다.","계약금등의 예치명의자가 될 수 있는 자에는 공제사업을 하는 자와 계약금등 및 계약 관련서류를 관리하는 업무를 수행하는 전문회사가 포함된다.","개업공인중개사가 계약금등을 자기 명의로 예치하는 경우 자기 소유의 예치금과 분리하여 관리해야 하며, 거래당사자의 동의 없이 인출해서는 안 된다.","개업공인중개사가 자기의 중개사무소를 다른 사람의 중개행위의 장소로 제공하여 거래당사자에게 재산상 손해가 발생한 경우 그 손해를 배상할 책임이 있다.","법에 따른 개업공인중개사의 손해배상책임은 거래당사자의 재산상 손해뿐 아니라 정신적 손해에도 미치므로, 보증보험금으로 위자료도 지급받을 수 있다."],"a":[5],"L":"중1-9","o":"변형","x":{"한줄":"법이 정한 손해배상책임과 그 보장 대상은 거래당사자의 재산상 손해다.","근거":[{"법령":"공인중개사법","조문":"제30조제1항","원문":"개업공인중개사는 중개행위를 하는 경우 고의 또는 과실로 인하여 거래당사자에게 재산상의 손해를 발생하게 한 때에는 그 손해를 배상할 책임이 있다."},{"법령":"공인중개사법","조문":"제30조제2항","원문":"개업공인중개사는 자기의 중개사무소를 다른 사람의 중개행위의 장소로 제공함으로써 거래당사자에게 재산상의 손해를 발생하게 한 때에는 그 손해를 배상할 책임이 있다."},{"법령":"공인중개사법","조문":"제31조제1항","원문":"개업공인중개사는 거래의 안전을 보장하기 위하여 필요하다고 인정하는 경우에는 거래계약의 이행이 완료될 때까지 계약금ㆍ중도금 또는 잔금…을 개업공인중개사 또는 대통령령으로 정하는 자의 명의로 금융기관, 제42조에 따라 공제사업을 하는 자 또는 「자본시장과 금융투자업에 관한 법률」에 따른 신탁업자 등에 예치하도록 거래당사자에게 권고할 수 있다."},{"법령":"공인중개사법 시행령","조문":"제27조제1항제5호·제6호","원문":"5. 법 제42조의 규정에 따라 공제사업을 하는 자 6. 부동산 거래계약의 이행을 보장하기 위하여 계약금ㆍ중도금 또는 잔금…및 계약 관련서류를 관리하는 업무를 수행하는 전문회사"},{"법령":"공인중개사법 시행령","조문":"제27조제3항","원문":"개업공인중개사는 …거래계약과 관련된 계약금등을 자기 명의로 금융기관 등에 예치하는 경우에는 자기 소유의 예치금과 분리하여 관리될 수 있도록 하여야 하며, 예치된 계약금등은 거래당사자의 동의 없이 인출하여서는 아니 된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"예치는 권고할 수 있는 임의 사항이다(법 제31조제1항)."},{"번호":2,"판정":"옳음","설명":"공제사업자와 전문회사 모두 예치명의자가 될 수 있다(영 제27조제1항제5호·제6호)."},{"번호":3,"판정":"옳음","설명":"분리 관리와 동의 없는 인출 금지가 의무다(영 제27조제3항)."},{"번호":4,"판정":"옳음","설명":"장소 제공으로 재산상 손해가 나면 개업공인중개사가 배상한다(법 제30조제2항)."},{"번호":5,"판정":"틀림","설명":"법 제30조는 재산상 손해만 규정한다. 정신적 손해는 보장 대상이 아니다."}],"개념":[{"종류":"표","제목":"계약금등 예치제도","머리":["항목","내용"],"행":[["성격","개업공인중개사가 거래당사자에게 권고할 수 있는 임의 제도(법 제31조제1항)"],["예치 대상","계약금·중도금·잔금"],["예치명의자","개업공인중개사, 은행, 보험회사, 신탁업자, 체신관서, 공제사업을 하는 자, 계약금등·계약 관련서류 관리 전문회사(영 제27조제1항)"],["자기 명의 예치 시","자기 예치금과 분리 관리, 동의 없는 인출 금지, 예치금액만큼 보증보험·공제·공탁 + 증서 사본 교부(영 제27조제3항·제4항)"],["매도인의 선수령","반환을 보장하는 금융기관·보증보험 보증서를 예치명의자에게 교부하면 계약금등을 미리 수령(법 제31조제2항)"],["실비","반환채무이행 보장에 소요된 실비는 권리를 취득하려는 의뢰인(매수인·임차인)에게 청구(규칙 제20조제2항)"]]},{"종류":"비교","제목":"손해배상책임의 두 유형","왼쪽":{"이름":"중개행위로 인한 책임(법 제30조제1항)","항목":["중개행위 중 고의 또는 과실","거래당사자에게 재산상 손해 발생","개업공인중개사등의 행위는 개업공인중개사의 행위로 봄(법 제15조제2항)"]},"오른쪽":{"이름":"장소 제공 책임(법 제30조제2항)","항목":["자기 사무소를 다른 사람의 중개행위 장소로 제공","그로 인해 재산상 손해 발생","고용인 아닌 제3자의 중개행위에도 개업공인중개사가 책임"]}}],"함정":"선지 5처럼 보장 범위를 넓히는 문장이 정답 후보다. 법 제30조는 두 항 모두 재산상 손해라고 못 박았다. 정신적 손해는 민법에 따라 따로 청구한다."}},{"i":"S5-2-1-중개사법-18","r":"S5","g":2,"c":2,"n":18,"s":"중개사법","q":"乙이 개업공인중개사 甲에게 중개를 의뢰하여 거래계약이 체결된 경우 공인중개사법령상 중개보수에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲의 고의 또는 과실로 乙과 상대방 사이의 거래행위가 무효가 된 경우 甲은 중개보수를 받을 수 없다.","법정 한도를 초과하는 甲과 乙의 중개보수 약정은 그 초과하는 부분만 무효이다.","건축법령상 오피스텔로서 전용면적 85㎡ 이하이고 상·하수도 시설이 갖추어진 전용입식 부엌, 전용수세식 화장실 및 목욕시설을 갖춘 경우, 임대차 중개보수의 상한요율은 거래금액의 1천분의 4이다.","동일한 중개대상물에 대하여 동일 당사자 간에 매매와 임대차가 동일한 기회에 이루어진 경우, 매매와 임대차 각각의 거래금액에 요율을 적용하여 합산한다.","교환계약의 경우 교환대상 중개대상물 중 거래금액이 큰 중개대상물의 가액을 거래금액으로 한다."],"a":[4],"L":"중1-10","o":"변형","x":{"한줄":"같은 물건·같은 당사자 사이에서 같은 기회에 매매와 임대차가 이루어지면 매매계약의 거래금액만으로 보수를 계산한다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제20조제5항","원문":"제1항 및 제4항의 경우 거래금액의 계산은 다음 각 호에 따른다. 1. 임대차 중 보증금 외에 차임이 있는 경우에는 월 단위의 차임액에 100을 곱한 금액을 보증금에 합산한 금액을 거래금액으로 한다. 다만, 본문의 규정에 따라 합산한 금액이 5천만원 미만인 경우에는 …월 단위의 차임액에 70을 곱한 금액과 보증금을 합산한 금액을 거래금액으로 한다. 2. 교환계약의 경우에는 교환대상 중개대상물 중 거래금액이 큰 중개대상물의 가액을 거래금액으로 한다. 3. 동일한 중개대상물에 대하여 동일 당사자간에 매매를 포함한 둘 이상의 거래가 동일 기회에 이루어지는 경우에는 매매계약에 관한 거래금액만을 적용한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제4항제1호","원문":"「건축법 시행령」 별표 1 제14호나목2)에 따른 오피스텔(다음 각 목의 요건을 모두 갖춘 경우에 한정한다): 중개의뢰인 쌍방으로부터 각각 받되, 별표 2의 상한요율 이내에서 …결정한다. 가. 전용면적이 85제곱미터 이하일 것 나. 상ㆍ하수도 시설이 갖추어진 전용입식 부엌, 전용수세식 화장실 및 목욕시설…을 갖출 것"},{"법령":"공인중개사법","조문":"제32조제1항","원문":"개업공인중개사는 중개업무에 관하여 중개의뢰인으로부터 소정의 보수를 받는다. 다만, 개업공인중개사의 고의 또는 과실로 인하여 중개의뢰인간의 거래행위가 무효ㆍ취소 또는 해제된 경우에는 그러하지 아니하다."},{"판례":"한도 초과 약정(판례)","요지":"법정 한도를 초과하는 중개보수 약정은 강행규정 위반이어서 초과하는 부분만 무효이고, 한도 안쪽 부분은 유효하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"중개사의 고의·과실로 거래행위가 무효·취소·해제되면 보수를 받지 못한다(법 제32조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"한도를 넘는 부분만 무효다(판례)."},{"번호":3,"판정":"옳음","설명":"요건을 갖춘 오피스텔은 별표 2에 따라 매매·교환 1천분의 5, 임대차 등 1천분의 4가 상한이다(규칙 제20조제4항제1호, 별표 2)."},{"번호":4,"판정":"틀림","설명":"이 경우에는 매매계약에 관한 거래금액만 적용한다(규칙 제20조제5항제3호)."},{"번호":5,"판정":"옳음","설명":"교환은 가액이 큰 물건 하나를 거래금액으로 본다(규칙 제20조제5항제2호)."}],"개념":[{"종류":"계산","제목":"월 차임이 있는 임대차의 거래금액과 보수(주택, 보증금 1천만원 · 월 차임 30만원)","단계":[{"설명":"환산 공식(월 차임 × 100 + 보증금)","식":"30만원 × 100 + 1,000만원","값":"4,000만원"},{"설명":"5천만원 미만이므로 70배로 다시 계산","식":"30만원 × 70 + 1,000만원","값":"3,100만원"},{"설명":"주택 임대차 5천만원 미만 구간(상한요율 1천분의 5, 한도액 20만원)","식":"3,100만원 × 5/1,000","값":"15만5천원"},{"설명":"한도액과 비교","식":"15만5천원 < 20만원","값":"한도 안이므로 15만5천원이 상한"}]},{"종류":"표","제목":"거래금액 계산 규칙(규칙 제20조제5항)","머리":["경우","거래금액"],"행":[["보증금 + 월 차임","월 차임 × 100 + 보증금. 합계가 5천만원 미만이면 월 차임 × 70 + 보증금"],["교환","교환대상 중 가액이 큰 물건의 가액"],["동일 기회 복수 거래","같은 물건·같은 당사자의 매매 포함 둘 이상 거래는 매매 거래금액만"],["분양권 매매(판례)","총 분양대금이 아니라 이미 낸 계약금·중도금에 프리미엄을 더한 금액"],["주택·주택 외가 섞인 건축물","주택 면적이 2분의 1 이상이면 주택 규정, 미만이면 주택 외 규정(규칙 제20조제6항)"]]}],"함정":"선지 4는 동일 기회 거래의 합산 여부를 거꾸로 썼다. 합산하지 않고 매매 하나만 쓴다. 월 차임 환산에서 70을 곱하는 경우(합계 5천만원 미만)도 자주 틀린다.","개정":"규칙 제20조제4항은 2026.8.11 개정되어 있다. 현행 오피스텔 특례 요건은 전용면적 85㎡ 이하, 상·하수도 시설이 갖추어진 전용입식 부엌, 전용수세식 화장실 및 목욕시설을 모두 갖추는 것이다."}},{"i":"S5-2-1-중개사법-19","r":"S5","g":2,"c":2,"n":19,"s":"중개사법","q":"공인중개사법령상 중개보수 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사의 중개업무상 과실로 인하여 중개의뢰인간의 거래행위가 무효가 된 경우 개업공인중개사는 중개의뢰인으로부터 소정의 보수를 받을 수 없다.","주택의 중개에 대한 보수는 중개의뢰인 쌍방으로부터 각각 받되, 그 금액은 시ㆍ도의 조례로 정하는 요율한도 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다.","중개보수의 지급시기는 개업공인중개사와 중개의뢰인간의 약정에 따르되, 약정이 없을 때에는 중개대상물의 거래대금 지급이 완료된 날로 한다.","중개대상물인 주택의 소재지와 중개사무소의 소재지가 다른 경우 중개보수는 중개대상물의 소재지를 관할하는 시ㆍ도의 조례에서 정한 기준에 따라야 한다.","개업공인중개사는 중개의뢰인으로부터 중개대상물의 권리관계 등의 확인에 소요되는 실비를 받을 수 있다."],"a":[4],"L":"중1-10","o":"기출","x":{"한줄":"주택 소재지와 사무소 소재지가 다르면 중개사무소 소재지를 관할하는 시·도의 조례를 따른다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제20조제3항","원문":"제1항 및 제2항의 경우에 중개대상물의 소재지와 중개사무소의 소재지가 다른 경우에는 개업공인중개사는 중개사무소의 소재지를 관할하는 시ㆍ도의 조례에서 정한 기준에 따라 중개보수 및 실비를 받아야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제1항","원문":"법 제32조제4항에 따른 주택의 중개에 대한 보수는 중개의뢰인 쌍방으로부터 각각 받되, 그 일방으로부터 받을 수 있는 한도는 별표 1과 같으며, 그 금액은 법 제32조제4항에 따라 시ㆍ도의 조례로 정하는 요율한도 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다."},{"법령":"공인중개사법 시행령","조문":"제27조의2","원문":"법 제32조제3항에 따른 중개보수의 지급시기는 개업공인중개사와 중개의뢰인간의 약정에 따르되, 약정이 없을 때에는 중개대상물의 거래대금 지급이 완료된 날로 한다."},{"법령":"공인중개사법","조문":"제32조제2항","원문":"개업공인중개사는 중개의뢰인으로부터 제25조제1항에 따른 중개대상물의 권리관계 등의 확인 또는 제31조에 따른 계약금등의 반환채무이행 보장에 소요되는 실비를 받을 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사의 과실로 거래행위가 무효가 되면 보수를 받지 못한다(법 제32조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"주택 보수는 쌍방에게 각각 받고 조례의 요율한도 안에서 협의한다(규칙 제20조제1항)."},{"번호":3,"판정":"옳음","설명":"약정이 없으면 거래대금 지급이 완료된 날이다(영 제27조의2)."},{"번호":4,"판정":"틀림","설명":"중개사무소 소재지 시·도의 조례를 따른다(규칙 제20조제3항)."},{"번호":5,"판정":"옳음","설명":"권리관계 확인 실비는 받을 수 있다(법 제32조제2항)."}],"개념":[{"종류":"표","제목":"주택 중개보수 상한요율(규칙 별표 1)","머리":["거래내용","거래금액","상한요율","한도액"],"행":[["매매·교환","5천만원 미만","1천분의 6","25만원"],["매매·교환","5천만원 이상 2억원 미만","1천분의 5","80만원"],["매매·교환","2억원 이상 9억원 미만","1천분의 4","-"],["매매·교환","9억원 이상 12억원 미만","1천분의 5","-"],["매매·교환","12억원 이상 15억원 미만","1천분의 6","-"],["매매·교환","15억원 이상","1천분의 7","-"],["임대차 등","5천만원 미만","1천분의 5","20만원"],["임대차 등","5천만원 이상 1억원 미만","1천분의 4","30만원"],["임대차 등","1억원 이상 6억원 미만","1천분의 3","-"],["임대차 등","6억원 이상 12억원 미만","1천분의 4","-"],["임대차 등","12억원 이상 15억원 미만","1천분의 5","-"],["임대차 등","15억원 이상","1천분의 6","-"]]},{"종류":"표","제목":"중개대상물별 보수 규정","머리":["구분","정하는 법령","상한"],"행":[["주택(부속토지 포함)","국토교통부령 범위 안에서 시·도 조례. 사무소 소재지 시·도 조례 적용","규칙 별표 1의 요율·한도액"],["요건을 갖춘 오피스텔","국토교통부령(규칙 별표 2)","매매·교환 1천분의 5, 임대차 등 1천분의 4"],["그 밖의 주택 외 중개대상물","국토교통부령","거래금액의 1천분의 9 이내에서 협의, 사무소 요율표에 자기 상한 명시"],["실비","주택의 실비 한도는 조례(법 제32조제4항). 권리관계 확인 실비는 권리를 넘기는 쪽, 반환채무이행 보장 실비는 권리를 얻는 쪽에 청구","영수증 첨부"]]}],"함정":"선지 4는 주택 소재지를 기준으로 삼았다. 주택 보수와 실비는 중개사무소 소재지 시·도 조례가 기준이고, 주택 외 물건의 보수는 조례가 아니라 국토교통부령이다.","개정":"주택 중개보수는 규칙 제20조제1항·별표 1(신설 2021.10.19)의 상한요율과 한도액 안에서 시·도 조례가 정한다. 임대차 등을 1천분의 8 이내에서 조례로 정한다고 본 옛 기출 해설은 현행과 다르다."}},{"i":"S5-2-1-중개사법-20","r":"S5","g":2,"c":2,"n":20,"s":"중개사법","q":"공인중개사법령상 포상금을 지급받을 수 있는 신고 또는 고발의 대상이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["중개사무소의 개설등록을 하지 않고 중개업을 한 자","부정한 방법으로 중개사무소의 개설등록을 한 자","공인중개사자격증을 다른 사람으로부터 양수받은 자","개업공인중개사로서 부당한 이익을 얻을 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 중개대상물의 시세에 부당한 영향을 줄 우려가 있는 행위를 한 자","개업공인중개사로서 중개의뢰인과 직접 거래를 한 자"],"a":[5],"L":"중1-11","o":"기출","x":{"한줄":"직접거래는 법 제33조제1항제6호이고, 포상금 대상은 그중 제8호·제9호뿐이다.","근거":[{"법령":"공인중개사법","조문":"제46조제1항","원문":"등록관청은 다음 각 호의 어느 하나에 해당하는 자를 등록관청, 수사기관이나 제47조의2에 따른 부동산거래질서교란행위 신고센터에 신고 또는 고발한 자에 대하여 대통령령으로 정하는 바에 따라 포상금을 지급할 수 있다. 1. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자 2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 자 3. 중개사무소등록증 또는 공인중개사자격증을 다른 사람에게 양도ㆍ대여하거나 다른 사람으로부터 양수ㆍ대여받은 자 4. 제18조의2제3항을 위반하여 표시ㆍ광고를 한 자 5. 제33조제1항제8호 또는 제9호에 따른 행위를 한 자 6. 제33조제2항을 위반하여 개업공인중개사등의 업무를 방해한 자"},{"법령":"공인중개사법 시행령","조문":"제36조의2제1항·제2항","원문":"포상금은 1건당 50만원으로 한다. / 포상금은 …행정기관에 의하여 발각되기 전에 등록관청이나 수사기관에 신고 또는 고발한 자에게 그 신고 또는 고발사건에 대하여 검사가 공소제기 또는 기소유예의 결정을 한 경우에 한하여 지급한다."}],"선지":[{"번호":1,"판정":"-","설명":"무등록 중개업자는 대상이다(법 제46조제1항제1호)."},{"번호":2,"판정":"-","설명":"부정 등록자는 대상이다(법 제46조제1항제2호)."},{"번호":3,"판정":"-","설명":"자격증을 양수·대여받은 자는 대상이다(법 제46조제1항제3호)."},{"번호":4,"판정":"-","설명":"시세교란 행위(법 제33조제1항제8호)는 대상이다(법 제46조제1항제5호)."},{"번호":5,"판정":"-","설명":"직접거래(법 제33조제1항제6호)는 대상이 아니다."}],"개념":[{"종류":"표","제목":"포상금 지급 대상(법 제46조제1항)","머리":["호","대상","해당 벌칙"],"행":[["1","무등록 중개업","3년 이하 징역·3천만원 이하 벌금"],["2","거짓·부정한 방법의 개설등록","3년 이하 징역·3천만원 이하 벌금"],["3","등록증·자격증 양도·대여, 양수·대여받은 자","1년 이하 징역·1천만원 이하 벌금"],["4","개업공인중개사가 아닌 자의 표시·광고","1년 이하 징역·1천만원 이하 벌금"],["5","시세교란(법 제33조제1항제8호), 단체 구성 공동중개 제한(제9호)","3년 이하 징역·3천만원 이하 벌금"],["6","누구든지 하는 업무방해(법 제33조제2항)","3년 이하 징역·3천만원 이하 벌금"]]},{"종류":"흐름","제목":"포상금 지급","단계":[{"이름":"신고·고발","설명":"행정기관에 발각되기 전에 등록관청·수사기관·신고센터에 신고 또는 고발"},{"이름":"검사의 처분","설명":"검사가 공소제기 또는 기소유예를 결정한 경우에만 지급 대상(무혐의면 제외, 공소제기 후 무죄가 나와도 지급)"},{"이름":"신청","설명":"포상금지급신청서를 등록관청에 제출(규칙 제28조제1항)"},{"이름":"지급 결정","설명":"수사기관의 처분내용을 조회한 뒤 지급 결정"},{"이름":"지급","설명":"결정일부터 1개월 이내, 1건당 50만원. 공동 신고는 균등 배분(합의가 있으면 합의대로), 중복 신고는 최초 신고자. 비용은 국고에서 100분의 50 이내 보조 가능"}]}],"함정":"금지행위가 모두 포상금 대상은 아니다. 제33조제1항 중 포상금이 걸린 것은 제8호·제9호이고, 직접거래·쌍방대리·매매업·초과보수는 제외다."}},{"i":"S5-2-1-중개사법-21","r":"S5","g":2,"c":2,"n":21,"s":"중개사법","q":"공인중개사법령상 “한국공인중개사협회”(이하 ‘협회’라 함)에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["협회가 정관을 제정하거나 변경하려는 경우에는 시·도지사의 인가를 받아야 한다.","협회는 총회의 의결내용을 지체 없이 국토교통부장관에게 보고하여야 한다.","협회가 시·도회를 설치한 때에는 그 시·도회는 등록관청에 신고하여야 한다.","협회가 하는 공제사업은 영리사업으로서 회원간의 상호부조를 목적으로 한다.","협회에 관하여 이 법에 규정된 것 외에는 「상법」 중 회사에 관한 규정을 적용한다."],"a":[2],"L":"중1-12","o":"변형","x":{"한줄":"총회 의결내용은 지체 없이 국토교통부장관에게 보고한다(법 제41조의2제3항).","근거":[{"법령":"공인중개사법","조문":"제41조제2항·제4항","원문":"②협회는 법인으로 하며, 정관을 제정하거나 변경하려는 경우에는 국토교통부장관의 인가를 받아야 한다.\n④협회는 정관으로 정하는 바에 따라 주사무소에 두는 중앙회를 설치하고, 시ㆍ도에 시ㆍ도회를, 시(구가 설치되지 아니한 시와 특별자치도의 행정시를 말한다)ㆍ군ㆍ구에 지회를 둘 수 있다."},{"법령":"공인중개사법","조문":"제41조의2제3항","원문":"③ 협회는 총회의 의결내용을 지체 없이 국토교통부장관에게 보고하여야 한다. 이 경우 다음 각 호의 사항은 총회의 의결을 거쳐야 한다.\n1. 정관의 제정과 변경\n2. 예산과 결산\n3. 그 밖에 정관으로 정하는 사항"},{"법령":"공인중개사법 시행령","조문":"제32조제2항","원문":"②협회가 그 시ㆍ도회 또는 지회를 설치할 때에는 그 시ㆍ도회는 시ㆍ도지사에게, 지회는 등록관청에 신고하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제31조제6호","원문":"협회는 법 제41조제1항의 규정에 따른 목적을 달성하기 위하여 다음 각 호의 업무를 수행할 수 있다.\n6. 법 제42조의 규정에 따른 공제사업. 이 경우 공제사업은 비영리사업으로서 회원간의 상호부조를 목적으로 한다."},{"법령":"공인중개사법","조문":"제43조","원문":"협회에 관하여 이 법에 규정된 것 외에는 「민법」중 사단법인에 관한 규정을 적용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"정관의 제정·변경은 국토교통부장관의 인가를 받는다(법 제41조제2항)."},{"번호":2,"판정":"옳음","설명":"총회의 의결내용은 지체 없이 국토교통부장관에게 보고한다. 시·도지사나 등록관청에 보고하거나 등기하라는 규정은 없다(법 제41조의2제3항)."},{"번호":3,"판정":"틀림","설명":"시·도회는 시·도지사에게, 지회는 등록관청에 신고한다(영 제32조제2항)."},{"번호":4,"판정":"틀림","설명":"공제사업은 비영리사업이고 목적이 회원 간 상호부조다(영 제31조제6호)."},{"번호":5,"판정":"틀림","설명":"협회에는 「민법」 중 사단법인 규정을 적용한다(법 제43조)."}],"개념":[{"종류":"표","제목":"협회가 거쳐야 하는 인가·승인·보고·신고","머리":["사항","상대와 방식","근거"],"행":[["정관 제정·변경","국토교통부장관의 인가","법 제41조제2항"],["총회 의결내용","지체 없이 국토교통부장관에게 보고","법 제41조의2제3항"],["시·도회 설치","시·도지사에게 신고","영 제32조제2항"],["지회 설치","등록관청에 신고","영 제32조제2항"],["공제규정 제정·변경","국토교통부장관의 승인","법 제42조제2항"],["책임준비금을 다른 용도로 사용","국토교통부장관의 승인","법 제42조제4항"]]},{"종류":"표","제목":"협회가 할 수 있는 업무(영 제31조)","머리":["구분","내용"],"행":[["회원 관련","회원의 품위유지, 자질향상을 위한 지도·교육·연수, 윤리헌장 제정과 실천"],["제도 관련","부동산중개제도의 연구·개선"],["정보 관련","부동산 정보제공"],["공제사업","비영리사업, 목적은 회원 간 상호부조"],["그 밖","설립목적 달성에 필요한 업무"]]}],"함정":"보고 상대(국토교통부장관)와 신고 상대(시·도회는 시·도지사, 지회는 등록관청)를 서로 바꿔 넣은 선지가 반복된다. 공제사업을 영리사업으로 바꾸거나 「민법」 대신 「상법」을 넣은 문장도 같은 방식이다. 정관 인가권자는 시·도지사가 아니라 국토교통부장관이다.","개정":"2026.2.27 개정으로 협회는 법이 직접 설립하는 「한국공인중개사협회」가 되었다(법 제41조제1항). 설립인가와 창립총회를 정한 옛 제3항은 삭제되었다. 옛 기출의 「지부」는 2026.8.18 개정 영 제32조제2항에서 「시·도회」로 바뀌었다."}},{"i":"S5-2-1-중개사법-22","r":"S5","g":2,"c":2,"n":22,"s":"중개사법","q":"공인중개사법령상 공인중개사의 자격취소 및 자격정지에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시·도지사는 공인중개사의 자격취소처분을 한 때에는 5일 이내에 이를 국토교통부장관과 다른 시·도지사에게 통보하여야 한다.","자격취소처분을 받은 자는 처분을 받은 날부터 7일 이내에 공인중개사자격증을 교부한 시·도지사에게 반납하여야 한다.","소속공인중개사가 거래계약서에 서명 및 날인을 하지 아니한 경우 시·도지사는 그 자격을 취소하여야 한다.","시·도지사는 위반행위의 동기·결과 및 횟수 등을 참작하여 자격정지기간의 2분의 1의 범위에서 가중할 수 있으나, 가중하여 처분하는 때에도 자격정지기간은 6월을 초과할 수 없다.","시·도지사는 공인중개사의 자격을 취소하고자 하는 경우에는 청문을 실시하여야 한다."],"a":[3],"L":"중1-13","o":"변형","x":{"한줄":"거래계약서에 서명 및 날인을 하지 않은 소속공인중개사는 자격취소가 아니라 6개월 범위의 자격정지 대상이다(법 제36조제1항제5호).","근거":[{"법령":"공인중개사법 시행령","조문":"제29조제3항","원문":"③시ㆍ도지사는 공인중개사의 자격취소처분을 한 때에는 5일 이내에 이를 국토교통부장관과 다른 시ㆍ도지사에게 통보해야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제21조","원문":"법 제35조제3항의 규정에 따라 공인중개사자격증을 반납하고자 하는 자는 자격취소처분을 받은 날부터 7일 이내에 그 공인중개사자격증을 교부한 시ㆍ도지사에게 공인중개사자격증을 반납하여야 한다."},{"법령":"공인중개사법","조문":"제36조제1항제5호","원문":"①시ㆍ도지사는 공인중개사가 소속공인중개사로서 업무를 수행하는 기간 중에 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 그 자격을 정지할 수 있다.\n5. 제26조제2항의 규정을 위반하여 거래계약서에 서명 및 날인을 하지 아니한 경우"},{"법령":"공인중개사법 시행규칙","조문":"제22조제2항","원문":"②시ㆍ도지사는 위반행위의 동기ㆍ결과 및 횟수 등을 참작하여 제1항의 규정에 따른 자격정지기간의 2분의 1의 범위 안에서 가중 또는 감경할 수 있다. 이 경우 가중하여 처분하는 때에도 자격정지기간은 6월을 초과할 수 없다."},{"법령":"공인중개사법","조문":"제35조제2항","원문":"②시ㆍ도지사는 제1항에 따라 공인중개사의 자격을 취소하고자 하는 경우에는 청문을 실시하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"자격취소 후 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보한다(영 제29조제3항)."},{"번호":2,"판정":"옳음","설명":"반납 기한은 처분을 받은 날부터 7일이고, 반납처는 자격증을 교부한 시·도지사다(규칙 제21조)."},{"번호":3,"판정":"틀림","설명":"거래계약서 서명·날인 누락은 자격정지 사유이고 기준은 3개월이다(법 제36조제1항제5호, 규칙 별표 3)."},{"번호":4,"판정":"옳음","설명":"정지기간의 2분의 1 범위에서 가중하되 6월을 넘지 못한다(규칙 제22조제2항)."},{"번호":5,"판정":"옳음","설명":"자격취소는 청문을 거친다(법 제35조제2항)."}],"개념":[{"종류":"비교","제목":"자격취소와 자격정지","왼쪽":{"이름":"자격취소","항목":["시·도지사가 반드시 취소한다(기속)","사유: 부정한 방법의 취득, 성명 사용·자격증 양도·대여, 정지기간 중 중개업무, 금고 이상 형 선고(집행유예 포함)","청문을 실시한다(법 제35조제2항)","5일 이내 국토교통부장관·다른 시·도지사에 통보, 7일 이내 자격증 반납"]},"오른쪽":{"이름":"자격정지","항목":["시·도지사가 6개월 범위에서 정지할 수 있다(재량)","소속공인중개사로 업무를 수행하는 기간의 일곱 가지 위반","법에 청문 규정이 없다","등록관청이 사유를 알게 되면 지체 없이 시·도지사에 통보한다(법 제36조제2항)"]}},{"종류":"표","제목":"자격정지 기준(규칙 별표 3)","머리":["위반행위","기준"],"행":[["2 이상 중개사무소에 소속","6월"],["인장등록 안 함·미등록 인장 사용","3월"],["확인·설명 불성실, 근거자료 미제시","3월"],["확인·설명서 서명·날인 누락","3월"],["거래계약서 서명·날인 누락","3월"],["거래계약서 거짓 기재, 이중계약서","6월"],["금지행위","6월"]]}],"함정":"서명·날인 누락이라는 말만 보고 중한 처분을 고르기 쉽다. 이 법에서 자격취소는 네 가지 사유뿐이고, 서명·날인, 인장, 확인·설명, 이중소속은 모두 자격정지다. 숫자 선지도 5일(통보)과 7일(반납)을 맞바꿔 낸다."}},{"i":"S5-2-1-중개사법-23","r":"S5","g":2,"c":2,"n":23,"s":"중개사법","q":"공인중개사법령상 공인중개사인 개업공인중개사의 중개사무소 개설등록 취소 사유에 해당하지 않는 경우는?","b":null,"bs":"없음","img":[],"ch":["중개대상물 확인ㆍ설명서를 교부하지 아니한 경우","거짓으로 중개사무소의 개설등록을 한 경우","업무정지기간 중에 중개업무를 한 경우","공인중개사인 개업공인중개사가 개업공인중개사인 법인의 사원ㆍ임원이 된 경우","개업공인중개사가 사망한 경우"],"a":[1],"L":"중1-13","o":"기출","x":{"한줄":"확인·설명서 미교부는 개설등록 취소 사유가 아니라 업무정지 사유다(법 제39조제1항제6호).","근거":[{"법령":"공인중개사법","조문":"제38조제1항제1호·제2호·제5호·제7호","원문":"①등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소하여야 한다.\n1. 개인인 개업공인중개사가 사망하거나 개업공인중개사인 법인이 해산한 경우\n2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 경우\n5. 제12조제2항의 규정을 위반하여 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 된 경우\n7. 업무정지기간 중에 중개업무를 하거나 자격정지처분을 받은 소속공인중개사로 하여금 자격정지기간 중에 중개업무를 하게 한 경우"},{"법령":"공인중개사법","조문":"제39조제1항제6호","원문":"①등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 업무의 정지를 명할 수 있다. 이 경우 법인인 개업공인중개사에 대하여는 법인 또는 분사무소별로 업무의 정지를 명할 수 있다.\n6. 제25조제3항의 규정을 위반하여 중개대상물확인ㆍ설명서를 교부하지 아니하거나 보존하지 아니한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"취소 사유가 아니다. 확인·설명서를 교부하지 않거나 보존하지 않으면 업무정지를 할 수 있다(법 제39조제1항제6호)."},{"번호":2,"판정":"옳음","설명":"거짓이나 부정한 방법의 등록은 필요적 취소 사유다(법 제38조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"업무정지기간 중 중개업무는 필요적 취소 사유다(법 제38조제1항제7호)."},{"번호":4,"판정":"옳음","설명":"다른 개업공인중개사의 소속이 되거나 법인의 사원·임원이 되면 필요적 취소다(법 제38조제1항제5호, 제12조제2항)."},{"번호":5,"판정":"옳음","설명":"개인인 개업공인중개사의 사망은 필요적 취소 사유다(법 제38조제1항제1호)."}],"개념":[{"종류":"표","제목":"등록취소와 업무정지의 구분","머리":["위반행위","처분","근거"],"행":[["거짓·부정한 방법의 등록","등록취소(필요적)","법 제38조제1항제2호"],["업무정지기간 중 중개업무","등록취소(필요적)","법 제38조제1항제7호"],["다른 사무소의 소속 또는 법인의 사원·임원이 됨","등록취소(필요적)","법 제38조제1항제5호"],["개인 사망·법인 해산","등록취소(필요적)","법 제38조제1항제1호"],["확인·설명서 미교부·미보존","업무정지(임의)","법 제39조제1항제6호"],["확인·설명서 서명·날인 누락","업무정지(임의)","법 제39조제1항제7호"],["거래계약서 서명·날인 누락","업무정지(임의)","법 제39조제1항제9호"]]},{"종류":"비교","제목":"필요적 취소와 임의적 취소","왼쪽":{"이름":"필요적 취소(법 제38조제1항)","항목":["등록관청이 반드시 취소","사망·해산, 거짓 등록, 결격사유, 이중등록, 이중소속, 중개보조원 수 초과, 성명·상호 대여, 업무정지 중 업무, 1년 안 업무정지 2회 후 재위반","제1호를 뺀 나머지는 청문 후 취소"]},"오른쪽":{"이름":"임의적 취소(법 제38조제2항)","항목":["등록관청이 취소할 수 있다","등록기준 미달, 둘 이상 사무소, 임시 중개시설물, 겸업, 6개월 초과 휴업, 거래계약서 거짓 기재, 보증 없이 업무 개시, 금지행위 등","모두 청문 후 취소"]}}],"함정":"확인·설명서와 관련된 위반은 중한 처분으로 이어질 것 같지만 업무정지에 그친다. 선지 4는 개업공인중개사가 다른 법인의 사원·임원이 되는 것이라 이중소속에 해당해 필요적 취소다."}},{"i":"S5-2-1-중개사법-24","r":"S5","g":2,"c":2,"n":24,"s":"중개사법","q":"공인중개사법령상 행정제재처분효과의 승계 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["폐업신고 전에 개업공인중개사에게 한 업무정지처분의 효과는 그 처분일부터 1년간 재등록 개업공인중개사에게 승계된다.","폐업기간이 14개월인 재등록 개업공인중개사에게 폐업신고 전의 업무정지 사유에 해당하는 위반행위를 이유로 업무정지처분을 할 수 있다.","폐업기간이 3년 2개월인 재등록 개업공인중개사에게 폐업신고 전의 개설등록 취소사유에 해당하는 위반행위를 이유로 개설등록취소처분을 할 수 있다.","재등록 개업공인중개사에게 폐업신고 전의 위반행위를 이유로 행정처분을 하는 경우에는 폐업의 사유를 고려하지 않는다.","폐업신고 후 다시 개설등록을 한 개업공인중개사인 법인의 대표자에 관하여는 행정제재처분효과의 승계에 관한 규정을 준용하지 않는다."],"a":[1],"L":"중1-13","o":"변형","x":{"한줄":"폐업 전 업무정지처분의 효과는 처분일부터 1년간 재등록한 개업공인중개사에게 이어진다(법 제40조제2항).","근거":[{"법령":"공인중개사법","조문":"제40조제1항·제2항","원문":"①개업공인중개사가 제21조에 따른 폐업신고후 제9조에 따라 다시 중개사무소의 개설등록을 한 때에는 폐업신고 전의 개업공인중개사의 지위를 승계한다.\n②제1항의 경우 폐업신고 전의 개업공인중개사에 대하여 제39조제1항 각 호, 제51조제1항 각 호, 같은 조 제2항 각 호 및 같은 조 제3항 각 호의 위반행위를 사유로 행한 행정처분의 효과는 그 처분일부터 1년간 다시 중개사무소의 개설등록을 한 자(이하 이 조에서 \"재등록 개업공인중개사\"라 한다)에게 승계된다."},{"법령":"공인중개사법","조문":"제40조제3항","원문":"③제1항의 경우 재등록 개업공인중개사에 대하여 폐업신고 전의 제38조제1항 각 호, 같은 조 제2항 각 호 및 제39조제1항 각 호의 위반행위에 대한 행정처분을 할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우는 제외한다.\n1. 폐업신고를 한 날부터 다시 중개사무소의 개설등록을 한 날까지의 기간(이하 제2호에서 \"폐업기간\"이라 한다)이 3년을 초과한 경우\n2. 폐업신고 전의 위반행위에 대한 행정처분이 업무정지에 해당하는 경우로서 폐업기간이 1년을 초과한 경우"},{"법령":"공인중개사법","조문":"제40조제4항·제5항","원문":"④제3항에 따라 행정처분을 하는 경우에는 폐업기간과 폐업의 사유 등을 고려하여야 한다.\n⑤ 개업공인중개사인 법인의 대표자에 관하여는 제1항부터 제4항까지를 준용한다. 이 경우 \"개업공인중개사\"는 \"법인의 대표자\"로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"처분 효과의 승계 기간은 처분일부터 1년이다(법 제40조제2항)."},{"번호":2,"판정":"틀림","설명":"업무정지에 해당하는 위반행위는 폐업기간이 1년을 넘으면 처분할 수 없다. 14개월은 1년 초과다(법 제40조제3항제2호)."},{"번호":3,"판정":"틀림","설명":"폐업기간이 3년을 넘으면 어떤 처분도 할 수 없다. 3년 2개월은 3년 초과다(법 제40조제3항제1호)."},{"번호":4,"판정":"틀림","설명":"처분할 때는 폐업기간과 폐업의 사유 등을 고려하여야 한다(법 제40조제4항)."},{"번호":5,"판정":"틀림","설명":"법인의 대표자에게도 제1항부터 제4항까지를 준용하며, 이때 개업공인중개사는 법인의 대표자로 본다(법 제40조제5항)."}],"개념":[{"종류":"표","제목":"폐업 후 재등록 때 위반행위로 처분할 수 있는가","머리":["폐업 전 위반행위","폐업기간","처분"],"행":[["업무정지에 해당","1년 이하","업무정지 가능"],["업무정지에 해당","1년 초과","불가(제3항제2호)"],["등록취소에 해당","3년 이하","등록취소 가능"],["등록취소에 해당","3년 초과","불가(제3항제1호)"],["어떤 위반이든","3년 초과","어떤 처분도 불가"]]},{"종류":"흐름","제목":"폐업 후 재등록 때 적용 순서","단계":[{"이름":"폐업신고","설명":"법 제21조에 따른 폐업신고"},{"이름":"재등록","설명":"법 제9조에 따라 다시 개설등록을 하면 폐업신고 전 개업공인중개사의 지위를 승계(제1항)"},{"이름":"처분 효과 승계","설명":"폐업 전 업무정지·과태료 처분의 효과가 처분일부터 1년간 이어짐(제2항)"},{"이름":"위반행위 처분","설명":"폐업 전 위반행위를 이유로 처분 가능, 폐업기간 3년 초과 또는 업무정지 사유에 폐업기간 1년 초과면 불가(제3항)"},{"이름":"처분 때 고려","설명":"폐업기간과 폐업의 사유 등을 고려(제4항)"}]}],"함정":"1년과 3년이 서로 다른 곳에 쓰인다. 처분 효과의 승계는 처분일부터 1년, 위반행위 처분의 한도는 업무정지 사유 1년·등록취소 사유 3년의 폐업기간이다. 기간을 하나로 뭉뚱그려 외우면 선지 2·3에서 틀린다."}},{"i":"S5-2-1-중개사법-25","r":"S5","g":2,"c":2,"n":25,"s":"중개사법","q":"공인중개사법령상 벌칙 부과대상 행위 중 피해자의 명시한 의사에 반하여 벌하지 않는 경우는?","b":null,"bs":"없음","img":[],"ch":["거래정보사업자가 개업공인중개사로부터 의뢰받은 내용과 다르게 중개대상물의 정보를 부동산거래정보망에 공개한 경우","개업공인중개사가 그 업무상 알게 된 비밀을 누설한 경우","개업공인중개사가 중개의뢰인으로부터 법령으로 정한 보수를 초과하여 금품을 받은 경우","시세에 부당한 영향을 줄 목적으로 개업공인중개사에게 중개대상물을 시세보다 현저하게 높게 표시ㆍ광고하도록 강요하는 방법으로 개업공인중개사의 업무를 방해한 경우","개업공인중개사가 단체를 구성하여 단체 구성원 이외의 자와 공동중개를 제한한 경우"],"a":[2],"L":"중1-14","o":"기출","x":{"한줄":"업무상 비밀 누설만 피해자의 명시한 의사에 반하여 벌하지 않는다(법 제49조제2항).","근거":[{"법령":"공인중개사법","조문":"제49조제1항제8호·제9호·제10호, 제2항","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n8. 제24조제4항의 규정을 위반하여 정보를 공개한 자\n9. 제29조제2항의 규정을 위반하여 업무상 비밀을 누설한 자\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자\n②제29조제2항의 규정에 위반한 자는 피해자의 명시한 의사에 반하여 벌하지 아니한다."},{"법령":"공인중개사법","조문":"제48조제3호·제4호","원문":"다음 각 호의 어느 하나에 해당하는 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.\n3. 제33조제1항제5호부터 제9호까지의 규정을 위반한 자\n4. 제33조제2항 각 호의 규정을 위반한 자"},{"법령":"공인중개사법","조문":"제29조제2항","원문":"②개업공인중개사등은 이 법 및 다른 법률에 특별한 규정이 있는 경우를 제외하고는 그 업무상 알게 된 비밀을 누설하여서는 아니된다. 개업공인중개사등이 그 업무를 떠난 후에도 또한 같다."}],"선지":[{"번호":1,"판정":"틀림","설명":"부동산거래정보망 정보를 의뢰 내용과 다르게 공개하면 1년 이하 징역 또는 1천만원 이하 벌금이고 반의사불벌이 아니다(법 제49조제1항제8호)."},{"번호":2,"판정":"옳음","설명":"비밀 누설은 1년 이하 징역 또는 1천만원 이하 벌금이지만, 피해자의 명시한 의사에 반하여 벌하지 않는다(법 제49조제1항제9호·제2항)."},{"번호":3,"판정":"틀림","설명":"초과 보수 수수는 1년 이하 징역 또는 1천만원 이하 벌금이고 반의사불벌이 아니다(법 제49조제1항제10호, 제33조제1항제3호)."},{"번호":4,"판정":"틀림","설명":"시세 방해를 위한 표시·광고 강요는 3년 이하 징역 또는 3천만원 이하 벌금이다(법 제48조제4호, 제33조제2항제5호)."},{"번호":5,"판정":"틀림","설명":"단체를 구성한 공동중개 제한은 3년 이하 징역 또는 3천만원 이하 벌금이다(법 제48조제3호, 제33조제1항제9호)."}],"개념":[{"종류":"비교","제목":"3년 이하와 1년 이하의 구분","왼쪽":{"이름":"3년 이하 징역·3천만원 이하 벌금(법 제48조)","항목":["무등록 중개업","거짓·부정한 방법의 개설등록","금지행위 중 제33조제1항 제5호~제9호(분양권 증서 중개, 직접거래·쌍방대리, 투기 조장, 시세 조작, 공동중개 제한)","누구든 하는 업무방해(제33조제2항)"]},"오른쪽":{"이름":"1년 이하 징역·1천만원 이하 벌금(법 제49조)","항목":["자격증 대여·양수, 유사명칭 사용","이중등록·이중소속, 둘 이상 사무소, 임시 중개시설물","거래정보사업자의 부당한 정보공개","업무상 비밀 누설","금지행위 중 제33조제1항 제1호~제4호(매매업, 무등록자와 거래, 초과 보수, 거짓 언행)"]}},{"종류":"표","제목":"반의사불벌과 양벌규정","머리":["항목","내용","근거"],"행":[["반의사불벌","업무상 비밀 누설은 피해자의 명시한 의사에 반하여 벌하지 않음","법 제49조제2항"],["비밀유지 의무","업무를 떠난 후에도 지속","법 제29조제2항"],["양벌규정 대상","소속공인중개사, 중개보조원, 법인의 사원·임원이 중개업무에 관해 제48조·제49조 위반","법 제50조"],["양벌 효과","행위자를 벌하는 외에 개업공인중개사에게 해당 조의 벌금형(징역형은 없음)","법 제50조"],["면책","위반행위를 방지하기 위해 상당한 주의와 감독을 게을리하지 않은 경우","법 제50조 단서"]]}],"함정":"징역·벌금의 수준(3년 이하인가 1년 이하인가)만 구분하면 이 문제는 풀리지 않는다. 반의사불벌은 비밀 누설 하나뿐이다. 거래정보사업자의 정보 공개 위반과 초과 보수는 같은 1년 이하 징역이지만 반의사불벌이 아니다."}},{"i":"S5-2-1-중개사법-26","r":"S5","g":2,"c":2,"n":26,"s":"중개사법","q":"공인중개사법령상 과태료 부과 대상자에 해당하는 것은?","b":null,"bs":"없음","img":[],"ch":["다른 사람의 공인중개사자격증을 대여받은 자","중개사무소의 개설등록을 하지 아니하고 중개업을 한 자","공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자","개업공인중개사가 아닌 자로서 중개업을 하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자","개업공인중개사로서 중개대상물의 확인ㆍ설명의 의무를 이행하면서 설명의 근거자료를 제시하지 아니한 자"],"a":[5],"L":"중1-14","o":"기출","x":{"한줄":"설명의 근거자료를 제시하지 않은 개업공인중개사는 500만원 이하 과태료 대상이다(법 제51조제2항제1호의6).","근거":[{"법령":"공인중개사법","조문":"제51조제2항제1호의6","원문":"② 다음 각 호의 어느 하나에 해당하는 자에게는 500만원 이하의 과태료를 부과한다.\n1의6. 제25조제1항을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 자"},{"법령":"공인중개사법","조문":"제49조제1항제1호·제2호·제6호의2","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n6의2. 제18조의2제3항을 위반하여 개업공인중개사가 아닌 자로서 중개업을  하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자"},{"법령":"공인중개사법","조문":"제48조제1호","원문":"다음 각 호의 어느 하나에 해당하는 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.\n1. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"자격증을 대여받은 자는 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"무등록 중개업은 3년 이하 징역 또는 3천만원 이하 벌금이다(법 제48조제1호)."},{"번호":3,"판정":"틀림","설명":"유사명칭 사용은 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조제1항제2호)."},{"번호":4,"판정":"틀림","설명":"개업공인중개사가 아닌 자의 중개대상물 표시·광고는 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조제1항제6호의2)."},{"번호":5,"판정":"옳음","설명":"성실·정확한 확인·설명을 하지 않거나 근거자료를 제시하지 않으면 500만원 이하 과태료다(법 제51조제2항제1호의6)."}],"개념":[{"종류":"표","제목":"과태료 부과권자와 대상(법 제51조제5항)","머리":["부과권자","대표 대상","금액 구간"],"행":[["국토교통부장관","거래정보사업자의 운영규정 위반·감독명령 불응, 협회의 공시 누락·개선명령 불이행·검사 거부, 정보통신서비스 제공자의 자료 제출·조치 불이행","500만원 이하"],["시·도지사","연수교육 미이수(제51조제2항제5호의2), 자격증 미반납·사유서 미제출(제51조제3항제6호)","500만원 이하 / 100만원 이하"],["등록관청","부당한 표시·광고, 확인·설명 불성실·근거자료 미제시, 중개보조원 고지의무 위반","500만원 이하"],["등록관청","등록증 미게시, 명칭 문자 미사용, 이전·휴업·폐업 신고 누락, 손해배상책임 미설명, 등록증 미반납","100만원 이하"]]},{"종류":"비교","제목":"형벌이냐 과태료냐","왼쪽":{"이름":"형벌 대상","항목":["개업공인중개사가 아닌 자의 중개대상물 표시·광고","거짓 언행으로 중개의뢰인의 판단을 그르침","초과 보수 수수","자격증 대여·양수"]},"오른쪽":{"이름":"과태료 대상","항목":["개업공인중개사의 존재하지 않는 매물 표시·광고 등 부당한 표시·광고","확인·설명 불성실, 근거자료 미제시","광고에 명시사항을 누락한 표시·광고(100만원 이하)","연수교육 미이수"]}}],"함정":"같은 확인·설명 의무 위반이라도 소속공인중개사는 자격정지, 개업공인중개사는 과태료·업무정지로 처분이 갈린다. 광고도 개업공인중개사가 아닌 자가 하면 형벌, 개업공인중개사가 위반하면 과태료다."}},{"i":"S5-2-1-중개사법-27","r":"S5","g":2,"c":2,"n":27,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 부동산 거래신고의 대상이 되는 계약이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["「산업입지 및 개발에 관한 법률」에 따라 공급되는 토지에 대한 공급계약","「건축물의 분양에 관한 법률」에 따라 공급되는 건축물의 분양계약","「공공주택 특별법」에 따른 공급계약을 통하여 부동산을 공급받는 자로 선정된 지위의 매매계약","「도시 및 주거환경정비법」에 따른 관리처분계획의 인가로 취득한 입주자로 선정된 지위의 매매계약","「주택법」에 따라 공급받은 주택을 자녀에게 증여하는 계약"],"a":[5],"L":"중2-1","o":"변형","x":{"한줄":"신고 대상은 매매계약, 공급계약, 분양권·입주권 지위의 매매계약뿐이라 증여계약은 해당하지 않는다(법 제3조제1항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조제1항","원문":"① 거래당사자는 다음 각 호의 어느 하나에 해당하는 계약을 체결한 경우 그 실제 거래가격 등 대통령령으로 정하는 사항을 거래계약의 체결일부터 30일 이내에 그 권리의 대상인 부동산등(권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다)의 소재지를 관할하는 시장(구가 설치되지 아니한 시의 시장 및 특별자치시장과 특별자치도 행정시의 시장을 말한다)ㆍ군수 또는 구청장(이하 \"신고관청\"이라 한다)에게 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 국가, 지방자치단체, 대통령령으로 정하는 자의 경우(이하 \"국가등\"이라 한다)에는 국가등이 신고를 하여야 한다.\n1. 부동산의 매매계약\n2. 「택지개발촉진법」, 「주택법」 등 대통령령으로 정하는 법률에 따른 부동산에 대한 공급계약\n3. 다음 각 목의 어느 하나에 해당하는 지위의 매매계약\n가. 제2호에 따른 계약을 통하여 부동산을 공급받는 자로 선정된 지위\n나. 「도시 및 주거환경정비법」 제74조에 따른 관리처분계획의 인가 및 「빈집 및 소규모주택 정비에 관한 특례법」 제29조에 따른 사업시행계획인가로 취득한 입주자로 선정된 지위"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제3조제3항","원문":"③ 법 제3조제1항제2호에서 \"「택지개발촉진법」, 「주택법」 등 대통령령으로 정하는 법률\"이란 다음 각 호의 법률을 말한다.\n1. 「건축물의 분양에 관한 법률」\n2. 「공공주택 특별법」\n3. 「도시개발법」\n4. 「도시 및 주거환경정비법」\n4의2. 「빈집 및 소규모주택 정비에 관한 특례법」\n5. 「산업입지 및 개발에 관한 법률」\n6. 「주택법」\n7. 「택지개발촉진법」"}],"선지":[{"번호":1,"판정":"옳음","설명":"산업입지법에 따른 공급계약은 영 제3조제3항제5호의 대상이다."},{"번호":2,"판정":"옳음","설명":"건축물분양법에 따른 공급계약은 영 제3조제3항제1호의 대상이다."},{"번호":3,"판정":"옳음","설명":"공급계약으로 공급받는 자로 선정된 지위(분양권)의 매매계약은 법 제3조제1항제3호가목의 대상이다."},{"번호":4,"판정":"옳음","설명":"관리처분계획 인가로 취득한 입주자 지위(입주권)의 매매계약은 법 제3조제1항제3호나목의 대상이다."},{"번호":5,"판정":"틀림","설명":"증여는 신고 대상 계약으로 열거되어 있지 않다(법 제3조제1항 각 호)."}],"개념":[{"종류":"표","제목":"부동산 거래신고 대상 여부","머리":["계약","대상 여부","근거"],"행":[["부동산 매매계약","대상","법 제3조제1항제1호"],["7개 법률(영 제3조제3항)에 따른 공급계약","대상","법 제3조제1항제2호"],["공급받는 자로 선정된 지위(분양권)의 매매","대상","법 제3조제1항제3호가목"],["관리처분계획 등으로 취득한 입주자 지위(입주권)의 매매","대상","법 제3조제1항제3호나목"],["증여·교환","대상 아님","법 제3조제1항에 열거 없음"],["임대차","대상 아님(주택 임대차는 법 제6조의2의 별도 신고)","법 제3조제1항에 열거 없음"]]},{"종류":"표","제목":"공급계약의 근거 법률(영 제3조제3항)","머리":["호","법률"],"행":[["제1호","건축물의 분양에 관한 법률"],["제2호","공공주택 특별법"],["제3호","도시개발법"],["제4호","도시 및 주거환경정비법"],["제4호의2","빈집 및 소규모주택 정비에 관한 특례법"],["제5호","산업입지 및 개발에 관한 법률"],["제6호","주택법"],["제7호","택지개발촉진법"]]}],"함정":"분양권·입주권은 부동산 자체가 아니라 지위를 사고파는 계약인데도 신고 대상이다. 반대로 증여·교환·임대차는 대상이 아니다. 공급계약 근거 법률 여덟 개 가운데 산업입지법과 건축물분양법을 빠뜨리기 쉽다."}},{"i":"S5-2-1-중개사법-28","r":"S5","g":2,"c":2,"n":28,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 신고대상인 부동산 거래계약의 신고에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사가 공동으로 중개하여 거래계약서를 작성ㆍ교부한 경우, 공동으로 중개한 개업공인중개사 중 어느 한 사람이 단독으로 신고하면 된다.","부동산의 매수인은 신고인이 신고필증을 발급받은 때에 「부동산등기 특별조치법」에 따른 검인을 받은 것으로 본다.","거래당사자 중 일방이 지방공사인 경우, 그 지방공사가 부동산 거래계약의 신고를 하여야 한다.","개업공인중개사가 거래계약의 신고를 한 경우, 그 계약이 해제된 때의 해제등 신고도 해당 개업공인중개사가 할 수 있다.","신고관청은 거래계약을 신고하지 아니한 사실을 자진 신고한 자에 대하여 과태료를 감경 또는 면제할 수 있다."],"a":[1],"L":"중2-1","o":"변형","x":{"한줄":"공동으로 중개한 경우에는 해당 개업공인중개사들이 공동으로 신고한다(법 제3조제3항 후단).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조제3항·제6항","원문":"③ 「공인중개사법」 제2조제4호에 따른 개업공인중개사(이하 \"개업공인중개사\"라 한다)가 같은 법 제26조제1항에 따라 거래계약서를 작성ㆍ교부한 경우에는 제1항에도 불구하고 해당 개업공인중개사가 같은 항에 따른 신고를 하여야 한다. 이 경우 공동으로 중개를 한 경우에는 해당 개업공인중개사가 공동으로 신고하여야 한다.\n⑥ 부동산등의 매수인은 신고인이 제5항에 따른 신고필증을 발급받은 때에 「부동산등기 특별조치법」 제3조제1항에 따른 검인을 받은 것으로 본다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조제1항 단서","원문":"① 거래당사자는 다음 각 호의 어느 하나에 해당하는 계약을 체결한 경우 그 실제 거래가격 등 대통령령으로 정하는 사항을 거래계약의 체결일부터 30일 이내에 그 권리의 대상인 부동산등(권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다)의 소재지를 관할하는 시장(구가 설치되지 아니한 시의 시장 및 특별자치시장과 특별자치도 행정시의 시장을 말한다)ㆍ군수 또는 구청장(이하 \"신고관청\"이라 한다)에게 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 국가, 지방자치단체, 대통령령으로 정하는 자의 경우(이하 \"국가등\"이라 한다)에는 국가등이 신고를 하여야 한다.\n1. 부동산의 매매계약\n2. 「택지개발촉진법」, 「주택법」 등 대통령령으로 정하는 법률에 따른 부동산에 대한 공급계약\n3. 다음 각 목의 어느 하나에 해당하는 지위의 매매계약\n가. 제2호에 따른 계약을 통하여 부동산을 공급받는 자로 선정된 지위\n나. 「도시 및 주거환경정비법」 제74조에 따른 관리처분계획의 인가 및 「빈집 및 소규모주택 정비에 관한 특례법」 제29조에 따른 사업시행계획인가로 취득한 입주자로 선정된 지위"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제3조제2항","원문":"② 법 제3조제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 자\"란 다음 각 호의 기관을 말한다.\n1. 「공공기관의 운영에 관한 법률」에 따른 공공기관\n2. 「지방공기업법」에 따른 지방직영기업ㆍ지방공사 또는 지방공단"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조의2제2항","원문":"② 개업공인중개사가 제3조제3항에 따라 신고를 한 경우에는 제1항에도 불구하고 개업공인중개사가 같은 항에 따른 신고(공동으로 중개를 한 경우에는 해당 개업공인중개사가 공동으로 신고하는 것을 말한다)를 할 수 있다. 다만, 개업공인중개사 중 일방이 신고를 거부한 경우에는 제1항 단서를 준용한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제29조","원문":"신고관청은 제28조제2항제1호부터 제3호까지 및 제3항부터 제5항까지의 어느 하나에 따른 위반사실을 자진 신고한 자에 대하여 대통령령으로 정하는 바에 따라 같은 규정에 따른 과태료를 감경 또는 면제할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"공동으로 중개한 경우에는 개업공인중개사가 공동으로 신고한다. 한쪽이 신고를 거부한 때에만 다른 쪽이 단독으로 신고한다(법 제3조제3항·제4항)."},{"번호":2,"판정":"옳음","설명":"검인 의제의 기준 시점은 신고서 제출이 아니라 신고인이 신고필증을 발급받은 때다(법 제3조제6항)."},{"번호":3,"판정":"옳음","설명":"지방공사는 영 제3조제2항의 ‘국가등’이므로 상대방이 개인이어도 지방공사가 신고한다(법 제3조제1항 단서)."},{"번호":4,"판정":"옳음","설명":"개업공인중개사가 거래신고를 했다면 해제등 신고도 개업공인중개사가 할 수 있다(법 제3조의2제2항)."},{"번호":5,"판정":"옳음","설명":"신고를 하지 않은 위반은 500만원 이하 과태료 사유(법 제28조제2항제1호)이고, 자진 신고하면 감경·면제할 수 있다(법 제29조)."}],"개념":[{"종류":"흐름","제목":"부동산 거래신고 절차","단계":[{"이름":"계약 체결","설명":"부동산 거래계약 체결"},{"이름":"신고","설명":"계약 체결일부터 30일 이내, 부동산 소재지 시장·군수·구청장(신고관청)에게 신고서 제출"},{"이름":"신고필증 발급","설명":"신고관청이 내용을 확인한 후 지체 없이 신고필증 발급(법 제3조제5항)"},{"이름":"검인 의제","설명":"신고인이 신고필증을 발급받은 때 매수인은 검인을 받은 것으로 봄(법 제3조제6항)"},{"이름":"검증과 조사","설명":"신고가격 검증 결과를 세무관서에 통보, 필요하면 보완 요구와 자료 제출 요구(법 제5조·제6조)"}]},{"종류":"표","제목":"신고의무자","머리":["상황","신고하는 사람","근거"],"행":[["직거래","매도인·매수인이 공동으로 서명·날인하여 신고","법 제3조제1항, 규칙 제2조제1항"],["당사자 일방이 거부","다른 쪽이 계약서 사본, 계약금 지급 증빙, 단독신고사유서를 붙여 단독 신고","법 제3조제2항, 규칙 제2조제3항"],["당사자 일방이 국가등","국가등이 단독으로 서명·날인하여 신고","법 제3조제1항 단서, 규칙 제2조제2항"],["개업공인중개사가 거래계약서 작성·교부","해당 개업공인중개사(공동중개는 공동으로)","법 제3조제3항"],["중개한 개업공인중개사 중 일방이 거부","다른 개업공인중개사가 단독 신고","법 제3조제4항"],["소속공인중개사","개업공인중개사의 위임을 받아 제출만 대행, 신분증명서 제시","규칙 제5조제2항"]]}],"함정":"신고는 당사자와 개업공인중개사가 고르는 것이 아니다. 계약서를 쓴 개업공인중개사가 있으면 그에게 의무가 있고, 공동중개라면 두 사람이 함께 낸다. 한 사람이 대표로 낸다는 문장은 법에 없다. 소속공인중개사는 신고의무자가 아니라 제출 대행자일 뿐이다."}},{"i":"S5-2-1-중개사법-29","r":"S5","g":2,"c":2,"n":29,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 부동산거래계약 신고서 작성에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["거래당사자가 다수인 경우 매도인 또는 매수인의 주소란에 거래 지분 비율을 표시하되, 매도인과 매수인의 거래지분 비율은 일치해야 한다.","“종전 부동산”란은 입주권 매매의 경우뿐 아니라 분양권 매매의 경우에도 작성한다.","계약대상 면적에는 실제 거래면적을 계산하여 적되, 아파트와 같은 집합건축물은 전용면적을 적고, 그 밖의 건축물은 연면적을 적는다.","“공급계약”은 시행사 또는 건축주 등이 최초로 부동산을 공급(분양)하는 계약을 말하고, “임대주택 분양전환”은 임대기한이 완료되어 분양전환하는 법인 임대주택사업자의 주택인 경우에 표시한다.","다수의 부동산, 관련 필지, 매도ㆍ매수인, 개업공인중개사 등 기재사항이 복잡한 경우에는 다른 용지에 작성하여 간인 처리한 후 첨부한다."],"a":[2],"L":"중2-1","o":"변형","x":{"한줄":"“종전 부동산”란은 입주권 매매의 경우에만 작성한다(별지 제1호서식 작성방법 9).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 작성방법 1·4·6·7·8·9·10·11","원문":"1. ①ㆍ② 거래당사자가 다수인 경우 매도인 또는 매수인의 주소란에 ⑥의 거래대상별 거래지분을 기준으로 각자의 거래 지분 비율(매도인과 매수인의 거래지분 비율은 일치해야 합니다)을 표시하고, 거래당사자가 외국인인 경우 거래당사자의 국적을 반드시 적어야 하며, 외국인이 부동산등을 매수하는 경우 체류자격 및 국내에 주소를 두거나 183일 이상 거소를 두고 있는지 여부를 표시하고, 매수용도란의 주거용(아파트), 주거용(단독주택), 주거용(그 밖의 주택), 레저용, 상업용, 공장용, 그 밖의 용도 중 하나에 √표시를 합니다.\n4. ⑤ 공급계약은 시행사 또는 건축주 등이 최초로 부동산을 공급(분양)하는 계약을 말하며, 준공 전과 준공 후 계약 여부에 따라 √표시하고, “임대주택 분양전환”은 임대주택사업자 (법인으로 한정)가 임대기한이 완료되어 분양전환하는 주택인 경우에 √표시합니다. 전매는 부동산을 취득할 수 있는 권리의 매매로서, “분양권” 또는 “입주권”에 √표시를 합니다.\n6. ⑦ “계약대상 면적”란에는 실제 거래면적을 계산하여 적되, 건축물 면적은 집합건축물의 경우 전용면적을 적고, 그 밖의 건축물의 경우 연면적을 적습니다.\n7. ⑧ “물건별 거래가격”란에는 각각의 부동산별 거래가격을 적습니다. 최초 공급계약(분양) 또는 전매계약(분양권, 입주권)의 경우 분양가격, 발코니 확장 등 선택비용 및 추가 지급액 등(프리미엄 등 분양가격을 초과 또는 미달하는 금액)을 각각 적습니다. 이 경우 각각의 비용에 부가가치세가 있는 경우 부가가치세를 포함한 금액으로 적습니다.\n8. ⑨ “총 실제 거래가격”란에는 전체 거래가격(둘 이상의 부동산을 함께 거래하는 경우 각각의 부동산별 거래가격의 합계 금액)을 적고, 계약금/중도금/잔금 및 그 지급일을 적습니다.\n9. ⑩ “종전 부동산”란은 입주권 매매의 경우에만 작성하고, 거래금액란에는 추가 지급액 등(프리미엄 등 분양가격을 초과 또는 미달하는 금액) 및 권리가격, 합계 금액, 계약금, 중도금, 잔금을 적습니다.\n10. ⑪ “계약의 조건 및 참고사항”란은 부동산 거래계약 내용에 계약조건이나 기한을 붙인 경우, 거래와 관련한 참고내용이 있을 경우에 적습니다.\n11. 다수의 부동산, 관련 필지, 매도ㆍ매수인, 개업공인중개사 등 기재사항이 복잡한 경우에는 다른 용지에 작성하여 간인 처리한 후 첨부합니다."}],"선지":[{"번호":1,"판정":"옳음","설명":"거래당사자가 다수이면 지분 비율을 적고, 매도인 쪽과 매수인 쪽 비율은 일치해야 한다(작성방법 1)."},{"번호":2,"판정":"틀림","설명":"종전 부동산란은 입주권 매매에만 쓴다. 분양권 매매는 전매란의 ‘분양권’에 표시한다(작성방법 4·9)."},{"번호":3,"판정":"옳음","설명":"집합건축물은 전용면적, 그 밖의 건축물은 연면적이다(작성방법 6)."},{"번호":4,"판정":"옳음","설명":"공급계약의 뜻과 임대주택 분양전환 표시 요건은 작성방법 4의 문장 그대로다."},{"번호":5,"판정":"옳음","설명":"기재사항이 복잡하면 다른 용지에 작성하고 간인한 뒤 붙인다(작성방법 11)."}],"개념":[{"종류":"표","제목":"신고서 작성 요령(별지 제1호서식 작성방법)","머리":["항목","작성 방법"],"행":[["거래당사자가 다수","거래 지분 비율을 표시하고 매도인과 매수인의 비율을 일치시킴"],["거래당사자가 외국인","국적을 반드시 기재, 매수인이면 체류자격과 국내 주소·183일 이상 거소 여부 표시"],["계약대상 면적","실제 거래면적, 집합건축물은 전용면적·그 밖의 건축물은 연면적"],["물건별 거래가격","부동산별 거래가격, 공급·전매는 분양가격·선택비용·추가 지급액을 각각 적고 부가가치세가 있으면 포함"],["총 실제 거래가격","전체 거래가격의 합계와 계약금·중도금·잔금 및 지급일"],["종전 부동산란","입주권 매매의 경우에만 작성"],["계약의 조건 및 참고사항","조건이나 기한을 붙인 경우, 참고내용이 있는 경우에 작성"],["기재사항이 복잡한 경우","다른 용지에 작성하고 간인 처리 후 첨부"]]},{"종류":"비교","제목":"정정신청과 변경신고","왼쪽":{"이름":"정정신청(규칙 제3조제1항·제2항)","항목":["처음부터 잘못 기재된 사항을 바로잡음","대상: 당사자 주소·전화번호, 거래 지분 비율, 개업공인중개사 전화번호·상호·소재지, 건축물 종류, 지목·면적·거래 지분·대지권비율","신고필증에 정정 사항을 표시하고 서명 또는 날인","당사자 주소·전화번호만 일방이 단독으로 가능"]},"오른쪽":{"이름":"변경신고(규칙 제3조제3항~제5항)","항목":["계약 후 바뀐 사항을 등기신청 전에 신고","대상: 거래 지분 비율·지분, 면적, 조건·기한, 거래가격, 중도금·잔금과 지급일, 공동매수인 일부 제외, 일부 부동산 제외, 위탁관리인","변경 신고서에 서명 또는 날인","공급계약·분양권·입주권의 분양가격·선택품목은 일방이 단독으로 가능"]}}],"함정":"종전 부동산란은 입주권 매매에만 쓴다. 분양권과 입주권을 묶어 ‘전매’로 외우면 이 선지에서 틀린다. 면적 선지는 집합건축물과 그 밖의 건축물의 기준(전용·연면적)을 맞바꿔 낸다."}},{"i":"S5-2-1-중개사법-30","r":"S5","g":2,"c":2,"n":30,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 주택 임대차계약의 신고에 관한 설명으로 옳은 것은? (단, 다른 법률에 따른 신고의 의제는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["A특별자치시 소재 주택으로서 보증금이 6천만원이고 월 차임이 30만원으로 임대차계약을 신규 체결한 경우 신고 대상이다.","B시 소재 주택으로서 보증금이 5천만원이고 월 차임이 40만원으로 임대차계약을 신규 체결한 경우 신고 대상이 아니다.","자연인 甲과 ｢지방공기업법｣에 따른 지방공사 乙이 신고 대상인 주택 임대차계약을 체결한 경우 甲과 乙은 관할 신고관청에 공동으로 신고하여야 한다.","C광역시 D군 소재 주택으로서 보증금이 1억원이고 월차임이 100만원으로 신고된 임대차계약에서 보증금 및 차임의 증감 없이 임대차 기간만 연장하는 갱신계약은 신고 대상이 아니다.","개업공인중개사가 신고 대상인 주택 임대차계약을 중개한 경우 해당 개업공인중개사가 신고하여야 한다."],"a":[4],"L":"중2-2","o":"기출","x":{"한줄":"보증금과 차임의 증감 없이 기간만 연장하는 갱신계약은 신고 대상에서 제외된다(영 제4조의3제1항 괄호).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제4조의3제1항·제2항","원문":"① 법 제6조의2제1항 본문에서 \"대통령령으로 정하는 금액을 초과하는 임대차 계약\"이란 보증금이 6천만원을 초과하거나 월 차임이 30만원을 초과하는 주택 임대차 계약(계약을 갱신하는 경우로서 보증금 및 차임의 증감 없이 임대차 기간만 연장하는 계약은 제외한다)을 말한다.\n② 법 제6조의2제2항에서 \"대통령령으로 정하는 지역\"이란 특별자치시ㆍ특별자치도ㆍ시ㆍ군(광역시 및 경기도의 관할구역에 있는 군으로 한정한다)ㆍ구(자치구를 말한다)를 말한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제6조의2제1항","원문":"① 임대차계약당사자는 주택(「주택임대차보호법」 제2조에 따른 주택을 말하며, 주택을 취득할 수 있는 권리를 포함한다. 이하 같다)에 대하여 대통령령으로 정하는 금액을 초과하는 임대차 계약을 체결한 경우 그 보증금 또는 차임 등 국토교통부령으로 정하는 사항을 임대차 계약의 체결일부터 30일 이내에 주택 소재지를 관할하는 신고관청에 공동으로 신고하여야 한다. 다만, 임대차계약당사자 중 일방이 국가등인 경우에는 국가등이 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제3조제2항","원문":"② 법 제3조제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 자\"란 다음 각 호의 기관을 말한다.\n1. 「공공기관의 운영에 관한 법률」에 따른 공공기관\n2. 「지방공기업법」에 따른 지방직영기업ㆍ지방공사 또는 지방공단"}],"선지":[{"번호":1,"판정":"틀림","설명":"보증금 6천만원은 ‘초과’가 아니고 월 차임 30만원도 ‘초과’가 아니라서 신고 대상이 아니다."},{"번호":2,"판정":"틀림","설명":"월 차임 40만원은 30만원을 초과하므로 보증금이 5천만원이어도 신고 대상이다."},{"번호":3,"판정":"틀림","설명":"일방이 국가등(지방공사 포함)이면 국가등이 신고한다. 공동신고가 아니다(법 제6조의2제1항 단서)."},{"번호":4,"판정":"옳음","설명":"군은 광역시와 경기도에 속한 군만 지역 요건에 들고(영 제4조의3제2항), 금액 증감 없는 갱신계약은 제외된다(제1항)."},{"번호":5,"판정":"틀림","설명":"주택 임대차 신고의무자는 임대차계약당사자다. 중개한 개업공인중개사에게 신고의무가 없다(법 제6조의2제1항)."}],"개념":[{"종류":"표","제목":"주택 임대차 신고 요건","머리":["항목","내용","근거"],"행":[["금액","보증금 6천만원 초과 또는 월 차임 30만원 초과(하나만 넘어도 대상)","영 제4조의3제1항"],["지역","특별자치시·특별자치도·시·구, 군은 광역시·경기도 소속 군만","영 제4조의3제2항"],["갱신계약","보증금·차임 증감 없이 기간만 연장하면 제외","영 제4조의3제1항"],["기한","계약 체결일부터 30일 이내","법 제6조의2제1항"],["신고의무자","임대차계약당사자 공동, 일방이 국가등이면 국가등 단독","법 제6조의2제1항"],["일방이 거부","국토교통부령에 따라 단독 신고","법 제6조의2제3항"],["신고 효과","전입신고로 신고 의제, 임대차계약서를 낸 신고는 확정일자 의제","법 제6조의5"],["과태료","신고·변경·해제 신고를 하지 않거나 거짓으로 하면 100만원 이하","법 제28조제5항제3호"]]},{"종류":"비교","제목":"부동산 거래신고와 주택 임대차 신고","왼쪽":{"이름":"부동산 거래신고(제3조)","항목":["대상: 매매, 공급계약, 분양권·입주권 매매","계약서를 쓴 개업공인중개사가 신고","신고필증 발급 시 검인 의제","미신고 과태료 500만원 이하"]},"오른쪽":{"이름":"주택 임대차 신고(제6조의2)","항목":["대상: 보증금 6천만원 초과 또는 월 차임 30만원 초과 주택 임대차(지역 한정)","임대차계약당사자가 신고, 개업공인중개사 신고의무 없음","계약서를 낸 신고는 확정일자 의제","미신고 과태료 100만원 이하"]}}],"함정":"6천만원과 30만원은 기준선 그 자체라서 대상이 아니다. 보증금이 기준 이하여도 월 차임이 30만원을 넘으면 대상이다. 매매 신고와 달리 개업공인중개사에게 신고의무가 없고, 일방이 국가등이면 공동신고가 아니라 국가등 단독 신고다."}},{"i":"S5-2-1-중개사법-31","r":"S5","g":2,"c":2,"n":31,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 외국인등의 국내 부동산의 취득ㆍ보유 등에 관한 설명으로 틀린 것은? (단, 헌법과 법률에 따라 체결된 조약의 이행에 필요한 경우는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["외국인등이 건물을 증여받는 계약을 체결한 경우 계약체결일부터 60일 이내에 신고관청에 취득신고를 해야 한다.","외국인등이 건축물을 신축하여 취득한 경우에는 취득한 날부터 6개월 이내에 신고관청에 취득신고를 해야 한다.","대한민국의 법령에 따라 설립된 법인이 외국인등으로 변경된 후 그 법인이 소유한 부동산을 계속 보유하려면 외국인등으로 변경된 날부터 6개월 이내에 신고관청에 계속보유 신고를 해야 한다.","외국인등이 「문화유산의 보존 및 활용에 관한 법률」에 따른 지정문화유산의 보호구역 내 토지를 취득하려는 경우, 신고관청은 허가신청서를 받은 날부터 30일 이내에 허가 또는 불허가 처분을 해야 한다.","토지거래계약 허가구역 안의 토지를 취득하는 외국인등이 토지거래계약에 관한 허가를 받았다면, 별도로 외국인등의 토지취득 허가를 받지 않아도 된다."],"a":[4],"L":"중2-3","o":"변형","x":{"한줄":"군사 관련 구역이 아닌 지정문화유산 보호구역의 허가 처리기간은 15일이다(영 제6조제3항제2호).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제8조제1항~제3항","원문":"① 외국인등이 대한민국 안의 부동산등을 취득하는 계약(제3조제1항 각 호에 따른 계약은 제외한다)을 체결하였을 때에는 계약체결일부터 60일 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다.\n② 외국인등이 상속ㆍ경매, 그 밖에 대통령령으로 정하는 계약 외의 원인으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다.\n③ 대한민국 안의 부동산등을 가지고 있는 대한민국국민이나 대한민국의 법령에 따라 설립된 법인 또는 단체가 외국인등으로 변경된 경우 그 외국인등이 해당 부동산등을 계속보유하려는 경우에는 외국인등으로 변경된 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제5조제2항","원문":"② 법 제8조제2항에서 \"대통령령으로 정하는 계약 외의 원인\"이란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.\n1. 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 및 그 밖의 법률에 따른 환매권의 행사\n2. 법원의 확정판결\n3. 법인의 합병\n4. 건축물의 신축ㆍ증축ㆍ개축ㆍ재축"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제6조제3항","원문":"③ 제1항에 따른 신청서를 받은 신고관청은 신청서를 받은 날부터 다음 각 호의 구분에 따른 기간 안에 허가 또는 불허가 처분을 해야 한다. 다만, 부득이한 사유로 제1호에 따른 기간 안에 허가 또는 불허가 처분을 할 수 없는 경우에는 30일의 범위에서 그 기간을 연장할 수 있으며, 기간을 연장하는 경우에는 연장 사유와 처리예정일을 지체 없이 신청인에게 알려야 한다.\n1. 법 제9조제1항제1호에 따른 구역ㆍ지역의 경우: 30일\n2. 제1호 외의 구역ㆍ지역의 경우: 15일"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제9조제1항","원문":"① 제3조 및 제8조에도 불구하고 외국인등이 취득하려는 토지가 다음 각 호의 어느 하나에 해당하는 구역ㆍ지역 등에 있으면 토지를 취득하는 계약(이하 \"토지취득계약\"이라 한다)을 체결하기 전에 대통령령으로 정하는 바에 따라 신고관청으로부터 토지취득의 허가를 받아야 한다. 다만, 제11조에 따라 토지거래계약에 관한 허가를 받은 경우에는 그러하지 아니하다.\n1. 「군사기지 및 군사시설 보호법」 제2조제6호에 따른 군사기지 및 군사시설 보호구역, 그 밖에 국방목적을 위하여 외국인등의 토지취득을 특별히 제한할 필요가 있는 지역으로서 대통령령으로 정하는 지역\n2. 「문화유산의 보존 및 활용에 관한 법률」 제2조제3항에 따른 지정문화유산과 이를 위한 보호물 또는 보호구역\n2의2. 「자연유산의 보존 및 활용에 관한 법률」에 따라 지정된 천연기념물등과 이를 위한 보호물 또는 보호구역\n3. 「자연환경보전법」 제2조제12호에 따른 생태ㆍ경관보전지역\n4. 「야생생물 보호 및 관리에 관한 법률」 제27조에 따른 야생생물 특별보호구역"}],"선지":[{"번호":1,"판정":"옳음","설명":"증여는 매매 외 계약이다. 계약체결일부터 60일 이내에 신고한다(법 제8조제1항)."},{"번호":2,"판정":"옳음","설명":"건축물의 신축은 계약 외의 원인이다. 취득한 날부터 6개월 이내에 신고한다(법 제8조제2항, 영 제5조제2항제4호)."},{"번호":3,"판정":"옳음","설명":"국내 법인이 외국인등으로 변경되면 변경된 날부터 6개월 이내에 계속보유 신고를 한다(법 제8조제3항)."},{"번호":4,"판정":"틀림","설명":"30일은 국방목적의 구역·지역(제9조제1항제1호)에만 적용된다. 문화유산 보호구역은 15일이다(영 제6조제3항제2호)."},{"번호":5,"판정":"옳음","설명":"토지거래계약 허가를 받았으면 외국인등의 토지취득 허가는 받지 않는다(법 제9조제1항 단서)."}],"개념":[{"종류":"표","제목":"외국인등의 부동산 취득·보유 신고 기한","머리":["원인","절차","기한","과태료"],"행":[["매매계약(공급계약·분양권·입주권 매매 포함)","부동산 거래신고","계약체결일부터 30일","500만원 이하"],["증여·교환 등 매매 외 계약","취득신고","계약체결일부터 60일","300만원 이하"],["상속·경매·확정판결·환매권 행사·법인 합병·건축물 신축 등","취득신고","취득한 날부터 6개월","100만원 이하"],["국민·국내 법인이 외국인등으로 변경","계속보유 신고","변경된 날부터 6개월","100만원 이하"]]},{"종류":"표","제목":"외국인등의 토지취득 허가 구역과 처리기간","머리":["구역·지역(법 제9조제1항)","처리기간(영 제6조제3항)"],"행":[["군사기지 및 군사시설 보호구역, 국방목적 지역(섬 지역, 군부대주둔지와 인근, 국가중요시설과 인근)","30일(부득이하면 30일 범위에서 연장)"],["지정문화유산과 보호물·보호구역","15일"],["천연기념물등과 보호물·보호구역","15일"],["생태·경관보전지역","15일"],["야생생물 특별보호구역","15일"],["허가 없이 체결한 토지취득계약","효력이 발생하지 않음(법 제9조제3항)"]]}],"함정":"허가 처리기간을 15일로 외우면 국방목적 구역에서, 30일로 외우면 문화유산 등에서 틀린다. 군사 관련 구역만 30일이고 나머지는 15일이다. 신고 기한은 원인별로 30일·60일·6개월이 갈린다.","개정":"2023.10.4 개정 영 제6조제3항으로 국방목적 구역·지역(법 제9조제1항제1호)의 처리기간은 30일(30일 범위에서 연장 가능), 그 밖의 구역·지역은 15일이 되었다."}},{"i":"S5-2-1-중개사법-32","r":"S5","g":2,"c":2,"n":32,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 토지거래계약허가를 받아 취득한 토지를 허가받은 목적대로 이용하고 있지 않은 경우 시장ㆍ군수ㆍ구청장이 취할 수 있는 조치가 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["과태료를 부과할 수 있다.","토지거래계약허가를 취소할 수 있다.","3개월 이내의 기간을 정하여 토지의 이용 의무를 이행하도록 문서로 명할 수 있다.","해당 토지에 관한 토지거래계약 허가신청이 있을 때 국가, 지방자치단체, 한국토지주택공사가 그 토지의 매수를 원하면 이들 중에서 매수할 자를 지정하여 협의 매수하게 할 수 있다.","해당 토지를 직접 이용하지 않고 임대하고 있다는 이유로 이행명령을 했음에도 정해진 기간에 이행되지 않은 경우, 토지 취득가액의 100분의 7에 상당하는 금액의 이행강제금을 부과한다."],"a":[1],"L":"중2-4","o":"기출","x":{"한줄":"이용의무 위반에 대한 조치에 과태료는 없다. 이행명령, 이행강제금, 허가취소, 선매로 대응한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제17조제1항","원문":"① 제11조에 따라 토지거래계약을 허가받은 자는 대통령령으로 정하는 사유가 있는 경우 외에는 5년의 범위에서 대통령령으로 정하는 기간에 그 토지를 허가받은 목적대로 이용하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제18조제1항·제2항","원문":"① 시장ㆍ군수 또는 구청장은 제17조제1항에 따른 토지의 이용 의무를 이행하지 아니한 자에 대하여는 상당한 기간을 정하여 토지의 이용 의무를 이행하도록 명할 수 있다. 다만, 대통령령으로 정하는 사유가 있는 경우에는 이용 의무의 이행을 명하지 아니할 수 있다.\n② 시장ㆍ군수 또는 구청장은 제1항에 따른 이행명령이 정하여진 기간에 이행되지 아니한 경우에는 토지 취득가액의 100분의 10의 범위에서 대통령령으로 정하는 금액의 이행강제금을 부과한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제21조","원문":"국토교통부장관, 시ㆍ도지사, 시장ㆍ군수 또는 구청장은 다음 각 호의 어느 하나에 해당하는 자에게 제11조에 따른 허가 취소 또는 그 밖에 필요한 처분을 하거나 조치를 명할 수 있다.\n1. 제11조에 따른 토지거래계약에 관한 허가 또는 변경허가를 받지 아니하고 토지거래계약 또는 그 변경계약을 체결한 자\n2. 제11조에 따른 토지거래계약에 관한 허가를 받은 자가 그 토지를 허가받은 목적대로 이용하지 아니한 자\n3. 부정한 방법으로 제11조에 따른 토지거래계약에 관한 허가를 받은 자"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제15조제1항","원문":"① 시장ㆍ군수 또는 구청장은 제11조제1항에 따른 토지거래계약에 관한 허가신청이 있는 경우 다음 각 호의 어느 하나에 해당하는 토지에 대하여 국가, 지방자치단체, 한국토지주택공사, 그 밖에 대통령령으로 정하는 공공기관 또는 공공단체가 그 매수를 원하는 경우에는 이들 중에서 해당 토지를 매수할 자[이하 \"선매자(先買者)\"라 한다]를 지정하여 그 토지를 협의 매수하게 할 수 있다.\n1. 공익사업용 토지\n2. 제11조제1항에 따른 토지거래계약허가를 받아 취득한 토지를 그 이용목적대로 이용하고 있지 아니한 토지"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제16조제1항·제3항","원문":"① 법 제18조제1항 본문에 따른 이행명령은 문서로 하여야 하며, 이행기간은 3개월 이내로 정하여야 한다.\n③ 법 제18조제2항에서 \"대통령령으로 정하는 금액\"이란 다음 각 호의 구분에 따른 금액을 말한다.\n1. 토지거래계약허가를 받아 토지를 취득한 자가 당초의 목적대로 이용하지 아니하고 방치한 경우: 토지 취득가액의 100분의 10에 상당하는 금액\n2. 토지거래계약허가를 받아 토지를 취득한 자가 직접 이용하지 아니하고 임대한 경우: 토지 취득가액의 100분의 7에 상당하는 금액\n3. 토지거래계약허가를 받아 토지를 취득한 자가 제14조제1항제3호에 따른 허가관청의 승인 없이 당초의 이용목적을 변경하여 이용하는 경우: 토지 취득가액의 100분의 5에 상당하는 금액\n4. 제1호부터 제3호까지에 해당하지 아니하는 경우: 토지 취득가액의 100분의 7에 상당하는 금액"}],"선지":[{"번호":1,"판정":"틀림","설명":"이용의무를 어긴 데 대한 과태료 규정은 없다. 과태료 사유는 법 제28조에 열거되어 있고 이용의무 위반은 들어 있지 않다."},{"번호":2,"판정":"옳음","설명":"허가를 받은 목적대로 이용하지 않은 자에게 허가 취소를 할 수 있다(법 제21조제2호)."},{"번호":3,"판정":"옳음","설명":"이행명령은 문서로 하고 이행기간은 3개월 이내다(영 제16조제1항)."},{"번호":4,"판정":"옳음","설명":"허가받은 목적대로 이용하지 않는 토지는 선매 대상이다(법 제15조제1항제2호)."},{"번호":5,"판정":"옳음","설명":"직접 이용하지 않고 임대한 경우의 이행강제금은 취득가액의 100분의 7이다(영 제16조제3항제2호)."}],"개념":[{"종류":"표","제목":"이용의무를 어긴 경우의 조치","머리":["조치","내용","근거"],"행":[["이행명령","상당한 기간을 정해 이행을 명함, 문서로 하고 3개월 이내","법 제18조제1항, 영 제16조제1항"],["이행강제금","이행명령을 따르지 않으면 취득가액의 100분의 10 범위에서 부과","법 제18조제2항"],["허가 취소·조치명령","허가를 받고도 목적대로 이용하지 않은 자에게 가능","법 제21조제2호"],["선매","목적대로 이용하지 않는 토지에 허가신청이 있으면 선매자를 지정해 협의 매수","법 제15조제1항제2호"],["이용 현황 조사","시장·군수·구청장이 국토교통부령에 따라 조사","법 제17조제2항"]]},{"종류":"표","제목":"토지 이용의무 기간(영 제14조제2항)","머리":["허가 목적","의무 기간"],"행":[["자기 거주용 주택용지, 주민 복지·편익시설, 농업·임업·어업 경영(법 제12조제1호가목~다목)","토지 취득일부터 2년"],["수용 가능한 사업, 지정 목적에 맞는 사업, 인근 사업 시행자의 이용(법 제12조제1호라목~바목)","토지 취득일부터 4년"],["대체토지 취득","토지 취득일부터 2년"],["현상 보존 목적","토지 취득일부터 5년"],["그 밖의 경우","토지 취득일부터 5년"]]}],"함정":"이행강제금은 있지만 과태료는 없다. 이용의무 위반에는 이행명령이 먼저이고, 이행명령을 따르지 않을 때 이행강제금이 붙는다. 이행명령 없이 곧바로 이행강제금을 부과하는 것이 아니다."}},{"i":"S5-2-1-중개사법-33","r":"S5","g":2,"c":2,"n":33,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 이행강제금에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["이행명령은 문서로 하며 이행기간은 6개월 이내로 정하여야 한다.","토지거래계약허가를 받아 토지를 취득한 자가 직접 이용하지 아니하고 임대하여 이행명령을 받고도 정하여진 기간에 이를 이행하지 아니한 경우, 시장ㆍ군수 또는 구청장은 토지 취득가액의 100분의 10에 상당하는 금액의 이행강제금을 부과한다.","시장ㆍ군수 또는 구청장은 최초의 이행명령이 있었던 날을 기준으로 1년에 한 번씩 그 이행명령이 이행될 때까지 반복하여 이행강제금을 부과ㆍ징수할 수 있다.","이행명령을 받은 자가 그 명령을 이행하는 경우 새로운 이행강제금의 부과를 즉시 중지하며, 명령을 이행하기 전에 부과된 이행강제금도 징수할 수 없다.","이행강제금 부과처분을 받은 자는 부과처분을 고지받은 날부터 14일 이내에 국토교통부장관에게 이의를 제기하여야 한다."],"a":[3],"L":"중2-4","o":"변형","x":{"한줄":"이행강제금은 최초 이행명령일을 기준으로 1년에 한 번씩 이행될 때까지 반복해서 부과할 수 있다(법 제18조제3항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제16조제1항·제3항·제5항~제7항","원문":"① 법 제18조제1항 본문에 따른 이행명령은 문서로 하여야 하며, 이행기간은 3개월 이내로 정하여야 한다.\n③ 법 제18조제2항에서 \"대통령령으로 정하는 금액\"이란 다음 각 호의 구분에 따른 금액을 말한다.\n1. 토지거래계약허가를 받아 토지를 취득한 자가 당초의 목적대로 이용하지 아니하고 방치한 경우: 토지 취득가액의 100분의 10에 상당하는 금액\n2. 토지거래계약허가를 받아 토지를 취득한 자가 직접 이용하지 아니하고 임대한 경우: 토지 취득가액의 100분의 7에 상당하는 금액\n3. 토지거래계약허가를 받아 토지를 취득한 자가 제14조제1항제3호에 따른 허가관청의 승인 없이 당초의 이용목적을 변경하여 이용하는 경우: 토지 취득가액의 100분의 5에 상당하는 금액\n4. 제1호부터 제3호까지에 해당하지 아니하는 경우: 토지 취득가액의 100분의 7에 상당하는 금액\n⑤ 허가관청은 법 제18조제2항에 따른 이행강제금을 부과하기 전에 이행기간 내에 이행명령을 이행하지 아니하면 이행강제금을 부과ㆍ징수한다는 뜻을 미리 문서로 계고(戒告)하여야 한다.\n⑥ 법 제18조제2항에 따른 이행강제금을 부과하는 경우에는 이행강제금의 금액ㆍ부과사유ㆍ납부기한 및 수납기관, 이의제기방법 및 이의제기기관 등을 명시한 문서로 하여야 한다.\n⑦ 제6항에 따른 이행강제금 부과처분을 받은 자는 법 제18조제6항에 따라 이의를 제기하려는 경우에는 부과처분을 고지받은 날부터 30일 이내에 하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제18조제2항~제6항","원문":"② 시장ㆍ군수 또는 구청장은 제1항에 따른 이행명령이 정하여진 기간에 이행되지 아니한 경우에는 토지 취득가액의 100분의 10의 범위에서 대통령령으로 정하는 금액의 이행강제금을 부과한다.\n③ 시장ㆍ군수 또는 구청장은 최초의 이행명령이 있었던 날을 기준으로 1년에 한 번씩 그 이행명령이 이행될 때까지 반복하여 제2항에 따른 이행강제금을 부과ㆍ징수할 수 있다.\n④ 시장ㆍ군수 또는 구청장은 제17조제1항에 따른 이용 의무기간이 지난 후에는 이행강제금을 부과할 수 없다.\n⑤ 시장ㆍ군수 또는 구청장은 제1항에 따른 이행명령을 받은 자가 그 명령을 이행하는 경우에는 새로운 이행강제금의 부과를 즉시 중지하되, 명령을 이행하기 전에 이미 부과된 이행강제금은 징수하여야 한다.\n⑥ 제2항에 따른 이행강제금의 부과처분에 불복하는 자는 시장ㆍ군수 또는 구청장에게 이의를 제기할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"이행기간은 3개월 이내다(영 제16조제1항)."},{"번호":2,"판정":"틀림","설명":"직접 이용하지 않고 임대한 경우는 100분의 7이다. 100분의 10은 방치한 경우다(영 제16조제3항)."},{"번호":3,"판정":"옳음","설명":"반복 부과의 기산점은 최초의 이행명령이 있었던 날이고, 부과 주기는 1년에 한 번이다(법 제18조제3항)."},{"번호":4,"판정":"틀림","설명":"명령 이행 전에 이미 부과된 이행강제금은 징수하여야 한다(법 제18조제5항)."},{"번호":5,"판정":"틀림","설명":"이의는 고지받은 날부터 30일 이내에 시장·군수·구청장에게 제기한다(법 제18조제6항, 영 제16조제7항)."}],"개념":[{"종류":"표","제목":"이행강제금의 금액(영 제16조제3항)","머리":["사유","금액"],"행":[["당초 목적대로 이용하지 않고 방치","토지 취득가액의 100분의 10"],["직접 이용하지 않고 임대","토지 취득가액의 100분의 7"],["허가관청의 승인 없이 이용목적을 변경","토지 취득가액의 100분의 5"],["그 밖의 경우","토지 취득가액의 100분의 7"]]},{"종류":"흐름","제목":"이행강제금 부과 절차","단계":[{"이름":"이용의무 위반","설명":"허가받은 목적대로 이용하지 않음"},{"이름":"이행명령","설명":"문서로 하고 이행기간은 3개월 이내(영 제16조제1항)"},{"이름":"계고","설명":"이행하지 않으면 이행강제금을 부과·징수한다는 뜻을 미리 문서로 계고(영 제16조제5항)"},{"이름":"부과","설명":"금액·부과사유·납부기한·이의제기방법을 명시한 문서로 부과(영 제16조제6항)"},{"이름":"반복 부과","설명":"최초 이행명령일 기준 1년에 한 번씩, 이용 의무기간이 지나면 부과 불가(법 제18조제3항·제4항)"},{"이름":"이행 후","설명":"새로운 부과는 즉시 중지, 이미 부과된 분은 징수(법 제18조제5항)"},{"이름":"이의제기","설명":"고지받은 날부터 30일 이내 시장·군수·구청장에게(영 제16조제7항)"}]}],"함정":"방치(100분의 10)와 임대(100분의 7)의 비율을 맞바꾼 선지가 가장 흔하다. 기부과분은 명령을 이행해도 징수하고, 이의 기한은 30일이다. 반복 부과 주기는 1년에 한 번이고 기준일은 최초 위반일이 아니라 최초 이행명령일이다."}},{"i":"S5-2-1-중개사법-34","r":"S5","g":2,"c":2,"n":34,"s":"중개사법","q":"개업공인중개사가 「장사 등에 관한 법률」에 대해 중개의뢰인에게 설명한 것으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개인묘지는 30제곱미터를 초과해서는 안된다.","시장등은 묘지의 설치·관리를 목적으로 민법에 따라 설립된 재단법인에 한정하여 법인묘지의 설치·관리를 허가할 수 있다.","분묘의 설치기간은 30년이고, 설치기간이 지난 분묘의 연고자가 연장을 신청하면 1회에 한하여 연장해 준다.","가족묘지를 설치·관리하려는 자는 묘지를 설치한 후 30일 이내에 관할 시장등에게 신고하여야 한다.","설치기간이 끝난 분묘의 연고자는 설치기간이 끝난 날부터 1년 이내에 해당 분묘에 설치된 시설물을 철거하고 매장된 유골을 화장하거나 봉안해야 한다."],"a":[4],"L":"중3-1","o":"변형","x":{"한줄":"신고만으로 설치할 수 있는 사설묘지는 개인묘지뿐이고, 가족묘지는 설치·관리 전에 시장등의 허가를 받아야 한다(법 제14조제4항).","근거":[{"법령":"장사 등에 관한 법률","조문":"제14조제2항·제4항·제5항","원문":"② 개인묘지를 설치한 자는 보건복지부령으로 정하는 바에 따라 묘지를 설치한 후 30일 이내에 해당 묘지를 관할하는 시장등에게 신고하여야 한다. 신고한 사항 중 대통령령으로 정하는 사항을 변경한 경우에도 또한 같다.\n④ 가족묘지, 종중ㆍ문중묘지 또는 법인묘지를 설치ㆍ관리하려는 자는 보건복지부령으로 정하는 바에 따라 해당 묘지를 관할하는 시장등의 허가를 받아야 한다. 허가받은 사항 중 대통령령으로 정하는 사항을 변경하려는 경우에도 또한 같다.\n⑤ 시장등은 묘지의 설치ㆍ관리를 목적으로 「민법」에 따라 설립된 재단법인에 한정하여 법인묘지의 설치ㆍ관리를 허가할 수 있다."},{"법령":"장사 등에 관한 법률","조문":"제18조제2항","원문":"② 개인묘지는 30제곱미터를 초과하여서는 아니 된다."},{"법령":"장사 등에 관한 법률","조문":"제19조제1항·제2항","원문":"① 제13조에 따른 공설묘지 및 제14조에 따른 사설묘지에 설치된 분묘의 설치기간은 30년으로 한다.\n② 제1항에 따른 설치기간이 지난 분묘의 연고자가 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 제14조제4항에 따라 법인묘지의 설치ㆍ관리를 허가받은 자에게 그 설치기간의 연장을 신청하는 경우에는 1회에 한하여 그 설치기간을 30년으로 하여 연장하여야 한다."},{"법령":"장사 등에 관한 법률","조문":"제20조제1항","원문":"① 제19조에 따른 설치기간이 끝난 분묘의 연고자는 설치기간이 끝난 날부터 1년 이내에 해당 분묘에 설치된 시설물을 철거하고 매장된 유골을 화장하거나 봉안하여야 한다."},{"법령":"장사 등에 관한 법률 시행령","조문":"별표 2 사설묘지의 설치기준 제2호가목·제3호가목·제4호가목","원문":"2. 가족묘지\n가. 가족묘지는 가족당 1개소로 제한하되, 그 면적은 100제곱미터 이하여야 한다.\n3. 종중·문중묘지\n가. 종중·문중묘지는 종중 또는 문중별로 각각 1개소에 한정하여 설치할 수 있으며, 그 면적은 1천제곱미터 이하여야 한다.\n4. 법인묘지\n가. 법인묘지의 면적은 10만 제곱미터 이상으로 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개인묘지의 면적 상한은 30제곱미터다(법 제18조제2항)."},{"번호":2,"판정":"옳음","설명":"법인묘지는 묘지의 설치·관리를 목적으로 「민법」에 따라 설립된 재단법인에 한정해 허가한다(법 제14조제5항)."},{"번호":3,"판정":"옳음","설명":"설치기간은 30년이고 연고자가 연장을 신청하면 1회에 한하여 30년으로 연장한다(법 제19조제1항·제2항)."},{"번호":4,"판정":"틀림","설명":"가족묘지는 신고가 아니라 시장등의 허가를 받아야 한다(법 제14조제4항). 설치 후 30일 이내 신고는 개인묘지에 해당한다(법 제14조제2항)."},{"번호":5,"판정":"옳음","설명":"설치기간이 끝난 날부터 1년 이내에 시설물을 철거하고 유골을 화장하거나 봉안한다(법 제20조제1항)."}],"개념":[{"종류":"표","제목":"사설묘지 4종","머리":["구분","뜻(법 제14조제1항)","설치 절차","면적"],"행":[["개인묘지","1기의 분묘 또는 해당 분묘에 매장된 자와 배우자 관계였던 자의 분묘","설치 후 30일 이내 시장등에 신고","30㎡ 초과 금지(법 제18조제2항)"],["가족묘지","「민법」에 따라 친족관계였던 자의 분묘","설치·관리 전 시장등의 허가","가족당 1개소, 100㎡ 이하(영 별표 2)"],["종중·문중묘지","종중이나 문중 구성원의 분묘","설치·관리 전 시장등의 허가","종중·문중별 1개소, 1천㎡ 이하(영 별표 2)"],["법인묘지","법인이 불특정 다수인의 분묘를 설치하는 묘지","시장등의 허가, 「민법」상 재단법인에 한정","10만㎡ 이상(영 별표 2)"]]},{"종류":"표","제목":"장사법의 신고·기간","머리":["사항","내용","근거"],"행":[["매장 신고","매장 후 30일 이내 매장지 관할 시장등에게 신고","법 제8조제1항"],["분묘 1기의 점유면적","공설·가족·종중·문중·법인묘지 안에서 10㎡(합장 15㎡) 초과 금지","법 제18조제1항"],["분묘 설치기간","30년, 연장 신청 시 1회 30년(조례로 5년 이상 30년 미만으로 단축 가능)","법 제19조"],["설치기간 종료 분묘","끝난 날부터 1년 이내 시설물 철거, 유골 화장 또는 봉안","법 제20조제1항"],["묘지 사전 매매 금지","매장될 자가 사망하기 전에는 매매·양도·임대·사용계약 불가, 70세 이상인 자가 사용하려는 경우 등은 예외","법 제21조"]]}],"함정":"가족묘지·종중묘지·법인묘지는 설치 전에 허가를 받고, 신고로 설치하는 묘지는 개인묘지 하나다. 매장 신고(매장 후 30일)와 개인묘지 신고(설치 후 30일)가 모두 30일이라 허가 대상 묘지에도 신고를 붙여 낸 선지가 나온다."}},{"i":"S5-2-1-중개사법-35","r":"S5","g":2,"c":2,"n":35,"s":"중개사법","q":"개업공인중개사 乙의 중개로, 甲은 丙에게 매수자금을 주고 丙이 자기 이름으로 丁 소유 X건물을 매수하여 丙 명의로 소유권이전등기를 하기로 약정하였다. 丙은 약정대로 丁과 매매계약을 체결하고 소유권이전등기를 마쳤다. 乙이 甲에게 설명한 내용으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 丙 사이의 명의신탁약정은 丁이 그 약정을 알았는지 여부와 관계없이 무효이다.","丁이 계약 체결 당시 명의신탁약정이 있다는 사실을 알지 못하였다면, 丙 명의의 소유권이전등기는 무효이다.","丁이 계약 체결 당시 명의신탁약정이 있다는 사실을 알고 있었다면, X건물의 소유자는 丁이다.","丁이 계약 체결 당시 명의신탁약정이 있다는 사실을 알지 못하였다면, 甲은 丙에게 매수자금 상당의 부당이득반환을 청구할 수 있다.","丁이 계약 체결 당시 명의신탁약정이 있다는 사실을 알지 못한 경우, 丙이 X건물을 戊에게 처분하고 소유권이전등기를 마쳤다면 戊는 소유권을 취득한다."],"a":[2],"L":"중3-2","o":"변형","x":{"한줄":"계약 체결 당시 매도인이 명의신탁약정을 알지 못했다면 수탁자 명의 등기는 유효하고 수탁자가 소유권을 취득한다(부동산실명법 제4조제2항 단서).","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제1항~제3항","원문":"① 명의신탁약정은 무효로 한다.\n② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다.\n③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"계약명의신탁에서 신탁자의 구제(대법원 판례)","요지":"계약 체결 당시 매도인이 명의신탁약정을 몰랐다면 수탁자가 소유권을 취득한다. 신탁자는 부동산 자체를 청구할 수 없고, 수탁자에게 매수자금 상당의 부당이득반환을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"명의신탁약정은 상대방의 선의·악의와 관계없이 무효다(실명법 제4조제1항)."},{"번호":2,"판정":"틀림","설명":"매도인이 선의면 등기는 무효가 되지 않는다. 계약명의신탁에서 매도인이 선의면 수탁자 명의 등기는 유효하다(실명법 제4조제2항 단서)."},{"번호":3,"판정":"옳음","설명":"매도인이 악의면 수탁자 명의 등기는 무효이고 소유권은 매도인에게 남는다(실명법 제4조제2항 본문)."},{"번호":4,"판정":"옳음","설명":"매도인이 선의라 수탁자가 소유권을 취득하므로, 신탁자는 건넨 매수자금을 부당이득으로 돌려받을 수 있다(판례)."},{"번호":5,"판정":"옳음","설명":"수탁자로부터 취득한 제3자는 선의·악의를 묻지 않고 소유권을 취득한다(실명법 제4조제3항)."}],"개념":[{"종류":"표","제목":"명의신탁 유형별 효력","머리":["유형","계약 당사자","수탁자 명의 등기","소유자","신탁자의 구제"],"행":[["2자간 등기명의신탁","신탁자가 원래 소유자","무효","신탁자","수탁자 명의 등기의 말소 또는 진정명의회복"],["3자간 등기명의신탁","매도인과 신탁자","무효","매도인","매도인에게 매매계약상 이전등기 청구, 매도인을 대위해 수탁자 등기 말소"],["계약명의신탁(매도인 선의)","매도인과 수탁자","유효","수탁자","수탁자에게 매수자금 부당이득반환 청구"],["계약명의신탁(매도인 악의)","매도인과 수탁자","무효","매도인","매수자금을 수탁자에게 청구"]]},{"종류":"표","제목":"명의신탁약정에 대한 제재와 특례","머리":["항목","내용","근거"],"행":[["제3자 보호","약정·등기의 무효는 제3자에게 대항하지 못함","실명법 제4조제3항"],["과징금","명의신탁자에게 부동산 가액의 100분의 30 범위에서 부과","실명법 제5조제1항"],["이행강제금","과징금 부과 후 실명등기를 하지 않으면 1년 뒤 부동산평가액의 100분의 10, 다시 1년 뒤 100분의 20","실명법 제6조제2항"],["벌칙","명의신탁자 5년 이하 징역 또는 2억원 이하 벌금, 명의수탁자 3년 이하 징역 또는 1억원 이하 벌금","실명법 제7조"],["특례","종중, 배우자, 종교단체 산하 조직 명의 등기는 조세 포탈·강제집행 면탈·법령상 제한 회피 목적이 없으면 제4조~제7조 적용 제외","실명법 제8조"]]}],"함정":"계약명의신탁은 계약 체결 당시 매도인의 인식으로 소유권이 갈린다. 선의면 수탁자 명의 등기가 유효하고, 악의면 무효다. 등기할 때 알게 된 경우는 기준이 아니다. 선의일 때 신탁자가 청구할 수 있는 것은 부동산이 아니라 매수자금이다."}},{"i":"S5-2-1-중개사법-36","r":"S5","g":2,"c":2,"n":36,"s":"중개사법","q":"개업공인중개사가 상가건물을 임차하려는 중개의뢰인 甲에게 ｢상가건물 임대차보호법｣의 내용에 관하여 설명한 것으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["甲이 건물을 인도 받고 ｢부가가치세법｣에 따른 사업자등록을 신청하면 그 다음 날부터 대항력이 생긴다.","확정일자는 건물의 소재지 관할 세무서장이 부여한다.","임대차계약을 체결하려는 甲은 임대인의 동의를 받아 관할 세무서장에게 건물의 확정일자 부여일 등 관련 정보의 제공을 요청할 수 있다.","甲이 거짓이나 그 밖의 부정한 방법으로 임차한 경우 임대인은 甲의 계약갱신요구를 거절할 수 있다.","건물의 경매 시 甲은 환가대금에서 우선변제권에 따른 보증금을 지급받은 이후에 건물을 양수인에게 인도하면 된다."],"a":[5],"L":"중3-2","o":"기출","x":{"한줄":"임차인은 건물을 양수인에게 인도하지 않으면 우선변제 보증금을 받을 수 없다(상가법 제5조제3항).","근거":[{"법령":"상가건물 임대차보호법","조문":"제3조제1항","원문":"① 임대차는 그 등기가 없는 경우에도 임차인이 건물의 인도와 「부가가치세법」 제8조, 「소득세법」 제168조 또는 「법인세법」 제111조에 따른 사업자등록을 신청하면 그 다음 날부터 제3자에 대하여 효력이 생긴다."},{"법령":"상가건물 임대차보호법","조문":"제4조제1항·제4항","원문":"① 제5조제2항의 확정일자는 상가건물의 소재지 관할 세무서장이 부여한다.\n④ 임대차계약을 체결하려는 자는 임대인의 동의를 받아 관할 세무서장에게 제3항에 따른 정보제공을 요청할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제10조제1항제2호","원문":"① 임대인은 임차인이 임대차기간이 만료되기 6개월 전부터 1개월 전까지 사이에 계약갱신을 요구할 경우 정당한 사유 없이 거절하지 못한다. 다만, 다음 각 호의 어느 하나의 경우에는 그러하지 아니하다.\n2. 임차인이 거짓이나 그 밖의 부정한 방법으로 임차한 경우"},{"법령":"상가건물 임대차보호법","조문":"제5조제2항·제3항","원문":"② 제3조제1항의 대항요건을 갖추고 관할 세무서장으로부터 임대차계약서상의 확정일자를 받은 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매 시 임차건물(임대인 소유의 대지를 포함한다)의 환가대금에서 후순위권리자나 그 밖의 채권자보다 우선하여 보증금을 변제받을 권리가 있다.\n③ 임차인은 임차건물을 양수인에게 인도하지 아니하면 제2항에 따른 보증금을 받을 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"건물의 인도와 사업자등록 신청을 하면 그 다음 날부터 제3자에 대하여 효력이 생긴다(제3조제1항)."},{"번호":2,"판정":"옳음","설명":"확정일자는 상가건물 소재지 관할 세무서장이 부여한다(제4조제1항)."},{"번호":3,"판정":"옳음","설명":"임대차계약을 체결하려는 자는 임대인의 동의를 받아 관할 세무서장에게 정보제공을 요청할 수 있다(제4조제4항)."},{"번호":4,"판정":"옳음","설명":"거짓이나 부정한 방법으로 임차한 경우는 갱신요구 거절 사유다(제10조제1항제2호)."},{"번호":5,"판정":"틀림","설명":"순서가 반대다. 건물을 양수인에게 인도해야 우선변제 보증금을 받을 수 있다(제5조제3항)."}],"개념":[{"종류":"비교","제목":"주택임대차와 상가임대차","왼쪽":{"이름":"주택임대차보호법","항목":["대항요건: 주택의 인도 + 주민등록(전입신고)","확정일자: 읍·면사무소, 동 주민센터, 법원·등기소, 공증인 등","최단 기간 2년","갱신요구: 만료 6개월~2개월 전, 1회, 2년","차임 연체 2기: 갱신 거절·갱신요구 거절 사유","묵시적 갱신: 임대인이 6개월~2개월 전 통지 안 하면 2년"]},"오른쪽":{"이름":"상가건물 임대차보호법","항목":["대항요건: 건물의 인도 + 사업자등록 신청","확정일자: 관할 세무서장","최단 기간 1년","갱신요구: 만료 6개월~1개월 전, 전체 임대차기간 10년 이내","차임 연체 3기: 갱신요구 거절·해지 사유","묵시적 갱신: 임대인이 6개월~1개월 전 통지 안 하면 1년"]}},{"종류":"표","제목":"우선변제와 소멸","머리":["항목","상가건물 임대차보호법"],"행":[["우선변제권 요건","대항요건 + 관할 세무서장의 확정일자(제5조제2항)"],["보증금을 받을 때","건물을 양수인에게 인도해야 함(제5조제3항)"],["경매 시 임차권","매각되면 소멸, 보증금이 전액 변제되지 않은 대항력 있는 임차권은 제외(제8조)"],["임차권등기명령","임대차 종료 후 보증금 미반환 시 신청, 등기 후 대항력·우선변제권 유지(제6조)"],["소액보증금 보호","경매신청 등기 전에 대항요건을 갖추면 보증금 중 일정액을 우선변제(제14조)"]]}],"함정":"우선변제를 받는 순서가 인도 → 보증금 수령이다. 경매 환가대금을 먼저 받고 나중에 인도해도 된다는 문장은 제5조제3항과 반대다. 갱신거절 사유(거짓 임차, 3기 연체)와 숫자는 주택법과 맞바꿔 내기 쉽다."}},{"i":"S5-2-1-중개사법-37","r":"S5","g":2,"c":2,"n":37,"s":"중개사법","q":"甲은 乙 소유 X토지를 매수하면서 세금을 줄이기 위해 甲과 丙 사이의 명의신탁약정에 따라 乙이 丙 앞으로 직접 소유권이전등기를 해 주기로 하였고, 乙에서 丙에게 이전등기가 마쳐졌다. 이에 관하여 개업공인중개사가 甲과 乙에게 설명한 내용으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 丙 사이의 명의신탁약정은 유효하다.","乙에서 丙에게 마쳐진 소유권이전등기는 유효하여 丙이 X토지의 소유권을 취득한다.","丙이 X토지를 丁에게 처분하고 소유권이전등기를 마친 경우, 丁이 명의신탁약정 사실을 알고 있었더라도 丁은 소유권을 취득한다.","「부동산 실권리자명의 등기에 관한 법률」에 따른 과징금은 명의수탁자인 丙에게 부과하고 甲에게는 부과하지 않는다.","甲은 丙을 상대로 X토지의 소유권이전등기를 직접 청구할 수 있다."],"a":[3],"L":"중3-2","o":"변형","x":{"한줄":"수탁자가 처분한 부동산을 취득한 제3자는 선의·악의를 묻지 않고 유효하게 소유권을 취득한다(실명법 제4조제3항).","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제1항~제3항","원문":"① 명의신탁약정은 무효로 한다.\n② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다.\n③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제5조제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 자에게는 해당 부동산 가액(價額)의 100분의 30에 해당하는 금액의 범위에서 과징금을 부과한다.\n1. 제3조제1항을 위반한 명의신탁자\n2. 제3조제2항을 위반한 채권자 및 같은 항에 따른 서면에 채무자를 거짓으로 적어 제출하게 한 실채무자(實債務者)"},{"판례":"3자간 등기명의신탁에서 신탁자의 구제(대법원 판례)","요지":"약정과 수탁자 명의 등기가 무효라 소유권은 매도인에게 남는다. 매매계약은 유효하므로 신탁자는 매도인에게 이전등기를 청구하고, 매도인을 대위해 수탁자 명의 등기의 말소를 구한다. 수탁자에게 직접 이전등기를 청구할 수는 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"명의신탁약정은 무효다(실명법 제4조제1항)."},{"번호":2,"판정":"틀림","설명":"매도인(乙)이 계약의 당사자이고 수탁자(丙)는 당사자가 아니므로 단서가 적용되지 않는다. 丙 명의 등기는 무효이고 소유권은 乙에게 남는다(실명법 제4조제2항)."},{"번호":3,"판정":"옳음","설명":"약정·등기의 무효는 제3자에게 대항하지 못한다. 丁이 악의여도 소유권을 취득한다(실명법 제4조제3항)."},{"번호":4,"판정":"틀림","설명":"과징금은 명의신탁자에게 부과한다. 수탁자는 과징금 대상이 아니다(실명법 제5조제1항제1호)."},{"번호":5,"판정":"틀림","설명":"소유권이 乙에게 있어 丙에게는 이전등기를 청구할 원인이 없다. 甲은 乙에게 매매계약상 이전등기를 청구한다(판례)."}],"개념":[{"종류":"비교","제목":"3자간 등기명의신탁과 계약명의신탁","왼쪽":{"이름":"3자간 등기명의신탁","항목":["매매계약의 당사자: 매도인과 신탁자","수탁자 명의 등기는 무효","소유권은 매도인에게 남음","신탁자는 매도인에게 이전등기 청구, 매도인을 대위해 수탁자 등기 말소","수탁자가 처분하면 제3자는 선의·악의 불문 취득"]},"오른쪽":{"이름":"계약명의신탁","항목":["매매계약의 당사자: 매도인과 수탁자","매도인이 계약 당시 선의면 수탁자 명의 등기 유효","소유권은 수탁자(선의) 또는 매도인(악의)","신탁자는 부동산이 아니라 매수자금을 부당이득으로 청구","수탁자가 처분하면 제3자는 선의·악의 불문 취득"]}},{"종류":"흐름","제목":"3자간 등기명의신탁에서 권리를 찾는 순서","단계":[{"이름":"약정·등기","설명":"甲·丙의 약정은 무효, 乙에서 丙으로의 등기도 무효(제4조제1항·제2항)"},{"이름":"소유권","설명":"X토지의 소유자는 여전히 乙"},{"이름":"신탁자의 청구","설명":"甲이 乙에게 매매계약상 이전등기를 청구하고, 乙을 대위해 丙 명의 등기의 말소를 구함(판례)"},{"이름":"제재","설명":"甲에게 부동산 가액의 100분의 30 범위의 과징금(제5조제1항), 자기 명의 등기 의무와 이행강제금(제6조)"},{"이름":"제3자","설명":"丙이 처분한 상대 丁은 선의·악의를 묻지 않고 소유권 취득(제4조제3항)"}]}],"함정":"처음 두 선지는 약정이 유효하다거나 수탁자가 소유권을 얻는다는 문장이다. 이는 계약명의신탁에서 매도인이 선의일 때의 결론이다. 3자간 등기명의신탁에서는 계약 당사자가 매도인과 신탁자라 소유권이 매도인에게 남는다. 과징금은 수탁자가 아니라 신탁자에게 부과한다."}},{"i":"S5-2-1-중개사법-38","r":"S5","g":2,"c":2,"n":38,"s":"중개사법","q":"개업공인중개사가 선순위 저당권이 설정되어 있는 서울시 소재 상가건물(상가건물 임대차보호법이 적용됨)에 대해 임대차기간 2026.10.1.부터 1년, 보증금 5천만원, 월차임 100만원으로 임대차를 중개하면서 임대인 甲과 임차인 乙에게 설명한 내용으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["乙의 연체차임액이 200만원에 이르는 경우 甲은 계약을 해지할 수 있다.","차임 또는 보증금의 감액이 있은 후 1년 이내에는 다시 감액을 하지 못한다.","甲이 임대차기간 만료 6개월 전부터 1개월 전까지 사이에 乙에게 갱신 거절 또는 조건 변경의 통지를 하지 않은 경우, 임대차기간 만료일에 임대차계약이 해지된 것으로 본다.","상가건물에 대한 경매개시결정 등기 전에 乙이 건물의 인도와 사업자등록 신청을 한 때에는, 보증금 중 일정액을 선순위 저당권자보다 우선하여 변제받을 수 있다.","乙의 계약갱신요구권은 최초의 임대차기간을 포함한 전체 임대차기간이 10년을 초과하지 않는 범위에서만 행사할 수 있다."],"a":[5],"L":"중3-2","o":"변형","x":{"한줄":"계약갱신요구권은 최초의 임대차기간을 포함해 전체 10년 이내에서만 행사할 수 있다(상가법 제10조제2항).","근거":[{"법령":"상가건물 임대차보호법","조문":"제10조의8","원문":"임차인의 차임연체액이 3기의 차임액에 달하는 때에는 임대인은 계약을 해지할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제11조제1항·제2항","원문":"① 차임 또는 보증금이 임차건물에 관한 조세, 공과금, 그 밖의 부담의 증감이나 「감염병의 예방 및 관리에 관한 법률」 제2조제2호에 따른 제1급감염병 등에 의한 경제사정의 변동으로 인하여 상당하지 아니하게 된 경우에는 당사자는 장래의 차임 또는 보증금에 대하여 증감을 청구할 수 있다. 그러나 증액의 경우에는 대통령령으로 정하는 기준에 따른 비율을 초과하지 못한다.\n② 제1항에 따른 증액 청구는 임대차계약 또는 약정한 차임 등의 증액이 있은 후 1년 이내에는 하지 못한다."},{"법령":"상가건물 임대차보호법","조문":"제10조제2항·제4항","원문":"② 임차인의 계약갱신요구권은 최초의 임대차기간을 포함한 전체 임대차기간이 10년을 초과하지 아니하는 범위에서만 행사할 수 있다.\n④ 임대인이 제1항의 기간 이내에 임차인에게 갱신 거절의 통지 또는 조건 변경의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 이 경우에 임대차의 존속기간은 1년으로 본다."},{"법령":"상가건물 임대차보호법","조문":"제14조제1항","원문":"① 임차인은 보증금 중 일정액을 다른 담보물권자보다 우선하여 변제받을 권리가 있다. 이 경우 임차인은 건물에 대한 경매신청의 등기 전에 제3조제1항의 요건을 갖추어야 한다."},{"법령":"상가건물 임대차보호법 시행령","조문":"제2조제1항제1호·제3항","원문":"①「상가건물 임대차보호법」(이하 \"법\"이라 한다) 제2조제1항 단서에서 \"대통령령으로 정하는 보증금액\"이란 다음 각 호의 구분에 의한 금액을 말한다.\n1. 서울특별시 : 9억원\n③법 제2조제2항에서 \"대통령령으로 정하는 비율\"이라 함은 1분의 100을 말한다."},{"법령":"상가건물 임대차보호법 시행령","조문":"제6조제1호","원문":"법 제14조의 규정에 의하여 우선변제를 받을 임차인은 보증금과 차임이 있는 경우 법 제2조제2항의 규정에 의하여 환산한 금액의 합계가 다음 각호의 구분에 의한 금액 이하인 임차인으로 한다.\n1. 서울특별시 : 6천500만원"}],"선지":[{"번호":1,"판정":"틀림","설명":"월차임이 100만원이므로 해지 사유는 3기분인 300만원에 이를 때다. 200만원은 2기분이다(제10조의8)."},{"번호":2,"판정":"틀림","설명":"1년 제한은 증액 청구에만 있다. 증액이 있은 후 1년 이내에는 증액하지 못한다. 감액은 제한이 없다(제11조제2항)."},{"번호":3,"판정":"틀림","설명":"통지하지 않으면 해지되는 것이 아니라 전 임대차와 동일한 조건으로 다시 임대차한 것으로 보고, 존속기간은 1년이다(제10조제4항)."},{"번호":4,"판정":"틀림","설명":"환산보증금이 1억 5천만원(5천만원 + 100만원 × 100)이라 서울 기준 6,500만원을 넘어 소액임차인이 아니다. 최우선변제를 받지 못한다(제14조, 시행령 제6조)."},{"번호":5,"판정":"옳음","설명":"전체 임대차기간 10년 이내라는 제한은 법 제10조제2항 그대로다."}],"개념":[{"종류":"계산","제목":"환산보증금과 적용 범위","단계":[{"설명":"환산보증금 = 보증금 + 월 차임 × 100(영 제2조제3항)","식":"5천만원 + 100만원 × 100","값":"1억 5천만원"},{"설명":"법 적용 범위: 서울 9억원 이하인지(영 제2조제1항제1호)","식":"1억 5천만원 ≤ 9억원","값":"적용"},{"설명":"소액임차인 범위: 서울 6,500만원 이하인지(영 제6조제1호)","식":"1억 5천만원 > 6,500만원","값":"소액임차인 아님, 최우선변제 불가"}]},{"종류":"표","제목":"상가임대차의 기간과 증감","머리":["항목","내용","근거"],"행":[["최단 기간","기간을 정하지 않거나 1년 미만이면 1년으로 봄(임차인은 짧은 기간 주장 가능)","제9조제1항"],["갱신요구","만료 6개월 전부터 1개월 전까지, 전체 10년 이내","제10조제1항·제2항"],["묵시적 갱신","통지 없으면 같은 조건으로 갱신, 존속기간 1년","제10조제4항"],["차임 연체","3기분에 달하면 임대인이 해지 가능","제10조의8"],["증액 청구","청구 당시 금액의 100분의 5 초과 불가, 증액 후 1년 이내 재증액 불가","제11조제2항, 영 제4조"],["월차임 전환","연 12%와 기준금리 × 4.5 중 낮은 비율","제12조, 영 제5조"]]}],"함정":"숫자만 바꾼 선지가 많다. 연체 해지는 3기(주택은 2기)이고, 1년 제한은 증액에만 있다. 소액임차인 판단은 보증금이 아니라 월차임을 100배해서 더한 환산보증금으로 한다. 환산보증금이 기준을 넘어도 계약갱신요구권은 보장된다."}},{"i":"S5-2-1-중개사법-39","r":"S5","g":2,"c":2,"n":39,"s":"중개사법","q":"甲은 매수신청대리인으로 등록한 개업공인중개사 乙에게 「민사집행법」에 의한 경매대상 부동산에 대한 매수신청대리의 위임을 하였다. 이에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["乙은 매수신청대리를 하는 경우 매각장소 또는 집행법원에 乙 본인 또는 소속 중개보조원이 출석하면 된다.","乙은 「민사집행법」에 따른 공유자의 우선매수신고를 할 수 있다.","乙은 매수신청대리 대상물의 확인·설명 사항을 서면으로 작성하여 서명날인한 후 甲에게 교부하고, 그 사본을 사건카드에 철하여 5년간 보존해야 한다.","乙이 중개업을 휴업한 경우 관할 지방법원장은 乙에 대하여 기간을 정하여 매수신청대리업무를 정지하는 처분을 하여야 한다.","乙은 매수신청대리인이 된 사건에서 매수신청인으로서 매수신청을 할 수 없다."],"a":[1],"L":"중3-3","o":"변형","x":{"한줄":"매수신청대리는 매각장소 또는 집행법원에 개업공인중개사가 직접 출석해서 해야 하며, 중개보조원을 대신 보낼 수 없다(규칙 제14조제3항).","근거":[{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제14조제3항","원문":"③개업공인중개사는 제2조의 규정에 따른 대리행위를 함에 있어서 매각장소 또는 집행법원에 직접 출석하여야 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제2조제5호","원문":"법원에 매수신청대리인으로 등록된 개업공인중개사가 매수신청대리의 위임을 받은 경우 다음 각 호의 행위를 할 수 있다.\n5. 「민사집행법」 제140조의 규정에 따른 공유자의 우선매수신고"},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제16조제2항","원문":"②개업공인중개사는 위임계약을 체결한 경우 제1항의 확인ㆍ설명 사항을 서면으로 작성하여 서명날인한 후 위임인에게 교부하고, 그 사본을 사건카드에 철하여 5년간 보존하여야 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제22조제1항제1호","원문":"①지방법원장은 개업공인중개사(이 경우 분사무소를 포함한다)가 다음 각 호의 어느 하나에 해당하는 경우에는 기간을 정하여 매수신청대리업무를 정지하는 처분을 하여야 한다.\n1. 법 제21조 또는 이 규칙 제13조의2제1항의 규정에 따라 휴업하였을 경우"},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제18조제5항제2호","원문":"⑤개업공인중개사는 다음 각 호의 행위를 하여서는 아니된다.\n2. 매수신청대리인이 된 사건에 있어서 매수신청인으로서 매수신청을 하는 행위"}],"선지":[{"번호":1,"판정":"틀림","설명":"乙이 직접 출석해야 한다. 중개보조원이 대신 출석할 수 없다(규칙 제14조제3항)."},{"번호":2,"판정":"옳음","설명":"공유자의 우선매수신고는 대리권의 범위에 속한다(규칙 제2조제5호)."},{"번호":3,"판정":"옳음","설명":"확인·설명서를 서면으로 작성해 서명날인한 뒤 위임인에게 교부하고, 사본을 사건카드에 철해 5년간 보존한다(규칙 제16조제2항)."},{"번호":4,"판정":"옳음","설명":"휴업은 매수신청대리업무정지를 하여야 하는 사유다. 등록취소 사유가 아니다(규칙 제22조제1항제1호)."},{"번호":5,"판정":"옳음","설명":"매수신청대리인이 된 사건에서 매수신청인으로서 매수신청을 하는 행위는 금지행위다(규칙 제18조제5항제2호)."}],"개념":[{"종류":"표","제목":"매수신청대리 등록취소와 업무정지","머리":["사유","처분","근거"],"행":[["폐업신고","등록취소(필요적)","규칙 제21조제1항제2호"],["공인중개사 자격취소","등록취소(필요적)","규칙 제21조제1항제3호"],["중개사무소 개설등록 취소","등록취소(필요적)","규칙 제21조제1항제4호"],["사건카드 미작성·미보존, 확인·설명서 미교부·미보존","등록취소(임의적)","규칙 제21조제2항제3호·제4호"],["휴업","업무정지(필요적)","규칙 제22조제1항제1호"],["공인중개사 자격정지","업무정지(필요적)","규칙 제22조제1항제2호"],["중개업무정지","업무정지(필요적)","규칙 제22조제1항제3호"],["등록증 등 미게시","업무정지(임의적)","규칙 제22조제2항제2호"]]},{"종류":"표","제목":"지방법원장에게 10일 이내 신고하는 사유(규칙 제18조제4항)","머리":["사유","근거"],"행":[["중개사무소 이전","제1호"],["중개업 휴업 또는 폐업","제2호"],["공인중개사 자격취소","제3호"],["공인중개사 자격정지","제4호"],["중개사무소 개설등록 취소","제5호"],["중개업무 정지","제6호"],["분사무소 설치","제7호"]]}],"함정":"28회 기출은 중개업 휴업을 등록취소 사유로 바꿔 틀린 선지로 냈다. 휴업은 업무정지(필요적), 폐업신고는 등록취소(필요적)다. 대리행위는 개업공인중개사가 직접 출석해야 하므로 소속 중개보조원을 보내는 문장은 틀리다."}},{"i":"S5-2-1-중개사법-40","r":"S5","g":2,"c":2,"n":40,"s":"중개사법","q":"개업공인중개사 甲은 ｢공인중개사의 매수신청대리인등록 등에 관한 규칙｣에 따라 매수신청대리인으로 등록한 후 乙과 매수신청대리에 관한 위임계약을 체결하였다. 이에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["甲이 법인이고 분사무소를 1개 둔 경우 매수신청대리에 따른 손해배상책임을 보장하기 위하여 설정해야 하는 보증의 금액은 6억원 이상이다.","甲은 매수신청대리 사건카드에 乙에게서 위임받은 사건에 관한 사항을 기재하고 서명날인 한 후 이를 3년간 보존해야 한다.","甲은 매수신청대리 대상물에 대한 확인ㆍ설명 사항을 서면으로 작성하여 사건카드에 철하여 3년간 보존해야 하며 乙에게 교부할 필요는 없다.","등기사항증명서는 甲이 乙에게 제시할 수 있는 매수신청대리 대상물에 대한 설명의 근거자료에 해당하지 않는다.","甲이 중개사무소를 이전한 경우 14일 이내에 乙에게 통지하고 지방법원장에게 그 사실을 신고해야 한다."],"a":[1],"L":"중3-3","o":"기출","x":{"한줄":"법인은 4억원 이상이고 분사무소마다 2억원 이상을 추가하므로, 분사무소 1개면 6억원 이상이다(규칙 제13조제1항제1호).","근거":[{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제13조제1항","원문":"①개업공인중개사가 제11조제2항의 규정에 따른 손해배상책임을 보장하기 위한 보증을 설정하여야 하는 금액은 다음 각 호와 같다.\n1. 법인인 개업공인중개사 : 4억 원 이상. 다만, 분사무소를 두는 경우에는 분사무소마다 2억 원 이상을 추가로 설정하여야 한다.\n2. 법인이 아닌 개업공인중개사 : 2억 원 이상"},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제15조제1항","원문":"①개업공인중개사는 매수신청대리 사건카드를 비치하고, 사건을 위임받은 때에는 사건카드에 위임받은 순서에 따라 일련번호, 경매사건번호, 위임받은 연월일, 보수액과 위임인의 주소ㆍ성명 기타 필요한 사항을 기재하고, 서명날인 한 후 5년간 이를 보존하여야 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제16조제1항·제2항","원문":"①개업공인중개사가 매수신청대리를 위임받은 경우 매수신청대리 대상물의 권리관계, 경제적 가치, 매수인이 부담하여야 할 사항 등에 대하여 위임인에게 성실ㆍ정확하게 설명하고 등기사항증명서 등 설명의 근거자료를 제시하여야 한다.\n②개업공인중개사는 위임계약을 체결한 경우 제1항의 확인ㆍ설명 사항을 서면으로 작성하여 서명날인한 후 위임인에게 교부하고, 그 사본을 사건카드에 철하여 5년간 보존하여야 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제18조제4항제1호","원문":"④개업공인중개사는 다음 각 호의 어느 하나에 해당하는 경우에는 그 사유가 발생한 날로부터 10일 이내에 지방법원장에게 그 사실을 신고하여야 한다.\n1. 중개사무소를 이전한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"법인 4억원 + 분사무소 1개 2억원 = 6억원 이상이다(규칙 제13조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"사건카드의 보존기간은 5년이다(규칙 제15조제1항)."},{"번호":3,"판정":"틀림","설명":"확인·설명 사항은 서면으로 작성해 위임인에게 교부하고, 사본을 사건카드에 철해 5년간 보존한다(규칙 제16조제2항)."},{"번호":4,"판정":"틀림","설명":"등기사항증명서는 설명의 근거자료로 예시된 자료다(규칙 제16조제1항)."},{"번호":5,"판정":"틀림","설명":"사무소를 이전하면 10일 이내에 지방법원장에게 신고한다. 위임인에게 통지하라는 규정은 없다(규칙 제18조제4항제1호)."}],"개념":[{"종류":"계산","제목":"매수신청대리 보증금액","단계":[{"설명":"법인이 아닌 개업공인중개사","식":"기본 2억원 이상","값":"2억원 이상"},{"설명":"법인인 개업공인중개사","식":"기본 4억원 이상","값":"4억원 이상"},{"설명":"법인에 분사무소를 두는 경우","식":"4억원 + 2억원 × 분사무소 수","값":"분사무소 1개: 6억원 이상, 2개: 8억원 이상"}]},{"종류":"표","제목":"매수신청대리 규칙의 숫자","머리":["사항","내용","근거"],"행":[["사건카드 보존","서명날인 후 5년","규칙 제15조제1항"],["확인·설명서 사본","사건카드에 철하여 5년 보존, 위임인에게 교부","규칙 제16조제2항"],["신고 기한","사무소 이전·휴업·폐업·자격취소·정지 등은 사유 발생일부터 10일 이내 지방법원장에게","규칙 제18조제4항"],["실무교육","등록신청일 전 1년 이내에 이수","규칙 제10조제1항"],["공탁금 회수","폐업, 사망, 해산한 날부터 3년 이내 회수 불가","규칙 제11조제3항"],["업무정지 기간","1월 이상 2년 이하","규칙 제22조제3항"]]}],"함정":"숫자 선지가 섞여 있다. 사건카드와 확인·설명서 사본은 5년(일반 중개의 확인·설명서 보존기간 3년과 혼동하기 쉽다), 신고는 10일에 지방법원장이다. 설명의 근거자료에 등기사항증명서가 빠진다는 문장도 틀리다."}},{"i":"S5-2-1-공법-01","r":"S5","g":2,"c":2,"n":41,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 도시·군기본계획에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["광역시장이 도시·군기본계획을 수립하려면 미리 국토교통부장관의 승인을 받아야 한다.","시장 또는 군수가 도시·군기본계획을 수립하려면 미리 그 시 또는 군 의회의 동의를 받아야 한다.","시장은 지역여건상 필요하면 인접한 군의 관할 구역 일부를 포함하여 도시·군기본계획을 수립할 수 있으며, 이 경우 미리 그 군수와 협의하여야 한다.","도지사가 시장·군수의 도시·군기본계획을 승인하려면 관계 행정기관의 장과 협의한 후 중앙도시계획위원회의 심의를 거쳐야 한다.","수도권에 속하지 아니하고 광역시와 경계를 같이하지 아니한 시 또는 군으로서 인구 20만명 이하인 시 또는 군은 도시·군기본계획을 수립하지 아니할 수 있다."],"a":[3],"L":"공1-1","o":"변형","x":{"한줄":"시장이 인접한 군의 관할 구역을 포함해 도시·군기본계획을 수립하려면 미리 그 군수와 협의해야 한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제18조제2항","원문":"② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 지역여건상 필요하다고 인정되면 인접한 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역 전부 또는 일부를 포함하여 도시ㆍ군기본계획을 수립할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제18조제3항","원문":"③ 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 제2항에 따라 인접한 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역을 포함하여 도시ㆍ군기본계획을 수립하려면 미리 그 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수와 협의하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제21조제1항","원문":"① 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 도시ㆍ군기본계획을 수립하거나 변경하려면 미리 그 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군 의회의 의견을 들어야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제22조제1항","원문":"① 특별시장ㆍ광역시장ㆍ특별자치시장 또는 특별자치도지사는 도시ㆍ군기본계획을 수립하거나 변경하려면 관계 행정기관의 장(국토교통부장관을 포함한다. 이하 이 조 및 제22조의2에서 같다)과 협의한 후 지방도시계획위원회의 심의를 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제22조의2제2항","원문":"② 도지사는 제1항에 따라 도시ㆍ군기본계획을 승인하려면 관계 행정기관의 장과 협의한 후 지방도시계획위원회의 심의를 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제14조제1호","원문":"1. 「수도권정비계획법」 제2조제1호의 규정에 의한 수도권(이하 \"수도권\"이라 한다)에 속하지 아니하고 광역시와 경계를 같이하지 아니한 시 또는 군으로서 인구 10만명 이하인 시 또는 군"}],"선지":[{"번호":1,"판정":"틀림","설명":"특별시장·광역시장·특별자치시장·특별자치도지사는 관계 행정기관의 장(국토교통부장관 포함)과 협의한 뒤 지방도시계획위원회의 심의를 거쳐 직접 확정한다. 승인 절차는 없다(법 제22조제1항)."},{"번호":2,"판정":"틀림","설명":"지방의회는 동의 대상이 아니다. 수립·변경 전에 그 시·군 의회의 의견을 들으면 되고, 의회는 특별한 사유가 없으면 30일 이내에 의견을 낸다(법 제21조제1항·제2항)."},{"번호":3,"판정":"옳음","설명":"인접한 시·군의 관할 구역 전부 또는 일부를 포함해 수립할 수 있고, 그때는 미리 그 시장·군수와 협의한다(법 제18조제2항·제3항)."},{"번호":4,"판정":"틀림","설명":"도지사의 승인 절차에서 거치는 위원회는 지방도시계획위원회이다. 중앙도시계획위원회가 아니다(법 제22조의2제2항)."},{"번호":5,"판정":"틀림","설명":"수립을 생략할 수 있는 시·군은 수도권 밖이고 광역시와 경계를 같이하지 않는 인구 10만명 이하의 시·군이다. 20만명이 아니다(영 제14조제1호)."}],"개념":[{"종류":"표","제목":"광역도시계획과 도시·군기본계획 비교","머리":["구분","광역도시계획","도시·군기본계획"],"행":[["대상","광역계획권(인접한 둘 이상 시·군 등)","특별시·광역시·특별자치시·특별자치도·시·군 관할 구역"],["수립권자","국토교통부장관, 시·도지사, 시장·군수(제11조제1항)","특별시장·광역시장·특별자치시장·특별자치도지사·시장·군수(제18조제1항)"],["승인·확정","시·도지사 수립은 국토교통부장관 승인, 시장·군수 수립은 도지사 승인(제16조제1항·제5항)","특별시장·광역시장 등은 협의·심의 후 직접 확정(제22조), 시장·군수는 도지사 승인(제22조의2)"],["협의·심의","관계 중앙행정기관 협의 후 중앙도시계획위원회 심의(도지사 승인은 지방도시계획위원회)","관계 행정기관 협의 후 지방도시계획위원회 심의"],["지방의회 의견","관계 시·도, 시·군 의회와 관계 시장·군수 의견(제15조)","해당 시·군 의회 의견(제21조)"],["정비","-","5년마다 타당성 전반 재검토·정비(제23조제1항)"]]},{"종류":"흐름","제목":"도시·군기본계획 수립 절차","단계":[{"이름":"기초조사","설명":"토지적성평가·재해취약성분석 포함(제20조제2항), 입안일부터 5년 이내 실시한 경우 등은 생략 가능(제20조제3항)"},{"이름":"공청회","설명":"주민과 관계 전문가 의견 청취(제20조제1항, 제14조 준용)"},{"이름":"지방의회 의견 청취","설명":"수립·변경 전 해당 의회 의견, 의회는 30일 이내 제시(제21조)"},{"이름":"협의·심의","설명":"관계 행정기관 협의, 지방도시계획위원회 심의"},{"이름":"확정·승인","설명":"특별시장·광역시장 등은 직접 확정, 시장·군수는 도지사 승인(제22조, 제22조의2)"},{"이름":"공고·열람","설명":"관계 서류 송부 후 공고하고 일반인에게 열람(제22조제3항, 제22조의2제4항)"},{"이름":"정비","설명":"5년마다 타당성 재검토(제23조제1항)"}]}],"함정":"특별시장·광역시장 등은 협의와 심의만 거쳐 직접 확정하고, 도지사 승인이 필요한 쪽은 시장·군수의 계획이다. 지방의회는 동의가 아니라 의견 청취 대상이다. 도지사 승인 단계의 심의 기관은 지방도시계획위원회이다. 수립을 생략할 수 있는 기준은 인구 10만명 이하이다."}},{"i":"S5-2-1-공법-02","r":"S5","g":2,"c":2,"n":42,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 시장 또는 군수가 도시ㆍ군기본계획의 승인을 받으려 할 때, 도시ㆍ군기본계획안에 첨부하여야 할 서류에 해당하는 것은?","b":null,"bs":"없음","img":[],"ch":["기초조사 결과","청문회의 청문조서","해당 시ㆍ군 및 도의 의회의 심의ㆍ의결 결과","해당 시ㆍ군 및 도의 지방도시계획위원회의 심의 결과","관계 중앙행정기관의 장과의 협의 및 중앙도시계획위원회의 심의에 필요한 서류"],"a":[1],"L":"공1-1","o":"기출","x":{"한줄":"시장·군수가 도지사에게 기본계획 승인을 신청할 때 기초조사 결과를 첨부한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제17조제1항","원문":"①시장 또는 군수는 법 제22조의2제1항에 따라 도시ㆍ군기본계획의 승인을 받으려면 도시ㆍ군기본계획안에 다음 각 호의 서류를 첨부하여 도지사에게 제출하여야 한다. 1. 기초조사 결과 2. 공청회개최 결과 3. 법 제21조에 따른 해당 시ㆍ군의 의회의 의견청취 결과 4. 해당 시ㆍ군에 설치된 지방도시계획위원회의 자문을 거친 경우에는 그 결과 5. 법 제22조의2제2항에 따른 관계 행정기관의 장과의 협의 및 도의 지방도시계획위원회의 심의에 필요한 서류"}],"선지":[{"번호":1,"판정":"옳음","설명":"첨부서류의 첫째가 기초조사 결과이다(영 제17조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"첨부하는 것은 공청회개최 결과이다. 청문조서는 해당하지 않는다(영 제17조제1항제2호). 청문은 개발행위허가 취소 등 처분에서 하는 절차이다(법 제136조)."},{"번호":3,"판정":"틀림","설명":"의회 관련 서류는 해당 시·군 의회의 의견청취 결과이다. 도의 의회는 관계가 없고 심의·의결 결과도 아니다(영 제17조제1항제3호)."},{"번호":4,"판정":"틀림","설명":"시·군 지방도시계획위원회는 자문을 거친 경우의 그 결과만 첨부한다. 도의 지방도시계획위원회는 심의 결과가 아니라 그 심의에 필요한 서류를 낸다(영 제17조제1항제4호·제5호)."},{"번호":5,"판정":"틀림","설명":"협의 상대는 관계 행정기관의 장이고, 심의 기관은 도의 지방도시계획위원회이다. 중앙도시계획위원회가 아니다(영 제17조제1항제5호, 법 제22조의2제2항)."}],"개념":[{"종류":"표","제목":"시장·군수 도시·군기본계획 승인 신청 첨부서류","머리":["호","서류","근거"],"행":[["1","기초조사 결과","영 제17조제1항제1호"],["2","공청회개최 결과","같은 항 제2호"],["3","해당 시·군 의회의 의견청취 결과","같은 항 제3호, 법 제21조"],["4","해당 시·군 지방도시계획위원회의 자문 결과(자문을 거친 경우)","같은 항 제4호"],["5","관계 행정기관 협의 및 도의 지방도시계획위원회 심의에 필요한 서류","같은 항 제5호, 법 제22조의2제2항"]]},{"종류":"흐름","제목":"시·군 기본계획 승인 후속 절차","단계":[{"이름":"승인 신청","설명":"시장·군수가 첨부서류를 붙여 도지사에게 제출(영 제17조제1항)"},{"이름":"보완 요청","설명":"수립기준 등에 맞지 않으면 도지사가 보완 요청(영 제17조제2항)"},{"이름":"협의·심의","설명":"도지사가 관계 행정기관 협의 후 지방도시계획위원회 심의(법 제22조의2제2항)"},{"이름":"승인·송부","설명":"승인하면 관계 행정기관의 장과 시장·군수에게 관계 서류 송부(법 제22조의2제4항)"},{"이름":"공고·열람","설명":"시·군 공보와 인터넷 홈페이지에 게재, 열람기간 30일 이상(영 제17조제3항)"}]}],"함정":"첨부서류는 영 제17조제1항 다섯 호에 적힌 것뿐이다. 의회 관련 서류는 시·군 의회의 의견청취 결과이고, 위원회 관련 서류는 시·군은 자문 결과, 도는 심의에 필요한 서류이다."}},{"i":"S5-2-1-공법-03","r":"S5","g":2,"c":2,"n":43,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 도시ㆍ군관리계획에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["국토교통부장관은 국가계획과 관련된 경우 직접 도시ㆍ군관리계획을 입안할 수 있다.","주민은 산업ㆍ유통개발진흥지구의 지정에 관한 사항에 대하여 도시ㆍ군관리계획의 입안권자에게 도시ㆍ군관리계획의 입안을 제안할 수 있다.","도시ㆍ군관리계획으로 입안하려는 지구단위계획구역이 상업지역에 위치하는 경우에는 재해취약성분석을 하지 아니할 수 있다.","도시ㆍ군관리계획 결정의 효력은 지형도면을 고시한 다음 날부터 발생한다.","인접한 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역에 대한 도시ㆍ군관리계획은 관계특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수가 협의하여 공동으로 입안하거나 입안할 자를 정한다."],"a":[4],"L":"공1-2","o":"기출","x":{"한줄":"도시·군관리계획 결정의 효력은 지형도면을 고시한 날부터 생기고, 다음 날부터가 아니다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제31조제1항","원문":"① 도시ㆍ군관리계획 결정의 효력은 제32조제4항에 따라 지형도면을 고시한 날부터 발생한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제24조제5항제1호","원문":"⑤ 국토교통부장관은 제1항이나 제2항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 직접 또는 관계 중앙행정기관의 장의 요청에 의하여 도시ㆍ군관리계획을 입안할 수 있다. 이 경우 국토교통부장관은 관할 시ㆍ도지사 및 시장ㆍ군수의 의견을 들어야 한다. 1. 국가계획과 관련된 경우"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제24조제3항","원문":"③ 제2항에 따른 인접한 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역에 대한 도시ㆍ군관리계획은 관계 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수가 협의하여 공동으로 입안하거나 입안할 자를 정한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제26조제1항제3호가목","원문":"3. 다음 각 목의 어느 하나에 해당하는 용도지구의 지정 및 변경에 관한 사항 가. 개발진흥지구 중 공업기능 또는 유통물류기능 등을 집중적으로 개발ㆍ정비하기 위한 개발진흥지구로서 대통령령으로 정하는 개발진흥지구"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제27조제4항","원문":"④ 도시ㆍ군관리계획으로 입안하려는 지역이 도심지에 위치하거나 개발이 끝나 나대지가 없는 등 대통령령으로 정하는 요건에 해당하면 제1항부터 제3항까지의 규정에 따른 기초조사, 환경성 검토, 토지적성평가 또는 재해취약성분석을 하지 아니할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제21조제2항제1호가목·제4호가목","원문":"가. 해당 지구단위계획구역이 도심지(상업지역과 상업지역에 연접한 지역을 말한다)에 위치하는 경우 4. 재해취약성분석을 실시하지 않을 수 있는 요건: 다음 각 목의 어느 하나에 해당하는 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"국가계획과 관련된 경우 국토교통부장관은 직접 입안할 수 있고, 이때 관할 시·도지사와 시장·군수의 의견을 듣는다(법 제24조제5항제1호)."},{"번호":2,"판정":"옳음","설명":"주민은 공업·유통물류 기능을 집중 개발하는 개발진흥지구로서 대통령령으로 정한 산업·유통개발진흥지구의 지정을 제안할 수 있다(법 제26조제1항제3호가목, 영 제19조의2제1항)."},{"번호":3,"판정":"옳음","설명":"도심지(상업지역과 연접 지역)에 위치한 지구단위계획구역은 기초조사와 재해취약성분석을 생략할 수 있다(법 제27조제4항, 영 제21조제2항제1호가목·제4호가목)."},{"번호":4,"판정":"틀림","설명":"효력은 지형도면을 고시한 날부터 발생한다. 다음 날이 아니다(법 제31조제1항)."},{"번호":5,"판정":"옳음","설명":"협의해 공동으로 입안하거나 입안할 자를 정한다(법 제24조제3항)."}],"개념":[{"종류":"흐름","제목":"도시·군관리계획 입안부터 효력 발생까지","단계":[{"이름":"입안","설명":"입안권자는 특별시장~군수, 예외로 국토교통부장관·도지사 직접 입안(법 제24조)"},{"이름":"기초조사","설명":"환경성 검토, 토지적성평가, 재해취약성분석 포함, 도심지 등은 생략 가능(법 제27조)"},{"이름":"주민·지방의회 의견","설명":"주민 의견 청취 후 타당하면 반영, 지방의회 의견 청취(법 제28조)"},{"이름":"협의·심의","설명":"관계 행정기관 협의 30일 이내 의견, 중앙 또는 시·도도시계획위원회 심의(법 제30조)"},{"이름":"결정·고시","설명":"시·도지사 또는 대도시 시장 등이 결정하고 고시(법 제29조, 제30조제6항)"},{"이름":"지형도면 작성·고시","설명":"지적이 표시된 지형도에 도면 작성, 시장·군수는 도지사 승인(법 제32조)"},{"이름":"효력 발생","설명":"지형도면 고시일(법 제31조제1항)"}]},{"종류":"표","제목":"입안 예외 권한","머리":["입안자","요건","의견 청취"],"행":[["국토교통부장관","국가계획 관련, 둘 이상 시·도에 걸친 용도지역·사업 계획, 조정 요구 미이행","관할 시·도지사와 시장·군수 의견"],["도지사","둘 이상 시·군에 걸친 용도지역·사업 계획, 도지사 직접 수립 사업 계획","관계 시장·군수 의견"],["협의 입안","인접 지역을 포함하는 경우 관계 장이 협의해 공동 입안","미성립 시 같은 도는 도지사, 둘 이상 시·도는 국토교통부장관이 입안할 자 지정(법 제24조제4항)"]]}],"함정":"효력은 지형도면을 고시한 날부터 발생하고 다음 날부터가 아니다. 상업지역 등 도심지 요건에 해당하는 지구단위계획구역은 재해취약성분석을 생략할 수 있다.","개정":"2024.2.6. 개정으로 법 제26조제1항제4호가 삭제됐고 제40조의2도 삭제됐다. 입지규제최소구역에 관한 입안 제안 항목은 현행 조문에 없다."}},{"i":"S5-2-1-공법-04","r":"S5","g":2,"c":2,"n":44,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 용도지역에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["용도지역은 토지를 경제적ㆍ효율적으로 이용하기 위하여 필요한 경우 서로 중복되게 지정할 수 있다.","용도지역은 필요한 경우 도시ㆍ군기본계획으로 결정할 수 있다.","주민은 상업지역에 산업ㆍ유통개발진흥지구를 지정하여 줄 것을 내용으로 하는 도시ㆍ군관리계획의 입안을 제안할 수 있다.","바다인 공유수면의 매립구역이 둘 이상의 용도지역과 이웃하고 있는 경우 그 매립구역은 이웃하고 있는 가장 큰 용도지역으로 지정된 것으로 본다.","관리지역에서 ｢농지법｣에 따른 농업진흥지역으로 지정ㆍ고시된 지역은 ｢국토의 계획 및 이용에 관한 법률｣에 따른 농림지역으로 결정ㆍ고시된 것으로 본다."],"a":[5],"L":"공1-3","o":"기출","x":{"한줄":"관리지역의 농업진흥지역은 농림지역으로 결정·고시된 것으로 본다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제42조제2항","원문":"② 관리지역에서 「농지법」에 따른 농업진흥지역으로 지정ㆍ고시된 지역은 이 법에 따른 농림지역으로, 관리지역의 산림 중 「산지관리법」에 따라 보전산지로 지정ㆍ고시된 지역은 그 고시에서 구분하는 바에 따라 이 법에 따른 농림지역 또는 자연환경보전지역으로 결정ㆍ고시된 것으로 본다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제15호","원문":"15. \"용도지역\"이란 토지의 이용 및 건축물의 용도, 건폐율(「건축법」 제55조의 건폐율을 말한다. 이하 같다), 용적률(「건축법」 제56조의 용적률을 말한다. 이하 같다), 높이 등을 제한함으로써 토지를 경제적ㆍ효율적으로 이용하고 공공복리의 증진을 도모하기 위하여 서로 중복되지 아니하게 도시ㆍ군관리계획으로 결정하는 지역을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제36조제1항","원문":"① 국토교통부장관, 시ㆍ도지사 또는 대도시 시장은 다음 각 호의 어느 하나에 해당하는 용도지역의 지정 또는 변경을 도시ㆍ군관리계획으로 결정한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제41조제2항","원문":"② 공유수면의 매립 목적이 그 매립구역과 이웃하고 있는 용도지역의 내용과 다른 경우 및 그 매립구역이 둘 이상의 용도지역에 걸쳐 있거나 이웃하고 있는 경우 그 매립구역이 속할 용도지역은 도시ㆍ군관리계획결정으로 지정하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제19조의2제3항제2호","원문":"2. 지정 대상 지역이 자연녹지지역ㆍ계획관리지역 또는 생산관리지역일 것. 다만, 계획관리지역에 있는 기존 공장의 증축이 필요한 경우로서 해당 공장이 도로ㆍ철도ㆍ하천ㆍ건축물ㆍ바다 등으로 둘러싸여 있어 증축을 위해서는 불가피하게 보전관리지역 또는 농림지역을 포함해야 하는 경우에는 전체 면적의 20퍼센트 이하의 범위에서 보전관리지역 또는 농림지역을 포함하되, 다음 각 목의 어느 하나에 해당하는 경우에는 20퍼센트 이상으로 할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"용도지역은 서로 중복되지 않게 도시·군관리계획으로 결정하는 지역이다(법 제2조제15호). 용도지구는 용도지역과 겹쳐 지정한다."},{"번호":2,"판정":"틀림","설명":"용도지역의 지정·변경은 도시·군관리계획으로 결정한다(법 제36조제1항). 도시·군기본계획으로 결정하지 않는다."},{"번호":3,"판정":"틀림","설명":"산업·유통개발진흥지구의 지정을 제안할 수 있는 지역은 자연녹지지역·계획관리지역·생산관리지역이다. 상업지역은 대상이 아니다(영 제19조의2제3항제2호)."},{"번호":4,"판정":"틀림","설명":"매립구역이 둘 이상의 용도지역에 걸치거나 이웃하는 경우에는 도시·군관리계획결정으로 지정한다. 가장 큰 용도지역으로 보는 규정은 없다(법 제41조제2항)."},{"번호":5,"판정":"옳음","설명":"관리지역 안의 농업진흥지역은 농림지역으로 결정·고시된 것으로 본다(법 제42조제2항)."}],"개념":[{"종류":"표","제목":"다른 법률에 따라 용도지역으로 의제되는 지역","머리":["구분","지정된 지역","의제되는 용도지역","근거"],"행":[["도시지역","항만구역(도시지역 연접 공유수면), 어항구역(도시지역 연접 공유수면)","도시지역","제42조제1항제1호·제2호"],["도시지역","국가산업단지·일반산업단지·도시첨단산업단지","도시지역","제42조제1항제3호"],["도시지역","택지개발촉진법상 택지개발지구","도시지역","제42조제1항제4호"],["도시지역","전원개발사업구역·예정구역(수력발전소·송변전설비만 설치하는 구역 제외)","도시지역","제42조제1항제5호"],["농림지역","관리지역 안의 농업진흥지역","농림지역","제42조제2항"],["농림지역 또는 자연환경보전지역","관리지역 안의 보전산지","고시에서 구분하는 바에 따라","제42조제2항"]]},{"종류":"표","제목":"공유수면(바다) 매립지의 용도지역","머리":["경우","용도지역 결정","근거"],"행":[["매립 목적이 이웃 용도지역의 내용과 같음","도시·군관리계획 절차 없이 준공인가일부터 이웃 용도지역으로 지정된 것으로 봄","제41조제1항"],["매립 목적이 이웃 용도지역과 다름","도시·군관리계획결정으로 지정","제41조제2항"],["매립구역이 둘 이상의 용도지역에 걸치거나 이웃함","도시·군관리계획결정으로 지정","제41조제2항"]]}],"함정":"용도지역은 서로 겹치지 않고 도시·군관리계획으로 결정한다. 공유수면 매립구역이 둘 이상의 용도지역과 이웃하면 가장 큰 용도지역으로 보지 않고 관리계획결정으로 지정한다. 산업·유통개발진흥지구 제안 대상은 자연녹지지역·계획관리지역·생산관리지역이다."}},{"i":"S5-2-1-공법-05","r":"S5","g":2,"c":2,"n":45,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 용도지역ㆍ용도지구ㆍ용도구역에 관한 설명으로 옳은 것은? (단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["대도시 시장은 유통상업지역에 복합용도지구를 지정할 수 있다.","대도시 시장은 재해의 반복 발생이 우려되는 지역에 대해서는 특정용도제한지구를 지정하여야 한다.","용도지역 안에서의 건축물의 용도ㆍ종류 및 규모의 제한에 대한 규정은 도시ㆍ군계획시설에 대해서도 적용된다.","공유수면의 매립 목적이 그 매립구역과 이웃하고 있는 용도지역의 내용과 다른 경우 그 매립준공구역은 이와 이웃하고 있는 용도지역으로 지정된 것으로 본다.","｢택지개발촉진법｣에 따른 택지개발지구로 지정ㆍ고시된 지역은 ｢국토의 계획 및 이용에 관한 법률｣에 따른 도시지역으로 결정ㆍ고시된 것으로 본다."],"a":[5],"L":"공1-3","o":"기출","x":{"한줄":"택지개발지구로 지정·고시된 지역은 도시지역으로 결정·고시된 것으로 본다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제42조제1항제4호","원문":"4. 「택지개발촉진법」 제3조에 따른 택지개발지구"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제37조제5항","원문":"⑤ 시ㆍ도지사 또는 대도시 시장은 대통령령으로 정하는 주거지역ㆍ공업지역ㆍ관리지역에 복합용도지구를 지정할 수 있으며, 그 지정기준 및 방법 등에 필요한 사항은 대통령령으로 정한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제31조제6항","원문":"⑥ 법 제37조제5항에서 \"대통령령으로 정하는 주거지역ㆍ공업지역ㆍ관리지역\"이란 다음 각 호의 어느 하나에 해당하는 용도지역을 말한다. 1. 일반주거지역 2. 일반공업지역 3. 계획관리지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제37조제4항","원문":"④ 시ㆍ도지사 또는 대도시 시장은 연안침식이 진행 중이거나 우려되는 지역 등 대통령령으로 정하는 지역에 대해서는 제1항제5호의 방재지구의 지정 또는 변경을 도시ㆍ군관리계획으로 결정하여야 한다. 이 경우 도시ㆍ군관리계획의 내용에는 해당 방재지구의 재해저감대책을 포함하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제83조제1항","원문":"①용도지역ㆍ용도지구안에서의 도시ㆍ군계획시설에 대하여는 제71조 내지 제82조의 규정을 적용하지 아니한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제41조제2항","원문":"② 공유수면의 매립 목적이 그 매립구역과 이웃하고 있는 용도지역의 내용과 다른 경우 및 그 매립구역이 둘 이상의 용도지역에 걸쳐 있거나 이웃하고 있는 경우 그 매립구역이 속할 용도지역은 도시ㆍ군관리계획결정으로 지정하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"복합용도지구는 일반주거지역·일반공업지역·계획관리지역에 지정한다. 유통상업지역은 대상이 아니다(법 제37조제5항, 영 제31조제6항)."},{"번호":2,"판정":"틀림","설명":"연안침식이 진행 중이거나 동일 재해가 최근 10년 내 2회 이상 발생해 인명 피해를 입은 지역 등은 방재지구를 지정해야 한다. 특정용도제한지구는 오염물질 배출시설·청소년 유해시설 등의 입지를 제한하는 지구이다(법 제37조제1항제8호·제4항, 영 제31조제5항)."},{"번호":3,"판정":"틀림","설명":"용도지역·용도지구 안의 도시·군계획시설에는 영 제71조부터 제82조까지의 건축제한을 적용하지 않는다(영 제83조제1항)."},{"번호":4,"판정":"틀림","설명":"매립 목적이 이웃 용도지역과 다르면 도시·군관리계획결정으로 지정한다. 이웃 용도지역으로 보는 경우는 목적이 같을 때뿐이다(법 제41조제1항·제2항)."},{"번호":5,"판정":"옳음","설명":"택지개발지구는 도시지역으로 결정·고시된 것으로 본다(법 제42조제1항제4호)."}],"개념":[{"종류":"표","제목":"복합용도지구와 방재지구","머리":["구분","요건","근거"],"행":[["복합용도지구 지정 대상","일반주거지역, 일반공업지역, 계획관리지역","법 제37조제5항, 영 제31조제6항"],["복합용도지구 지정 면적","해당 용도지역 전체 면적의 3분의 1 이하","영 제31조제7항제3호"],["방재지구 의무 지정","연안침식관리구역으로 지정된 지역(연안육역)","영 제31조제5항제1호"],["방재지구 의무 지정","풍수해·산사태 등 동일 재해가 최근 10년 이내 2회 이상 발생해 인명 피해를 입은 지역","영 제31조제5항제2호"],["방재지구 지정 시 포함","재해저감대책","법 제37조제4항 후단"]]},{"종류":"표","제목":"용도지역·용도지구 건축제한의 적용 범위","머리":["대상","건축제한 적용"],"행":[["용도지역 안의 일반 건축물","영 제71조 및 해당 별표에 따름"],["도시·군계획시설","적용하지 않음(영 제83조제1항)"],["개발제한구역·도시자연공원구역·시가화조정구역·수산자원보호구역","각 해당 법령(영 제83조제3항)"],["취락지구·개발진흥지구·복합용도지구","지정목적 범위에서 대통령령으로 따로 정함(법 제76조제5항)"]]}],"함정":"복합용도지구는 일반주거지역·일반공업지역·계획관리지역에만 지정한다. 재해 반복 지역에는 방재지구를 지정하고, 도시·군계획시설에는 용도지역 건축제한이 적용되지 않으며, 매립 목적이 이웃 용도지역과 다르면 관리계획결정으로 용도지역을 정한다."}},{"i":"S5-2-1-공법-06","r":"S5","g":2,"c":2,"n":46,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 도시혁신구역에서 다른 법률 규정에도 불구하고 도시혁신계획으로 따로 정할 수 있는 사항이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["「도시공원 및 녹지 등에 관한 법률」에 따른 도시공원 또는 녹지 확보기준","「문화예술진흥법」에 따른 건축물에 대한 미술작품의 설치","「주차장법」에 따른 부설주차장의 설치","「학교용지 확보 등에 관한 특례법」에 따른 학교용지의 조성ㆍ개발 기준","「체육시설의 설치ㆍ이용에 관한 법률」에 따른 사업계획의 승인"],"a":[5],"L":"공1-3","o":"기출","x":{"한줄":"체육시설법상 사업계획의 승인은 도시혁신계획으로 따로 정할 수 있는 사항으로 열거돼 있지 않다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제83조의3제1항","원문":"① 도시혁신구역에 대하여는 다음 각 호의 법률 규정에도 불구하고 도시혁신계획으로 따로 정할 수 있다. 2. 「주차장법」 제19조에 따른 부설주차장의 설치 3. 「문화예술진흥법」 제9조에 따른 건축물에 대한 미술작품의 설치 5. 「도시공원 및 녹지 등에 관한 법률」 제14조에 따른 도시공원 또는 녹지 확보기준 6. 「학교용지 확보 등에 관한 특례법」 제3조에 따른 학교용지의 조성ㆍ개발 기준"}],"선지":[{"번호":1,"판정":"옳음","설명":"도시공원 또는 녹지 확보기준(「도시공원 및 녹지 등에 관한 법률」 제14조)은 도시혁신계획으로 따로 정할 수 있다(법 제83조의3제1항제5호)."},{"번호":2,"판정":"옳음","설명":"건축물에 대한 미술작품 설치(「문화예술진흥법」 제9조)는 도시혁신계획으로 따로 정할 수 있다(법 제83조의3제1항제3호)."},{"번호":3,"판정":"옳음","설명":"부설주차장 설치(「주차장법」 제19조)는 도시혁신계획으로 따로 정할 수 있다(법 제83조의3제1항제2호)."},{"번호":4,"판정":"옳음","설명":"학교용지 조성·개발 기준(「학교용지 확보 등에 관한 특례법」 제3조)은 도시혁신계획으로 따로 정할 수 있다(법 제83조의3제1항제6호)."},{"번호":5,"판정":"틀림","설명":"「체육시설의 설치·이용에 관한 법률」에 따른 사업계획 승인은 제83조의3제1항 각 호에 없다. 따로 정할 수 있는 사항이 아니다."}],"개념":[{"종류":"표","제목":"도시혁신구역에서 도시혁신계획으로 따로 정할 수 있는 법률 규정","머리":["호","법률 규정","내용"],"행":[["1","주택법 제35조","주택의 배치, 부대시설·복리시설의 설치기준 및 대지조성기준"],["2","주차장법 제19조","부설주차장의 설치"],["3","문화예술진흥법 제9조","건축물에 대한 미술작품의 설치"],["4","건축법 제43조","공개 공지 등의 확보"],["5","도시공원 및 녹지 등에 관한 법률 제14조","도시공원 또는 녹지 확보기준"],["6","학교용지 확보 등에 관한 특례법 제3조","학교용지의 조성·개발 기준"]]},{"종류":"표","제목":"도시혁신구역·복합용도구역·도시·군계획시설입체복합구역","머리":["구분","도시혁신구역","복합용도구역","입체복합구역"],"행":[["조문","제40조의3","제40조의4","제40조의5"],["지정권자","공간재구조화계획 결정권자","공간재구조화계획 결정권자","도시·군관리계획 결정권자"],["지정 대상","도심·부도심 또는 생활권 중심지역, 주요 기반시설과 연계한 거점 지역 등","산업구조 변화로 복합적 토지이용이 필요한 지역, 노후 건축물 밀집 지역 등","도시·군계획시설 준공 후 10년 경과 시설 개량·정비 필요 등"],["계획","도시혁신계획","복합용도계획","건축제한·건폐율·용적률·높이를 대통령령 범위에서 따로 정함"],["특별건축구역","지정된 것으로 봄(제83조의3제2항)","도시혁신구역 규정 준용(제83조의4)","-"],["밀도 한도","-","-","건폐율·용적률 용도지역별 최대한도의 200퍼센트 이하(제40조의5제3항)"]]}],"함정":"완화 대상은 법 제83조의3제1항의 여섯 가지이다. 주택법 제35조와 건축법 제43조도 여기에 들어 있고, 사업계획 승인 같은 인허가 절차는 열거돼 있지 않다.","개정":"제40조의2가 2024.2.6. 삭제됐고, 입지규제최소구역을 대신해 도시혁신구역(제40조의3)과 복합용도구역(제40조의4)이 규정돼 있다."}},{"i":"S5-2-1-공법-07","r":"S5","g":2,"c":2,"n":47,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 제1종일반주거지역에서 도시ㆍ군계획조례의 정함과 관계없이 건축할 수 있는 건축물이 아닌 것은? (단, 건축물은 4층 이하임)","b":null,"bs":"없음","img":[],"ch":["단독주택","기숙사","초등학교","종교시설","제1종 근린생활시설"],"a":[4],"L":"공1-4","o":"변형","x":{"한줄":"종교시설은 제1종일반주거지역에서 조례가 정하는 바에 따라서만 건축할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제71조제1항제3호","원문":"3. 제1종일반주거지역안에서 건축할 수 있는 건축물 : 별표 4에 규정된 건축물"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"별표 4 제1호","원문":"건축할 수 있는 건축물[4층 이하의 건축물만 해당한다] 가. 「건축법 시행령」 별표 1 제1호의 단독주택 나. 「건축법 시행령」 별표 1 제2호의 공동주택(아파트를 제외한다) 다. 「건축법 시행령」 별표 1 제3호의 제1종 근린생활시설 라. 「건축법 시행령」 별표 1 제10호의 교육연구시설 중 유치원ㆍ초등학교·중학교 및 고등학교 마. 「건축법 시행령」 별표 1 제11호의 노유자시설"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"별표 4 제2호","원문":"도시ㆍ군계획조례가 정하는 바에 의하여 건축할 수 있는 건축물(4층 이하의 건축물에 한한다) 가. 「건축법 시행령」 별표 1 제4호의 제2종 근린생활시설(단란주점 및 안마시술소를 제외한다) 나. 「건축법 시행령」 별표 1 제5호의 문화 및 집회시설(공연장 및 관람장을 제외한다) 다. 「건축법 시행령」 별표 1 제6호의 종교시설"}],"선지":[{"번호":1,"판정":"옳음","설명":"단독주택은 별표 4 제1호가목에 있어 조례 없이 건축할 수 있다."},{"번호":2,"판정":"옳음","설명":"기숙사는 「건축법 시행령」 별표 1 제2호 공동주택에 속하고, 제1종일반주거지역에서는 아파트만 제외된다(별표 4 제1호나목)."},{"번호":3,"판정":"옳음","설명":"교육연구시설 중 유치원·초등학교·중학교·고등학교는 별표 4 제1호라목에 있다."},{"번호":4,"판정":"틀림","설명":"종교시설은 별표 4 제2호다목에 있어 도시·군계획조례가 정하는 바에 따라서만 건축할 수 있다."},{"번호":5,"판정":"옳음","설명":"제1종 근린생활시설은 별표 4 제1호다목에 있다."}],"개념":[{"종류":"표","제목":"주거지역별 건폐율·용적률 한도(조례로 정하는 비율의 상한)","머리":["용도지역","건폐율","용적률"],"행":[["제1종전용주거지역","50퍼센트 이하","50퍼센트 이상 100퍼센트 이하"],["제2종전용주거지역","50퍼센트 이하","50퍼센트 이상 150퍼센트 이하"],["제1종일반주거지역","60퍼센트 이하","100퍼센트 이상 200퍼센트 이하"],["제2종일반주거지역","60퍼센트 이하","100퍼센트 이상 250퍼센트 이하"],["제3종일반주거지역","50퍼센트 이하","100퍼센트 이상 300퍼센트 이하"],["준주거지역","70퍼센트 이하","200퍼센트 이상 500퍼센트 이하"]]},{"종류":"표","제목":"제1종일반주거지역의 건축물(별표 4, 4층 이하)","머리":["구분","건축물"],"행":[["조례 없이 건축 가능(제1호)","단독주택, 공동주택(아파트 제외), 제1종 근린생활시설, 유치원·초·중·고등학교, 노유자시설"],["조례로 건축 가능(제2호)","제2종 근린생활시설(단란주점·안마시술소 제외), 문화 및 집회시설(공연장·관람장 제외), 종교시설"],["조례로 건축 가능(제2호)","의료시설(격리병원 제외), 수련시설, 운동시설(옥외 철탑 골프연습장 제외)"],["조례로 건축 가능(제2호)","판매시설 일부, 오피스텔(바닥면적 합계 3천제곱미터 미만), 일부 공장"],["그 밖","별표 4에 없는 용도는 건축 불가"]]}],"함정":"종교시설·의료시설·제2종 근린생활시설은 조례가 허용해야 건축할 수 있다. 아파트는 제1종일반주거지역에서 제외되고, 기숙사는 공동주택이지만 아파트가 아니므로 허용된다."}},{"i":"S5-2-1-공법-08","r":"S5","g":2,"c":2,"n":48,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 도시ㆍ군계획시설사업에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["도시ㆍ군계획시설은 기반시설 중 도시ㆍ군관리계획으로 결정된 시설이다.","도시ㆍ군계획시설사업이 같은 도의 관할 구역에 속하는 둘 이상의 시 또는 군에 걸쳐 시행되는 경우에는 국토교통부장관이 시행자를 정한다.","한국토지주택공사는 도시ㆍ군계획시설사업 대상 토지소유자 동의 요건을 갖추지 않아도 도시ㆍ군계획시설사업의 시행자로 지정을 받을 수 있다.","도시ㆍ군계획시설사업 실시계획에는 사업의 착수예정일 및 준공예정일도 포함되어야 한다.","도시ㆍ군계획시설사업 실시계획 인가 내용과 다르게 도시ㆍ군계획시설사업을 하여 토지의 원상회복 명령을 받은 자가 원상회복을 하지 아니하면 ｢행정대집행법｣에 따른 행정대집행에 따라 원상회복을 할 수 있다."],"a":[2],"L":"공1-5","o":"기출","x":{"한줄":"같은 도 안의 둘 이상 시·군에 걸치는 사업은 관계 시장·군수가 협의해 시행자를 정하고, 협의가 안 되면 도지사가 지정한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제86조제2항·제3항","원문":"② 도시ㆍ군계획시설사업이 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역에 걸쳐 시행되게 되는 경우에는 관계 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수가 서로 협의하여 시행자를 정한다. ③ 제2항에 따른 협의가 성립되지 아니하는 경우 도시ㆍ군계획시설사업을 시행하려는 구역이 같은 도의 관할 구역에 속하는 경우에는 관할 도지사가 시행자를 지정하고, 둘 이상의 시ㆍ도의 관할 구역에 걸치는 경우에는 국토교통부장관이 시행자를 지정한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제7호","원문":"7. \"도시ㆍ군계획시설\"이란 기반시설 중 도시ㆍ군관리계획으로 결정된 시설을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제86조제7항","원문":"⑦ 다음 각 호에 해당하지 아니하는 자가 제5항에 따라 도시ㆍ군계획시설사업의 시행자로 지정을 받으려면 도시ㆍ군계획시설사업의 대상인 토지(국공유지는 제외한다)의 소유 면적 및 토지 소유자의 동의 비율에 관하여 대통령령으로 정하는 요건을 갖추어야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제96조제3항제3호","원문":"③ 법 제86조제7항제2호에서 \"대통령령으로 정하는 공공기관\"이란 다음 각 호의 어느 하나에 해당하는 기관을 말한다. 3. 「한국토지주택공사법」에 따른 한국토지주택공사"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제97조제1항제4호","원문":"①법 제88조제1항의 규정에 의한 실시계획(이하 \"실시계획\"이라 한다)에는 다음 각호의 사항이 포함되어야 한다. 4. 사업의 착수예정일 및 준공예정일"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제89조제4항","원문":"④ 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 제3항에 따른 원상회복의 명령을 받은 자가 원상회복을 하지 아니하는 경우에는 「행정대집행법」에 따른 행정대집행에 따라 원상회복을 할 수 있다. 이 경우 행정대집행에 필요한 비용은 제1항에 따라 도시ㆍ군계획시설사업의 시행자가 예치한 이행보증금으로 충당할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"도시·군계획시설은 기반시설 중 도시·군관리계획으로 결정된 시설이다(법 제2조제7호)."},{"번호":2,"판정":"틀림","설명":"관계 시장·군수가 서로 협의해 시행자를 정하고, 협의가 성립되지 않으면 같은 도 안에서는 도지사가 지정한다. 국토교통부장관이 지정하는 경우는 둘 이상의 시·도에 걸칠 때이다(법 제86조제2항·제3항)."},{"번호":3,"판정":"옳음","설명":"한국토지주택공사는 영 제96조제3항의 공공기관이므로 토지 소유·동의 요건 없이 시행자로 지정받을 수 있다(법 제86조제7항제2호)."},{"번호":4,"판정":"옳음","설명":"실시계획에는 사업의 종류·명칭, 면적 또는 규모, 시행자, 착수예정일 및 준공예정일이 들어간다(영 제97조제1항)."},{"번호":5,"판정":"옳음","설명":"원상회복 명령을 이행하지 않으면 행정대집행으로 원상회복할 수 있다(법 제89조제3항·제4항)."}],"개념":[{"종류":"흐름","제목":"도시·군계획시설사업 시행 절차","단계":[{"이름":"시행자 정함","설명":"원칙은 특별시장~군수, 둘 이상 시·군에 걸치면 협의 후 도지사 또는 국토교통부장관 지정(법 제86조제1항~제3항)"},{"이름":"시행자 지정","설명":"그 밖의 자는 국토교통부장관·시·도지사·시장·군수에게 지정 신청, 동의 요건 충족(법 제86조제5항·제7항)"},{"이름":"실시계획 작성","설명":"설계도서, 자금계획, 시행기간 등(법 제88조제1항·제5항, 영 제97조제1항)"},{"이름":"실시계획 인가","설명":"국토교통부장관 지정 시행자는 국토교통부장관, 그 밖에는 시·도지사 또는 대도시 시장(영 제97조제2항)"},{"이름":"실시계획 고시·이행 담보","설명":"실시계획 고시(법 제91조), 필요 시 이행보증금 예치(법 제89조제1항)"},{"이름":"공사완료 공고","설명":"시행자는 공사 후 준공검사를 받고 공사완료 공고(법 제98조)"}]},{"종류":"표","제목":"시행자 구분","머리":["구분","시행자","근거"],"행":[["원칙","관할 구역의 특별시장·광역시장·특별자치시장·특별자치도지사·시장·군수","제86조제1항"],["둘 이상의 시·군에 걸침","관계 장이 협의, 불성립 시 같은 도는 도지사 지정","제86조제2항·제3항"],["둘 이상의 시·도에 걸침","협의 불성립 시 국토교통부장관 지정","제86조제3항"],["직접 시행","국토교통부장관(국가계획 관련 등), 도지사(광역도시계획 관련 등), 관계 시장·군수 의견 청취","제86조제4항"],["그 밖의 자","지정을 받아 시행","제86조제5항"]]}],"함정":"지정권자는 같은 도 안의 둘 이상 시·군이면 도지사, 둘 이상 시·도이면 국토교통부장관이다. 공공기관은 동의 요건이 면제되고 민간 사업자는 면제되지 않는다."}},{"i":"S5-2-1-공법-09","r":"S5","g":2,"c":2,"n":49,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 도시ㆍ군계획시설사업의 시행 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["단계별 집행계획은 도시ㆍ군계획시설결정의 고시일부터 3개월 이내에 재원조달계획, 보상계획 등을 포함하여 수립하는 것이 원칙이다.","단계별 집행계획 중 3년 이내에 시행하는 도시ㆍ군계획시설사업은 제1단계 집행계획에 포함되도록 하여야 한다.","한국토지주택공사나 지방공사가 아닌 민간사업자가 시행자로 지정받으려면 사업대상 토지(국ㆍ공유지 제외)의 2분의 1 이상을 소유하고 토지소유자 총수의 3분의 2 이상의 동의를 받아야 한다.","국토교통부장관은 국가계획과 관련되거나 특히 필요하다고 인정되는 경우 관계 시장 또는 군수의 의견을 들어 직접 도시ㆍ군계획시설사업을 시행할 수 있다.","시장 또는 군수는 실시계획 인가 내용과 다르게 사업을 한 자가 원상회복 명령을 이행하지 않아 행정대집행을 하는 경우 그 비용을 시행자가 예치한 이행보증금으로 충당할 수 있다."],"a":[3],"L":"공1-5","o":"변형","x":{"한줄":"민간 사업자가 시행자로 지정받으려면 토지 면적 3분의 2 이상 소유와 소유자 총수 2분의 1 이상 동의가 필요하다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제85조제1항","원문":"① 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 도시ㆍ군계획시설에 대하여 도시ㆍ군계획시설결정의 고시일부터 3개월 이내에 대통령령으로 정하는 바에 따라 재원조달계획, 보상계획 등을 포함하는 단계별 집행계획을 수립하여야 한다. 다만, 대통령령으로 정하는 법률에 따라 도시ㆍ군관리계획의 결정이 의제되는 경우에는 해당 도시ㆍ군계획시설결정의 고시일부터 2년 이내에 단계별 집행계획을 수립할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제85조제3항","원문":"③ 단계별 집행계획은 제1단계 집행계획과 제2단계 집행계획으로 구분하여 수립하되, 3년 이내에 시행하는 도시ㆍ군계획시설사업은 제1단계 집행계획에, 3년 후에 시행하는 도시ㆍ군계획시설사업은 제2단계 집행계획에 포함되도록 하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제96조제2항","원문":"②법 제86조제7항 각 호 외의 부분 중 \"대통령령으로 정하는 요건\"이란 도시ㆍ군계획시설사업의 대상인 토지(국ㆍ공유지를 제외한다. 이하 이 항에서 같다)면적의 3분의 2 이상에 해당하는 토지를 소유하고, 토지소유자 총수의 2분의 1 이상에 해당하는 자의 동의를 얻는 것을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제86조제4항","원문":"④ 제1항부터 제3항까지의 규정에도 불구하고 국토교통부장관은 국가계획과 관련되거나 그 밖에 특히 필요하다고 인정되는 경우에는 관계 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 의견을 들어 직접 도시ㆍ군계획시설사업을 시행할 수 있으며, 도지사는 광역도시계획과 관련되거나 특히 필요하다고 인정되는 경우에는 관계 시장 또는 군수의 의견을 들어 직접 도시ㆍ군계획시설사업을 시행할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제89조제4항","원문":"④ 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 제3항에 따른 원상회복의 명령을 받은 자가 원상회복을 하지 아니하는 경우에는 「행정대집행법」에 따른 행정대집행에 따라 원상회복을 할 수 있다. 이 경우 행정대집행에 필요한 비용은 제1항에 따라 도시ㆍ군계획시설사업의 시행자가 예치한 이행보증금으로 충당할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"결정 고시일부터 3개월 이내에 수립한다. 도시·군관리계획 결정이 의제되는 일부 법률(정비법 등)의 경우에만 고시일부터 2년 이내로 늘어난다(법 제85조제1항, 영 제95조제2항)."},{"번호":2,"판정":"옳음","설명":"3년 이내 시행 사업은 제1단계, 3년 후 시행 사업은 제2단계에 넣는다(법 제85조제3항)."},{"번호":3,"판정":"틀림","설명":"요건은 토지 면적의 3분의 2 이상 소유와 소유자 총수의 2분의 1 이상 동의이다. 면적과 인원 비율이 뒤바뀌었다(영 제96조제2항). 국가·지방자치단체·공공기관·지방공사 등은 이 요건이 면제된다(법 제86조제7항)."},{"번호":4,"판정":"옳음","설명":"국토교통부장관은 관계 시장·군수의 의견을 듣고 직접 시행할 수 있다. 도지사의 직접 시행은 광역도시계획과 관련되거나 특히 필요한 경우이다(법 제86조제4항)."},{"번호":5,"판정":"옳음","설명":"대집행에 필요한 비용은 시행자가 예치한 이행보증금으로 충당할 수 있다(법 제89조제4항 후단)."}],"개념":[{"종류":"표","제목":"시행자 지정 동의 요건과 면제","머리":["구분","내용","근거"],"행":[["동의 요건","대상 토지(국·공유지 제외) 면적의 3분의 2 이상 소유 + 소유자 총수의 2분의 1 이상 동의","영 제96조제2항"],["면제","국가, 지방자치단체","법 제86조제7항제1호"],["면제","대통령령으로 정하는 공공기관(한국토지주택공사, 한국도로공사, 한국철도공사 등)","영 제96조제3항"],["면제","지방공사·지방공단, 다른 법률에 따라 도시·군계획시설사업이 포함된 사업의 시행자로 지정된 자","영 제96조제4항제1호·제2호"],["면제","공공시설을 무상귀속시키려고 설치하는 자, 기부를 조건으로 시설물을 설치하려는 자","영 제96조제4항제3호·제4호"]]},{"종류":"표","제목":"장기미집행 도시·군계획시설","머리":["기간(결정 고시일부터)","내용","근거"],"행":[["10년 이내 미시행","대지(垈)인 토지 소유자의 매수 청구, 매수의무자는 6개월 이내 매수 여부 결정, 결정한 토지는 알린 날부터 2년 이내 매수","법 제47조제1항·제6항"],["10년 이내 미시행","시장·군수가 현황과 단계별 집행계획을 지방의회에 보고, 의회는 해제 권고 가능","법 제48조제3항·제4항"],["10년 이후 실시계획 인가","실시계획 고시일부터 5년 내 재결신청 없으면 효력 상실(3분의 2 이상 권원 확보 시 7년)","법 제88조제7항"],["20년 미시행","20년이 되는 날의 다음 날 시설결정 실효","법 제48조제1항"]]}],"함정":"시행자 지정 동의 요건은 면적이 3분의 2, 인원이 2분의 1이다. 공공기관의 면제는 영 제96조제3항에 열거된 기관에만 적용된다."}},{"i":"S5-2-1-공법-10","r":"S5","g":2,"c":2,"n":50,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 도시지역 외의 지역에 지정하는 지구단위계획구역에 관한 설명으로 틀린 것은? (단, 산업ㆍ유통개발진흥지구는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["지정하려는 구역 면적의 100분의 50 이상이 계획관리지역으로서 대통령령으로 정하는 요건에 해당하는 지역은 지구단위계획구역으로 지정할 수 있다.","도시지역 외의 지역에 지정된 개발진흥지구로서 대통령령으로 정하는 요건에 해당하는 지역도 지구단위계획구역으로 지정할 수 있다.","지구단위계획으로 해당 용도지역에 적용되는 건폐율의 150퍼센트 및 용적률의 200퍼센트 이내에서 건폐율과 용적률을 완화하여 적용할 수 있다.","계획관리지역에 지정된 개발진흥지구 안의 지구단위계획구역에서 건축물의 용도ㆍ종류 및 규모 등을 완화하여 적용하는 경우에도 아파트 및 연립주택은 허용되지 아니한다.","다른 법률에서 지구단위계획의 결정에 관하여 따로 정한 경우를 제외하고, 지구단위계획구역의 지정에 관한 도시ㆍ군관리계획결정의 고시일부터 3년 이내에 지구단위계획이 결정ㆍ고시되지 아니하면 그 3년이 되는 날의 다음날 지정 결정은 효력을 잃는다."],"a":[4],"L":"공1-6","o":"변형","x":{"한줄":"계획관리지역에 지정된 개발진흥지구는 아파트·연립주택 불허 대상에서 제외된다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제51조제3항","원문":"③ 도시지역 외의 지역을 지구단위계획구역으로 지정하려는 경우 다음 각 호의 어느 하나에 해당하여야 한다. 1. 지정하려는 구역 면적의 100분의 50 이상이 제36조에 따라 지정된 계획관리지역으로서 대통령령으로 정하는 요건에 해당하는 지역 2. 제37조에 따라 지정된 개발진흥지구로서 대통령령으로 정하는 요건에 해당하는 지역"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제47조제1항","원문":"①지구단위계획구역(도시지역 외에 지정하는 경우로 한정한다. 이하 이 조에서 같다)에서는 법 제52조제3항에 따라 지구단위계획으로 해당 용도지역 또는 개발진흥지구에 적용되는 건폐율의 150퍼센트 및 용적률의 200퍼센트 이내에서 건폐율 및 용적률을 완화하여 적용할 수 있다. 다만, 제84조제4항제2호가목 단서에 해당하는 산업ㆍ유통개발진흥지구의 전부 또는 일부에 대해 지구단위계획구역이 지정된 경우에는 같은 규정에 따른 건폐율의 120퍼센트 이내의 범위에서 건폐율을 완화하여 적용할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제47조제2항","원문":"②지구단위계획구역에서는 법 제52조제3항의 규정에 의하여 지구단위계획으로 법 제76조의 규정에 의한 건축물의 용도ㆍ종류 및 규모 등을 완화하여 적용할 수 있다. 다만, 개발진흥지구(계획관리지역에 지정된 개발진흥지구를 제외한다)에 지정된 지구단위계획구역에 대하여는 「건축법 시행령」 별표 1 제2호의 공동주택중 아파트 및 연립주택은 허용되지 아니한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제53조제1항","원문":"① 지구단위계획구역의 지정에 관한 도시ㆍ군관리계획결정의 고시일부터 3년 이내에 그 지구단위계획구역에 관한 지구단위계획이 결정ㆍ고시되지 아니하면 그 3년이 되는 날의 다음날에 그 지구단위계획구역의 지정에 관한 도시ㆍ군관리계획결정은 효력을 잃는다. 다만, 다른 법률에서 지구단위계획의 결정(결정된 것으로 보는 경우를 포함한다)에 관하여 따로 정한 경우에는 그 법률에 따라 지구단위계획을 결정할 때까지 지구단위계획구역의 지정은 그 효력을 유지한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"구역 면적의 100분의 50 이상이 계획관리지역이고 대통령령 요건에 맞으면 도시지역 외에도 지정할 수 있다(법 제51조제3항제1호)."},{"번호":2,"판정":"옳음","설명":"개발진흥지구로서 대통령령 요건에 맞는 지역도 지정 대상이다(법 제51조제3항제2호)."},{"번호":3,"판정":"옳음","설명":"도시지역 외의 지구단위계획구역은 건폐율 150퍼센트, 용적률 200퍼센트 이내에서 완화된다(영 제47조제1항)."},{"번호":4,"판정":"틀림","설명":"아파트·연립주택 불허는 개발진흥지구 중 계획관리지역에 지정된 지구를 제외한 곳에 적용된다. 계획관리지역의 개발진흥지구에는 이 제한이 없다(영 제47조제2항 단서)."},{"번호":5,"판정":"옳음","설명":"3년 이내에 지구단위계획이 결정·고시되지 않으면 그 3년이 되는 날의 다음날 지정 결정이 효력을 잃는다(법 제53조제1항)."}],"개념":[{"종류":"표","제목":"도시지역 내·외 지구단위계획구역의 완화 적용","머리":["구분","도시지역 내(영 제46조)","도시지역 외(영 제47조)"],"행":[["건폐율","공공시설 등 부지 제공 시 해당 용도지역 건폐율 × (1 + 제공면적 ÷ 원래 대지면적) 이내, 한도 150퍼센트","해당 용도지역 또는 개발진흥지구 건폐율의 150퍼센트 이내"],["용적률","산식에 따른 완화, 개발진흥지구 지정 시 120퍼센트 이내, 한도 200퍼센트","해당 용도지역 또는 개발진흥지구 용적률의 200퍼센트 이내"],["높이","공공시설 제공 시 완화, 개발진흥지구 지정 시 건축법상 높이의 120퍼센트 이내","높이 완화 규정 없음"],["용도·종류·규모","조례에서 허용되는 건축물 범위에서 완화","완화 가능, 개발진흥지구(계획관리지역 제외)는 아파트·연립주택 불허"]]},{"종류":"표","제목":"지구단위계획구역 지정·계획 결정의 실효","머리":["구분","실효 요건","근거"],"행":[["지구단위계획구역 지정","고시일부터 3년 이내 지구단위계획 결정·고시가 없으면 3년이 되는 날의 다음날 실효","법 제53조제1항"],["주민이 입안을 제안한 지구단위계획","결정 고시일부터 5년 이내 허가·인가·승인 등을 받아 사업·공사에 착수하지 않으면 5년이 된 날의 다음날 실효","법 제53조제2항"],["실효 시","지체 없이 그 사실을 고시","법 제53조제3항"]]}],"함정":"도시지역 외 지구단위계획구역은 건폐율 150퍼센트와 용적률 200퍼센트가 한도이다. 높이 완화 규정은 영 제47조에 없다. 아파트·연립주택 불허는 개발진흥지구에만 걸리고, 그중 계획관리지역은 빠진다."}},{"i":"S5-2-1-공법-11","r":"S5","g":2,"c":2,"n":51,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 개발행위허가에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["재해복구나 재난수습을 위한 응급조치로 개발행위를 하려는 자는 사전에 개발행위허가를 받아야 한다.","개발행위허가권자는 허가 신청에 대하여 특별한 사유가 없으면 10일(도시계획위원회의 심의나 관계 행정기관과의 협의 기간은 제외) 이내에 허가 또는 불허가의 처분을 하여야 한다.","개발행위허가를 받은 자가 행정청이 아닌 경우, 개발행위로 용도가 폐지되는 공공시설은 새로 설치한 공공시설의 설치비용에 상당하는 범위에서 개발행위허가를 받은 자에게 무상으로 양도할 수 있다.","개발행위허가를 받지 않고 개발행위를 한 자가 원상회복 명령을 이행하지 않아 행정대집행을 하는 경우 그 비용은 이행보증금으로 충당할 수 없다.","「건축법」에 따라 신고하고 설치할 수 있는 건축물의 개축ㆍ증축 또는 재축과 이에 필요한 토지의 형질변경은 도시ㆍ군계획시설사업이 시행되지 아니하고 있는 도시ㆍ군계획시설 부지가 아니어도 개발행위허가 없이 할 수 있다."],"a":[3],"L":"공1-7","o":"변형","x":{"한줄":"행정청이 아닌 자의 개발행위로 용도가 폐지되는 공공시설은 새 시설의 설치비용에 상당하는 범위에서 무상으로 양도할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제65조제2항","원문":"② 개발행위허가를 받은 자가 행정청이 아닌 경우 개발행위허가를 받은 자가 새로 설치한 공공시설은 그 시설을 관리할 관리청에 무상으로 귀속되고, 개발행위로 용도가 폐지되는 공공시설은 「국유재산법」과 「공유재산 및 물품 관리법」에도 불구하고 새로 설치한 공공시설의 설치비용에 상당하는 범위에서 개발행위허가를 받은 자에게 무상으로 양도할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제56조제4항","원문":"④ 다음 각 호의 어느 하나에 해당하는 행위는 제1항에도 불구하고 개발행위허가를 받지 아니하고 할 수 있다. 다만, 제1호의 응급조치를 한 경우에는 1개월 이내에 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수에게 신고하여야 한다. 1. 재해복구나 재난수습을 위한 응급조치 2. 「건축법」에 따라 신고하고 설치할 수 있는 건축물의 개축ㆍ증축 또는 재축과 이에 필요한 범위에서의 토지의 형질 변경(도시ㆍ군계획시설사업이 시행되지 아니하고 있는 도시ㆍ군계획시설의 부지인 경우만 가능하다)"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제54조제1항","원문":"①법 제57조제2항에서 \"대통령령으로 정하는 기간\"이란 15일(도시계획위원회의 심의를 거쳐야 하거나 관계 행정기관의 장과 협의를 하여야 하는 경우에는 심의 또는 협의기간을 제외한다)을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제60조제4항","원문":"④ 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 제3항에 따른 원상회복의 명령을 받은 자가 원상회복을 하지 아니하면 「행정대집행법」에 따른 행정대집행에 따라 원상회복을 할 수 있다. 이 경우 행정대집행에 필요한 비용은 제1항에 따라 개발행위허가를 받은 자가 예치한 이행보증금을 사용할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"재해복구나 재난수습을 위한 응급조치는 허가 없이 할 수 있다. 응급조치를 한 경우 1개월 이내에 신고한다(법 제56조제4항제1호 및 단서)."},{"번호":2,"판정":"틀림","설명":"처분 기간은 15일이다(심의·협의 기간 제외). 10일이 아니다(영 제54조제1항)."},{"번호":3,"판정":"옳음","설명":"행정청이 아닌 자는 새로 설치한 공공시설을 관리청에 무상 귀속시키고, 용도가 폐지되는 공공시설은 새 시설의 설치비용에 상당하는 범위에서 무상 양도받을 수 있다(법 제65조제2항)."},{"번호":4,"판정":"틀림","설명":"행정대집행 비용은 허가받은 자가 예치한 이행보증금을 사용할 수 있다(법 제60조제4항 후단)."},{"번호":5,"판정":"틀림","설명":"신고 대상 건축물의 개축·증축·재축과 필요한 형질변경이 허가 없이 가능한 경우는 도시·군계획시설사업이 시행되지 않고 있는 도시·군계획시설의 부지인 때뿐이다(법 제56조제4항제2호)."}],"개념":[{"종류":"흐름","제목":"개발행위허가 절차","단계":[{"이름":"신청","설명":"기반시설 설치·용지 확보, 위해 방지, 환경오염 방지, 경관, 조경 계획서를 첨부(법 제57조제1항)"},{"이름":"의견 청취·심의","설명":"도시·군계획사업 시행자 의견 청취(법 제58조제2항), 일정 규모 이상은 도시계획위원회 심의(법 제59조, 영 제57조)"},{"이름":"처분","설명":"특별한 사유가 없으면 15일 이내(심의·협의 기간 제외) 허가 또는 불허가(영 제54조제1항)"},{"이름":"조건부 허가","설명":"조건을 붙이려면 미리 신청자 의견 청취(법 제57조제4항, 영 제54조제2항)"},{"이름":"이행보증","설명":"필요한 경우 이행보증금 예치, 국가·지방자치단체 시행은 제외(법 제60조제1항)"},{"이름":"준공검사","설명":"개발행위를 마치면 준공검사(건축물은 사용승인으로 갈음, 법 제62조제1항)"},{"이름":"공공시설 귀속","설명":"행정청은 종래 시설 무상 귀속, 비행정청은 설치비용 범위 무상 양도(법 제65조)"}]},{"종류":"표","제목":"용도지역별 개발행위 규모(토지의 형질변경면적, 영 제55조제1항)","머리":["용도지역","규모"],"행":[["주거지역·상업지역·자연녹지지역·생산녹지지역","1만제곱미터 미만"],["공업지역","3만제곱미터 미만"],["보전녹지지역","5천제곱미터 미만"],["관리지역","3만제곱미터 미만"],["농림지역","3만제곱미터 미만"],["자연환경보전지역","5천제곱미터 미만"]]}],"함정":"응급조치는 사전 허가가 아니라 사후 신고(1개월 이내)이다. 처분 기간은 15일이고 이행보증금으로 대집행 비용을 충당할 수 있다. 신고 대상 건축물의 개축·증축·재축에 필요한 형질변경은 시행되지 않는 도시·군계획시설 부지에서만 허가가 면제된다."}},{"i":"S5-2-1-공법-12","r":"S5","g":2,"c":2,"n":52,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 기반시설부담구역에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시장 또는 군수가 기반시설의 설치가 필요하다고 인정하는 지역으로서 전년도 개발행위허가 건수가 전전년도 개발행위허가 건수보다 20퍼센트 이상 증가한 지역은 기반시설부담구역으로 지정하여야 한다.","기반시설부담구역을 지정하려면 주민의 의견을 듣고 해당 지방자치단체에 설치된 지방도시계획위원회의 심의를 거쳐야 한다.","기반시설부담구역의 지정고시일부터 1년이 되는 날까지 기반시설설치계획을 수립하지 아니하면 그 1년이 되는 날의 다음날에 기반시설부담구역의 지정은 해제된 것으로 본다.","기반시설설치비용의 부과대상은 연면적(기존 건축물의 연면적 포함) 300제곱미터를 초과하는 건축물의 신축ㆍ증축 행위이다.","납부의무자는 사용승인 신청 시까지 기반시설설치비용을 내야 하며, 시장 또는 군수는 건축허가를 받은 날부터 2개월 이내에 이를 부과하여야 한다."],"a":[4],"L":"공1-8","o":"변형","x":{"한줄":"기반시설설치비용의 부과대상은 연면적(기존 건축물 포함) 200제곱미터를 초과하는 건축물의 신축·증축이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제68조제1항","원문":"① 기반시설부담구역에서 기반시설설치비용의 부과대상인 건축행위는 제2조제20호에 따른 시설로서 200제곱미터(기존 건축물의 연면적을 포함한다)를 초과하는 건축물의 신축ㆍ증축 행위로 한다. 다만, 기존 건축물을 철거하고 신축하는 경우에는 기존 건축물의 건축연면적을 초과하는 건축행위만 부과대상으로 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제67조제1항","원문":"① 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 다음 각 호의 어느 하나에 해당하는 지역에 대하여는 기반시설부담구역으로 지정하여야 한다. 다만, 개발행위가 집중되어 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수가 해당 지역의 계획적 관리를 위하여 필요하다고 인정하면 다음 각 호에 해당하지 아니하는 경우라도 기반시설부담구역으로 지정할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제64조제1항제1호","원문":"① 법 제67조제1항제3호에서 \"대통령령으로 정하는 지역\"이란 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수가 제4조의2에 따른 기반시설의 설치가 필요하다고 인정하는 지역으로서 다음 각 호의 어느 하나에 해당하는 지역을 말한다. 1. 해당 지역의 전년도 개발행위허가 건수가 전전년도 개발행위허가 건수보다 20퍼센트 이상 증가한 지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제67조제2항","원문":"② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 기반시설부담구역을 지정 또는 변경하려면 주민의 의견을 들어야 하며, 해당 지방자치단체에 설치된 지방도시계획위원회의 심의를 거쳐 대통령령으로 정하는 바에 따라 이를 고시하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제65조제4항","원문":"④ 기반시설부담구역의 지정고시일부터 1년이 되는 날까지 기반시설설치계획을 수립하지 아니하면 그 1년이 되는 날의 다음날에 기반시설부담구역의 지정은 해제된 것으로 본다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제69조제2항","원문":"② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 납부의무자가 국가 또는 지방자치단체로부터 건축허가(다른 법률에 따른 사업승인 등 건축허가가 의제되는 경우에는 그 사업승인)를 받은 날부터 2개월 이내에 기반시설설치비용을 부과하여야 하고, 납부의무자는 사용승인(다른 법률에 따라 준공검사 등 사용승인이 의제되는 경우에는 그 준공검사) 신청 시까지 이를 내야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"전년도 개발행위허가 건수가 전전년도보다 20퍼센트 이상 증가한 지역은 지정 대상이다. 기반시설부담구역은 법 제67조제1항 각 호의 지역에 지정하여야 한다(영 제64조제1항제1호, 법 제67조제1항제3호)."},{"번호":2,"판정":"옳음","설명":"주민 의견 청취와 지방도시계획위원회 심의를 거쳐 고시한다(법 제67조제2항)."},{"번호":3,"판정":"옳음","설명":"1년 안에 기반시설설치계획을 수립하지 않으면 1년이 되는 날의 다음날 지정이 해제된 것으로 본다(영 제65조제4항)."},{"번호":4,"판정":"틀림","설명":"부과대상은 200제곱미터(기존 건축물의 연면적 포함)를 초과하는 건축물의 신축·증축이다. 300제곱미터가 아니다(법 제68조제1항)."},{"번호":5,"판정":"옳음","설명":"건축허가를 받은 날부터 2개월 이내에 부과하고, 납부의무자는 사용승인 신청 시까지 낸다(법 제69조제2항)."}],"개념":[{"종류":"흐름","제목":"기반시설설치비용 부과·납부 절차","단계":[{"이름":"구역 지정","설명":"주민 의견 청취, 지방도시계획위원회 심의, 지방자치단체 공보·인터넷 홈페이지에 고시(법 제67조제2항, 영 제64조제2항)"},{"이름":"기반시설설치계획 수립","설명":"지정고시일부터 1년 이내 수립해 도시·군관리계획에 반영, 지구단위계획 수립 시 수립한 것으로 봄(법 제67조제4항, 영 제65조)"},{"이름":"건축행위","설명":"200제곱미터(기존 건축물 포함) 초과 건축물 신축·증축이 부과대상(법 제68조제1항)"},{"이름":"부과","설명":"건축허가를 받은 날부터 2개월 이내(법 제69조제2항)"},{"이름":"납부","설명":"사용승인 신청 시까지, 미납 시 지방행정제재·부과금의 징수 등에 관한 법률에 따라 징수(법 제69조제2항·제3항)"},{"이름":"환급","설명":"사용승인 신청 후 기반시설 추가 설치 등 환급 사유 발생 시(법 제69조제4항)"}]},{"종류":"표","제목":"기반시설부담구역 지정 대상","머리":["구분","지역","근거"],"행":[["지정하여야 하는 지역","법령 제정·개정으로 행위제한이 완화되거나 해제되는 지역","법 제67조제1항제1호"],["지정하여야 하는 지역","법령에 따라 지정된 용도지역 등이 변경·해제되어 행위제한이 완화되는 지역","같은 항 제2호"],["지정하여야 하는 지역","전년도 개발행위허가 건수가 전전년도보다 20퍼센트 이상 증가한 지역","영 제64조제1항제1호"],["지정하여야 하는 지역","전년도 인구증가율이 속한 시·군의 인구증가율보다 20퍼센트 이상 높은 지역","영 제64조제1항제2호"],["임의 지정","개발행위가 집중되어 계획적 관리가 필요하다고 인정하는 경우 위 각 호에 해당하지 않아도 지정 가능","법 제67조제1항 단서"]]}],"함정":"부과대상 면적은 200제곱미터(기존 건축물 연면적 포함)이다. 법령 개정으로 행위제한이 완화되는 지역은 지정해야 하는 지역이다. 부과 기한은 건축허가일부터 2개월, 납부 기한은 사용승인 신청 시까지이다."}},{"i":"S5-2-1-공법-13","r":"S5","g":2,"c":2,"n":53,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 개발밀도관리구역에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["개발밀도관리구역은 주거ㆍ상업ㆍ공업지역은 물론 녹지지역에서도 기반시설의 설치가 곤란한 경우 지정할 수 있다.","개발밀도관리구역에서는 건폐율 또는 용적률을 강화하여 적용하되, 용적률의 강화범위는 해당 용도지역에 적용되는 용적률 최대한도의 30퍼센트 이내이다.","향후 2년 이내에 해당 지역의 하수발생량이 하수시설의 시설용량을 초과할 것으로 예상되는 지역은 개발밀도관리구역으로 지정할 수 있다.","개발밀도관리구역을 지정하려면 미리 해당 지방의회의 의견을 들어야 한다.","개발밀도관리구역은 시ㆍ도지사만 지정할 수 있고 시장 또는 군수는 지정할 수 없다."],"a":[3],"L":"공1-8","o":"변형","x":{"한줄":"향후 2년 이내 하수발생량이 하수시설 용량을 초과할 것으로 예상되는 지역은 개발밀도관리구역 지정 대상이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제66조제1항","원문":"① 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 주거ㆍ상업 또는 공업지역에서의 개발행위로 기반시설(도시ㆍ군계획시설을 포함한다)의 처리ㆍ공급 또는 수용능력이 부족할 것으로 예상되는 지역 중 기반시설의 설치가 곤란한 지역을 개발밀도관리구역으로 지정할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제66조제2항","원문":"② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 개발밀도관리구역에서는 대통령령으로 정하는 범위에서 제77조나 제78조에 따른 건폐율 또는 용적률을 강화하여 적용한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제62조제1항","원문":"①법 제66조제2항에서 \"대통령령으로 정하는 범위\"란 해당 용도지역에 적용되는 용적률의 최대한도의 50퍼센트를 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제66조제3항","원문":"③ 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 제1항에 따라 개발밀도관리구역을 지정하거나 변경하려면 다음 각 호의 사항을 포함하여 해당 지방자치단체에 설치된 지방도시계획위원회의 심의를 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제63조제1호라목","원문":"1. 개발밀도관리구역은 도로ㆍ수도공급설비ㆍ하수도ㆍ학교 등 기반시설의 용량이 부족할 것으로 예상되는 지역중 기반시설의 설치가 곤란한 지역으로서 다음 각목의 1에 해당하는 지역에 대하여 지정할 수 있도록 할 것 라. 향후 2년 이내에 당해 지역의 하수발생량이 하수시설의 시설용량을 초과할 것으로 예상되는 지역"}],"선지":[{"번호":1,"판정":"틀림","설명":"대상은 주거·상업·공업지역이다. 녹지지역은 포함되지 않는다(법 제66조제1항)."},{"번호":2,"판정":"틀림","설명":"용적률 강화 범위는 해당 용도지역 용적률 최대한도의 50퍼센트이다. 30퍼센트가 아니다(영 제62조제1항)."},{"번호":3,"판정":"옳음","설명":"하수발생량이 향후 2년 이내 하수시설 용량을 초과할 것으로 예상되는 지역은 지정 기준에 든다(영 제63조제1호라목)."},{"번호":4,"판정":"틀림","설명":"지정·변경은 해당 지방자치단체의 지방도시계획위원회 심의를 거친다. 지방의회 의견 청취 규정은 없다(법 제66조제3항)."},{"번호":5,"판정":"틀림","설명":"지정권자는 특별시장·광역시장·특별자치시장·특별자치도지사·시장 또는 군수이다(법 제66조제1항)."}],"개념":[{"종류":"표","제목":"개발밀도관리구역 지정기준(영 제63조제1호)","머리":["호","지역","요건"],"행":[["가","도로서비스 수준이 매우 낮은 지역","차량통행이 현저하게 지체되는 지역"],["나","도로율이 낮은 지역","용도지역별 도로율에 20퍼센트 이상 미달"],["다","수도 부족 예상 지역","향후 2년 이내 수요량이 수도시설 용량 초과 예상"],["라","하수 처리 부족 예상 지역","향후 2년 이내 하수발생량이 하수시설 용량 초과 예상"],["마","학교 부족 예상 지역","향후 2년 이내 학생수가 학교수용능력을 20퍼센트 이상 초과 예상"]]},{"종류":"비교","제목":"개발밀도관리구역과 기반시설부담구역","왼쪽":{"이름":"개발밀도관리구역","항목":["대상 지역: 주거·상업·공업지역 중 기반시설 설치가 곤란한 지역(법 제66조제1항)","효과: 건폐율 또는 용적률 강화, 용적률은 최대한도의 50퍼센트 범위(영 제62조제1항)","절차: 지방도시계획위원회 심의 후 공보에 고시하고 인터넷 홈페이지에 게재(법 제66조제3항·제4항, 영 제62조)"]},"오른쪽":{"이름":"기반시설부담구역","항목":["대상 지역: 법령 개정 등으로 행위제한이 완화되는 지역 등(법 제67조제1항)","효과: 200제곱미터 초과 건축물의 신축·증축에 기반시설설치비용 부과(법 제68조제1항)","절차: 주민 의견 청취, 지방도시계획위원회 심의, 고시, 1년 이내 기반시설설치계획 수립(법 제67조, 영 제65조제4항)"]}}],"함정":"지정 대상은 주거·상업·공업지역이고 지정권자에 시장·군수가 포함되며 절차는 지방도시계획위원회 심의이다. 용적률 강화 범위 수치는 50퍼센트이다."}},{"i":"S5-2-1-공법-14","r":"S5","g":2,"c":2,"n":54,"s":"공법","q":"도시개발법령상 도시개발구역에서 허가를 받아야 할 행위로 명시되지 않은 것은?","b":null,"bs":"없음","img":[],"ch":["토지의 합병","토석의 채취","죽목의 식재","공유수면의 매립","｢건축법｣에 따른 건축물의 용도 변경"],"a":[1],"L":"공2-1","o":"기출","x":{"한줄":"토지의 합병은 도시개발구역 행위허가 대상으로 열거돼 있지 않다. 열거된 것은 토지분할이다.","근거":[{"법령":"도시개발법","조문":"제9조제5항","원문":"⑤ 제7조제1항에 따라 도시개발구역지정에 관한 주민 등의 의견청취를 위한 공고가 있는 지역 및 도시개발구역에서 건축물의 건축, 공작물의 설치, 토지의 형질 변경, 토석의 채취, 토지 분할, 물건을 쌓아놓는 행위, 죽목의 벌채 및 식재 등 대통령령으로 정하는 행위를 하려는 자는 특별시장ㆍ광역시장ㆍ특별자치도지사ㆍ시장 또는 군수의 허가를 받아야 한다. 허가받은 사항을 변경하려는 경우에도 또한 같다."},{"법령":"도시개발법 시행령","조문":"제16조제1항","원문":"① 법 제9조제5항에 따라 특별시장ㆍ광역시장ㆍ특별자치도지사ㆍ시장 또는 군수의 허가를 받아야 하는 행위는 다음 각 호와 같다. 1. 건축물의 건축 등: 「건축법」 제2조제1항제2호에 따른 건축물(가설건축물을 포함한다)의 건축, 대수선(大修繕) 또는 용도 변경 3. 토지의 형질변경: 절토(땅깎기)ㆍ성토(흙쌓기)ㆍ정지ㆍ포장 등의 방법으로 토지의 형상을 변경하는 행위, 토지의 굴착 또는 공유수면의 매립 4. 토석의 채취: 흙ㆍ모래ㆍ자갈ㆍ바위 등의 토석을 채취하는 행위. 다만, 토지의 형질 변경을 목적으로 하는 것은 제3호에 따른다. 5. 토지분할 7. 죽목(竹木)의 벌채 및 식재(植栽)"}],"선지":[{"번호":1,"판정":"틀림","설명":"행위허가 대상은 건축물의 건축 등, 공작물의 설치, 토지의 형질변경, 토석의 채취, 토지분할, 물건 쌓아놓기, 죽목의 벌채 및 식재이다. 토지의 합병은 없다(영 제16조제1항)."},{"번호":2,"판정":"옳음","설명":"토석의 채취는 제4호에 있다."},{"번호":3,"판정":"옳음","설명":"죽목의 벌채 및 식재는 제7호에 있다."},{"번호":4,"판정":"옳음","설명":"공유수면의 매립은 제3호 토지의 형질변경에 포함된다."},{"번호":5,"판정":"옳음","설명":"건축물의 건축, 대수선 또는 용도 변경은 제1호에 있다."}],"개념":[{"종류":"표","제목":"도시개발구역의 행위허가 대상(영 제16조제1항)","머리":["호","행위","비고"],"행":[["1","건축물의 건축 등","건축·대수선·용도 변경, 가설건축물 포함"],["2","공작물의 설치","건축물을 제외한 인공 시설물"],["3","토지의 형질변경","절토·성토·정지·포장, 토지의 굴착, 공유수면의 매립"],["4","토석의 채취","토지 형질변경 목적이면 제3호"],["5","토지분할","합병은 열거되지 않음"],["6","물건을 쌓아놓는 행위","옮기기 쉽지 않은 물건을 1개월 이상"],["7","죽목의 벌채 및 식재","관상용 임시 식재 등은 예외"]]},{"종류":"표","제목":"도시개발구역의 지정대상 규모(영 제2조제1항)","머리":["구분","규모"],"행":[["도시지역 주거지역·상업지역","1만제곱미터 이상"],["도시지역 공업지역","3만제곱미터 이상"],["도시지역 자연녹지지역","1만제곱미터 이상"],["도시지역 생산녹지지역(구역 지정면적의 100분의 30 이하인 경우만)","1만제곱미터 이상"],["도시지역 외의 지역","30만제곱미터 이상(아파트·연립주택 건설계획 포함 시 일정 요건 충족하면 10만제곱미터 이상)"]]}],"함정":"토지분할은 허가 대상이고 합병은 열거되지 않는다. 죽목은 벌채와 식재가 모두 대상이다. 공유수면의 매립은 토지의 형질변경에 들어가고, 건축물의 용도 변경은 건축물의 건축 등에 들어간다."}},{"i":"S5-2-1-공법-15","r":"S5","g":2,"c":2,"n":55,"s":"공법","q":"도시개발법령상 도시개발사업의 시행자에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["국가는 도시개발사업의 시행자가 될 수 없다.","지정권자는 시행자가 도시개발사업에 관한 실시계획의 인가를 받은 후 1년 이내에 사업을 착수하지 아니하는 경우 시행자를 변경할 수 있다.","토지 소유자가 도시개발구역의 지정을 제안하려는 경우에는 대상 구역 토지면적의 3분의 1 이상에 해당하는 토지 소유자의 동의를 받아야 한다.","도시개발구역의 전부를 환지 방식으로 시행하는 경우에는 지정권자는 토지 소유자나 조합을 시행자로 지정한다.","지방공사는 조성된 토지의 분양을 「주택법」에 따른 주택건설사업자에게 대행하게 할 수 없다."],"a":[4],"L":"공2-2","o":"변형","x":{"한줄":"도시개발구역의 전부를 환지 방식으로 시행하면 토지 소유자나 조합을 시행자로 지정한다.","근거":[{"법령":"도시개발법","조문":"제11조제1항","원문":"① 도시개발사업의 시행자(이하 \"시행자\"라 한다)는 다음 각 호의 자 중에서 지정권자가 지정한다. 다만, 도시개발구역의 전부를 환지 방식으로 시행하는 경우에는 제5호의 토지 소유자나 제6호의 조합을 시행자로 지정한다."},{"법령":"도시개발법","조문":"제11조제8항","원문":"⑧ 지정권자는 다음 각 호의 어느 하나에 해당하는 경우에는 시행자를 변경할 수 있다. 1. 도시개발사업에 관한 실시계획의 인가를 받은 후 2년 이내에 사업을 착수하지 아니하는 경우"},{"법령":"도시개발법","조문":"제11조제6항","원문":"⑥ 토지 소유자 또는 제1항제7호부터 제11호까지(제1항제1호부터 제4호까지의 규정에 해당하는 자가 대통령령으로 정하는 비율을 초과하여 출자한 경우는 제외한다)의 규정에 해당하는 자가 제5항에 따라 도시개발구역의 지정을 제안하려는 경우에는 대상 구역 토지면적의 3분의 2 이상에 해당하는 토지 소유자(지상권자를 포함한다)의 동의를 받아야 한다."},{"법령":"도시개발법","조문":"제11조제11항","원문":"⑪ 제1항제1호부터 제4호까지의 규정에 해당하는 자는 도시개발사업을 효율적으로 시행하기 위하여 필요한 경우에는 대통령령으로 정하는 바에 따라 설계ㆍ분양 등 도시개발사업의 일부를 「주택법」 제4조에 따른 주택건설사업자 등으로 하여금 대행하게 할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국가나 지방자치단체는 시행자가 될 수 있다(법 제11조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"사업 미착수로 시행자를 변경할 수 있는 시점은 실시계획 인가 후 2년 이내이다. 1년이 아니다(법 제11조제8항제1호)."},{"번호":3,"판정":"틀림","설명":"구역 지정을 제안하려면 대상 구역 토지면적의 3분의 2 이상에 해당하는 토지 소유자의 동의가 필요하다(법 제11조제6항)."},{"번호":4,"판정":"옳음","설명":"전부 환지 방식이면 제5호의 토지 소유자나 제6호의 조합을 시행자로 지정한다(법 제11조제1항 단서)."},{"번호":5,"판정":"틀림","설명":"국가·지방자치단체·공공기관·정부출연기관·지방공사는 설계·분양 등 사업의 일부를 「주택법」 제4조에 따른 주택건설사업자 등으로 하여금 대행하게 할 수 있다(법 제11조제11항)."}],"개념":[{"종류":"표","제목":"도시개발사업 시행자(법 제11조제1항)","머리":["구분","시행자"],"행":[["공공(제1호~제4호)","국가·지방자치단체, 대통령령으로 정하는 공공기관, 정부출연기관, 지방공사"],["토지 소유자 계열(제5호·제6호)","도시개발구역의 토지 소유자, 토지 소유자가 설립한 조합(전부 환지 방식인 경우만)"],["민간(제7호~제11호)","과밀억제권역에서 이전하는 법인, 주택법상 등록자, 건설산업기본법상 토목공사업·토목건축공사업 면허자 등, 부동산개발업자, 부동산투자회사, 위 시행자가 출자해 설립한 법인"],["수용·사용 방식의 토지 소유자","국·공유지를 제외한 토지면적의 3분의 2 이상을 소유한 자(제5호 괄호)"],["전부 환지 방식","토지 소유자나 조합을 시행자로 지정(제1항 단서)"]]},{"종류":"표","제목":"시행자 변경 사유(법 제11조제8항)","머리":["호","사유"],"행":[["1","실시계획 인가를 받은 후 2년 이내에 사업을 착수하지 아니하는 경우"],["2","행정처분으로 시행자 지정이나 실시계획 인가가 취소된 경우"],["3","시행자의 부도·파산 등으로 도시개발사업의 목적을 달성하기 어렵다고 인정되는 경우"],["4","제1항 단서에 따라 지정된 자가 대통령령으로 정하는 기간에 실시계획 인가를 신청하지 않은 경우"]]}],"함정":"시행자 변경 사유의 기간은 인가 후 2년이다. 구역 지정 제안 동의율은 3분의 2이다. 국가와 지방자치단체는 시행자가 될 수 있고, 지방공사 같은 공공 시행자는 분양 등을 주택건설사업자에게 대행하게 할 수 있다."}},{"i":"S5-2-1-공법-16","r":"S5","g":2,"c":2,"n":56,"s":"공법","q":"도시개발법령상 도시개발사업 조합에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["조합은 그 주된 사무소의 소재지에서 등기를 하면 성립한다.","주된 사무소의 소재지를 변경하려면 지정권자로부터 변경인가를 받아야 한다.","조합 설립의 인가를 신청하려면 해당 도시개발구역의 토지면적의 3분의 2 이상에 해당하는 토지 소유자와 그 구역의 토지 소유자 총수의 2분의 1 이상의 동의를 받아야 한다.","조합의 조합원은 도시개발구역의 토지 소유자로 한다.","조합의 설립인가를 받은 조합의 대표자는 설립인가를 받은 날부터 30일 이내에 주된 사무소의 소재지에서 설립등기를 하여야 한다."],"a":[2],"L":"공2-2","o":"기출","x":{"한줄":"주된 사무소의 소재지를 변경하는 것은 경미한 사항의 변경이어서 변경인가가 아니라 신고 대상이다.","근거":[{"법령":"도시개발법","조문":"제13조제2항","원문":"② 조합이 제1항에 따라 인가를 받은 사항을 변경하려면 지정권자로부터 변경인가를 받아야 한다. 다만, 대통령령으로 정하는 경미한 사항을 변경하려는 경우에는 신고하여야 한다."},{"법령":"도시개발법 시행령","조문":"제30조제1호","원문":"제30조(조합설립인가사항의 경미한 변경) 법 제13조제2항 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하려는 경우\"란 다음 각 호의 경우를 말한다. 1. 주된 사무소의 소재지를 변경하려는 경우"},{"법령":"도시개발법","조문":"제13조제3항","원문":"③ 제1항에 따라 조합 설립의 인가를 신청하려면 해당 도시개발구역의 토지면적의 3분의 2 이상에 해당하는 토지 소유자와 그 구역의 토지 소유자 총수의 2분의 1 이상의 동의를 받아야 한다."},{"법령":"도시개발법","조문":"제14조제1항","원문":"① 조합의 조합원은 도시개발구역의 토지 소유자로 한다."},{"법령":"도시개발법","조문":"제15조제2항","원문":"② 조합은 그 주된 사무소의 소재지에서 등기를 하면 성립한다."},{"법령":"도시개발법 시행령","조문":"제32조제1항","원문":"① 법 제13조에 따라 조합의 설립인가를 받은 조합의 대표자는 설립인가를 받은 날부터 30일 이내에 주된 사무소의 소재지에서 설립등기를 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"조합은 법인이고 주된 사무소의 소재지에서 등기하면 성립한다(법 제15조제1항·제2항)."},{"번호":2,"판정":"틀림","설명":"주된 사무소의 소재지 변경은 경미한 사항이다. 신고하면 된다(법 제13조제2항 단서, 영 제30조제1호)."},{"번호":3,"판정":"옳음","설명":"설립인가 신청에는 토지면적 3분의 2 이상의 토지 소유자와 토지 소유자 총수 2분의 1 이상의 동의가 필요하다(법 제13조제3항)."},{"번호":4,"판정":"옳음","설명":"조합원은 도시개발구역의 토지 소유자이다(법 제14조제1항)."},{"번호":5,"판정":"옳음","설명":"설립인가를 받은 날부터 30일 이내에 설립등기를 한다(영 제32조제1항)."}],"개념":[{"종류":"흐름","제목":"도시개발조합 설립 절차","단계":[{"이름":"정관 작성","설명":"토지 소유자 7명 이상이 정관을 작성(법 제13조제1항)"},{"이름":"동의 확보","설명":"구역 토지면적의 3분의 2 이상에 해당하는 토지 소유자와 토지 소유자 총수의 2분의 1 이상, 인가 신청 전에는 철회 가능(법 제13조제3항, 영 제31조제2항)"},{"이름":"설립인가","설명":"지정권자의 인가(법 제13조제1항)"},{"이름":"설립등기","설명":"인가를 받은 날부터 30일 이내 주된 사무소의 소재지에서 대표자가 등기(영 제32조제1항)"},{"이름":"조합 성립","설명":"등기하면 법인으로 성립(법 제15조제1항·제2항)"}]},{"종류":"표","제목":"조합 인가사항의 변경","머리":["구분","절차","근거"],"행":[["일반 변경","지정권자로부터 변경인가","법 제13조제2항 본문"],["주된 사무소의 소재지 변경","신고","영 제30조제1호"],["공고방법 변경","신고","영 제30조제2호"],["임원 결격","피성년후견인·피한정후견인·미성년자, 복권되지 않은 파산자, 금고 이상 형 집행 종료 후 2년이 지나지 않은 자 또는 집행유예 기간 중인 자","법 제14조제3항"]]}],"함정":"조합 인가사항 변경은 원칙적으로 변경인가이고, 주된 사무소 소재지와 공고방법 변경은 신고이다. 설립 동의율은 면적 3분의 2와 인원 2분의 1이고, 설립등기는 인가일부터 30일 이내이다."}},{"i":"S5-2-1-공법-17","r":"S5","g":2,"c":2,"n":57,"s":"공법","q":"도시개발법령상 수용 또는 사용의 방식에 따른 사업 시행에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["시행자는 도시개발구역 전체 토지 면적의 2분의 1 이내에서 원형지를 공급하여 개발하게 할 수 있다.","국가나 지방자치단체가 아닌 원형지개발자는 원형지에 대한 공사완료 공고일부터 5년과 원형지 공급계약일부터 10년 중 먼저 끝나는 기간 안에는 원형지를 매각할 수 없다. 다만, 일정한 경우로서 미리 지정권자의 승인을 받으면 예외로 한다.","도시개발구역의 토지 소유자가 시행자로서 토지등을 수용 또는 사용하려면 사업대상 토지면적의 2분의 1 이상을 소유하고 토지 소유자 총수의 3분의 2 이상의 동의를 받아야 한다.","공공기관인 시행자가 토지상환채권을 발행하려면 대통령령으로 정하는 금융기관 등의 지급보증을 받아야 한다.","수용 대상 토지의 세부목록을 고시한 경우 사업인정 및 그 고시가 있었던 것으로 보며, 이 경우 재결신청은 사업인정 고시일부터 1년 이내에 하여야 한다."],"a":[2],"L":"공2-3","o":"변형","x":{"한줄":"국가·지방자치단체가 아닌 원형지개발자는 공사완료 공고일부터 5년과 계약일부터 10년 중 먼저 끝나는 기간 안에 원형지를 매각할 수 없다.","근거":[{"법령":"도시개발법","조문":"제25조의2제1항","원문":"① 시행자는 도시를 자연친화적으로 개발하거나 복합적ㆍ입체적으로 개발하기 위하여 필요한 경우에는 대통령령으로 정하는 절차에 따라 미리 지정권자의 승인을 받아 다음 각 호의 어느 하나에 해당하는 자에게 원형지를 공급하여 개발하게 할 수 있다. 이 경우 공급될 수 있는 원형지의 면적은 도시개발구역 전체 토지 면적의 3분의 1 이내로 한정한다."},{"법령":"도시개발법","조문":"제25조의2제6항","원문":"⑥ 원형지개발자(국가 및 지방자치단체는 제외한다)는 10년의 범위에서 대통령령으로 정하는 기간 안에는 원형지를 매각할 수 없다. 다만, 이주용 주택이나 공공ㆍ문화 시설 등 대통령령으로 정하는 경우로서 미리 지정권자의 승인을 받은 경우에는 예외로 한다."},{"법령":"도시개발법 시행령","조문":"제55조의2제3항","원문":"③ 법 제25조의2제6항 본문에서 \"대통령령으로 정하는 기간\"이란 다음 각 호의 기간 중 먼저 끝나는 기간을 말한다. 1. 원형지에 대한 공사완료 공고일부터 5년 2. 원형지 공급 계약일부터 10년"},{"법령":"도시개발법","조문":"제22조제1항","원문":"① 시행자는 도시개발사업에 필요한 토지등을 수용하거나 사용할 수 있다. 다만, 제11조제1항제5호 및 제7호부터 제11호까지의 규정(같은 항 제1호부터 제4호까지의 규정에 해당하는 자가 100분의 50 비율을 초과하여 출자한 경우는 제외한다)에 해당하는 시행자는 사업대상 토지면적의 3분의 2 이상에 해당하는 토지를 소유하고 토지 소유자 총수의 2분의 1 이상에 해당하는 자의 동의를 받아야 한다. 이 경우 토지 소유자의 동의요건 산정기준일은 도시개발구역지정 고시일을 기준으로 하며, 그 기준일 이후 시행자가 취득한 토지에 대하여는 동의 요건에 필요한 토지 소유자의 총수에 포함하고 이를 동의한 자의 수로 산정한다."},{"법령":"도시개발법","조문":"제23조제1항","원문":"① 시행자는 토지 소유자가 원하면 토지등의 매수 대금의 일부를 지급하기 위하여 대통령령으로 정하는 바에 따라 사업 시행으로 조성된 토지ㆍ건축물로 상환하는 채권(이하 \"토지상환채권\"이라 한다)을 발행할 수 있다. 다만, 제11조제1항제5호부터 제11호까지의 규정에 해당하는 자는 대통령령으로 정하는 금융기관 등으로부터 지급보증을 받은 경우에만 이를 발행할 수 있다."},{"법령":"도시개발법","조문":"제22조제3항","원문":"③ 제2항에 따라 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」을 준용할 때 제5조제1항제14호에 따른 수용 또는 사용의 대상이 되는 토지의 세부목록을 고시한 경우에는 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 제20조제1항과 제22조에 따른 사업인정 및 그 고시가 있었던 것으로 본다. 다만, 재결신청은 같은 법 제23조제1항과 제28조제1항에도 불구하고 개발계획에서 정한 도시개발사업의 시행 기간 종료일까지 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"원형지 면적은 도시개발구역 전체 토지 면적의 3분의 1 이내이다(법 제25조의2제1항)."},{"번호":2,"판정":"옳음","설명":"국가·지방자치단체를 제외한 원형지개발자는 공사완료 공고일부터 5년, 공급계약일부터 10년 중 먼저 끝나는 기간 안에 매각할 수 없다. 기반시설 용지, 임대주택 용지 등으로 사용하는 경우는 미리 지정권자 승인을 받으면 예외이다(법 제25조의2제6항, 영 제55조의2제3항·제4항)."},{"번호":3,"판정":"틀림","설명":"동의 요건은 사업대상 토지면적의 3분의 2 이상 소유와 토지 소유자 총수의 2분의 1 이상 동의이다. 비율이 뒤바뀌었다(법 제22조제1항)."},{"번호":4,"판정":"틀림","설명":"지급보증은 제11조제1항제5호부터 제11호까지에 해당하는 시행자에게만 요구된다. 공공기관은 제2호 시행자이므로 해당하지 않는다(법 제23조제1항 단서)."},{"번호":5,"판정":"틀림","설명":"세부목록을 고시하면 사업인정 및 고시가 있었던 것으로 보되, 재결신청은 개발계획에서 정한 시행 기간 종료일까지 한다(법 제22조제3항)."}],"개념":[{"종류":"표","제목":"수용·사용 방식 주요 요건","머리":["항목","내용","근거"],"행":[["수용 동의(토지 소유자 등 시행자)","사업대상 토지면적의 3분의 2 이상 소유 + 토지 소유자 총수의 2분의 1 이상 동의","법 제22조제1항"],["사업인정 의제","세부목록 고시 시 사업인정·고시 의제, 재결신청은 개발계획의 시행 기간 종료일까지","법 제22조제3항"],["토지상환채권 발행규모","상환할 토지·건축물이 분양토지·분양건축물 면적의 2분의 1 이하","영 제45조"],["지급보증","제11조제1항제5호~제11호 시행자만 금융기관 등 지급보증","법 제23조제1항 단서"],["선수금(공공 시행자)","개발계획 수립·고시 후 사업시행 토지면적의 100분의 10 이상 토지 소유권 확보(사용동의 포함), 지정권자 승인","영 제55조제1항제1호"],["원형지 공급 면적","도시개발구역 전체 토지 면적의 3분의 1 이내, 지정권자 승인","법 제25조의2제1항"]]},{"종류":"흐름","제목":"원형지 공급·개발 절차","단계":[{"이름":"공급 승인 신청","설명":"원형지 공급계획(개발자, 공급내용 포함)을 작성해 지정권자에게 제출(법 제25조의2제2항·제3항)"},{"이름":"승인","설명":"지정권자가 개발계획 수립 후 승인, 개발밀도·기반시설 등 이행조건을 붙일 수 있음(영 제55조의2제2항, 법 제25조의2제5항)"},{"이름":"공급계약","설명":"원형지개발자 선정은 수의계약, 공급가격은 감정가격에 기반시설 공사비를 더한 금액 기준으로 협의(영 제55조의2제6항·제7항)"},{"이름":"세부계획 제출·반영","설명":"원형지개발자의 세부계획을 실시계획 내용에 반영(법 제25조의2제4항)"},{"이름":"개발·매각 제한","설명":"국가·지방자치단체 외에는 일정 기간 매각 금지(법 제25조의2제6항)"},{"이름":"위반 시 조치","설명":"시행자는 2회 이상 시정을 요구한 뒤 공급계약 해제 가능(영 제55조의2제5항)"}]}],"함정":"원형지는 구역 전체의 3분의 1 이내이다. 토지 소유자 시행자의 수용 동의는 면적 3분의 2 이상 소유와 인원 2분의 1 이상 동의이다. 세부목록 고시 시 사업인정이 의제되어도 재결신청 기한은 일반 규정이 아니라 시행 기간 종료일이다. 지급보증은 공공 시행자에게 요구되지 않는다."}},{"i":"S5-2-1-공법-18","r":"S5","g":2,"c":2,"n":58,"s":"공법","q":"도시개발법령상 환지 방식에 의한 사업시행에 관한 설명으로 틀린 것은? (단, 시행자는 행정청이 아님)","b":null,"bs":"없음","img":[],"ch":["시행자는 입체 환지를 시행하는 경우 건축 계획이 포함된 환지 계획을 작성하여야 한다.","환지 설계를 평가식으로 하는 경우 평균부담률은 '[총사업비/(권리가액의 합계+체비지 평가액의 합계)]×100'의 계산식에 따른다.","환지 계획에서 환지를 정하지 아니한 종전의 토지에 있던 권리는 그 환지처분이 공고되고 소유권이전등기를 마친 때에 소멸한다.","시행자는 토지 면적의 규모를 조정할 특별한 필요가 있으면 면적이 작은 토지는 과소 토지가 되지 아니하도록 면적을 늘려 환지를 정하거나 환지 대상에서 제외할 수 있다.","평면 환지는 환지 전 토지에 대한 권리를 도시개발사업으로 조성되는 토지에 이전하는 방식이다."],"a":[3],"L":"공2-4","o":"기출","x":{"한줄":"환지를 정하지 않은 종전 토지의 권리는 환지처분이 공고된 날이 끝나는 때에 소멸하고 등기 완료와는 무관하다.","근거":[{"법령":"도시개발법","조문":"제42조제1항","원문":"① 환지 계획에서 정하여진 환지는 그 환지처분이 공고된 날의 다음 날부터 종전의 토지로 보며, 환지 계획에서 환지를 정하지 아니한 종전의 토지에 있던 권리는 그 환지처분이 공고된 날이 끝나는 때에 소멸한다."},{"법령":"도시개발법 시행규칙","조문":"제26조제3항제3호","원문":"③ 법 제28조제1항제6호에서 \"국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 3. 건축 계획(입체 환지를 시행하는 경우로 한정한다)"},{"법령":"도시개발법 시행규칙","조문":"제26조제4항제1호","원문":"평균부담률 = [총사업비/(권리가액의 합계 + 체비지 평가액의 합계)] × 100"},{"법령":"도시개발법","조문":"제31조제1항","원문":"① 시행자는 토지 면적의 규모를 조정할 특별한 필요가 있으면 면적이 작은 토지는 과소(過小) 토지가 되지 아니하도록 면적을 늘려 환지를 정하거나 환지 대상에서 제외할 수 있고, 면적이 넓은 토지는 그 면적을 줄여서 환지를 정할 수 있다."},{"법령":"도시개발법 시행규칙","조문":"제27조제2항제1호","원문":"② 환지의 방식은 다음 각 호와 같이 구분한다. 1. 평면 환지: 환지 전 토지에 대한 권리를 도시개발사업으로 조성되는 토지에 이전하는 방식"}],"선지":[{"번호":1,"판정":"옳음","설명":"입체 환지를 시행하는 경우 환지 계획에 건축 계획이 포함된다(시행규칙 제26조제3항제3호, 법 제28조제1항)."},{"번호":2,"판정":"옳음","설명":"평가식 환지 설계의 평균부담률은 총사업비를 권리가액 합계와 체비지 평가액 합계의 합으로 나눈 값에 100을 곱한다(시행규칙 제26조제4항제1호)."},{"번호":3,"판정":"틀림","설명":"환지를 정하지 않은 종전 토지의 권리는 환지처분이 공고된 날이 끝나는 때에 소멸한다. 소유권이전등기와는 관계가 없다(법 제42조제1항)."},{"번호":4,"판정":"옳음","설명":"면적이 작은 토지는 과소 토지가 되지 않도록 면적을 늘려 환지를 정하거나 환지 대상에서 제외할 수 있다(법 제31조제1항)."},{"번호":5,"판정":"옳음","설명":"평면 환지는 환지 전 토지에 대한 권리를 조성되는 토지에 이전하는 방식이다(시행규칙 제27조제2항제1호)."}],"개념":[{"종류":"흐름","제목":"환지 방식 사업 절차","단계":[{"이름":"환지 계획 작성","설명":"환지 설계, 환지 명세, 청산 대상 토지 명세, 체비지·보류지 명세 등(법 제28조제1항)"},{"이름":"계획 인가","설명":"행정청이 아닌 시행자는 특별자치도지사·시장·군수·구청장의 인가(법 제29조제1항)"},{"이름":"공람·의견","설명":"토지 소유자·임차권자등에게 알리고 공람, 공람 종료일부터 60일 이내 반영 여부 통보(법 제29조제3항·제6항)"},{"이름":"환지 예정지 지정","설명":"지정의 효력 발생일부터 환지처분 공고일까지 환지 예정지에서 종전과 같은 권리 행사(법 제35조, 제36조제1항)"},{"이름":"공사 완료 공고·공람","설명":"공사를 끝낸 뒤 공고하고 관계 서류 공람(법 제40조제1항)"},{"이름":"준공검사·환지처분","설명":"준공검사를 받은 뒤 대통령령으로 정한 기간에 환지처분, 토지 소유자에게 알리고 공고(법 제40조제4항·제5항)"},{"이름":"효과·등기","설명":"공고일이 끝나는 때 권리 소멸, 다음 날 청산금 확정, 공고 후 14일 이내 등기 촉탁·신청(법 제42조, 제43조제1항)"}]},{"종류":"비교","제목":"평면 환지와 입체 환지","왼쪽":{"이름":"평면 환지","항목":["환지 전 토지에 대한 권리를 조성되는 토지에 이전(시행규칙 제27조제2항제1호)","위치는 환지 전 토지의 용도, 보유 기간, 위치, 권리가액, 청산금 규모 등을 고려(같은 조 제4항제1호)"]},"오른쪽":{"이름":"입체 환지","항목":["환지 전 토지나 건축물(무허가 제외)에 대한 권리를 건설되는 구분건축물에 이전(시행규칙 제27조제2항제2호)","토지 소유자 등의 신청에 따라 위치 결정, 같은 신청이 둘 이상이면 보유 기간·거주 기간·권리가액 등 고려(같은 조 제4항제2호)","신청 기간은 통지한 날부터 30일 이상 60일 이하(법 제32조제4항)"]}}],"함정":"효과가 생기는 시점은 환지처분 공고일이다. 환지를 정하지 않은 종전 토지의 권리는 그날이 끝나는 때 소멸하고, 환지는 다음 날부터 종전의 토지로 본다. 등기는 공고 후 14일 이내에 촉탁·신청하는 별개 절차이다."}},{"i":"S5-2-1-공법-19","r":"S5","g":2,"c":2,"n":59,"s":"공법","q":"도시개발법령상 ｢지방공기업법｣에 따라 설립된 지방공사가 단독으로 토지상환채권을 발행하는 경우에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["｢은행법｣에 따른 은행으로부터 지급보증을 받은 경우에만 토지상환채권을 발행할 수 있다.","토지상환채권의 발행규모는 그 토지상환채권으로 상환할 토지ㆍ건축물이 해당 도시개발사업으로 조성되는 분양토지 또는 분양건축물 면적의 2분의 1을 초과하지 아니하도록 하여야 한다.","토지상환채권은 이전할 수 없다.","토지가격의 추산방법은 토지상환채권의 발행계획에 포함되지 않는다.","토지등의 매수 대금 일부의 지급을 위하여 토지상환채권을 발행할 수 없다."],"a":[2],"L":"공2-4","o":"기출","x":{"한줄":"토지상환채권의 발행규모는 분양토지·분양건축물 면적의 2분의 1을 초과할 수 없다.","근거":[{"법령":"도시개발법 시행령","조문":"제45조","원문":"제45조(토지상환채권의 발행규모) 법 제23조제1항에 따른 토지상환채권(이하 \"토지상환채권\"이라 한다)의 발행규모는 그 토지상환채권으로 상환할 토지ㆍ건축물이 해당 도시개발사업으로 조성되는 분양토지 또는 분양건축물 면적의 2분의 1을 초과하지 아니하도록 하여야 한다."},{"법령":"도시개발법","조문":"제23조제1항","원문":"① 시행자는 토지 소유자가 원하면 토지등의 매수 대금의 일부를 지급하기 위하여 대통령령으로 정하는 바에 따라 사업 시행으로 조성된 토지ㆍ건축물로 상환하는 채권(이하 \"토지상환채권\"이라 한다)을 발행할 수 있다. 다만, 제11조제1항제5호부터 제11호까지의 규정에 해당하는 자는 대통령령으로 정하는 금융기관 등으로부터 지급보증을 받은 경우에만 이를 발행할 수 있다."},{"법령":"도시개발법 시행령","조문":"제47조제6호","원문":"제47조(토지상환채권의 발행계획) 법 제23조제2항에 따른 토지상환채권의 발행계획에는 다음 각 호의 사항이 포함되어야 한다. 6. 토지가격의 추산방법"},{"법령":"도시개발법 시행령","조문":"제53조제1항","원문":"① 토지상환채권을 이전하는 경우 취득자는 그 성명과 주소를 토지상환채권원부에 기재하여 줄 것을 요청하여야 하며, 취득자의 성명과 주소가 토지상환채권에 기재되지 아니하면 취득자는 발행자 및 그 밖의 제3자에게 대항하지 못한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지급보증은 제11조제1항제5호부터 제11호까지의 시행자에게 요구된다. 지방공사는 제4호 시행자이므로 지급보증 없이 발행할 수 있다(법 제23조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"발행규모는 분양토지·분양건축물 면적의 2분의 1을 넘지 않아야 한다(영 제45조)."},{"번호":3,"판정":"틀림","설명":"토지상환채권은 이전할 수 있다. 취득자의 성명과 주소를 원부에 기재해야 발행자와 제3자에게 대항할 수 있다(영 제53조제1항)."},{"번호":4,"판정":"틀림","설명":"발행계획에 토지가격의 추산방법이 포함된다(영 제47조제6호)."},{"번호":5,"판정":"틀림","설명":"토지등의 매수 대금의 일부를 지급하기 위해 발행할 수 있다(법 제23조제1항)."}],"개념":[{"종류":"표","제목":"토지상환채권 요건","머리":["항목","내용","근거"],"행":[["발행 목적","토지 소유자가 원하면 토지등의 매수 대금의 일부를 조성된 토지·건축물로 상환","법 제23조제1항"],["발행규모","상환할 토지·건축물이 분양토지·분양건축물 면적의 2분의 1 이하","영 제45조"],["지급보증","제11조제1항제5호~제11호 시행자는 은행, 보험회사, 공제조합 등의 지급보증","법 제23조제1항 단서, 영 제46조"],["발행계획 승인","시행자(지정권자 제외)는 발행계획을 작성해 미리 지정권자의 승인","법 제23조제2항"],["증권 형식","기명식 증권","영 제49조제2항"],["이전","취득자 성명·주소를 원부에 기재해야 제3자 대항, 질권자도 원부 기재","영 제53조"]]},{"종류":"흐름","제목":"토지상환채권 발행 절차","단계":[{"이름":"발행계획 작성","설명":"시행자 명칭, 발행총액, 이율, 발행가액·시기, 상환대상지역 또는 토지 용도, 토지가격의 추산방법, 보증기관·내용(영 제47조)"},{"이름":"지정권자 승인","설명":"지정권자가 시행자인 경우를 제외하고 미리 승인(법 제23조제2항)"},{"이름":"발행공고","설명":"채권 명칭과 발행계획 사항 공고(영 제48조)"},{"이름":"청약","설명":"청약자가 청약서 2통을 작성해 시행자에게 제출(영 제50조)"},{"이름":"발행·이전","설명":"기명식 증권으로 발행하고 이전은 원부 기재(영 제49조, 제53조)"}]}],"함정":"지방공사는 법 제11조제1항제4호 시행자여서 지급보증 대상이 아니다. 발행규모는 2분의 1 이하이고, 발행계획에는 토지가격의 추산방법이 들어가며, 채권은 이전할 수 있다."}},{"i":"S5-2-1-공법-20","r":"S5","g":2,"c":2,"n":60,"s":"공법","q":"도시 및 주거환경정비법령상 정비기반시설에 해당하지 않는 것은? (단, 주거환경개선사업을 위하여 지정ㆍ고시된 정비구역이 아님)","b":null,"bs":"없음","img":[],"ch":["녹지","공공공지","공용주차장","소방용수시설","공동으로 사용하는 구판장"],"a":[5],"L":"공3-1","o":"기출","x":{"한줄":"공동으로 사용하는 구판장은 공동이용시설이고 정비기반시설이 아니다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제2조제4호","원문":"4. \"정비기반시설\"이란 도로ㆍ상하수도ㆍ구거(溝渠: 도랑)ㆍ공원ㆍ공용주차장ㆍ공동구(「국토의 계획 및 이용에 관한 법률」 제2조제9호에 따른 공동구를 말한다. 이하 같다), 그 밖에 주민의 생활에 필요한 열ㆍ가스 등의 공급시설로서 대통령령으로 정하는 시설을 말한다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제3조","원문":"제3조(정비기반시설) 법 제2조제4호에서 \"대통령령으로 정하는 시설\"이란 다음 각 호의 시설을 말한다. 1. 녹지 3. 공공공지 5. 소방용수시설"},{"법령":"도시 및 주거환경정비법","조문":"제2조제5호","원문":"5. \"공동이용시설\"이란 주민이 공동으로 사용하는 놀이터ㆍ마을회관ㆍ공동작업장, 그 밖에 대통령령으로 정하는 시설을 말한다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제4조","원문":"제4조(공동이용시설) 법 제2조제5호에서 \"대통령령으로 정하는 시설\"이란 다음 각 호의 시설을 말한다. 1. 공동으로 사용하는 구판장ㆍ세탁장ㆍ화장실 및 수도"}],"선지":[{"번호":1,"판정":"옳음","설명":"녹지는 정비기반시설이다(영 제3조제1호)."},{"번호":2,"판정":"옳음","설명":"공공공지는 정비기반시설이다(영 제3조제3호)."},{"번호":3,"판정":"옳음","설명":"공용주차장은 법에서 직접 정한 정비기반시설이다(법 제2조제4호)."},{"번호":4,"판정":"옳음","설명":"소방용수시설은 정비기반시설이다(영 제3조제5호)."},{"번호":5,"판정":"틀림","설명":"공동으로 사용하는 구판장은 공동이용시설이다(영 제4조제1호). 주거환경개선사업 정비구역에서 사업시행계획서에 시장·군수등이 관리하는 것으로 포함된 공동이용시설만 정비기반시설이 되는데(영 제3조제9호), 이 문항은 그 정비구역이 아니다."}],"개념":[{"종류":"표","제목":"정비기반시설과 공동이용시설","머리":["구분","시설","근거"],"행":[["정비기반시설(법)","도로, 상하수도, 구거, 공원, 공용주차장, 공동구, 열·가스 등 공급시설","법 제2조제4호"],["정비기반시설(영)","녹지, 하천, 공공공지, 광장, 소방용수시설, 비상대피시설, 가스공급시설, 지역난방시설","영 제3조제1호~제8호"],["정비기반시설(영)","주거환경개선사업 정비구역의 공동이용시설로서 사업시행계획서에 시장·군수등이 관리하는 것으로 포함된 시설","영 제3조제9호"],["공동이용시설(법)","놀이터, 마을회관, 공동작업장","법 제2조제5호"],["공동이용시설(영)","공동으로 사용하는 구판장·세탁장·화장실 및 수도, 탁아소·어린이집·경로당 등 노유자시설, 시·도조례로 정하는 유사 시설","영 제4조"]]},{"종류":"표","제목":"정비사업의 종류(법 제2조제2호)","머리":["사업","대상 지역·목적"],"행":[["주거환경개선사업","도시저소득 주민이 집단거주하고 정비기반시설이 극히 열악하며 노후·불량건축물이 과도하게 밀집한 지역의 주거환경 개선, 또는 단독주택·다세대주택 밀집 지역에서 정비기반시설과 공동이용시설 확충"],["재개발사업","정비기반시설이 열악하고 노후·불량건축물이 밀집한 지역의 주거환경 개선, 상업지역·공업지역 등에서 도시기능 회복과 상권활성화를 위한 도시환경 개선"],["재건축사업","정비기반시설은 양호하나 노후·불량건축물에 해당하는 공동주택이 밀집한 지역의 주거환경 개선"]]}],"함정":"구판장·세탁장·화장실·수도·어린이집·경로당은 공동이용시설이고, 녹지·하천·공공공지·광장·소방용수시설은 정비기반시설이다. 주거환경개선사업 정비구역에서는 사업시행계획서에 시장·군수등이 관리하는 것으로 포함된 공동이용시설이 정비기반시설이 된다(영 제3조제9호)."}},{"i":"S5-2-1-공법-21","r":"S5","g":2,"c":2,"n":61,"s":"공법","q":"도시 및 주거환경정비법령상 주거환경개선사업의 사업시행자가 작성하는 사업시행계획서에 포함되어야 하는 사항이 아닌 것은?(단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["토지이용계획(건축물배치계획을 포함한다)","세입자의 주거 및 이주 대책","정비사업비","정비사업의 시행과정에서 발생하는 폐기물의 처리계획","국민주택규모 주택의 건설계획"],"a":[5],"L":"공3-2","o":"변형","x":{"한줄":"국민주택규모 주택의 건설계획은 주거환경개선사업의 사업시행계획서에 포함하지 않는다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제52조제1항제1호·제4호·제7호·제10호·제12호","원문":"① 사업시행자는 정비계획에 따라 다음 각 호의 사항을 포함하는 사업시행계획서를 작성하여야 한다.\n1. 토지이용계획(건축물배치계획을 포함한다)\n4. 세입자의 주거 및 이주 대책\n7. 제54조제4항, 제101조의5 및 제101조의6에 따른 국민주택규모 주택의 건설계획(주거환경개선사업의 경우는 제외한다)\n10. 정비사업의 시행과정에서 발생하는 폐기물의 처리계획\n12. 정비사업비"}],"선지":[{"번호":1,"판정":"옳음","설명":"토지이용계획(건축물배치계획 포함)은 모든 정비사업의 사업시행계획서에 들어간다(법 제52조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"세입자의 주거 및 이주 대책도 사업 종류와 관계없이 포함한다(법 제52조제1항제4호)."},{"번호":3,"판정":"옳음","설명":"정비사업비는 사업시행계획서의 필수 항목이다(법 제52조제1항제12호)."},{"번호":4,"판정":"옳음","설명":"시행과정에서 발생하는 폐기물의 처리계획이 들어간다(법 제52조제1항제10호)."},{"번호":5,"판정":"틀림","설명":"국민주택규모 주택의 건설계획은 「주거환경개선사업의 경우는 제외」한다(법 제52조제1항제7호). 주거환경개선사업의 사업시행계획서에는 넣지 않는다."}],"개념":[{"종류":"표","제목":"사업시행계획서 포함사항(법 제52조제1항)","머리":["호","사항","사업별 예외·조건"],"행":[["1","토지이용계획(건축물배치계획 포함)","-"],["2","정비기반시설 및 공동이용시설의 설치계획","-"],["3","임시거주시설을 포함한 주민이주대책","-"],["4","세입자의 주거 및 이주 대책","-"],["5","사업시행기간 동안의 범죄예방대책(가로등·폐쇄회로 텔레비전 설치 등)","-"],["6","제10조에 따른 임대주택의 건설계획","재건축사업 제외"],["7","국민주택규모 주택의 건설계획","주거환경개선사업 제외"],["8","공공지원민간임대주택 또는 임대관리 위탁주택의 건설계획","필요한 경우로 한정"],["9","건축물의 높이 및 용적률 등에 관한 건축계획","-"],["10","정비사업 시행과정에서 발생하는 폐기물의 처리계획","-"],["11","교육시설의 교육환경 보호에 관한 계획","정비구역에서 200미터 이내에 교육시설이 있는 경우"],["12","정비사업비","-"],["13","그 밖에 시·도조례로 정하는 사항","대통령령이 정하는 바에 따름"]]},{"종류":"흐름","제목":"사업시행계획인가부터 분양공고까지","단계":[{"이름":"총회 의결","설명":"조합은 인가 신청 전에 총회 의결을 거친다. 사업시행계획서 작성·변경은 조합원 과반수 찬성이고, 정비사업비가 10퍼센트 이상 늘면 3분의 2 이상 찬성이다(법 제50조제5항, 제45조제4항)."},{"이름":"인가 신청","설명":"사업시행계획서에 정관등과 국토교통부령이 정한 서류를 붙여 시장·군수등에게 제출한다(법 제50조제1항)."},{"이름":"인가 여부 통보","설명":"특별한 사유가 없으면 제출일부터 60일 이내에 결정해 통보한다(법 제50조제4항)."},{"이름":"공보 고시","설명":"인가를 하면 지방자치단체 공보에 고시한다(법 제50조제9항)."},{"이름":"분양공고·통지","설명":"고시일부터 90일 이내(1회 30일 범위 연장 가능)에 토지등소유자에게 통지하고 공고한다(법 제72조제1항)."}]}],"함정":"임대주택 건설계획은 재건축사업만, 국민주택규모 주택 건설계획은 주거환경개선사업만 제외된다. 제외 대상 사업이 서로 다르다. 주거환경개선사업은 임대주택 건설계획을 넣고 국민주택규모 주택 건설계획은 뺀다."}},{"i":"S5-2-1-공법-22","r":"S5","g":2,"c":2,"n":62,"s":"공법","q":"도시 및 주거환경정비법령상 조합에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["조합 정관의 기재사항 중 정비사업비의 부담 시기 및 절차를 변경하려는 경우에는 조합원 과반수의 찬성으로 시장ㆍ군수등의 인가를 받아야 한다.","법인인 토지등소유자가 조합원일 경우 법인의 대리인은 조합임원으로 선임될 수 없다.","조합장은 선임일부터 정비사업의 준공인가 시까지는 해당 정비구역에서 거주하여야 한다.","조합의 전문조합관리인의 임기는 5년의 범위에서 시ㆍ도 조례로 따로 정한다.","조합의 대의원회는 총회의 의결사항 중 사업완료로 인한 조합 해산에 관한 사항에 대하여 총회의 권한을 대행할 수 있다."],"a":[5],"L":"공3-2","o":"기출","x":{"한줄":"대의원회는 총회 권한을 대행하지 못하는 사항 외에는 대행할 수 있고, 사업완료로 인한 조합 해산은 대행 불가 사항에서 빠진다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제46조제4항","원문":"④ 대의원회는 총회의 의결사항 중 대통령령으로 정하는 사항 외에는 총회의 권한을 대행할 수 있다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제43조제10호","원문":"10. 제42조제1항제1호에 따른 조합의 합병 또는 해산에 관한 사항. 다만, 사업완료로 인한 해산의 경우는 제외한다."},{"법령":"도시 및 주거환경정비법","조문":"제40조제3항","원문":"③ 조합이 정관을 변경하려는 경우에는 제35조제2항부터 제5항까지의 규정에도 불구하고 총회를 개최하여 조합원 과반수의 찬성으로 시장ㆍ군수등의 인가를 받아야 한다. 다만, 제1항제2호ㆍ제3호ㆍ제4호ㆍ제8호ㆍ제13호 또는 제16호의 경우에는 조합원 3분의 2 이상의 찬성으로 한다."},{"법령":"도시 및 주거환경정비법","조문":"제41조제1항 후단","원문":"① 조합은 조합원으로서 정비구역에 위치한 건축물 또는 토지(재건축사업의 경우에는 건축물과 그 부속토지를 말한다. 이하 이 항에서 같다)를 소유한 자[하나의 건축물 또는 토지의 소유권을 다른 사람과 공유한 경우에는 가장 많은 지분을 소유(2인 이상의 공유자가 가장 많은 지분을 소유한 경우를 포함한다)한 경우로 한정한다] 중 다음 각 호의 어느 하나의 요건을 갖춘 조합장 1명과 이사, 감사를 임원으로 둔다. 이 경우 조합장은 선임일부터 제74조제1항에 따른 관리처분계획인가를 받을 때까지는 해당 정비구역에서 거주(영업을 하는 자의 경우 영업을 말한다. 이하 이 조 및 제43조에서 같다)하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제45조제5항제3호","원문":"3. 법인인 토지등소유자가 대리인을 지정하는 경우. 이 경우 법인의 대리인은 조합임원 또는 대의원으로 선임될 수 있다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제41조제4항","원문":"④ 전문조합관리인의 임기는 3년으로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"정비사업비의 부담 시기 및 절차는 정관 기재사항 제13호이고, 이를 변경하는 정관 변경은 조합원 3분의 2 이상 찬성이 필요하다(법 제40조제1항제13호, 제3항 단서). 과반수로는 부족하다."},{"번호":2,"판정":"틀림","설명":"법인인 토지등소유자가 지정한 대리인은 조합임원 또는 대의원으로 선임될 수 있다(법 제45조제5항제3호)."},{"번호":3,"판정":"틀림","설명":"조합장의 거주 의무는 선임일부터 관리처분계획인가를 받을 때까지다(법 제41조제1항). 준공인가까지가 아니다."},{"번호":4,"판정":"틀림","설명":"전문조합관리인의 임기는 3년으로 정해져 있다(영 제41조제4항). 시·도 조례로 따로 정하지 않는다."},{"번호":5,"판정":"옳음","설명":"조합의 합병 또는 해산은 대의원회가 대행할 수 없으나, 사업완료로 인한 해산은 제외한다(영 제43조제10호 단서). 사업완료 해산은 대의원회가 총회 권한을 대행한다."}],"개념":[{"종류":"표","제목":"조합 기구별 기준","머리":["구분","기준","근거"],"행":[["조합임원","조합장 1명, 이사 3명 이상, 감사 1명 이상 3명 이하. 토지등소유자 100인 초과 시 이사 5명 이상","법 제41조제1항, 영 제40조"],["조합장 요건","정비구역 건축물·토지 5년 이상 소유, 또는 선임 직전 3년 중 1년 이상 거주","법 제41조제1항"],["조합장 거주의무","선임일부터 관리처분계획인가를 받을 때까지 정비구역에 거주(영업 포함)","법 제41조제1항"],["임기","3년 이하의 범위에서 정관으로 정하고 연임 가능","법 제41조제4항"],["전문조합관리인","임기 3년. 임원 업무를 대행하며 시장·군수등이 선정","법 제41조제5항, 영 제41조제4항"],["대의원회","조합원 100명 이상이면 둔다. 조합원의 10분의 1 이상으로 구성","법 제46조제1항·제2항"],["대의원 자격","조합장이 아닌 조합임원은 대의원이 될 수 없다","법 제46조제3항"]]},{"종류":"표","제목":"대의원회가 총회 권한을 대행할 수 없는 사항(영 제43조)","머리":["호","대행 불가 사항"],"행":[["1","정관의 변경(경미한 변경은 총회 의결사항으로 정한 경우로 한정)"],["2","자금의 차입과 그 방법·이자율 및 상환방법"],["3","예산으로 정한 사항 외에 조합원에게 부담이 되는 계약"],["4","시공자·설계자·감정평가법인등의 선정 및 변경"],["5","정비사업전문관리업자의 선정 및 변경"],["6","조합임원의 선임·해임, 대의원의 선임·해임(임기 중 궐위된 자의 보궐선임은 가능, 조합장은 제외)"],["7","사업시행계획서의 작성 및 변경(경미한 변경 제외)"],["8","관리처분계획의 수립 및 변경(경미한 변경 제외)"],["9","총회에 상정하여야 하는 사항"],["10","조합의 합병 또는 해산(사업완료로 인한 해산은 대행 가능)"],["11","건설되는 건축물의 설계 개요의 변경"],["12","정비사업비의 변경"]]}],"함정":"정관 변경은 과반수 찬성이 원칙이지만 조합원 자격, 제명·탈퇴, 정비구역 위치·면적, 조합의 비용부담·회계, 정비사업비 부담 시기·절차, 시공자·설계자 선정 및 계약서 내용(제2·3·4·8·13·16호)은 3분의 2 이상이다. 조합장 거주 기간은 관리처분계획인가까지이고 준공인가까지가 아니다. 대의원회가 대행하지 못하는 해산에서 사업완료로 인한 해산은 빠진다."}},{"i":"S5-2-1-공법-23","r":"S5","g":2,"c":2,"n":63,"s":"공법","q":"도시 및 주거환경정비법령상 관리처분계획에 따른 처분 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["정비사업의 시행으로 건설된 건축물은 인가받은 관리처분계획에 따라 토지등소유자에게 공급하여야 한다.","사업시행자는 분양신청을 받은 후 잔여분이 있는 경우 정관등 또는 사업시행계획으로 정하는 목적을 위하여 그 잔여분을 보류지로 정할 수 있다.","사업시행자는 분양대상자에게 주택을 공급하고 남은 주택을 분양대상자 외의 자에게 공급할 수 없다.","사업시행자가 토지주택공사등인 경우에는 분양대상자와 사업시행자가 공동 소유하는 방식으로 주택을 공급할 수 있다.","세입자와 대통령령으로 정하는 면적 이하의 토지 또는 주택을 소유한 자의 요청이 있으면 인수한 재개발임대주택의 일부를 토지임대부 분양주택으로 전환하여 공급하여야 한다."],"a":[3],"L":"공3-3","o":"변형","x":{"한줄":"공급대상자에게 주택을 공급하고 남은 주택은 공급대상자 외의 자에게도 공급할 수 있다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제79조제2항","원문":"② 사업시행자는 정비사업의 시행으로 건설된 건축물을 제74조에 따라 인가받은 관리처분계획에 따라 토지등소유자에게 공급하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제79조제4항","원문":"④ 사업시행자는 제72조에 따른 분양신청을 받은 후 잔여분이 있는 경우에는 정관등 또는 사업시행계획으로 정하는 목적을 위하여 그 잔여분을 보류지(건축물을 포함한다)로 정하거나 조합원 또는 토지등소유자 이외의 자에게 분양할 수 있다. 이 경우 분양공고와 분양신청절차 등에 필요한 사항은 대통령령으로 정한다."},{"법령":"도시 및 주거환경정비법","조문":"제79조제7항","원문":"⑦ 사업시행자는 제2항부터 제6항까지의 규정에 따른 공급대상자에게 주택을 공급하고 남은 주택을 제2항부터 제6항까지의 규정에 따른 공급대상자 외의 자에게 공급할 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제80조제1항·제2항","원문":"① 사업시행자가 토지주택공사등인 경우에는 분양대상자와 사업시행자가 공동 소유하는 방식으로 주택(이하 \"지분형주택\"이라 한다)을 공급할 수 있다. 이 경우 공급되는 지분형주택의 규모, 공동 소유기간 및 분양대상자 등 필요한 사항은 대통령령으로 정한다.\n② 국토교통부장관, 시ㆍ도지사, 시장, 군수, 구청장 또는 토지주택공사등은 정비구역에 세입자와 대통령령으로 정하는 면적 이하의 토지 또는 주택을 소유한 자의 요청이 있는 경우에는 제79조제5항에 따라 인수한 임대주택의 일부를 「주택법」에 따른 토지임대부 분양주택으로 전환하여 공급하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"건설된 건축물은 제74조에 따라 인가받은 관리처분계획에 따라 토지등소유자에게 공급한다(법 제79조제2항)."},{"번호":2,"판정":"옳음","설명":"분양신청 후 잔여분은 정관등 또는 사업시행계획이 정한 목적을 위해 보류지로 정하거나 조합원·토지등소유자 외의 자에게 분양할 수 있다(법 제79조제4항)."},{"번호":3,"판정":"틀림","설명":"제2항부터 제6항까지의 공급대상자에게 공급하고 남은 주택은 공급대상자 외의 자에게 공급할 수 있다(법 제79조제7항). 이 경우 공급 방법·절차는 「주택법」 제54조를 준용한다(같은 조 제8항)."},{"번호":4,"판정":"옳음","설명":"토지주택공사등이 사업시행자이면 분양대상자와 공동 소유하는 지분형주택을 공급할 수 있다(법 제80조제1항)."},{"번호":5,"판정":"옳음","설명":"세입자와 일정 면적 이하의 토지·주택 소유자가 요청하면 제79조제5항에 따라 인수한 임대주택의 일부를 토지임대부 분양주택으로 전환하여 공급해야 한다(법 제80조제2항)."}],"개념":[{"종류":"표","제목":"관리처분계획에 따른 처분·공급(법 제79조·제80조)","머리":["조문","내용"],"행":[["법 제79조제1항","조성된 대지·건축물은 관리처분계획에 따라 처분 또는 관리"],["법 제79조제2항","건설된 건축물은 인가받은 관리처분계획에 따라 토지등소유자에게 공급"],["법 제79조제3항","입주자 모집 조건·방법·절차 등은 시장·군수등의 승인을 받아 「주택법」 제54조와 달리 정할 수 있음"],["법 제79조제4항","분양신청 후 잔여분은 보류지로 정하거나 조합원·토지등소유자 외의 자에게 분양 가능"],["법 제79조제5항","조합 요청 시 재개발사업으로 건설된 임대주택(재개발임대주택)을 국토교통부장관, 시·도지사, 시장, 군수, 구청장 또는 토지주택공사등이 인수. 시·도지사 또는 시장·군수·구청장이 우선 인수(영 제68조제1항)"],["법 제79조제7항","공급대상자에게 공급하고 남은 주택은 공급대상자 외의 자에게 공급 가능"],["법 제80조제1항","사업시행자가 토지주택공사등이면 지분형주택(분양대상자와 공동 소유) 공급 가능"],["법 제80조제2항","세입자 등의 요청이 있으면 인수한 임대주택 일부를 토지임대부 분양주택으로 전환 공급"]]},{"종류":"흐름","제목":"분양공고부터 현금청산 협의·재결까지","단계":[{"이름":"분양공고·통지","설명":"사업시행계획인가 고시일(인가 후 시공자를 선정했으면 계약 체결일)부터 90일 이내. 1회에 한해 30일 범위에서 연장 가능(법 제72조제1항)."},{"이름":"분양신청","설명":"통지한 날부터 30일 이상 60일 이내. 관리처분계획 수립에 지장이 없으면 20일 범위에서 한 차례 연장(법 제72조제2항)."},{"이름":"관리처분계획 공람","설명":"인가 신청 전에 관계 서류를 30일 이상 토지등소유자에게 공람하고 의견을 듣는다(법 제78조제1항)."},{"이름":"인가 여부 결정","설명":"신청일부터 30일 이내. 타당성 검증을 요청하면 60일 이내(법 제78조제2항)."},{"이름":"손실보상 협의","설명":"인가·고시된 다음 날부터 90일 이내에 분양신청을 하지 않은 자 등과 협의한다(법 제73조제1항)."},{"이름":"수용재결·매도청구","설명":"협의가 불성립하면 협의기간 만료일 다음 날부터 60일 이내에 수용재결을 신청하거나 매도청구소송을 제기한다(법 제73조제2항)."}]}],"함정":"남은 주택을 공급대상자 외의 자에게 공급할 수 없다고 쓰면 틀린다(제79조제7항). 임대주택 인수 규정(제79조제5항)은 재개발사업에만 해당하고 재건축사업에는 없다. 재개발임대주택을 우선 인수하는 주체는 시·도지사 또는 시장·군수·구청장이고, 국토교통부장관이 아니다(영 제68조제1항)."}},{"i":"S5-2-1-공법-24","r":"S5","g":2,"c":2,"n":64,"s":"공법","q":"도시 및 주거환경정비법령상 공사완료에 따른 조치 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시장·군수등은 준공인가의 신청을 받으면 지체 없이 준공검사를 실시하여야 한다.","정비구역의 지정이 해제되면 지방자치단체는 해당 지역을 「국토의 계획 및 이용에 관한 법률」에 따른 지구단위계획으로 관리하여야 한다.","준공인가 등에 따른 정비구역의 해제는 조합의 존속에 영향을 주지 아니한다.","시장·군수등이 직접 시행하는 정비사업의 경우에도 준공인가 전에 입주예정자가 완공된 건축물을 사용하려면 사용허가를 받아야 한다.","사업시행자는 이전고시가 있은 때에는 지체 없이 대지 및 건축물에 관한 등기를 지방법원지원 또는 등기소에 촉탁 또는 신청하여야 한다."],"a":[4],"L":"공3-3","o":"변형","x":{"한줄":"시장·군수등이 사업시행자인 경우에는 허가를 받지 않고 입주예정자가 완공된 건축물을 사용하게 할 수 있다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제83조제2항","원문":"② 제1항에 따라 준공인가신청을 받은 시장ㆍ군수등은 지체 없이 준공검사를 실시하여야 한다. 이 경우 시장ㆍ군수등은 효율적인 준공검사를 위하여 필요한 때에는 관계 행정기관ㆍ공공기관ㆍ연구기관, 그 밖의 전문기관 또는 단체에게 준공검사의 실시를 의뢰할 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제83조제5항","원문":"⑤ 시장ㆍ군수등은 제1항에 따른 준공인가를 하기 전이라도 완공된 건축물이 사용에 지장이 없는 등 대통령령으로 정하는 기준에 적합한 경우에는 입주예정자가 완공된 건축물을 사용할 수 있도록 사업시행자에게 허가할 수 있다. 다만, 시장ㆍ군수등이 사업시행자인 경우에는 허가를 받지 아니하고 입주예정자가 완공된 건축물을 사용하게 할 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제84조","원문":"① 정비구역의 지정은 제83조에 따른 준공인가의 고시가 있은 날(관리처분계획을 수립하는 경우에는 이전고시가 있은 때를 말한다)의 다음 날에 해제된 것으로 본다. 이 경우 지방자치단체는 해당 지역을 「국토의 계획 및 이용에 관한 법률」에 따른 지구단위계획으로 관리하여야 한다.\n② 제1항에 따른 정비구역의 해제는 조합의 존속에 영향을 주지 아니한다."},{"법령":"도시 및 주거환경정비법","조문":"제88조제1항","원문":"① 사업시행자는 제86조제2항에 따른 이전고시가 있은 때에는 지체 없이 대지 및 건축물에 관한 등기를 지방법원지원 또는 등기소에 촉탁 또는 신청하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"준공인가신청을 받은 시장·군수등은 지체 없이 준공검사를 실시한다(법 제83조제2항)."},{"번호":2,"판정":"옳음","설명":"정비구역 지정이 해제되면 지방자치단체가 그 지역을 지구단위계획으로 관리한다(법 제84조제1항 후단)."},{"번호":3,"판정":"옳음","설명":"정비구역의 해제는 조합의 존속에 영향을 주지 않는다(법 제84조제2항). 해산은 이전고시 후 총회 의결로 한다(법 제86조의2)."},{"번호":4,"판정":"틀림","설명":"준공인가전 사용허가는 시장·군수등이 사업시행자에게 하는 허가다. 시장·군수등이 사업시행자인 경우에는 허가를 받지 아니하고 입주예정자가 완공된 건축물을 사용하게 할 수 있다(법 제83조제5항 단서)."},{"번호":5,"판정":"옳음","설명":"이전고시가 있으면 사업시행자가 지체 없이 등기를 촉탁 또는 신청한다(법 제88조제1항)."}],"개념":[{"종류":"흐름","제목":"공사완료부터 청산·조합 해산까지","단계":[{"이름":"준공인가 신청","설명":"시장·군수등이 아닌 사업시행자는 공사를 완료하면 시장·군수등의 준공인가를 받는다(법 제83조제1항)."},{"이름":"준공검사·고시","설명":"지체 없이 준공검사를 하고, 인가받은 사업시행계획대로 완료되었으면 준공인가 후 공사완료를 공보에 고시한다(법 제83조제2항·제3항)."},{"이름":"준공인가전 사용허가","설명":"허가 기준은 세 가지다. 전기·수도·난방 및 상하수도 시설이 갖추어져 사용에 지장이 없을 것. 관리처분계획에 적합할 것. 입주자가 공사에 따른 차량통행·소음·분진 등의 위해로부터 안전할 것. 동별·세대별·구획별 허가가 가능하다(법 제83조제5항, 영 제75조)."},{"이름":"이전고시","설명":"대지확정측량과 토지 분할 후 소유권 이전 내용을 공보에 고시하고 시장·군수등에게 보고한다. 분양받을 자는 고시일 다음 날 소유권을 취득한다(법 제86조)."},{"이름":"정비구역 해제","설명":"관리처분계획을 수립한 경우 이전고시가 있은 날의 다음 날에 정비구역 지정이 해제된 것으로 본다(법 제84조제1항)."},{"이름":"등기·청산","설명":"이전고시 후 지체 없이 등기를 신청하고, 청산금은 이전고시 후에 징수·지급한다(법 제88조제1항, 제89조제1항)."},{"이름":"조합 해산","설명":"조합장은 이전고시 고시일부터 1년 이내에 해산을 위한 총회를 소집한다(법 제86조의2제1항)."}]},{"종류":"표","제목":"이전고시 이후의 권리관계(법 제86조~제90조)","머리":["조문","내용"],"행":[["법 제86조제2항","대지·건축물을 분양받을 자는 이전고시가 있은 날의 다음 날 소유권 취득"],["법 제87조제1항","종전 토지·건축물의 지상권·전세권·저당권·임차권·가등기담보권·가압류 등 등기된 권리는 소유권을 이전받은 대지·건축물에 설정된 것으로 봄"],["법 제87조제2항","토지등소유자에게 분양하는 대지·건축물은 「도시개발법」에 따른 환지로 봄"],["법 제87조제3항","보류지와 일반 분양 대지·건축물은 「도시개발법」의 보류지 또는 체비지로 봄"],["법 제88조제3항","이전고시일부터 등기가 있을 때까지 저당권 등 다른 등기 불가"],["법 제90조제3항","청산금을 받거나 징수할 권리는 이전고시일 다음 날부터 5년간 행사하지 않으면 소멸"]]}],"함정":"준공인가전 사용허가에서 시장·군수등이 사업시행자이면 허가가 필요 없다. 정비구역 해제로 조합이 해산되는 것도 아니다. 해산은 이전고시일부터 1년 이내 총회를 소집해 의결한다."}},{"i":"S5-2-1-공법-25","r":"S5","g":2,"c":2,"n":65,"s":"공법","q":"건축법령상 용어에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["\"고층건축물\"은 건축물의 층수가 30층 이상이고 높이가 120미터 이상인 건축물을 말한다.","건축물의 주요구조부를 해체하지 아니하고 같은 대지의 다른 위치로 옮기는 것은 \"이전\"에 해당한다.","기존 건축물의 내력벽·기둥·보·지붕틀 중 둘 이상이 포함되는 부분을 해체하고 그 대지에 종전과 같은 규모의 범위에서 다시 축조하는 것은 \"개축\"에 해당한다.","건축물의 내력벽의 벽면적을 20제곱미터 수선하는 것은 \"대수선\"에 해당한다.","부속건축물만 있는 대지에 새로 주된 건축물을 축조하는 것은 \"신축\"에 해당하지 않는다."],"a":[2],"L":"공4-1","o":"변형","x":{"한줄":"이전은 주요구조부를 해체하지 않고 같은 대지의 다른 위치로 옮기는 것이다.","근거":[{"법령":"건축법 시행령","조문":"영 제2조제5호","원문":"5. \"이전\"이란 건축물의 주요구조부를 해체하지 아니하고 같은 대지의 다른 위치로 옮기는 것을 말한다."},{"법령":"건축법","조문":"법 제2조제1항제19호","원문":"19. \"고층건축물\"이란 층수가 30층 이상이거나 높이가 120미터 이상인 건축물을 말한다."},{"법령":"건축법 시행령","조문":"영 제2조제1호·제3호","원문":"1. \"신축\"이란 건축물이 없는 대지(기존 건축물이 해체되거나 멸실된 대지를 포함한다)에 새로 건축물을 축조(築造)하는 것[부속건축물만 있는 대지에 새로 주된 건축물을 축조하는 것을 포함하되, 개축(改築) 또는 재축(再築)하는 것은 제외한다]을 말한다.\n3. \"개축\"이란 기존 건축물의 전부 또는 일부[내력벽ㆍ기둥ㆍ보ㆍ지붕틀(제16호에 따른 한옥의 경우에는 지붕틀의 범위에서 서까래는 제외한다) 중 셋 이상이 포함되는 경우를 말한다]를 해체하고 그 대지에 종전과 같은 규모의 범위에서 건축물을 다시 축조하는 것을 말한다."},{"법령":"건축법 시행령","조문":"영 제3조의2제1호","원문":"1. 내력벽을 증설 또는 해체하거나 그 벽면적을 30제곱미터 이상 수선 또는 변경하는 것"}],"선지":[{"번호":1,"판정":"틀림","설명":"고층건축물은 층수가 30층 이상이거나 높이가 120미터 이상인 건축물이다(법 제2조제1항제19호). 둘 중 하나만 충족해도 된다."},{"번호":2,"판정":"옳음","설명":"이전은 건축물의 주요구조부를 해체하지 아니하고 같은 대지의 다른 위치로 옮기는 것이다(영 제2조제5호). 해체해서 옮기면 이전이 아니라 신축 등에 해당한다."},{"번호":3,"판정":"틀림","설명":"개축은 내력벽·기둥·보·지붕틀 중 셋 이상이 포함되는 부분을 해체하고 종전과 같은 규모 범위에서 다시 축조하는 것이다(영 제2조제3호). 둘 이상이 아니다."},{"번호":4,"판정":"틀림","설명":"내력벽은 증설 또는 해체하거나 벽면적을 30제곱미터 이상 수선·변경해야 대수선이다(영 제3조의2제1호). 20제곱미터는 미달한다."},{"번호":5,"판정":"틀림","설명":"신축에는 부속건축물만 있는 대지에 새로 주된 건축물을 축조하는 것이 포함된다(영 제2조제1호)."}],"개념":[{"종류":"표","제목":"건축 행위의 구분(영 제2조, 제3조의2)","머리":["행위","요건"],"행":[["신축","건축물이 없는 대지(기존 건축물이 해체·멸실된 대지 포함)에 새로 축조. 부속건축물만 있는 대지에 새로 주된 건축물을 축조하는 것 포함. 개축·재축 제외"],["증축","기존 건축물이 있는 대지에서 건축면적, 연면적, 층수 또는 높이를 늘리는 것"],["개축","기존 건축물의 전부 또는 일부(내력벽·기둥·보·지붕틀 중 셋 이상 포함)를 해체하고 그 대지에 종전과 같은 규모의 범위에서 다시 축조"],["재축","천재지변 등으로 멸실된 경우 연면적 합계는 종전 규모 이하, 동수·층수·높이는 모두 종전 규모 이하이거나 법령등에 모두 적합하게 다시 축조"],["이전","주요구조부를 해체하지 않고 같은 대지의 다른 위치로 옮기는 것"],["대수선","내력벽 증설·해체 또는 벽면적 30제곱미터 이상 수선·변경, 기둥·보·지붕틀 증설·해체 또는 3개 이상 수선·변경 등. 증축·개축·재축에 해당하지 않는 것"]]},{"종류":"표","제목":"건축물 규모 관련 용어","머리":["용어","기준","근거"],"행":[["고층건축물","30층 이상 또는 높이 120미터 이상","법 제2조제1항제19호"],["초고층 건축물","50층 이상 또는 높이 200미터 이상","영 제2조제15호"],["준초고층 건축물","고층건축물 중 초고층 건축물이 아닌 것","영 제2조제15호의2"],["다중이용 건축물","문화·집회, 종교, 판매, 여객용 운수, 종합병원, 관광숙박시설 용도 바닥면적 합계 5천제곱미터 이상 또는 16층 이상","영 제2조제17호"],["준다중이용 건축물","다중이용 건축물 외로서 문화·집회, 종교, 판매, 교육연구 등 지정 용도 바닥면적 합계 1천제곱미터 이상","영 제2조제17호의2"]]}],"함정":"고층건축물은 「30층 이상 또는 120미터 이상」이다. 「이고」로 바꾸면 틀린다. 개축은 내력벽·기둥·보·지붕틀 중 셋 이상 해체 조건이고, 둘이면 개축이 아니다. 내력벽 대수선 기준은 30제곱미터 이상이다."}},{"i":"S5-2-1-공법-26","r":"S5","g":2,"c":2,"n":66,"s":"공법","q":"건축법령상 국가가 소유한 대지의 지상 여유공간에 구분지상권을 설정하여 시설을 설치하려는 경우, 허가권자가 구분지상권자를 건축주로 보고 구분지상권이 설정된 부분을 대지로 보아 건축허가를 할 수 있는 시설에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["의료시설 중 병원","교육연구시설 중 학교","노유자시설 중 노인복지시설","문화 및 집회시설 중 전시장","문화 및 집회시설 중 관람장"],"a":[5],"L":"공4-2","o":"변형","x":{"한줄":"문화 및 집회시설은 공연장과 전시장으로 한정되어 관람장은 구분지상권 건축허가 대상 시설이 아니다.","근거":[{"법령":"건축법","조문":"법 제29조제4항","원문":"④ 국가나 지방자치단체가 소유한 대지의 지상 또는 지하 여유공간에 구분지상권을 설정하여 주민편의시설 등 대통령령으로 정하는 시설을 설치하고자 하는 경우 허가권자는 구분지상권자를 건축주로 보고 구분지상권이 설정된 부분을 제2조제1항제1호의 대지로 보아 건축허가를 할 수 있다. 이 경우 구분지상권 설정의 대상 및 범위, 기간 등은 「국유재산법」 및 「공유재산 및 물품 관리법」에 적합하여야 한다."},{"법령":"건축법 시행령","조문":"영 제22조제4항","원문":"④ 법 제29조제4항 전단에서 \"주민편의시설 등 대통령령으로 정하는 시설\"이란 다음 각 호의 시설을 말한다.\n2. 제2종 근린생활시설(총포판매소, 장의사, 다중생활시설, 제조업소, 단란주점, 안마시술소 및 노래연습장은 제외한다)\n3. 문화 및 집회시설(공연장 및 전시장으로 한정한다)\n4. 의료시설\n5. 교육연구시설\n6. 노유자시설\n8. 업무시설(오피스텔은 제외한다)"}],"선지":[{"번호":1,"판정":"옳음","설명":"의료시설은 구분지상권 설정 대상 시설이다(영 제22조제4항제4호)."},{"번호":2,"판정":"옳음","설명":"교육연구시설은 대상 시설이다(영 제22조제4항제5호)."},{"번호":3,"판정":"옳음","설명":"노유자시설은 대상 시설이다(영 제22조제4항제6호)."},{"번호":4,"판정":"옳음","설명":"문화 및 집회시설 중 공연장과 전시장이 대상이다(영 제22조제4항제3호)."},{"번호":5,"판정":"틀림","설명":"문화 및 집회시설은 「공연장 및 전시장으로 한정한다」(영 제22조제4항제3호). 관람장은 집회장·동식물원과 함께 제외된다."}],"개념":[{"종류":"표","제목":"구분지상권 설정 시 건축허가 대상 시설(영 제22조제4항)","머리":["용도","대상 범위","제외"],"행":[["제1종 근린생활시설","전부","-"],["제2종 근린생활시설","일부","총포판매소, 장의사, 다중생활시설, 제조업소, 단란주점, 안마시술소, 노래연습장"],["문화 및 집회시설","공연장, 전시장","집회장, 관람장, 동·식물원"],["의료시설","전부","-"],["교육연구시설","전부","-"],["노유자시설","전부","-"],["운동시설","전부","-"],["업무시설","일반업무시설","오피스텔"]]},{"종류":"표","제목":"공용건축물에 대한 특례(법 제29조)","머리":["항","내용"],"행":[["제1항","국가·지방자치단체가 제11조, 제14조, 제19조, 제20조, 제83조에 따른 건축물을 건축·대수선·용도변경하거나 가설건축물 건축, 공작물 축조를 하려면 미리 허가권자와 협의"],["제2항","협의한 경우 건축허가·신고 등을 받은 것으로 봄"],["제3항","협의한 건축물은 제22조제1항~제3항(사용승인) 미적용. 공사가 끝나면 지체 없이 허가권자에게 통보"],["제4항","국가·지방자치단체 소유 대지의 지상·지하 여유공간에 구분지상권을 설정해 주민편의시설 등을 설치하려는 경우, 구분지상권자를 건축주로 보고 구분지상권 부분을 대지로 보아 건축허가 가능"]]}],"함정":"문화 및 집회시설을 통째로 대상이라고 보기 쉽다. 공연장과 전시장만 해당하고 관람장은 빠진다. 제2종 근린생활시설 중 노래연습장·다중생활시설과 업무시설 중 오피스텔도 제외 대상이다."}},{"i":"S5-2-1-공법-27","r":"S5","g":2,"c":2,"n":67,"s":"공법","q":"건축법령상 자연환경이나 수질을 보호하기 위하여 도지사가 지정ㆍ공고한 구역에 건축하는 3층 이상인 건축물로 시장ㆍ군수가 건축허가를 하려면 미리 도지사의 승인을 받아야 하는 용도의 건축물이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["공장","공동주택","위락시설","숙박시설","제2종 근린생활시설 중 일반음식점"],"a":[1],"L":"공4-2","o":"기출","x":{"한줄":"도지사 승인 대상 용도는 공동주택, 일반음식점, 일반업무시설, 숙박시설, 위락시설이며 공장은 들어 있지 않다.","근거":[{"법령":"건축법","조문":"법 제11조제2항제2호","원문":"② 시장ㆍ군수는 제1항에 따라 다음 각 호의 어느 하나에 해당하는 건축물의 건축을 허가하려면 미리 건축계획서와 국토교통부령으로 정하는 건축물의 용도, 규모 및 형태가 표시된 기본설계도서를 첨부하여 도지사의 승인을 받아야 한다.\n2. 자연환경이나 수질을 보호하기 위하여 도지사가 지정ㆍ공고한 구역에 건축하는 3층 이상 또는 연면적의 합계가 1천제곱미터 이상인 건축물로서 위락시설과 숙박시설 등 대통령령으로 정하는 용도에 해당하는 건축물"},{"법령":"건축법 시행령","조문":"영 제8조제3항","원문":"③ 법 제11조제2항제2호에서 \"위락시설과 숙박시설 등 대통령령으로 정하는 용도에 해당하는 건축물\"이란 다음 각 호의 건축물을 말한다.\n1. 공동주택\n2. 제2종 근린생활시설(일반음식점만 해당한다)\n3. 업무시설(일반업무시설만 해당한다)\n4. 숙박시설\n5. 위락시설"}],"선지":[{"번호":1,"판정":"틀림","설명":"공장은 영 제8조제3항 각 호에 없다. 승인 대상 용도가 아니다."},{"번호":2,"판정":"옳음","설명":"공동주택은 영 제8조제3항제1호의 승인 대상 용도다."},{"번호":3,"판정":"옳음","설명":"위락시설은 영 제8조제3항제5호의 승인 대상 용도다."},{"번호":4,"판정":"옳음","설명":"숙박시설은 영 제8조제3항제4호의 승인 대상 용도다."},{"번호":5,"판정":"옳음","설명":"제2종 근린생활시설은 일반음식점만 대상이다(영 제8조제3항제2호). 일반음식점은 승인 대상 용도에 든다."}],"개념":[{"종류":"표","제목":"건축허가권자와 승인권자(법 제11조, 영 제8조)","머리":["구분","대상","비고"],"행":[["시장·군수·구청장 허가","일반 건축물의 건축·대수선","법 제11조제1항 본문"],["특별시장·광역시장 허가","특별시·광역시에 건축하는 21층 이상 또는 연면적 합계 10만제곱미터 이상 건축물","공장, 창고 제외(영 제8조제1항 단서)"],["도지사 승인(시장·군수가 허가하려는 경우)","21층 이상 또는 연면적 합계 10만제곱미터 이상 건축물","도 조례로 정하는 건축물은 제외(법 제11조제2항제1호)"],["도지사 승인","자연환경·수질 보호를 위해 도지사가 지정·공고한 구역의 3층 이상 또는 연면적 합계 1천제곱미터 이상 건축물로서 공동주택, 일반음식점, 일반업무시설, 숙박시설, 위락시설","법 제11조제2항제2호, 영 제8조제3항"],["도지사 승인","주거환경·교육환경 보호를 위해 도지사가 지정·공고한 구역의 위락시설·숙박시설","법 제11조제2항제3호"]]}],"함정":"승인 대상 용도에는 공장이 없고 일반음식점은 있다. 제2종 근린생활시설 전체가 아니라 일반음식점만, 업무시설도 일반업무시설만 해당한다. 법 조문은 「3층 이상 또는 연면적 합계 1천제곱미터 이상」이다."}},{"i":"S5-2-1-공법-28","r":"S5","g":2,"c":2,"n":68,"s":"공법","q":"건축법령상 건축물로부터 바깥쪽으로 나가는 출구를 설치하여야 하는 건축물이 아닌 것은? (단, 건축물은 해당 용도로 쓰는 바닥면적의 합계가 300제곱미터 이상으로 승강기를 설치하여야 하는 건축물이 아니며, 건축법령상 특례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["전시장","무도학원","동물 전용의 장례식장","인터넷컴퓨터게임시설제공업소","업무시설 중 국가 또는 지방자치단체의 청사"],"a":[1],"L":"공4-3","o":"기출","x":{"한줄":"문화 및 집회시설은 출구 설치 대상이지만 전시장 및 동·식물원은 제외된다.","근거":[{"법령":"건축법 시행령","조문":"영 제39조제1항","원문":"① 법 제49조제1항에 따라 다음 각 호의 어느 하나에 해당하는 건축물에는 국토교통부령으로 정하는 기준에 따라 그 건축물로부터 바깥쪽으로 나가는 출구를 설치하여야 한다.\n1. 제2종 근린생활시설 중 공연장ㆍ종교집회장ㆍ인터넷컴퓨터게임시설제공업소(해당 용도로 쓰는 바닥면적의 합계가 각각 300제곱미터 이상인 경우만 해당한다)\n2. 문화 및 집회시설(전시장 및 동ㆍ식물원은 제외한다)\n3. 종교시설\n4. 판매시설\n5. 업무시설 중 국가 또는 지방자치단체의 청사\n6. 위락시설\n7. 연면적이 5천 제곱미터 이상인 창고시설\n8. 교육연구시설 중 학교\n9. 장례시설\n10. 승강기를 설치하여야 하는 건축물"}],"선지":[{"번호":1,"판정":"틀림","설명":"전시장은 문화 및 집회시설이지만 영 제39조제1항제2호가 「전시장 및 동·식물원은 제외한다」고 정한다. 출구 설치 대상이 아니다."},{"번호":2,"판정":"옳음","설명":"무도학원은 위락시설(별표 1 제16호마목)이고 위락시설은 대상이다(영 제39조제1항제6호)."},{"번호":3,"판정":"옳음","설명":"동물 전용의 장례식장은 장례시설(별표 1 제28호나목)이고 장례시설은 대상이다(영 제39조제1항제9호)."},{"번호":4,"판정":"옳음","설명":"인터넷컴퓨터게임시설제공업소는 해당 용도 바닥면적 합계가 300제곱미터 이상이면 대상이다(영 제39조제1항제1호). 문제의 단서가 300제곱미터 이상으로 주어져 있다."},{"번호":5,"판정":"옳음","설명":"업무시설 중 국가 또는 지방자치단체의 청사가 대상이다(영 제39조제1항제5호)."}],"개념":[{"종류":"표","제목":"바깥쪽으로 나가는 출구 설치 대상(영 제39조제1항)","머리":["호","대상 건축물","단서"],"행":[["1","제2종 근린생활시설 중 공연장·종교집회장·인터넷컴퓨터게임시설제공업소","해당 용도 바닥면적 합계가 각각 300제곱미터 이상인 경우만"],["2","문화 및 집회시설","전시장 및 동·식물원 제외"],["3","종교시설","-"],["4","판매시설","-"],["5","업무시설 중 국가 또는 지방자치단체의 청사","-"],["6","위락시설","-"],["7","창고시설","연면적 5천제곱미터 이상인 경우만"],["8","교육연구시설 중 학교","-"],["9","장례시설","-"],["10","승강기를 설치하여야 하는 건축물","-"]]},{"종류":"표","제목":"문화 및 집회시설의 세부 용도(별표 1 제5호)","머리":["목","용도","출구 설치 대상 여부"],"행":[["가","공연장(제2종 근린생활시설에 해당하지 않는 것)","대상"],["나","집회장(예식장, 공회당, 회의장 등)","대상"],["다","관람장(경마장, 경륜장, 경정장, 자동차 경기장 등)","대상"],["라","전시장(박물관, 미술관, 과학관, 산업전시장 등)","제외"],["마","동·식물원(동물원, 식물원, 수족관 등)","제외"]]}],"함정":"문화 및 집회시설을 통째로 대상으로 보면 전시장에서 틀린다. 무도학원은 위락시설(별표 1 제16호마목), 동물 전용의 장례식장은 장례시설(별표 1 제28호나목)로 분류되어 출구 설치 대상에 든다."}},{"i":"S5-2-1-공법-29","r":"S5","g":2,"c":2,"n":69,"s":"공법","q":"건축법령상 건축물의 면적 등의 산정방법에 관한 설명으로 틀린 것은? (단, 건축법령상 특례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["공동주택으로서 지상층에 설치한 조경시설의 면적은 바닥면적에 산입하지 않는다.","지하주차장의 경사로의 면적은 건축면적에 산입한다.","태양열을 주된 에너지원으로 이용하는 주택의 건축면적은 건축물의 외벽중 내측 내력벽의 중심선을 기준으로 한다.","용적률을 산정할 때에는 지하층의 면적은 연면적에 산입하지 않는다.","층의 구분이 명확하지 아니한 건축물의 높이는 4미터마다 하나의 층으로 보고 그 층수를 산정한다."],"a":[2],"L":"공4-3","o":"기출","x":{"한줄":"지하주차장의 경사로는 건축면적에 산입하지 않는다.","근거":[{"법령":"건축법 시행령","조문":"영 제119조제1항제2호다목4)","원문":"다. 다음의 경우에는 건축면적에 산입하지 않는다.\n4) 지하주차장의 경사로"},{"법령":"건축법 시행령","조문":"영 제119조제1항제3호마목","원문":"마. 공동주택으로서 지상층에 설치한 기계실, 전기실, 어린이놀이터, 조경시설 및 생활폐기물 보관시설의 면적은 바닥면적에 산입하지 않는다."},{"법령":"건축법 시행령","조문":"영 제119조제1항제4호가목","원문":"4. 연면적: 하나의 건축물 각 층의 바닥면적의 합계로 하되, 용적률을 산정할 때에는 다음 각 목에 해당하는 면적은 제외한다.\n가. 지하층의 면적"},{"법령":"건축법 시행규칙","조문":"규칙 제43조제1항","원문":"①영 제119조제1항제2호나목1) 및 3)에 따라 태양열을 주된 에너지원으로 이용하는 주택의 건축면적과 단열재를 구조체의 외기측에 설치하는 단열공법으로 건축된 건축물의 건축면적은 건축물의 외벽중 내측 내력벽의 중심선을 기준으로 한다. 이 경우 태양열을 주된 에너지원으로 이용하는 주택의 범위는 국토교통부장관이 정하여 고시하는 바에 따른다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공동주택으로서 지상층에 설치한 기계실·전기실·어린이놀이터·조경시설·생활폐기물 보관시설은 바닥면적에 산입하지 않는다(영 제119조제1항제3호마목)."},{"번호":2,"판정":"틀림","설명":"지하주차장의 경사로는 건축면적에 산입하지 않는 경우에 해당한다(영 제119조제1항제2호다목4))."},{"번호":3,"판정":"옳음","설명":"태양열을 주된 에너지원으로 이용하는 주택의 건축면적은 외벽 중 내측 내력벽의 중심선을 기준으로 한다(영 제119조제1항제2호나목1), 규칙 제43조제1항)."},{"번호":4,"판정":"옳음","설명":"용적률을 산정할 때 연면적에서 지하층의 면적은 제외한다(영 제119조제1항제4호가목)."},{"번호":5,"판정":"옳음","설명":"층의 구분이 명확하지 않은 건축물은 높이 4미터마다 하나의 층으로 보아 층수를 산정한다(영 제119조제1항제9호)."}],"개념":[{"종류":"표","제목":"면적·높이·층수 산정방법(영 제119조제1항)","머리":["대상","산정 기준"],"행":[["건축면적","외벽 중심선으로 둘러싸인 부분의 수평투영면적. 처마·차양 등이 중심선에서 1미터 이상 돌출되면 돌출 끝에서 일정 거리 후퇴한 선 기준(그 밖의 건축물은 1미터)"],["바닥면적","각 층 또는 그 일부로서 벽·기둥 등 구획의 중심선으로 둘러싸인 부분의 수평투영면적"],["연면적","각 층 바닥면적의 합계. 용적률 산정 시 지하층, 지상층의 부속용도 주차용 면적, 피난안전구역 면적 등 제외"],["건축물의 높이","지표면에서 건축물 상단까지. 옥상 승강기탑·계단탑 등은 수평투영면적 합계가 건축면적의 8분의 1 이하이면 12미터를 넘는 부분만 산입"],["층수","층의 구분이 명확하지 않으면 높이 4미터마다 한 층. 지하층과 건축면적 8분의 1 이하의 옥상 부분은 불산입. 부분별로 층수가 다르면 가장 많은 층수"]]},{"종류":"비교","제목":"건축면적과 바닥면적에서 빼는 것","왼쪽":{"이름":"건축면적에 산입하지 않는 것","항목":["지표면으로부터 1미터 이하에 있는 부분(창고 입출고 차량 접안 부분은 1.5미터 이하)","건축물 지상층의 보행통로나 차량통로","지하주차장의 경사로","건축물 지하층의 출입구 상부(출입구 너비에 상당하는 규모)","생활폐기물 보관시설","장애인용 승강기·에스컬레이터·휠체어리프트·경사로"]},"오른쪽":{"이름":"바닥면적에 산입하지 않는 것","항목":["공동주택 지상층의 기계실·전기실·어린이놀이터·조경시설·생활폐기물 보관시설","공중통행·차량통행·주차에 전용되는 필로티, 공동주택의 필로티","승강기탑, 계단탑, 장식탑, 층고 1.5미터(경사지붕 1.8미터) 이하 다락","지하주차장의 경사로(지상층에서 지하 1층으로 내려가는 부분)","장애인용 승강기·에스컬레이터·휠체어리프트·경사로"]}}],"함정":"지하주차장 경사로는 건축면적과 바닥면적 모두에서 빠진다. 공동주택 지상층의 조경시설은 바닥면적 불산입이다. 태양열 주택의 건축면적 기준(내측 내력벽의 중심선)은 시행규칙 제43조에 있다."}},{"i":"S5-2-1-공법-30","r":"S5","g":2,"c":2,"n":70,"s":"공법","q":"건축법령상 건축협정구역에서 건축하는 건축물에 대하여 완화하여 적용할 수 있는 건축기준 중 건축위원회의 심의와 「국토의 계획 및 이용에 관한 법률」에 따른 지방도시계획위원회의 심의를 통합하여 거쳐야 하는 것은?","b":null,"bs":"없음","img":[],"ch":["건축물의 용적률","건축물의 건폐율","건축물의 높이 제한","대지의 조경 면적","일조 등의 확보를 위한 건축물의 높이 제한"],"a":[1],"L":"공4-4","o":"기출","x":{"한줄":"건축협정구역에서 완화 적용하는 기준 중 용적률(제56조)만 건축위원회와 지방도시계획위원회의 통합 심의를 거친다.","근거":[{"법령":"건축법","조문":"법 제77조의13제6항","원문":"⑥ 건축협정구역에 건축하는 건축물에 대하여는 제42조, 제55조, 제56조, 제58조, 제60조 및 제61조와 「주택법」 제35조를 대통령령으로 정하는 바에 따라 완화하여 적용할 수 있다. 다만, 제56조를 완화하여 적용하는 경우에는 제4조에 따른 건축위원회의 심의와 「국토의 계획 및 이용에 관한 법률」 제113조에 따른 지방도시계획위원회의 심의를 통합하여 거쳐야 한다."},{"법령":"건축법 시행령","조문":"영 제110조의7제1항","원문":"① 건축협정구역에서 건축하는 건축물에 대해서는 법 제77조의13제6항에 따라 법 제42조, 제55조, 제56조, 제60조 및 제61조를 다음 각 호의 구분에 따라 완화하여 적용할 수 있다.\n2. 법 제55조에 따른 건폐율: 해당 지역에 적용하는 건폐율의 100분의 20의 범위에서 완화. 이 경우 「국토의 계획 및 이용에 관한 법률 시행령」 제84조에 따른 건폐율의 최대한도를 초과할 수 없다.\n3. 법 제56조에 따른 용적률: 해당 지역에 적용하는 용적률의 100분의 20의 범위에서 완화. 이 경우 「국토의 계획 및 이용에 관한 법률 시행령」 제85조에 따른 용적률의 최대한도를 초과할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"용적률(법 제56조)을 완화 적용하는 경우에만 건축위원회와 지방도시계획위원회의 심의를 통합하여 거친다(법 제77조의13제6항 단서)."},{"번호":2,"판정":"틀림","설명":"건폐율(법 제55조)은 기준의 100분의 20 범위에서 완화하며 국토계획법 시행령 제84조의 최대한도를 넘을 수 없다(영 제110조의7제1항제2호). 통합 심의는 제56조를 완화하는 경우에 한한다."},{"번호":3,"판정":"틀림","설명":"높이 제한(법 제60조)은 너비 6미터 이상의 도로에 접한 구역에 한해 높이 기준의 100분의 20 범위에서 완화한다(영 제110조의7제1항제4호). 이 완화는 통합 심의를 거치지 않는다."},{"번호":4,"판정":"틀림","설명":"대지의 조경 면적(법 제42조)은 도로에 면해 통합 조성하는 구역에 한해 기준의 100분의 20 범위에서 완화한다(영 제110조의7제1항제1호). 건축위원회 심의만으로 족하다."},{"번호":5,"판정":"틀림","설명":"일조 등의 확보를 위한 높이 제한(법 제61조)은 구역 안 대지 상호간에 건축하는 공동주택에 한해 100분의 20 범위에서 완화한다(영 제110조의7제1항제5호). 통합 심의 규정과 무관하다."}],"개념":[{"종류":"표","제목":"건축협정구역의 건축기준 완화(법 제77조의13제6항, 영 제110조의7제1항)","머리":["완화 기준","완화 범위","조건·심의"],"행":[["대지의 조경(법 제42조)","조경 면적 기준의 100분의 20 범위","도로에 면하여 통합 조성하는 건축협정구역에 한정"],["건폐율(법 제55조)","기준의 100분의 20 범위","국토계획법 시행령 제84조의 최대한도 초과 불가"],["용적률(법 제56조)","기준의 100분의 20 범위","국토계획법 시행령 제85조의 최대한도 초과 불가. 건축위원회와 지방도시계획위원회 통합 심의"],["높이 제한(법 제60조)","높이 기준의 100분의 20 범위","너비 6미터 이상 도로에 접한 구역에 한정"],["일조 등 높이 제한(법 제61조)","기준의 100분의 20 범위","구역 안 대지 상호간에 건축하는 공동주택에 한정"]]},{"종류":"흐름","제목":"건축협정의 체결부터 폐지까지","단계":[{"이름":"체결","설명":"토지 또는 건축물의 소유자, 지상권자 등이 전원의 합의로 지구단위계획구역 등에서 체결한다. 토지 소유자가 1인이어도 체결할 수 있다(법 제77조의4제1항·제2항)."},{"이름":"인가","설명":"협정체결자 또는 건축협정운영회의 대표자가 건축협정서를 작성해 건축협정인가권자의 인가를 받는다. 인가 전 건축위원회 심의를 거친다(법 제77조의6제1항)."},{"이름":"공고","설명":"인가하면 내용을 공고한다. 공고 후 권리를 이전받은 자는 협정체결자의 지위를 승계한다(법 제77조의6제3항, 제77조의10제2항)."},{"이름":"변경","설명":"인가받은 사항을 변경하려면 변경인가를 받는다. 경미한 사항은 제외한다(법 제77조의7)."},{"이름":"폐지","설명":"협정체결자 과반수의 동의를 받아 건축협정인가권자의 인가를 받는다(법 제77조의9제1항)."}]}],"함정":"완화 대상은 조경·건폐율·용적률·높이·일조 높이 다섯 가지이지만 통합 심의는 용적률만이다. 건폐율을 용적률과 같은 묶음으로 보기 쉽다. 이 외에 맞벽 건축 등에서는 대지의 조경, 대지와 도로의 관계, 지하층, 건폐율, 부설주차장 등을 통합 적용하는 별도 특례가 있다(법 제77조의13제3항)."}},{"i":"S5-2-1-공법-31","r":"S5","g":2,"c":2,"n":71,"s":"공법","q":"주택법령상 용어에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["「건축법 시행령」에 따른 다세대주택은 공동주택에 해당한다.","「건축법 시행령」에 따른 오피스텔은 준주택에 해당한다.","주택단지에 해당하는 토지가 폭 8미터 이상인 도시계획예정도로로 분리된 경우, 분리된 토지를 각각 별개의 주택단지로 본다.","주택에 딸린 자전거보관소는 복리시설에 해당한다.","도로ㆍ상하수도ㆍ전기시설ㆍ가스시설ㆍ통신시설ㆍ지역난방시설은 기간시설(基幹施設)에 해당한다."],"a":[4],"L":"공5-1","o":"기출","x":{"한줄":"주택에 딸린 자전거보관소는 복리시설이 아니라 부대시설이다.","근거":[{"법령":"주택법 시행령","조문":"영 제6조제1호","원문":"제6조(부대시설의 범위) 법 제2조제13호다목에서 \"대통령령으로 정하는 시설 또는 설비\"란 다음 각 호의 시설 또는 설비를 말한다.\n1. 보안등, 대문, 경비실 및 자전거보관소"},{"법령":"주택법","조문":"법 제2조제13호·제14호","원문":"13. \"부대시설\"이란 주택에 딸린 다음 각 목의 시설 또는 설비를 말한다.\n14. \"복리시설\"이란 주택단지의 입주자 등의 생활복리를 위한 다음 각 목의 공동시설을 말한다.\n가. 어린이놀이터, 근린생활시설, 유치원, 주민운동시설 및 경로당"},{"법령":"주택법 시행령","조문":"영 제4조제4호","원문":"제4조(준주택의 종류와 범위) 법 제2조제4호에 따른 준주택의 종류와 범위는 다음 각 호와 같다.\n4. 「건축법 시행령」 별표 1 제14호나목2)에 따른 오피스텔"},{"법령":"주택법","조문":"법 제2조제12호다목","원문":"12. \"주택단지\"란 제15조에 따른 주택건설사업계획 또는 대지조성사업계획의 승인을 받아 주택과 그 부대시설 및 복리시설을 건설하거나 대지를 조성하는 데 사용되는 일단(一團)의 토지를 말한다. 다만, 다음 각 목의 시설로 분리된 토지는 각각 별개의 주택단지로 본다.\n다. 폭 8미터 이상인 도시계획예정도로"},{"법령":"주택법","조문":"법 제2조제16호","원문":"16. \"기간시설\"(基幹施設)이란 도로ㆍ상하수도ㆍ전기시설ㆍ가스시설ㆍ통신시설ㆍ지역난방시설 등을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"다세대주택은 공동주택의 종류다(영 제3조제1항제3호)."},{"번호":2,"판정":"옳음","설명":"오피스텔은 준주택이다(영 제4조제4호)."},{"번호":3,"판정":"옳음","설명":"폭 8미터 이상인 도시계획예정도로로 분리된 토지는 각각 별개의 주택단지로 본다(법 제2조제12호다목)."},{"번호":4,"판정":"틀림","설명":"자전거보관소는 부대시설이다(영 제6조제1호). 복리시설은 어린이놀이터, 근린생활시설, 유치원, 주민운동시설, 경로당 등이다(법 제2조제14호)."},{"번호":5,"판정":"옳음","설명":"도로·상하수도·전기시설·가스시설·통신시설·지역난방시설 등이 기간시설이다(법 제2조제16호)."}],"개념":[{"종류":"비교","제목":"부대시설과 복리시설","왼쪽":{"이름":"부대시설(법 제2조제13호, 영 제6조)","항목":["주차장, 관리사무소, 담장, 주택단지 안의 도로","건축설비(전기·가스·급수·배수·난방·소화·승강기 등)","보안등, 대문, 경비실, 자전거보관소","조경시설, 옹벽, 축대","안내표지판, 공중화장실","저수시설, 지하양수시설, 대피시설","쓰레기 수거·처리시설, 오수처리시설, 정화조","소방시설, 냉난방공급시설(지역난방공급시설 제외), 방범설비","전기자동차 충전 공급시설"]},"오른쪽":{"이름":"복리시설(법 제2조제14호, 영 제7조)","항목":["어린이놀이터, 근린생활시설, 유치원, 주민운동시설, 경로당","종교시설, 판매시설 중 소매시장 및 상점","교육연구시설, 노유자시설, 수련시설","업무시설 중 금융업소, 지식산업센터, 사회복지관","공동작업장, 주민공동시설, 도시·군계획시설인 시장","제2종 근린생활시설 중 총포판매소·장의사·다중생활시설·단란주점·안마시술소는 제외"]}},{"종류":"표","제목":"주택법상 주택·준주택·주택단지 용어","머리":["용어","내용","근거"],"행":[["공동주택","아파트, 연립주택, 다세대주택","영 제3조제1항"],["준주택","기숙사, 다중생활시설, 노인복지주택, 오피스텔","영 제4조"],["주택단지 분리","철도·고속도로·자동차전용도로, 폭 20미터 이상 일반도로, 폭 8미터 이상 도시계획예정도로로 분리된 토지는 별개의 주택단지","법 제2조제12호"],["기간시설","도로·상하수도·전기시설·가스시설·통신시설·지역난방시설 등","법 제2조제16호"],["간선시설","주택단지 안의 기간시설을 단지 밖의 같은 종류의 기간시설에 연결시키는 시설. 가스·통신·지역난방은 단지 안 기간시설 포함","법 제2조제17호"]]}],"함정":"부대시설과 복리시설의 구분이 핵심이다. 자전거보관소·경비실·조경시설·방범설비는 부대시설이고, 주민공동시설·어린이놀이터·경로당은 복리시설이다. 기간시설은 도로·상하수도 등 시설 자체이고, 간선시설은 단지 안 기간시설을 단지 밖 같은 종류의 기간시설에 연결하는 시설이다(법 제2조제17호)."}},{"i":"S5-2-1-공법-32","r":"S5","g":2,"c":2,"n":72,"s":"공법","q":"주택법령상 용어에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["「수도권정비계획법」에 따른 수도권을 제외한 도시지역이 아닌 읍 또는 면 지역에서 1호당 주거전용면적이 100제곱미터 이하인 주택은 \"국민주택규모\"에 해당한다.","한국토지주택공사가 건설하는 주택은 주거전용면적과 관계없이 \"국민주택\"에 해당한다.","경비실은 \"복리시설\"에 해당한다.","「건축법 시행령」에 따른 다중생활시설은 \"준주택\"에 해당하지 않는다.","\"도시형 생활주택\"이란 500세대 미만의 국민주택규모에 해당하는 주택으로서 대통령령으로 정하는 주택을 말한다."],"a":[1],"L":"공5-1","o":"변형","x":{"한줄":"수도권 밖의 도시지역이 아닌 읍·면 지역은 1호당 주거전용면적 100제곱미터 이하까지 국민주택규모로 본다.","근거":[{"법령":"주택법","조문":"법 제2조제5호·제6호","원문":"5. \"국민주택\"이란 다음 각 목의 어느 하나에 해당하는 주택으로서 국민주택규모 이하인 주택을 말한다.\n가. 국가ㆍ지방자치단체, 「한국토지주택공사법」에 따른 한국토지주택공사(이하 \"한국토지주택공사\"라 한다) 또는 「지방공기업법」 제49조에 따라 주택사업을 목적으로 설립된 지방공사(이하 \"지방공사\"라 한다)가 건설하는 주택\n6. \"국민주택규모\"란 주거의 용도로만 쓰이는 면적(이하 \"주거전용면적\"이라 한다)이 1호(戶) 또는 1세대당 85제곱미터 이하인 주택(「수도권정비계획법」 제2조제1호에 따른 수도권을 제외한 도시지역이 아닌 읍 또는 면 지역은 1호 또는 1세대당 주거전용면적이 100제곱미터 이하인 주택을 말한다)을 말한다. 이 경우 주거전용면적의 산정방법은 국토교통부령으로 정한다."},{"법령":"주택법 시행령","조문":"영 제6조제1호","원문":"제6조(부대시설의 범위) 법 제2조제13호다목에서 \"대통령령으로 정하는 시설 또는 설비\"란 다음 각 호의 시설 또는 설비를 말한다.\n1. 보안등, 대문, 경비실 및 자전거보관소"},{"법령":"주택법 시행령","조문":"영 제4조제2호","원문":"2. 「건축법 시행령」 별표 1 제4호거목 및 제15호다목에 따른 다중생활시설"},{"법령":"주택법","조문":"법 제2조제20호","원문":"20. \"도시형 생활주택\"이란 300세대 미만의 국민주택규모에 해당하는 주택으로서 대통령령으로 정하는 주택을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"국민주택규모는 1호당 주거전용면적 85제곱미터 이하이고, 수도권을 제외한 도시지역이 아닌 읍 또는 면 지역은 100제곱미터 이하다(법 제2조제6호)."},{"번호":2,"판정":"틀림","설명":"국민주택은 한국토지주택공사가 건설하는 주택 등으로서 국민주택규모 이하인 주택이다(법 제2조제5호). 규모를 초과하면 국민주택이 아니다."},{"번호":3,"판정":"틀림","설명":"경비실은 부대시설이다(영 제6조제1호). 복리시설은 법 제2조제14호와 영 제7조에 열거된 공동시설이다."},{"번호":4,"판정":"틀림","설명":"다중생활시설은 준주택이다(영 제4조제2호)."},{"번호":5,"판정":"틀림","설명":"도시형 생활주택은 300세대 미만의 국민주택규모에 해당하는 주택이다(법 제2조제20호)."}],"개념":[{"종류":"표","제목":"국민주택·민영주택·도시형 생활주택","머리":["용어","기준","근거"],"행":[["국민주택","국가·지방자치단체·한국토지주택공사·지방공사가 건설하는 주택, 또는 국가·지방자치단체의 재정이나 주택도시기금으로부터 자금을 지원받아 건설·개량되는 주택으로서 국민주택규모 이하","법 제2조제5호"],["국민주택규모","1호 또는 1세대당 주거전용면적 85제곱미터 이하. 수도권 외의 도시지역이 아닌 읍·면 지역은 100제곱미터 이하","법 제2조제6호"],["민영주택","국민주택을 제외한 주택","법 제2조제7호"],["도시형 생활주택","300세대 미만의 국민주택규모 주택으로서 도시지역에 건설하는 아파트형 주택, 단지형 연립주택, 단지형 다세대주택","법 제2조제20호, 영 제10조"],["세대구분형 공동주택","주택 내부 공간의 일부를 세대별로 구분해 생활이 가능하되 구분된 공간 일부를 구분소유할 수 없는 주택","법 제2조제19호"]]},{"종류":"표","제목":"도시형 생활주택의 건축 제한(영 제10조)","머리":["구분","내용"],"행":[["아파트형 주택","세대별로 독립된 주거가 가능하도록 욕실과 부엌을 설치하고, 지하층에는 세대를 설치하지 않을 것"],["단지형 연립·다세대주택","건축위원회 심의를 받으면 제1종전용주거지역·제1종일반주거지역은 5개 층까지, 그 밖의 지역은 6개 층까지"],["혼합 건축 금지","하나의 건축물에 도시형 생활주택과 그 밖의 주택을 함께 건축할 수 없음. 예외는 주거전용면적 85제곱미터 초과 주택 1세대와의 혼합, 준주거지역·상업지역의 아파트형 주택과 그 밖의 주택 혼합"],["단지형과 아파트형","단지형 연립주택·단지형 다세대주택과 아파트형 주택은 하나의 건축물에 함께 건축 불가"]]}],"함정":"한국토지주택공사가 건설해도 국민주택규모를 넘으면 국민주택이 아니다. 100제곱미터 특례는 수도권 밖의 도시지역이 아닌 읍·면 지역에만 적용된다. 도시형 생활주택의 상한은 300세대 미만이다."}},{"i":"S5-2-1-공법-33","r":"S5","g":2,"c":2,"n":73,"s":"공법","q":"주택법령상 주택상환사채에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["주택상환사채의 납입금은 주택건설자재의 구입을 위하여 사용할 수 있다.","주택상환사채는 무기명증권으로 한다.","등록사업자의 등록이 말소된 경우에는 등록사업자가 발행한 주택상환사채의 효력도 소멸한다.","등록사업자가 발행할 수 있는 주택상환사채의 규모는 최근 5년간의 연평균 주택건설 호수 이내로 한다.","주택상환사채의 상환기간은 5년 이내로 한다."],"a":[1],"L":"공5-1","o":"기출","x":{"한줄":"주택상환사채의 납입금은 택지의 구입·조성, 주택건설자재의 구입, 건설공사비 충당 등에 쓸 수 있다.","근거":[{"법령":"주택법 시행령","조문":"영 제87조제1항","원문":"① 주택상환사채의 납입금은 다음 각 호의 용도로만 사용할 수 있다.\n1. 택지의 구입 및 조성\n2. 주택건설자재의 구입\n3. 건설공사비에의 충당\n4. 그 밖에 주택상환을 위하여 필요한 비용으로서 국토교통부장관의 승인을 받은 비용에의 충당"},{"법령":"주택법","조문":"법 제81조제2항","원문":"② 주택상환사채는 기명증권(記名證券)으로 하고, 사채권자의 명의변경은 취득자의 성명과 주소를 사채원부에 기록하는 방법으로 하며, 취득자의 성명을 채권에 기록하지 아니하면 사채발행자 및 제3자에게 대항할 수 없다."},{"법령":"주택법","조문":"법 제82조","원문":"제82조(주택상환사채의 효력) 제8조에 따라 등록사업자의 등록이 말소된 경우에도 등록사업자가 발행한 주택상환사채의 효력에는 영향을 미치지 아니한다."},{"법령":"주택법 시행령","조문":"영 제84조제2항","원문":"② 등록사업자가 발행할 수 있는 주택상환사채의 규모는 최근 3년간의 연평균 주택건설 호수 이내로 한다."},{"법령":"주택법 시행령","조문":"영 제86조제1항","원문":"① 주택상환사채의 상환기간은 3년을 초과할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"납입금은 택지의 구입 및 조성, 주택건설자재의 구입, 건설공사비 충당, 장관이 승인한 비용에 한해 쓸 수 있다(영 제87조제1항제2호)."},{"번호":2,"판정":"틀림","설명":"주택상환사채는 기명증권으로 한다(법 제81조제2항). 명의변경은 사채원부 기록으로 한다."},{"번호":3,"판정":"틀림","설명":"등록사업자의 등록이 말소되어도 발행한 주택상환사채의 효력에는 영향이 없다(법 제82조)."},{"번호":4,"판정":"틀림","설명":"등록사업자의 발행 규모는 최근 3년간 연평균 주택건설 호수 이내다(영 제84조제2항)."},{"번호":5,"판정":"틀림","설명":"상환기간은 3년을 초과할 수 없다(영 제86조제1항)."}],"개념":[{"종류":"표","제목":"주택상환사채 요약(법 제80조~제83조, 영 제83조~제87조)","머리":["항목","내용"],"행":[["발행자","한국토지주택공사, 등록사업자"],["등록사업자 요건","법인으로서 자본금 5억원 이상, 건설업 등록, 최근 3년간 연평균 주택건설 실적 300호 이상, 금융기관 또는 주택도시보증공사의 보증"],["발행 승인","주택상환사채발행계획을 수립해 국토교통부장관의 승인"],["발행 규모","등록사업자는 최근 3년간 연평균 주택건설 호수 이내"],["증권 형태","기명증권. 명의변경은 취득자의 성명·주소를 사채원부에 기록"],["상환기간","3년 초과 불가. 발행일부터 주택 공급계약 체결일까지"],["양도·해약","양도하거나 중도에 해약 불가. 해외이주 등 국토교통부령이 정한 부득이한 사유는 예외"],["납입금 용도","택지 구입·조성, 주택건설자재 구입, 건설공사비 충당, 장관 승인 비용"],["등록 말소","등록이 말소되어도 주택상환사채의 효력에 영향 없음"]]},{"종류":"흐름","제목":"주택상환사채 발행 절차","단계":[{"이름":"발행계획 수립·승인 신청","설명":"발행계획서에 택지 권리 증명서류, 금융기관 또는 주택도시보증공사의 보증서를 첨부해 국토교통부장관에게 제출한다. 발행대행계약서와 납입금 관리계약서는 모집공고 전까지 제출할 수 있다(영 제85조제1항)."},{"이름":"승인·통보","설명":"국토교통부장관이 승인하고 발행 대상지역 관할 시·도지사에게 통보한다(영 제85조제3항)."},{"이름":"모집공고","설명":"모집 전에 모집공고안을 작성해 국토교통부장관에게 제출한다(영 제85조제4항)."},{"이름":"발행·납입금 관리","설명":"액면 또는 할인 방법으로 발행하고 주택상환사채대장을 갖춘다. 납입금은 보증기관과 협의한 금융기관이 관리한다(영 제83조, 제87조제2항)."},{"이름":"상환","설명":"발행조건에 따라 주택을 건설해 사채권자에게 상환한다(법 제81조제1항)."}]}],"함정":"상환기간(3년), 발행 규모의 기준 기간(3년), 증권 형태(기명증권)가 선지에서 바뀌어 나온다. 등록이 말소되어도 사채의 효력은 유지된다."}},{"i":"S5-2-1-공법-34","r":"S5","g":2,"c":2,"n":74,"s":"공법","q":"주택법령상 공동주택 품질점검단에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["품질점검단은 시장·군수·구청장이 설치·운영한다.","사업주체가 품질점검단의 점검에 따르지 아니하거나 기피 또는 방해한 경우 과태료 부과의 대상에 해당한다.","품질점검단은 품질점검을 실시한 후 점검 종료일부터 3일 이내에 점검결과를 사용검사권자에게 제출하여야 한다.","사용검사권자는 품질점검단으로부터 제출받은 점검결과를 사용검사가 있은 날부터 3년 이상 보관하여야 한다.","공무원으로서 공동주택 관련 지도ㆍ감독 및 인ㆍ허가 업무 등에 종사한 경력이 4년인 사람은 품질점검단의 위원이 될 수 있다."],"a":[2],"L":"공5-2","o":"기출","x":{"한줄":"사업주체가 품질점검단의 점검에 따르지 않거나 기피·방해하면 2천만원 이하의 과태료 대상이다.","근거":[{"법령":"주택법","조문":"법 제48조의3제3항","원문":"③ 사업주체는 제2항에 따른 품질점검단의 점검에 협조하여야 하며 이에 따르지 아니하거나 기피 또는 방해해서는 아니 된다."},{"법령":"주택법","조문":"법 제106조제1항제2호","원문":"① 다음 각 호의 어느 하나에 해당하는 자에게는 2천만원 이하의 과태료를 부과한다.\n2. 제48조의3제3항을 위반하여 점검에 따르지 아니하거나 기피 또는 방해한 자"},{"법령":"주택법","조문":"법 제48조의3제1항·제5항","원문":"① 시ㆍ도지사는 제48조의2에 따른 사전방문을 실시하고 제49조제1항에 따른 사용검사를 신청하기 전에 공동주택의 품질을 점검하여 사업계획의 내용에 적합한 공동주택이 건설되도록 할 목적으로 주택 관련 분야 등의 전문가로 구성된 공동주택 품질점검단(이하 \"품질점검단\"이라 한다)을 설치ㆍ운영할 수 있다. 이 경우 시ㆍ도지사는 품질점검단의 설치ㆍ운영에 관한 사항을 조례로 정하는 바에 따라 대도시 시장에게 위임할 수 있다.\n⑤ 사용검사권자는 제2항에 따라 제출받은 점검결과를 제49조제1항에 따른 사용검사가 있은 날부터 2년 이상 보관하여야 하며, 입주자(입주예정자를 포함한다)가 관련 자료의 공개를 요구하는 경우에는 이를 공개하여야 한다."},{"법령":"주택법 시행규칙","조문":"규칙 제20조의4제5항","원문":"⑤ 품질점검단은 품질점검을 실시한 후 점검 종료일부터 5일 이내에 점검결과를 시ㆍ도지사와 사용검사권자에게 제출해야 한다."},{"법령":"주택법 시행령","조문":"영 제53조의4제1항제8호","원문":"8. 공무원으로서 공동주택 관련 지도ㆍ감독 및 인ㆍ허가 업무 등에 종사한 경력이 5년 이상인 사람"}],"선지":[{"번호":1,"판정":"틀림","설명":"품질점검단은 시·도지사가 설치·운영한다. 시·도지사는 조례로 대도시 시장에게 위임할 수 있다(법 제48조의3제1항)."},{"번호":2,"판정":"옳음","설명":"점검에 따르지 않거나 기피 또는 방해한 사업주체에게는 2천만원 이하의 과태료를 부과한다(법 제106조제1항제2호, 제48조의3제3항)."},{"번호":3,"판정":"틀림","설명":"품질점검단은 점검 종료일부터 5일 이내에 결과를 시·도지사와 사용검사권자에게 제출한다(규칙 제20조의4제5항)."},{"번호":4,"판정":"틀림","설명":"사용검사권자는 점검결과를 사용검사가 있은 날부터 2년 이상 보관한다(법 제48조의3제5항)."},{"번호":5,"판정":"틀림","설명":"공무원 출신 위원은 공동주택 관련 지도·감독 및 인·허가 업무 등에 종사한 경력이 5년 이상이어야 한다(영 제53조의4제1항제8호)."}],"개념":[{"종류":"표","제목":"공동주택 품질점검단 요약","머리":["항목","내용","근거"],"행":[["설치·운영","시·도지사. 조례로 대도시 시장에게 위임 가능","법 제48조의3제1항"],["점검 대상","공동주택 중 등록사업자 등이 건설하는 300세대 이상. 시·도지사가 필요하다고 인정하면 조례로 300세대 미만도 가능","영 제53조의5제1항"],["점검 사항","공용부분, 일부 세대의 전유부분(3세대 이상 선정), 사용검사권자가 자문 요청한 현장조사 사항","영 제53조의5제2항, 규칙 제20조의4제4항"],["결과 제출","점검 종료일부터 5일 이내에 시·도지사와 사용검사권자에게","규칙 제20조의4제5항"],["결과 보관","사용검사가 있은 날부터 2년 이상. 입주자가 요구하면 공개","법 제48조의3제5항"],["위원 임기","공무원이 아닌 위원은 2년, 두 차례만 연임","영 제53조의4제2항"],["사업주체 협조 위반","점검에 따르지 않거나 기피·방해: 2천만원 이하 과태료. 조치명령 불이행: 1천만원 이하 과태료","법 제106조"]]},{"종류":"흐름","제목":"품질점검부터 조치명령까지","단계":[{"이름":"점검 요청","설명":"사업주체의 사전방문계획을 받은 사용검사권자가 대상 공동주택이면 지체 없이 시·도지사에게 품질점검을 요청한다(규칙 제20조의4제1항)."},{"이름":"점검계획 통보","설명":"시·도지사는 점검 시작일 7일 전까지 사용검사권자와 사업주체에게 통보한다(규칙 제20조의4제3항)."},{"이름":"점검 실시","설명":"사전방문기간 종료일부터 10일 이내에 점검한다(규칙 제20조의4제2항)."},{"이름":"결과 제출","설명":"점검 종료일부터 5일 이내에 제출한다(규칙 제20조의4제5항)."},{"이름":"사업주체 의견","설명":"사용검사권자가 점검결과를 사업주체에 즉시 통보하고, 사업주체는 통보일부터 5일 이내에 의견을 낼 수 있다(영 제53조의6제1항·제2항)."},{"이름":"조치명령","설명":"하자로 판단하면 의견 제출일부터 5일 이내에 보수·보강 등을 명한다(영 제53조의6제3항)."}]}],"함정":"설치 주체는 시장·군수·구청장이 아니라 시·도지사다. 결과 제출 5일, 결과 보관 2년, 공무원 경력 5년이 선지에서 3일, 3년, 4년으로 바뀌어 나온다. 과태료는 점검 기피·방해에 부과하고 상한은 2천만원이다."}},{"i":"S5-2-1-공법-35","r":"S5","g":2,"c":2,"n":75,"s":"공법","q":"주택법령상 사업주체가 50세대의 주택과 주택 외의 시설을 동일 건축물로 건축하는 계획 및 임대주택의 건설·공급에 관한 사항을 포함한 사업계획승인신청서를 제출한 경우에 대한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["사업주체는 사업계획승인을 신청한 후에 용적률의 완화로 건설되는 임대주택의 규모 등에 관하여 인수자와 협의하여 승인 내용에 반영하여야 한다.","용적률의 완화로 건설되는 임대주택의 부속토지는 인수자에게 기부채납한 것으로 본다.","사업주체는 완화된 용적률의 60퍼센트에 해당하는 면적을 임대주택으로 공급하여야 한다.","사업주체가 임대주택을 인수자에게 공급하는 경우 시장·군수·구청장이 우선 인수할 수 있다.","사업주체가 임대주택의 준공인가를 받은 후 등기를 거부하거나 지체하더라도 인수자는 등기를 촉탁 또는 신청할 수 없다."],"a":[2],"L":"공5-2","o":"변형","x":{"한줄":"용적률 완화로 건설되는 임대주택의 부속토지는 인수자에게 기부채납한 것으로 본다.","근거":[{"법령":"주택법","조문":"법 제20조제3항","원문":"③ 제2항에 따라 공급되는 임대주택의 공급가격은 「공공주택 특별법」 제50조의3제1항에 따른 공공건설임대주택의 분양전환가격 산정기준에서 정하는 건축비로 하고, 그 부속토지는 인수자에게 기부채납한 것으로 본다."},{"법령":"주택법","조문":"법 제20조제2항 전단","원문":"② 제1항에 따라 용적률을 완화하여 적용하는 경우 사업주체는 완화된 용적률의 60퍼센트 이하의 범위에서 대통령령으로 정하는 비율 이상에 해당하는 면적을 임대주택으로 공급하여야 한다. 이 경우 사업주체는 임대주택을 국토교통부장관, 시ㆍ도지사, 한국토지주택공사 또는 지방공사(이하 \"인수자\"라 한다)에 공급하여야 하며 시ㆍ도지사가 우선 인수할 수 있다. 다만, 시ㆍ도지사가 임대주택을 인수하지 아니하는 경우 다음 각 호의 구분에 따라 국토교통부장관에게 인수자 지정을 요청하여야 한다."},{"법령":"주택법 시행령","조문":"영 제37조제1항","원문":"① 법 제20조제2항 각 호 외의 부분에서 \"대통령령으로 정하는 비율\"이란 30퍼센트 이상 60퍼센트 이하의 범위에서 특별시ㆍ광역시ㆍ특별자치시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 조례로 정하는 비율을 말한다."},{"법령":"주택법","조문":"법 제20조제4항·제6항","원문":"④ 사업주체는 제15조에 따른 사업계획승인을 신청하기 전에 미리 용적률의 완화로 건설되는 임대주택의 규모 등에 관하여 인수자와 협의하여 사업계획승인신청서에 반영하여야 한다.\n⑥ 사업주체는 임대주택의 준공인가(「건축법」 제22조의 사용승인을 포함한다)를 받은 후 지체 없이 인수자에게 등기를 촉탁 또는 신청하여야 한다. 이 경우 사업주체가 거부 또는 지체하는 경우에는 인수자가 등기를 촉탁 또는 신청할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"인수자와의 협의는 사업계획승인을 신청하기 전에 미리 한다(법 제20조제4항)."},{"번호":2,"판정":"옳음","설명":"임대주택의 공급가격은 공공건설임대주택의 분양전환가격 산정기준상 건축비로 하고, 부속토지는 인수자에게 기부채납한 것으로 본다(법 제20조제3항)."},{"번호":3,"판정":"틀림","설명":"공급 면적은 완화된 용적률의 60퍼센트 이하 범위에서 대통령령이 정하는 비율 이상이고, 그 비율은 시·도 조례로 30퍼센트 이상 60퍼센트 이하에서 정한다(법 제20조제2항, 영 제37조제1항)."},{"번호":4,"판정":"틀림","설명":"시·도지사가 우선 인수할 수 있다(법 제20조제2항). 시·도지사가 인수하지 않으면 관할 시장·군수·구청장이 국토교통부장관에게 인수자 지정을 요청한다."},{"번호":5,"판정":"틀림","설명":"사업주체가 거부하거나 지체하면 인수자가 등기를 촉탁 또는 신청할 수 있다(법 제20조제6항)."}],"개념":[{"종류":"표","제목":"주택건설사업 등에 따른 임대주택(법 제20조, 영 제37조)","머리":["항목","내용"],"행":[["용적률 완화","사업계획승인신청서에 제15조제1항 호수 이상의 주택과 주택 외 시설을 동일 건축물로 건축하는 계획과 임대주택 건설·공급 사항을 포함하면 용도지역별 용적률 범위에서 조례 기준에 따라 완화 가능. 건폐율은 완화 대상이 아님"],["임대주택 공급 비율","완화된 용적률의 60퍼센트 이하 범위에서 대통령령이 정하는 비율 이상. 시·도 조례로 30퍼센트 이상 60퍼센트 이하"],["인수자","국토교통부장관, 시·도지사, 한국토지주택공사 또는 지방공사. 시·도지사가 우선 인수"],["인수자 지정","시·도지사가 인수하지 않으면 시장·군수·구청장이 국토교통부장관에게 지정 요청. 국토교통부장관은 30일 이내 지정·통보"],["공급가격","분양전환가격 산정기준상 건축비. 부속토지는 인수자에게 기부채납한 것으로 봄"],["사전 협의","사업계획승인 신청 전에 임대주택의 규모 등을 인수자와 협의해 신청서에 반영"],["임대주택 선정","공급 주택 전부(주택조합이 설립된 경우 조합원 공급 후 남은 주택)를 대상으로 공개추첨"],["등기","준공인가(사용승인 포함) 후 지체 없이 인수자에게 등기 촉탁·신청. 사업주체가 거부·지체하면 인수자가 촉탁·신청 가능"]]},{"종류":"흐름","제목":"용적률 완화 임대주택 공급 순서","단계":[{"이름":"인수자와 사전 협의","설명":"사업계획승인 신청 전에 임대주택의 규모 등을 협의한다(법 제20조제4항)."},{"이름":"사업계획승인 신청","설명":"주택·주택 외 시설 동일 건축물 계획과 임대주택 건설·공급 사항을 신청서에 포함한다(법 제20조제1항)."},{"이름":"용적률 완화","설명":"사업계획승인권자가 조례 기준에 따라 용적률을 완화한다(법 제20조제1항)."},{"이름":"임대주택 선정","설명":"공개추첨으로 선정하고 결과를 지체 없이 인수자에게 통보한다(법 제20조제5항)."},{"이름":"준공 후 등기","설명":"준공인가 후 지체 없이 인수자에게 등기를 촉탁·신청한다(법 제20조제6항)."}]}],"함정":"완화 대상은 용적률뿐이고 건폐율은 아니다. 공급 비율은 60퍼센트로 고정되지 않고 30~60퍼센트 범위에서 시·도 조례가 정한다. 우선 인수 주체는 시·도지사이고 시장·군수·구청장이 아니다."}},{"i":"S5-2-1-공법-36","r":"S5","g":2,"c":2,"n":76,"s":"공법","q":"주택법령상 공동주택의 리모델링에 관한 설명으로 틀린 것은?(단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["입주자·사용자 또는 관리주체가 리모델링하려는 경우에는 공사기간, 공사방법 등이 적혀 있는 동의서에 입주자 전체의 동의를 받아야 한다.","리모델링에 동의한 소유자는 리모델링주택조합 또는 입주자대표회의가 허가신청서를 시장·군수·구청장에게 제출하기 전까지 서면으로 동의를 철회할 수 있다.","수직증축형 리모델링의 대상이 되는 기존 건축물의 층수가 14층 이하인 경우에는 3개 층까지 증축할 수 있다.","리모델링주택조합이 주택단지 전체를 리모델링하려는 경우 주택단지 전체 구분소유자 및 의결권의 각 75퍼센트 이상의 동의와 각 동별 구분소유자 및 의결권의 각 50퍼센트 이상의 동의를 받아야 한다.","시장·군수·구청장이 50세대 이상으로 세대수가 증가하는 세대수 증가형 리모델링을 허가하려는 경우에는 시·군·구도시계획위원회의 심의를 거쳐야 한다."],"a":[3],"L":"공5-3","o":"변형","x":{"한줄":"수직증축형 리모델링은 기존 15층 이상이면 3개 층, 14층 이하이면 2개 층까지 증축할 수 있다.","근거":[{"법령":"주택법 시행령","조문":"영 제13조제1항","원문":"① 법 제2조제25호다목1)에서 \"대통령령으로 정하는 범위\"란 다음 각 호의 구분에 따른 범위를 말한다.\n1. 수직으로 증축하는 행위(이하 \"수직증축형 리모델링\"이라 한다)의 대상이 되는 기존 건축물의 층수가 15층 이상인 경우: 3개층\n2. 수직증축형 리모델링의 대상이 되는 기존 건축물의 층수가 14층 이하인 경우: 2개층"},{"법령":"주택법 시행령","조문":"영 제75조제3항","원문":"③ 법 제66조제2항에 따라 리모델링에 동의한 소유자는 리모델링주택조합 또는 입주자대표회의가 제2항에 따라 시장ㆍ군수ㆍ구청장에게 허가신청서를 제출하기 전까지 서면으로 동의를 철회할 수 있다."},{"법령":"주택법 시행령","조문":"별표 4 제1호가목·나목","원문":"가. 입주자ㆍ사용자 또는 관리주체의 경우\n공사기간, 공사방법 등이 적혀 있는 동의서에 입주자 전체의 동의를 받아야 한다.\n나. 리모델링주택조합의 경우\n다음의 사항이 적혀 있는 결의서에 주택단지 전체를 리모델링하는 경우에는 주택단지 전체 구분소유자 및 의결권의 각 75퍼센트 이상의 동의와 각 동별 구분소유자 및 의결권의 각 50퍼센트 이상의 동의를 받아야 하며, 동을 리모델링하는 경우에는 그 동의 구분소유자 및 의결권의 각 75퍼센트 이상의 동의를 받아야 한다."},{"법령":"주택법","조문":"법 제66조제6항","원문":"⑥ 제1항에 따라 시장ㆍ군수ㆍ구청장이 세대수 증가형 리모델링(대통령령으로 정하는 세대수 이상으로 세대수가 증가하는 경우로 한정한다. 이하 이 조에서 같다)을 허가하려는 경우에는 기반시설에의 영향이나 도시ㆍ군관리계획과의 부합 여부 등에 대하여 「국토의 계획 및 이용에 관한 법률」 제113조제2항에 따라 설치된 시ㆍ군ㆍ구도시계획위원회(이하 \"시ㆍ군ㆍ구도시계획위원회\"라 한다)의 심의를 거쳐야 한다."},{"법령":"주택법 시행령","조문":"영 제76조제2항","원문":"② 법 제66조제6항에서 \"대통령령으로 정하는 세대수\"란 50세대를 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"입주자·사용자 또는 관리주체가 하는 리모델링은 입주자 전체의 동의서가 필요하다(영 별표 4 제1호가목)."},{"번호":2,"판정":"옳음","설명":"동의 철회는 허가신청서를 제출하기 전까지 서면으로 할 수 있다(영 제75조제3항)."},{"번호":3,"판정":"틀림","설명":"기존 건축물이 14층 이하이면 2개 층까지만 증축할 수 있다(영 제13조제1항제2호). 3개 층은 15층 이상일 때다."},{"번호":4,"판정":"옳음","설명":"리모델링주택조합의 허가 동의 비율은 단지 전체 75퍼센트 이상, 각 동별 50퍼센트 이상이다(영 별표 4 제1호나목)."},{"번호":5,"판정":"옳음","설명":"대통령령이 정한 세대수는 50세대이고, 그 이상 증가하는 세대수 증가형 리모델링은 시·군·구도시계획위원회 심의를 거친다(법 제66조제6항, 영 제76조제2항)."}],"개념":[{"종류":"표","제목":"리모델링 동의 비율(조합 설립인가와 허가의 차이)","머리":["단계·주체","범위","동의 비율","근거"],"행":[["조합 설립인가","주택단지 전체","구분소유자와 의결권의 각 3분의 2 이상 결의 + 각 동의 구분소유자와 의결권의 각 과반수 결의","법 제11조제3항제1호"],["조합 설립인가","동","그 동의 구분소유자와 의결권의 각 3분의 2 이상 결의","법 제11조제3항제2호"],["리모델링 허가(조합)","주택단지 전체","구분소유자와 의결권의 각 75퍼센트 이상 + 각 동별 각 50퍼센트 이상","영 별표 4 제1호나목"],["리모델링 허가(조합)","동","그 동의 구분소유자와 의결권의 각 75퍼센트 이상","영 별표 4 제1호나목"],["리모델링 허가(입주자대표회의)","주택단지","소유자 전원 동의","영 별표 4 제1호다목"],["리모델링 허가(입주자 등)","-","입주자 전체 동의","영 별표 4 제1호가목"]]},{"종류":"흐름","제목":"증축형 리모델링의 안전진단과 안전성 검토","단계":[{"이름":"안전진단 요청","설명":"증축형 리모델링을 하려는 자가 시장·군수·구청장에게 요청한다(법 제68조제1항)."},{"이름":"안전진단 실시","설명":"시장·군수·구청장이 안전진단전문기관, 국토안전관리원, 한국건설기술연구원 등에 의뢰한다. 리모델링을 하려는 자가 추천한 건축구조기술사와 함께 실시한다(법 제68조제2항, 영 제78조제1항)."},{"이름":"증축 가능 여부 통보","설명":"결과보고서와 리모델링 기본계획을 고려해 시장·군수·구청장이 요청자에게 통보한다. 구조 안전에 위험이 있어 재건축이 필요하다고 결정된 건축물은 증축형 리모델링을 할 수 없다(법 제68조제3항, 영 제78조제4항)."},{"이름":"전문기관 안전성 검토","설명":"수직증축형은 건축위원회 심의 요청 시 국토안전관리원 또는 한국건설기술연구원에 의뢰한다. 검토기간은 의뢰일부터 30일이고 20일 범위에서 한 차례 연장할 수 있다(법 제69조, 영 제79조)."},{"이름":"허가 후 상세 안전진단","설명":"수직증축형을 허가한 후 구조안전성 상세 확인을 위해 안전진단을 다시 실시한다(법 제68조제4항)."}]}],"함정":"수직증축 층수는 기존 건축물 층수가 15층 이상이면 3개 층, 14층 이하이면 2개 층이다. 리모델링주택조합의 설립인가 동의(3분의 2, 과반수)와 허가 동의(75퍼센트, 50퍼센트)는 서로 다른 단계의 기준이다. 세대수 증가형 리모델링은 기존 세대수의 15퍼센트 이내이고, 증축 리모델링 대상은 사용검사일 등으로부터 15년이 지난 공동주택이다(조례로 15년 이상 20년 미만의 연수를 정할 수 있다. 법 제2조제25호)."}},{"i":"S5-2-1-공법-37","r":"S5","g":2,"c":2,"n":77,"s":"공법","q":"주택법령상 투기과열지구 및 조정대상지역에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["시·도지사는 주거정책심의위원회의 심의를 거쳐 조정대상지역을 지정할 수 있다.","국토교통부장관은 주택의 분양·매매 등 거래가 위축될 우려가 있는 지역을 투기과열지구로 지정할 수 있다.","투기과열지구 지정의 해제를 요청받은 국토교통부장관 또는 시·도지사는 요청받은 날부터 60일 이내에 해제 여부를 결정하여 통보하여야 한다.","국토교통부장관이 투기과열지구를 지정할 때에는 미리 해당 시·도지사와 협의하여야 한다.","투기과열지구로 지정된 지역의 시장·군수·구청장은 지정 사유가 없어졌다고 인정하는 경우 국토교통부장관 또는 시·도지사에게 지정의 해제를 요청할 수 있다."],"a":[5],"L":"공5-3","o":"변형","x":{"한줄":"투기과열지구 지정 사유가 없어졌다고 인정되면 해당 지역의 시·도지사, 시장, 군수, 구청장이 해제를 요청할 수 있다.","근거":[{"법령":"주택법","조문":"법 제63조제7항·제8항","원문":"⑦ 투기과열지구로 지정된 지역의 시ㆍ도지사, 시장, 군수 또는 구청장은 투기과열지구 지정 후 해당 지역의 주택가격이 안정되는 등 지정 사유가 없어졌다고 인정되는 경우에는 국토교통부장관 또는 시ㆍ도지사에게 투기과열지구 지정의 해제를 요청할 수 있다.\n⑧ 제7항에 따라 투기과열지구 지정의 해제를 요청받은 국토교통부장관 또는 시ㆍ도지사는 요청받은 날부터 40일 이내에 주거정책심의위원회의 심의를 거쳐 투기과열지구 지정의 해제 여부를 결정하여 그 투기과열지구를 관할하는 지방자치단체의 장에게 심의결과를 통보하여야 한다."},{"법령":"주택법","조문":"법 제63조제5항","원문":"⑤ 제1항에 따라 국토교통부장관이 투기과열지구를 지정하거나 해제할 경우에는 미리 시ㆍ도지사의 의견을 듣고 그 의견에 대한 검토의견을 회신하여야 하며, 시ㆍ도지사가 투기과열지구를 지정하거나 해제할 경우에는 국토교통부장관과 협의하여야 한다."},{"법령":"주택법","조문":"법 제63조의2제1항","원문":"① 국토교통부장관은 다음 각 호의 어느 하나에 해당하는 지역으로서 대통령령으로 정하는 기준을 충족하는 지역을 주거정책심의위원회의 심의를 거쳐 조정대상지역(이하 \"조정대상지역\"이라 한다)으로 지정할 수 있다. 이 경우 제1호에 해당하는 조정대상지역은 그 지정 목적을 달성할 수 있는 최소한의 범위에서 시ㆍ군ㆍ구 또는 읍ㆍ면ㆍ동의 지역 단위로 지정하되, 택지개발지구(「택지개발촉진법」 제2조제3호에 따른 택지개발지구를 말한다) 등 해당 지역 여건을 고려하여 지정 단위를 조정할 수 있다.\n1. 주택가격, 청약경쟁률, 분양권 전매량 및 주택보급률 등을 고려하였을 때 주택 분양 등이 과열되어 있거나 과열될 우려가 있는 지역\n2. 주택가격, 주택거래량, 미분양주택의 수 및 주택보급률 등을 고려하여 주택의 분양ㆍ매매 등 거래가 위축되어 있거나 위축될 우려가 있는 지역"}],"선지":[{"번호":1,"판정":"틀림","설명":"조정대상지역은 국토교통부장관이 주거정책심의위원회의 심의를 거쳐 지정한다(법 제63조의2제1항). 시·도지사는 지정권자가 아니다."},{"번호":2,"판정":"틀림","설명":"거래가 위축될 우려가 있는 지역은 조정대상지역 지정 대상이다(법 제63조의2제1항제2호). 투기과열지구는 투기가 성행하거나 성행할 우려가 있는 지역이다(법 제63조제2항)."},{"번호":3,"판정":"틀림","설명":"해제 요청을 받은 날부터 40일 이내에 주거정책심의위원회 심의를 거쳐 결정하고 통보한다(법 제63조제8항)."},{"번호":4,"판정":"틀림","설명":"국토교통부장관이 지정·해제할 때에는 미리 시·도지사의 의견을 듣고 그 의견에 대한 검토의견을 회신한다. 시·도지사가 지정·해제할 때 국토교통부장관과 협의한다(법 제63조제5항)."},{"번호":5,"판정":"옳음","설명":"지정 사유가 없어졌다고 인정되는 경우 지정 지역의 시·도지사, 시장, 군수, 구청장이 해제를 요청할 수 있다(법 제63조제7항)."}],"개념":[{"종류":"비교","제목":"투기과열지구와 조정대상지역","왼쪽":{"이름":"투기과열지구(법 제63조)","항목":["지정권자: 국토교통부장관 또는 시·도지사(주거정책심의위원회 심의)","지정 대상: 주택가격 안정을 위해 필요한 지역. 투기가 성행하거나 성행할 우려가 있는 곳","지정 단위: 시·군·구 또는 읍·면·동","국토교통부장관은 지정·해제 시 시·도지사 의견 청취, 시·도지사는 장관과 협의","해제 요청: 지정 지역의 시·도지사·시장·군수·구청장. 요청일부터 40일 이내 결정","재검토: 국토교통부장관이 반기마다 유지 여부 재검토"]},"오른쪽":{"이름":"조정대상지역(법 제63조의2)","항목":["지정권자: 국토교통부장관(주거정책심의위원회 심의). 미리 시·도지사 의견 청취","지정 대상: 과열 우려 지역, 거래 위축 우려 지역","과열 지역은 시·군·구 또는 읍·면·동 단위로 지정","해제: 유지할 필요가 없다고 판단되면 주거정책심의위원회 심의를 거쳐 해제","해제 요청: 지정 지역의 시·도지사 또는 시장·군수·구청장이 국토교통부장관에게","재검토: 국토교통부장관이 반기마다 유지 여부 재검토"]}},{"종류":"표","제목":"지정기준(영 제72조의2, 제72조의3)","머리":["구분","기준"],"행":[["투기과열지구","직전 2개월 월별 평균 청약경쟁률이 모두 5대 1 초과(국민주택규모는 10대 1 초과). 또는 분양실적이 전달보다 30퍼센트 이상 감소하는 등 공급 위축. 또는 신도시 개발·전매행위 성행 등으로 시·도의 주택보급률 또는 자가주택비율이 전국 평균 이하 등"],["조정대상지역(과열)","직전월부터 3개월간 주택가격상승률이 시·도 소비자물가상승률의 1.3배 초과, 그리고 청약경쟁률 5대 1(국민주택규모 10대 1) 초과 또는 분양권 전매거래량 30퍼센트 이상 증가 또는 시·도 주택보급률·자가주택비율이 전국 평균 이하 중 하나"],["조정대상지역(위축)","직전월부터 6개월간 평균 주택가격상승률이 마이너스 1퍼센트 이하, 그리고 3개월 연속 주택매매거래량 20퍼센트 이상 감소 또는 평균 미분양주택 수가 직전 연도 같은 기간의 2배 이상 또는 시·도 주택보급률·자가주택비율이 전국 평균 초과 중 하나"]]}],"함정":"조정대상지역은 시·도지사가 지정하지 못하고 국토교통부장관만 지정한다. 거래 위축 지역은 투기과열지구가 아니라 조정대상지역 사유다. 해제 요청 처리기한은 40일이다."}},{"i":"S5-2-1-공법-38","r":"S5","g":2,"c":2,"n":78,"s":"공법","q":"주택법령상 주택의 공급에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시장·군수·구청장은 사업주체로부터 받은 마감자재 목록표와 영상물 등을 사용검사가 있은 날부터 2년 이상 보관하여야 하며, 입주자가 열람을 요구하는 경우 이를 공개하여야 한다.","사업주체가 부득이한 사유로 마감자재 목록표의 마감자재와 다르게 시공·설치하려는 경우에는 당초의 마감자재와 같은 질 이상으로 설치하여야 한다.","사업주체가 마감자재 목록표의 자재와 다른 마감자재를 시공·설치하려는 경우에는 그 사실을 입주예정자에게 알려야 한다.","사업주체가 일반인에게 공급하는 공동주택 중 공공택지에서 공급하는 도시형 생활주택에는 분양가상한제가 적용된다.","사업주체는 분양가상한제 적용주택으로서 공공택지에서 공급하는 주택에 대하여 입주자모집 승인을 받았을 때에는 입주자 모집공고에 택지비, 공사비, 간접비 등의 분양가격을 공시하여야 한다."],"a":[4],"L":"공5-3","o":"변형","x":{"한줄":"도시형 생활주택은 공공택지에서 공급하더라도 분양가상한제 적용이 제외된다.","근거":[{"법령":"주택법","조문":"법 제57조제1항·제2항제1호","원문":"① 사업주체가 제54조에 따라 일반인에게 공급하는 공동주택 중 다음 각 호의 어느 하나에 해당하는 지역에서 공급하는 주택의 경우에는 이 조에서 정하는 기준에 따라 산정되는 분양가격 이하로 공급(이에 따라 공급되는 주택을 \"분양가상한제 적용주택\"이라 한다. 이하 같다)하여야 한다.\n1. 공공택지\n② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 제1항을 적용하지 아니한다.\n1. 도시형 생활주택"},{"법령":"주택법","조문":"법 제54조제5항~제7항","원문":"⑤ 시장ㆍ군수ㆍ구청장은 제3항에 따라 받은 마감자재 목록표와 영상물 등을 제49조제1항에 따른 사용검사가 있은 날부터 2년 이상 보관하여야 하며, 입주자가 열람을 요구하는 경우에는 이를 공개하여야 한다.\n⑥ 사업주체가 마감자재 생산업체의 부도 등으로 인한 제품의 품귀 등 부득이한 사유로 인하여 제15조에 따른 사업계획승인 또는 마감자재 목록표의 마감자재와 다르게 마감자재를 시공ㆍ설치하려는 경우에는 당초의 마감자재와 같은 질 이상으로 설치하여야 한다.\n⑦ 사업주체가 제6항에 따라 마감자재 목록표의 자재와 다른 마감자재를 시공ㆍ설치하려는 경우에는 그 사실을 입주예정자에게 알려야 한다."},{"법령":"주택법","조문":"법 제57조제5항","원문":"⑤ 사업주체는 분양가상한제 적용주택으로서 공공택지에서 공급하는 주택에 대하여 입주자모집 승인을 받았을 때에는 입주자 모집공고에 다음 각 호[국토교통부령으로 정하는 세분류(細分類)를 포함한다]에 대하여 분양가격을 공시하여야 한다.\n1. 택지비\n2. 공사비\n3. 간접비"}],"선지":[{"번호":1,"판정":"옳음","설명":"마감자재 목록표와 영상물 등은 사용검사일부터 2년 이상 보관하고 입주자의 열람 요구 시 공개한다(법 제54조제5항)."},{"번호":2,"판정":"옳음","설명":"부득이한 사유로 다르게 시공할 때는 당초 자재와 같은 질 이상으로 설치한다(법 제54조제6항)."},{"번호":3,"판정":"옳음","설명":"다른 마감자재를 설치하려는 경우 입주예정자에게 그 사실을 알려야 한다(법 제54조제7항)."},{"번호":4,"판정":"틀림","설명":"도시형 생활주택은 분양가격 제한의 적용 제외 대상이다(법 제57조제2항제1호). 공공택지에서 공급해도 적용되지 않는다."},{"번호":5,"판정":"옳음","설명":"공공택지의 분양가상한제 적용주택은 입주자 모집공고에 택지비, 공사비, 간접비 등 분양가격을 공시한다(법 제57조제5항)."}],"개념":[{"종류":"표","제목":"분양가상한제 적용 지역과 제외 대상(법 제57조제1항·제2항)","머리":["구분","내용"],"행":[["적용 지역 1","공공택지"],["적용 지역 2","공공택지 외의 택지로서 주택가격 상승 우려가 있어 국토교통부장관이 주거정책심의위원회 심의를 거쳐 지정하는 지역"],["제외 1","도시형 생활주택"],["제외 2","경제자유구역에서 외자유치 촉진과 관련해 경제자유구역위원회가 제한을 적용하지 않기로 의결한 공동주택"],["제외 3","관광특구의 50층 이상 또는 높이 150미터 이상 공동주택"],["제외 4","한국토지주택공사 또는 지방공사가 시행자로 참여하는 등 공공성 요건을 충족하는 정비사업·소규모주택정비사업 주택"],["제외 5","주거환경개선사업, 공공재개발사업, 주거재생혁신지구 혁신지구재생사업, 도심 공공주택 복합사업, 쪽방 밀집지역 공공주택사업의 주택"]]},{"종류":"표","제목":"마감자재 목록표 관리(법 제54조제3항~제7항)","머리":["항","내용"],"행":[["제3항","입주자 모집승인 신청 시 견본주택에 사용되는 마감자재의 규격·성능·재질 목록표와 견본주택 각 실 영상물 등을 승인권자에게 제출"],["제4항","주택공급계약 체결 시 입주예정자에게 마감자재 목록표 제공(입주자 모집공고에 표시한 경우 제외)"],["제5항","시장·군수·구청장은 사용검사가 있은 날부터 2년 이상 보관, 입주자 열람 요구 시 공개"],["제6항","부득이한 사유(생산업체 부도 등)로 달리 시공할 때는 당초 자재와 같은 질 이상"],["제7항","다른 자재를 시공·설치하려면 입주예정자에게 알려야 함"]]}],"함정":"분양가상한제는 공공택지에서도 도시형 생활주택에는 적용되지 않는다. 마감자재는 같은 질 이상이어야 하고 이하로 바꿀 수 없다. 보관 기간은 사용검사일부터 2년 이상이다."}},{"i":"S5-2-1-공법-39","r":"S5","g":2,"c":2,"n":79,"s":"공법","q":"농지법령상 농지를 개량하기 위하여 성토를 하려는 자가 농지개량행위의 신고를 하지 않아도 되는 경미한 행위에 관한 내용이다. ( )에 들어갈 숫자로 옳은 것은? (단, 조례는 고려하지 않음)","b":"○ 면적(성토가 이루어지는 해당 필지의 총면적을 말한다) ( ㄱ )천제곱미터 이하인 농지에 대한 성토\n○ 높이(성토가 이루어지는 해당 필지에서 최근 1년간 성토한 높이를 합산한 것을 말한다) ( ㄴ )센티미터 이내의 성토","bs":"글자","img":[],"ch":["ㄱ: 1, ㄴ: 50","ㄱ: 1, ㄴ: 60","ㄱ: 3, ㄴ: 50","ㄱ: 3 , ㄴ: 60","ㄱ: 3, ㄴ: 70"],"a":[1],"L":"공6-1","o":"기출","x":{"한줄":"성토 면적 1천제곱미터 이하, 성토 높이 50센티미터 이내이면 농지개량행위 신고를 하지 않아도 된다.","근거":[{"법령":"농지법 시행령","조문":"영 제59조의2","원문":"제59조의2(신고를 하지 않아도 되는 경미한 행위) 법 제41조의3제1항제4호에서 \"대통령령으로 정하는 경미한 행위\"란 다음 각 호의 어느 하나에 해당하는 행위를 말한다. 다만, 다음 각 호의 범위에서 시ㆍ군ㆍ자치구의 조례로 따로 정하는 경우에는 그에 따른다.\n1. 면적(성토가 이루어지는 해당 필지의 총면적을 말한다) 1천제곱미터 이하인 농지에 대한 성토\n2. 면적(절토가 이루어지는 해당 필지의 총면적을 말한다) 1천제곱미터 이하인 농지에 대한 절토\n3. 높이(성토가 이루어지는 해당 필지에서 최근 1년간 성토한 높이를 합산한 것을 말한다) 50센티미터 이내의 성토\n4. 깊이(절토가 이루어지는 해당 필지에서 최근 1년간 절토한 깊이를 합산한 것을 말한다) 50센티미터 이내의 절토"},{"법령":"농지법","조문":"법 제41조의3제1항","원문":"① 농지를 개량하려는 자 중 성토 또는 절토를 하려는 자는 농림축산식품부령으로 정하는 바에 따라 시장ㆍ군수 또는 자치구구청장에게 신고하여야 하며, 신고한 사항을 변경하려는 경우에도 또한 같다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.\n4. 대통령령으로 정하는 경미한 행위인 경우"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 1천제곱미터, ㄴ은 50센티미터다. 영 제59조의2제1호·제3호와 일치하는 조합이다."},{"번호":2,"판정":"-","설명":"ㄱ 1천제곱미터는 맞으나 ㄴ이 60센티미터가 아니라 50센티미터다(영 제59조의2제3호)."},{"번호":3,"판정":"-","설명":"ㄱ이 3천제곱미터가 아니라 1천제곱미터다(영 제59조의2제1호). ㄴ 50센티미터만 맞다."},{"번호":4,"판정":"-","설명":"ㄱ이 3천제곱미터가 아니라 1천제곱미터이고 ㄴ이 60센티미터가 아니라 50센티미터다. 둘 다 틀렸다."},{"번호":5,"판정":"-","설명":"ㄱ이 3천제곱미터가 아니라 1천제곱미터이고 ㄴ이 70센티미터가 아니라 50센티미터다. 둘 다 틀렸다."}],"개념":[{"종류":"비교","제목":"신고하지 않아도 되는 경미한 행위(영 제59조의2)","왼쪽":{"이름":"성토","항목":["면적: 성토가 이루어지는 해당 필지의 총면적 1천제곱미터 이하","높이: 해당 필지에서 최근 1년간 성토한 높이를 합산해 50센티미터 이내"]},"오른쪽":{"이름":"절토","항목":["면적: 절토가 이루어지는 해당 필지의 총면적 1천제곱미터 이하","깊이: 해당 필지에서 최근 1년간 절토한 깊이를 합산해 50센티미터 이내"]}},{"종류":"표","제목":"농지개량행위 신고 제도(법 제41조의3 등)","머리":["항목","내용","근거"],"행":[["신고 대상","농지를 개량하려는 자 중 성토 또는 절토를 하려는 자. 변경할 때도 신고","법 제41조의3제1항"],["신고 면제","개발행위허가를 받은 경우, 국가·지방자치단체의 공익사업, 재해복구·재난수습 응급조치, 경미한 행위","법 제41조의3제1항 각 호"],["신고 서류","사업계획서, 소유권 또는 사용권 입증서류, 농지개량 기준에 적합한 흙임을 증명하는 서류(성토의 경우)","규칙 제52조의3제1항"],["수리","내용을 검토해 이 법에 적합하면 신고를 수리","법 제41조의3제2항"],["위반 시 원상회복","신고 없이 성토·절토하면 원상회복명령, 불이행 시 대집행","법 제42조"],["위반 시 벌칙","3년 이하의 징역 또는 3천만원 이하의 벌금(신고·변경신고 위반, 농지개량 기준 위반)","법 제60조제4호·제5호"]]}],"함정":"면적 기준은 1천제곱미터, 높이·깊이 기준은 50센티미터다. 성토와 절토는 같은 숫자를 쓴다. 높이는 필지에서 최근 1년간 합산한 값이다. 시·군·자치구 조례로 달리 정할 수 있으나 이 문항은 조례를 고려하지 않는다."}},{"i":"S5-2-1-공법-40","r":"S5","g":2,"c":2,"n":80,"s":"공법","q":"농지법령상 유휴농지에 대한 대리경작자의 지정에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["지력의 증진이나 토양의 개량ㆍ보전을 위하여 필요한 기간 동안 휴경하는 농지에 대하여도 대리경작자를 지정할 수 있다.","대리경작자 지정은 유휴농지를 경작하려는 농업인 또는 농업법인의 신청이 있을 때에만 할 수 있고, 직권으로는 할 수 없다.","대리경작자가 경작을 게을리하는 경우에는 대리경작 기간이 끝나기 전이라도 대리경작자 지정을 해지할 수 있다.","대리경작 기간은 3년이고, 이와 다른 기간을 따로 정할 수 없다.","농지 소유권자를 대신할 대리경작자만 지정할 수 있고, 농지 임차권자를 대신할 대리경작자를 지정할 수는 없다."],"a":[3],"L":"공6-1","o":"기출","x":{"한줄":"대리경작자가 경작을 게을리하면 대리경작 기간이 끝나기 전이라도 지정을 해지할 수 있다.","근거":[{"법령":"농지법","조문":"법 제20조제1항·제3항·제6항","원문":"①시장(구를 두지 아니한 시의 시장을 말한다. 이하 이 조에서 같다)ㆍ군수 또는 구청장은 유휴농지(농작물 경작이나 다년생식물 재배에 이용되지 아니하는 농지로서 대통령령으로 정하는 농지를 말한다. 이하 같다)에 대하여 대통령령으로 정하는 바에 따라 그 농지의 소유권자나 임차권자를 대신하여 농작물을 경작할 자(이하 \"대리경작자\"라 한다)를 직권으로 지정하거나 농림축산식품부령으로 정하는 바에 따라 유휴농지를 경작하려는 자의 신청을 받아 대리경작자를 지정할 수 있다.\n③대리경작 기간은 따로 정하지 아니하면 3년으로 한다.\n⑥시장ㆍ군수 또는 구청장은 다음 각 호의 어느 하나에 해당하면 대리경작 기간이 끝나기 전이라도 대리경작자 지정을 해지할 수 있다.\n2. 대리경작자가 경작을 게을리하는 경우"},{"법령":"농지법 시행령","조문":"영 제18조제1호","원문":"제18조(유휴농지의 범위) 법 제20조제1항에서 \"대통령령으로 정하는 농지\"란 다음 각 호의 어느 하나에 해당하지 아니하는 농지를 말한다.\n1. 지력의 증진이나 토양의 개량ㆍ보전을 위하여 필요한 기간 동안 휴경하는 농지"}],"선지":[{"번호":1,"판정":"틀림","설명":"지력 증진이나 토양 개량·보전을 위해 필요한 기간 휴경하는 농지는 유휴농지에서 제외된다(영 제18조제1호). 대리경작자를 지정할 수 없다."},{"번호":2,"판정":"틀림","설명":"대리경작자는 직권으로 지정하거나 유휴농지를 경작하려는 자의 신청을 받아 지정할 수 있다(법 제20조제1항)."},{"번호":3,"판정":"옳음","설명":"대리경작자가 경작을 게을리하면 기간이 끝나기 전이라도 지정을 해지할 수 있다(법 제20조제6항제2호)."},{"번호":4,"판정":"틀림","설명":"대리경작 기간은 따로 정하지 않으면 3년이다(법 제20조제3항). 다른 기간을 정할 수 있다."},{"번호":5,"판정":"틀림","설명":"대리경작자는 소유권자나 임차권자를 대신하여 경작한다(법 제20조제1항). 임차권자도 대신할 수 있다."}],"개념":[{"종류":"흐름","제목":"대리경작자 지정부터 해지까지","단계":[{"이름":"지정","설명":"시장·군수·구청장이 유휴농지에 대해 직권으로 지정하거나 경작하려는 자의 신청을 받아 지정한다. 소유권자나 임차권자를 대신하는 지정이다(법 제20조제1항)."},{"이름":"예고·이의","설명":"지정 전에 소유권자 또는 임차권자에게 예고한다. 이의는 예고를 받은 날부터 10일 이내에 신청하고 시장등은 7일 이내에 심사 결과를 알린다(법 제20조제2항, 영 제20조)."},{"이름":"지정통지","설명":"대리경작자와 소유권자 또는 임차권자에게 지정통지서를 보낸다(법 제20조제2항)."},{"이름":"대리경작 기간","설명":"따로 정하지 않으면 3년이다(법 제20조제3항)."},{"이름":"토지사용료","설명":"수확량의 100분의 10을 소유권자나 임차권자에게 지급한다. 수확일부터 2개월 이내에 지급하고 늦으면 연 12퍼센트를 가산한다(법 제20조제4항, 규칙 제18조). 수령 거부나 지급 곤란 시 공탁할 수 있다."},{"이름":"지정 중지","설명":"소유권자 또는 임차권자가 스스로 경작하려면 대리경작 기간이 끝나기 3개월 전까지 중지를 신청한다. 시장등은 신청일부터 1개월 이내에 알린다(법 제20조제5항)."},{"이름":"지정 해지","설명":"소유권자·임차권자의 해지신청, 대리경작자의 경작 태만, 토지사용료 미지급·미공탁, 대리경작자의 해지신청 중 하나이면 기간 중에도 해지할 수 있다(법 제20조제6항, 영 제21조)."}]},{"종류":"표","제목":"유휴농지에서 제외되는 농지(영 제18조)","머리":["호","제외 농지"],"행":[["1","지력 증진이나 토양 개량·보전을 위해 필요한 기간 휴경하는 농지"],["2","연작 피해가 예상되는 작물의 경작·재배 전후에 지력 증진·회복을 위해 필요한 기간 휴경하는 농지"],["3","농지전용허가를 받거나 농지전용협의를 거친 농지"],["4","농지전용신고를 한 농지"],["5","농지의 타용도 일시사용허가를 받거나 협의를 거친 농지"],["6","농지의 타용도 일시사용신고를 하거나 협의를 거친 농지"],["7","그 밖에 농림축산식품부장관이 정하는 제1호부터 제6호까지에 준하는 농지"]]}],"함정":"휴경 중인 농지는 유휴농지가 아니다. 직권 지정도 가능하다. 대리경작 기간 3년은 따로 정하지 않은 경우의 기본값이고, 소유권자뿐 아니라 임차권자를 대신하는 지정도 된다."}},{"i":"S5-2-2-공시법-01","r":"S5","g":3,"c":2,"n":1,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지목의 구분에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["온수ㆍ약수ㆍ석유류 등을 일정한 장소로 운송하는 송수관ㆍ송유관 및 저장시설의 부지는 “광천지”로 한다.","사과ㆍ배ㆍ밤ㆍ호두ㆍ귤나무 등 과수류를 집단적으로 재배하는 토지와 이에 접속된 주거용 건축물의 부지는 “과수원”으로 한다.","종교용지에 있는 유적ㆍ고적ㆍ기념물 등을 보호하기 위하여 구획된 토지는 “사적지”로 한다.","물을 정수하여 공급하기 위한 취수ㆍ저수ㆍ도수(導水)ㆍ정수ㆍ송수 및 배수 시설의 부지 및 이에 접속된 부속시설물의 부지는 “수도용지”로 한다.","교통 운수를 위하여 일정한 궤도 등의 설비와 형태를 갖추어 이용되는 토지와 이에 접속된 차고ㆍ발전시설 등 부속시설물의 부지는 “도로”로 한다."],"a":[4],"L":"시1-1","o":"기출","x":{"한줄":"취수ㆍ저수ㆍ도수ㆍ정수ㆍ송수ㆍ배수 시설의 부지와 이에 접속된 부속시설물의 부지가 수도용지다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제21호","원문":"21. 수도용지\n물을 정수하여 공급하기 위한 취수ㆍ저수ㆍ도수(導水)ㆍ정수ㆍ송수 및 배수 시설의 부지 및 이에 접속된 부속시설물의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제6호","원문":"6. 광천지\n지하에서 온수ㆍ약수ㆍ석유류 등이 용출되는 용출구(湧出口)와 그 유지(維持)에 사용되는 부지. 다만, 온수ㆍ약수ㆍ석유류 등을 일정한 장소로 운송하는 송수관ㆍ송유관 및 저장시설의 부지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제3호","원문":"3. 과수원\n사과ㆍ배ㆍ밤ㆍ호두ㆍ귤나무 등 과수류를 집단적으로 재배하는 토지와 이에 접속된 저장고 등 부속시설물의 부지. 다만, 주거용 건축물의 부지는 \"대\"로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제26호","원문":"26. 사적지\n국가유산으로 지정된 역사적인 유적ㆍ고적ㆍ기념물 등을 보존하기 위하여 구획된 토지. 다만, 학교용지ㆍ공원ㆍ종교용지 등 다른 지목으로 된 토지에 있는 유적ㆍ고적ㆍ기념물 등을 보호하기 위하여 구획된 토지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제15호","원문":"15. 철도용지\n교통 운수를 위하여 일정한 궤도 등의 설비와 형태를 갖추어 이용되는 토지와 이에 접속된 역사(驛舍)ㆍ차고ㆍ발전시설 및 공작창(工作廠) 등 부속시설물의 부지"}],"선지":[{"번호":1,"판정":"틀림","설명":"송수관ㆍ송유관 및 저장시설의 부지는 광천지에서 빠진다. 광천지는 용출구와 그 유지에 사용되는 부지만 해당한다(영 제58조제6호 단서)."},{"번호":2,"판정":"틀림","설명":"과수원에 접속된 주거용 건축물의 부지는 “대”다. 과수원에 포함되는 부속시설물은 저장고 등이다(영 제58조제3호 단서)."},{"번호":3,"판정":"틀림","설명":"종교용지 등 다른 지목으로 된 토지에 있는 유적ㆍ고적ㆍ기념물 보호 구획 토지는 사적지에서 제외된다. 그 토지는 종교용지로 남는다(영 제58조제26호 단서)."},{"번호":4,"판정":"옳음","설명":"수도용지의 정의 그대로다(영 제58조제21호)."},{"번호":5,"판정":"틀림","설명":"궤도 등의 설비를 갖춘 토지와 접속된 차고ㆍ발전시설 등의 부지는 “철도용지”다. 도로는 보행이나 차량운행에 필요한 설비ㆍ형태를 갖춘 토지다(영 제58조제14호, 제15호)."}],"개념":[{"종류":"표","제목":"지목 정의의 단서ㆍ제외 규정","머리":["지목","원칙","단서ㆍ제외"],"행":[["과수원","과수류 집단 재배 토지와 접속된 저장고 등 부속시설물의 부지","주거용 건축물의 부지는 대"],["목장용지","초지 조성 토지, 가축 사육 축사 등의 부지, 접속된 부속시설물의 부지","주거용 건축물의 부지는 대"],["광천지","온수ㆍ약수ㆍ석유류 등의 용출구와 그 유지에 사용되는 부지","송수관ㆍ송유관 및 저장시설의 부지 제외"],["사적지","국가유산으로 지정된 유적ㆍ고적ㆍ기념물 등을 보존하기 위하여 구획된 토지","학교용지ㆍ공원ㆍ종교용지 등 다른 지목 토지에 있는 것 제외"],["묘지","시체ㆍ유골이 매장된 토지, 묘지공원, 봉안시설과 접속된 부속시설물의 부지","묘지 관리를 위한 건축물의 부지는 대"],["주차장","독립적 시설을 갖춘 주차 부지, 주차전용 건축물과 접속된 부속시설물의 부지","노상주차장, 부설주차장, 자동차 판매 목적의 물류장ㆍ야외전시장 제외"]]},{"종류":"표","제목":"교통ㆍ수로 관련 지목 구분","머리":["지목","해당 토지","제외 또는 부속시설"],"행":[["도로","일반 공중의 교통 운수를 위해 보행이나 차량운행에 필요한 설비ㆍ형태를 갖춘 토지, 2필지 이상에 진입하는 통로, 고속도로 휴게소 부지","아파트ㆍ공장 등 단일 용도 단지 안의 통로 제외"],["철도용지","궤도 등의 설비와 형태를 갖추어 이용되는 토지","접속된 역사ㆍ차고ㆍ발전시설ㆍ공작창 부지 포함"],["수도용지","취수ㆍ저수ㆍ도수ㆍ정수ㆍ송수ㆍ배수 시설의 부지","접속된 부속시설물의 부지 포함"],["제방","방조제ㆍ방수제ㆍ방사제ㆍ방파제 등의 부지","-"],["하천","자연의 유수가 있거나 있을 것으로 예상되는 토지","-"],["구거","인공 수로ㆍ둑ㆍ부속시설물의 부지, 소규모 수로부지","-"]]}],"함정":"①②③은 지목 정의의 단서(제외) 규정을 반대로 읽게 만든 선지다. 주거용 건축물의 부지는 과수원ㆍ목장용지에서 모두 대로 나간다. ⑤는 철도용지의 정의에 지목명만 도로로 바꿔 넣었다."}},{"i":"S5-2-2-공시법-02","r":"S5","g":3,"c":2,"n":2,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지목의 구분과 설정방법에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["1필지가 둘 이상의 용도로 활용되는 경우에는 주된 용도에 따라 지목을 설정한다.","사과ㆍ배ㆍ귤나무 등 과수류를 집단적으로 재배하는 토지에 접속된 주거용 건축물의 부지는 “과수원”으로 한다.","묘지의 관리를 위한 건축물의 부지는 “묘지”로 한다.","토지가 일시적 또는 임시적인 용도로 사용될 때에는 그 용도에 따라 지목을 변경하여야 한다.","자동차 등의 판매 목적으로 설치된 야외전시장의 부지는 “주차장”으로 한다."],"a":[1],"L":"시1-1","o":"변형","x":{"한줄":"1필지가 둘 이상의 용도로 쓰이면 주된 용도에 따라 지목을 하나 설정한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제59조","원문":"제59조(지목의 설정방법 등)\n① 법 제67조제1항에 따른 지목의 설정은 다음 각 호의 방법에 따른다.\n  1. 필지마다 하나의 지목을 설정할 것\n  2. 1필지가 둘 이상의 용도로 활용되는 경우에는 주된 용도에 따라 지목을 설정할 것\n② 토지가 일시적 또는 임시적인 용도로 사용될 때에는 지목을 변경하지 아니한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제3호","원문":"3. 과수원\n사과ㆍ배ㆍ밤ㆍ호두ㆍ귤나무 등 과수류를 집단적으로 재배하는 토지와 이에 접속된 저장고 등 부속시설물의 부지. 다만, 주거용 건축물의 부지는 \"대\"로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제27호","원문":"27. 묘지\n사람의 시체나 유골이 매장된 토지, 「도시공원 및 녹지 등에 관한 법률」에 따른 묘지공원으로 결정ㆍ고시된 토지 및 「장사 등에 관한 법률」 제2조제9호에 따른 봉안시설과 이에 접속된 부속시설물의 부지. 다만, 묘지의 관리를 위한 건축물의 부지는 \"대\"로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제11호","원문":"11. 주차장\n자동차 등의 주차에 필요한 독립적인 시설을 갖춘 부지와 주차전용 건축물 및 이에 접속된 부속시설물의 부지. 다만, 다음 각 목의 어느 하나에 해당하는 시설의 부지는 제외한다.\n    나. 자동차 등의 판매 목적으로 설치된 물류장 및 야외전시장"}],"선지":[{"번호":1,"판정":"옳음","설명":"지목은 필지마다 하나만 설정하고, 용도가 둘 이상이면 주된 용도를 따른다(영 제59조제1항)."},{"번호":2,"판정":"틀림","설명":"주거용 건축물의 부지는 “대”다. 과수원은 저장고 등 부속시설물의 부지까지다(영 제58조제3호 단서)."},{"번호":3,"판정":"틀림","설명":"묘지의 관리를 위한 건축물의 부지는 “대”다(영 제58조제27호 단서)."},{"번호":4,"판정":"틀림","설명":"일시적ㆍ임시적 용도로 사용될 때에는 지목을 변경하지 않는다(영 제59조제2항)."},{"번호":5,"판정":"틀림","설명":"자동차 판매 목적의 물류장ㆍ야외전시장은 주차장에서 제외된다. 다른 지목에 속하지 않으므로 잡종지다(영 제58조제11호나목, 제28호바목)."}],"개념":[{"종류":"표","제목":"지목 설정방법 (영 제59조)","머리":["구분","내용","근거"],"행":[["필지와 지목","필지마다 하나의 지목","영 제59조제1항제1호"],["복합 용도","주된 용도에 따라 설정","영 제59조제1항제2호"],["일시적ㆍ임시적 용도","지목 변경 없음","영 제59조제2항"],["표기","지적도ㆍ임야도에는 부호로 표기","규칙 제64조"]]},{"종류":"표","제목":"단서 때문에 다른 지목이 되는 경우","머리":["토지","지목 결과","근거"],"행":[["과수원 안의 주거용 건축물 부지","대","영 제58조제3호 단서"],["목장용지 안의 주거용 건축물 부지","대","영 제58조제4호 단서"],["묘지 관리를 위한 건축물 부지","대","영 제58조제27호 단서"],["자동차 판매 목적 물류장ㆍ야외전시장","주차장에서 제외","영 제58조제11호나목"],["노상주차장ㆍ부설주차장","주차장에서 제외","영 제58조제11호가목"],["원상회복 조건으로 허가된 토취장ㆍ채석장","잡종지에서 제외","영 제58조제28호 단서"]]}],"함정":"④는 일시적 용도라는 표현에 끌려 변경한다고 읽게 만든 선지다. 일시적ㆍ임시적 용도는 지목변경 사유가 되지 않는다. ②③은 건축물 부지가 대로 나가는 단서를 놓치게 만든다."}},{"i":"S5-2-2-공시법-03","r":"S5","g":3,"c":2,"n":3,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적도의 축척이 600분의 1인 지역에서 신규등록할 1필지의 측정 면적이 928.651m²인 경우 토지대장에 등록할 면적은? (단, 다른 조건은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["928m²","928.6m²","928.65m²","928.7m²","929m²"],"a":[4],"L":"시1-2","o":"기출","x":{"한줄":"축척 600분의 1 지역은 면적을 0.1m² 단위로 정하고, 0.05m²를 넘는 끝수는 올리므로 928.651m²는 928.7m²다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제60조제1항제2호","원문":"2. 지적도의 축척이 600분의 1인 지역과 경계점좌표등록부에 등록하는 지역의 토지 면적은 제1호에도 불구하고 제곱미터 이하 한 자리 단위로 하되, 0.1제곱미터 미만의 끝수가 있는 경우 0.05제곱미터 미만일 때에는 버리고 0.05제곱미터를 초과할 때에는 올리며, 0.05제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 0.1제곱미터 미만일 때에는 0.1제곱미터로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제60조제1항제1호","원문":"1. 토지의 면적에 1제곱미터 미만의 끝수가 있는 경우 0.5제곱미터 미만일 때에는 버리고 0.5제곱미터를 초과하는 때에는 올리며, 0.5제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 1제곱미터 미만일 때에는 1제곱미터로 한다."}],"선지":[{"번호":1,"판정":"-","설명":"소수점 이하를 모두 버린 값이다. 이 지역의 등록 단위는 0.1m²다."},{"번호":2,"판정":"-","설명":"끝수 0.051m²를 버린 값이다. 0.05m²를 초과하므로 올려야 한다."},{"번호":3,"판정":"-","설명":"소수 둘째 자리까지 쓴 값이다. 등록 면적은 소수 한 자리다."},{"번호":4,"판정":"-","설명":"0.1m² 미만 끝수 0.051m²가 0.05m²를 초과하여 올린 값이다."},{"번호":5,"판정":"-","설명":"1m² 단위로 올린 값이다. 일반 지역의 처리 방법이고 600분의 1 지역에는 쓰지 않는다."}],"개념":[{"종류":"표","제목":"면적 단위와 끝수 처리 (영 제60조제1항)","머리":["지역","등록 단위","끝수 처리","최소 면적"],"행":[["일반 지역","1m²","0.5m² 미만 버림, 0.5m² 초과 올림, 0.5m²는 앞자리가 0 또는 짝수면 버림, 홀수면 올림","1m² 미만이면 1m²"],["축척 600분의 1 지역","0.1m²","0.05m² 미만 버림, 0.05m² 초과 올림, 0.05m²는 앞자리가 0 또는 짝수면 버림, 홀수면 올림","0.1m² 미만이면 0.1m²"],["경계점좌표등록부 시행 지역","0.1m²","600분의 1 지역과 같다","0.1m² 미만이면 0.1m²"],["방위각ㆍ종횡선 수치ㆍ거리 계산","구하려는 끝자리","다음 숫자가 5 미만이면 버림, 5 초과면 올림, 5이면 앞자리가 0 또는 짝수면 버림, 홀수면 올림","-"]]},{"종류":"계산","제목":"928.651m²의 끝수 처리","단계":[{"설명":"적용 규정 선택","식":"600분의 1 지역 → 0.1m² 단위","값":"영 제60조제1항제2호"},{"설명":"0.1m² 미만 끝수 구하기","식":"928.651 − 928.6","값":"0.051m²"},{"설명":"끝수와 0.05m² 비교","식":"0.051 > 0.05","값":"올림"},{"설명":"등록 면적","식":"928.6 + 0.1","값":"928.7m²"}]}],"함정":"일반 지역의 1m² 단위 규칙을 적용하면 929m²(⑤)가 나온다. 축척 600분의 1이라는 조건에서 0.1m² 단위 규칙으로 갈아타야 한다. 끝수 0.051은 0.05를 넘으므로 928.6(②)에서 멈추면 안 된다."}},{"i":"S5-2-2-공시법-04","r":"S5","g":3,"c":2,"n":4,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지상 경계의 결정기준으로 옳은 것은? (단, 지상 경계의 구획을 형성하는 구조물 등의 소유자는 같고, 다른 조건은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["연접되는 토지 간에 높낮이 차이가 없는 경우: 그 구조물 등의 하단부","도로ㆍ구거 등의 토지에 절토(땅깎기)된 부분이 있는 경우: 그 경사면의 상단부","토지가 해면 또는 수면에 접하는 경우: 최소만조위 또는 최저수위가 되는 선","연접되는 토지 간에 높낮이 차이가 있는 경우: 그 구조물 등의 상단부","공유수면매립지의 토지 중 제방 등을 토지에 편입하여 등록하는 경우: 안쪽 어깨부분"],"a":[2],"L":"시1-2","o":"변형","x":{"한줄":"도로ㆍ구거 등에 절토된 부분이 있으면 그 경사면의 상단부를 지상 경계로 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제55조제1항","원문":"① 법 제65조제1항에 따른 지상 경계의 결정기준은 다음 각 호의 구분에 따른다.\n  1. 연접되는 토지 간에 높낮이 차이가 없는 경우: 그 구조물 등의 중앙\n  2. 연접되는 토지 간에 높낮이 차이가 있는 경우: 그 구조물 등의 하단부\n  3. 도로ㆍ구거 등의 토지에 절토(땅깎기)된 부분이 있는 경우: 그 경사면의 상단부\n  4. 토지가 해면 또는 수면에 접하는 경우: 최대만조위 또는 최대만수위가 되는 선\n  5. 공유수면매립지의 토지 중 제방 등을 토지에 편입하여 등록하는 경우: 바깥쪽 어깨부분"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제55조제2항","원문":"② 지상 경계의 구획을 형성하는 구조물 등의 소유자가 다른 경우에는 제1항제1호부터 제3호까지의 규정에도 불구하고 그 소유권에 따라 지상 경계를 결정한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제65조제2항","원문":"② 지적소관청은 토지의 이동에 따라 지상경계를 새로 정한 경우에는 다음 각 호의 사항을 등록한 지상경계점등록부를 작성ㆍ관리하여야 한다.\n  1. 토지의 소재\n  2. 지번\n  3. 경계점 좌표(경계점좌표등록부 시행지역에 한정한다)\n  4. 경계점 위치 설명도\n  5. 그 밖에 국토교통부령으로 정하는 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"높낮이 차이가 없으면 구조물 등의 중앙이다(영 제55조제1항제1호). 하단부는 높낮이 차이가 있는 경우다."},{"번호":2,"판정":"옳음","설명":"절토된 부분이 있으면 경사면의 상단부다(영 제55조제1항제3호)."},{"번호":3,"판정":"틀림","설명":"해면 또는 수면에 접하면 최대만조위 또는 최대만수위가 되는 선이다(영 제55조제1항제4호)."},{"번호":4,"판정":"틀림","설명":"높낮이 차이가 있으면 구조물 등의 하단부다(영 제55조제1항제2호)."},{"번호":5,"판정":"틀림","설명":"제방 등을 편입하여 등록하는 공유수면매립지는 바깥쪽 어깨부분이다(영 제55조제1항제5호)."}],"개념":[{"종류":"표","제목":"지상 경계의 결정기준 (영 제55조제1항)","머리":["상황","경계 위치"],"행":[["연접 토지 간 높낮이 차이 없음","구조물 등의 중앙"],["연접 토지 간 높낮이 차이 있음","구조물 등의 하단부"],["도로ㆍ구거 등에 절토된 부분 있음","경사면의 상단부"],["토지가 해면 또는 수면에 접함","최대만조위 또는 최대만수위가 되는 선"],["공유수면매립지에서 제방 등을 토지에 편입하여 등록","바깥쪽 어깨부분"],["구획 구조물 등의 소유자가 서로 다름(위 1~3의 경우)","소유권에 따라 결정"]]},{"종류":"표","제목":"지상경계점등록부 등록사항","머리":["구분","등록사항","근거"],"행":[["법에서 정한 사항","토지의 소재, 지번","법 제65조제2항제1호ㆍ제2호"],["법에서 정한 사항","경계점 좌표(경계점좌표등록부 시행지역에 한정)","법 제65조제2항제3호"],["법에서 정한 사항","경계점 위치 설명도","법 제65조제2항제4호"],["규칙에서 정한 사항","공부상 지목과 실제 토지이용 지목","규칙 제60조제2항제1호"],["규칙에서 정한 사항","경계점의 사진 파일","규칙 제60조제2항제2호"],["규칙에서 정한 사항","경계점표지의 종류 및 경계점 위치","규칙 제60조제2항제3호"]]}],"함정":"중앙ㆍ하단부ㆍ상단부 세 위치를 서로 바꿔 놓는 유형이다. 높낮이 차이가 없으면 중앙, 있으면 하단부, 절토 경사면은 상단부다. ③은 최대를 최소로, ⑤는 바깥쪽을 안쪽으로 바꿨다."}},{"i":"S5-2-2-공시법-05","r":"S5","g":3,"c":2,"n":5,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 대지권 등록부의 등록사항만으로 나열된 것이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["지번, 지목","토지의 소재, 토지의 고유번호","대지권 비율, 전유부분(專有部分)의 건물표시","소유권 지분, 토지소유자가 변경된 날과 그 원인","건물의 명칭, 집합건물별 대지권등록부의 장번호"],"a":[1],"L":"시1-3","o":"기출","x":{"한줄":"대지권등록부에는 지번은 있으나 지목은 없다. 지목은 토지대장ㆍ임야대장의 등록사항이다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제71조제3항","원문":"③ 토지대장이나 임야대장에 등록하는 토지가 「부동산등기법」에 따라 대지권 등기가 되어 있는 경우에는 대지권등록부에 다음 각 호의 사항을 등록하여야 한다.\n  1. 토지의 소재\n  2. 지번\n  3. 대지권 비율\n  4. 소유자의 성명 또는 명칭, 주소 및 주민등록번호\n  5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제68조제4항","원문":"④ 법 제71조제3항제5호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다.\n  1. 토지의 고유번호\n  2. 전유부분(專有部分)의 건물표시\n  3. 건물의 명칭\n  4. 집합건물별 대지권등록부의 장번호\n  5. 토지소유자가 변경된 날과 그 원인\n  6. 소유권 지분"}],"선지":[{"번호":1,"판정":"-","설명":"지번은 등록사항이나 지목은 아니다. 토지대장과 임야대장에 등록한다(법 제71조제1항제3호)."},{"번호":2,"판정":"-","설명":"둘 다 등록사항이다(법 제71조제3항제1호, 규칙 제68조제4항제1호)."},{"번호":3,"판정":"-","설명":"둘 다 등록사항이다(법 제71조제3항제3호, 규칙 제68조제4항제2호)."},{"번호":4,"판정":"-","설명":"둘 다 등록사항이다(규칙 제68조제4항제5호ㆍ제6호)."},{"번호":5,"판정":"-","설명":"둘 다 등록사항이다(규칙 제68조제4항제3호ㆍ제4호)."}],"개념":[{"종류":"표","제목":"지적공부별 등록사항 비교","머리":["등록사항","토지ㆍ임야대장","공유지연명부","대지권등록부"],"행":[["토지의 소재ㆍ지번","○","○","○"],["지목ㆍ면적","○","-","-"],["소유자의 성명ㆍ주소ㆍ주민등록번호","○","○","○"],["소유권 지분","-","○","○"],["대지권 비율","-","-","○"],["전유부분의 건물표시ㆍ건물의 명칭","-","-","○"],["토지의 고유번호","○","○","○"],["토지소유자가 변경된 날과 그 원인","○","○","○"]]},{"종류":"표","제목":"토지대장ㆍ임야대장의 그 밖의 등록사항 (규칙 제68조제2항)","머리":["번호","등록사항"],"행":[["1","토지의 고유번호"],["2","지적도 또는 임야도의 번호와 필지별 토지대장 또는 임야대장의 장번호 및 축척"],["3","토지의 이동사유"],["4","토지소유자가 변경된 날과 그 원인"],["5","토지등급 또는 기준수확량등급과 그 설정ㆍ수정 연월일"],["6","개별공시지가와 그 기준일"],["7","그 밖에 국토교통부장관이 정하는 사항"]]}],"함정":"지번과 지목은 토지대장에서 붙어 다니는 항목이라 한 묶음으로 읽고 넘기기 쉽다. 대지권등록부는 지목과 면적을 두지 않는다. 나머지 선지는 규칙 제68조제4항의 항목 그대로다."}},{"i":"S5-2-2-공시법-06","r":"S5","g":3,"c":2,"n":6,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적공부의 보존 및 보관방법 등에 관한 설명으로 틀린 것은? (단, 정보처리시스템을 통하여 기록ㆍ저장한 지적공부는 제외함)","b":null,"bs":"없음","img":[],"ch":["천재지변이나 그 밖에 이에 준하는 재난을 피하기 위하여 필요한 경우에는 시ㆍ도지사의 승인 없이도 지적공부를 해당 청사 밖으로 반출할 수 있다.","지적공부 보관상자는 벽으로부터 10센티미터 이상 띄워야 하며, 높이 15센티미터 이상의 깔판 위에 올려놓아야 한다.","지적서고의 골조는 철근콘크리트 이상의 강질로 하고, 바닥과 벽은 2중으로 하여 영구적인 방수설비를 하여야 한다.","부책(簿冊)으로 된 토지대장ㆍ임야대장 및 공유지연명부는 지적공부 보관상자에 넣어 보관한다.","지적서고는 제한구역으로 지정하고, 출입자를 지적사무담당공무원으로 한정하여야 한다."],"a":[2],"L":"시1-3","o":"변형","x":{"한줄":"보관상자는 벽에서 15센티미터 이상 띄우고, 높이 10센티미터 이상의 깔판 위에 올려놓는다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제65조제4항","원문":"④ 지적공부 보관상자는 벽으로부터 15센티미터 이상 띄워야 하며, 높이 10센티미터 이상의 깔판 위에 올려놓아야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제69조제1항","원문":"① 지적소관청은 해당 청사에 지적서고를 설치하고 그 곳에 지적공부(정보처리시스템을 통하여 기록ㆍ저장한 경우는 제외한다. 이하 이 항에서 같다)를 영구히 보존하여야 하며, 다음 각 호의 어느 하나에 해당하는 경우 외에는 해당 청사 밖으로 지적공부를 반출할 수 없다.\n  1. 천재지변이나 그 밖에 이에 준하는 재난을 피하기 위하여 필요한 경우\n  2. 관할 시ㆍ도지사 또는 대도시 시장의 승인을 받은 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제65조제2항ㆍ제3항","원문":"② 제1항에 따른 지적서고의 구조는 다음 각 호의 기준에 따라야 한다.\n  1. 골조는 철근콘크리트 이상의 강질로 할 것\n  3. 바닥과 벽은 2중으로 하고 영구적인 방수설비를 할 것\n③ 지적서고는 다음 각 호의 기준에 따라 관리하여야 한다.\n  1. 지적서고는 제한구역으로 지정하고, 출입자를 지적사무담당공무원으로 한정할 것"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제66조제1항","원문":"① 부책(簿冊)으로 된 토지대장ㆍ임야대장 및 공유지연명부는 지적공부 보관상자에 넣어 보관하고, 카드로 된 토지대장ㆍ임야대장ㆍ공유지연명부ㆍ대지권등록부 및 경계점좌표등록부는 100장 단위로 바인더(binder)에 넣어 보관하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"천재지변 등 재난을 피하기 위한 반출은 승인 없이 가능하다. 승인이 필요한 경우는 그 밖의 사유다(법 제69조제1항제1호ㆍ제2호)."},{"번호":2,"판정":"틀림","설명":"벽에서 띄우는 거리가 15센티미터, 깔판 높이가 10센티미터다. 두 숫자가 바뀌어 있다(규칙 제65조제4항)."},{"번호":3,"판정":"옳음","설명":"골조는 철근콘크리트 이상의 강질, 바닥과 벽은 2중에 영구적 방수설비다(규칙 제65조제2항제1호ㆍ제3호)."},{"번호":4,"판정":"옳음","설명":"부책은 보관상자에, 카드는 100장 단위로 바인더에 넣는다(규칙 제66조제1항)."},{"번호":5,"판정":"옳음","설명":"제한구역 지정과 출입자 한정은 지적서고의 관리 기준이다(규칙 제65조제3항제1호)."}],"개념":[{"종류":"표","제목":"지적서고의 설치ㆍ관리 기준 (규칙 제65조)","머리":["구분","기준"],"행":[["위치","지적사무를 처리하는 사무실과 연접하여 설치"],["골조","철근콘크리트 이상의 강질"],["바닥ㆍ벽","2중, 영구적인 방수설비"],["창문ㆍ출입문","2중, 바깥쪽 문은 철제, 안쪽 문은 곤충ㆍ쥐 침입을 막는 철망 등"],["온도ㆍ습도","자동조절장치 설치, 연중 평균온도 섭씨 20±5도, 연중평균습도 65±5퍼센트"],["전기시설","단독퓨즈 설치, 소화장비 비치"],["출입","제한구역으로 지정, 출입자는 지적사무담당공무원으로 한정"],["보관물","지적공부, 지적 관계 서류, 지적측량장비만 보관, 인화물질 반입 금지"],["보관상자","벽에서 15센티미터 이상 띄우고, 높이 10센티미터 이상 깔판 위에 올림"]]},{"종류":"표","제목":"지적공부 보관방법 (규칙 제66조)","머리":["대상","보관방법"],"행":[["부책으로 된 토지대장ㆍ임야대장ㆍ공유지연명부","지적공부 보관상자"],["카드로 된 토지대장ㆍ임야대장ㆍ공유지연명부ㆍ대지권등록부ㆍ경계점좌표등록부","100장 단위로 바인더"],["일람도ㆍ지번색인표ㆍ지적도면","지번부여지역별로 도면번호순, 각 장별로 보호대"],["정보처리시스템으로 기록ㆍ저장한 지적공부","지적정보관리체계에 영구 보존(시ㆍ도지사, 시장ㆍ군수 또는 구청장)"]]},{"종류":"흐름","제목":"지적공부 청사 밖 반출","단계":[{"이름":"원칙","설명":"지적소관청은 지적서고에 지적공부를 영구히 보존하고 청사 밖으로 반출하지 못한다(법 제69조제1항)"},{"이름":"예외 1","설명":"천재지변이나 이에 준하는 재난을 피하기 위해 필요한 경우 반출 가능"},{"이름":"예외 2 신청","설명":"시ㆍ도지사 또는 대도시 시장에게 반출사유를 적은 승인신청서 제출(규칙 제67조제1항)"},{"이름":"예외 2 승인","설명":"시ㆍ도지사 또는 대도시 시장이 사유를 심사한 뒤 승인 여부를 지적소관청에 통지(규칙 제67조제2항)"}]}],"함정":"숫자 두 개의 자리를 바꾼 유형이다. 벽에서 띄우는 거리 15, 깔판 높이 10으로 외운다. 반출 승인권자는 국토교통부장관이 아니라 시ㆍ도지사 또는 대도시 시장이다."}},{"i":"S5-2-2-공시법-07","r":"S5","g":3,"c":2,"n":7,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 부동산종합공부에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["부동산종합공부의 멸실 또는 훼손에 대비하여 이를 별도로 복제하여 관리하는 정보관리체계는 국토교통부장관이 구축한다.","건축물의 표시와 소유자에 관한 사항은 토지에 건축물이 있는 경우에만 등록하며, 그 내용은 건축물대장의 내용이다.","부동산의 가격에 관한 사항으로 개별공시지가, 개별주택가격 및 공동주택가격 공시내용이 등록된다.","「부동산등기법」 제48조에 따른 부동산의 권리에 관한 사항은 부동산종합공부의 등록사항이다.","부동산종합공부의 등록사항을 관리하는 기관의 장은 지적소관청에 상시적으로 관련 정보를 제공하여야 한다."],"a":[1],"L":"시1-3","o":"변형","x":{"한줄":"부동산종합공부를 영구히 보존하고 별도 복제 관리 정보관리체계를 구축하는 주체는 국토교통부장관이 아니라 지적소관청이다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제76조의2제2항","원문":"② 지적소관청은 부동산종합공부를 영구히 보존하여야 하며, 부동산종합공부의 멸실 또는 훼손에 대비하여 이를 별도로 복제하여 관리하는 정보관리체계를 구축하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제76조의3","원문":"지적소관청은 부동산종합공부에 다음 각 호의 사항을 등록하여야 한다.\n  1. 토지의 표시와 소유자에 관한 사항: 이 법에 따른 지적공부의 내용\n  2. 건축물의 표시와 소유자에 관한 사항(토지에 건축물이 있는 경우만 해당한다): 「건축법」 제38조에 따른 건축물대장의 내용\n  3. 토지의 이용 및 규제에 관한 사항: 「토지이용규제 기본법」 제10조에 따른 토지이용계획확인서의 내용\n  4. 부동산의 가격에 관한 사항: 「부동산 가격공시에 관한 법률」 제10조에 따른 개별공시지가, 같은 법 제16조, 제17조 및 제18조에 따른 개별주택가격 및 공동주택가격 공시내용\n  5. 그 밖에 부동산의 효율적 이용과 부동산과 관련된 정보의 종합적 관리ㆍ운영을 위하여 필요한 사항으로서 대통령령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제62조의2","원문":"법 제76조의3제5호에서 \"대통령령으로 정하는 사항\"이란 「부동산등기법」 제48조에 따른 부동산의 권리에 관한 사항을 말한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제76조의2제3항","원문":"③ 제76조의3 각 호의 등록사항을 관리하는 기관의 장은 지적소관청에 상시적으로 관련 정보를 제공하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"복제 관리 정보관리체계는 지적소관청이 구축한다(법 제76조의2제2항). 국토교통부장관이 복제 관리 체계를 구축하는 대상은 지적공부다(법 제69조제3항)."},{"번호":2,"판정":"옳음","설명":"건축물 사항은 토지에 건축물이 있는 경우만 등록하며 건축물대장의 내용이다(법 제76조의3제2호)."},{"번호":3,"판정":"옳음","설명":"개별공시지가, 개별주택가격, 공동주택가격 공시내용이 부동산의 가격에 관한 사항이다(법 제76조의3제4호)."},{"번호":4,"판정":"옳음","설명":"부동산의 권리에 관한 사항이 영으로 정한 그 밖의 등록사항이다(법 제76조의3제5호, 영 제62조의2)."},{"번호":5,"판정":"옳음","설명":"등록사항 관리기관의 장은 지적소관청에 상시적으로 정보를 제공한다(법 제76조의2제3항)."}],"개념":[{"종류":"표","제목":"부동산종합공부의 등록사항 (법 제76조의3)","머리":["구분","등록사항","내용의 출처"],"행":[["토지의 표시와 소유자","지적공부의 내용","공간정보관리법"],["건축물의 표시와 소유자(토지에 건축물이 있는 경우만)","건축물대장의 내용","건축법 제38조"],["토지의 이용 및 규제","토지이용계획확인서의 내용","토지이용규제 기본법 제10조"],["부동산의 가격","개별공시지가, 개별주택가격, 공동주택가격 공시내용","부동산 가격공시에 관한 법률"],["그 밖의 사항","부동산의 권리에 관한 사항","부동산등기법 제48조(영 제62조의2)"]]},{"종류":"표","제목":"부동산종합공부의 관리ㆍ열람ㆍ정정","머리":["구분","내용","근거"],"행":[["관리ㆍ운영","지적소관청","법 제76조의2제1항"],["보존","영구 보존, 별도 복제 관리 정보관리체계도 지적소관청이 구축","법 제76조의2제2항"],["정보 제공","등록사항 관리기관의 장이 지적소관청에 상시적으로 제공","법 제76조의2제3항"],["자료 제출 요구","지적소관청이 관리기관의 장에게 요구, 특별한 사유가 없으면 제공","법 제76조의2제4항"],["열람ㆍ증명서 발급 신청","지적소관청이나 읍ㆍ면ㆍ동의 장","법 제76조의4제1항"],["등록사항 정정","법 제84조 준용: 토지소유자가 지적소관청에 신청","법 제76조의5, 제84조제1항"],["불일치 등록사항","지적소관청이 확인ㆍ관리하고 관리기관의 장에게 통지하여 정정 요청 가능","영 제62조의3"]]}],"함정":"지적공부 복제 관리는 국토교통부장관(법 제69조제3항), 부동산종합공부 복제 관리는 지적소관청(법 제76조의2제2항)으로 주체가 다르다. 열람ㆍ증명서 발급은 읍ㆍ면ㆍ동의 장에게도 신청할 수 있지만 등록사항 정정은 지적소관청에 한다."}},{"i":"S5-2-2-공시법-08","r":"S5","g":3,"c":2,"n":8,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 축척변경에 따른 청산금에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["청산금은 축척변경 지번별 조서의 필지별 증감면적에 지번별 제곱미터당 금액을 곱하여 산정한다.","지적소관청은 청산금이 결정되었다는 뜻을 15일 이상 공고하여 일반인이 열람할 수 있게 하여야 한다.","청산금의 납부고지를 받은 자는 그 고지를 받은 날부터 6개월 이내에 청산금을 지적소관청에 내야 한다.","증가된 면적에 대한 청산금의 합계와 감소된 면적에 대한 청산금의 합계에 차액이 생긴 경우 초과액은 그 지방자치단체의 수입으로 하고, 부족액은 그 지방자치단체가 부담한다.","납부고지되거나 수령통지된 청산금에 관하여 이의가 있는 자는 납부고지 또는 수령통지를 받은 날부터 3개월 이내에 지적소관청에 이의신청을 할 수 있다."],"a":[5],"L":"시1-4","o":"변형","x":{"한줄":"청산금 이의신청은 납부고지 또는 수령통지를 받은 날부터 1개월 이내에 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제77조","원문":"제77조(청산금에 관한 이의신청)\n① 제76조제1항에 따라 납부고지되거나 수령통지된 청산금에 관하여 이의가 있는 자는 납부고지 또는 수령통지를 받은 날부터 1개월 이내에 지적소관청에 이의신청을 할 수 있다.\n② 제1항에 따른 이의신청을 받은 지적소관청은 1개월 이내에 축척변경위원회의 심의ㆍ의결을 거쳐 그 인용(認容) 여부를 결정한 후 지체 없이 그 내용을 이의신청인에게 통지하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제75조제3항ㆍ제4항ㆍ제5항","원문":"③ 청산금은 제73조에 따라 작성된 축척변경 지번별 조서의 필지별 증감면적에 제2항에 따라 결정된 지번별 제곱미터당 금액을 곱하여 산정한다.\n④ 지적소관청은 청산금을 산정하였을 때에는 청산금 조서(축척변경 지번별 조서에 필지별 청산금 명세를 적은 것을 말한다)를 작성하고, 청산금이 결정되었다는 뜻을 제71조제2항의 방법에 따라 15일 이상 공고하여 일반인이 열람할 수 있게 하여야 한다.\n⑤ 제3항에 따라 청산금을 산정한 결과 증가된 면적에 대한 청산금의 합계와 감소된 면적에 대한 청산금의 합계에 차액이 생긴 경우 초과액은 그 지방자치단체의 수입으로 하고, 부족액은 그 지방자치단체가 부담한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제76조제1항~제4항","원문":"① 지적소관청은 제75조제4항에 따라 청산금의 결정을 공고한 날부터 20일 이내에 토지소유자에게 청산금의 납부고지 또는 수령통지를 하여야 한다.\n② 제1항에 따른 납부고지를 받은 자는 그 고지를 받은 날부터 6개월 이내에 청산금을 지적소관청에 내야 한다.\n③ 지적소관청은 제1항에 따른 수령통지를 한 날부터 6개월 이내에 청산금을 지급하여야 한다.\n④ 지적소관청은 청산금을 지급받을 자가 행방불명 등으로 받을 수 없거나 받기를 거부할 때에는 그 청산금을 공탁할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"필지별 증감면적에 지번별 제곱미터당 금액을 곱한다(영 제75조제3항)."},{"번호":2,"판정":"옳음","설명":"청산금 결정 공고는 15일 이상이다(영 제75조제4항)."},{"번호":3,"판정":"옳음","설명":"납부고지를 받은 날부터 6개월 이내에 낸다(영 제76조제2항)."},{"번호":4,"판정":"옳음","설명":"차액이 생기면 초과액은 지방자치단체의 수입, 부족액은 지방자치단체의 부담이다(영 제75조제5항)."},{"번호":5,"판정":"틀림","설명":"이의신청 기간은 1개월이다. 신청을 받은 지적소관청도 1개월 이내에 축척변경위원회의 심의ㆍ의결을 거쳐 결정한다(영 제77조)."}],"개념":[{"종류":"표","제목":"청산금 절차의 기간","머리":["단계","기간","근거"],"행":[["청산금 결정 공고","15일 이상 공고","영 제75조제4항"],["납부고지 또는 수령통지","결정 공고일부터 20일 이내","영 제76조제1항"],["청산금 납부","납부고지를 받은 날부터 6개월 이내","영 제76조제2항"],["청산금 지급","수령통지를 한 날부터 6개월 이내","영 제76조제3항"],["이의신청","납부고지 또는 수령통지를 받은 날부터 1개월 이내","영 제77조제1항"],["이의신청 결정","지적소관청이 1개월 이내에 축척변경위원회 심의ㆍ의결을 거쳐 결정, 지체 없이 통지","영 제77조제2항"]]},{"종류":"흐름","제목":"청산금 처리 순서","단계":[{"이름":"청산금 산정","설명":"증감면적 × 지번별 제곱미터당 금액. 금액은 축척변경위원회 의결로 정한다(영 제75조제2항ㆍ제3항)"},{"이름":"결정 공고","설명":"청산금 조서 작성 후 15일 이상 공고하여 열람"},{"이름":"납부고지ㆍ수령통지","설명":"공고한 날부터 20일 이내"},{"이름":"이의신청","설명":"고지ㆍ통지를 받은 날부터 1개월 이내 지적소관청에 신청"},{"이름":"납부ㆍ지급","설명":"납부는 고지일부터, 지급은 통지일부터 각 6개월 이내. 받을 수 없거나 거부하면 공탁 가능"},{"이름":"확정공고","설명":"청산금의 납부 및 지급이 완료되었을 때 지체 없이(영 제78조제1항)"}]}],"함정":"6개월(납부ㆍ지급)과 1개월(이의신청)의 기간을 바꿔 쓰는 유형이다. 청산금 납부기간은 6개월이고 이의신청은 1개월이며, 납부고지ㆍ수령통지는 공고한 날부터 20일 이내에 한다."}},{"i":"S5-2-2-공시법-09","r":"S5","g":3,"c":2,"n":9,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 축척변경 확정공고에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["지적소관청은 청산금의 납부고지 및 수령통지가 완료되었을 때 지체 없이 축척변경의 확정공고를 하여야 한다.","확정공고에는 축척변경 지번별 조서가 포함되고, 청산금 조서는 포함되지 않는다.","축척변경 시행지역의 토지는 확정공고일에 토지의 이동이 있는 것으로 본다.","지적소관청은 시ㆍ도지사의 승인을 받은 후에 축척변경의 확정공고를 하여야 한다.","확정공고에는 토지의 소재 및 지역명이 포함되고, 지적도의 축척은 포함되지 않는다."],"a":[3],"L":"시1-4","o":"변형","x":{"한줄":"축척변경 시행지역의 토지는 확정공고일에 토지의 이동이 있는 것으로 본다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제78조","원문":"제78조(축척변경의 확정공고)\n① 청산금의 납부 및 지급이 완료되었을 때에는 지적소관청은 지체 없이 축척변경의 확정공고를 하여야 한다.\n② 지적소관청은 제1항에 따른 확정공고를 하였을 때에는 지체 없이 축척변경에 따라 확정된 사항을 지적공부에 등록하여야 한다.\n③ 축척변경 시행지역의 토지는 제1항에 따른 확정공고일에 토지의 이동이 있는 것으로 본다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제92조제1항","원문":"① 영 제78조제1항에 따른 축척변경의 확정공고에는 다음 각 호의 사항이 포함되어야 한다.\n  1. 토지의 소재 및 지역명\n  2. 영 제73조에 따른 축척변경 지번별 조서\n  3. 영 제75조제4항에 따른 청산금 조서\n  4. 지적도의 축척"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제83조제3항","원문":"③ 지적소관청은 제2항에 따라 축척변경을 하려면 축척변경 시행지역의 토지소유자 3분의 2 이상의 동의를 받아 제1항에 따른 축척변경위원회의 의결을 거친 후 시ㆍ도지사 또는 대도시 시장의 승인을 받아야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"확정공고 시기는 청산금의 납부 및 지급이 완료되었을 때다. 납부고지ㆍ수령통지를 마친 때가 아니다(영 제78조제1항)."},{"번호":2,"판정":"틀림","설명":"확정공고에는 축척변경 지번별 조서와 청산금 조서가 모두 포함된다(규칙 제92조제1항제2호ㆍ제3호)."},{"번호":3,"판정":"옳음","설명":"확정공고일이 토지의 이동이 있는 날이다(영 제78조제3항)."},{"번호":4,"판정":"틀림","설명":"시ㆍ도지사 또는 대도시 시장의 승인은 축척변경을 시작할 때 받는다(법 제83조제3항). 확정공고에는 승인 절차가 없다."},{"번호":5,"판정":"틀림","설명":"확정공고에는 토지의 소재 및 지역명, 축척변경 지번별 조서, 청산금 조서, 지적도의 축척이 모두 포함된다(규칙 제92조제1항)."}],"개념":[{"종류":"표","제목":"축척변경 확정공고 (영 제78조, 규칙 제92조)","머리":["구분","내용"],"행":[["공고 시기","청산금의 납부 및 지급이 완료되었을 때 지체 없이"],["공고 사항","토지의 소재 및 지역명, 축척변경 지번별 조서, 청산금 조서, 지적도의 축척"],["공고 뒤 조치","확정된 사항을 지체 없이 지적공부에 등록"],["토지 이동 시기","확정공고일에 토지의 이동이 있는 것으로 봄"],["등기촉탁","토지의 표시 변경에 관한 등기가 필요하면 지체 없이 관할 등기관서에 촉탁(법 제89조제1항)"]]},{"종류":"흐름","제목":"축척변경 절차","단계":[{"이름":"신청ㆍ직권","설명":"토지소유자의 신청 또는 지적소관청의 직권으로 일정한 지역을 정한다(법 제83조제2항)"},{"이름":"동의ㆍ의결ㆍ승인","설명":"토지소유자 3분의 2 이상의 동의, 축척변경위원회 의결, 시ㆍ도지사 또는 대도시 시장의 승인(법 제83조제3항)"},{"이름":"시행공고","설명":"승인을 받으면 지체 없이 20일 이상 공고(영 제71조제1항)"},{"이름":"경계점표지 설치","설명":"시행공고일부터 30일 이내 토지소유자 또는 점유자가 설치(영 제71조제3항)"},{"이름":"측량ㆍ지번별 조서","설명":"축척변경 측량 후 시행공고일 현재 면적과 측량 후 면적을 비교한 지번별 조서 작성(영 제73조)"},{"이름":"청산금 처리","설명":"산정, 15일 이상 공고, 20일 이내 납부고지ㆍ수령통지, 이의신청, 6개월 내 납부ㆍ지급"},{"이름":"확정공고","설명":"청산금의 납부 및 지급이 완료되었을 때 지체 없이, 이어서 지적공부 등록"}]}],"함정":"확정공고의 시기를 묻는 선지가 가장 많이 틀린다. 측량 완료, 지번별 조서 작성, 납부고지 완료는 모두 확정공고 시기가 아니고 청산금의 납부와 지급이 끝난 때다. 승인은 시작할 때의 절차다."}},{"i":"S5-2-2-공시법-10","r":"S5","g":3,"c":2,"n":10,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적소관청은 축척변경 확정공고를 하였을 때에는 지체 없이 축척변경에 따라 확정된 사항을 지적공부에 등록하여야 한다. 이 경우 토지대장에 등록하는 기준으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["축척변경 확정측량 결과도에 따른다.","청산금납부고지서에 따른다.","토지이동현황 조사계획서에 따른다.","확정공고된 축척변경 지번별 조서에 따른다.","축척변경 시행계획에 따른다."],"a":[4],"L":"시1-4","o":"기출","x":{"한줄":"토지대장은 확정공고된 축척변경 지번별 조서에 따라 등록한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제92조제2항","원문":"② 영 제78조제2항에 따라 지적공부에 등록하는 때에는 다음 각 호의 기준에 따라야 한다.\n  1. 토지대장은 제1항제2호에 따라 확정공고된 축척변경 지번별 조서에 따를 것\n  2. 지적도는 확정측량 결과도 또는 경계점좌표에 따를 것"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제78조제2항","원문":"② 지적소관청은 제1항에 따른 확정공고를 하였을 때에는 지체 없이 축척변경에 따라 확정된 사항을 지적공부에 등록하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"확정측량 결과도는 지적도에 등록하는 기준이다(규칙 제92조제2항제2호)."},{"번호":2,"판정":"틀림","설명":"청산금납부고지서는 청산금을 고지할 때 쓰는 서식이다(규칙 제90조). 지적공부 등록 기준이 아니다."},{"번호":3,"판정":"틀림","설명":"토지이동현황 조사계획은 지적소관청이 직권으로 토지이동을 조사ㆍ측량할 때 세우는 계획이다(규칙 제59조제1항)."},{"번호":4,"판정":"옳음","설명":"토지대장은 확정공고된 축척변경 지번별 조서에 따른다(규칙 제92조제2항제1호)."},{"번호":5,"판정":"틀림","설명":"시행계획은 시행공고 사항이다(영 제71조제1항제2호). 등록 기준이 아니다."}],"개념":[{"종류":"표","제목":"축척변경 확정사항의 지적공부 등록 기준","머리":["대상","등록 기준","근거"],"행":[["토지대장","확정공고된 축척변경 지번별 조서","규칙 제92조제2항제1호"],["지적도","확정측량 결과도 또는 경계점좌표","규칙 제92조제2항제2호"],["면적(원칙)","축척변경 측량 결과도","규칙 제87조제1항"],["면적(오차가 허용범위 이내)","축척변경 전의 면적을 결정면적으로 함","규칙 제87조제2항"],["면적(오차가 허용면적 초과)","축척변경 후의 면적을 결정면적으로 함","규칙 제87조제2항"],["경계점좌표등록부를 새로 갖추는 지역","경계점좌표에 따라 면적 결정","규칙 제87조제3항"]]},{"종류":"흐름","제목":"확정공고 이후","단계":[{"이름":"확정공고","설명":"청산금의 납부 및 지급이 완료되었을 때 지체 없이"},{"이름":"지적공부 등록","설명":"토지대장은 지번별 조서, 지적도는 확정측량 결과도 또는 경계점좌표에 따라 등록"},{"이름":"토지 이동 시기","설명":"확정공고일에 토지의 이동이 있는 것으로 본다"},{"이름":"등기촉탁","설명":"토지의 표시 변경 등기가 필요하면 지체 없이 관할 등기관서에 촉탁"}]}],"함정":"토지대장은 지번별 조서, 지적도는 확정측량 결과도 또는 경계점좌표다. 두 공부의 기준을 서로 바꾼 ①이 가장 그럴듯한 오답이다."}},{"i":"S5-2-2-공시법-11","r":"S5","g":3,"c":2,"n":11,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지상건축물 등의 현황을 지적도 및 임야도에 등록된 경계와 대비하여 표시하는 지적측량은?","b":null,"bs":"없음","img":[],"ch":["등록전환측량","신규등록측량","지적현황측량","경계복원측량","토지분할측량"],"a":[3],"L":"시1-5","o":"기출","x":{"한줄":"지상건축물 등의 현황을 지적도ㆍ임야도에 등록된 경계와 대비하여 표시하는 측량은 지적현황측량이다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제18조","원문":"제18조(지적현황측량) 법 제23조제1항제5호에서 \"대통령령으로 정하는 경우\"란 지상건축물 등의 현황을 지적도 및 임야도에 등록된 경계와 대비하여 표시하는 데에 필요한 경우를 말한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제23조제1항제3호ㆍ제4호","원문":"3. 다음 각 목의 어느 하나에 해당하는 경우로서 측량을 할 필요가 있는 경우\n    나. 제77조에 따라 토지를 신규등록하는 경우\n    다. 제78조에 따라 토지를 등록전환하는 경우\n    라. 제79조에 따라 토지를 분할하는 경우\n4. 경계점을 지상에 복원하는 경우\n5. 그 밖에 대통령령으로 정하는 경우"}],"선지":[{"번호":1,"판정":"-","설명":"등록전환측량은 임야대장ㆍ임야도에 등록된 토지를 토지대장ㆍ지적도에 옮겨 등록하기 위한 측량이다(법 제23조제1항제3호다목)."},{"번호":2,"판정":"-","설명":"신규등록측량은 새로 조성된 토지나 지적공부에 등록되지 않은 토지를 처음 등록하기 위한 측량이다(법 제23조제1항제3호나목)."},{"번호":3,"판정":"-","설명":"건축물 등의 현황을 등록 경계와 대비해 표시하는 측량이다(영 제18조)."},{"번호":4,"판정":"-","설명":"경계복원측량은 등록된 경계점을 지상에 복원하는 측량이다(법 제23조제1항제4호). 현황과 대비하지 않는다."},{"번호":5,"판정":"-","설명":"토지분할측량은 토지를 분할하기 위한 측량이다(법 제23조제1항제3호라목)."}],"개념":[{"종류":"표","제목":"지적측량을 하여야 하는 경우 (법 제23조제1항)","머리":["구분","사유"],"행":[["기준점","지적기준점을 정하는 경우"],["검사","지적측량성과를 검사하는 경우"],["토지의 이동 등","지적공부 복구, 신규등록, 등록전환, 분할, 바다가 된 토지의 등록말소, 축척변경, 등록사항 정정, 도시개발사업 등 시행지역의 토지 이동, 지적재조사사업에 따른 토지 이동"],["경계 복원","경계점을 지상에 복원하는 경우"],["지적현황측량","지상건축물 등의 현황을 지적도ㆍ임야도의 경계와 대비하여 표시하는 데에 필요한 경우(영 제18조)"]]},{"종류":"표","제목":"지적측량의 의뢰와 검사","머리":["구분","내용","근거"],"행":[["의뢰 상대","지적측량업 등록을 한 자 또는 한국국토정보공사(지적측량수행자)","법 제24조제1항"],["의뢰 제외","지적재조사사업에 따른 토지 이동(법 제23조제1항제3호자목)","법 제24조제1항"],["성과 결정","지적측량수행자가 측량 후 성과를 결정","법 제24조제2항"],["성과 검사","시ㆍ도지사, 대도시 시장 또는 지적소관청","법 제25조제1항"],["검사 제외","지적공부를 정리하지 아니하는 측량으로서 국토교통부령으로 정하는 측량","법 제25조제1항 단서"]]}],"함정":"경계복원측량(④)은 등록된 경계를 지상에 복원하는 측량이고, 지적현황측량은 건물 등 지상 현황을 등록 경계와 대비해 표시하는 측량이다. 두 측량 모두 토지의 이동을 수반하지 않는다."}},{"i":"S5-2-2-공시법-12","r":"S5","g":3,"c":2,"n":12,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적위원회 및 지적측량의 적부심사 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["적부심사청구를 받은 시ㆍ도지사는 30일 이내에 다툼이 되는 지적측량의 경위 및 그 성과, 토지이동 및 소유권 변동 연혁, 현황 실측도를 조사하여 지방지적위원회에 회부하여야 한다.","지방지적위원회는 심사청구를 회부받은 날부터 60일 이내에 심의ㆍ의결하여야 하나, 부득이한 경우에는 그 심의기간을 해당 지적위원회의 의결을 거쳐 30일 이내에서 한 번만 연장할 수 있다.","지방지적위원회의 의결이 있은 후 재심사 청구기간에 재심사를 청구하지 아니하거나 중앙지적위원회의 의결이 있는 경우에는 해당 지적측량성과에 대하여 다시 적부심사청구를 할 수 없다.","지방지적위원회의 의결서를 받은 자가 의결에 불복하는 경우에는 그 의결서를 받은 날부터 90일 이내에 시ㆍ도지사를 거쳐 중앙지적위원회에 재심사를 청구할 수 있다.","중앙지적위원회는 지적기술자의 업무정지 처분 및 징계요구에 관한 사항을 심의ㆍ의결한다."],"a":[4],"L":"시1-5","o":"변형","x":{"한줄":"재심사 청구는 시ㆍ도지사가 아니라 국토교통부장관을 거쳐 중앙지적위원회에 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제29조제6항","원문":"⑥ 제5항에 따라 의결서를 받은 자가 지방지적위원회의 의결에 불복하는 경우에는 그 의결서를 받은 날부터 90일 이내에 국토교통부장관을 거쳐 중앙지적위원회에 재심사를 청구할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제29조제2항ㆍ제3항","원문":"② 제1항에 따른 지적측량 적부심사청구를 받은 시ㆍ도지사는 30일 이내에 다음 각 호의 사항을 조사하여 지방지적위원회에 회부하여야 한다.\n  1. 다툼이 되는 지적측량의 경위 및 그 성과\n  2. 해당 토지에 대한 토지이동 및 소유권 변동 연혁\n  3. 해당 토지 주변의 측량기준점, 경계, 주요 구조물 등 현황 실측도\n③ 제2항에 따라 지적측량 적부심사청구를 회부받은 지방지적위원회는 그 심사청구를 회부받은 날부터 60일 이내에 심의ㆍ의결하여야 한다. 다만, 부득이한 경우에는 그 심의기간을 해당 지적위원회의 의결을 거쳐 30일 이내에서 한 번만 연장할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제29조제12항","원문":"⑫ 지방지적위원회의 의결이 있은 후 제6항에 따른 기간에 재심사를 청구하지 아니하거나 중앙지적위원회의 의결이 있는 경우에는 해당 지적측량성과에 대하여 다시 지적측량 적부심사청구를 할 수 없다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제28조제1항제5호","원문":"5. 제42조에 따른 지적기술자의 업무정지 처분 및 징계요구에 관한 사항"}],"선지":[{"번호":1,"판정":"옳음","설명":"시ㆍ도지사의 조사ㆍ회부 기한은 30일이고, 조사사항은 경위 및 성과, 연혁, 현황 실측도다(법 제29조제2항)."},{"번호":2,"판정":"옳음","설명":"심의ㆍ의결 기한은 회부일부터 60일이고, 연장은 30일 이내에서 한 번만 가능하다(법 제29조제3항)."},{"번호":3,"판정":"옳음","설명":"재심사 기간 경과 또는 중앙지적위원회 의결 뒤에는 다시 청구하지 못한다(법 제29조제12항)."},{"번호":4,"판정":"틀림","설명":"재심사는 의결서를 받은 날부터 90일 이내에 국토교통부장관을 거쳐 청구한다(법 제29조제6항, 영 제26조제1항). 시ㆍ도지사를 거치는 것은 최초 적부심사 청구다."},{"번호":5,"판정":"옳음","설명":"업무정지 처분 및 징계요구는 중앙지적위원회의 심의ㆍ의결 사항이다(법 제28조제1항제5호). 지방지적위원회는 적부심사 청구사항을 심의ㆍ의결한다."}],"개념":[{"종류":"흐름","제목":"지적측량 적부심사 절차","단계":[{"이름":"청구","설명":"토지소유자ㆍ이해관계인ㆍ지적측량수행자가 심사청구서에 지적측량성과를 첨부하여 시ㆍ도지사를 거쳐 지방지적위원회에 청구(법 제29조제1항, 영 제24조제1항)"},{"이름":"조사ㆍ회부","설명":"시ㆍ도지사가 30일 이내에 조사하여 지방지적위원회에 회부"},{"이름":"심의ㆍ의결","설명":"회부받은 날부터 60일 이내, 부득이하면 의결을 거쳐 30일 이내에서 한 번 연장"},{"이름":"통지","설명":"지방지적위원회가 시ㆍ도지사에게 의결서 송부, 시ㆍ도지사는 받은 날부터 7일 이내에 청구인과 이해관계인에게 통지"},{"이름":"재심사","설명":"의결서를 받은 날부터 90일 이내에 국토교통부장관을 거쳐 중앙지적위원회에 청구. 조사ㆍ회부ㆍ심의ㆍ통지 규정을 준용"},{"이름":"정리","설명":"의결서 사본을 받은 지적소관청이 지적공부 등록사항을 정정하거나 측량성과를 수정"}]},{"종류":"비교","제목":"중앙지적위원회와 지방지적위원회","왼쪽":{"이름":"중앙지적위원회 (국토교통부)","항목":["지적 관련 정책 개발 및 업무 개선","지적측량기술의 연구ㆍ개발 및 보급","적부심사에 대한 재심사","지적기술자의 양성","지적기술자의 업무정지 처분 및 징계요구"]},"오른쪽":{"이름":"지방지적위원회 (시ㆍ도)","항목":["지적측량 적부심사 청구사항의 심의ㆍ의결","청구는 시ㆍ도지사를 거쳐 제출","의결서는 시ㆍ도지사에게 송부","의결에 불복하면 중앙지적위원회에 재심사 청구"]}}],"함정":"시ㆍ도지사를 거치는 단계는 최초 청구뿐이다. 재심사는 국토교통부장관을 거친다. 지방지적위원회에는 징계요구 권한이 없고, 이는 중앙지적위원회 소관이다."}},{"i":"S5-2-2-공시법-13","r":"S5","g":3,"c":2,"n":13,"s":"공시법","q":"등기한 권리의 순위에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["부동산에 대한 가압류등기와 저당권설정등기 상호간의 순위는 접수번호에 따른다.","2번 저당권이 설정된 후 1번 저당권 일부이전의 부기등기가 이루어진 경우, 배당에 있어서 그 부기등기가 2번 저당권에 우선한다.","위조된 근저당권해지증서에 의해 1번 근저당권등기가 말소된 후 2번 근저당권이 설정된 경우, 말소된 1번 근저당권등기가 회복되더라도 2번 근저당권이 우선한다.","가등기 후에 제3자 명의의 소유권이전등기가 이루어진 경우, 가등기에 기한 본등기가 이루어지면 본등기는 제3자 명의 등기에 우선한다.","집합건물 착공 전의 나대지에 대하여 근저당권이 설정된 경우, 그 근저당권등기는 집합건물을 위한 대지권등기에 우선한다."],"a":[3],"L":"시2-1","o":"기출","x":{"한줄":"위조 서류로 말소된 1번 근저당권등기가 회복되면 종전 순위를 되찾으므로 1번이 2번보다 우선한다.","근거":[{"법령":"부동산등기법","조문":"제4조","원문":"제4조(권리의 순위)\n① 같은 부동산에 관하여 등기한 권리의 순위는 법률에 다른 규정이 없으면 등기한 순서에 따른다.\n② 등기의 순서는 등기기록 중 같은 구(區)에서 한 등기 상호간에는 순위번호에 따르고, 다른 구에서 한 등기 상호간에는 접수번호에 따른다."},{"법령":"부동산등기법","조문":"제5조","원문":"제5조(부기등기의 순위) 부기등기(附記登記)의 순위는 주등기(主登記)의 순위에 따른다. 다만, 같은 주등기에 관한 부기등기 상호간의 순위는 그 등기 순서에 따른다."},{"법령":"부동산등기법","조문":"제59조","원문":"제59조(말소등기의 회복) 말소된 등기의 회복(回復)을 신청하는 경우에 등기상 이해관계 있는 제3자가 있을 때에는 그 제3자의 승낙이 있어야 한다."},{"법령":"부동산등기법","조문":"제91조","원문":"제91조(가등기에 의한 본등기의 순위) 가등기에 의한 본등기(本登記)를 한 경우 본등기의 순위는 가등기의 순위에 따른다."},{"이론":"말소회복등기의 순위(판례 취지)","내용":"말소된 등기를 회복하면 말소 전의 순위와 효력을 되찾는다. 말소 후 회복 전에 설정된 등기의 명의인은 등기상 이해관계 있는 제3자로서 회복등기에 승낙할 의무가 있다."},{"이론":"나대지 근저당권과 대지권(판례 취지)","내용":"집합건물 착공 전 나대지에 설정된 근저당권은 건물 신축과 대지권등기보다 앞서 성립한 권리여서 대지권등기에 우선한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"가압류등기는 갑구, 저당권설정등기는 을구에 하므로 다른 구의 등기다. 접수번호로 순위를 정한다(법 제4조제2항)."},{"번호":2,"판정":"옳음","설명":"부기등기의 순위는 주등기에 따른다. 1번 저당권의 일부이전 부기등기는 1번 순위여서 2번 저당권에 우선한다(법 제5조)."},{"번호":3,"판정":"틀림","설명":"회복된 1번 근저당권은 종전 순위를 되찾는다. 말소 뒤에 설정된 2번 근저당권자는 회복에 승낙할 의무가 있고 1번이 우선한다(법 제59조, 판례 취지)."},{"번호":4,"판정":"옳음","설명":"가등기에 의한 본등기의 순위는 가등기 순위에 따르므로 본등기가 제3자 명의 등기에 우선한다. 등기관은 가등기에 의하여 보전되는 권리를 침해하는 이후 등기를 직권으로 말소한다(법 제91조, 제92조제1항)."},{"번호":5,"판정":"옳음","설명":"착공 전에 설정된 근저당권은 대지권등기보다 먼저 성립한 권리여서 대지권등기에 우선한다(판례 취지)."}],"개념":[{"종류":"표","제목":"등기의 순위 결정","머리":["상황","순위 기준","근거"],"행":[["같은 구에서 한 등기 상호간","순위번호","법 제4조제2항"],["다른 구에서 한 등기 상호간(갑구와 을구)","접수번호","법 제4조제2항"],["부기등기와 주등기","주등기의 순위","법 제5조"],["같은 주등기에 관한 부기등기 상호간","그 등기 순서","법 제5조 단서"],["가등기에 의한 본등기","가등기의 순위","법 제91조"],["대지권에 대한 등기로서 효력이 있는 건물 등기와 토지 등기기록 중 해당 구의 등기","접수번호","법 제61조제2항"],["등기신청의 접수 시기","신청정보가 전산정보처리조직에 저장된 때","법 제6조제1항"],["등기의 효력 발생","접수한 때부터","법 제6조제2항"]]},{"종류":"표","제목":"부기로 하는 등기 (법 제52조)","머리":["부기 대상","비고"],"행":[["등기명의인표시의 변경이나 경정의 등기","-"],["소유권 외의 권리의 이전등기","저당권 이전 등이 해당"],["소유권 외의 권리를 목적으로 하는 권리에 관한 등기","전세권저당권 등"],["소유권 외의 권리에 대한 처분제한 등기","-"],["권리의 변경이나 경정의 등기","이해관계 있는 제3자의 승낙이 없으면 주등기"],["환매특약등기, 권리소멸약정등기, 공유물 분할금지약정등기","-"]]}],"함정":"부기등기는 별도 순위가 아니라 주등기의 순위를 갖는다(②). 말소회복은 새 등기가 아니라 종전 순위를 되찾는 것이어서 회복 전에 설정된 후순위 등기보다 앞선다(③). 갑구와 을구 등기는 접수번호로 비교한다(①)."}},{"i":"S5-2-2-공시법-14","r":"S5","g":3,"c":2,"n":14,"s":"공시법","q":"등기신청에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["정지조건이 붙은 유증을 원인으로 소유권이전등기를 신청하는 경우, 조건성취를 증명하는 서면을 첨부하여야 한다.","사립대학이 부동산을 기증받은 경우, 학교 명의로 소유권이전등기를 할 수 있다.","법무사는 매매계약에 따른 소유권이전등기를 매도인과 매수인 쌍방을 대리하여 신청할 수 있다.","법인 아닌 사단인 종중이 건물을 매수한 경우, 종중의 대표자는 종중 명의로 소유권이전등기를 신청할 수 있다.","채권자대위권에 의한 등기신청의 경우, 대위채권자는 채무자의 등기신청권을 자기의 이름으로 행사한다."],"a":[2],"L":"시2-2","o":"기출","x":{"한줄":"학교는 법인도 법인 아닌 사단ㆍ재단도 아니어서 등기명의인이 될 수 없고, 학교법인 명의로 등기한다.","근거":[{"법령":"부동산등기법","조문":"제26조","원문":"제26조(법인 아닌 사단 등의 등기신청)\n① 종중(宗中), 문중(門中), 그 밖에 대표자나 관리인이 있는 법인 아닌 사단(社團)이나 재단(財團)에 속하는 부동산의 등기에 관하여는 그 사단이나 재단을 등기권리자 또는 등기의무자로 한다.\n② 제1항의 등기는 그 사단이나 재단의 명의로 그 대표자나 관리인이 신청한다."},{"법령":"부동산등기법","조문":"제28조","원문":"제28조(채권자대위권에 의한 등기신청)\n① 채권자는 「민법」 제404조에 따라 채무자를 대위(代位)하여 등기를 신청할 수 있다.\n② 등기관이 제1항 또는 다른 법령에 따른 대위신청에 의하여 등기를 할 때에는 대위자의 성명 또는 명칭, 주소 또는 사무소 소재지 및 대위원인을 기록하여야 한다."},{"법령":"민법","조문":"제124조","원문":"제124조(자기계약, 쌍방대리) 대리인은 본인의 허락이 없으면 본인을 위하여 자기와 법률행위를 하거나 동일한 법률행위에 관하여 당사자쌍방을 대리하지 못한다. 그러나 채무의 이행은 할 수 있다."},{"법령":"민법","조문":"제147조제1항","원문":"①정지조건있는 법률행위는 조건이 성취한 때로부터 그 효력이 생긴다."},{"이론":"등기명의인의 자격","내용":"자연인, 법인, 대표자나 관리인이 있는 법인 아닌 사단ㆍ재단이 등기명의인이 될 수 있다. 학교 자체는 이에 해당하지 않아 학교법인 명의로 등기한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"정지조건부 유증은 조건이 성취된 때 효력이 생기므로 조건 성취를 증명하는 정보를 함께 제공한다(민법 제147조제1항, 규칙 제46조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"학교 명의로는 등기하지 못한다. 학교법인이 등기명의인이다."},{"번호":3,"판정":"옳음","설명":"등기신청은 채무의 이행이어서 쌍방대리가 허용된다(민법 제124조 단서)."},{"번호":4,"판정":"옳음","설명":"종중은 그 명의로 등기하고 대표자가 신청한다(법 제26조)."},{"번호":5,"판정":"옳음","설명":"대위채권자는 채무자의 권리를 자기 이름으로 행사하며, 등기에는 대위자와 대위원인이 기록된다(법 제28조, 민법 제404조)."}],"개념":[{"종류":"표","제목":"등기신청인에 관한 규정","머리":["구분","내용","근거"],"행":[["원칙","등기권리자와 등기의무자가 공동으로 신청","법 제23조제1항"],["법인 아닌 사단ㆍ재단","그 사단ㆍ재단 명의로 대표자나 관리인이 신청","법 제26조"],["포괄승계인","등기원인 발생 후 상속 등이 있으면 상속인 등이 신청","법 제27조"],["채권자대위","채권자가 채무자를 대위하여 신청, 대위자 성명ㆍ주소ㆍ대위원인을 기록","법 제28조"],["신청 방법","방문신청(신청인 또는 대리인이 등기소에 출석하여 서면 제출) 또는 전자신청","법 제24조제1항"],["대리인","채무 이행인 등기신청은 쌍방대리 가능","민법 제124조 단서"]]},{"종류":"표","제목":"등기신청의 각하 사유 (법 제29조)","머리":["번호","사유"],"행":[["1","사건이 그 등기소의 관할이 아닌 경우"],["2","사건이 등기할 것이 아닌 경우"],["3","신청할 권한이 없는 자가 신청한 경우"],["4","방문신청에서 당사자나 대리인이 출석하지 아니한 경우"],["5","신청정보의 제공이 대법원규칙으로 정한 방식에 맞지 아니한 경우"],["6","신청정보의 부동산 또는 권리의 표시가 등기기록과 일치하지 아니한 경우"],["7","신청정보의 등기의무자 표시가 등기기록과 일치하지 아니한 경우(포괄승계인 신청 등 제외)"],["8","신청정보와 등기원인을 증명하는 정보가 일치하지 아니한 경우"],["9","등기에 필요한 첨부정보를 제공하지 아니한 경우"],["10","취득세ㆍ등록면허세ㆍ수수료를 내지 아니하거나 다른 법률에 따라 부과된 의무를 이행하지 아니한 경우"],["11","신청정보 또는 등기기록의 부동산 표시가 토지대장ㆍ임야대장ㆍ건축물대장과 일치하지 아니한 경우"]]}],"함정":"종중 같은 법인 아닌 사단은 명의 자격이 있어 ④가 옳다. 학교는 사단도 재단도 아닌 시설이어서 학교 이름으로는 등기할 수 없다. 쌍방대리가 안 된다는 민법 원칙(③)은 채무이행에는 적용되지 않는다."}},{"i":"S5-2-2-공시법-15","r":"S5","g":3,"c":2,"n":15,"s":"공시법","q":"부동산등기법령상 등기관의 처분에 대한 이의절차에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["이의신청은 결정 또는 처분을 한 등기관이 속한 등기소를 거치지 않고 관할 지방법원에 직접 이의신청서를 제출하여야 한다.","등기관은 이의가 이유 없다고 인정하면 이의신청일부터 3일 이내에 의견을 붙여 이의신청서를 관할 지방법원에 보내야 한다.","등기관은 이의가 이유 있다고 인정하면 그에 해당하는 처분을 하여야 한다.","이의에 대한 관할 지방법원의 결정에 대하여는 「비송사건절차법」에 따라 항고할 수 있다.","관할 지방법원은 이의신청에 대하여 결정하기 전에 등기관에게 가등기 또는 이의가 있다는 뜻의 부기등기를 명령할 수 있다."],"a":[1],"L":"시2-2","o":"변형","x":{"한줄":"이의신청서는 결정ㆍ처분을 한 등기관이 속한 등기소에 제출한다. 지방법원에 직접 내지 않는다.","근거":[{"법령":"부동산등기법","조문":"제101조","원문":"제101조(이의신청의 방법) 제100조에 따른 이의신청(이하 이 장에서 \"이의신청\"이라 한다)은 대법원규칙으로 정하는 바에 따라 결정 또는 처분을 한 등기관이 속한 등기소에 이의신청서를 제출하거나 전산정보처리조직을 이용하여 이의신청정보를 보내는 방법으로 한다."},{"법령":"부동산등기법","조문":"제103조","원문":"제103조(등기관의 조치)\n① 등기관은 이의가 이유 있다고 인정하면 그에 해당하는 처분을 하여야 한다.\n② 등기관은 이의가 이유 없다고 인정하면 이의신청일부터 3일 이내에 의견을 붙여 이의신청서 또는 이의신청정보를 관할 지방법원에 보내야 한다.\n③ 등기를 마친 후에 이의신청이 있는 경우에는 3일 이내에 의견을 붙여 이의신청서 또는 이의신청정보를 관할 지방법원에 보내고 등기상 이해관계 있는 자에게 이의신청 사실을 알려야 한다."},{"법령":"부동산등기법","조문":"제105조ㆍ제106조","원문":"제105조(이의에 대한 결정과 항고)\n② 제1항의 결정에 대하여는 「비송사건절차법」에 따라 항고할 수 있다.\n제106조(처분 전의 가등기 및 부기등기의 명령) 관할 지방법원은 이의신청에 대하여 결정하기 전에 등기관에게 가등기 또는 이의가 있다는 뜻의 부기등기를 명령할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"이의신청서는 처분을 한 등기관이 속한 등기소에 제출하거나 전산정보처리조직으로 보낸다(법 제101조). 관할 지방법원은 이의에 대해 결정하는 기관이다(법 제100조)."},{"번호":2,"판정":"옳음","설명":"이유 없다고 보면 3일 이내에 의견을 붙여 관할 지방법원에 보낸다(법 제103조제2항)."},{"번호":3,"판정":"옳음","설명":"이유 있다고 보면 등기관이 스스로 그에 해당하는 처분을 한다(법 제103조제1항)."},{"번호":4,"판정":"옳음","설명":"지방법원의 결정에 대해서는 비송사건절차법에 따라 항고한다(법 제105조제2항)."},{"번호":5,"판정":"옳음","설명":"결정 전에 가등기 또는 이의가 있다는 뜻의 부기등기를 명령할 수 있다(법 제106조)."}],"개념":[{"종류":"흐름","제목":"등기관의 처분에 대한 이의절차","단계":[{"이름":"이의신청","설명":"등기관의 결정 또는 처분에 이의 있는 자가 관할 지방법원에 이의신청(법 제100조). 이의신청서는 그 등기관이 속한 등기소에 제출(법 제101조)"},{"이름":"등기관의 조치","설명":"이유 있으면 그에 해당하는 처분. 이유 없으면 이의신청일부터 3일 이내에 의견을 붙여 관할 지방법원에 송부(법 제103조)"},{"이름":"등기 후 이의","설명":"3일 이내에 의견을 붙여 송부하고 등기상 이해관계 있는 자에게 이의신청 사실 통지(법 제103조제3항)"},{"이름":"법원의 조치","설명":"결정 전에 가등기 또는 이의가 있다는 뜻의 부기등기를 명령할 수 있음(법 제106조)"},{"이름":"결정과 항고","설명":"이유를 붙여 결정. 이유 있으면 등기관에게 처분을 명령하고 신청인과 이해관계인에게 알림. 결정에 대해서는 비송사건절차법에 따라 항고(법 제105조)"}]},{"종류":"표","제목":"이의신청의 요건과 효력","머리":["항목","내용","근거"],"행":[["이의신청 기간","법에 기간 제한 규정이 없음","법 제100조~제106조"],["이의 사유","새로운 사실이나 새로운 증거방법을 근거로 할 수 없음","법 제102조"],["집행정지","이의에는 집행정지의 효력이 없음","법 제104조"],["이의신청서 기재","성명과 주소, 대상인 결정ㆍ처분, 취지와 이유, 대법원예규로 정하는 사항, 신청인의 기명날인 또는 서명","규칙 제158조제1항"],["전자 방식","전산정보처리조직을 이용하고 인증서등을 함께 송신","규칙 제158조제2항"]]}],"함정":"이의신청서를 낼 곳(등기소)과 결정하는 곳(관할 지방법원)이 다르다. 신청서를 법원에 직접 내는 것으로 쓰면 틀린다. 이의에는 집행정지의 효력이 없고, 새로운 사실ㆍ증거방법을 근거로 한 이의는 허용되지 않는다."}},{"i":"S5-2-2-공시법-16","r":"S5","g":3,"c":2,"n":16,"s":"공시법","q":"등기권리자와 등기의무자가 공동으로 등기신청을 해야하는 것은? (단, 판결 등 집행권원에 의한 등기신청은 제외함)","b":null,"bs":"없음","img":[],"ch":["소유권보존등기의 말소등기를 신청하는 경우","법인의 합병으로 인한 포괄승계에 따른 등기를 신청하는 경우","등기명의인표시의 경정등기를 신청하는 경우","토지를 수용한 사업시행자가 수용으로 인한 소유권이전등기를 신청하는 경우","변제로 인한 피담보채권의 소멸에 의해 근저당권설정등기의 말소등기를 신청하는 경우"],"a":[5],"L":"시2-2","o":"기출","x":{"한줄":"근저당권설정등기의 말소등기는 법률에 단독신청 규정이 없으므로 등기권리자와 등기의무자가 공동으로 신청한다.","근거":[{"법령":"부동산등기법","조문":"제23조제1항","원문":"① 등기는 법률에 다른 규정이 없는 경우에는 등기권리자(登記權利者)와 등기의무자(登記義務者)가 공동으로 신청한다."},{"법령":"부동산등기법","조문":"제23조제2항ㆍ제3항ㆍ제6항","원문":"② 소유권보존등기(所有權保存登記) 또는 소유권보존등기의 말소등기(抹消登記)는 등기명의인으로 될 자 또는 등기명의인이 단독으로 신청한다.\n③ 상속, 법인의 합병, 그 밖에 대법원규칙으로 정하는 포괄승계에 따른 등기는 등기권리자가 단독으로 신청한다.\n⑥ 등기명의인표시의 변경이나 경정의 등기는 해당 권리의 등기명의인이 단독으로 신청한다."},{"법령":"부동산등기법","조문":"제99조제1항","원문":"① 수용으로 인한 소유권이전등기는 제23조제1항에도 불구하고 등기권리자가 단독으로 신청할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"소유권보존등기의 말소등기는 등기명의인이 단독으로 신청한다(법 제23조제2항)."},{"번호":2,"판정":"-","설명":"법인의 합병에 따른 포괄승계 등기는 등기권리자가 단독으로 신청한다(법 제23조제3항)."},{"번호":3,"판정":"-","설명":"등기명의인표시의 변경이나 경정의 등기는 해당 권리의 등기명의인이 단독으로 신청한다(법 제23조제6항)."},{"번호":4,"판정":"-","설명":"수용으로 인한 소유권이전등기는 사업시행자(등기권리자)가 단독으로 신청한다(법 제99조제1항)."},{"번호":5,"판정":"-","설명":"근저당권 말소는 소유자(등기권리자)와 근저당권자(등기의무자)의 공동신청이 원칙이다(법 제23조제1항)."}],"개념":[{"종류":"표","제목":"단독신청이 허용되는 등기","머리":["등기","단독 신청인","근거"],"행":[["소유권보존등기, 그 말소등기","등기명의인으로 될 자 또는 등기명의인","법 제23조제2항"],["상속, 법인의 합병 등 포괄승계에 따른 등기","등기권리자","법 제23조제3항"],["등기절차의 이행 또는 인수를 명하는 판결에 의한 등기","승소한 등기권리자 또는 등기의무자","법 제23조제4항"],["부동산표시의 변경이나 경정의 등기","소유권의 등기명의인","법 제23조제5항"],["등기명의인표시의 변경이나 경정의 등기","해당 권리의 등기명의인","법 제23조제6항"],["신탁등기","수탁자","법 제23조제7항"],["신탁등기의 말소등기","수탁자","법 제87조제3항"],["수용으로 인한 소유권이전등기","등기권리자(사업시행자)","법 제99조제1항"],["가등기","가등기권리자(가등기의무자의 승낙이나 가처분명령이 있을 때)","법 제89조"]]},{"종류":"비교","제목":"공동신청과 단독신청","왼쪽":{"이름":"공동신청 (원칙)","항목":["등기권리자와 등기의무자가 함께 신청","매매 등으로 인한 소유권이전등기","저당권ㆍ근저당권 등 설정등기","변제 또는 해지로 인한 근저당권 말소등기","해제ㆍ무효 등으로 인한 소유권이전등기의 말소등기"]},"오른쪽":{"이름":"단독신청 (법률에 규정이 있는 경우)","항목":["보존등기와 그 말소등기","상속ㆍ합병 등 포괄승계","판결에 의한 등기","표시 변경ㆍ경정, 등기명의인표시 변경ㆍ경정","신탁등기, 수용으로 인한 이전등기"]}}],"함정":"‘말소등기’라는 말에 끌려 단독신청으로 읽기 쉽다. 단독으로 신청하는 말소는 소유권보존등기의 말소와 신탁등기의 말소처럼 법에 규정이 있는 것뿐이다. 변제로 소멸한 근저당권의 말소는 설정자와 근저당권자가 공동으로 신청한다."}},{"i":"S5-2-2-공시법-17","r":"S5","g":3,"c":2,"n":17,"s":"공시법","q":"부동산등기법상 신탁등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["수익자는 수탁자를 대위하여 신탁등기를 신청할 수 있다.","신탁등기의 말소등기는 수탁자가 단독으로 신청할 수 있다.","신탁가등기는 소유권이전청구권보전을 위한 가등기와 동일한 방식으로 신청하되, 신탁원부 작성을 위한 정보를 첨부정보로서 제공해야 한다.","여러 명의 수탁자 중 1인의 임무종료로 인한 합유명의인 변경등기를 한 경우에는 등기관은 직권으로 신탁원부 기록을 변경해야 한다.","법원이 신탁관리인 선임의 재판을 한 경우, 그 신탁관리인은 지체없이 신탁원부 기록의 변경등기를 신청해야 한다."],"a":[5],"L":"시2-3","o":"기출","x":{"한줄":"법원이 신탁관리인 선임의 재판을 하면 신탁관리인이 아니라 법원이 지체 없이 신탁원부 기록의 변경등기를 등기소에 촉탁한다.","근거":[{"법령":"부동산등기법","조문":"제85조제1항","원문":"① 법원은 다음 각 호의 어느 하나에 해당하는 재판을 한 경우 지체 없이 신탁원부 기록의 변경등기를 등기소에 촉탁하여야 한다.\n  1. 수탁자 해임의 재판\n  2. 신탁관리인의 선임 또는 해임의 재판\n  3. 신탁 변경의 재판"},{"법령":"부동산등기법","조문":"제82조제2항","원문":"② 수익자나 위탁자는 수탁자를 대위하여 신탁등기를 신청할 수 있다. 이 경우 제1항은 적용하지 아니한다."},{"법령":"부동산등기법","조문":"제87조제3항","원문":"③ 신탁등기의 말소등기는 수탁자가 단독으로 신청할 수 있다."},{"법령":"부동산등기법","조문":"제85조의2","원문":"제85조의2(직권에 의한 신탁변경등기) 등기관이 신탁재산에 속하는 부동산에 관한 권리에 대하여 다음 각 호의 어느 하나에 해당하는 등기를 할 경우 직권으로 그 부동산에 관한 신탁원부 기록의 변경등기를 하여야 한다.\n  1. 수탁자의 변경으로 인한 이전등기\n  2. 여러 명의 수탁자 중 1인의 임무 종료로 인한 변경등기\n  3. 수탁자인 등기명의인의 성명 및 주소(법인인 경우에는 그 명칭 및 사무소 소재지를 말한다)에 관한 변경등기 또는 경정등기"},{"법령":"부동산등기규칙","조문":"제139조제3항","원문":"③ 신탁등기를 신청하는 경우에는 법 제81조제1항 각 호의 사항을 첨부정보로서 등기소에 제공하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수익자나 위탁자는 수탁자를 대위하여 신탁등기를 신청할 수 있다(법 제82조제2항)."},{"번호":2,"판정":"옳음","설명":"신탁등기의 말소등기는 수탁자가 단독으로 신청할 수 있다(법 제87조제3항)."},{"번호":3,"판정":"옳음","설명":"가등기 신청 방식에 따르되 신탁원부 작성을 위해 법 제81조제1항 각 호의 사항을 첨부정보로 제공한다(규칙 제139조제3항)."},{"번호":4,"판정":"옳음","설명":"수탁자 1인의 임무 종료로 인한 변경등기를 하면 등기관이 직권으로 신탁원부를 변경한다(법 제85조의2제2호)."},{"번호":5,"판정":"틀림","설명":"신탁관리인 선임 재판에 따른 신탁원부 변경등기는 법원이 촉탁한다(법 제85조제1항제2호). 신탁관리인에게 신청 의무가 있지 않다."}],"개념":[{"종류":"표","제목":"신탁등기 관련 신청ㆍ촉탁ㆍ직권","머리":["구분","내용","근거"],"행":[["신탁등기 신청","수탁자가 단독으로, 권리의 설정ㆍ보존ㆍ이전ㆍ변경 신청과 동시에(1건의 신청정보로 일괄)","법 제23조제7항, 제82조제1항, 규칙 제139조제1항"],["대위신청","수익자 또는 위탁자가 수탁자를 대위하여 신청, 이 경우 동시 신청 불요","법 제82조제2항"],["수탁자 임무 종료","신수탁자가 단독으로 권리이전등기 신청","법 제83조"],["수탁자 여럿 중 1인의 임무 종료","다른 수탁자가 단독으로 권리변경등기 신청, 다른 수탁자가 여럿이면 전원 공동","법 제84조제2항"],["법원의 촉탁","수탁자 해임, 신탁관리인 선임 또는 해임, 신탁 변경의 재판","법 제85조제1항"],["법무부장관의 촉탁","수탁자 직권 해임, 신탁관리인 직권 선임ㆍ해임, 신탁내용 변경 명령","법 제85조제2항"],["등기관의 직권 변경","수탁자 변경 이전등기, 수탁자 1인의 임무 종료 변경등기, 수탁자의 성명ㆍ주소 변경ㆍ경정","법 제85조의2"],["수탁자의 변경등기 신청","위 경우를 제외하고 신탁원부 사항이 변경되면 지체 없이 신청","법 제86조"],["신탁등기 말소","수탁자가 단독으로, 권리 이전ㆍ변경ㆍ소멸 신청과 동시에","법 제87조"]]},{"종류":"표","제목":"신탁원부의 기록사항 (법 제81조제1항)","머리":["구분","내용"],"행":[["당사자","위탁자, 수탁자, 수익자의 성명ㆍ주소"],["수익자 관련","수익자를 지정ㆍ변경할 권한자, 지정ㆍ변경 방법, 수익권 발생ㆍ소멸 조건"],["신탁관리인","선임된 경우 성명ㆍ주소"],["특수 신탁","수익자 없는 특정 목적 신탁, 재신탁, 유언대용신탁, 수익자연속신탁, 수익증권발행신탁, 공익신탁, 유한책임신탁인 경우 그 뜻"],["신탁 내용","신탁의 목적, 신탁재산의 관리ㆍ처분ㆍ운용ㆍ개발 방법, 신탁종료 사유, 그 밖의 신탁 조항"]]}],"함정":"‘신청해야 한다’의 주체를 바꾼 선지다. 신탁관리인 선임이나 수탁자 해임 같은 재판이 있으면 법원이 촉탁하고, 수탁자 1인의 임무 종료나 수탁자의 성명ㆍ주소 변경은 등기관이 직권으로 신탁원부를 고친다."}},{"i":"S5-2-2-공시법-18","r":"S5","g":3,"c":2,"n":18,"s":"공시법","q":"집합건물의 등기에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["등기관이 구분건물의 대지권등기를 하였을 때에는 건축물대장 소관청의 촉탁에 따라 대지권의 목적인 토지의 등기기록에 소유권, 지상권, 전세권 또는 임차권이 대지권이라는 뜻을 기록한다.","구분건물로서 그 대지권의 소멸이 있는 경우에는 구분건물의 소유권의 등기명의인은 1동의 건물에 속하는 다른 구분건물의 소유권의 등기명의인을 대위하여 그 등기를 신청할 수 있다.","대지권에 대한 등기로서 효력이 있는 건물의 등기와 대지권의 목적인 토지의 등기기록 중 해당 구에 한 등기의 순서는 순위번호에 따른다.","1동의 건물에 속하는 구분건물 중 일부만에 관하여 소유권보존등기를 신청하는 경우, 나머지 구분건물의 표시에 관한 등기는 보존등기를 마친 뒤에 따로 신청할 수 있다.","「집합건물의 소유 및 관리에 관한 법률」상 규약에 따른 공용부분이라는 뜻의 등기는 건축물대장 소관청의 촉탁으로 한다."],"a":[2],"L":"시2-3","o":"변형","x":{"한줄":"구분건물의 대지권 변경이나 소멸이 있으면 소유권 등기명의인은 다른 구분건물 소유권 등기명의인을 대위하여 그 등기를 신청할 수 있다.","근거":[{"법령":"부동산등기법","조문":"제41조제3항","원문":"③ 구분건물로서 그 대지권의 변경이나 소멸이 있는 경우에는 구분건물의 소유권의 등기명의인은 1동의 건물에 속하는 다른 구분건물의 소유권의 등기명의인을 대위하여 그 등기를 신청할 수 있다."},{"법령":"부동산등기법","조문":"제40조제4항","원문":"④ 등기관이 제3항에 따라 대지권등기를 하였을 때에는 직권으로 대지권의 목적인 토지의 등기기록에 소유권, 지상권, 전세권 또는 임차권이 대지권이라는 뜻을 기록하여야 한다."},{"법령":"부동산등기법","조문":"제61조제2항","원문":"② 제1항에 따라 대지권에 대한 등기로서의 효력이 있는 등기와 대지권의 목적인 토지의 등기기록 중 해당 구에 한 등기의 순서는 접수번호에 따른다."},{"법령":"부동산등기법","조문":"제46조제1항","원문":"① 1동의 건물에 속하는 구분건물 중 일부만에 관하여 소유권보존등기를 신청하는 경우에는 나머지 구분건물의 표시에 관한 등기를 동시에 신청하여야 한다."},{"법령":"부동산등기법","조문":"제47조제1항","원문":"① 「집합건물의 소유 및 관리에 관한 법률」 제3조제4항에 따른 공용부분(共用部分)이라는 뜻의 등기는 소유권의 등기명의인이 신청하여야 한다. 이 경우 공용부분인 건물에 소유권 외의 권리에 관한 등기가 있을 때에는 그 권리의 등기명의인의 승낙이 있어야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대지권등기를 하면 등기관이 직권으로 토지 등기기록에 대지권이라는 뜻을 기록한다. 촉탁이 필요하지 않다(법 제40조제4항)."},{"번호":2,"판정":"옳음","설명":"대지권의 변경이나 소멸이 있으면 대위신청이 가능하다(법 제41조제3항)."},{"번호":3,"판정":"틀림","설명":"대지권에 대한 등기로서 효력이 있는 건물 등기와 토지 등기기록 해당 구의 등기는 접수번호에 따라 순서를 정한다(법 제61조제2항)."},{"번호":4,"판정":"틀림","설명":"나머지 구분건물의 표시에 관한 등기는 보존등기와 동시에 신청해야 한다(법 제46조제1항)."},{"번호":5,"판정":"틀림","설명":"공용부분이라는 뜻의 등기는 소유권의 등기명의인이 신청하고, 소유권 외의 권리가 있으면 그 권리자의 승낙이 있어야 한다(법 제47조제1항)."}],"개념":[{"종류":"표","제목":"구분건물ㆍ대지권 등기의 주요 규정","머리":["내용","규정","근거"],"행":[["등기기록","1동의 건물에 속하는 전부에 1개의 등기기록을 사용","법 제15조제1항 단서"],["대지권 표시","1동 건물 표제부에 대지권의 목적인 토지 표시, 전유부분 표제부에 대지권 표시","법 제40조제3항"],["토지 쪽 기록","대지권등기를 하면 등기관이 직권으로 토지 등기기록에 대지권이라는 뜻 기록","법 제40조제4항"],["대지권 변경ㆍ소멸","구분건물 소유권 명의인이 다른 구분건물 소유권 명의인을 대위하여 신청 가능","법 제41조제3항"],["1동 표제부 변경","같은 1동의 다른 구분건물에도 변경등기로서 효력","법 제41조제4항"],["일부 보존","나머지 구분건물의 표시등기를 동시에 신청, 대위 신청 가능","법 제46조제1항ㆍ제2항"],["규약상 공용부분","소유권 명의인이 신청, 소유권 외의 권리가 있으면 그 명의인의 승낙","법 제47조제1항"],["대지권등기 후 건물 권리 등기","대지권에 대하여 동일한 등기로서 효력(건물만에 관한 것이라는 부기가 있으면 제외)","법 제61조제1항"],["순서","대지권 효력 건물 등기와 토지 해당 구 등기는 접수번호에 따름","법 제61조제2항"],["처분 제한","대지권이 등기된 구분건물에는 건물만에 관한 소유권이전ㆍ저당권설정 등기 불가, 대지권이라는 뜻이 등기된 토지에도 소유권이전ㆍ저당권설정 등기 불가","법 제61조제3항ㆍ제4항"]]},{"종류":"표","제목":"대지사용권 취득에 따른 등기 (법 제60조)","머리":["상황","신청","비고"],"행":[["구분건물 신축자가 대지사용권을 가지고 있으나 대지권등기 없이 구분건물만 소유권이전등기를 마친 경우","현재의 구분건물 소유명의인과 공동으로 대지사용권 이전등기 신청","법 제60조제1항"],["신축 양도인이 대지사용권을 나중에 취득하여 이전하기로 약정한 경우","제1항 준용","법 제60조제2항"],["위 두 경우의 등기","대지권에 관한 등기와 동시에 신청","법 제60조제3항"]]}],"함정":"대지권 관련 등기는 등기관의 직권(대지권이라는 뜻 기록), 소유권 명의인의 신청(공용부분), 대위신청(변경ㆍ소멸)으로 나뉜다. 건축물대장 소관청이 촉탁하는 경우로 바꿔 쓴 ①⑤는 틀리다. 순서 기준은 접수번호다."}},{"i":"S5-2-2-공시법-19","r":"S5","g":3,"c":2,"n":19,"s":"공시법","q":"건축물대장에 甲 건물을 乙 건물에 합병하는 등록을 2026년 8월 1일에 한 후, 건물의 합병등기를 하고자 하는 경우에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["乙 건물의 소유권의 등기명의인은 건축물대장상 건물의 합병등록이 있은 날부터 1개월 이내에 건물합병등기를 신청하여야 한다.","합병하려는 모든 건물에 등기원인 및 그 연월일과 접수번호가 동일한 저당권에 관한 등기만 있는 경우에는 건물합병등기를 할 수 있다.","甲 건물에만 전세권등기가 있는 경우에도 건물합병등기를 할 수 있다.","등기관이 합병제한 사유가 있음을 이유로 신청을 각하한 경우 지체 없이 그 사유를 건축물대장 소관청에 알려야 한다.","건물합병등기를 신청할 의무가 있는 자가 그 등기신청을 게을리하면 「부동산등기법」에 따라 과태료를 부과받는다."],"a":[5],"L":"시2-3","o":"변형","x":{"한줄":"현행 부동산등기법에는 건물합병등기를 게을리한 경우의 과태료 규정이 없다.","근거":[{"법령":"부동산등기법","조문":"제41조제1항","원문":"① 건물의 분할, 구분, 합병이 있는 경우와 제40조의 등기사항에 변경이 있는 경우에는 그 건물 소유권의 등기명의인은 그 사실이 있는 때부터 1개월 이내에 그 등기를 신청하여야 한다."},{"법령":"부동산등기법","조문":"제42조","원문":"제42조(합병 제한)\n① 합병하려는 건물에 다음 각 호의 등기 외의 권리에 관한 등기가 있는 경우에는 합병의 등기를 할 수 없다.\n  1. 소유권ㆍ전세권 및 임차권의 등기\n  2. 합병하려는 모든 건물에 있는 등기원인 및 그 연월일과 접수번호가 동일한 저당권에 관한 등기\n  3. 합병하려는 모든 건물에 있는 제81조제1항 각 호의 등기사항이 동일한 신탁등기\n② 등기관이 제1항을 위반한 등기의 신청을 각하하면 지체 없이 그 사유를 건축물대장 소관청에 알려야 한다."},{"법령":"부동산등기법","조문":"제112조","원문":"제112조 삭제 <2017.10.13>"},{"법령":"부동산등기법","조문":"제111조","원문":"제111조(벌칙) 다음 각 호의 어느 하나에 해당하는 사람은 2년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n  1. 제110조제2항을 위반하여 등기필정보의 작성이나 관리에 관한 비밀을 누설한 사람\n  2. 제110조제3항을 위반하여 등기필정보를 취득한 사람 또는 그 사정을 알면서 등기필정보를 제공한 사람\n  3. 부정하게 취득한 등기필정보를 제2호의 목적으로 보관한 사람"}],"선지":[{"번호":1,"판정":"옳음","설명":"건물 합병이 있는 때부터 1개월 이내에 소유권 등기명의인이 신청한다(법 제41조제1항)."},{"번호":2,"판정":"옳음","설명":"합병하려는 모든 건물에 원인ㆍ연월일ㆍ접수번호가 같은 저당권 등기만 있으면 합병이 가능하다(법 제42조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"소유권ㆍ전세권ㆍ임차권 등기는 합병을 막지 않는 등기로 열거되어 있다(법 제42조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"제한을 위반한 신청을 각하하면 지체 없이 그 사유를 건축물대장 소관청에 알린다(법 제42조제2항)."},{"번호":5,"판정":"틀림","설명":"현행 법에는 건물 표시변경등기를 게을리한 데 대한 과태료 규정이 없다. 과태료 조항인 제112조는 2017.10.13 삭제되었고 제111조는 등기필정보 관련 벌칙만 정한다."}],"개념":[{"종류":"비교","제목":"토지 합필 제한과 건물 합병 제한","왼쪽":{"이름":"토지 합필 (법 제37조)","항목":["허용되는 등기: 소유권, 지상권, 전세권, 임차권, 승역지에 하는 지역권","합필하려는 모든 토지에 등기원인 및 그 연월일과 접수번호가 동일한 저당권 등기","합필하려는 모든 토지에 신탁원부 기재사항이 동일한 신탁등기","제한을 위반한 신청을 각하하면 지적소관청에 통지"]},"오른쪽":{"이름":"건물 합병 (법 제42조)","항목":["허용되는 등기: 소유권, 전세권, 임차권","합병하려는 모든 건물에 등기원인 및 그 연월일과 접수번호가 동일한 저당권 등기","합병하려는 모든 건물에 신탁원부 기재사항이 동일한 신탁등기","제한을 위반한 신청을 각하하면 건축물대장 소관청에 통지"]}},{"종류":"표","제목":"표시에 관한 등기의 신청 기한","머리":["등기","신청인","기한","근거"],"행":[["토지의 분할, 합병, 표제부 등기사항 변경","토지 소유권의 등기명의인","그 사실이 있는 때부터 1개월 이내","법 제35조"],["건물의 분할, 구분, 합병, 표제부 등기사항 변경","건물 소유권의 등기명의인","그 사실이 있는 때부터 1개월 이내","법 제41조제1항"],["건물 멸실","건물 소유권의 등기명의인(1개월 내 신청이 없으면 건물대지 소유자가 대위 신청 가능)","그 사실이 있는 때부터 1개월 이내","법 제43조제1항ㆍ제2항"],["1동 전부 멸실","구분건물 소유권 명의인이 다른 구분건물 명의인을 대위하여 신청 가능","-","법 제43조제3항"],["지적소관청 통지에 따른 변경","신청이 없으면 등기관이 직권으로 변경등기","법 제35조 기간 이내에 신청 없을 때","법 제36조제1항"]]}],"함정":"합병 제한은 ‘소유권ㆍ전세권ㆍ임차권’이 예외이므로 전세권 등기가 있어도 합병된다. 저당권은 모든 건물에 원인ㆍ연월일ㆍ접수번호가 같을 때만 예외다. 합병등기를 게을리해도 현행 법에는 과태료가 없다.","개정":"부동산등기법 제112조는 2017.10.13 삭제되었다. 현행 법에는 건물합병등기 신청을 게을리한 경우의 과태료 규정이 없다."}},{"i":"S5-2-2-공시법-20","r":"S5","g":3,"c":2,"n":20,"s":"공시법","q":"등기관이 승역지의 등기기록에 지역권설정의 등기를 할 때 기록하여야 할 사항이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["범위","요역지","지역권자","지역권설정의 목적","등기원인 및 그 연월일"],"a":[3],"L":"시2-4","o":"기출","x":{"한줄":"승역지에 지역권설정의 등기를 할 때 기록하는 사항은 법 제48조제1항제1호~제4호와 제70조 각 호이고, 권리자(지역권자)는 포함되지 않는다.","근거":[{"법령":"부동산등기법","조문":"제70조","원문":"제70조(지역권의 등기사항) 등기관이 승역지의 등기기록에 지역권설정의 등기를 할 때에는 제48조제1항제1호부터 제4호까지에서 규정한 사항 외에 다음 각 호의 사항을 기록하여야 한다. 다만, 제4호는 등기원인에 그 약정이 있는 경우에만 기록한다.\n  1. 지역권설정의 목적\n  2. 범위\n  3. 요역지\n  4. 「민법」 제292조제1항 단서, 제297조제1항 단서 또는 제298조의 약정\n  5. 승역지의 일부에 지역권설정의 등기를 할 때에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제48조제1항","원문":"① 등기관이 갑구 또는 을구에 권리에 관한 등기를 할 때에는 다음 각 호의 사항을 기록하여야 한다.\n  1. 순위번호\n  2. 등기목적\n  3. 접수연월일 및 접수번호\n  4. 등기원인 및 그 연월일\n  5. 권리자"},{"법령":"부동산등기법","조문":"제71조제1항","원문":"① 등기관이 승역지에 지역권설정의 등기를 하였을 때에는 직권으로 요역지의 등기기록에 다음 각 호의 사항을 기록하여야 한다.\n  1. 순위번호\n  2. 등기목적\n  3. 승역지\n  4. 지역권설정의 목적\n  5. 범위\n  6. 등기연월일"}],"선지":[{"번호":1,"판정":"-","설명":"범위는 승역지에 기록할 사항이다(법 제70조제2호)."},{"번호":2,"판정":"-","설명":"요역지는 승역지에 기록할 사항이다(법 제70조제3호)."},{"번호":3,"판정":"-","설명":"법 제70조는 제48조제1항 중 제1호~제4호만 끌어오고 제5호 권리자는 제외한다. 승역지에는 지역권자를 기록하지 않는다."},{"번호":4,"판정":"-","설명":"지역권설정의 목적은 승역지에 기록할 사항이다(법 제70조제1호)."},{"번호":5,"판정":"-","설명":"등기원인 및 그 연월일은 제48조제1항제4호에 따라 기록한다."}],"개념":[{"종류":"비교","제목":"승역지와 요역지의 지역권 기록사항","왼쪽":{"이름":"승역지 등기기록 (설정등기, 법 제70조)","항목":["순위번호, 등기목적, 접수연월일ㆍ접수번호, 등기원인 및 그 연월일 (제48조제1항제1호~제4호)","지역권설정의 목적","범위","요역지","민법 제292조제1항 단서, 제297조제1항 단서, 제298조의 약정(그 약정이 있는 경우에만)","승역지 일부이면 그 부분을 표시한 도면의 번호"]},"오른쪽":{"이름":"요역지 등기기록 (직권, 법 제71조)","항목":["순위번호","등기목적","승역지","지역권설정의 목적","범위","등기연월일","승역지에 지역권 변경ㆍ말소의 등기를 하면 직권으로 요역지에 변경ㆍ말소의 등기"]}},{"종류":"표","제목":"용익권ㆍ담보권의 등기사항 (제48조 사항 외)","머리":["권리","반드시 기록","약정이 있는 경우에만 기록"],"행":[["지상권 (법 제69조)","설정의 목적, 범위","존속기간, 지료와 지급시기, 민법 제289조의2제1항 후단의 약정"],["지역권 승역지 (법 제70조)","설정의 목적, 범위, 요역지","민법 제292조제1항 단서, 제297조제1항 단서, 제298조의 약정"],["전세권 (법 제72조)","전세금, 범위","존속기간, 위약금 또는 배상금, 민법 제306조 단서의 약정"],["임차권 (법 제74조)","차임, 범위","차임지급시기, 존속기간, 임차보증금, 양도 또는 전대에 대한 임대인의 동의"],["저당권 (법 제75조제1항)","채권액, 채무자","변제기, 이자와 발생기ㆍ지급시기, 원본ㆍ이자 지급장소, 손해배상 약정, 민법 제358조 단서의 약정, 채권의 조건"],["근저당권 (법 제75조제2항)","채권의 최고액, 채무자","민법 제358조 단서의 약정, 존속기간"]]}],"함정":"법 제70조는 제48조제1항 중 제1호~제4호만 끌어오므로 제5호 권리자는 승역지 기록사항이 아니다. 승역지에는 요역지를, 요역지에는 승역지를 기록한다."}},{"i":"S5-2-2-공시법-21","r":"S5","g":3,"c":2,"n":21,"s":"공시법","q":"용익권과 담보권의 등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["승역지의 등기기록에 지역권설정등기를 할 때 등기관은 권리자로서 요역지 소유자의 성명과 주소를 기록해야 한다.","근저당권설정등기에서 존속기간은 등기원인에 그 약정이 있는 경우에만 기록한다.","지상권설정의 범위가 토지의 일부인 경우, 그 부분을 표시한 지적도를 첨부정보로 제공해야 한다.","동일한 채권을 담보하기 위해 5개의 부동산에 저당권설정등기를 하는 경우, 등기관은 공동담보목록을 작성하고 각 부동산의 등기기록에 그 목록의 번호를 기록한다.","전세금반환채권의 일부 양도를 원인으로 한 전세권 일부이전등기는, 존속기간 만료 전이라도 전세권이 소멸하였음을 증명하여 신청할 수 있다."],"a":[1],"L":"시2-4","o":"변형","x":{"한줄":"승역지 등기기록의 지역권설정등기에는 요역지 소유자(지역권자)의 성명·주소를 권리자로 기록하지 않고 요역지를 기록한다.","근거":[{"법령":"부동산등기법","조문":"제70조","원문":"등기관이 승역지의 등기기록에 지역권설정의 등기를 할 때에는 제48조제1항제1호부터 제4호까지에서 규정한 사항 외에 다음 각 호의 사항을 기록하여야 한다. 다만, 제4호는 등기원인에 그 약정이 있는 경우에만 기록한다.\n1. 지역권설정의 목적\n2. 범위\n3. 요역지\n4. 「민법」 제292조제1항 단서, 제297조제1항 단서 또는 제298조의 약정\n5. 승역지의 일부에 지역권설정의 등기를 할 때에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제75조제2항","원문":"등기관은 제1항의 저당권의 내용이 근저당권(根抵當權)인 경우에는 제48조에서 규정한 사항 외에 다음 각 호의 사항을 기록하여야 한다. 다만, 제3호 및 제4호는 등기원인에 그 약정이 있는 경우에만 기록한다.\n1. 채권의 최고액\n2. 채무자의 성명 또는 명칭과 주소 또는 사무소 소재지\n3. 「민법」 제358조 단서의 약정\n4. 존속기간"},{"법령":"부동산등기규칙","조문":"제126조제2항","원문":"지상권설정의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 지적도를 첨부정보로서 등기소에 제공하여야 한다."},{"법령":"부동산등기법","조문":"제78조제2항","원문":"등기관은 제1항의 경우에 부동산이 5개 이상일 때에는 공동담보목록을 작성하여야 한다."},{"법령":"부동산등기법","조문":"제73조제2항","원문":"제1항의 전세권 일부이전등기의 신청은 전세권의 존속기간의 만료 전에는 할 수 없다. 다만, 존속기간 만료 전이라도 해당 전세권이 소멸하였음을 증명하여 신청하는 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지역권설정등기는 제48조제1항 제1~4호(순위번호·등기목적·접수연월일·등기원인)만 기록하므로 제5호 권리자는 적지 않는다. 승역지에는 목적·범위·요역지를 적는다(법 제70조)."},{"번호":2,"판정":"옳음","설명":"근저당권은 채권의 최고액과 채무자가 필수이고, 존속기간과 민법 제358조 단서의 약정은 약정이 있을 때만 적는다(법 제75조제2항제3호·제4호)."},{"번호":3,"판정":"옳음","설명":"토지 일부에 지상권을 설정하면 그 부분을 표시한 지적도를 낸다(규칙 제126조제2항)."},{"번호":4,"판정":"옳음","설명":"부동산이 5개 이상이면 공동담보목록을 만들고, 각 부동산 등기기록에는 목록의 번호를 적는다(법 제78조제2항, 규칙 제135조제2항)."},{"번호":5,"판정":"옳음","설명":"존속기간 만료 전에는 신청할 수 없지만, 전세권이 소멸하였음을 증명하면 가능하다(법 제73조제2항, 규칙 제129조제2항)."}],"개념":[{"종류":"표","제목":"용익권 등기의 필요적·임의적 기록사항","머리":["권리","반드시 기록","약정이 있을 때만","일부 설정 시 첨부"],"행":[["지상권","목적, 범위","존속기간, 지료·지급시기, 민법 제289조의2제1항 후단 약정","지적도"],["지역권(승역지)","목적, 범위, 요역지","민법 제292조제1항 단서·제297조제1항 단서·제298조 약정","지적도"],["전세권","전세금, 범위","존속기간, 위약금·배상금, 민법 제306조 단서 약정","지적도 또는 건물도면"],["임차권","차임, 범위","차임지급시기, 존속기간, 임차보증금, 양도·전대 동의","지적도 또는 건물도면"]]},{"종류":"표","제목":"저당권과 근저당권의 기록사항","머리":["구분","저당권","근저당권"],"행":[["반드시 기록","채권액, 채무자","채권의 최고액, 채무자"],["약정이 있을 때만","변제기, 이자·발생기·지급시기, 지급장소, 손해배상 약정, 민법 제358조 단서 약정, 채권의 조건","민법 제358조 단서 약정, 존속기간"],["금액 아닌 채권 담보","채권의 평가액 기록(법 제77조)","채권의 평가액 기록(법 제77조)"],["여러 부동산 공동담보","5개 이상이면 공동담보목록 작성(법 제78조제2항)","5개 이상이면 공동담보목록 작성(법 제78조제2항)"]]}],"함정":"지역권을 지상권·전세권과 같은 방식으로 외워 지역권자 기록이 필요하다고 보면 ①을 놓친다. 지역권은 승역지에 요역지를 적고 권리자 인적사항은 적지 않는다. 근저당권의 존속기간은 약정이 있으면 적는 등기사항이므로 ②는 옳은 선지다."}},{"i":"S5-2-2-공시법-22","r":"S5","g":3,"c":2,"n":22,"s":"공시법","q":"토지에 대한 소유권이전청구권보전 가등기에 기하여 소유권이전의 본등기를 한 경우, 그 가등기 후 본등기 전에 마쳐진 등기 중 등기관의 직권말소 대상이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["지상권설정등기","지역권설정등기","저당권설정등기","임차권설정등기","해당 가등기상 권리를 목적으로 하는 가압류등기"],"a":[5],"L":"시2-5","o":"기출","x":{"한줄":"소유권이전청구권 가등기로 본등기를 하면 가등기 후 본등기 전의 등기는 거의 모두 직권말소하지만, 해당 가등기상 권리를 목적으로 하는 가압류·가처분등기는 남긴다.","근거":[{"법령":"부동산등기규칙","조문":"제147조제1항","원문":"등기관이 소유권이전등기청구권보전 가등기에 의하여 소유권이전의 본등기를 한 경우에는 법 제92조제1항에 따라 가등기 후 본등기 전에 마쳐진 등기 중 다음 각 호의 등기를 제외하고는 모두 직권으로 말소한다.\n1. 해당 가등기상 권리를 목적으로 하는 가압류등기나 가처분등기\n2. 가등기 전에 마쳐진 가압류에 의한 강제경매개시결정등기\n3. 가등기 전에 마쳐진 담보가등기, 전세권 및 저당권에 의한 임의경매개시결정등기\n4. 가등기권자에게 대항할 수 있는 주택임차권등기, 주택임차권설정등기, 상가건물임차권등기, 상가건물임차권설정등기(이하 \"주택임차권등기등\"이라 한다)"},{"법령":"부동산등기법","조문":"제92조제1항","원문":"등기관은 가등기에 의한 본등기를 하였을 때에는 대법원규칙으로 정하는 바에 따라 가등기 이후에 된 등기로서 가등기에 의하여 보전되는 권리를 침해하는 등기를 직권으로 말소하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"규칙 제147조제1항 각 호에 없어 직권말소 대상이다."},{"번호":2,"판정":"-","설명":"각 호에 없어 직권말소 대상이다."},{"번호":3,"판정":"-","설명":"각 호에 없어 직권말소 대상이다. 남는 것은 가등기 전에 마쳐진 저당권에 의한 임의경매개시결정등기이고(제3호), 가등기 후의 저당권설정등기는 말소된다."},{"번호":4,"판정":"-","설명":"제4호는 가등기권자에게 대항할 수 있는 임차권등기만 남긴다. 가등기 후에 설정된 임차권설정등기는 대항할 수 없어 직권말소 대상이다."},{"번호":5,"판정":"-","설명":"제1호에 해당하므로 직권말소 대상이 아니다."}],"개념":[{"종류":"표","제목":"소유권이전청구권 가등기의 본등기 후 처리","머리":["구분","내용"],"행":[["직권말소","가등기 후 본등기 전에 마쳐진 등기 중 아래 남기는 등기를 뺀 모두"],["남기는 등기 1","해당 가등기상 권리를 목적으로 하는 가압류·가처분등기"],["남기는 등기 2","가등기 전에 마쳐진 가압류에 의한 강제경매개시결정등기"],["남기는 등기 3","가등기 전에 마쳐진 담보가등기·전세권·저당권에 의한 임의경매개시결정등기"],["남기는 등기 4","가등기권자에게 대항할 수 있는 주택·상가건물 임차권등기 및 임차권설정등기"],["체납처분 압류","직권말소대상통지 후 이의신청이 있으면 예규에 따라 말소 여부 결정(규칙 제147조제2항)"]]},{"종류":"표","제목":"가등기 종류별 본등기 후 직권말소","머리":["가등기 종류","말소하는 것","말소하지 않는 것"],"행":[["소유권이전청구권","위 남기는 등기를 뺀 모든 등기","위 남기는 등기"],["지상권·전세권·임차권 설정청구권","같은 부분의 지상권·지역권·전세권·임차권설정등기, 대항력 없는 주택임차권등기등","소유권이전·가등기, 가압류·가처분, 체납처분 압류, 저당권설정등기"],["저당권설정청구권","없음","가등기 후 본등기 전의 등기 전부"]]}],"함정":"지상권·지역권·임차권처럼 용익권이면 남는다고 보거나, 가압류는 처분제한이니 모두 남는다고 보기 쉽다. 남는 가압류는 가등기상 권리를 목적으로 한 것뿐이다. 가등기 후에 설정된 저당권·임차권설정등기는 말소된다."}},{"i":"S5-2-2-공시법-23","r":"S5","g":3,"c":2,"n":23,"s":"공시법","q":"가등기에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["임차권 이전청구권을 보전하기 위한 가등기는 허용되지 않는다.","가등기에 의하여 본등기를 하는 경우 가등기의 순위번호를 사용하여 본등기를 하며, 본등기의 순위는 가등기의 순위에 따른다.","가등기명의인이 단독으로 가등기의 말소를 신청하는 경우에는 가등기의무자의 승낙을 증명하는 정보를 제공해야 한다.","지상권설정청구권보전 가등기에 의하여 지상권설정의 본등기를 한 경우, 가등기 후 본등기 전에 마쳐진 같은 토지에 대한 저당권설정등기는 직권말소 대상이다.","가등기를 명하는 가처분명령은 가등기의무자의 주소지를 관할하는 지방법원이 가등기권리자의 신청으로 할 수 있다."],"a":[2],"L":"시2-5","o":"변형","x":{"한줄":"가등기에 의한 본등기는 가등기의 순위번호를 사용하며, 본등기의 순위는 가등기의 순위를 따른다.","근거":[{"법령":"부동산등기규칙","조문":"제146조","원문":"가등기를 한 후 본등기의 신청이 있을 때에는 가등기의 순위번호를 사용하여 본등기를 하여야 한다."},{"법령":"부동산등기법","조문":"제91조","원문":"가등기에 의한 본등기(本登記)를 한 경우 본등기의 순위는 가등기의 순위에 따른다."},{"법령":"부동산등기법","조문":"제3조","원문":"등기는 부동산의 표시(表示)와 다음 각 호의 어느 하나에 해당하는 권리의 보존, 이전, 설정, 변경, 처분의 제한 또는 소멸에 대하여 한다.\n1. 소유권(所有權)\n2. 지상권(地上權)\n3. 지역권(地役權)\n4. 전세권(傳貰權)\n5. 저당권(抵當權)\n6. 권리질권(權利質權)\n7. 채권담보권(債權擔保權)\n8. 임차권(賃借權)"},{"법령":"부동산등기법","조문":"제93조제1항","원문":"가등기명의인은 제23조제1항에도 불구하고 단독으로 가등기의 말소를 신청할 수 있다."},{"법령":"부동산등기규칙","조문":"제148조제2항제4호","원문":"지상권, 전세권 또는 임차권의 설정등기청구권보전 가등기에 의하여 지상권, 전세권 또는 임차권의 설정의 본등기를 한 경우 가등기 후 본등기 전에 마쳐진 다음 각 호의 등기는 직권말소의 대상이 되지 아니한다.\n4. 저당권설정등기"},{"법령":"부동산등기법","조문":"제90조제1항","원문":"제89조의 가등기를 명하는 가처분명령은 부동산의 소재지를 관할하는 지방법원이 가등기권리자의 신청으로 가등기 원인사실의 소명이 있는 경우에 할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"임차권도 제3조 각 호의 권리이므로 그 이전청구권을 보전하는 가등기를 할 수 있다(법 제3조제8호, 제88조)."},{"번호":2,"판정":"옳음","설명":"본등기는 가등기의 순위번호로 하고 순위는 가등기 때로 소급한다(규칙 제146조, 법 제91조)."},{"번호":3,"판정":"틀림","설명":"가등기명의인은 승낙 증명정보 없이 단독으로 말소를 신청한다. 승낙이 필요한 쪽은 가등기의무자·이해관계인이다(법 제93조제1항·제2항)."},{"번호":4,"판정":"틀림","설명":"지상권·전세권·임차권 설정청구권 가등기로 본등기를 해도 저당권설정등기는 직권말소 대상이 아니다(규칙 제148조제2항제4호)."},{"번호":5,"판정":"틀림","설명":"관할은 부동산의 소재지를 관할하는 지방법원이다. 의무자 주소지가 아니다(법 제90조제1항)."}],"개념":[{"종류":"표","제목":"가등기 말소 신청 주체","머리":["신청인","요건","첨부정보"],"행":[["가등기명의인","단독신청","승낙 증명정보 불필요"],["가등기의무자","가등기명의인의 승낙을 받아 단독신청","승낙 또는 대항할 수 있는 재판이 있음을 증명하는 정보"],["등기상 이해관계인","가등기명의인의 승낙을 받아 단독신청","승낙 또는 대항할 수 있는 재판이 있음을 증명하는 정보"],["근거","법 제93조제1항·제2항","규칙 제150조"]]},{"종류":"흐름","제목":"가등기 신청에서 본등기까지","단계":[{"이름":"가등기 신청","설명":"법 제3조 권리의 설정·이전·변경·소멸 청구권 보전. 청구권이 시기부·정지조건부여도 가능. 보전하려는 권리를 신청정보로 제공"},{"이름":"신청 방식","설명":"원칙은 공동신청. 가등기의무자의 승낙이나 가처분명령이 있으면 권리자 단독신청"},{"이름":"가처분명령","설명":"부동산 소재지 관할 지방법원이 권리자 신청과 원인사실 소명으로 결정. 각하 결정에는 즉시항고"},{"이름":"본등기","설명":"가등기의 순위번호를 사용하고 순위는 가등기 순위를 따른다"},{"이름":"직권말소","설명":"가등기 후 본등기 전에 마쳐진 등기로 가등기에 의하여 보전되는 권리를 침해하는 것을 말소하고, 말소된 권리의 명의인에게 통지"}]}],"함정":"④는 소유권 가등기의 직권말소 범위와 섞으면 틀린다. 용익권 설정청구권 가등기는 같은 부분의 용익권만 말소하고 저당권은 남긴다. ③은 누가 말소를 신청하느냐에 따라 승낙 필요 여부가 갈린다. ⑤의 관할은 부동산 소재지다."}},{"i":"S5-2-2-공시법-24","r":"S5","g":3,"c":2,"n":24,"s":"공시법","q":"가등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["청구권이 정지조건부인 경우에도 그 청구권을 보전하기 위한 가등기를 신청할 수 있다.","가등기권리자가 가등기의무자의 승낙을 받아 단독으로 가등기를 신청하는 경우, 그 승낙이 있음을 증명하는 정보를 첨부정보로 제공해야 한다.","가등기를 명하는 가처분명령의 신청을 각하한 결정에 대하여는 불복할 수 없다.","등기관이 가등기에 의한 본등기를 하면서 가등기 이후의 등기를 직권으로 말소하였을 때에는 지체 없이 그 사실을 말소된 권리의 등기명의인에게 통지해야 한다.","가등기명의인은 단독으로 가등기의 말소를 신청할 수 있다."],"a":[3],"L":"시2-5","o":"변형","x":{"한줄":"가등기를 명하는 가처분명령 신청을 각하한 결정에 대하여는 즉시항고를 할 수 있다.","근거":[{"법령":"부동산등기법","조문":"제90조제2항","원문":"제1항의 신청을 각하한 결정에 대하여는 즉시항고(卽時抗告)를 할 수 있다."},{"법령":"부동산등기법","조문":"제88조","원문":"가등기는 제3조 각 호의 어느 하나에 해당하는 권리의 설정, 이전, 변경 또는 소멸의 청구권(請求權)을 보전(保全)하려는 때에 한다. 그 청구권이 시기부(始期附) 또는 정지조건부(停止條件附)일 경우나 그 밖에 장래에 확정될 것인 경우에도 같다."},{"법령":"부동산등기규칙","조문":"제145조제2항","원문":"법 제89조에 따라 가등기권리자가 단독으로 가등기를 신청하는 경우에는 가등기의무자의 승낙이나 가처분명령이 있음을 증명하는 정보를 첨부정보로서 등기소에 제공하여야 한다."},{"법령":"부동산등기법","조문":"제92조제2항","원문":"등기관이 제1항에 따라 가등기 이후의 등기를 말소하였을 때에는 지체 없이 그 사실을 말소된 권리의 등기명의인에게 통지하여야 한다."},{"법령":"부동산등기법","조문":"제93조제1항","원문":"가등기명의인은 제23조제1항에도 불구하고 단독으로 가등기의 말소를 신청할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"정지조건부·시기부 청구권도 가등기 대상이다(법 제88조)."},{"번호":2,"판정":"옳음","설명":"단독신청 때는 승낙 또는 가처분명령을 증명하는 정보를 첨부한다(규칙 제145조제2항)."},{"번호":3,"판정":"틀림","설명":"각하 결정에는 즉시항고를 할 수 있고, 즉시항고에는 비송사건절차법을 준용한다(법 제90조제2항·제3항)."},{"번호":4,"판정":"옳음","설명":"직권말소 뒤에는 말소된 권리의 명의인에게 지체 없이 통지한다(법 제92조제2항)."},{"번호":5,"판정":"옳음","설명":"가등기명의인은 공동신청 원칙의 예외로 단독 말소신청을 할 수 있다(법 제93조제1항)."}],"개념":[{"종류":"흐름","제목":"가등기 단독신청 절차","단계":[{"이름":"승낙 경로","설명":"가등기의무자의 승낙을 받으면 권리자가 단독으로 신청하고 승낙 증명정보를 첨부(규칙 제145조제2항)"},{"이름":"가처분 경로","설명":"가등기의무자가 승낙하지 않으면 부동산 소재지 관할 지방법원에 가처분명령을 신청(법 제90조제1항)"},{"이름":"법원 판단","설명":"원인사실의 소명이 있으면 명령. 각하 결정에는 즉시항고(법 제90조제2항)"},{"이름":"등기 신청","설명":"가처분명령이 있음을 증명하는 정보를 첨부해 권리자가 단독으로 신청"}]},{"종류":"표","제목":"가등기 관련 조문 모음","머리":["항목","내용","근거"],"행":[["대상","법 제3조 권리의 설정·이전·변경·소멸 청구권(시기부·정지조건부 포함)","법 제88조"],["단독신청","의무자 승낙 또는 가처분명령","법 제89조"],["가처분 관할","부동산 소재지 관할 지방법원","법 제90조제1항"],["각하 결정","즉시항고 가능","법 제90조제2항"],["본등기 순위","가등기의 순위","법 제91조"],["직권말소 통지","말소된 권리의 등기명의인에게 지체 없이","법 제92조제2항"]]}],"함정":"가등기를 명하는 가처분은 법원이 가등기 원인사실을 소명받아 결정하는 재판이어서 각하 결정도 항고 대상이 아니라고 단정하기 쉽다. 법은 각하 결정에 즉시항고를 명시한다."}},{"i":"S5-2-2-세법-01","r":"S5","g":3,"c":2,"n":25,"s":"세법","q":"국세기본법령 및 지방세기본법령상 납세의무의 성립 시기에 관한 설명으로 틀린 것은? (단, 원천징수, 예정신고 및 수시부과의 경우는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["토지에 대한 양도소득세: 과세기간이 끝나는 때","주택에 대한 종합부동산세: 과세기준일","전세권설정등기에 대한 등록면허세: 등기하는 때","토지에 대한 재산세: 과세기준일","건축물에 대한 지역자원시설세: 취득하는 때"],"a":[5],"L":"세1-1","o":"기출","x":{"한줄":"건축물에 대한 지역자원시설세는 취득하는 때가 아니라 과세기준일에 납세의무가 성립한다.","근거":[{"법령":"지방세기본법","조문":"제34조제1항제10호아목","원문":"건축물 및 선박: 과세기준일"},{"법령":"지방세기본법","조문":"제34조제1항제2호가목","원문":"등록에 대한 등록면허세: 재산권과 그 밖의 권리를 등기하거나 등록하는 때"},{"법령":"지방세기본법","조문":"제34조제1항제8호","원문":"재산세: 과세기준일"},{"법령":"국세기본법","조문":"제21조제2항제1호","원문":"소득세ㆍ법인세: 과세기간이 끝나는 때."},{"법령":"국세기본법","조문":"제21조제2항제10호","원문":"종합부동산세: 과세기준일"}],"선지":[{"번호":1,"판정":"옳음","설명":"양도소득세는 소득세이므로 과세기간이 끝나는 때 성립한다(국세기본법 제21조 제2항 제1호)."},{"번호":2,"판정":"옳음","설명":"종합부동산세는 과세기준일(6월 1일)에 성립한다(국세기본법 제21조 제2항 제10호, 종합부동산세법 제3조)."},{"번호":3,"판정":"옳음","설명":"등록에 대한 등록면허세는 재산권과 그 밖의 권리를 등기하거나 등록하는 때 성립한다. 전세권설정등기도 같다(지방세기본법 제34조 제1항 제2호 가목)."},{"번호":4,"판정":"옳음","설명":"재산세는 과세기준일에 성립한다(지방세기본법 제34조 제1항 제8호)."},{"번호":5,"판정":"틀림","설명":"지역자원시설세 중 건축물 및 선박분은 과세기준일에 성립한다. 취득하는 때에 성립하는 세목은 취득세다(지방세기본법 제34조 제1항 제1호·제10호 아목)."}],"개념":[{"종류":"표","제목":"세목별 납세의무 성립시기","머리":["세목","성립시기","근거"],"행":[["소득세(양도소득세 포함)·법인세","과세기간이 끝나는 때","국세기본법 제21조제2항제1호"],["종합부동산세","과세기준일","국세기본법 제21조제2항제10호"],["상속세 / 증여세","상속이 개시되는 때 / 증여로 재산을 취득하는 때","국세기본법 제21조제2항제2·3호"],["취득세","과세물건을 취득하는 때","지방세기본법 제34조제1항제1호"],["등록면허세(등록)","재산권과 그 밖의 권리를 등기하거나 등록하는 때","지방세기본법 제34조제1항제2호가목"],["재산세","과세기준일","지방세기본법 제34조제1항제8호"],["지역자원시설세(건축물·선박)","과세기준일","지방세기본법 제34조제1항제10호아목"],["지방교육세","과세표준이 되는 세목의 납세의무가 성립하는 때","지방세기본법 제34조제1항제11호"],["지방소득세","소득세·법인세의 납세의무가 성립하는 때","지방세기본법 제34조제1항제7호"],["자동차세(소유)","납기가 있는 달의 1일","지방세기본법 제34조제1항제9호가목"]]},{"종류":"표","제목":"일반 성립시기의 예외","머리":["구분","성립시기","근거"],"행":[["원천징수하는 소득세·법인세","소득금액 또는 수입금액을 지급하는 때","국세기본법 제21조제3항제1호"],["예정신고납부하는 소득세","과세표준이 되는 금액이 발생한 달의 말일","국세기본법 제21조제3항제2호"],["중간예납하는 소득세·법인세","중간예납기간이 끝나는 때","국세기본법 제21조제3항제3호"],["수시부과하는 국세","수시부과할 사유가 발생한 때","국세기본법 제21조제3항제4호"],["특별징수하는 지방소득세","소득세·법인세를 원천징수하는 때","지방세기본법 제34조제2항제1호"],["수시로 부과하는 지방세","수시부과할 사유가 발생하는 때","지방세기본법 제34조제2항제2호"]]}],"함정":"지역자원시설세 건축물·선박분은 취득이 아니라 보유를 과세요건으로 삼아 과세기준일에 성립한다. 양도소득세는 양도일이 아니라 과세기간이 끝나는 때(12월 31일)에 성립하고, 예정신고납부분만 과세표준 금액이 발생한 달의 말일에 성립한다."}},{"i":"S5-2-2-세법-02","r":"S5","g":3,"c":2,"n":26,"s":"세법","q":"지방세기본법상 가산세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["사기나 그 밖의 부정한 행위로 법정신고기한까지 과세표준 신고를 하지 아니한 경우의 무신고가산세: 무신고납부세액의 100분의 60에 상당하는 금액","법정신고기한까지 신고하였으나 사기나 그 밖의 부정한 행위 없이 납부세액을 적게 신고한 경우의 과소신고가산세: 과소신고납부세액등의 100분의 20에 상당하는 금액","사기나 그 밖의 부정한 행위로 과소신고한 경우의 가산세: 부정과소신고납부세액등의 100분의 20에 상당하는 금액","납세고지서에 따른 납부기한까지 납부하지 아니한 세액에 대한 납부지연가산세: 그 납부하지 아니한 세액(가산세 제외)의 100분의 3에 상당하는 금액","법정납부기한의 다음 날부터 자진납부일까지의 일수에 따라 계산하는 납부지연가산세: 납부하지 아니한 세액의 100분의 50을 한도로 하는 금액"],"a":[4],"L":"세1-1","o":"변형","x":{"한줄":"납세고지서에 따른 납부기한까지 납부하지 않은 세액에는 그 세액의 100분의 3이 납부지연가산세로 붙는다.","근거":[{"법령":"지방세기본법","조문":"제53조제2항","원문":"제1항에도 불구하고 사기나 그 밖의 부정한 행위로 법정신고기한까지 과세표준 신고를 하지 아니한 경우에는 무신고납부세액의 100분의 40에 상당하는 금액을 가산세로 부과한다."},{"법령":"지방세기본법","조문":"제54조제1항","원문":"과소신고한 납부세액과 초과환급신고한 환급세액을 합한 금액(이 법과 지방세관계법에 따른 가산세와 가산하여 납부하여야 할 이자상당액이 있는 경우 그 금액은 제외하며, 이하 \"과소신고납부세액등\"이라 한다)의 100분의 10에 상당하는 금액을 가산세로 부과한다."},{"법령":"지방세기본법","조문":"제54조제2항제1호·제2호","원문":"1. 사기나 그 밖의 부정한 행위로 인한 과소신고납부세액등(이하 \"부정과소신고납부세액등\"이라 한다)의 100분의 40에 상당하는 금액\n2. 과소신고납부세액등에서 부정과소신고납부세액등을 뺀 금액의 100분의 10에 상당하는 금액"},{"법령":"지방세기본법","조문":"제55조제1항제3호","원문":"납세고지서에 따른 납부기한까지 납부하지 아니한 세액 또는 과소납부분 세액(지방세관계법에 따라 가산하여 납부하여야 할 이자상당액이 있는 경우 그 금액을 더하고, 가산세는 제외한다) × 100분의 3"},{"법령":"지방세기본법","조문":"제55조제1항 후단","원문":"이 경우 제1호 및 제2호의 가산세는 납부하지 아니한 세액, 과소납부분(납부하여야 할 금액에 미달하는 금액을 말한다. 이하 같다) 세액 또는 초과환급분(환급받아야 할 세액을 초과하는 금액을 말한다. 이하 같다) 세액의 100분의 75에 해당하는 금액을 한도로 하고,"}],"선지":[{"번호":1,"판정":"틀림","설명":"부정행위로 무신고한 경우의 무신고가산세는 무신고납부세액의 100분의 40이다(지방세기본법 제53조 제2항). 일반 무신고는 100분의 20이다(같은 조 제1항)."},{"번호":2,"판정":"틀림","설명":"부정행위가 없는 과소신고가산세는 과소신고납부세액등의 100분의 10이다(지방세기본법 제54조 제1항)."},{"번호":3,"판정":"틀림","설명":"부정과소신고납부세액등의 100분의 40에 더해, 과소신고납부세액등에서 부정분을 뺀 금액의 100분의 10을 합산해 부과한다(지방세기본법 제54조 제2항)."},{"번호":4,"판정":"옳음","설명":"납세고지서에 따른 납부기한까지 내지 않은 세액에는 100분의 3이 붙는다. 이 금액은 납부지연가산세 제3호에 해당한다(지방세기본법 제55조 제1항 제3호)."},{"번호":5,"판정":"틀림","설명":"일수에 따라 계산하는 제1호·제2호 가산세의 한도는 납부하지 아니한 세액 등의 100분의 75다(지방세기본법 제55조 제1항 후단)."}],"개념":[{"종류":"표","제목":"지방세기본법상 가산세 한눈에 보기","머리":["가산세","요건","가산율·금액","근거"],"행":[["무신고가산세","일반","무신고납부세액의 100분의 20","제53조제1항"],["무신고가산세","사기나 그 밖의 부정한 행위","무신고납부세액의 100분의 40","제53조제2항"],["과소신고·초과환급신고가산세","일반","과소신고납부세액등의 100분의 10","제54조제1항"],["과소신고·초과환급신고가산세","부정행위 포함","부정분의 100분의 40 + 나머지의 100분의 10","제54조제2항"],["납부지연가산세","법정납부기한 다음 날부터 자진납부일·납세고지일까지","미납세액 × 일수 × 1일 10만분의 22","제55조제1항제1호, 시행령 제34조제1항"],["납부지연가산세","납세고지서의 납부기한까지 미납","미납세액의 100분의 3","제55조제1항제3호"],["납부지연가산세","납세고지서의 납부기한이 지난 날부터 1개월마다","미납세액 × 월 1만분의 66","제55조제1항제4호, 시행령 제34조제2항"]]},{"종류":"흐름","제목":"납부지연가산세가 붙는 순서와 한도","단계":[{"이름":"법정납부기한 경과","설명":"신고납부 세목은 법정납부기한 다음 날부터 자진납부일 또는 납세고지일까지 매일 1일 10만분의 22를 곱한다(제1호)."},{"이름":"납세고지서 납부기한 경과","설명":"고지서의 납부기한까지 내지 않은 세액에 100분의 3을 한 번 더한다(제3호)."},{"이름":"이후 1개월마다","설명":"고지서 납부기한이 지난 날부터 1개월이 지날 때마다 월 1만분의 66을 곱한다(제4호). 60개월을 넘길 수 없다."},{"이름":"한도와 배제","설명":"제1호·제2호 가산세는 미납세액의 100분의 75까지다. 납세고지서별·세목별 세액이 45만원 미만이면 제4호 가산세를 적용하지 않는다(제55조제4항)."}]}],"함정":"가산율이 붙는 자리가 제각각이다. 20%는 일반 무신고, 40%는 부정 무신고와 부정 과소신고의 부정분, 10%는 일반 과소신고와 부정 과소신고의 나머지 금액, 3%는 고지서 납부기한 경과분, 75%는 일수 기준 가산세의 한도다. 부정 과소신고는 40%만 붙는 것이 아니라 나머지 금액에 10%가 더 붙는다.","개정":"옛 기출의 납부불성실가산세는 현행 지방세기본법 제55조에서 납부지연가산세로 규정되어 있다(제55조 <개정 2020.12.29> 표시)."}},{"i":"S5-2-2-세법-03","r":"S5","g":3,"c":2,"n":27,"s":"세법","q":"지방세법령상 취득세에 관한 설명으로 틀린 것은? (단, 지방세특례제한법령은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["대한민국 정부기관의 취득에 대하여 과세하는 외국정부의 취득에 대해서는 취득세를 부과한다.","토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다.","국가에 귀속의 반대급부로 영리법인이 국가 소유의 부동산을 무상으로 양여받는 경우에는 취득세를 부과하지 아니한다.","영리법인이 취득한 임시흥행장의 존속기간이 1년을 초과하는 경우에는 취득세를 부과한다.","신탁(｢신탁법｣에 따른 신탁으로서 신탁등기가 병행되는 것만 해당한다)으로 인한 신탁재산의 취득 중 주택조합등과 조합원 간의 부동산 취득에 대해서는 취득세를 부과한다."],"a":[3],"L":"세2-1","o":"기출","x":{"한줄":"국가에 귀속시키는 조건으로 취득하더라도 그 반대급부로 국가 소유 부동산을 무상으로 양여받는 부분에는 취득세를 부과한다.","근거":[{"법령":"지방세법","조문":"제9조제2항제2호","원문":"국가등에 귀속등의 반대급부로 국가등이 소유하고 있는 부동산 및 사회기반시설을 무상으로 양여받거나 기부채납 대상물의 무상사용권을 제공받는 경우"},{"법령":"지방세법","조문":"제9조제1항 단서","원문":"다만, 대한민국 정부기관의 취득에 대하여 과세하는 외국정부의 취득에 대해서는 취득세를 부과한다."},{"법령":"지방세법","조문":"제7조제4항","원문":"선박, 차량과 기계장비의 종류를 변경하거나 토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다."},{"법령":"지방세법","조문":"제9조제5항","원문":"임시흥행장, 공사현장사무소 등(제13조제5항에 따른 과세대상은 제외한다) 임시건축물의 취득에 대하여는 취득세를 부과하지 아니한다. 다만, 존속기간이 1년을 초과하는 경우에는 취득세를 부과한다."},{"법령":"지방세법","조문":"제9조제3항 단서","원문":"다만, 신탁재산의 취득 중 주택조합등과 조합원 간의 부동산 취득 및 주택조합등의 비조합원용 부동산 취득은 제외한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"외국정부의 취득은 비과세가 원칙이다. 대한민국 정부기관의 취득에 과세하는 외국정부의 취득은 과세한다(지방세법 제9조 제1항 단서)."},{"번호":2,"판정":"옳음","설명":"토지의 지목을 사실상 변경해 가액이 증가하면 취득으로 본다. 가액이 줄어든 변경은 취득이 아니다(지방세법 제7조 제4항)."},{"번호":3,"판정":"틀림","설명":"귀속·기부채납을 조건으로 한 취득은 비과세이나, 그 반대급부로 국가 소유 부동산을 무상 양여받는 부분은 취득세를 부과한다(지방세법 제9조 제2항 제2호)."},{"번호":4,"판정":"옳음","설명":"임시건축물은 비과세이나 존속기간이 1년을 초과하면 취득세를 부과한다(지방세법 제9조 제5항 단서)."},{"번호":5,"판정":"옳음","설명":"신탁등기가 병행되는 신탁의 취득은 비과세 유형이 있으나, 주택조합등과 조합원 간 부동산 취득은 제외되어 과세한다(지방세법 제9조 제3항 단서)."}],"개념":[{"종류":"표","제목":"취득세 비과세와 그 예외(제9조)","머리":["비과세 대상","비과세 범위","과세되는 예외"],"행":[["국가·지방자치단체·지방자치단체조합·외국정부·주한국제기구","취득 전부","대한민국 정부기관의 취득에 과세하는 외국정부"],["국가등에 귀속·기부채납을 조건으로 취득하는 부동산","취득 전부","조건 불이행 후 매각·증여, 반대급부로 국가 소유 부동산을 무상 양여받거나 기부채납 대상물의 무상사용권을 제공받는 부분"],["신탁등기가 병행되는 신탁","위탁자→수탁자 이전, 신탁 종료로 수탁자→위탁자 이전, 수탁자 변경에 따른 이전","주택조합등과 조합원 간 취득, 주택조합등의 비조합원용 부동산 취득"],["임시흥행장·공사현장사무소 등 임시건축물","존속기간 1년 이하","존속기간 1년 초과"],["공동주택 개수(대수선 제외)","개수 취득 당시 시가표준액 9억원 이하 주택","시가표준액 9억원 초과 주택"]]},{"종류":"표","제목":"취득으로 보는 경우(간주취득)","머리":["유형","취득으로 보는 내용","누가 취득하나"],"행":[["지목변경","토지 지목을 사실상 변경해 가액이 증가한 경우","토지 소유자"],["과점주주","법인 주식·지분을 취득해 과점주주가 된 경우(법인 설립 시 발행 주식 취득은 제외)","과점주주"],["배우자·직계존비속 취득","배우자 또는 직계존비속의 부동산등을 취득하면 증여로 봄(공매·교환·대가 지급 입증은 유상)","취득자"],["부담부증여","증여자의 채무를 인수한 부분은 유상, 나머지는 무상","수증자"],["신탁 위탁자 지위 이전","새로운 위탁자가 신탁재산을 취득한 것으로 봄","새로운 위탁자"],["주택조합 조합원용 부동산","조합원이 취득한 것으로 봄","조합원"]]}],"함정":"③은 귀속 조건 취득의 비과세 원칙과 반대급부 무상 양여 과세 단서가 한 조항에 함께 있다. 단서를 놓치면 옳은 문장으로 읽힌다. ⑤는 신탁 비과세 유형 가운데 주택조합등과 조합원 간 취득이 단서로 빠져 과세된다."}},{"i":"S5-2-2-세법-04","r":"S5","g":3,"c":2,"n":28,"s":"세법","q":"지방세법상 취득세의 부과ㆍ징수에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["취득세의 징수는 보통징수의 방법으로 한다.","상속으로 취득세 과세물건을 취득한 자는 상속개시일부터 60일 이내에 산출한 세액을 신고하고 납부하여야 한다.","신고ㆍ납부기한 이내에 재산권과 그 밖의 권리의 취득ㆍ이전에 관한 사항을 공부에 등기하거나 등록(등재 포함)하려는 경우에는 등기 또는 등록 신청서를 등기ㆍ등록관서에 접수하는 날까지 취득세를 신고ㆍ납부하여야 한다.","취득세 과세물건을 취득한 후에 그 과세물건이 중과 세율의 적용대상이 되었을 때에는 중과 세율을 적용하여 산출한 세액에서 이미 납부한 세액(가산세 포함)을 공제한 금액을 세액으로 하여 신고ㆍ납부하여야 한다.","법인의 취득당시가액을 증명할 수 있는 장부가 없는 경우 지방자치단체의 장은 그 산출된 세액의 100분의 20을 징수하여야 할 세액에 가산한다."],"a":[3],"L":"세2-1","o":"기출","x":{"한줄":"신고·납부기한 안에 등기·등록하려면 등기·등록 신청서를 접수하는 날까지 취득세를 신고·납부해야 한다.","근거":[{"법령":"지방세법","조문":"제20조제4항","원문":"제1항부터 제3항까지의 신고ㆍ납부기한 이내에 재산권과 그 밖의 권리의 취득ㆍ이전에 관한 사항을 공부(公簿)에 등기하거나 등록[등재(登載)를 포함한다. 이하 같다]하려는 경우에는 등기 또는 등록 신청서를 등기ㆍ등록관서에 접수하는 날까지 취득세를 신고ㆍ납부하여야 한다."},{"법령":"지방세법","조문":"제18조","원문":"취득세의 징수는 신고납부의 방법으로 한다."},{"법령":"지방세법","조문":"제20조제1항","원문":"상속으로 인한 경우는 상속개시일이 속하는 달의 말일부터, 실종으로 인한 경우는 실종선고일이 속하는 달의 말일부터 각각 6개월(외국에 주소를 둔 상속인이 있는 경우에는 각각 9개월)"},{"법령":"지방세법","조문":"제20조제2항","원문":"이미 납부한 세액(가산세는 제외한다)을 공제한 금액을 세액으로 하여 대통령령으로 정하는 바에 따라 신고하고 납부하여야 한다."},{"법령":"지방세법","조문":"제22조의2제2항","원문":"지방자치단체의 장은 취득세 납세의무가 있는 법인이 제1항에 따른 의무를 이행하지 아니하는 경우에는 산출된 세액 또는 부족세액의 100분의 10에 상당하는 금액을 징수하여야 할 세액에 가산한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"취득세는 신고납부 방식으로 징수한다(지방세법 제18조). 보통징수는 제20조에 따른 신고·납부의무를 다하지 않았을 때 부족세액과 가산세를 걷는 방법이다(제21조 제1항)."},{"번호":2,"판정":"틀림","설명":"상속은 상속개시일이 속하는 달의 말일부터 6개월 이내다. 외국에 주소를 둔 상속인이 있으면 9개월이다. 60일은 유상 취득 등 일반 기한이다(지방세법 제20조 제1항)."},{"번호":3,"판정":"옳음","설명":"신고·납부기한 이내에 등기·등록하려면 신청서를 접수하는 날까지 신고·납부해야 한다(지방세법 제20조 제4항)."},{"번호":4,"판정":"틀림","설명":"중과세율 적용대상이 된 때에는 이미 납부한 세액에서 가산세를 제외하고 공제한다(지방세법 제20조 제2항)."},{"번호":5,"판정":"틀림","설명":"장부를 갖추지 않은 법인에는 산출세액 또는 부족세액의 100분의 10을 가산한다(지방세법 제22조의2 제2항)."}],"개념":[{"종류":"흐름","제목":"취득세 신고·납부 절차","단계":[{"이름":"취득","설명":"과세물건을 취득한 날이 기산점이다. 토지거래허가구역 토지는 허가 전에 대금을 완납했다면 허가일이 기산점이다."},{"이름":"신고·납부","설명":"일반 취득은 60일 이내, 무상취득(상속 제외)과 부담부증여는 취득일이 속하는 달의 말일부터 3개월, 상속·실종은 6개월(외국 주소 상속인이 있으면 9개월) 이내에 신고하고 낸다."},{"이름":"등기·등록이 먼저인 경우","설명":"기한 안에 등기·등록하려면 등기·등록 신청서를 접수하는 날까지 신고·납부한다(제20조제4항)."},{"이름":"사후 변동","설명":"중과세율 적용대상이 되거나 비과세·감면 뒤 추징사유가 생기면 사유 발생일부터 60일 이내에 차액을 신고·납부한다. 공제하는 기납부세액에서 가산세는 뺀다(제20조제2항·제3항)."},{"이름":"불이행 시 징수","설명":"신고·납부의무를 다하지 않으면 산출세액 또는 부족세액에 가산세를 더해 보통징수한다(제21조제1항). 신고 없이 매각하면 산출세액에 100분의 80을 가산한다(제21조제2항)."}]},{"종류":"표","제목":"취득세 신고·납부 기한과 가산 규정","머리":["구분","기한·가산","근거"],"행":[["유상취득 등 일반","취득한 날부터 60일 이내","제20조제1항"],["무상취득(상속 제외)·부담부증여","취득일이 속하는 달의 말일부터 3개월 이내","제20조제1항"],["상속","상속개시일이 속하는 달의 말일부터 6개월(외국 주소 상속인 있으면 9개월)","제20조제1항"],["실종","실종선고일이 속하는 달의 말일부터 6개월(외국 주소 상속인 있으면 9개월)","제20조제1항"],["중과세율 적용대상이 된 경우","대통령령이 정하는 날부터 60일 이내, 기납부세액(가산세 제외) 공제","제20조제2항"],["법인이 취득당시가액 장부를 갖추지 않은 경우","산출세액 또는 부족세액의 100분의 10 가산","제22조의2제2항"],["신고 없이 사실상 취득 후 매각","산출세액에 100분의 80 가산","제21조제2항"]]}],"함정":"②는 60일이라는 일반 기한을 상속에 그대로 적용한 문장이다. 상속은 6개월, 외국 주소 상속인이 있으면 9개월이다. ⑤의 20%는 일반 무신고가산세율이고 장부 미비 가산율은 10%다. ①은 징수방법을 보통징수로 바꿔 놓았다."}},{"i":"S5-2-2-세법-05","r":"S5","g":3,"c":2,"n":29,"s":"세법","q":"지방세법령상 등록에 대한 등록면허세에 관한 설명으로 틀린 것은? (단, 지방세관계법령상 감면 및 특례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["같은 등록에 관계되는 재산이 둘 이상의 지방자치단체에 걸쳐 있어 등록면허세를 지방자치단체별로 부과할 수 없을 때에는 등록관청 소재지를 납세지로 한다.","지방자치단체의 장은 조례로 정하는 바에 따라 등록면허세의 세율을 부동산 등기에 따른 표준세율의 100분의 50의 범위에서 가감할 수 있다.","주택의 토지와 건축물을 한꺼번에 평가하여 토지나 건축물에 대한 과세표준이 구분되지 아니하는 경우에는 한꺼번에 평가한 개별주택가격을 토지나 건축물의 가액비율로 나눈 금액을 각각 토지와 건축물의 과세표준으로 한다.","부동산의 등록에 대한 등록면허세의 과세표준은 등록자가 신고한 당시의 가액으로 하고, 신고가 없거나 신고가액이 시가표준액보다 많은 경우에는 시가표준액으로 한다.","채권자대위자는 납세의무자를 대위하여 부동산의 등기에 대한 등록면허세를 신고납부할 수 있다."],"a":[4],"L":"세2-2","o":"기출","x":{"한줄":"신고가 없거나 신고가액이 시가표준액보다 적으면 시가표준액이 과세표준이다. 신고가액이 시가표준액보다 많은 경우는 신고가액을 따른다.","근거":[{"법령":"지방세법","조문":"제27조제2항","원문":"제1항에 따른 과세표준은 조례로 정하는 바에 따라 등록자의 신고에 따른다. 다만, 신고가 없거나 신고가액이 제4조에 따른 시가표준액보다 적은 경우에는 시가표준액을 과세표준으로 한다."},{"법령":"지방세법","조문":"제25조제1항제16호","원문":"같은 등록에 관계되는 재산이 둘 이상의 지방자치단체에 걸쳐 있어 등록면허세를 지방자치단체별로 부과할 수 없을 때에는 등록관청 소재지를 납세지로 한다."},{"법령":"지방세법","조문":"제28조제6항","원문":"지방자치단체의 장은 조례로 정하는 바에 따라 등록면허세의 세율을 제1항제1호에 따른 표준세율의 100분의 50의 범위에서 가감할 수 있다."},{"법령":"지방세법 시행령","조문":"제42조제2항","원문":"주택의 토지와 건축물을 한꺼번에 평가하여 토지나 건축물에 대한 과세표준이 구분되지 아니하는 경우에는 한꺼번에 평가한 개별주택가격을 토지나 건축물의 가액 비율로 나눈 금액을 각각 토지와 건축물의 과세표준으로 한다."},{"법령":"지방세법","조문":"제30조제5항","원문":"채권자대위자는 납세의무자를 대위하여 부동산의 등기에 대한 등록면허세를 신고납부할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"재산이 둘 이상의 지방자치단체에 걸쳐 따로 부과할 수 없으면 등록관청 소재지가 납세지다(지방세법 제25조 제1항 제16호)."},{"번호":2,"판정":"옳음","설명":"조례로 부동산 등기 표준세율의 100분의 50 범위에서 가감할 수 있다(지방세법 제28조 제6항)."},{"번호":3,"판정":"옳음","설명":"주택의 토지와 건축물이 한꺼번에 평가되어 구분되지 않으면 개별주택가격을 가액 비율로 나눠 각각의 과세표준으로 한다(지방세법 시행령 제42조 제2항)."},{"번호":4,"판정":"틀림","설명":"신고가 없거나 신고가액이 시가표준액보다 적은 경우에 시가표준액을 과세표준으로 한다. 신고가액이 시가표준액보다 많으면 신고가액이다(지방세법 제27조 제2항)."},{"번호":5,"판정":"옳음","설명":"채권자대위자는 납세의무자를 대위해 부동산 등기의 등록면허세를 신고납부할 수 있다. 지방자치단체의 장은 이를 납세의무자에게 즉시 통보한다(지방세법 제30조 제5항·제6항)."}],"개념":[{"종류":"표","제목":"부동산 등기 등록면허세 표준세율(제28조제1항제1호)","머리":["등기","과세표준","세율"],"행":[["소유권 보존","부동산 가액","1천분의 8"],["소유권 이전(유상)","부동산 가액","1천분의 20(유상 주택은 주택 취득세율의 100분의 50)"],["소유권 이전(무상)","부동산 가액","1천분의 15"],["소유권 이전(상속)","부동산 가액","1천분의 8"],["지상권","부동산 가액","1천분의 2"],["저당권","채권금액","1천분의 2"],["지역권","요역지 가액","1천분의 2"],["전세권","전세금액","1천분의 2"],["임차권","월 임대차금액","1천분의 2"],["경매신청·가압류·가처분","채권금액","1천분의 2"],["가등기","부동산 가액 또는 채권금액","1천분의 2"],["그 밖의 등기","건당","6천원"]]},{"종류":"표","제목":"등기·등록 등록면허세 납세지(제25조제1항)","머리":["등기·등록","납세지"],"행":[["부동산 등기","부동산 소재지"],["선박 등기·등록","선적항 소재지"],["법인 등기","등기에 관련되는 본점·지점 또는 주사무소·분사무소 등의 소재지"],["상호 등기","영업소 소재지"],["광업권 및 조광권 등록","광구 소재지"],["그 밖의 등록","등록관청 소재지"],["재산이 둘 이상의 지방자치단체에 걸쳐 따로 부과할 수 없는 경우","등록관청 소재지"],["같은 채권 담보를 위한 둘 이상의 저당권 등록","하나의 등록으로 보아 처음 등록하는 등록관청 소재지"]]}],"함정":"④는 비교 방향을 바꾼 문장이다. 시가표준액은 신고가액의 하한이라서 신고가액이 더 크면 신고가액이 과세표준이 된다."}},{"i":"S5-2-2-세법-06","r":"S5","g":3,"c":2,"n":30,"s":"세법","q":"지방세법상 재산세 비과세 대상에 해당하는 것은? (단, 수익사업에 사용하거나 유료로 사용하는 재산은 아니며, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["국가가 1년 이상 공용으로 사용하는 재산으로서 소유권의 유상이전을 약정하고 그 재산을 취득하기 전에 미리 사용하는 재산","「군사기지 및 군사시설 보호법」에 따른 군사기지 및 군사시설 보호구역 중 통제보호구역에 있는 과수원","「도로법」에 따른 도로의 부속물 중 주유소","「도로법」에 따른 도로 중 「건축법 시행령」 제80조의2에 따른 대지 안의 공지","「산림보호법」에 따라 지정된 산림보호구역"],"a":[5],"L":"세2-3","o":"변형","x":{"한줄":"「산림보호법」에 따라 지정된 산림보호구역은 재산세를 부과하지 않는 토지다.","근거":[{"법령":"지방세법","조문":"제109조제3항제2호","원문":"「산림보호법」 제7조에 따른 산림보호구역, 그 밖에 공익상 재산세를 부과하지 아니할 타당한 이유가 있는 것으로서 대통령령으로 정하는 토지"},{"법령":"지방세법 시행령","조문":"제108조제2항제2호","원문":"「산림보호법」에 따라 지정된 산림보호구역 및 「산림자원의 조성 및 관리에 관한 법률」에 따라 지정된 채종림ㆍ시험림"},{"법령":"지방세법","조문":"제109조제2항","원문":"국가, 지방자치단체 또는 지방자치단체조합이 1년 이상 공용 또는 공공용으로 사용(1년 이상 사용할 것이 계약서 등에 의하여 입증되는 경우를 포함한다)하는 재산에 대하여는 재산세를 부과하지 아니한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 재산세를 부과한다.\n1. 유료로 사용하는 경우\n2. 소유권의 유상이전을 약정한 경우로서 그 재산을 취득하기 전에 미리 사용하는 경우"},{"법령":"지방세법 시행령","조문":"제108조제2항제1호","원문":"「군사기지 및 군사시설 보호법」에 따른 군사기지 및 군사시설 보호구역 중 통제보호구역에 있는 토지. 다만, 전ㆍ답ㆍ과수원 및 대지는 제외한다."},{"법령":"지방세법 시행령","조문":"제108조제1항제1호","원문":"도로: 「도로법」에 따른 도로(같은 법 제2조제2호에 따른 도로의 부속물 중 도로관리시설, 휴게시설, 주유소, 충전소, 교통ㆍ관광안내소 및 도로에 연접하여 설치한 연구시설은 제외한다)와 그 밖에 일반인의 자유로운 통행을 위하여 제공할 목적으로 개설한 사설 도로. 다만, 「건축법 시행령」 제80조의2에 따른 대지 안의 공지는 제외한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국가가 1년 이상 공용으로 쓰는 재산은 비과세이나, 유상이전을 약정하고 취득 전에 미리 사용하는 경우는 재산세를 부과한다(지방세법 제109조 제2항 제2호)."},{"번호":2,"판정":"틀림","설명":"통제보호구역의 토지는 비과세이나 전·답·과수원·대지는 제외되어 과세한다(지방세법 시행령 제108조 제2항 제1호)."},{"번호":3,"판정":"틀림","설명":"도로의 부속물 중 주유소는 비과세 도로에서 제외된다(지방세법 시행령 제108조 제1항 제1호)."},{"번호":4,"판정":"틀림","설명":"「건축법 시행령」 제80조의2에 따른 대지 안의 공지는 비과세 도로에서 제외된다(지방세법 시행령 제108조 제1항 제1호 단서)."},{"번호":5,"판정":"옳음","설명":"산림보호구역과 채종림·시험림은 비과세 토지다(지방세법 제109조 제3항 제2호, 시행령 제108조 제2항 제2호)."}],"개념":[{"종류":"표","제목":"재산세 비과세 구분(제109조)","머리":["구분","비과세","과세로 돌아가는 경우"],"행":[["소유자 기준","국가·지방자치단체·지방자치단체조합·외국정부·주한국제기구 소유 재산","대한민국 정부기관 재산에 과세하는 외국정부 재산, 연부매매로 무상사용권을 받은 매수계약자의 재산"],["사용 기준","국가·지방자치단체·지방자치단체조합이 1년 이상 공용·공공용으로 사용하는 재산","유료 사용, 유상이전 약정 후 취득 전에 미리 사용"],["용도 기준","도로·하천·제방·구거·유지·묘지, 산림보호구역 등","대통령령이 정하는 수익사업 사용, 유료 사용, 일부가 목적에 직접 사용되지 않는 부분"],["임시건축물","과세기준일 현재 존속기간 1년 미만","1년 이상"],["철거 예정","철거명령을 받았거나 철거보상계약이 체결된 건축물·주택의 건축물 부분","건축물 부분이 아닌 부속토지"]]},{"종류":"표","제목":"비과세 토지 세부 범위(시행령 제108조)","머리":["구분","비과세","제외(과세)"],"행":[["도로","「도로법」에 따른 도로, 일반인 통행용 사설 도로","도로 부속물 중 도로관리시설·휴게시설·주유소·충전소·교통·관광안내소·연접 연구시설, 건축법상 대지 안의 공지"],["하천","「하천법」 하천, 「소하천정비법」 소하천","-"],["제방","「공간정보의 구축 및 관리 등에 관한 법률」에 따른 제방","특정인이 전용하는 제방"],["구거","농업용 구거, 자연유수의 배수처리에 제공하는 구거","-"],["유지","농업용·발전용 댐·저수지·소류지, 자연 형성 호수·늪","-"],["묘지","지목이 묘지인 토지(무덤과 부속시설물 부지)","-"],["통제보호구역","통제보호구역에 있는 토지","전·답·과수원·대지"],["산림 등","산림보호구역, 채종림·시험림, 공원자연보존지구 임야, 백두대간보호지역 임야","-"]]}],"함정":"비과세 항목마다 제외 단서가 붙어 있다. 주유소와 대지 안의 공지는 도로에서 빠지고, 통제보호구역은 전·답·과수원·대지가 빠진다. 국가가 사용하는 재산도 유료 사용이거나 취득 전에 미리 사용하는 경우에는 과세한다."}},{"i":"S5-2-2-세법-07","r":"S5","g":3,"c":2,"n":31,"s":"세법","q":"지방세법상 재산세의 물납과 분할납부에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["재산세의 납부세액이 1천만원을 초과하는 경우 납세의무자의 신청을 받아 해당 지방자치단체의 관할구역에 있는 부동산에 대하여만 물납을 허가할 수 있다.","재산세를 물납하려는 자는 행정안전부령으로 정하는 서류를 갖추어 그 납부기한 5일 전까지 납세지를 관할하는 시장ㆍ군수ㆍ구청장에게 신청하여야 한다.","물납을 허가하는 부동산의 가액은 재산세 과세기준일 현재의 시가로 한다. 토지 및 주택의 시가는 수용ㆍ공매가액 등으로서 시가로 인정되는 경우를 제외하고 시가표준액에 따른다.","물납 불허가 통지를 받은 납세의무자가 그 통지를 받은 날부터 10일 이내에 해당 시ㆍ군ㆍ구의 관할구역에 있는 관리ㆍ처분이 가능한 다른 부동산으로 변경 신청하는 경우에는 변경하여 허가할 수 있다.","재산세의 납부할 세액이 500만원을 초과하는 경우에는 그 세액의 100분의 50 이하의 금액을 납부기한이 지난 날부터 3개월 이내에 분할납부하게 할 수 있다."],"a":[2],"L":"세2-3","o":"변형","x":{"한줄":"재산세를 물납하려면 납부기한 10일 전까지 시장·군수·구청장에게 신청해야 한다.","근거":[{"법령":"지방세법 시행령","조문":"제113조제1항","원문":"법 제117조에 따라 재산세를 물납(物納)하려는 자는 행정안전부령으로 정하는 서류를 갖추어 그 납부기한 10일 전까지 납세지를 관할하는 시장ㆍ군수ㆍ구청장에게 신청하여야 한다."},{"법령":"지방세법","조문":"제117조","원문":"지방자치단체의 장은 재산세의 납부세액이 1천만원을 초과하는 경우에는 납세의무자의 신청을 받아 해당 지방자치단체의 관할구역에 있는 부동산에 대하여만 대통령령으로 정하는 바에 따라 물납을 허가할 수 있다."},{"법령":"지방세법 시행령","조문":"제115조제1항","원문":"제113조제2항 및 제114조제2항에 따라 물납을 허가하는 부동산의 가액은 재산세 과세기준일 현재의 시가로 한다."},{"법령":"지방세법 시행령","조문":"제114조제2항","원문":"시장ㆍ군수ㆍ구청장은 제1항 및 제113조제2항에 따라 불허가 통지를 받은 납세의무자가 그 통지를 받은 날부터 10일 이내에 해당 시ㆍ군ㆍ구의 관할구역에 있는 부동산으로서 관리ㆍ처분이 가능한 다른 부동산으로 변경 신청하는 경우에는 변경하여 허가할 수 있다."},{"법령":"지방세법 시행령","조문":"제116조제1항제2호","원문":"납부할 세액이 500만원을 초과하는 경우: 그 세액의 100분의 50 이하의 금액"}],"선지":[{"번호":1,"판정":"옳음","설명":"납부세액이 1천만원을 초과해야 물납을 허가할 수 있고, 그 지방자치단체 관할구역 안의 부동산만 대상이다(지방세법 제117조)."},{"번호":2,"판정":"틀림","설명":"물납 신청은 납부기한 10일 전까지다(지방세법 시행령 제113조 제1항). 5일은 신청을 받은 시장·군수·구청장이 허가 여부를 서면으로 통지하는 기한이다(같은 조 제2항)."},{"번호":3,"판정":"옳음","설명":"물납 부동산의 가액은 과세기준일 현재의 시가이고, 토지·주택은 시가표준액을 시가로 본다. 수용·공매가액 등으로 시가로 인정되는 것은 시가로 본다(지방세법 시행령 제115조 제1항·제2항)."},{"번호":4,"판정":"옳음","설명":"불허가 통지를 받은 날부터 10일 이내에 같은 시·군·구의 다른 부동산으로 변경 신청하면 변경하여 허가할 수 있다(지방세법 시행령 제114조 제2항)."},{"번호":5,"판정":"옳음","설명":"분할납부는 납부세액이 250만원을 초과할 때 가능하고, 500만원 초과분은 세액의 100분의 50 이하의 금액을 납부기한이 지난 날부터 3개월 이내에 나눠 낸다(지방세법 제118조, 시행령 제116조 제1항 제2호)."}],"개념":[{"종류":"흐름","제목":"재산세 물납 절차","단계":[{"이름":"요건","설명":"재산세 납부세액이 1천만원 초과, 대상은 그 지방자치단체 관할구역 안의 부동산(제117조)."},{"이름":"신청","설명":"행정안전부령 서류를 갖춰 납부기한 10일 전까지 납세지 관할 시장·군수·구청장에게 신청(시행령 제113조제1항)."},{"이름":"허가 통지","설명":"신청받은 날부터 5일 이내에 허가 여부를 서면으로 통지(시행령 제113조제2항)."},{"이름":"불허가 시 변경 신청","설명":"통지받은 날부터 10일 이내에 같은 시·군·구의 관리·처분 가능한 다른 부동산으로 변경 신청(시행령 제114조제2항)."},{"이름":"평가와 납부","설명":"과세기준일 현재 시가로 평가해 물납하면 납부기한 내에 납부한 것으로 본다(시행령 제113조제3항·제115조)."}]},{"종류":"비교","제목":"물납과 분할납부","왼쪽":{"이름":"물납","항목":["납부세액 1천만원 초과","그 지방자치단체 관할구역 안의 부동산만","납부기한 10일 전까지 신청","신청일부터 5일 이내 허가 여부 통지","물납하면 납부기한 내 납부한 것으로 봄"]},"오른쪽":{"이름":"분할납부","항목":["납부세액 250만원 초과","500만원 이하는 250만원 초과액, 500만원 초과는 세액의 100분의 50 이하 금액","납부기한이 지난 날부터 3개월 이내","납부기한까지 신청서를 시장·군수·구청장에게 제출","신청받은 뒤 납세고지서를 구분해 수정 고지"]}}],"함정":"5일과 10일이 서로 바뀐 선지다. 신청은 납부기한 10일 전, 허가 통지는 신청일부터 5일 이내다. 문턱 금액은 물납이 1천만원 초과, 분할납부가 250만원 초과로 다르다."}},{"i":"S5-2-2-세법-08","r":"S5","g":3,"c":2,"n":32,"s":"세법","q":"지방세법상 2026년도 귀속 재산세의 부과·징수에 관한 설명으로 틀린 것은? (단, 세액변경이나 수시부과사유는 없음)","b":null,"bs":"없음","img":[],"ch":["토지분 재산세의 납기는 매년 9월 16일부터 9월 30일까지이다.","항공기분 재산세의 납기는 매년 9월 16일부터 9월 30일까지이다.","재산세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다.","주택분 재산세로서 해당 연도에 부과할 세액이 20만원 이하인 경우에는 조례로 정하는 바에 따라 납기를 7월 16일부터 7월 31일까지로 하여 한꺼번에 부과ㆍ징수할 수 있다.","주택분 재산세의 납기는 해당 연도에 부과ㆍ징수할 세액의 2분의 1은 매년 7월 16일부터 7월 31일까지, 나머지 2분의 1은 9월 16일부터 9월 30일까지이다."],"a":[2],"L":"세2-3","o":"변형","x":{"한줄":"항공기분 재산세의 납기는 7월 16일부터 7월 31일까지다.","근거":[{"법령":"지방세법","조문":"제115조제1항제5호","원문":"항공기: 매년 7월 16일부터 7월 31일까지"},{"법령":"지방세법","조문":"제115조제1항제1호","원문":"토지: 매년 9월 16일부터 9월 30일까지"},{"법령":"지방세법","조문":"제116조제1항","원문":"재산세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다."},{"법령":"지방세법","조문":"제115조제1항제3호","원문":"주택: 해당 연도에 부과ㆍ징수할 세액의 2분의 1은 매년 7월 16일부터 7월 31일까지, 나머지 2분의 1은 9월 16일부터 9월 30일까지. 다만, 해당 연도에 부과할 세액이 20만원 이하인 경우에는 조례로 정하는 바에 따라 납기를 7월 16일부터 7월 31일까지로 하여 한꺼번에 부과ㆍ징수할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"토지분 재산세 납기는 9월 16일부터 9월 30일까지다(지방세법 제115조 제1항 제1호)."},{"번호":2,"판정":"틀림","설명":"항공기는 건축물·선박과 같이 7월 16일부터 7월 31일까지다(지방세법 제115조 제1항 제2호·제4호·제5호)."},{"번호":3,"판정":"옳음","설명":"재산세는 세액을 산정해 보통징수한다. 특별징수나 신고납부 방식이 아니다(지방세법 제116조 제1항)."},{"번호":4,"판정":"옳음","설명":"주택분 부과세액이 20만원 이하이면 조례로 7월 16일부터 7월 31일까지 한꺼번에 부과·징수할 수 있다(지방세법 제115조 제1항 제3호 단서)."},{"번호":5,"판정":"옳음","설명":"주택분은 세액의 2분의 1씩 7월과 9월에 나눠 부과·징수한다(지방세법 제115조 제1항 제3호 본문)."}],"개념":[{"종류":"표","제목":"재산세 납기(제115조제1항)","머리":["과세대상","납기"],"행":[["토지","9월 16일~9월 30일"],["건축물","7월 16일~7월 31일"],["주택","세액의 1/2은 7월 16일~7월 31일, 나머지 1/2은 9월 16일~9월 30일"],["주택(부과세액 20만원 이하)","조례로 7월 16일~7월 31일에 한꺼번에 부과·징수 가능"],["선박","7월 16일~7월 31일"],["항공기","7월 16일~7월 31일"]]},{"종류":"표","제목":"재산세 부과·징수 방법","머리":["항목","내용","근거"],"행":[["과세기준일","매년 6월 1일","제114조"],["징수방법","관할 지방자치단체의 장이 세액을 산정해 보통징수","제116조제1항"],["납세고지서","토지·건축물·주택·선박·항공기로 구분해 과세표준과 세액을 적어 납기개시 5일 전까지 발급","제116조제2항"],["수시 부과·징수","과세대상 누락, 위법, 착오 등으로 세액을 변경하거나 수시부과 사유가 생긴 경우","제115조제2항"]]}],"함정":"선박·항공기는 토지가 아니라 건축물과 같은 7월 납기다. 9월 납기는 토지 전부와 주택 후반부뿐이다. 20만원 이하 7월 일괄 특례는 주택에만 있다."}},{"i":"S5-2-2-세법-09","r":"S5","g":3,"c":2,"n":33,"s":"세법","q":"종합부동산세법상 납세의무 성립시기가 2026년인 종합부동산세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["과세기준일 현재 주택의 공시가격을 합산한 금액이 8억원인 개인은 납부할 주택분 종합부동산세액이 있다.","주택에 대한 과세표준이 5억원인 개인(2주택 이하 소유)의 경우 3억원을 초과하는 금액에 적용될 세율은 1천분의 5이다.","관할세무서장은 납부하여야 할 세액이 250만원을 초과하는 경우 그 세액의 일부를 납부기한이 지난 날부터 3개월 이내에 분납하게 할 수 있다.","공익법인등이 아닌 법인이 3주택 이상을 소유한 경우 주택분 종합부동산세는 과세표준에 1천분의 30의 단일세율을 적용하여 계산한다.","종합부동산세를 신고납부방식으로 납부하려는 납세의무자는 해당 연도 12월 1일부터 12월 15일까지 과세표준과 세액을 신고하여야 한다. 이 경우 관할세무서장의 결정은 없었던 것으로 본다."],"a":[5],"L":"세3-1","o":"변형","x":{"한줄":"신고납부방식을 택한 납세의무자는 12월 1일부터 15일까지 신고해야 하고, 이때 관할세무서장의 결정은 없었던 것으로 본다.","근거":[{"법령":"종합부동산세법","조문":"제16조제3항","원문":"제1항 및 제2항에도 불구하고 종합부동산세를 신고납부방식으로 납부하고자 하는 납세의무자는 종합부동산세의 과세표준과 세액을 해당 연도 12월 1일부터 12월 15일까지 대통령령으로 정하는 바에 따라 관할세무서장에게 신고하여야 한다. 이 경우 제1항의 규정에 따른 결정은 없었던 것으로 본다."},{"법령":"종합부동산세법","조문":"제8조제1항","원문":"1. 대통령령으로 정하는 1세대 1주택자(이하 \"1세대 1주택자\"라 한다): 12억원\n2. 제9조제2항제3호 각 목의 세율이 적용되는 법인 또는 법인으로 보는 단체: 0원\n3. 제1호 및 제2호에 해당하지 아니하는 자: 9억원"},{"법령":"종합부동산세법","조문":"제9조제1항제1호","원문":"150만원+(3억원을 초과하는 금액의 1천분의 7)"},{"법령":"종합부동산세법","조문":"제20조","원문":"관할세무서장은 종합부동산세로 납부하여야 할 세액이 250만원을 초과하는 경우에는 대통령령으로 정하는 바에 따라 그 세액의 일부를 납부기한이 지난 날부터 6개월 이내에 분납하게 할 수 있다."},{"법령":"종합부동산세법","조문":"제9조제2항제3호","원문":"제1호 및 제2호 외의 경우: 다음 각 목에 따른 세율\n가. 2주택 이하를 소유한 경우: 1천분의 27\n나. 3주택 이상을 소유한 경우: 1천분의 50"}],"선지":[{"번호":1,"판정":"틀림","설명":"일반 납세의무자의 공제금액은 9억원이고 1세대 1주택자도 12억원이다. 공시가격 합계 8억원이면 과세표준이 0이라 납부할 세액이 없다(종합부동산세법 제8조 제1항)."},{"번호":2,"판정":"틀림","설명":"과세표준 3억원 초과 6억원 이하 구간의 세율은 150만원에 3억원 초과분의 1천분의 7을 더한다. 1천분의 5는 3억원 이하 구간이다(종합부동산세법 제9조 제1항 제1호)."},{"번호":3,"판정":"틀림","설명":"분납 기간은 납부기한이 지난 날부터 6개월 이내다. 3개월은 재산세 분할납부 기간이다(종합부동산세법 제20조, 지방세법 제118조)."},{"번호":4,"판정":"틀림","설명":"공익법인등이 아닌 법인의 3주택 이상 세율은 1천분의 50 단일세율이다. 1천분의 27은 2주택 이하 세율이다(종합부동산세법 제9조 제2항 제3호)."},{"번호":5,"판정":"옳음","설명":"신고납부를 택하면 12월 1일부터 12월 15일까지 신고하고 납부한다. 신고하면 앞선 결정은 없었던 것으로 본다(종합부동산세법 제16조 제3항·제4항)."}],"개념":[{"종류":"계산","제목":"주택분 종합부동산세액 계산 예(개인 2주택, 공시가격 합계 15억원 가정)","단계":[{"설명":"과세표준 = (공시가격 합계 − 공제금액) × 공정시장가액비율. 공제금액은 일반 9억원, 비율은 60%","식":"(15억원 − 9억원) × 60%","값":"3억 6천만원"},{"설명":"산출세액: 2주택 이하 세율표에서 3억원 초과 6억원 이하 구간 적용","식":"150만원 + (3억 6천만원 − 3억원) × 7/1000","값":"192만원"},{"설명":"납부세액 = 산출세액 − 주택분 재산세로 부과된 세액 중 공제액(시행령 제4조의3 제1항 계산식, 조례 가감·세부담 상한 적용 후 세액 기준)","식":"192만원 − 공제할 재산세액","값":"재산세액 공제 후 금액"}]},{"종류":"표","제목":"종합부동산세 일정","머리":["무엇","언제","근거"],"행":[["과세기준일","매년 6월 1일","종합부동산세법 제3조, 지방세법 제114조"],["합산배제 주택 보유현황 신고","해당 연도 9월 16일~9월 30일","제8조제3항"],["일시적 2주택·상속주택·지방 저가주택 특례 신청, 공동명의 1주택자 신청","해당 연도 9월 16일~9월 30일","제8조제5항, 제10조의2제2항"],["납부고지서 발급","납부기간 개시 5일 전까지(주택·토지 구분 기재)","제16조제2항"],["부과·징수(납부기간)","해당 연도 12월 1일~12월 15일","제16조제1항"],["신고납부 선택 시 신고","해당 연도 12월 1일~12월 15일","제16조제3항"],["분납(납부세액 250만원 초과)","납부기한이 지난 날부터 6개월 이내","제20조"]]}],"함정":"공시가격 합계가 공제금액 이하면 과세표준이 0이라 낼 세액이 없다(①). 분납은 6개월, 재산세 분할납부는 3개월이다(③). 법인 세율은 2주택 이하 1천분의 27, 3주택 이상 1천분의 50이다(④).","개정":"주택분 과세표준 공제금액은 법 제8조 제1항에서 일반 9억원, 1세대 1주택자 12억원, 2.7%·5% 세율 적용 법인 0원으로 규정한다(제8조 <개정 2022.12.31, 2023.4.18> 표시). 옛 기출 선지는 6억원 공제와 1세대 1주택자 3억원 추가 공제 구조였다."}},{"i":"S5-2-2-세법-10","r":"S5","g":3,"c":2,"n":34,"s":"세법","q":"종합부동산세법상 1세대 1주택자에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["과세기준일 현재 세대원 중 1인과 그 배우자만이 공동으로 1주택을 소유하고 해당 세대원 및 다른 세대원이 다른 주택을 소유하지 아니한 경우 신청하지 않더라도 공동명의 1주택자를 해당 1주택에 대한 납세의무자로 한다.","합산배제 신고한 ｢근현대문화유산의 보존 및 활용에 관한 법률｣에 따른 등록문화유산에 해당하는 주택은 1세대가 소유한 주택 수에서 제외한다.","1세대가 일반 주택과 합산배제 신고한 임대주택을 각각 1채씩 소유한 경우 해당 일반 주택에 그 주택소유자가 실제 거주하지 않더라도 1세대 1주택자에 해당한다.","1세대 1주택자는 주택의 공시가격을 합산한 금액에서 6억원을 공제한 금액에서 다시 3억원을 공제한 금액에 공정시장가액비율을 곱한 금액을 과세표준으로 한다.","1세대 1주택자에 대하여는 주택분 종합부동산세 산출세액에서 소유자의 연령과 주택 보유기간에 따른 공제액을 공제율 합계 100분의 70의 범위에서 중복하여 공제한다."],"a":[2],"L":"세3-1","o":"기출","x":{"한줄":"합산배제 신고한 등록문화유산 주택은 1세대 1주택자 여부를 판단할 때 주택 수에서 뺀다.","근거":[{"법령":"종합부동산세법 시행령","조문":"제2조의3제2항제3호","원문":"제4조제1항 각 호에 해당하는 주택으로서 같은 조 제5항에 따라 합산배제 신고를 한 주택"},{"법령":"종합부동산세법 시행령","조문":"제4조제1항제8호","원문":"「근현대문화유산의 보존 및 활용에 관한 법률」에 따른 등록문화유산"},{"법령":"종합부동산세법","조문":"제10조의2제2항","원문":"제1항을 적용받으려는 납세의무자는 당해 연도 9월 16일부터 9월 30일까지 대통령령으로 정하는 바에 따라 관할세무서장에게 신청하여야 한다."},{"법령":"종합부동산세법 시행령","조문":"제2조의3제2항 단서","원문":"다만, 제1호는 각 호 외의 주택을 소유하는 자가 과세기준일 현재 그 주택에 주민등록이 되어 있고 실제로 거주하고 있는 경우에 한정하여 적용한다."},{"법령":"종합부동산세법","조문":"제8조제1항","원문":"1. 대통령령으로 정하는 1세대 1주택자(이하 \"1세대 1주택자\"라 한다): 12억원"},{"법령":"종합부동산세법","조문":"제9조제5항","원문":"이 경우 제6항부터 제9항까지는 공제율 합계 100분의 80의 범위에서 중복하여 적용할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"공동명의 1주택자 특례는 해당 연도 9월 16일부터 9월 30일까지 신청해야 적용된다(종합부동산세법 제10조의2 제2항)."},{"번호":2,"판정":"옳음","설명":"제4조 제1항 각 호의 주택으로 합산배제 신고를 한 것은 주택 수에서 제외한다. 등록문화유산 주택이 그 제8호에 해당한다(종합부동산세법 시행령 제2조의3 제2항 제3호, 제4조 제1항 제8호)."},{"번호":3,"판정":"틀림","설명":"합산배제 임대주택을 주택 수에서 뺄 때는 일반 주택에 주민등록이 되어 있고 실제 거주해야 한다(종합부동산세법 시행령 제2조의3 제2항 단서)."},{"번호":4,"판정":"틀림","설명":"1세대 1주택자의 공제금액은 12억원이다. 6억원과 3억원을 차례로 공제하던 구조가 아니다(종합부동산세법 제8조 제1항 제1호)."},{"번호":5,"판정":"틀림","설명":"연령·보유기간 공제는 공제율 합계 100분의 80의 범위에서 중복 적용한다(종합부동산세법 제9조 제5항)."}],"개념":[{"종류":"표","제목":"1세대 1주택자 판정과 주택 수 제외","머리":["상황","처리","신청·요건"],"행":[["합산배제 임대주택(시행령 제3조 제1항 각 호, 제5호 제외) 신고 + 일반 주택 1채","임대주택은 주택 수에서 제외","일반 주택에 주민등록 + 실제 거주, 9월 16일~30일 합산배제 신고"],["합산배제 사원용 주택·미분양주택·가정어린이집·등록문화유산 주택 등(시행령 제4조 제1항)","주택 수에서 제외","합산배제 신고(실제 거주 요건은 임대주택에만 붙음)"],["1주택 + 다른 주택의 부속토지(건물·토지 소유자가 다른 경우)","1세대 1주택자로 봄","별도 신청 없음"],["일시적 2주택(대체취득)","1세대 1주택자로 봄","9월 16일~30일 신청"],["1주택 + 상속주택","1세대 1주택자로 봄","9월 16일~30일 신청"],["1주택 + 지방 저가주택","1세대 1주택자로 봄","9월 16일~30일 신청"],["부부 공동명의 1주택","공동명의 1주택자를 납세의무자로 할 수 있음","9월 16일~30일 신청, 신청하지 않으면 각자 납세의무자"],["다가구주택","1주택으로 봄(합산배제 임대주택으로 신고하면 구획된 부분을 각각 1주택)","시행령 제2조의3 제1항"]]},{"종류":"표","제목":"1세대 1주택자 세액공제(제9조제5항~제9항)","머리":["구분","요건","공제율"],"행":[["연령","만 60세 이상 65세 미만","100분의 20"],["연령","만 65세 이상 70세 미만","100분의 30"],["연령","만 70세 이상","100분의 40"],["보유기간","5년 이상 10년 미만","100분의 20"],["보유기간","10년 이상 15년 미만","100분의 40"],["보유기간","15년 이상","100분의 50"],["합계 한도","연령공제와 보유기간공제 중복 적용","100분의 80 범위"]]}],"함정":"공동명의 1주택자 특례와 일시적 2주택·상속주택·지방 저가주택 특례는 9월 16일~30일 신청이 있어야 적용된다. 합산배제 임대주택을 주택 수에서 뺄 때는 일반 주택에 주민등록과 실제 거주가 필요하다. 공제금액은 12억원이고 공제율 합계 한도는 80%다.","개정":"등록문화유산은 현행 시행령 제4조 제1항 제8호에서 「근현대문화유산의 보존 및 활용에 관한 법률」에 따른 것으로 규정되어 있어 선지 ②의 법률명을 이에 맞췄다. 정답은 그대로다."}},{"i":"S5-2-2-세법-11","r":"S5","g":3,"c":2,"n":35,"s":"세법","q":"소득세법상 거주자가 국내자산을 양도한 경우 양도소득의 필요경비에 관한 설명으로 옳은 것은? (단, 자본적지출액 등 및 양도비 등은 그 지출에 관하여 법령에 따른 증명서류를 수취ㆍ보관하거나 실제 지출사실이 금융거래 증명서류에 의하여 확인되는 경우에 한함)","b":null,"bs":"없음","img":[],"ch":["취득가액을 실지거래가액에 의하는 경우 당사자 약정에 의한 대금지급방법에 따라 취득원가에 이자상당액을 가산하여 거래가액을 확정하는 때에도 그 이자상당액은 취득원가에 포함하지 아니한다.","취득가액을 환산취득가액으로 하는 경우에는 보유기간 중 사업소득금액 계산 시 필요경비에 산입한 감가상각비를 취득가액에서 공제하지 아니한다.","양도소득세과세표준 신고서 작성비용 및 계약서 작성비용은 증명서류를 수취ㆍ보관하더라도 양도비 등에 해당하지 아니한다.","토지를 취득할 때 법령 등의 규정에 따라 매입한 국민주택채권을 만기 전에 금융기관 외의 자에게 양도함으로써 발생하는 매각차손은 같은 날 금융기관에 양도하였을 경우 발생하는 매각차손을 한도로 양도비 등에 해당한다.","취득가액을 환산취득가액으로 하는 경우 필요경비는 환산취득가액과 필요경비개산공제액의 합계액만 인정되며, 자본적지출액과 양도비의 합계액이 이보다 크더라도 그 합계액을 필요경비로 할 수 없다."],"a":[4],"L":"세3-2","o":"변형","x":{"한줄":"금융기관 외의 자에게 채권을 판 매각차손은 같은 날 금융기관에 팔았다면 생겼을 매각차손을 한도로 양도비 등에 든다.","근거":[{"법령":"소득세법 시행령","조문":"제163조제5항제2호","원문":"법 제94조제1항제1호의 자산을 취득함에 있어서 법령등의 규정에 따라 매입한 국민주택채권 및 토지개발채권을 만기전에 양도함으로써 발생하는 매각차손. 이 경우 재정경제부령으로 정하는 금융기관(이하 이 호에서 \"금융기관\"이라 한다) 외의 자에게 양도한 경우에는 동일한 날에 금융기관에 양도하였을 경우 발생하는 매각차손을 한도로 한다."},{"법령":"소득세법 시행령","조문":"제163조제1항제3호","원문":"제1호를 적용할 때 당사자 약정에 의한 대금지급방법에 따라 취득원가에 이자상당액을 가산하여 거래가액을 확정하는 경우 당해 이자상당액은 취득원가에 포함한다. 다만, 당초 약정에 의한 거래가액의 지급기일의 지연으로 인하여 추가로 발생하는 이자상당액은 취득원가에 포함하지 아니한다."},{"법령":"소득세법","조문":"제97조제3항","원문":"제2항에 따라 필요경비를 계산할 때 양도자산 보유기간에 그 자산에 대한 감가상각비로서 각 과세기간의 사업소득금액을 계산하는 경우 필요경비에 산입하였거나 산입할 금액이 있을 때에는 이를 제1항의 금액에서 공제한 금액을 그 취득가액으로 한다."},{"법령":"소득세법 시행령","조문":"제163조제5항제1호나목","원문":"양도소득세과세표준 신고서 작성비용 및 계약서 작성비용"},{"법령":"소득세법","조문":"제97조제2항제2호","원문":"다만, 제1항제1호나목에 따라 취득가액을 환산취득가액으로 하는 경우로서 가목의 금액이 나목의 금액보다 적은 경우에는 나목의 금액을 필요경비로 할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"약정한 대금지급방법에 따른 이자상당액은 취득원가에 포함한다. 지급기일 지연으로 추가로 생긴 이자상당액만 포함하지 않는다(소득세법 시행령 제163조 제1항 제3호)."},{"번호":2,"판정":"틀림","설명":"감가상각비를 필요경비로 산입한 금액은 제2항에 따라 필요경비를 계산할 때 취득가액에서 공제한다. 환산취득가액을 쓰는 경우도 같다(소득세법 제97조 제3항)."},{"번호":3,"판정":"틀림","설명":"신고서 작성비용과 계약서 작성비용은 양도비 등에 해당한다(소득세법 시행령 제163조 제5항 제1호 나목)."},{"번호":4,"판정":"옳음","설명":"금융기관 외의 자에게 양도한 경우 같은 날 금융기관에 양도했을 때의 매각차손이 한도다(소득세법 시행령 제163조 제5항 제2호)."},{"번호":5,"판정":"틀림","설명":"환산취득가액과 개산공제액의 합계액이 자본적지출액과 양도비의 합계액보다 적으면 후자를 필요경비로 할 수 있다(소득세법 제97조 제2항 제2호 단서)."}],"개념":[{"종류":"계산","제목":"환산취득가액을 쓰는 토지의 필요경비와 양도차익(가정 수치)","단계":[{"설명":"환산취득가액 = 양도 실지거래가액 × 취득 당시 기준시가 ÷ 양도 당시 기준시가. 양도가액 6억원, 취득 당시 기준시가 1억 2천만원, 양도 당시 기준시가 3억원으로 가정","식":"6억원 × 1억 2천만원 ÷ 3억원","값":"2억 4천만원"},{"설명":"필요경비개산공제 = 취득 당시 개별공시지가 × 3/100 (토지, 미등기 양도자산은 3/1000). 취득 당시 개별공시지가 1억 2천만원으로 가정","식":"1억 2천만원 × 3/100","값":"360만원"},{"설명":"가목 금액 = 환산취득가액 + 개산공제","식":"2억 4천만원 + 360만원","값":"2억 4,360만원"},{"설명":"나목 금액 = 자본적지출액 + 양도비. 자본적지출 2천만원, 양도비 1천만원으로 가정. 가목이 더 크므로 가목을 필요경비로 쓴다","식":"2천만원 + 1천만원","값":"3천만원"},{"설명":"양도차익 = 양도가액 − 필요경비","식":"6억원 − 2억 4,360만원","값":"3억 5,640만원"}]},{"종류":"표","제목":"양도소득 필요경비의 구성(소득세법 제97조, 시행령 제163조)","머리":["구분","포함","제외·한도"],"행":[["취득가액","취득에 든 실지거래가액, 약정 대금지급방법에 따른 이자상당액, 취득 관련 소송비용 중 필요경비 미산입분","지급기일 지연으로 추가 발생한 이자상당액, 필요경비에 산입된 소송비용, 감가상각비로 필요경비에 산입한 금액"],["자본적지출액 등","용도변경·개량·이용편의 비용, 개발부담금, 재건축부담금, 취득 후 소유권 확보 소송비용 중 필요경비 미산입분","지출 증명이 없는 금액(증명서류 수취·보관 또는 금융거래 증명서류로 확인 필요)"],["양도비 등","증권거래세, 신고서·계약서 작성비용, 공증비용·인지대·소개비, 명도비용, 국민주택채권·토지개발채권 매각차손","금융기관 외 양도 시 같은 날 금융기관에 양도했을 때의 매각차손 한도"],["환산취득가액 사용 시","환산취득가액 + 개산공제 (또는 자본적지출액 + 양도비 중 큰 쪽)","두 금액을 합쳐 쓰지 않고 하나를 선택"]]}],"함정":"감가상각비 공제는 취득가액을 실지거래가액으로 정하든 환산취득가액으로 정하든 적용된다(②). 환산취득가액을 쓸 때는 환산취득가액+개산공제와 자본적지출액+양도비 중 큰 쪽을 필요경비로 고를 수 있다(⑤). 약정 대금지급방법에 따른 이자는 취득원가에 넣고 지급기일 지연 이자는 넣지 않는다(①).","개정":"자본적지출액 등과 양도비 등은 증명서류 수취·보관 외에 실제 지출사실이 금융거래 증명서류로 확인되는 경우에도 인정한다(소득세법 시행령 제163조 제3항·제5항, <개정 2018.2.13> 표시)."}},{"i":"S5-2-2-세법-12","r":"S5","g":3,"c":2,"n":36,"s":"세법","q":"소득세법령상 거주자가 실지거래가액에 따른 양도차익을 계산할 때 양도가액에서 공제할 필요경비에 관한 설명으로 틀린 것은? (단, 자본적지출액 등 및 양도비 등은 그 지출에 관하여 법령에 따른 증명서류를 수취 ㆍ보관하거나 실제 지출사실이 금융거래 증명서류에 의하여 확인되는 경우에 한함)","b":null,"bs":"없음","img":[],"ch":["양도자산을 취득한 후 쟁송이 있는 경우에 그 소유권을 확보하기 위하여 직접 소요된 소송비용ㆍ화해비용 등의 금액으로서 그 지출한 연도의 각 소득금액의 계산에 있어서 필요경비에 산입된 금액은 자본적지출액 등에 해당한다.","「소득세법」 제94조 제1항 각 호의 자산을 양도하기 위하여 직접 지출한 비용으로서 매매계약에 따른 인도의무를 이행하기 위하여 양도자가 지출하는 명도비용은 양도비 등에 해당한다.","「소득세법시행령」 제163조 제1항 제1호를 적용할 때 당사자 약정에 의한 대금지급방법에 따라 취득원가에 이자상당액을 가산하여 거래가액을 확정하는 경우 당해 이자상당액은 취득원가에 포함한다. 다만, 당초 약정에 의한 거래가액의 지급기일의 지연으로 인하여 추가로 발생하는 이자상당액은 취득원가에 포함하지 아니한다.","「재건축초과이익 환수에 관한 법률」에 따른 재건축부담금(재건축부담금의 납부의무자와 양도자가 서로 다른 경우에는 양도자에게 사실상 배분될 재건축부담금상당액)은 자본적지출액 등에 해당한다.","「소득세법」 제94조 제1항 제1호의 토지를 취득함에 있어서 법령 등의 규정에 따라 매입한 토지개발채권을 만기전에 재정경제부령으로 정하는 금융기관에 양도함으로써 발생하는 매각차손은 양도비 등에 해당한다."],"a":[1],"L":"세3-2","o":"기출","x":{"한줄":"소송비용이 이미 그 지출한 연도의 필요경비에 산입되었다면 자본적지출액 등에서 뺀다.","근거":[{"법령":"소득세법 시행령","조문":"제163조제3항제2호","원문":"양도자산을 취득한 후 쟁송이 있는 경우에 그 소유권을 확보하기 위하여 직접 소요된 소송비용ㆍ화해비용 등의 금액으로서 그 지출한 연도의 각 소득금액의 계산에 있어서 필요경비에 산입된 것을 제외한 금액"},{"법령":"소득세법 시행령","조문":"제163조제5항제1호라목","원문":"매매계약에 따른 인도의무를 이행하기 위하여 양도자가 지출하는 명도비용"},{"법령":"소득세법 시행령","조문":"제163조제1항제3호","원문":"제1호를 적용할 때 당사자 약정에 의한 대금지급방법에 따라 취득원가에 이자상당액을 가산하여 거래가액을 확정하는 경우 당해 이자상당액은 취득원가에 포함한다. 다만, 당초 약정에 의한 거래가액의 지급기일의 지연으로 인하여 추가로 발생하는 이자상당액은 취득원가에 포함하지 아니한다."},{"법령":"소득세법 시행령","조문":"제163조제3항제3호의3","원문":"「재건축초과이익 환수에 관한 법률」에 따른 재건축부담금(재건축부담금의 납부의무자와 양도자가 서로 다른 경우에는 양도자에게 사실상 배분될 재건축부담금상당액을 말한다)"},{"법령":"소득세법 시행령","조문":"제163조제5항제2호","원문":"법 제94조제1항제1호의 자산을 취득함에 있어서 법령등의 규정에 따라 매입한 국민주택채권 및 토지개발채권을 만기전에 양도함으로써 발생하는 매각차손. 이 경우 재정경제부령으로 정하는 금융기관(이하 이 호에서 \"금융기관\"이라 한다) 외의 자에게 양도한 경우에는 동일한 날에 금융기관에 양도하였을 경우 발생하는 매각차손을 한도로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"소송비용 등은 그 지출한 연도의 각 소득금액 계산에서 필요경비에 산입된 금액을 제외한 금액이 자본적지출액 등이다(소득세법 시행령 제163조 제3항 제2호)."},{"번호":2,"판정":"옳음","설명":"매매계약에 따른 인도의무를 이행하기 위한 명도비용은 양도비 등이다(소득세법 시행령 제163조 제5항 제1호 라목)."},{"번호":3,"판정":"옳음","설명":"약정한 대금지급방법에 따른 이자상당액은 취득원가에 포함하고, 지급기일 지연으로 추가 발생한 이자상당액은 포함하지 않는다(소득세법 시행령 제163조 제1항 제3호)."},{"번호":4,"판정":"옳음","설명":"재건축부담금은 자본적지출액 등에 해당한다. 납부의무자와 양도자가 다르면 양도자에게 사실상 배분될 금액을 말한다(소득세법 시행령 제163조 제3항 제3호의3)."},{"번호":5,"판정":"옳음","설명":"토지 취득 때 매입한 국민주택채권·토지개발채권을 만기 전에 금융기관에 양도한 매각차손은 양도비 등이다(소득세법 시행령 제163조 제5항 제2호)."}],"개념":[{"종류":"표","제목":"자본적지출액 등과 양도비 등(소득세법 시행령 제163조 제3항·제5항)","머리":["구분","해당","주의"],"행":[["자본적지출액 등","용도변경·개량·이용편의 비용(재건축 철거비용 포함)","재해·노후화 등 부득이한 사유의 재건축 철거비용"],["자본적지출액 등","취득 후 소유권 확보 소송비용·화해비용","그 지출한 연도의 필요경비에 산입된 금액은 제외"],["자본적지출액 등","개발부담금, 재건축부담금","납부의무자와 양도자가 다르면 양도자에게 사실상 배분될 금액"],["양도비 등","증권거래세, 신고서·계약서 작성비용, 공증비용·인지대·소개비, 명도비용","양도하기 위해 직접 지출한 비용"],["양도비 등","토지 취득 때 매입한 국민주택채권·토지개발채권의 만기 전 양도 매각차손","금융기관 외의 자에게 양도하면 같은 날 금융기관에 양도했을 때의 매각차손이 한도"],["공통 요건","증명서류 수취·보관 또는 금융거래 증명서류로 지출사실 확인","증명이 없으면 필요경비 불산입"]]},{"종류":"비교","제목":"취득원가에 넣는 이자와 넣지 않는 이자","왼쪽":{"이름":"취득원가에 포함","항목":["당사자 약정에 의한 대금지급방법에 따라 취득원가에 가산한 이자상당액","현재가치할인차금(사업소득 필요경비로 상각한 금액은 공제)"]},"오른쪽":{"이름":"취득원가에 불포함","항목":["당초 약정한 지급기일의 지연으로 추가 발생하는 이자상당액","부당행위계산에 의한 시가초과액"]}}],"함정":"소송비용은 그 지출한 연도에 이미 필요경비로 넣은 금액을 뺀 나머지만 자본적지출액 등이 된다. 같은 비용을 두 번 공제하지 않게 하는 규정이다. ⑤는 부령 명칭만 바뀌었고 내용은 같다.","개정":"시행령 제163조 제5항 제2호의 금융기관을 정하는 부령이 현행 조문(<개정 2025.12.30> 표시)에서 재정경제부령으로 표기되어 선지 ⑤의 부령 명칭을 이에 맞췄다. 정답은 그대로다."}},{"i":"S5-2-2-세법-13","r":"S5","g":3,"c":2,"n":37,"s":"세법","q":"소득세법상 국외자산 양도에 대한 양도소득세에 관한 설명으로 틀린 것은? (단, 거주자는 해당 자산의 양도일까지 계속 5년 이상 국내에 주소를 둠)","b":null,"bs":"없음","img":[],"ch":["국외에 있는 토지를 3년 이상 보유하다가 양도한 경우 보유기간에 따른 장기보유특별공제를 적용한다.","국외자산의 양도가액은 양도 당시의 실지거래가액으로 한다. 양도 당시의 실지거래가액을 확인할 수 없는 경우 양도자산이 소재하는 국가의 양도 당시 현황을 반영한 시가에 따른다.","국외자산의 양도소득금액에서는 해당 과세기간에 연 250만원을 공제한다.","국외자산의 양도소득에 대하여 해당 외국에서 과세한 경우 외국납부세액의 세액공제방법과 외국납부세액의 필요경비 산입방법 중 하나를 선택하여 적용할 수 있다.","국외자산의 양도에 대한 양도소득세의 과세에는 양도 또는 취득의 시기와 양도소득의 부당행위계산에 관한 국내자산 양도소득세 규정을 준용한다."],"a":[1],"L":"세3-2","o":"변형","x":{"한줄":"국외자산을 양도하는 경우에는 보유기간이 길어도 장기보유특별공제를 하지 않는다.","근거":[{"법령":"소득세법","조문":"제118조의8","원문":"국외자산의 양도에 대한 양도소득세의 과세에 관하여는 제89조, 제90조, 제92조, 제95조, 제97조제3항, 제98조, 제100조, 제101조, 제105조부터 제107조까지, 제110조부터 제112조까지, 제114조, 제114조의2 및 제115조부터 제118조까지를 준용한다. 다만, 제95조에 따른 장기보유 특별공제액은 공제하지 아니한다."},{"법령":"소득세법","조문":"제118조의3제1항","원문":"제118조의2에 따른 자산(이하 이 절에서 \"국외자산\"이라 한다)의 양도가액은 그 자산의 양도 당시의 실지거래가액으로 한다. 다만, 양도 당시의 실지거래가액을 확인할 수 없는 경우에는 양도자산이 소재하는 국가의 양도 당시 현황을 반영한 시가에 따르되,"},{"법령":"소득세법","조문":"제118조의7제1항","원문":"국외자산의 양도에 대한 양도소득이 있는 거주자에 대해서는 해당 과세기간의 양도소득금액에서 연 250만원을 공제한다."},{"법령":"소득세법","조문":"제118조의6제1항","원문":"국외자산의 양도소득에 대하여 해당 외국에서 과세를 하는 경우로서 그 양도소득에 대하여 대통령령으로 정하는 국외자산 양도소득에 대한 세액(이하 이 항에서 \"국외자산 양도소득세액\"이라 한다)을 납부하였거나 납부할 것이 있을 때에는 다음 각 호의 방법 중 하나를 선택하여 적용할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국외자산 양도에는 제95조를 준용하되 장기보유특별공제액은 공제하지 않는다(소득세법 제118조의8 단서)."},{"번호":2,"판정":"옳음","설명":"국외자산의 양도가액은 실지거래가액이며, 확인할 수 없으면 소재국의 양도 당시 현황을 반영한 시가에 따른다(소득세법 제118조의3 제1항)."},{"번호":3,"판정":"옳음","설명":"국외자산 양도소득이 있는 거주자는 양도소득금액에서 연 250만원을 공제한다(소득세법 제118조의7 제1항)."},{"번호":4,"판정":"옳음","설명":"외국납부세액은 세액공제방법과 필요경비 산입방법 중 하나를 선택해 적용한다(소득세법 제118조의6 제1항)."},{"번호":5,"판정":"옳음","설명":"양도 또는 취득의 시기(제98조)와 양도소득의 부당행위계산(제101조)은 국외자산 양도에 준용한다(소득세법 제118조의8)."}],"개념":[{"종류":"표","제목":"국외자산 양도에 준용하는 국내자산 양도소득세 규정(제118조의8)","머리":["준용 조문","내용","국외자산에서의 처리"],"행":[["제89조","비과세 양도소득","준용"],["제90조","양도소득세액의 감면","준용"],["제92조","양도소득과세표준과 세액의 계산 순서","준용"],["제95조","양도소득금액과 장기보유특별공제","준용하되 장기보유특별공제액은 공제하지 않음"],["제97조제3항","감가상각비를 필요경비에서 공제","준용"],["제98조","양도 또는 취득의 시기","준용"],["제100조","양도차익의 산정","준용"],["제101조","양도소득의 부당행위계산","준용"],["제105조~제107조","예정신고, 예정신고납부, 예정신고 산출세액","준용"],["제110조~제112조","확정신고, 확정신고납부, 분할납부","준용"],["제114조~제118조(제114조의2 포함)","결정·경정, 가산세, 징수, 환급, 준용규정","준용"]]},{"종류":"표","제목":"국외자산에 별도 규정을 두는 항목","머리":["항목","국외자산 규정","내용"],"행":[["양도소득의 범위","제118조의2","양도일까지 계속 5년 이상 국내에 주소 또는 거소를 둔 거주자의 토지·건물, 부동산에 관한 권리, 기타자산 양도소득. 외화차입금 환차익은 제외"],["양도가액","제118조의3","실지거래가액, 확인할 수 없으면 소재국의 양도 당시 현황을 반영한 시가"],["필요경비","제118조의4","실지거래가액인 취득가액 + 자본적지출액 + 양도비"],["세율","제118조의5","제55조제1항의 세율"],["외국납부세액","제118조의6","세액공제방법 또는 필요경비 산입방법 선택"],["기본공제","제118조의7","연 250만원"]]}],"함정":"제118조의8은 제95조를 준용하면서 단서로 장기보유특별공제액만 공제하지 않는다고 정한다. 기본공제는 준용이 아니라 제118조의7이 연 250만원으로 따로 규정한다."}},{"i":"S5-2-2-세법-14","r":"S5","g":3,"c":2,"n":38,"s":"세법","q":"소득세법상 거주자의 양도소득세에 관한 설명으로 틀린 것은? (단, 국내소재 부동산의 양도임)","b":null,"bs":"없음","img":[],"ch":["「소득세법」 제104조 제3항에 따른 미등기양도자산의 양도소득금액에 대하여는 양도소득 기본공제를 하지 아니한다.","토지를 양도한 거주자는 양도차익이 없거나 양도차손이 발생한 경우에도 양도소득과세표준 예정신고를 하여야 한다.","거주자가 예정신고를 할 때 납부할 세액이 1천만원을 초과하는 경우 납부기한이 지난 후 2개월 이내에 분할납부할 수 있다.","양도일부터 소급하여 10년 이내에 배우자로부터 증여받은 토지를 양도한 경우 이월과세를 적용한다. 그 토지에 대하여 납부하였거나 납부할 증여세 상당액은 필요경비에 산입한다.","토지의 양도에서 양도차손이 발생한 자산이 있는 경우 같은 과세기간의 다른 토지ㆍ건물 양도소득금액에서 그 양도차손을 공제하고, 공제하지 못한 양도차손은 다음 과세기간으로 이월하여 공제한다."],"a":[5],"L":"세3-2","o":"변형","x":{"한줄":"양도차손은 같은 소득 그룹 안의 다른 자산 양도소득금액에서만 공제한다. 공제하지 못한 양도차손의 이월공제 규정은 없다.","근거":[{"법령":"소득세법","조문":"제102조제2항","원문":"제1항에 따라 양도소득금액을 계산할 때 양도차손이 발생한 자산이 있는 경우에는 제1항 각 호별로 해당 자산 외의 다른 자산에서 발생한 양도소득금액에서 그 양도차손을 공제한다. 이 경우 공제방법은 양도소득금액의 세율 등을 고려하여 대통령령으로 정한다."},{"법령":"소득세법","조문":"제103조제1항제1호","원문":"제94조제1항제1호ㆍ제2호 및 제4호에 따른 소득. 다만, 제104조제3항에 따른 미등기양도자산의 양도소득금액에 대해서는 그러하지 아니하다."},{"법령":"소득세법","조문":"제105조제3항","원문":"제1항은 양도차익이 없거나 양도차손이 발생한 경우에도 적용한다."},{"법령":"소득세법","조문":"제112조","원문":"거주자로서 제106조 또는 제111조에 따라 납부할 세액이 각각 1천만원을 초과하는 자는 대통령령으로 정하는 바에 따라 그 납부할 세액의 일부를 납부기한이 지난 후 2개월 이내에 분할납부할 수 있다."},{"법령":"소득세법","조문":"제97조의2제1항제3호","원문":"거주자가 해당 자산에 대하여 납부하였거나 납부할 증여세 상당액이 있는 경우 필요경비에 산입한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"미등기양도자산의 양도소득금액에는 양도소득 기본공제를 적용하지 않는다(소득세법 제103조 제1항 제1호 단서)."},{"번호":2,"판정":"옳음","설명":"예정신고는 양도차익이 없거나 양도차손이 발생한 경우에도 해야 한다(소득세법 제105조 제3항)."},{"번호":3,"판정":"옳음","설명":"예정신고납부세액이 1천만원을 초과하면 납부기한이 지난 후 2개월 이내에 분할납부할 수 있다(소득세법 제112조)."},{"번호":4,"판정":"옳음","설명":"배우자·직계존비속으로부터 양도일 소급 10년 이내에 증여받은 자산은 이월과세를 적용하고, 증여세 상당액은 필요경비에 산입한다(소득세법 제97조의2 제1항 제3호)."},{"번호":5,"판정":"틀림","설명":"양도차손은 같은 호별로 다른 자산의 양도소득금액에서 공제할 뿐, 다음 과세기간으로 이월하여 공제하는 규정이 없다(소득세법 제102조 제2항)."}],"개념":[{"종류":"계산","제목":"양도소득세 산출세액 계산 예(등기된 건물, 9년 보유, 가정 수치)","단계":[{"설명":"양도차익 = 양도가액 − 필요경비(취득가액 + 자본적지출액 + 양도비). 양도가액 7억원, 취득가액 4억원, 자본적지출 3천만원, 양도비 2천만원으로 가정","식":"7억원 − (4억원 + 3천만원 + 2천만원)","값":"2억 5천만원"},{"설명":"장기보유특별공제 = 양도차익 × 보유기간별 공제율. 보유 9년 이상 10년 미만은 100분의 18","식":"2억 5천만원 × 18%","값":"4,500만원"},{"설명":"양도소득금액 = 양도차익 − 장기보유특별공제","식":"2억 5천만원 − 4,500만원","값":"2억 500만원"},{"설명":"과세표준 = 양도소득금액 − 양도소득 기본공제 250만원","식":"2억 500만원 − 250만원","값":"2억 250만원"},{"설명":"산출세액: 보유 2년 이상 일반 자산은 제55조제1항 세율. 1억5천만원 초과 3억원 이하 구간은 3,706만원 + 1억5천만원 초과분의 38%","식":"3,706만원 + (2억 250만원 − 1억 5천만원) × 38%","값":"5,701만원"}]},{"종류":"표","제목":"양도소득세 신고·납부 기한","머리":["구분","기한","근거"],"행":[["예정신고(토지·건물, 부동산에 관한 권리, 기타자산, 신탁 수익권: 제94조제1항제1·2·4·6호)","양도일이 속하는 달의 말일부터 2개월","제105조제1항제1호"],["예정신고(주식등 중 제94조제1항제3호 가목·나목)","양도일이 속하는 반기의 말일부터 2개월","제105조제1항제2호"],["예정신고(부담부증여의 채무액 부분)","양도일이 속하는 달의 말일부터 3개월","제105조제1항제3호"],["확정신고","다음 연도 5월 1일~5월 31일","제110조제1항"],["예정신고를 한 경우","확정신고 생략 가능. 누진세율 대상 자산 예정신고를 2회 이상 한 경우 등은 예외","제110조제4항"],["분할납부","납부할 세액이 1천만원 초과 시 납부기한이 지난 후 2개월 이내","제112조"]]}],"함정":"양도차손은 같은 호 그룹 안의 다른 자산 양도소득금액에서 공제하는 데서 끝나고 다음 과세기간으로 이월되지 않는다. 종합소득의 이월결손금 제도와 다르다. 양도차손이 나도 예정신고는 해야 한다(②)."}},{"i":"S5-2-2-세법-15","r":"S5","g":3,"c":2,"n":39,"s":"세법","q":"거주자 甲은 2015년에 국외에 1채의 주택을 미화 1십만 달러(취득자금 중 일부 외화 차입)에 취득하였고, 2021년에 동 주택을 미화 2십만 달러에 양도하였다. 이 경우 소득세법상 설명으로 틀린 것은? (단, 甲은 해당 자산의 양도일까지 계속 5년 이상 국내에 주소를 둠)","b":null,"bs":"없음","img":[],"ch":["甲의 국외주택에 대한 양도차익은 양도가액에서 취득가액과 필요경비개산공제를 차감하여 계산한다.","甲의 국외주택 양도로 발생하는 소득이 환율변동으로 인하여 외화차입금으로부터 발생하는 환차익을 포함하고 있는 경우에는 해당 환차익을 양도소득의 범위에서 제외한다.","甲의 국외주택 양도에 대해서는 해당 과세기간의 양도소득금액에서 연 250만원을 공제한다.","甲은 국외주택을 3년 이상 보유하였음에도 불구하고 장기보유특별공제액은 공제하지 아니한다.","甲은 국외주택의 양도에 대하여 양도소득세의 납세의무가 있다."],"a":[1],"L":"세3-2","o":"기출","x":{"한줄":"국외자산의 필요경비는 실지거래가액인 취득가액에 자본적지출액과 양도비를 더한 금액이고, 필요경비개산공제는 없다.","근거":[{"법령":"소득세법","조문":"제118조의4제1항","원문":"국외자산의 양도에 대한 양도차익을 계산할 때 양도가액에서 공제하는 필요경비는 다음 각 호의 금액을 합한 것으로 한다.\n1. 취득가액\n해당 자산의 취득에 든 실지거래가액. 다만, 취득 당시의 실지거래가액을 확인할 수 없는 경우에는 양도자산이 소재하는 국가의 취득 당시의 현황을 반영한 시가에 따르되, 시가를 산정하기 어려울 때에는 그 자산의 종류, 규모, 거래상황 등을 고려하여 대통령령으로 정하는 방법에 따라 취득가액을 산정한다.\n2. 대통령령으로 정하는 자본적지출액\n3. 대통령령으로 정하는 양도비"},{"법령":"소득세법","조문":"제118조의2 단서","원문":"다만, 다음 각 호에 따른 소득이 국외에서 외화를 차입하여 취득한 자산을 양도하여 발생하는 소득으로서 환율변동으로 인하여 외화차입금으로부터 발생하는 환차익을 포함하고 있는 경우에는 해당 환차익을 양도소득의 범위에서 제외한다."},{"법령":"소득세법","조문":"제118조의7제1항","원문":"국외자산의 양도에 대한 양도소득이 있는 거주자에 대해서는 해당 과세기간의 양도소득금액에서 연 250만원을 공제한다."},{"법령":"소득세법","조문":"제118조의8 단서","원문":"다만, 제95조에 따른 장기보유 특별공제액은 공제하지 아니한다."},{"법령":"소득세법","조문":"제118조의2 본문","원문":"거주자(해당 자산의 양도일까지 계속 5년 이상 국내에 주소 또는 거소를 둔 자만 해당한다)의 국외에 있는 자산의 양도에 대한 양도소득은 해당 과세기간에 국외에 있는 자산을 양도함으로써 발생하는 다음 각 호의 소득으로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국외자산의 필요경비는 취득가액(실지거래가액), 자본적지출액, 양도비를 합한 것이다. 필요경비개산공제는 국내 환산취득가액에서 쓰는 개념이다(소득세법 제118조의4 제1항)."},{"번호":2,"판정":"옳음","설명":"외화차입금에서 생기는 환차익은 양도소득의 범위에서 제외한다(소득세법 제118조의2 단서)."},{"번호":3,"판정":"옳음","설명":"국외자산 양도소득이 있는 거주자는 양도소득금액에서 연 250만원을 공제받는다(소득세법 제118조의7 제1항)."},{"번호":4,"판정":"옳음","설명":"국외자산에는 제95조를 준용하되 장기보유특별공제액은 공제하지 않는다(소득세법 제118조의8 단서)."},{"번호":5,"판정":"옳음","설명":"양도일까지 계속 5년 이상 국내에 주소 또는 거소를 둔 거주자가 국외주택을 양도하면 양도소득세 납세의무가 있다(소득세법 제118조의2)."}],"개념":[{"종류":"흐름","제목":"국외자산 양도소득세 계산 순서","단계":[{"이름":"납세의무 판단","설명":"양도일까지 계속 5년 이상 국내에 주소 또는 거소를 둔 거주자만 해당(제118조의2)."},{"이름":"양도가액","설명":"양도 당시의 실지거래가액. 확인할 수 없으면 소재국의 양도 당시 현황을 반영한 시가(제118조의3)."},{"이름":"필요경비","설명":"실지거래가액인 취득가액 + 대통령령이 정하는 자본적지출액 + 양도비(제118조의4). 개산공제는 없다."},{"이름":"양도차익","설명":"양도가액 − 필요경비. 외화차입금 환율변동에서 생긴 환차익은 양도소득에서 제외(제118조의2 단서)."},{"이름":"양도소득금액","설명":"국외자산은 장기보유특별공제를 하지 않으므로 양도차익이 곧 양도소득금액(제118조의8 단서)."},{"이름":"과세표준","설명":"양도소득금액 − 연 250만원 기본공제(제118조의7)."},{"이름":"세액","설명":"제55조제1항 세율을 적용하고(제118조의5), 외국납부세액은 세액공제방법 또는 필요경비 산입방법 중 선택(제118조의6)."}]},{"종류":"비교","제목":"국내자산과 국외자산 양도소득세","왼쪽":{"이름":"국내자산","항목":["필요경비: 실지거래가액 또는 환산취득가액 + 개산공제","장기보유특별공제: 3년 이상 보유한 토지·건물 등에 적용(미등기양도 제외)","기본공제: 소득 그룹별 연 250만원, 미등기양도 제외","세율: 제104조(보유기간·자산 종류별)"]},"오른쪽":{"이름":"국외자산","항목":["필요경비: 실지거래가액 취득가액 + 자본적지출액 + 양도비","장기보유특별공제: 적용하지 않음","기본공제: 연 250만원","세율: 제55조제1항 기본세율"]}}],"함정":"필요경비개산공제는 국내 부동산을 환산취득가액으로 계산할 때 쓰는 개념이다. 국외자산은 실지거래가액이 원칙이고 확인할 수 없을 때 소재국 시가를 쓴다. 3년 이상 보유해도 장기보유특별공제는 없다."}},{"i":"S5-2-2-세법-16","r":"S5","g":3,"c":2,"n":40,"s":"세법","q":"소득세법상 부동산임대업에서 발생한 소득에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["해당 과세기간의 주거용 건물 임대업을 제외한 부동산임대업에서 발생한 결손금은 그 과세기간의 종합소득과세표준을 계산할 때 공제하지 않는다.","사업소득에 부동산임대업에서 발생한 소득이 포함되어 있는 사업자는 그 소득별로 구분하여 회계처리하여야 한다.","3주택(주택 수에 포함되지 않는 주택 제외) 이상을 소유한 거주자가 주택과 주택부수토지를 임대(주택부수토지만 임대하는 경우 제외)한 경우에는 법령으로 정하는 바에따라 계산한 금액(간주임대료)을 총수입금액에 산입한다.","간주임대료 계산 시 3주택 이상 여부 판정에 있어 주택수에 포함되지 않는 주택이란 주거의 용도로만 쓰이는 면적이 1호 또는 1세대당 40 m² 이하인 주택으로서 해당 과세기간의 기준시가가 2억원 이하인 주택을 말한다.","해당 과세기간에 분리과세 주택임대소득이 있는 거주자(종합소득과세표준이 없거나 결손금이 있는 거주자 포함)는 그 종합소득 과세표준을 그 과세기간의 다음 연도 5월 1일부터 5월 31일까지 신고하여야 한다."],"a":[3],"L":"세3-3","o":"기출","x":{"한줄":"3주택 이상을 소유해도 주택 보증금등의 합계액이 3억원을 초과하는 경우에 한해 간주임대료를 총수입금액에 산입한다.","근거":[{"법령":"소득세법","조문":"제25조제1항제1호","원문":"3주택 이상을 소유하고 해당 주택의 보증금등의 합계액이 3억원을 초과하는 경우"},{"법령":"소득세법","조문":"제25조제1항 단서","원문":"주택[주거의 용도로만 쓰이는 면적이 1호(戶) 또는 1세대당 40제곱미터 이하인 주택으로서 해당 과세기간의 기준시가가 2억원 이하인 주택은 2026년 12월 31일까지는 주택 수에 포함하지 아니한다]을 대여하고 보증금등을 받은 경우에는 다음 각 호의 어느 하나에 해당하는 경우를 말하며,"},{"법령":"소득세법","조문":"제45조제2항","원문":"제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 사업(이하 \"부동산임대업\"이라 한다)에서 발생한 결손금은 종합소득 과세표준을 계산할 때 공제하지 아니한다. 다만, 주거용 건물 임대업의 경우에는 그러하지 아니하다."},{"법령":"소득세법","조문":"제160조제4항","원문":"제1항이나 제2항의 경우에 사업소득에 부동산임대업에서 발생한 소득이 포함되어 있는 사업자는 그 소득별로 구분하여 회계처리하여야 한다."},{"법령":"소득세법","조문":"제70조제1항·제2항","원문":"해당 과세기간의 종합소득금액이 있는 거주자(종합소득과세표준이 없거나 결손금이 있는 거주자를 포함한다)는 그 종합소득 과세표준을 그 과세기간의 다음 연도 5월 1일부터 5월 31일까지 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 한다.\n② 해당 과세기간에 분리과세 주택임대소득 및 제127조제1항제6호나목의 소득이 있는 경우에도 제1항을 적용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"주거용 건물 임대업을 제외한 부동산임대업의 결손금은 종합소득 과세표준 계산 때 공제하지 않는다(소득세법 제45조 제2항)."},{"번호":2,"판정":"옳음","설명":"사업소득에 부동산임대업 소득이 포함되면 소득별로 구분해 회계처리한다(소득세법 제160조 제4항)."},{"번호":3,"판정":"틀림","설명":"3주택 이상 소유만으로는 부족하고 보증금등의 합계액이 3억원을 초과해야 한다(소득세법 제25조 제1항 제1호)."},{"번호":4,"판정":"옳음","설명":"주거전용 40㎡ 이하이면서 기준시가 2억원 이하인 주택은 주택 수에서 뺀다. 이 특례는 2026년 12월 31일까지다(소득세법 제25조 제1항 단서)."},{"번호":5,"판정":"옳음","설명":"분리과세 주택임대소득만 있거나 과세표준이 없어도 다음 연도 5월 1일~31일에 확정신고한다(소득세법 제70조 제1항·제2항)."}],"개념":[{"종류":"표","제목":"주택 수별 주택임대소득 과세","머리":["소유 주택 수","월세(사업소득)","보증금등 간주임대료"],"행":[["1주택(국내, 기준시가 12억원 이하)","비과세","대상 아님"],["1주택(기준시가 12억원 초과 또는 국외 주택)","과세","대상 아님(제25조 제1항은 3주택 이상 또는 2주택일 때만 규정)"],["2주택","과세","기준시가 12억원 이하 주택은 주택 수에서 빼고 센 2주택이어야 하고, 보증금등 합계액이 시행령 제53조 제1항의 12억원을 초과해야 함"],["3주택 이상","과세","보증금등 합계액이 3억원을 초과해야 함, 주택부수토지만 임대하면 제외"],["주택 수에서 제외하는 주택","40㎡ 이하이면서 기준시가 2억원 이하(2026년 12월 31일까지)","보증금등 판정 때 주택 수에서 제외"]]},{"종류":"계산","제목":"상가 보증금 간주임대료 계산 예(이자율 연 3%, 수치는 가정)","단계":[{"설명":"주택 외 임대의 총수입금액 산입액 = (보증금등의 적수 − 건설비 상당액의 적수) × 1/365 × 정기예금이자율 − 수입이자·할인료·배당금. 연간 기준으로 보증금 5억원, 건물 건설비 상당액 2억원으로 가정","식":"(5억원 − 2억원) × 3%","값":"900만원"},{"설명":"해당 임대사업부분에서 발생한 수입이자와 할인료 및 배당금 100만원을 뺀다. 유가증권처분이익은 빼지 않는다","식":"900만원 − 100만원","값":"800만원"},{"설명":"총수입금액 = 월세 연 합계 + 간주임대료. 월세 연 합계 1,200만원으로 가정","식":"1,200만원 + 800만원","값":"2,000만원"}]}],"함정":"간주임대료는 3주택 이상이면서 보증금등 합계액이 3억원을 초과해야 한다(③). 40㎡·2억원 소형주택의 주택 수 제외는 2026년 12월 31일까지만 적용된다(④). 분리과세 주택임대소득만 있어도 5월에 확정신고한다(⑤).","개정":"2주택 소유자도 기준시가 12억원 이하 주택을 빼고 센 2주택이고 보증금등이 12억원을 초과하면 간주임대료 대상이다(소득세법 제25조 제1항 제2호, 시행령 제53조 제1항 <신설 2025.2.28> 표시). 기출 선지는 3주택 이상만 다뤘다."}}];